['Below is an example implementation of a C function that initializes and manages a distributed system for handling `UEContext` structures in a multi-threaded environment:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define MAX_UE_ID 1000

typedef struct {
    int RLC_PDU_size;
    void* RLC_PDU_data;
} RLC_PDU;

typedef struct {
    int DRB_ID;
    // Other DRBConfig details
} DRBConfig;

typedef struct {
    int UE_ID;
    RLC_PDU* rlc_pdu_list;
    size_t pdu_count;
    DRBConfig drb_config[MAX_UE_ID];  // Example fixed-size array for simplicity
    pthread_mutex_t lock;             // Mutex for thread safety
} UEContext;

typedef struct Node {
    UEContext ue_context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t rwlock;
} ContextList;

// Initialize the context list
void init_context_list(ContextList* list) {
    list->head = NULL;
    pthread_rwlock_init(&list->rwlock, NULL);
}

// Add or update a UEContext entry
void add_or_update_uecontext(ContextList* list, UEContext ue_context) {
    pthread_rwlock_wrlock(&list->rwlock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->ue_context.UE_ID == ue_context.UE_ID) {
            // Update existing entry
            pthread_mutex_lock(&(*current)->ue_context.lock);
            memcpy(&(*current)->ue_context, &ue_context, sizeof(UEContext));
            pthread_mutex_unlock(&(*current)->ue_context.lock);
            break;
        }
        current = &((*current)->next);
    }

    if (!*current) {
        // Add new entry
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->ue_context = ue_context;
        new_node->next = NULL;
        *current = new_node;
    }

    pthread_rwlock_unlock(&list->rwlock);
}

// Retrieve a UEContext by its UE_ID
UEContext* get_uecontext(ContextList* list, int ue_id) {
    pthread_rwlock_rdlock(&list->rwlock);

    Node* current = list->head;
    while (current) {
        if (current->ue_context.UE_ID == ue_id) {
            pthread_mutex_lock(&current->ue_context.lock);
            UEContext* context_copy = (UEContext*)malloc(sizeof(UEContext));
            memcpy(context_copy, &current->ue_context, sizeof(UEContext));
            pthread_mutex_unlock(&current->ue_context.lock);
            pthread_rwlock_unlock(&list->rwlock);
            return context_copy;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rwlock);
    return NULL;
}

// Cleanup the context list
void free_context_list(ContextList* list) {
    pthread_rwlock_wrlock(&list->rwlock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        pthread_mutex_destroy(&temp->ue_context.lock);
        free(temp->ue_context.rlc_pdu_list); // Assuming RLC_PDU data was dynamically allocated
        free(temp);
    }

    list->head = NULL;
    pthread_rwlock_unlock(&list->rwlock);
    pthread_rwlock_destroy(&list->rwlock);
}
```

### Key Points:
- **Thread Safety:** The use of `pthread_rwlock_t` for read-write locks and `pthread_mutex_t` for individual `UEContext` locking ensures thread safety.
- **Memory Management:** Dynamic allocation is used for linked list nodes, and proper cleanup functions are provided to avoid memory leaks.
- **Scalability Considerations:** A linked list structure allows dynamic growth as new entries are added or updated. The use of read-write locks optimizes concurrent access patterns.
- **Data Consistency:** Locking mechanisms ensure that updates do not cause race conditions or data corruption.

This implementation provides a scalable, multi-threaded approach to managing `UEContext` structures with considerations for concurrency and resource management.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_SIZE 10
#define MAX_RANGE 100

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    size_t offset_count;
    size_t key_count;
    record *records;
    size_t record_capacity;
    pthread_mutex_t mutex;
    int logging_enabled;
} memory_pool;

void log_message(memory_pool *pool, const char *message) {
    if (pool->logging_enabled) {
        printf("Log: %s\n", message);
    }
}

memory_pool* create_memory_pool(int logging_enabled) {
    memory_pool *pool = malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->offset_count = INITIAL_SIZE;
    pool->key_count = INITIAL_SIZE;
    pool->record_capacity = INITIAL_SIZE;

    pool->offsets = malloc(pool->offset_count * sizeof(long));
    pool->keys = malloc(pool->key_count * sizeof(int));
    pool->records = malloc(pool->record_capacity * sizeof(record));

    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pool->logging_enabled = logging_enabled;

    log_message(pool, "Memory pool created.");
    return pool;
}

void resize_records(memory_pool *pool) {
    size_t new_capacity = pool->record_capacity * 2;
    record *new_records = realloc(pool->records, new_capacity * sizeof(record));
    if (!new_records) {
        log_message(pool, "Failed to resize records array.");
        return;
    }

    pool->records = new_records;
    pool->record_capacity = new_capacity;

    for (size_t i = pool->record_capacity / 2; i < pool->record_capacity; ++i) {
        pool->records[i].value = rand() % MAX_RANGE;
    }

    log_message(pool, "Records array resized.");
}

void initialize_records(memory_pool *pool) {
    pthread_mutex_lock(&pool->mutex);

    for (size_t i = 0; i < pool->record_capacity; ++i) {
        pool->records[i].value = rand() % MAX_RANGE;
    }

    pthread_mutex_unlock(&pool->mutex);
}

void add_record(memory_pool *pool, int value) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->record_capacity == 0) {
        resize_records(pool);
    }
    if (pool->record_capacity == pool->offset_count) {
        resize_records(pool);
    }

    pool->records[pool->record_capacity].value = value;
    ++(pool->record_capacity);

    pthread_mutex_unlock(&pool->mutex);
}

void free_memory_pool(memory_pool *pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
    log_message(pool, "Memory pool freed.");
}

// Test function
void test_memory_pool() {
    srand(time(NULL));

    memory_pool *pool = create_memory_pool(1);

    if (!pool) {
        printf("Failed to create memory pool.\n");
        return;
    }

    initialize_records(pool);
    add_record(pool, 42);

    for (size_t i = 0; i < pool->record_capacity; ++i) {
        printf("Record %zu: %d\n", i, pool->records[i].value);
    }

    free_memory_pool(pool);
}

int main() {
    test_memory_pool();
    return 0;
}
