#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_LINE_LENGTH 1024

// Error codes
enum {
    SUCCESS = 0,
    MEMORY_ERROR,
    FILE_ERROR,
    DNS_ERROR,
    INVALID_DATA
};

// Function to perform DNS resolution
int resolve_dns(const char *hostname, u_char *ip_buffer) {
    struct addrinfo hints, *res;
    int err;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4

    if ((err = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return DNS_ERROR;
    }

    struct sockaddr_in *ip_addr = (struct sockaddr_in *)res->ai_addr;
    void *addr_ptr = &(ip_addr->sin_addr);

    inet_ntop(AF_INET, addr_ptr, ip_buffer, INET_ADDRSTRLEN);
    freeaddrinfo(res);
    return SUCCESS;
}

// Function to calculate the average of two numbers
double calculate_average(double num1, double num2) {
    return (num1 + num2) / 2.0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return FILE_ERROR;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return FILE_ERROR;
    }

    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) {
        // Skip empty lines
        if (strlen(line) < 2) continue;

        char *token = strtok(line, ",");
        char **fields = malloc((strlen(line) / 2 + 10) * sizeof(char *));
        int field_count = 0;

        while (token != NULL) {
            fields[field_count++] = token;
            token = strtok(NULL, ",");
        }

        // Ensure there are at least two numeric fields for average calculation
        if (field_count < 3 || !isdigit(fields[field_count - 1][0]) || !isdigit(fields[field_count - 2][0])) {
            fprintf(stderr, "Invalid data: %s\n", line);
            free(fields);
            continue;
        }

        double num1 = atof(fields[field_count - 1]);
        double num2 = atof(fields[field_count - 2]);
        double average = calculate_average(num1, num2);

        // Print fields with average
        for (int i = 0; i < field_count - 2; i++) {
            printf("%s", fields[i]);
            if (i != field_count - 3) printf(",");
        }
        printf("%.2f\n", average);

        // DNS resolution
        u_char ip_buffer[INET_ADDRSTRLEN];
        if (resolve_dns(fields[0], ip_buffer) == SUCCESS) {
            printf("Resolved IP: %s\n", ip_buffer);
        } else {
            fprintf(stderr, "DNS resolution failed for hostname: %s\n", fields[0]);
        }

        free(fields);
    }

    free(line);
    fclose(file);

    return SUCCESS;
}
