#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_INTS 1000000

void read_and_find_largest() {
    int *numbers = NULL;
    size_t count = 0;
    int input, largest = INT_MIN;
    clock_t start_time, end_time;

    // Start timing
    start_time = clock();

    while (1) {
        if (scanf("%d", &input) != 1) break; // Break on invalid input or EOF

        numbers = realloc(numbers, (count + 1) * sizeof(int));
        if (!numbers) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        }

        numbers[count++] = input;

        // Check for largest integer
        if (input > largest) {
            largest = input;
        }

        // Time check every second
        end_time = clock();
        double elapsed = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
        if (elapsed >= 1.0 || count >= MAX_INTS) {
            break;
        }
    }

    if (count > MAX_INTS) {
        printf("Error: More than %zu integers were input.\n", MAX_INTS);
    } else if (elapsed >= 1.0 && count < MAX_INTS) {
        printf("Warning: Processing time exceeded 1 second.\n");
    }

    // Print the largest integer
    if (count > 0) {
        printf("Largest integer: %d\n", largest);
    }

    free(numbers); // Free allocated memory
}

int main() {
    read_and_find_largest();
    return 0;
}
