#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

// Example network packet header structure
typedef struct {
    int version;
    int length;
    char *sourceAddress;  // Assume dynamic allocation for variable size
    char *destinationAddress;
} NetworkPacketHeader;

// Configuration structure defining mandatory fields
typedef struct {
    int version;
    int length;
    const char *sourceAddress;
    const char *destinationAddress;
} PacketConfig;

// Error logging function prototype
void log_error(const char* format, ...);

// Thread-safe memory allocation wrapper
static void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        log_error("Memory allocation failed for %zu bytes", size);
    }
    return ptr;
}

// Function to initialize a network packet header based on configuration
NetworkPacketHeader* create_network_packet_header(PacketConfig config) {
    NetworkPacketHeader* header = safe_malloc(sizeof(NetworkPacketHeader));
    if (header == NULL) {
        return NULL;  // Handle allocation failure gracefully
    }

    #pragma omp critical  // Ensure thread safety for initialization
    {
        header->version = config.version;
        header->length = config.length;

        size_t sourceLen = strlen(config.sourceAddress) + 1;
        header->sourceAddress = safe_malloc(sourceLen);
        if (header->sourceAddress == NULL) {
            free(header);
            return NULL;
        }
        strncpy(header->sourceAddress, config.sourceAddress, sourceLen);

        size_t destLen = strlen(config.destinationAddress) + 1;
        header->destinationAddress = safe_malloc(destLen);
        if (header->destinationAddress == NULL) {
            free(header->sourceAddress);
            free(header);
            return NULL;
        }
        strncpy(header->destinationAddress, config.destinationAddress, destLen);
    }

    return header;
}

// Error logging function using va_start and va_end
void log_error(const char* format, ...) {
    char buffer[256];

    va_list args;
    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    fprintf(stderr, "ERROR: %s\n", buffer);
}

// Example usage
int main() {
    PacketConfig config = {1, 128, "192.168.0.1", "10.0.0.2"};
    NetworkPacketHeader* header = create_network_packet_header(config);

    if (header != NULL) {
        printf("Network packet header created:\n");
        printf("Version: %d\n", header->version);
        printf("Length: %d\n", header->length);
        printf("Source Address: %s\n", header->sourceAddress);
        printf("Destination Address: %s\n", header->destinationAddress);

        // Free allocated resources
        free(header->sourceAddress);
        free(header->destinationAddress);
        free(header);
    }

    return 0;
}
