int encrypt_data(const unsigned char *plaintext, int plaintext_len, unsigned char **ciphertext, int *ciphertext_len, EncryptionConfig *config) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context.\n");
        return -1;
    }

    int len;
    int ciphertext_size = plaintext_len + EVP_MAX_BLOCK_LENGTH;
    *ciphertext = malloc(ciphertext_size);
    if (!*ciphertext) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Memory allocation failed for ciphertext.\n");
        return -1;
    }

    if (config->cipher_mode == MODE_AES_128_CBC || config->cipher_mode == MODE_AES_256_ECB) {
        int key_len = 16; // AES-128
        if (config->cipher_mode == MODE_AES_256_ECB) {
            key_len = 32; // AES-256
        }

        EVP_CIPHER_CTX_init(ctx);
        if (config->cipher_mode == MODE_AES_128_CBC) {
            EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, config->key, config->iv);
        } else if (config->cipher_mode == MODE_AES_256_ECB) {
            EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, config->key, NULL);
        }

        EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len);
        int ciphertext_block_len = len;
        EVP_EncryptFinal_ex(ctx, *ciphertext + len, &len);
        ciphertext_block_len += len;

        *ciphertext_len = ciphertext_block_len;
    } else if (config->cipher_mode == MODE_CHACHA20) {
        // Implement ChaCha20 encryption here
        fprintf(stderr, "ChaCha20 is not implemented yet.\n");
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int decrypt_data(const unsigned char *ciphertext, int ciphertext_len, unsigned char **plaintext, int *plaintext_len, EncryptionConfig *config) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context.\n");
        return -1;
    }

    int len;
    *plaintext = malloc(ciphertext_len);
    if (!*plaintext) {
        EVP_CIPHER_CTX_free(ctx);
        fprintf(stderr, "Memory allocation failed for plaintext.\n");
        return -1;
    }

    if (config->cipher_mode == MODE_AES_128_CBC || config->cipher_mode == MODE_AES_256_ECB) {
        int key_len = 16; // AES-128
        if (config->cipher_mode == MODE_AES_256_ECB) {
            key_len = 32; // AES-256
        }

        EVP_CIPHER_CTX_init(ctx);
        if (config->cipher_mode == MODE_AES_128_CBC) {
            EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, config->key, config->iv);
        } else if (config->cipher_mode == MODE_AES_256_ECB) {
            EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, config->key, NULL);
        }

        EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len);
        int plaintext_block_len = len;
        EVP_DecryptFinal_ex(ctx, *plaintext + len, &len);
        plaintext_block_len += len;

        *plaintext_len = plaintext_block_len;
    } else if (config->cipher_mode == MODE_CHACHA20) {
        // Implement ChaCha20 decryption here
        fprintf(stderr, "ChaCha20 is not implemented yet.\n");
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
