['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <pthread.h>

#define MAX_ALGORITHMS 100

typedef struct {
    char name[50];
} Algorithm;

typedef struct {
    Algorithm *algorithms;
    size_t count;
} AlgorithmList;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Global variable to store disabled algorithms
char *disabled_algorithms[MAX_ALGORITHMS] = {0};
size_t disabled_count = 0;

void load_disabled_algorithms(const char *config_file) {
    FILE *file = fopen(config_file, "r");
    if (!file) return;

    while (fscanf(file, "%49s", disabled_algorithms[disabled_count]) == 1) {
        disabled_count++;
        if (disabled_count >= MAX_ALGORITHMS) break;
    }

    fclose(file);
}

int is_algorithm_disabled(const char *name) {
    for (size_t i = 0; i < disabled_count; i++) {
        if (strcmp(disabled_algorithms[i], name) == 0) return 1;
    }
    return 0;
}

AlgorithmList get_available_algorithms(const char *lib_path) {
    AlgorithmList list = {NULL, 0};
    void *handle = dlopen(lib_path, RTLD_NOW);
    if (!handle) {
        fprintf(stderr, "Error loading library: %s\n", dlerror());
        return list;
    }

    pthread_mutex_lock(&lock);

    // Assume the library provides a function to get available algorithms
    int (*get_algo_count)(void);
    void (*get_algo_name)(int index, char *name, size_t len);

    *(void **)(&get_algo_count) = dlsym(handle, "get_algo_count");
    *(void **)(&get_algo_name) = dlsym(handle, "get_algo_name");

    if (!get_algo_count || !get_algo_name) {
        fprintf(stderr, "Error finding symbols: %s\n", dlerror());
        pthread_mutex_unlock(&lock);
        dlclose(handle);
        return list;
    }

    int algo_count = get_algo_count();
    list.algorithms = malloc(sizeof(Algorithm) * algo_count);

    for (int i = 0; i < algo_count; i++) {
        char name[50];
        get_algo_name(i, name, sizeof(name));

        if (!is_algorithm_disabled(name)) {
            strcpy(list.algorithms[list.count].name, name);
            list.count++;
        }
    }

    pthread_mutex_unlock(&lock);

    dlclose(handle);
    return list;
}

void free_algorithm_list(AlgorithmList *list) {
    free(list->algorithms);
    list->count = 0;
}

int main() {
    load_disabled_algorithms("config.txt");

    AlgorithmList hash_functions = get_available_algorithms("./hash_lib.so");
    AlgorithmList block_ciphers = get_available_algorithms("./cipher_lib.so");

    for (size_t i = 0; i < hash_functions.count; i++) {
        printf("Hash: %s\n", hash_functions.algorithms[i].name);
    }

    for (size_t i = 0; i < block_ciphers.count; i++) {
        printf("Cipher: %s\n", block_ciphers.algorithms[i].name);
    }

    free_algorithm_list(&hash_functions);
    free_algorithm_list(&block_ciphers);

    return 0;
}
```

