typedef enum {
    ENCRYPT,
    DECRYPT,
    VERIFY_SIGNATURE
} OperationType;

typedef struct {
    const char *file_path;
    OperationType operation;
    FILE *log_file;
    pthread_mutex_t log_mutex;
} TaskData;

// Forward declarations
void* perform_operation(void* arg);
int handle_file(const char* file_path, int (*operation_func)(FILE*, EVP_PKEY*, EVP_MD*), const char* log_message);
EVP_PKEY* load_key(const char *key_path); // Placeholder for loading a key

// Log function with thread safety
void log_operation(FILE* log_file, pthread_mutex_t *mutex, const char* message) {
    pthread_mutex_lock(mutex);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(mutex);
}

int file_access_permission(const char *file_path) {
    return access(file_path, R_OK | W_OK); // Check read/write permissions
}

void cleanup_openssl() {
    ERR_free_strings();
    EVP_cleanup();
}

// Function to be called for each task
void* perform_operation(void* arg) {
    TaskData *data = (TaskData*)arg;

    if (file_access_permission(data->file_path) != 0) {
        log_operation(data->log_file, &data->log_mutex, "Permission denied");
        return NULL;
    }

