        case ENCRYPT:
            handle_file(data->file_path, encrypt_function, "Encryption operation performed");
            break;
        case DECRYPT:
            handle_file(data->file_path, decrypt_function, "Decryption operation performed");
            break;
        case VERIFY_SIGNATURE:
            handle_file(data->file_path, verify_signature_function, "Signature verification performed");
            break;
    }

    EVP_PKEY_free(key);
    EVP_MD_free(md);
    return NULL;
}

// Main function to setup the task and start threads
int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <file_path> <operation>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *file_path = argv[1];
    OperationType operation = ENCRYPT; // Default to encrypt

    if (strcmp(argv[2], "encrypt") == 0) {
        operation = ENCRYPT;
    } else if (strcmp(argv[2], "decrypt") == 0) {
        operation = DECRYPT;
    } else if (strcmp(argv[2], "verify_signature") == 0) {
        operation = VERIFY_SIGNATURE;
    }

    FILE *log_file = fopen("operation_logs.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

    TaskData task_data = {file_path, operation, log_file, log_mutex};

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, perform_operation, (void*)&task_data);

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    fclose(log_file);
    cleanup_openssl();

    return 0;
}

