['Below is a modular C library for thread-safe semaphore management with dynamic initialization, manipulation, deletion, and integration support. It includes error handling for overflows and underflow conditions.

```c
// semaphore.h
#ifndef SEMAPHORE_H
#define SEMAPHORE_H

#include <pthread.h>

typedef struct Semaphore {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} Semaphore;

typedef struct SemaphoresManager {
    Semaphore *semaphores;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock;
} SemaphoresManager;

SemaphoresManager* semaphores_manager_init(size_t capacity);
void semaphores_manager_destroy(SemaphoresManager* manager);
int semaphore_create(SemaphoresManager* manager, int initial_value);
void semaphore_delete(SemaphoresManager* manager, size_t index);
void semaphore_wait(Semaphore* semaphore);
void semaphore_signal(Semaphore* semaphore);

#endif // SEMAPHORE_H

// semaphore.c
#include "semaphore.h"
#include <stdlib.h>
#include <assert.h>

#define MAX_SEMAPHORES 1000

SemaphoresManager* semaphores_manager_init(size_t capacity) {
    assert(capacity <= MAX_SEMAPHORES);

    SemaphoresManager *manager = malloc(sizeof(SemaphoresManager));
    manager->semaphores = calloc(capacity, sizeof(Semaphore));
    manager->count = 0;
    manager->capacity = capacity;

    pthread_rwlock_init(&manager->rwlock, NULL);

    for (size_t i = 0; i < capacity; ++i) {
        pthread_mutex_init(&manager->semaphores[i].mutex, NULL);
        pthread_cond_init(&manager->semaphores[i].cond_var, NULL);
    }

    return manager;
}

void semaphores_manager_destroy(SemaphoresManager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->capacity; ++i) {
            pthread_mutex_destroy(&manager->semaphores[i].mutex);
            pthread_cond_destroy(&manager->semaphores[i].cond_var);
        }
        free(manager->semaphores);
        pthread_rwlock_destroy(&manager->rwlock);
        free(manager);
    }
}

int semaphore_create(SemaphoresManager* manager, int initial_value) {
    if (initial_value < -1000 || initial_value > 1000) return -1;

    pthread_rwlock_wrlock(&manager->rwlock);
    if (manager->count >= manager->capacity) {
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    Semaphore *semaphore = &manager->semaphores[manager->count++];
    semaphore->value = initial_value;

    pthread_rwlock_unlock(&manager->rwlock);
    return 0;
}

void semaphore_delete(SemaphoresManager* manager, size_t index) {
    assert(index < manager->count);

    pthread_rwlock_wrlock(&manager->rwlock);
    if (index >= manager->count) {
        pthread_rwlock_unlock(&manager->rwlock);
        return;
    }

    Semaphore *semaphore = &manager->semaphores[index];
    pthread_mutex_destroy(&semaphore->mutex);
    pthread_cond_destroy(&semaphore->cond_var);

    --manager->count;

    // Shift semaphores
    for (size_t i = index; i < manager->count; ++i) {
        manager->semaphores[i] = manager->semaphores[i + 1];
    }

    pthread_rwlock_unlock(&manager->rwlock);
}

void semaphore_wait(Semaphore* semaphore) {
    pthread_mutex_lock(&semaphore->mutex);

    while (semaphore->value <= 0) {
        pthread_cond_wait(&semaphore->cond_var, &semaphore->mutex);
    }
    if (--semaphore->value < -1000 || ++semaphore->value > 1000) {
        semaphore->value += 1; // Correct overflow/underflow
    }

    pthread_mutex_unlock(&semaphore->mutex);
}

void semaphore_signal(Semaphore* semaphore) {
    pthread_mutex_lock(&semaphore->mutex);

    if (++semaphore->value < -1000 || ++semaphore->value > 1000) {
        semaphore->value -= 1; // Correct overflow/underflow
    }

    pthread_cond_signal(&semaphore->cond_var);
    pthread_mutex_unlock(&semaphore->mutex);
}

// Unit tests (test_semaphore.c)
#include "semaphore.h"
#include <stdio.h>
#include <pthread.h>

#define THREAD_COUNT 100

void* test_thread_func(void* arg) {
    int index = *(int*)arg;
    Semaphore *semaphore = &semaphores[index];

    semaphore_wait(semaphore);
    printf("Thread %d acquired semaphore\n", index);
    pthread_exit(NULL);
}

void run_tests() {
    SemaphoresManager *manager = semaphores_manager_init(1000);

    for (int i = 0; i < THREAD_COUNT; ++i) {
        if (semaphore_create(manager, 1) != 0) {
            printf("Semaphore creation failed\n");
            return;
        }
    }

    pthread_t threads[THREAD_COUNT];
    int indices[THREAD_COUNT];

    for (int i = 0; i < THREAD_COUNT; ++i) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, test_thread_func, &indices[i]) != 0) {
            printf("Thread creation failed\n");
            return;
        }
    }

    for (int i = 0; i < THREAD_COUNT; ++i) {
        pthread_join(threads[i], NULL);
    }

    semaphores_manager_destroy(manager);
}

int main() {
    run_tests();
    return 0;
}
```

This code provides a basic library structure, with semaphore management functions and simple unit tests. It handles up to 1000 semaphores efficiently using read-write locks to minimize contention. The test suite demonstrates concurrent access and manipulation of semaphores. Further testing should be added for edge cases and stress conditions.']

