using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Text.Json;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace GameEngineConfigurator
{
    public class ConfigurationSettings
    {
        public int WorldWidth { get; set; }
        public int WorldHeight { get; set; }
        public CameraSettings Camera { get; set; } = new CameraSettings();
        public PhysicsSimulationParameters Physics { get; set; } = new PhysicsSimulationParameters();
    }

    public class CameraSettings
    {
        public float FieldOfView { get; set; }
        public Vector3 Position { get; set; }
    }

    public class PhysicsSimulationParameters
    {
        public float Gravity { get; set; }
        public float Friction { get; set; }
    }

    public class Vector3
    {
        public float X { get; set; }
        public float Y { get; set; }
        public float Z { get; set; }
    }

    public class GameEngineConfigManager
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<GameEngineConfigManager> _logger;
        private ConcurrentDictionary<string, object> _configCache = new();

        public ConfigurationSettings Settings { get; private set; } = new();

        public GameEngineConfigManager(IConfiguration configuration, ILogger<GameEngineConfigManager> logger)
        {
            _configuration = configuration ?? throw new ArgumentNullException(nameof(configuration));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));

            LoadInitialConfiguration();
            SubscribeToDynamicUpdates();
        }

        private void LoadInitialConfiguration()
        {
            try
            {
                var jsonSettings = LoadFromJsonFile("config.json");
                var envSettings = GetEnvironmentVariables();
                var apiSettings = FetchApiSettings();

                Settings = MergeSettings(jsonSettings, envSettings, apiSettings);

                CacheConfig(Settings);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to load initial configuration.");
                throw;
            }
        }

        private ConfigurationSettings LoadFromJsonFile(string path)
        {
            var jsonContent = File.ReadAllText(path);
            return JsonSerializer.Deserialize<ConfigurationSettings>(jsonContent) ?? new ConfigurationSettings();
        }

        private ConfigurationSettings GetEnvironmentVariables()
        {
            // Assuming environment variables follow a specific naming convention
            var settings = new ConfigurationSettings
            {
                WorldWidth = int.TryParse(Environment.GetEnvironmentVariable("GAME_WORLD_WIDTH"), out var width) ? width : Settings.WorldWidth,
                WorldHeight = int.TryParse(Environment.GetEnvironmentVariable("GAME_WORLD_HEIGHT"), out var height) ? height : Settings.WorldHeight,
                Camera = new CameraSettings
                {
                    FieldOfView = float.TryParse(Environment.GetEnvironmentVariable("CAMERA_FOV"), out var fov) ? fov : Settings.Camera.FieldOfView,
                    Position = new Vector3
                    {
                        X = float.TryParse(Environment.GetEnvironmentVariable("CAMERA_X"), out var x) ? x : Settings.Camera.Position.X,
                        Y = float.TryParse(Environment.GetEnvironmentVariable("CAMERA_Y"), out var y) ? y : Settings.Camera.Position.Y,
                        Z = float.TryParse(Environment.GetEnvironmentVariable("CAMERA_Z"), out var z) ? z : Settings.Camera.Position.Z
                    }
                },
                Physics = new PhysicsSimulationParameters
                {
                    Gravity = float.TryParse(Environment.GetEnvironmentVariable("PHYSICS_GRAVITY"), out var gravity) ? gravity : Settings.Physics.Gravity,
                    Friction = float.TryParse(Environment.GetEnvironmentVariable("PHYSICS_FRICTION"), out var friction) ? friction : Settings.Physics.Friction
                }
            };
            return settings;
        }

        private ConfigurationSettings FetchApiSettings()
        {
            try
            {
                using var httpClient = new HttpClient();
                var response = httpClient.GetStringAsync("https://api.example.com/game-settings").Result;
                var apiSettings = JsonSerializer.Deserialize<ConfigurationSettings>(response) ?? new ConfigurationSettings();

                return apiSettings;
            }
            catch (Exception ex)
            {
                _logger.LogWarning(ex, "Failed to fetch settings from API. Proceeding with existing configurations.");
                return new ConfigurationSettings();
            }
        }

        private ConfigurationSettings MergeSettings(ConfigurationSettings json, ConfigurationSettings env, ConfigurationSettings api)
        {
            // Prioritizing environment variables > JSON file > API
            var merged = new ConfigurationSettings
            {
                WorldWidth = env.WorldWidth != 0 ? env.WorldWidth : (api.WorldWidth != 0 ? api.WorldWidth : json.WorldWidth),
                WorldHeight = env.WorldHeight != 0 ? env.WorldHeight : (api.WorldHeight != 0 ? api.WorldHeight : json.WorldHeight),
                Camera = new CameraSettings
                {
                    FieldOfView = env.Camera.FieldOfView != 0f ? env.Camera.FieldOfView : (api.Camera.FieldOfView != 0f ? api.Camera.FieldOfView : json.Camera.FieldOfView),
                    Position = new Vector3
                    {
                        X = env.Camera.Position.X != 0f ? env.Camera.Position.X : (api.Camera.Position.X != 0f ? api.Camera.Position.X : json.Camera.Position.X),
                        Y = env.Camera.Position.Y != 0f ? env.Camera.Position.Y : (api.Camera.Position.Y != 0f ? api.Camera.Position.Y : json.Camera.Position.Y),
                        Z = env.Camera.Position.Z != 0f ? env.Camera.Position.Z : (api.Camera.Position.Z != 0f ? api.Camera.Position.Z : json.Camera.Position.Z)
                    }
                },
                Physics = new PhysicsSimulationParameters
                {
                    Gravity = env.Physics.Gravity != 0f ? env.Physics.Gravity : (api.Physics.Gravity != 0f ? api.Physics.Gravity : json.Physics.Gravity),
                    Friction = env.Physics.Friction != 0f ? env.Physics.Friction : (api.Physics.Friction != 0f ? api.Physics.Friction : json.Physics.Friction)
                }
            };

            return merged;
        }

        private void CacheConfig(ConfigurationSettings settings)
        {
            _configCache["WorldWidth"] = settings.WorldWidth;
            _configCache["WorldHeight"] = settings.WorldHeight;
            _configCache["CameraFOV"] = settings.Camera.FieldOfView;
            _configCache["CameraPosition"] = settings.Camera.Position;
            _configCache["PhysicsGravity"] = settings.Physics.Gravity;
            _configCache["PhysicsFriction"] = settings.Physics.Friction;
        }

        private void SubscribeToDynamicUpdates()
        {
            // Assuming a mechanism to subscribe to configuration changes (e.g., via message queue or similar)
            // This could be an observer pattern, event subscription, etc.
            OnConfigurationChanged((newSettings) =>
            {
                Settings = newSettings;
                CacheConfig(newSettings);
                _logger.LogInformation("Configuration updated dynamically.");
            });
        }

        private void OnConfigurationChanged(Action<ConfigurationSettings> updateCallback)
        {
            // Simulate dynamic updates
            var simulationTimer = System.Threading.Timer(_ =>
            {
                try
                {
                    var dynamicJsonSettings = LoadFromJsonFile("config.json");
                    var dynamicApiSettings = FetchApiSettings();

                    var updatedSettings = MergeSettings(dynamicJsonSettings, GetEnvironmentVariables(), dynamicApiSettings);

                    updateCallback(updatedSettings);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to dynamically update configuration.");
                }
            }, null, TimeSpan.FromSeconds(10), TimeSpan.FromSeconds(10));
        }

        public T GetCachedSetting<T>(string key)
        {
            if (_configCache.TryGetValue(key, out var value))
            {
                return (T)value;
            }

            _logger.LogWarning($"No cached setting found for {key}. Returning default value.");
            return default(T);
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            using var loggerFactory = LoggerFactory.Create(builder => builder.AddConsole());
            ILogger<GameEngineConfigManager> logger = loggerFactory.CreateLogger<GameEngineConfigManager>();

            var configurationBuilder = new ConfigurationBuilder()
                .AddJsonFile("appsettings.json", optional: true, reloadOnChange: true);

            IConfiguration configuration = configurationBuilder.Build();

            var gameEngineConfigManager = new GameEngineConfigManager(configuration, logger);

            // Simulate fetching settings
            var worldWidth = gameEngineConfigManager.GetCachedSetting<int>("WorldWidth");
            Console.WriteLine($"World Width: {worldWidth}");
        }
    }
}
