    if ($sub_action === 'delete') {
        if (!MockDatabase::findUserById($id)) {
            return json_encode(['message' => 'error', 'data' => ['error' => 'User not found.']]);
        }
        if (SessionService::checkActiveSessions($id)) {
            return json_encode(['message' => 'warning', 'data' => ['warning' => 'User has active sessions.']]);
        }
        $deleted = MockDatabase::deleteUserById($id);
        if ($deleted) {
            return json_encode(['message' => 'success', 'data' => ['message' => 'User deleted.']]);
        } else {
            return json_encode(['message' => 'error', 'data' => ['error' => 'Failed to delete user.']]);
        }
    }

    // If no valid action is found
    return json_encode(['message' => 'error', 'data' => ['error' => 'Invalid request.']]);

}
