    private bool IsRateLimited(string ipAddress)
    {
        var now = DateTime.UtcNow;
        if (_rateLimits.TryGetValue(ipAddress, out RateLimitInfo info))
        {
            if (info.LastRequestTime > now.AddMinutes(-1))
            {
                if (info.RequestCount >= 10) // Allow 10 requests per minute
                    return true;

                info.RequestCount++;
            }
            else
            {
                _rateLimits[ipAddress] = new RateLimitInfo { RequestCount = 1, LastRequestTime = now };
