// JavaScript function for AngularJS application
function refreshDialogFields(resourceId, url, fieldNamesToRefresh, config) {
    const dialog = angular.element(document.querySelector('.dialog-interface'));

    dialog.find('[data-field-name]').each(function() {
        const fieldName = $(this).attr('data-field-name');

        if (fieldNamesToRefresh.includes(fieldName)) {
            // Send a message to the parent window
            try {
                const result = window.parent.postMessage({ field: fieldName, resourceId }, '*');

                if (result && result.status === 'success') {
                    $(this).val(result.value);

                    if (config.logging) {
                        console.log(`Field ${fieldName} updated successfully.`);
                    }
                } else if (config.errorHandling) {
                    console.error(`Failed to update field ${fieldName}.`);
                }
            } catch (error) {
                if (config.errorHandling) {
                    console.error(`Network error: ${error.message}`);
                }
            }
        }
    });
}

// C++ helper function
#include <forward_list>
#include <string>

void insertStringAfterInForwardList(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto it = list.begin();
    bool inserted = false;

    for (; it != list.end(); ++it) {
        if (*it == target) {
            it = list.insert_after(it, toInsert);
            inserted = true;
            break;
        }
    }

    if (!inserted) {
        list.push_front(toInsert); // Insert at the end since we can't insert directly
    }
}
