class DataStreamService {
    constructor(messagingSystem) {
        this.active = false;
        this.paused = false;
        this.dataSources = [];
        this.messagingSystem = messagingSystem;
        this.buffer = [];
    }

    start(dataSources) {
        if (this.active) return;

        this.dataSources = dataSources;
        this.active = true;

        this._setupListeners();
        this._notifyStatus('started');
    }

    stop() {
        if (!this.active) return;

        this.paused = false;
        this.buffer.length = 0;

        this._teardownListeners();
        this._resetState();

        this.active = false;
        this._notifyStatus('stopped');
    }

    reset() {
        this.stop();
        this._initializeBuffers();
    }

    pause() {
        if (!this.active || this.paused) return;

        this.paused = true;
        this._notifyStatus('paused');
    }

    resume() {
        if (!this.active || !this.paused) return;

        this.paused = false;
        this._processBufferedData();

        this._notifyStatus('resumed');
    }

    addDataSource(dataSource) {
        if (!this.active) throw new Error("Service is not active");

        this.dataSources.push(dataSource);
        this._attachListenerToSource(dataSource);
    }

    _setupListeners() {
        this.dataSources.forEach(source => {
            this._attachListenerToSource(source);
        });
    }

    _teardownListeners() {
        this.dataSources.forEach(source => {
            source.removeListener(this._handleDataReceived);
        });
    }

    _attachListenerToSource(source) {
