import io
from collections import defaultdict, deque
from datetime import datetime
import heapq
import threading

class LogAggregator:
    def __init__(self):
        self.log_buffer = deque()
        self.log_cache = {}
        self.lock = threading.Lock()

    def parse_log_entry(self, log_entry):
        # Example parsing function; customize as needed for different formats
        try:
            timestamp_str, source_id, message = log_entry.split('|', 2)
            timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M:%S')
            return timestamp, source_id.strip(), message.strip()
        except ValueError:
            return None

    def resolve_conflicts(self, logs):
        # Example conflict resolution by latest timestamp
        unique_logs = {}
        for log in sorted(logs, key=lambda x: (x[1], x[0])):
            _, source_id, entry_data = log
            if source_id not in unique_logs or unique_logs[source_id][0] < log[0]:
                unique_logs[source_id] = log
        return list(unique_logs.values())

    def aggregate_logs(self, new_entries):
        with self.lock:
            for entry in new_entries:
                parsed_entry = self.parse_log_entry(entry)
                if not parsed_entry:
                    continue

                timestamp, source_id, message = parsed_entry
                cache_key = f"{source_id}-{timestamp}"

                # Avoid processing duplicates using cache
                if cache_key in self.log_cache:
                    continue

                # Store to buffer and update cache for potential overlaps
                heapq.heappush(self.log_buffer, (timestamp, source_id, message))
                self.log_cache[cache_key] = True

            # Resolve conflicts within the buffer
            aggregated_logs = self.resolve_conflicts(self.log_buffer)

            # Clear processed logs from buffer
            while self.log_buffer and len(aggregated_logs) > 0:
                _, _, _ = heapq.heappop(self.log_buffer)

            result_io = io.StringIO()
            for timestamp, source_id, message in aggregated_logs:
                result_io.write(f"{timestamp.strftime('%Y-%m-%d %H:%M:%S')} | {source_id} | {message}\n")

            return result_io.getvalue()

# Example usage
aggregator = LogAggregator()

new_logs = [
    "2023-10-01 12:00:00 | source1 | Message A",
    "2023-10-01 12:00:01 | source2 | Message B",
    # Add more diverse log entries
]

aggregated_message = aggregator.aggregate_logs(new_logs)
print(aggregated_message)
