public class ReviewProcessor {

    private static final Logger logger = Logger.getLogger(ReviewProcessor.class.getName());
    private final ConcurrentHashMap<String, String> reviewCache = new ConcurrentHashMap<>();
    private final Cache<String, Double> sentimentCache;
    private final ExecutorService executorService;

    public ReviewProcessor() {
        CacheBuilder<String, Double> cacheBuilder = CacheBuilder.newBuilder()
                .maximumSize(10000)
                .expireAfterWrite(Duration.ofMinutes(10))
                .build();
        this.sentimentCache = cacheBuilder.build();
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void processReviews(Path filePath) {
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            String line;
            while ((line = reader.readLine()) != null) {
                executorService.submit(() -> processReview(line));
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error reading file", e);
        }
    }

    private void processReview(String reviewText) {
        String cacheKey = generateCacheKey(reviewText);

        if (!reviewCache.containsKey(cacheKey)) {
            Double sentimentScore;
            synchronized (this.sentimentCache) {
                sentimentScore = sentimentCache.getIfPresent(cacheKey);
            }

            if (sentimentScore == null) {
                try {
                    sentimentScore = fetchSentimentFromApi(reviewText);
                    synchronized (this.sentimentCache) {
                        sentimentCache.put(cacheKey, sentimentScore);
                    }
                } catch (Exception e) {
                    logger.log(Level.WARNING, "API error: ", e);
                    return;
                }

                reviewCache.put(cacheKey, categorizeSentiment(sentimentScore));
            } else {
                reviewCache.put(cacheKey, categorizeSentiment(sentimentScore));
            }
        }

        logSystemMetrics();
    }

    private String generateCacheKey(String text) {
        return text.hashCode() + "";
    }

    private Double fetchSentimentFromApi(String reviewText) throws IOException {
        // Simulate API call to fetch sentiment score
        return Math.random();  // Mocked sentiment score
    }

    private String categorizeSentiment(Double sentimentScore) {
        if (sentimentScore > 0.75) {
            return "Positive";
        } else if (sentimentScore < 0.25) {
            return "Negative";
        } else {
            return "Neutral";
        }
    }

    private void logSystemMetrics() {
        Runtime runtime = Runtime.getRuntime();
        double usedMemory = (runtime.totalMemory() - runtime.freeMemory()) / (1024.0 * 1024.0);
        long cpuLoad = getCPULoad();

        logger.info("CPU Load: " + cpuLoad + "% | Memory Usage: " + usedMemory + "MB");
    }

    private long getCPULoad() {
        // Simulate CPU load calculation
        return new SecureRandom().nextInt(100);  // Mocked CPU load value
    }

    public void shutdown() {
        executorService.shutdown();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ReviewProcessor processor = new ReviewProcessor();
        Path filePath = Paths.get("path/to/large/review/file.txt");

        processor.processReviews(filePath);
        processor.shutdown();

        System.out.println("Processing completed.");
    }
}
