import java.util.concurrent.*;
import java.util.logging.*;
import java.time.*;

public class BackgroundServiceManager {

    private static final Logger logger = Logger.getLogger(BackgroundServiceManager.class.getName());
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private final ConcurrentHashMap<String, Boolean> serviceStatus = new ConcurrentHashMap<>();
    private final AtomicLong startCount = new AtomicLong();
    private final AtomicLong stopCount = new AtomicLong();

    // Configurable parameters
    private static double workloadThreshold;
    private static int retryLimit = 5;
    private static long initialBackoffMillis = 1000;
    private static int maxRandomDelaySeconds = 10;

    public BackgroundServiceManager(double threshold) {
        this.workloadThreshold = threshold;
    }

    public void startService(String serviceId, double currentWorkload) {
        if (currentWorkload >= workloadThreshold && !serviceStatus.getOrDefault(serviceId, false)) {
            serviceStatus.put(serviceId, true);
            logger.info("Starting service: " + serviceId);
            startCount.incrementAndGet();
            // Simulate starting the service
        } else {
            logger.info("Service already running or below threshold: " + serviceId);
        }
    }

    public void stopService(String serviceId) {
        if (serviceStatus.getOrDefault(serviceId, false)) {
            serviceStatus.put(serviceId, false);
            logger.info("Stopping service: " + serviceId);
            stopCount.incrementAndGet();
            generateHealthReport(serviceId);

            // Simulate stopping the service
        } else {
            logger.info("Service already stopped or doesn't exist: " + serviceId);
        }
    }

    private void generateHealthReport(String serviceId) {
        int retry = 0;
        long backoff = initialBackoffMillis;

        while (retry < retryLimit) {
            try {
                // Simulate sending a health report
                logger.info("Generating health report for: " + serviceId);
                break; // Break if successful
            } catch (Exception e) {
                logger.warning("Failed to send health report, attempt " + (retry + 1));
                retry++;
                backoff *= 2;
                try {
                    Thread.sleep(backoff + new Random().nextInt(1000)); // Exponential backoff with jitter
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        if (retry == retryLimit) {
            logger.severe("Failed to send health report after " + retryLimit + " attempts for service: " + serviceId);
        }
    }

    public String getServiceStatus() {
        return String.format(
            "Starts: %d, Stops: %d, Active Services: %s",
            startCount.get(),
            stopCount.get(),
            serviceStatus.toString()
        );
    }

    // Simulate workload monitoring
    private void monitorWorkload(double currentWorkload) {
        scheduler.scheduleAtFixedRate(() -> {
            for (String serviceId : serviceStatus.keySet()) {
                if (currentWorkload >= workloadThreshold && !serviceStatus.get(serviceId)) {
                    startService(serviceId, currentWorkload);
                } else if (currentWorkload < workloadThreshold && serviceStatus.get(serviceId)) {
                    stopService(serviceId);
                }
            }

            // Random delay to simulate dynamic response
            try {
                Thread.sleep(new Random().nextInt(maxRandomDelaySeconds * 1000));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, 0, 1, TimeUnit.SECONDS);
    }

    public static void main(String[] args) {
        BackgroundServiceManager manager = new BackgroundServiceManager(75.0); // Threshold set to 75%

        // Example workload monitor starting with a random workload value
        double initialWorkload = Math.random() * 100;
        logger.info("Initial Workload: " + initialWorkload);
        manager.monitorWorkload(initialWorkload);

        // Expose health check endpoint
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            System.out.println(manager.getServiceStatus());
        }));
    }
}
