function updateVendorAutoloader() {
    $maxRetries = 3;
    for ($attempt = 0; $attempt < $maxRetries; $attempt++) {
        try {
            shell_exec('git submodule update --init --recursive');
            composerInstall();
            break;
        } catch (Exception $e) {
            if ($attempt === $maxRetries - 1) {
                throw new Exception("Failed to update vendor autoloader after multiple attempts.", 0, $e);
            }
            sleep(5); // Retry delay
        }
    }
}

