    $configPath = __DIR__ . "/config/{$env}.php";
    if (!file_exists($configPath)) {
        throw new Exception("Configuration file for environment {$env} not found.");
    }

    $defaultConfig = require __DIR__ . '/config/default.php';
    $envConfig = include $configPath;

    return array_merge($defaultConfig, $envConfig);
}

