use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::time::{timeout, Duration};
use reqwest::{Client as ReqwestClient, Request, Response, Url};
use log::{info, error};

struct HttpClient {
    client: Arc<Mutex<ReqwestClient>>,
    backends: Vec<String>,
    current_backend_index: usize,
    timeout_duration: Duration,
}

impl HttpClient {
    pub fn new(backends: Vec<String>, timeout_ms: u64) -> Self {
        let client = ReqwestClient::builder()
            .gzip(true)
            .build().expect("Failed to build HTTP Client");

        HttpClient {
            client: Arc::new(Mutex::new(client)),
            backends,
            current_backend_index: 0,
            timeout_duration: Duration::from_millis(timeout_ms),
        }
    }

    pub async fn send_request(&mut self, request: Request) -> Result<Response, reqwest::Error> {
        let backend_url = self.select_backend();

        let mut client = self.client.lock().unwrap();

        // Modify the request URL with the selected backend
        let new_url = Url::parse_with_params(backend_url.as_str(), &request.url().query_pairs())
            .expect("Invalid backend URL");

        let modified_request = request.url(new_url).build()?;

        info!("Sending request to: {}", new_url);

        // Handle dynamic load balancing and retry logic
        let mut attempts = 0;
        loop {
            match timeout(self.timeout_duration, client.execute(modified_request.clone())).await {
                Ok(Ok(response)) => return Ok(response),
                Ok(Err(err)) if err.is_timeout() && attempts < 3 => {
                    error!("Request timed out: {}, retrying...", err);
                    self.rotate_backend();
                    attempts += 1;
                }
                Ok(Err(err)) => return Err(err.into()),
                Err(_) => return Err(reqwest::Error::new(
                    reqwest::StatusCode::REQUEST_TIMEOUT,
                    "Operation timed out",
                )),
            }
        }
    }

    fn select_backend(&mut self) -> String {
        let url = self.backends[self.current_backend_index].clone();
        self.rotate_backend();
        url
    }

    fn rotate_backend(&mut self) {
        self.current_backend_index = (self.current_backend_index + 1) % self.backends.len();
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let backends = vec![
        "https://backend1.example.com".to_string(),
        "https://backend2.example.com".to_string(),
    ];

    let mut client = HttpClient::new(backends, 5000);

    let request = Request::builder()
        .method("GET")
        .uri("https://example.com/data")
        .header("User-Agent", "Rust HTTP Client")
        .body(reqwest::Body::empty())
        .unwrap();

    match client.send_request(request).await {
        Ok(response) => {
            info!("Response: {}", response.status());
        }
        Err(e) => {
            error!("Error sending request: {:?}", e);
        }
    }

    Ok(())
}
```

