use std::fs;
use std::process::{Command, Output};
use std::time::{Duration, Instant};
use sysinfo::{ProcessExt, System, SystemExt};

fn get_resident_set_size(pid: u32) -> Option<u64> {
    let mut system = System::new_all();
    if let Some(process) = system.get_process(pid) {
        return process.memory().as_u64();
    }
    None
}

pub fn compile_with_metrics(source_dir: &str, target_binary: &str) -> i32 {
    // Function to log metrics and errors
    sync_lazy::SyncLazy::new(|| {
        let start_time = Instant::now();

        // Determine the process ID of the current Rust executable
        let pid = std::process::id() as u32;
        let start_rss = get_resident_set_size(pid);

        let output: Output = Command::new("cargo")
            .args(&["build", "--manifest-path", format!("{}/Cargo.toml", source_dir)])
            .output()
            .expect("Failed to run cargo build");

        let elapsed_time = start_time.elapsed();
        let end_rss = get_resident_set_size(pid);

        // Log metrics and errors based on conditions
        if output.status.success() {
            println!(
                "Compilation succeeded. Time: {:?}, Start RSS: {:?} bytes, End RSS: {:?} bytes",
                elapsed_time,
                start_rss,
                end_rss
            );
        } else {
            let error_message = String::from_utf8_lossy(&output.stderr);
            println!(
                "Compilation failed. Time: {:?}, Error: {}",
                elapsed_time, &error_message
            );

            // Conditional logging based on specific thresholds
            if elapsed_time > Duration::new(10, 0) { // If compilation takes more than 10 seconds
                println!("Warning: Compilation time exceeded threshold.");
            }

            if let Some(start_rss) = start_rss {
                if end_rss.unwrap_or(0) - start_rss > 100_000_000 { // RSS change of over 100MB
                    println!(
                        "Memory usage increased significantly. Start: {:?}, End: {:?}",
                        start_rss, end_rss.unwrap()
                    );
                }
            }
        }

        output.status.code().unwrap_or(1)
    })
}
