<?php

class WeatherUpdater {

    private $apiUrl;
    private $apiKey;
    private $cacheDuration = 3600; // Cache duration in seconds (1 hour)

    private $dbConnection;

    public function __construct($apiUrl, $apiKey, PDO $dbConnection) {
        $this->apiUrl = $apiUrl;
        $this->apiKey = $apiKey;
        $this->dbConnection = $dbConnection;
    }

    public function updateWeatherMetrics(array $locationIds): string {
        foreach ($locationIds as $locationId) {
            $cachedData = $this->getCachedWeather($locationId);

            if ($cachedData && (time() - strtotime($cachedData['timestamp'])) < $this->cacheDuration) {
                $this->updateDatabase($locationId, $cachedData);
                continue;
            }

            $weatherData = $this->fetchWeatherData($locationId);

            if ($weatherData) {
                $this->updateDatabase($locationId, $weatherData);
                $this->cacheWeather($locationId, $weatherData);
            } else {
                // Handle API rate limit or retry logic
                sleep(1); // Simple backoff strategy for demonstration purposes
                $weatherData = $this->fetchWeatherDataWithRetry($locationId, 3);

                if ($weatherData) {
                    $this->updateDatabase($locationId, $weatherData);
                    $this->cacheWeather($locationId, $weatherData);
                }
            }
        }

        return "Weather metrics updated successfully.";
    }

    private function fetchWeatherData(string $locationId): ?array {
        try {
            $response = file_get_contents("$this->apiUrl?apiKey=$this->apiKey&locationId=$locationId");
            if ($response === FALSE) {
                return null;
            }

            $data = json_decode($response, true);

            // Assuming the API returns structured data like: {"temperature": ... , "humidity": ..., "windSpeed": ...}
            return [
                'temperature' => $data['main']['temp'],
                'humidity' => $data['main']['humidity'],
                'wind_speed' => $data['wind']['speed'],
                'timestamp' => date('Y-m-d H:i:s')
            ];
        } catch (Exception $e) {
            return null;
        }
    }

    private function fetchWeatherDataWithRetry(string $locationId, int $retries): ?array {
        while ($retries > 0) {
            $data = $this->fetchWeatherData($locationId);
            if ($data !== null) {
                return $data;
            }
            sleep(2); // Exponential backoff could be implemented here
            $retries--;
        }

        return null; // Return null after exhausting retries
    }

    private function updateDatabase(string $locationId, array $weatherData): void {
        $stmt = $this->dbConnection->prepare("UPDATE weather_metrics SET temperature=?, humidity=?, wind_speed=?, timestamp=? WHERE location_id=?");
        $stmt->execute([
            $weatherData['temperature'],
            $weatherData['humidity'],
            $weatherData['wind_speed'],
            $weatherData['timestamp'],
            $locationId
        ]);
    }

    private function cacheWeather(string $locationId, array $weatherData): void {
        // Simple file-based caching mechanism for demonstration purposes.
        file_put_contents("cache/weather_$locationId.json", json_encode($weatherData));
    }

    private function getCachedWeather(string $locationId): ?array {
        $cacheFile = "cache/weather_$locationId.json";

        if (file_exists($cacheFile)) {
            return json_decode(file_get_contents($cacheFile), true);
        }

        return null;
    }
}

// Usage
$apiUrl = 'https://example.com/weather-api';
$apiKey = 'your_api_key_here';

try {
    $dbConnection = new PDO('mysql:host=localhost;dbname=weather_db', 'username', 'password');
} catch (PDOException $e) {
    die("DB Connection failed: " . $e->getMessage());
}

$weatherUpdater = new WeatherUpdater($apiUrl, $apiKey, $dbConnection);
echo $weatherUpdater->updateWeatherMetrics(['location1', 'location2']);
