const https = require('https');
const { promisify } = require('util');
const fs = require('fs');
const readline = require('readline');

const fetchWithRetries = async (url, retries = 3) => {
    for (let attempt = 0; attempt < retries; attempt++) {
        try {
            const response = await promisify(https.get)(url);
            return streamToPromise(response);
        } catch (error) {
            if (attempt === retries - 1 || !shouldRetry(error)) {
                throw error;
            }
        }
    }
};

const shouldRetry = (error) => {
    // Define logic for when to retry, e.g., network errors
    return error.code === 'ENOTFOUND' || error.code === 'EAI_AGAIN';
};

const streamToPromise = async (stream) => {
    const rl = readline.createInterface({
        input: stream,
        crlfDelay: Infinity
    });

    let data = '';
    for await (const line of rl) {
        data += line;
    }

    return data;
};

const getStorageLocation = (oauthRequest) => {
    // Logic to determine storage location based on request metadata
    const env = oauthRequest.environment || 'development';
    const version = oauthRequest.version || 'v1';
    return `/path/to/certs/${env}/${version}/`;
};

const logExecutionTime = async (fn, args) => {
    const start = Date.now();
    try {
        await fn(...args);
    } finally {
        const duration = Date.now() - start;
        console.log(`Execution time: ${duration}ms`);
    }
};

async function fetchAndConcatenateCertificates(oauthRequest) {
    return logExecutionTime(async () => {
        try {
            const storageLocation = getStorageLocation(oauthRequest);

            const privateKeyUrl = `${storageLocation}private.key`;
            const certificateUrl = `${storageLocation}certificate.crt`;

            const privateKey = await fetchWithRetries(privateKeyUrl);
            const certificate = await fetchWithRetries(certificateUrl);

            return `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`;
        } catch (error) {
            console.error(`Error fetching certificates: ${error.message}`);
            throw error;
        }
    });
}

module.exports = fetchAndConcatenateCertificates;

