<?php

function authenticateUserOAuth2($clientId, $clientSecret, $redirectUri, $authorizationCode) {
    // Endpoint configuration
    $tokenUrl = 'https://external-oauth-service.com/token';
    $userInfoUrl = 'https://external-oauth-service.com/userinfo';

    try {
        // Obtain access token via OAuth 2.0
        $ch = curl_init($tokenUrl);
        $data = [
            'grant_type' => 'authorization_code',
            'code'       => $authorizationCode,
            'redirect_uri' => $redirectUri,
            'client_id'   => $clientId,
            'client_secret' => $clientSecret
        ];

        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        $response = curl_exec($ch);
        if (curl_errno($ch)) {
            throw new Exception('Failed to obtain access token: ' . curl_error($ch));
        }

        curl_close($ch);

        $tokenData = json_decode($response, true);
        if (!isset($tokenData['access_token'])) {
            throw new Exception('Invalid response from OAuth server');
        }

        // Store tokens securely and manage session
        $_SESSION['accessToken'] = $tokenData['access_token'];
        $_SESSION['refreshToken'] = $tokenData['refresh_token'];

        // Retrieve user information using the access token
        $ch = curl_init($userInfoUrl);
        curl_setopt($ch, CURLOPT_HTTPHEADER, ['Authorization: Bearer ' . $tokenData['access_token']]);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        $userInfoResponse = curl_exec($ch);
        if (curl_errno($ch)) {
            throw new Exception('Failed to retrieve user information');
        }

        curl_close($ch);

        $userProfile = json_decode($userInfoResponse, true);

        // Fetch additional profile details from external API
        $additionalDetails = fetchAdditionalUserDetails($tokenData['access_token'], $userProfile['email']);

        // DNS resolution for email domain IP
        $domainIp = resolveDomainToIP(parse_url($userProfile['email'], PHP_URL_HOST));

        return [
            'profile' => $userProfile,
            'additionalDetails' => $additionalDetails,
            'ipAddress' => $domainIp
        ];
    } catch (Exception $e) {
        // Log error and provide a generic error message to the user
        error_log($e->getMessage());
        return ['error' => 'An unexpected error occurred during authentication. Please try again later.'];
    }
}

function fetchAdditionalUserDetails($accessToken, $emailDomain) {
    // Simulate additional API call for extra details with throttling to minimize frequency
    static $cache = [];
    $cacheKey = md5($emailDomain);

    if (isset($cache[$cacheKey]) && time() - $cache[$cacheKey]['timestamp'] < 3600) {
        return $cache[$cacheKey]['data'];
    }

    // Simulated API call
    try {
        $additionalDetails = []; // Replace with actual API request

        $cache[$cacheKey] = [
            'data' => $additionalDetails,
            'timestamp' => time()
        ];

        return $additionalDetails;
    } catch (Exception $e) {
        error_log('Failed to fetch additional user details: ' . $e->getMessage());
        return [];
    }
}

function resolveDomainToIP($domain) {
    try {
        // Resolve domain IP
        $ipAddress = gethostbyname($domain);

        if ($ipAddress === $domain || filter_var($ipAddress, FILTER_VALIDATE_IP) === false) {
            throw new Exception('DNS resolution failed');
        }

        return $ipAddress;
    } catch (Exception $e) {
        error_log('DNS resolution error: ' . $e->getMessage());
        return null;
    }
}

// Example usage
session_start();
$userData = authenticateUserOAuth2('your-client-id', 'your-client-secret', 'https://your-redirect-uri.com', $_GET['code']);
print_r($userData);

?>
```

