class PasswordUpdater {

    private $authService;
    private $logger;
    private $cache;

    public function __construct($authService, $logger, $cache) {
        $this->authService = $ authService;
        $this->logger = $logger;
        $this->cache = $cache;
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->validatePasswordStrength($newPassword)) {
            throw new Exception("Password does not meet strength requirements.");
        }

        if ($this->isPasswordDuplicate($userId, $newPassword)) {
            throw new Exception("Password must be unique.");
        }

        try {
            // Acquire a distributed lock to handle concurrency
            $lock = $this->acquireLock($userId);

            // Update the password in all databases/services
            $this->updateInDatabases($userId, $newPassword);
            $this->authService->updatePassword($userId, $newPassword);

            // Notify user of successful change
            $this->notifyUser($userId, "Your password has been successfully updated.");

            // Log the event
            $this->logger->info("Password changed for user ID: {$userId}");

        } catch (Exception $e) {
            $this->logger->error("Failed to update password for user ID: {$userId}, Error: {$e->getMessage()}");
            throw $e;
        } finally {
            if (isset($lock)) {
                $this->releaseLock($userId, $lock);
            }
        }

        // Clear cached password information
        $this->cache->delete("password_{$userId}");
