#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_STREAMS 10000
#define WINDOW_SIZE 100

typedef struct {
    double timestamp;
    int sensor_id;
    float signal_strength;
} SensorData;

typedef struct Node {
    SensorData data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} SlidingWindow;

typedef struct {
    float average_signal_strength;
    int redundant_readings_count;
    pthread_mutex_t metrics_lock;
} Metrics;

SlidingWindow windows[MAX_STREAMS];
Metrics metrics;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_system() {
    for (int i = 0; i < MAX_STREAMS; ++i) {
        windows[i].head = NULL;
        windows[i].tail = NULL;
        pthread_mutex_init(&windows[i].lock, NULL);
    }
    metrics.average_signal_strength = 0.0;
    metrics.redundant_readings_count = 0;
    pthread_mutex_init(&metrics.metrics_lock, NULL);
}

void add_data_to_window(int stream_id, SensorData data) {
    SlidingWindow* window = &windows[stream_id];
    pthread_mutex_lock(&window->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;

    if (!window->head || window->tail->data.timestamp < data.timestamp) {
        if (!window->head) {
            window->head = new_node;
        }
        window->tail->next = new_node;
        window->tail = new_node;
    } else {
        Node* current = window->head;
        while (current->next && current->next->data.timestamp < data.timestamp) {
            current = current->next;
        }
        if (current->next && current->next->data.timestamp == data.timestamp &&
            current->next->data.signal_strength == data.signal_strength) {
            pthread_mutex_lock(&metrics.metrics_lock);
            metrics.redundant_readings_count++;
            pthread_mutex_unlock(&metrics.metrics_lock);
            free(new_node);
        } else {
            new_node->next = current->next;
            current->next = new_node;
            if (new_node->next == NULL) {
                window->tail = new_node;
            }
        }
    }

    // Maintain sliding window size
    if (window->head && window->tail->data.timestamp - window->head->data.timestamp > WINDOW_SIZE) {
        Node* temp = window->head;
        window->head = window->head->next;
        free(temp);
    }

    pthread_mutex_unlock(&window->lock);

    // Update metrics
    pthread_mutex_lock(&metrics.metrics_lock);
    float total_strength = 0.0;
    int count = 0;
    for (int i = 0; i < MAX_STREAMS; ++i) {
        Node* current = windows[i].head;
        while (current) {
            total_strength += current->data.signal_strength;
            count++;
            current = current->next;
        }
    }
    metrics.average_signal_strength = (count > 0) ? total_strength / count : 0.0;
    pthread_mutex_unlock(&metrics.metrics_lock);
}

void* process_stream(void* arg) {
    int stream_id = *(int*)arg;

    // Simulate processing incoming data
    while (1) {
        SensorData data;
        // Assume fetch_data() is a function that retrieves sensor data for the given stream_id
        if (fetch_data(stream_id, &data)) {
            add_data_to_window(stream_id, data);
        }
        usleep(1000); // Simulate delay between incoming data packets
    }

    return NULL;
}

int main() {
    initialize_system();

    pthread_t threads[MAX_STREAMS];
    int stream_ids[MAX_STREAMS];

    for (int i = 0; i < MAX_STREAMS; ++i) {
        stream_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_stream, &stream_ids[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_STREAMS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}

// Placeholder function for fetching data
int fetch_data(int stream_id, SensorData* data) {
    // Simulate data retrieval logic
    time_t now = time(NULL);
    data->timestamp = (double)now + ((double)rand() / RAND_MAX);
    data->sensor_id = stream_id;
    data->signal_strength = (float)(rand() % 100) / 10.0;
    return 1; // Simulate successful fetch
}
