using System;
using System.Collections.Generic;

public class DynamicValueGenerator
{
    private double minValue;
    private double maxValue;
    private double stepSize;

    public DynamicValueGenerator(double minValue, double maxValue, double stepSize)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("minValue must be less than maxValue.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.stepSize = Math.Max(stepSize, 1e-10); // Prevent division by zero or extremely small step size.
    }

    public DynamicValueGenerator(string range)
    {
        if (string.IsNullOrWhiteSpace(range))
            throw new ArgumentException("Range cannot be null or whitespace.");

        var parts = range.Split(new[] { '-', '..', 'to' }, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length != 2)
            throw new ArgumentException("Invalid range format.");

        double start, end;
        if (!double.TryParse(parts[0], out start) || !double.TryParse(parts[1], out end))
            throw new ArgumentException("Range values must be numeric.");

        this.minValue = start;
        this.maxValue = end;
        this.stepSize = 1; // Default step size for integer ranges.
    }

    public double GetRandomFloat()
    {
        Random rand = new Random();
        double range = maxValue - minValue;
        int steps = (int)(range / stepSize);
        if (steps == 0) return minValue;

        double randomStep = rand.Next(steps + 1); // Include the upper boundary.
        return minValue + randomStep * stepSize;
    }

    public int GetRandomInt()
    {
        Random rand = new Random();
        return (int)(minValue + rand.NextDouble() * (maxValue - minValue));
    }

    public List<int> GetRandomList(int count)
    {
        if (count < 0) throw new ArgumentOutOfRangeException(nameof(count), "Count cannot be negative.");

        List<int> randomIntegers = new List<int>(count);
        Random rand = new Random();

        for (int i = 0; i < count; i++)
        {
            randomIntegers.Add((int)(minValue + rand.NextDouble() * (maxValue - minValue)));
        }

        return randomIntegers;
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }
}
