async function processDataset(dataset, updateInterval = 5000, completionThreshold = 10) {
    const maxConcurrentTasks = 10;
    let taskQueue = [];
    let completedCount = 0;
    let totalTasks = dataset.length;

    // Helper to simulate async processing of a data item
    const processItemAsync = (item, index) => new Promise((resolve, reject) => {
        setTimeout(() => {
            if (Math.random() > 0.9) { // Simulate random failure
                return reject(new Error(`Failed processing item ${index}`));
            }
            resolve(item * 2); // Example operation: double the value
        }, Math.random() * 1000 + 500); // Random delay to simulate network latency
    });

    // Helper function to run tasks with limited concurrency
    const runConcurrentTasks = async () => {
        let activePromises = [];

        for (let item of taskQueue) {
            if (activePromises.length >= maxConcurrentTasks) break;

            const index = dataset.indexOf(item);
            const promise = processItemAsync(item, index)
                .then(result => {
                    completedCount++;
                    return result;
                })
                .catch(error => {
                    console.error(`Error processing item: ${error.message}`);
                    return null; // handle failed task without stopping the queue
                });

            activePromises.push(promise);

            if (activePromises.length === maxConcurrentTasks) {
                const results = await Promise.all(activePromises);
                taskQueue = taskQueue.filter((_, i) => !results.includes(dataset[i] * 2));
                activePromises = [];
            }
        }

        if (activePromises.length > 0) {
            const results = await Promise.all(activePromises);
            taskQueue = taskQueue.filter((_, i) => !results.includes(dataset[i] * 2));
        }
    };

    // Function to provide periodic updates
    const startProgressUpdates = () => {
        setInterval(() => {
            const progressPercent = (completedCount / totalTasks) * 100;
            console.log(`Progress: ${progressPercent.toFixed(2)}% completed`);

            if (progressPercent >= completionThreshold && taskQueue.length > 0) {
                runConcurrentTasks();
            }
        }, updateInterval);
    };

    // Initialize the task queue with all items
    taskQueue = dataset;

    startProgressUpdates();

    while (taskQueue.length > 0) {
        await runConcurrentTasks();
    }

    console.log("All tasks completed.");
}

// Example usage:
const data = Array.from({ length: 100 }, (_, i) => i + 1); // Sample dataset

processDataset(data)
    .then(() => console.log("Processing complete."))
    .catch(error => console.error(`Final error: ${error.message}`));
```

### Explanation
- **Concurrent Task Limiting**: The `runConcurrentTasks` function handles concurrent tasks, ensuring no more than 10 are processed simultaneously.
- **Error Handling**: Errors during processing of individual items do not stop the entire process; they're logged and handled gracefully.
- **Progress Tracking**: Periodic updates on progress percentage are logged to console every specified interval (`updateInterval`), allowing for user interface integration if needed.
- **Asynchronous Processing**: Simulated with `setTimeout`, representing potential network delays or asynchronous operations.
- **Scalability and Robustness**: The design handles varying data sizes and network conditions, providing a robust solution against delays and failures.']

