char* processStringWithLimit(const char* str, int sizeLimit, void (*callback)(const char*)) {
    if (str == NULL || sizeLimit <= 0) return NULL;

    int length = strlen(str);
    if (length > sizeLimit) return NULL;

    // Allocate memory for the new string including '/' and null terminator
    int newSize = length + 2; // Length of original string + '/' + '\0'
    char* result = malloc(newSize);

    if (!result) return NULL;

    strcpy(result, str);
    strcat(result, "/");

    callback(result); // Call the provided callback function with the allocated memory
    return result;
}
