function getElementSelectors(node, selector, testElement) {
    let matchingElements = [];

    function traverseDOM(currentNode) {
        if (!currentNode || !currentNode.matches || !currentNode.querySelectorAll) return;

        // Test if current node matches the selector using the callback function
        if (currentNode.matches(selector)) {
            if (testElement(currentNode)) {
                matchingElements.push(currentNode);
            }
        }

        // Recursively traverse children
        currentNode.childNodes.forEach(traverseDOM);
    }

    traverseDOM(node);

    return matchingElements;
}
