using System.Threading.Tasks;

public class ImageMetadata
{
    public int BitsPerSample { get; set; }
    public int SamplesPerPixel { get; set; }
    public string ExtraSamples { get; set; } = string.Empty;
    public string MD5Hash { get; set; }
}

public class TIFFProcessor
{
    private static readonly HashSet<int> SupportedBitsPerSample = new HashSet<int>
    {
        1, 2, 4, 8, 16
    };

    public async Task<ImageMetadata> ProcessTIFFImageAsync(string imagePath)
    {
        var metadata = new ImageMetadata();

        // Compute MD5 hash of the file path
        using (var md5 = MD5.Create())
