#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_BASE_NAME_LENGTH 256
#define MAX_FILENAME_LENGTH 255

static char generate_filename(const char *base_name, const char *extension) {
    static char new_filename[MAX_FILENAME_LENGTH + 1];
    if (!base_name || !extension) return '\0';

    // Ensure total length does not exceed allowed size
    size_t base_len = strlen(base_name);
    size_t ext_len = strlen(extension);

    if (base_len >= MAX_BASE_NAME_LENGTH || (base_len + ext_len + 2) > MAX_FILENAME_LENGTH) {
        new_filename[0] = '\0';
        return new_filename[0];
    }

    // Normalize the base name
    int alpha_count = 0;
    for (size_t i = 0; i < base_len; ++i) {
        if (isalnum(base_name[i])) {
            new_filename[i] = base_name[i];
            ++alpha_count;
        } else {
            new_filename[i] = '_';
        }
    }

    // Append alphanumeric count to normalized base name
    char count_str[12];  // Enough for INT_MAX in decimal + null terminator
    snprintf(count_str, sizeof(count_str), "%d", alpha_count);
    size_t count_len = strlen(count_str);

    if (base_len + count_len > MAX_FILENAME_LENGTH) {
        new_filename[0] = '\0';
        return new_filename[0];
    }

    strncat(new_filename, count_str, MAX_FILENAME_LENGTH - base_len);

    // Derive a new extension
    char new_ext[4];  // Enough for character + digit + dot + null terminator
    if (base_len > 0) {
        new_ext[0] = isalnum(new_filename[0]) ? new_filename[0] : '_';
    } else {
        new_ext[0] = '_';  // Fallback
    }

    new_ext[1] = count_str[count_len - 1];  // Last digit of count

    // Create final filename with new extension, if needed
    snprintf(new_filename + strlen(new_filename), 
             MAX_FILENAME_LENGTH - strlen(new_filename) + 1,
             ".%c%d", new_ext[0], (count_str[0] != '\0') ? new_ext[1] : '0');

    // Append original extension if length permits
    size_t final_len = strlen(new_filename);
    if ((final_len + ext_len + 1) <= MAX_FILENAME_LENGTH && strcmp(extension, ".") != 0) {
        snprintf(new_filename + final_len, 
                 MAX_FILENAME_LENGTH - final_len + 1,
                 ".%s", extension);
    }

    return new_filename[0];
}
