#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/pem.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_THREADS 8

typedef struct {
    EVP_CIPHER_CTX *enc_ctx;
    EVP_MD_CTX *md_ctx;
    pthread_mutex_t lock;
} CryptoContext;

void initialize_crypto_context(CryptoContext **ctx) {
    *ctx = (CryptoContext *)malloc(sizeof(CryptoContext));
    (*ctx)->enc_ctx = EVP_CIPHER_CTX_new();
    (*ctx)->md_ctx = EVP_MD_CTX_new();
    pthread_mutex_init(&(*ctx)->lock, NULL);
}

void finalize_crypto_context(CryptoContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->enc_ctx);
    EVP_MD_CTX_free(ctx->md_ctx);
    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
}

int configure_crypto_system(const char *config_path) {
    FILE *file = fopen(config_path, "r");
    if (!file) return -1;

    const EVP_CIPHER *cipher;
    const EVP_MD *digest;

    while (fscanf(file, "%s", buffer) != EOF) {
        if (strcmp(buffer, "AES") == 0) {
            cipher = EVP_aes_256_cbc();
            EVP_add_cipher(cipher);
        } else if (strcmp(buffer, "Camellia") == 0) {
            cipher = EVP_camellia_256_cbc();
            EVP_add_cipher(cipher);
        } else if (strcmp(buffer, "MD5") == 0) {
            digest = EVP_md5();
            EVP_add_digest(digest);
        } else if (strcmp(buffer, "SHA1") == 0) {
            digest = EVP_sha1();
            EVP_add_digest(digest);
        } else if (strcmp(buffer, "SHA256") == 0) {
            digest = EVP_sha256();
            EVP_add_digest(digest);
        } else if (strncmp(buffer, "RSA_", 4) == 0) {
            const char *digest_type;
            sscanf(buffer + 4, "%s", digest_type);

            if (strcmp(digest_type, "SHA1") == 0)
                EVP_add_cipher(EVP_pkey_id(EVP_PKEY_RSA));
            else if (strcmp(digest_type, "SHA256") == 0)
                EVP_add_cipher(EVP_pkey_id(EVP_PKEY_RSA));

            if (strcmp(digest_type, "SHA1") == 0) {
                digest = EVP_sha1();
                EVP_add_digest_alias("RSA-SHA1", digest);
            } else if (strcmp(digest_type, "SHA256") == 0) {
                digest = EVP_sha256();
                EVP_add_digest_alias("RSA-SHA256", digest);
            }
        }
    }

    fclose(file);
    return 0;
}

void *crypto_operation(void *arg) {
    CryptoContext *ctx = (CryptoContext *)arg;

    pthread_mutex_lock(&ctx->lock);

    // Example operation: encrypt and sign data
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];

    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    EVP_EncryptInit_ex(ctx->enc_ctx, NULL, NULL, key, iv);
    // Continue with encryption...

    const EVP_MD *md = EVP_sha256();
    HMAC(EVP_md_CTX_new(), md, strlen((char *)key), "message", 7, NULL, NULL);

    pthread_mutex_unlock(&ctx->lock);

    return NULL;
}

void perform_crypto_operations(const char *config_path) {
    if (configure_crypto_system(config_path) != 0) {
        fprintf(stderr, "Failed to configure crypto system.\n");
        return;
    }

    CryptoContext *contexts[MAX_THREADS];
    pthread_t threads[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        initialize_crypto_context(&contexts[i]);
        if (pthread_create(&threads[i], NULL, crypto_operation, contexts[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
        finalize_crypto_context(contexts[i]);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    perform_crypto_operations(argv[1]);

    EVP_cleanup();
    return EXIT_SUCCESS;
}
```

This code provides a basic structure for dynamically configuring and executing cryptographic operations using OpenSSL. It includes thread management, dynamic memory allocation, and configuration parsing. Adjustments may be necessary to fit specific requirements or environments.']

