#define MAX_COMMANDS 10
#define RESOURCE_LIMIT 80 // Example limit in percentage

volatile sig_atomic_t terminate = 0;

void handle_signal(int signo) {
    if (signo == SIGTERM || signo == SIGINT) {
        terminate = 1;
    }
}

int execute_command(const char *command, const char *env_vars[], size_t env_count) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 0;
    }

    if (pid == 0) { // Child process
        // Set environment variables
        for (size_t i = 0; i < env_count; ++i) {
            setenv(env_vars[i], "value", 1);
        }

        // Execute the command
        char *argv[] = {"/bin/sh", "-c", (char *)command, NULL};
        execvp(argv[0], argv);

        perror("execvp");
        exit(EXIT_FAILURE);
    }

    return pid;
}

int monitor_resources() {
    // Dummy function to simulate resource monitoring
    // Implement actual system call or library usage here
    return 50; // Example: returns current CPU usage percentage
}

void cleanup(int pids[], int count) {
    for (int i = 0; i < count; ++i) {
        if (pids[i] > 0) {
            kill(pids[i], SIGTERM);
            waitpid(pids[i], NULL, 0);
        }
    }
}

int execute_concurrent_commands(const char *commands[][2], size_t command_count) {
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    pid_t pids[MAX_COMMANDS] = {0};
    int successful_starts = 1;

    for (size_t i = 0; i < command_count && i < MAX_COMMANDS && !terminate; ++i) {
        const char *cmd = commands[i][0];
        const char *env_vars[] = {commands[i][1]};

        if (monitor_resources() > RESOURCE_LIMIT) {
            fprintf(stderr, "Resource limit exceeded\n");
            successful_starts = 0;
            break;
        }

        pids[i] = execute_command(cmd, env_vars, sizeof(env_vars) / sizeof(char *));
        if (pids[i] <= 0) {
            successful_starts = 0;
        }
    }

    while (!terminate && successful_starts) {
        int status;
        pid_t wpid = waitpid(-1, &status, WNOHANG);
        if (wpid == -1 && errno != ECHILD) {
            perror("waitpid");
            successful_starts = 0;
            break;
        }
    }

    cleanup(pids, command_count);

    return successful_starts ? 1 : 0;
}

int main() {
    const char *commands[][2] = {
        {"echo 'Command 1'", "ENV_VAR_1"},
        {"sleep 10", "ENV_VAR_2"},
        // Add more commands as needed
    };

    size_t command_count = sizeof(commands) / sizeof(commands[0]);

    if (execute_concurrent_commands(commands, command_count)) {
        printf("All commands successfully started.\n");
    } else {
        fprintf(stderr, "Failed to start all commands.\n");
    }

    return 0;
}
