using Microsoft.Web.Administration;

public class WebSiteManager
{
    private static readonly object _lock = new object();
    private static Dictionary<string, bool> _siteNameCache = new();

    public bool AddWebsite(string directoryPath, string siteName, int port)
    {
        if (!Directory.Exists(directoryPath))
            return LogAndReturnFailure($"Directory path does not exist: {directoryPath}");

        var configFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFilePath))
            return LogAndReturnFailure("Web.config file is missing.");

        using (var serverManager = new ServerManager())
        {
            lock (_lock)
            {
                // Check for unique site name
                if (_siteNameCache.ContainsKey(siteName) || serverManager.Sites.Any(s => s.Name == siteName))
                    return LogAndReturnFailure($"Site with the name '{siteName}' already exists.");

                _siteNameCache[siteName] = true;

                try
                {
                    // Add new site
                    var newSite = serverManager.Sites.Add(siteName, "http", $"*:{port}:{directoryPath}");

                    // Update cache
                    _siteNameCache[newSite.Name] = true;

                    // Commit changes
                    serverManager.CommitChanges();

                    // Start the website
                    newSite.Start();
                }
                catch (Exception ex)
                {
                    Log($"Error adding site: {ex.Message}", true);
                    return false;
                }
            }

            ReportStatus(siteName, "Added successfully.");
            return true;
        }
    }

    private bool LogAndReturnFailure(string message)
    {
        Log(message, true);
        return false;
    }

    private void Log(string message, bool isError = false)
    {
        // Implement logging logic here
        Console.WriteLine($"{DateTime.Now}: {(isError ? "ERROR" : "INFO")} - {message}");
    }

    private void ReportStatus(string siteName, string status)
    {
        // Communicate with monitoring service
        // Example: MonitoringService.Report(siteName, status);
    }
}
