public class CommandExecutor {

    public static void main(String[] args) {
        String command = "your-external-command"; // Replace with the actual command
        String directoryToClear = "/path/to/directory"; // Replace with the desired path

        try {
            clearDirectory(directoryToClear);

            ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
            configureEnvironment(processBuilder);

            long startTime = System.nanoTime();
            Process process = processBuilder.start();

            int exitCode = process.waitFor();
            long endTime = System.nanoTime();

            logPerformanceMetrics(startTime, endTime, exitCode);
        } catch (IOException | InterruptedException e) {
            handleException(e);
        }
    }

    private static void clearDirectory(String directoryPath) throws IOException {
        Path path = Paths.get(directoryPath);
        Files.walk(path)
             .sorted(Comparator.reverseOrder())
             .map(Path::toFile)
             .forEach(File::delete);
    }

    private static void configureEnvironment(ProcessBuilder processBuilder) {
        Map<String, String> environmentVariables = Map.of(
            "VAR1", "value1",
            "VAR2", "value2"
        );

        processBuilder.environment().putAll(environmentVariables);
    }

    private static void logPerformanceMetrics(long startTime, long endTime, int exitCode) {
        double durationInSeconds = (endTime - startTime) / 1_000_000_000.0;
        System.out.println("Command executed in " + durationInSeconds + " seconds with exit code: " + exitCode);

        // Additional logging for optimization purposes can be added here
    }

    private static void handleException(Exception e) {
        e.printStackTrace();
        // Implement additional exception handling logic if needed
    }
}
