public class ConnectionDetails
{
    public string Title { get; set; }
    public string ConnectionString { get; set; }
    public ConnectionState State { get; set; }
}

public enum ConnectionState
{
    Open,
    Closed
}

public delegate void CallbackHandler();

public static class EncryptionHelper
{
    private const int ErrorCodeInvalidPassword = 1;
    private const int ErrorCodeInvalidConnection = 2;
    private const int ErrorCodeInvalidCallback = 3;
    private const int ErrorCodeDecryptionFailure = 4;

    public static string ProcessAndDecryptMessage(string base64EncodedEncryptedMessage, ref Credentials credentials,
                                                  ref ConnectionDetails connectionDetails, ref CallbackHandler callbackHandler)
    {
        try
        {
            // Check if password is not null or empty
            if (string.IsNullOrEmpty(credentials.Password))
                return ErrorCodeInvalidPassword.ToString();

            // Ensure database connection is valid and the connection string is not null or empty
            if (connectionDetails == null || string.IsNullOrEmpty(connectionDetails.ConnectionString) ||
                connectionDetails.State != ConnectionState.Open)
                return ErrorCodeInvalidConnection.ToString();

            // Confirm that the connection details have a non-null title
            if (string.IsNullOrEmpty(connectionDetails.Title))
                return ErrorCodeInvalidConnection.ToString();

            // Validate callback handler delegate is not null and can be invoked successfully
            if (callbackHandler == null || !callbackHandler())
                return ErrorCodeInvalidCallback.ToString();

            try
            {
                // Proceed with decryption using Triple DES
                string decryptedMessage = DecryptTripleDES(base64EncodedEncryptedMessage, credentials.Password);

                return decryptedMessage;
            }
            catch (Exception ex)
            {
                // Log the error for debugging purposes without exposing sensitive information
                Console.WriteLine("Decryption failed: " + ex.Message);
                return ErrorCodeDecryptionFailure.ToString();
            }
        }
        catch (Exception ex)
        {
            // Handle unexpected exceptions gracefully
            Console.WriteLine("An unexpected error occurred: " + ex.Message);
            return ErrorCodeDecryptionFailure.ToString();
        }
    }

    private static string DecryptTripleDES(string base64EncodedEncryptedMessage, string password)
    {
        byte[] encryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);

        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            // Generate key and IV based on the provided password
            MD5 md5Hasher = MD5.Create();
            byte[] key = md5Hasher.ComputeHash(Encoding.UTF8.GetBytes(password));
            byte[] iv = new byte[8]; // 64-bit block size

            tdes.Key = key;
            tdes.IV = iv;

            using (CryptoStream cryptoStream = new CryptoStream(
                new System.IO.MemoryStream(encryptedBytes),
                tdes.CreateDecryptor(),
                CryptoStreamMode.Read))
            {
                byte[] decryptedBytes = new byte[encryptedBytes.Length];
                int bytesRead = cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);

                return Encoding.UTF8.GetString(decryptedBytes, 0, bytesRead);
            }
        }
    }
}
