```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static class AesCbcDecryptor
{
    private static readonly object LockObject = new object();

    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, string hmacKey, byte[] receivedHmac)
    {
        if (key.Length != 16 && key.Length != 32)
            throw new ArgumentException("Key must be either 16 or 32 bytes long.");

        try
        {
            using (var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(hmacKey)))
            {
                byte[] computedHmac = hmac.ComputeHash(ciphertext);
                if (!CompareByteArrays(computedHmac, receivedHmac))
                    throw new CryptographicException("Integrity check failed.");
            }

            // External authentication service integration (pseudo-code)
            bool isAuthenticated = AuthenticateUser(); 
            if (!isAuthenticated) 
                throw new UnauthorizedAccessException("User context verification failed.");

            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = key;
                aesAlg.IV = iv;
                aesAlg.Mode = CipherMode.CBC;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                byte[] plaintextBytes;
                using (var msDecrypt = new MemoryStream(ciphertext))
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        var buffer = new byte[ciphertext.Length];
                        int bytesRead = csDecrypt.Read(buffer, 0, buffer.Length);
                        plaintextBytes = new byte[bytesRead];

                        Array.Copy(buffer, plaintextBytes, bytesRead);

                        // Remove padding
                        int unpaddedLength = Unpad(plaintextBytes, aesAlg.BlockSize / 8);
                        if (unpaddedLength < 0)
                            throw new CryptographicException("Invalid padding detected.");

                        Array.Resize(ref plaintextBytes, unpaddedLength);
                    }
                }

                LogDecryptionSuccess();
                return plaintextBytes;
            }
        }
        catch (Exception ex)
        {
            LogDecryptionFailure(ex.Message);
            throw; // Rethrow to preserve the stack trace
        }
    }

    private static bool CompareByteArrays(byte[] array1, byte[] array2)
    {
        if (array1.Length != array2.Length) return false;
        for (int i = 0; i < array1.Length; i++)
        {
            if (array1[i] != array2[i]) return false;
        }
        return true;
    }

    private static int Unpad(byte[] data, int blockSize)
    {
        int paddingValue = data[^1];
        if (paddingValue > blockSize || paddingValue == 0) return -1;

        for (int i = 0; i < paddingValue; i++)
        {
            if (data[^1-i] != paddingValue) return -1;
        }

        return data.Length - paddingValue;
    }

    private static bool AuthenticateUser()
    {
        // Pseudo-code to integrate with an external authentication service
        // Consider caching user context or retries on transient failures.
        return true; // Assume authenticated for this example
    }

    private static void LogDecryptionSuccess()
    {
        lock (LockObject)
        {
            Console.WriteLine("Decryption successful.");
        }
    }

    private static void LogDecryptionFailure(string message)
    {
        lock (LockObject)
        {
            Console.WriteLine($"Decryption failed: {message}");
        }
    }
}
```

### Key Points:
- **Integrity Validation**: HMAC-SHA256 checks are performed to validate the integrity of the ciphertext.
- **Error Handling**: Throws exceptions with detailed messages for various failure scenarios.
- **Thread Safety**: Uses a lock around logging operations.
- **Memory Efficiency**: Proper use of `using` statements ensures resources are disposed correctly. Arrays are resized as needed.
- **Padding Removal**: Handles PKCS7 padding during decryption.
- **External Authentication**: Includes a stub to simulate authentication service interaction.
- **Logging**: Logs both successes and failures for auditing purposes.

Ensure proper integration with your external authentication services and adjust the logging mechanism according to your application's infrastructure.']

