public class DataProcessor
{
    private readonly ConcurrentDictionary<string, Func<Stream, byte[]>> _decompressionStrategies = new()
    {
        { ".gz", stream => GZipDecompress(stream) },
        { ".lz4", stream => Lz4Decompress(stream) }
    };

    public async Task<MyCustomDataStructure> LoadAndDeserializeAsync(string filePath)
    {
        try
        {
            // Ensure file is available, with retry logic for network failures.
            await WaitForFileAvailabilityAsync(filePath);

            var extension = Path.GetExtension(filePath).ToLowerInvariant();
            if (!_decompressionStrategies.TryGetValue(extension, out var decompressStrategy))
                throw new NotSupportedException($"Unsupported compression format: {extension}");

            using (var inputStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize: 8192, useAsync: true))
            {
                byte[] decompressedData;
                try
                {
                    decompressedData = await Task.Run(() => decompressStrategy(inputStream));
                }
                catch (Exception ex)
                {
                    HandleDecompressionError(ex);
                    return null;
                }

                return Deserialize<MyCustomDataStructure>(decompressedData);
            }
        }
        catch (Exception ex)
        {
            // Log and handle general errors.
            HandleGeneralError(ex);
            return null;
        }
    }

    private async Task WaitForFileAvailabilityAsync(string filePath)
    {
        while (!File.Exists(filePath))
        {
            await Task.Delay(100); // Wait before retrying
        }
    }

    private byte[] GZipDecompress(Stream inputStream)
    {
        using var decompressionStream = new GZipStream(inputStream, CompressionMode.Decompress);
        using var memoryStream = new MemoryStream();
        decompressionStream.CopyTo(memoryStream);
        return memoryStream.ToArray();
    }

    private byte[] Lz4Decompress(Stream inputStream)
    {
        using var memoryStream = new MemoryStream();
        var lz4Stream = LZ4Codec.Decode(inputStream, memoryStream, (int)inputStream.Length, leaveOpen: true);
        memoryStream.Position = 0;
        return memoryStream.ToArray();
