const Bluebird = require('bluebird');
const fs = require('fs-extra');
const axios = require('axios');
const winston = require('winston');

// Setup logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'memory_pool.log' })
  ]
});

class MemoryPool {
  constructor(size, valueRange) {
    this.size = size;
    this.valueRange = valueRange;
    this.pool = Array.from({ length: size }, () => Math.floor(Math.random() * valueRange));
    this.locks = new Array(size).fill(false);
  }

  acquire(index) {
    return Bluebird.resolve().then(() => {
      let acquired = false;
      while (!acquired) {
        if (!this.locks[index]) {
          this.locks[index] = true;
          acquired = true;
        }
      }
    });
  }

  release(index) {
    this.locks[index] = false;
  }

  updateValue(index, newValue) {
    return Bluebird.resolve().then(() => this.acquire(index))
      .then(() => {
        if (index < this.pool.length) {
          this.pool[index] = newValue;
        }
      })
      .finally(() => this.release(index));
  }

  logMetrics() {
    logger.info(`Memory Pool Size: ${this.size}, Usage: ${this.pool.filter(Boolean).length}`);
  }

  resize(newSize) {
    if (newSize > this.size) {
      const additionalSlots = Array.from({ length: newSize - this.size }, () => Math.floor(Math.random() * this.valueRange));
      this.pool.push(...additionalSlots);
      this.locks.push(...Array.from({ length: newSize - this.size }).fill(false));
      this.size = newSize;
    }
  }

  handleConcurrency(index, newValue) {
    return this.updateValue(index, newValue).catch(err => logger.error(`Error updating value at ${index}: ${err}`));
  }
}

async function uploadFilesFromUrls(urls, memoryPool) {
  const fileUploader = Bluebird.map(urls, async (url, index) => {
    try {
      await axios.get(url, { responseType: 'stream' });
      logger.info(`File uploaded successfully from URL: ${url}`);
    } catch (error) {
      logger.error(`Failed to upload file from URL ${url}: ${error.message}`);
    }
  }, { concurrency: 5 });

  const memoryOperations = Bluebird.map(urls, async (url, index) => {
    try {
      await axios.get(url);
      memoryPool.handleConcurrency(index % memoryPool.size, Math.floor(Math.random() * memoryPool.valueRange));
    } catch (error) {
      logger.error(`Failed to fetch data from URL ${url}: ${error.message}`);
    }
  }, { concurrency: 5 });

  await Bluebird.all([fileUploader, memoryOperations]);
}

// Example usage
const urls = [
  'https://example.com/file1.txt',
  'https://example.com/file2.jpg'
];

const memoryPool = new MemoryPool(10, 100);
uploadFilesFromUrls(urls, memoryPool).then(() => {
  memoryPool.logMetrics();
}).catch(err => logger.error(`Error in uploadFilesFromUrls: ${err.message}`));
