// commandExecutor.js

class CommandExecutor {
  constructor() {
    this.cache = new Map();
    this.apiBaseUrl = 'https://api.example.com/commands';
  }

  async fetchCommandMetadata(command) {
    try {
      const response = await fetch(`${this.apiBaseUrl}/${command}`);
      if (!response.ok) throw new Error('Failed to fetch command metadata');
      return await response.json();
    } catch (error) {
      console.error(`Error fetching command metadata: ${error.message}`);
      return null;
    }
  }

  async executeCommand(command, args = []) {
    const cacheKey = `${command}:${args.join(',')}`;

    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    try {
      const execPromise = new Promise((resolve, reject) => {
        const childProcess = require('child_process');

        childProcess.exec(`${command} ${args.join(' ')}`, (error, stdout, stderr) => {
          if (error || stderr) {
            return reject(new Error(stderr || error.message));
          }
          resolve(stdout);
        });
      });

      const result = await execPromise;
      this.cache.set(cacheKey, result);

      // Optional: Implement cache size limit
      if (this.cache.size > 100) { // Example limit
        const firstKey = this.cache.keys().next().value;
        this.cache.delete(firstKey);
      }

      return result;
    } catch (error) {
      console.error(`Error executing command "${command}": ${error.message}`);
      throw error; // Re-throw to allow graceful degradation at the calling site
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = CommandExecutor;

// Usage example in an entry file (e.g., app.js)

const CommandExecutor = require('./commandExecutor');

async function main() {
  const executor = new CommandExecutor();

  try {
    const metadata = await executor.fetchCommandMetadata('ls');
    console.log(metadata);

    const result = await executor.executeCommand('ls', ['-l']);
    console.log(result);
  } catch (error) {
    console.error('An error occurred:', error.message);
  }
}

main();
```

