// Function to create directory and perform other tasks
async fn setup_directory(dir_name: &str) -> io::Result<()> {
    // Ensure the directory name is valid
    if dir_name.is_empty() || dir_name.contains('/') {
        error!("Invalid directory name.");
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Malformed directory name"));
    }

    let path = PathBuf::from(dir_name);

    // Create the directory atomically to handle race conditions
    if let Err(e) = fs::create_dir_all(&path).await {
        error!("Failed to create directory: {}", e);
        return Err(e);
    }

    // Set environment variable only if not already set
    let env_var_name = format!("DIR_{}", dir_name.replace("/", "_"));
    if env::var(env_var_name.clone()).is_err() {
        env::set_var(&env_var_name, path.to_str().unwrap_or_default());
    }

    // Check for existence of 'status.txt'
    let status_file_path = path.join("status.txt");
    if !status_file_path.exists() {
        let mut file = File::create(&status_file_path).await?;
        writeln!(file, "{}", Local::now()).await?;
