// Hash table size and load factor threshold for resizing
#define INITIAL_HASH_SIZE 101
#define LOAD_FACTOR_THRESHOLD 0.75

// Node for the hash table to handle collisions using chaining
typedef struct node {
    int key;
    long offset;
    struct node* next;
} node;

// Hash table structure
typedef struct {
    node** buckets;
    size_t capacity;
    size_t size;
} hashtable;

// Function prototypes
unsigned long hash_function(int key, size_t capacity);
hashtable* create_hashtable(size_t initial_capacity);
void free_hashtable(hashtable* ht);
int insert_to_hash(hashtable* ht, int key, long offset);
long lookup_offset(hashtable* ht, int key);
void resize_records_array(record** records, size_t current_size, size_t new_size);

// Main function to manage memory and hash table
void manage_memory_and_hash_table(int range_min, int range_max) {
    // Initial setup
    hashtable* ht = create_hashtable(INITIAL_HASH_SIZE);
    if (!ht) {
        fprintf(stderr, "Failed to initialize hash table\n");
        return;
    }

    size_t records_size = 10; // Initial size for the records array
    record* records = (record*)malloc(records_size * sizeof(record));
    if (!records) {
        free_hashtable(ht);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    long* offsets = NULL;
    int* keys = NULL;

    // Example operations: Insert some values
    size_t num_inserts = 20; // Number of entries to insert

    for (size_t i = 0; i < num_inserts; ++i) {
        if ((double)ht->size / ht->capacity >= LOAD_FACTOR_THRESHOLD) {
            // Resize the hash table
            hashtable* new_ht = create_hashtable(ht->capacity * 2);
            if (!new_ht) {
                fprintf(stderr, "Failed to resize hash table\n");
                free(records);
                free_hashtable(ht);
                return;
            }

            // Rehash existing elements into the new hash table
            for (size_t j = 0; j < ht->capacity; ++j) {
                node* current = ht->buckets[j];
                while (current != NULL) {
                    insert_to_hash(new_ht, current->key, current->offset);
                    node* temp = current;
                    current = current->next;
                    free(temp);
                }
            }

            // Free old hash table
            free(ht->buckets);
            *ht = *new_ht;  // Update old hash table pointer to new one
        }

        int key = rand() % num_inserts;
        long offset = i;
        if (!insert_to_hash(ht, key, offset)) {
            fprintf(stderr, "Failed to insert into hash table\n");
            free(records);
            free_hashtable(ht);
            return;
        }

        // Resize records array if necessary
        if (i >= records_size) {
            size_t new_records_size = i + 10;  // Increase by some factor
            resize_records_array(&records, records_size, new_records_size);
            records_size = new_records_size;

            offsets = realloc(offsets, records_size * sizeof(long));
            keys = realloc(keys, records_size * sizeof(int));

            if (!offsets || !keys) {
                fprintf(stderr, "Failed to reallocate memory\n");
                free(records);
                free_hashtable(ht);
                return;
            }
        }

        // Set record values
        records[i].value = range_min + rand() % (range_max - range_min + 1);

        offsets[i] = offset;
        keys[i] = key;
    }

    // Example lookup
    int search_key = 5;  // Some example key to look up
    long found_offset = lookup_offset(ht, search_key);
    printf("Offset for key %d: %ld\n", search_key, found_offset);

    // Cleanup
    free(offsets);
    free(keys);
    free(records);
    free_hashtable(ht);
}

// Hash function implementation
unsigned long hash_function(int key, size_t capacity) {
    return (key * 2654435761U) % capacity;
}

// Create a new hash table
hashtable* create_hashtable(size_t initial_capacity) {
    hashtable* ht = (hashtable*)malloc(sizeof(hashtable));
    if (!ht) return NULL;

    ht->buckets = (node**)calloc(initial_capacity, sizeof(node*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    ht->capacity = initial_capacity;
    ht->size = 0;
    return ht;
}

// Free hash table resources
void free_hashtable(hashtable* ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        node* current = ht->buckets[i];
        while (current != NULL) {
            node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(ht->buckets);
    free(ht);
}

// Insert key and offset into hash table
int insert_to_hash(hashtable* ht, int key, long offset) {
    unsigned long index = hash_function(key, ht->capacity);
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return 0;

    new_node->key = key;
    new_node->offset = offset;
    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
    ++ht->size;
    return 1;
}

// Lookup offset for a given key in hash table
long lookup_offset(hashtable* ht, int key) {
    unsigned long index = hash_function(key, ht->capacity);
    node* current = ht->buckets[index];

    while (current != NULL) {
        if (current->key == key) return current->offset;
        current = current->next;
    }
    return -1;  // Key not found
}

// Resize the records array to a new size
void resize_records_array(record** records, size_t current_size, size_t new_size) {
    record* temp = (record*)realloc(*records, new_size * sizeof(record));
    if (!temp) return;

    for (size_t i = current_size; i < new_size; ++i) {
        temp[i].value = 0;  // Initialize new elements
    }
    *records = temp;
}
