} ContextList;

ContextList context_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize a new UEContext
void init_ue_context(UEContext *ue_context, int ue_id) {
    ue_context->UE_ID = ue_id;
    ue_context->rlc_pdus = NULL;
    ue_context->rlc_pdu_count = 0;
    ue_context->drb_configs = NULL;
    ue_context->drb_config_count = 0;
}

// Function to add a new UEContext or update an existing one
int add_or_update_ue_context(int ue_id, RLC_PDU *new_pdus, size_t pdu_count,
                             DRBConfig **new_drbs, size_t drb_count) {
    pthread_mutex_lock(&context_list.lock);

    // Check if UEContext already exists and update it
    for (size_t i = 0; i < context_list.count; ++i) {
        if (context_list.entries[i]->UE_ID == ue_id) {
            free(context_list.entries[i]->rlc_pdus);
            context_list.entries[i]->rlc_pdus = malloc(pdu_count * sizeof(RLC_PDU));
            memcpy(context_list.entries[i]->rlc_pdus, new_pdus, pdu_count * sizeof(RLC_PDU));
            context_list.entries[i]->rlc_pdu_count = pdu_count;

            free(context_list.entries[i]->drb_configs);
            context_list.entries[i]->drb_configs = malloc(drb_count * sizeof(DRBConfig*));
            memcpy(context_list.entries[i]->drb_configs, new_drbs, drb_count * sizeof(DRBConfig*));
            context_list.entries[i]->drb_config_count = drb_count;

            pthread_mutex_unlock(&context_list.lock);
            return 0; // Updated successfully
        }
    }

    // Create a new UEContext if not found
    UEContext *new_ue_context = malloc(sizeof(UEContext));
    init_ue_context(new_ue_context, ue_id);

    new_ue_context->rlc_pdus = malloc(pdu_count * sizeof(RLC_PDU));
    memcpy(new_ue_context->rlc_pdus, new_pdus, pdu_count * sizeof(RLC_PDU));
    new_ue_context->rlc_pdu_count = pdu_count;

    new_ue_context->drb_configs = malloc(drb_count * sizeof(DRBConfig*));
    memcpy(new_ue_context->drb_configs, new_drbs, drb_count * sizeof(DRBConfig*));
    new_ue_context->drb_config_count = drb_count;

    context_list.entries = realloc(context_list.entries, (context_list.count + 1) * sizeof(UEContext*));
    context_list.entries[context_list.count++] = new_ue_context;

    pthread_mutex_unlock(&context_list.lock);
    return 0; // Added successfully
}

// Function to retrieve a UEContext by UE_ID
UEContext *get_ue_context(int ue_id) {
    pthread_mutex_lock(&context_list.lock);

    for (size_t i = 0; i < context_list.count; ++i) {
        if (context_list.entries[i]->UE_ID == ue_id) {
            pthread_mutex_unlock(&context_list.lock);
            return context_list.entries[i];
        }
    }

    pthread_mutex_unlock(&context_list.lock);
    return NULL;
}

// Cleanup function to free allocated resources
void cleanup_context_list() {
    pthread_mutex_lock(&context_list.lock);

    for (size_t i = 0; i < context_list.count; ++i) {
        if (context_list.entries[i]->rlc_pdus) {
            free(context_list.entries[i]->rlc_pdus);
        }
        if (context_list.entries[i]->drb_configs) {
            for (size_t j = 0; j < context_list.entries[i]->drb_config_count; ++j) {
                free(context_list.entries[i]->drb_configs[j]);
            }
            free(context_list.entries[i]->drb_configs);
        }
        free(context_list.entries[i]);
    }

    free(context_list.entries);
    context_list.entries = NULL;
    context_list.count = 0;

    pthread_mutex_unlock(&context_list.lock);
}

// Add more functions as needed for failover, persistence integration, etc.

int main() {
    // Example usage of the functions
    int ue_id = 1;
    RLC_PDU pdus[2] = {{.segment_id = 101}, {.segment_id = 102}};
    DRBConfig drbs[1] = { .drb_id = 201 };

    add_or_update_ue_context(ue_id, pdus, 2, (DRBConfig*[]){&drbs[0]}, 1);

    UEContext *context = get_ue_context(ue_id);
    if (context) {
        log_message(LOG_INFO, "Retrieved context successfully.");
    }

    cleanup_context_list();

    return 0;
}
```

### Design Choices and Instructions:

- **Thread Safety**: Used `pthread_mutex_t` to ensure thread safety when accessing/modifying the global `ContextList`. This helps prevent data races in a multi-threaded environment.

- **Data Structures**: The list of `UEContexts` is dynamically managed using an array that grows as needed, balancing memory usage and access speed. This approach is simple but effective for moderate loads.

- **Logging System**: A modular logging system with configurable log levels (`DEBUG`, `INFO`, `WARN`, `ERROR`) allows for flexible debugging and monitoring across different environments.

- **Failover & Persistence**: The code structure supports integration of failover mechanisms and external persistence, though specific implementations would depend on the environment and are left as future enhancements.

- **Backward Compatibility**: The design can accommodate changes in `UEContext` by adjusting internal structures without affecting the overall management logic. Any updates should include version checks or migration paths within existing functions.

For extending functionality (e.g., integration with external stores, failover), consider implementing additional helper functions and ensuring proper synchronization mechanisms are in place to maintain consistency and performance.']

