// C Code: Memory Management for Records

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

#define INITIAL_CAPACITY 10
#define LOGGING_ENABLED 1 // Set to 0 to disable logging

typedef struct {
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordPool;

void log(const char *message) {
    if (LOGGING_ENABLED) {
        printf("%s\n", message);
    }
}

RecordPool* create_record_pool() {
    RecordPool *pool = malloc(sizeof(RecordPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for record pool.\n");
        exit(EXIT_FAILURE);
    }

    pool->records = malloc(INITIAL_CAPACITY * sizeof(Record));
    if (!pool->records) {
        fprintf(stderr, "Failed to allocate initial memory block.\n");
        free(pool);
        exit(EXIT_FAILURE);
    }

    pool->capacity = INITIAL_CAPACITY;
    pool->count = 0;

    pthread_mutex_init(&pool->lock, NULL);

    log("Record pool created.");
    return pool;
}

void resize_record_pool(RecordPool *pool) {
    size_t new_capacity = pool->capacity * 2;
    Record *new_records = realloc(pool->records, new_capacity * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Failed to reallocate memory block.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&pool->lock);
    pool->records = new_records;
    pool->capacity = new_capacity;
    pthread_mutex_unlock(&pool->lock);

    log("Record pool resized.");
}

void add_record(RecordPool *pool, int value) {
    if (!pool) {
        fprintf(stderr, "Invalid record pool.\n");
        return;
    }

    if (pool->count >= pool->capacity) {
        resize_record_pool(pool);
    }

    pthread_mutex_lock(&pool->lock);
    pool->records[pool->count].value = value;
    pool->count++;
    pthread_mutex_unlock(&pool->lock);

    log("Record added.");
}

void free_record_pool(RecordPool *pool) {
    if (pool) {
        free(pool->records);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
        log("Record pool destroyed.");
    }
}
