// Define namespace for RandomNumberGenerator
namespace RNG {
    class RandomNumberGenerator {
    public:
        // Constructor initializes the Mersenne Twister engine
        RandomNumberGenerator() : rng(std::random_device{}()) {}

        // Destructor (trivial)
        ~RandomNumberGenerator() = default;

        // Static member variable for thread safety
        static std::mutex mtx;

        // Generate random number in a given range [min, max]
        int generate(int min, int max) {
            std::lock_guard<std::mutex> lock(mtx);
            std::uniform_int_distribution<> dist(min, max);
            return dist(rng);
        }

    private:
        std::mt19937 rng; // Mersenne Twister engine
    };

    std::mutex RandomNumberGenerator::mtx;
}

// Logging mechanism
class DNSLogger {
public:
    static bool loggingEnabled;

    static void log(const std::string& message) {
        if (loggingEnabled) {
            std::lock_guard<std::mutex> lock(logMtx);
            std::cout << "[DNS Logger] " << message << std::endl;
        }
    }

private:
    static std::mutex logMtx;
};

bool DNSLogger::loggingEnabled = true;
std::mutex DNSLogger::logMtx;

// DNS resolution function
int resolveDNS(const char* hostname, u_char* ipBuffer) {
    struct addrinfo hints{}, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only

    if ((status = getaddrinfo(hostname, nullptr, &hints, &res)) != 0) {
        DNSLogger::log("DNS resolution error: " + std::string(gai_strerror(status)));
        return status;
    }

    struct sockaddr_in* addr = (struct sockaddr_in*) res->ai_addr;
    inet_ntop(AF_INET, &(addr->sin_addr), (char*)ipBuffer, INET_ADDRSTRLEN);

    freeaddrinfo(res);
    DNSLogger::log("DNS resolution success for " + std::string(hostname) + ": " + (char*)ipBuffer);
    return 0; // Success
}

// Main function demonstrating the use of both functionalities
int main() {
    // Initialize RandomNumberGenerator and generate a random number
    RNG::RandomNumberGenerator rng;
    int randomNumber = rng.generate(1, 100);
    std::cout << "Generated random number: " << randomNumber << std::endl;

    // Perform DNS resolution
    u_char ipBuffer[INET_ADDRSTRLEN];
    const char* hostname = "example.com";

    if (resolveDNS(hostname, ipBuffer) == 0) {
        std::cout << "Resolved IP for " << hostname << ": " << (char*)ipBuffer << std::endl;
    } else {
        std::cerr << "Failed to resolve DNS for " << hostname << std::endl;
    }

    return 0;
}
