#include "bzlib.h"

typedef enum {
    ALGORITHM_ZLIB,
    ALGORITHM_LZMA,
    ALGORITHM_BZIP2,
} CompressionAlgorithm;

typedef struct {
    void *stream;
    size_t buffer_size;
    char *buffer;
    int algorithm;
    int level;
    unsigned long dictionary_size;
    void (*progress_callback)(int progress);
} CompressionContext;

// Initialize compression context
CompressionContext* init_compression_context(CompressionAlgorithm algo, int level, unsigned long dict_size, void (*callback)(int)) {
    CompressionContext *ctx = malloc(sizeof(CompressionContext));
    if (!ctx) return NULL;

    ctx->algorithm = algo;
    ctx->level = level;
    ctx->dictionary_size = dict_size;
    ctx->progress_callback = callback;

    switch (algo) {
        case ALGORITHM_ZLIB:
            ctx->stream = malloc(sizeof(z_stream));
            if (ctx->stream) {
                memset(ctx->stream, 0, sizeof(z_stream));
                if (deflateInit2((z_stream *)ctx->stream, level, Z_DEFLATED, 
                                dict_size ? MAX_WBITS + 16 : MAX_WBITS, DEF_MEM_LEVEL, Z_DEFAULT_STRATEGY)) {
                    free(ctx->stream);
                    ctx->stream = NULL;
                }
            }
            break;

        case ALGORITHM_LZMA:
            // Placeholder for LZMA initialization
            break;

        case ALGORITHM_BZIP2:
            ctx->buffer_size = dict_size ? dict_size : 1 << 24; // Default buffer size if no dictionary size provided
            ctx->buffer = malloc(ctx->buffer_size);
            if (!ctx->buffer) {
                free(ctx);
                return NULL;
            }
            BZFILE *bz_stream = BZ2_bzWriteOpen(&ctx, stdout, ctx->level, 0, 0, NULL);
            break;

        default:
            free(ctx);
            return NULL;
    }

    return ctx;
}

// Function to compress data
size_t compress_data(CompressionContext *ctx, const char *input, size_t input_size) {
    if (!ctx || !input || !input_size) return 0;

    switch (ctx->algorithm) {
        case ALGORITHM_ZLIB: {
            z_stream *zstream = (z_stream *)ctx->stream;
            zstream->next_in = (unsigned char*)input;
            zstream->avail_in = input_size;

            // Allocate buffer for compressed data
            size_t out_buffer_size = compressBound(input_size);
            ctx->buffer = malloc(out_buffer_size);
            if (!ctx->buffer) return 0;

            zstream->next_out = (unsigned char*)ctx->buffer;
            zstream->avail_out = out_buffer_size;

            int ret = deflate(zstream, Z_FINISH);
            size_t compressed_size = out_buffer_size - zstream->avail_out;

            if (ret != Z_STREAM_END) {
                free(ctx->buffer);
                return 0;
            }

            // Callback for progress
            if (ctx->progress_callback) ctx->progress_callback(100);

            deflateEnd(zstream);
            break;
        }

        case ALGORITHM_LZMA:
            // Placeholder for LZMA compression code
            break;

        case ALGORITHM_BZIP2: {
            BZFILE *bz_stream = (BZFILE*)ctx->stream;
            size_t compressed_size = 0;

            while (compressed_size < input_size) {
                size_t bytes_written = BZ2_bzWrite(&ctx, bz_stream, input + compressed_size, input_size - compressed_size);
                if (bytes_written == 0) break; // Error or EOF
                compressed_size += bytes_written;

                // Progress callback every 10%
                int progress = (int)((compressed_size * 100) / input_size);
                if (ctx->progress_callback && progress % 10 == 0)
                    ctx->progress_callback(progress);
            }

            BZ2_bzWriteClose(&ctx, bz_stream, 0, NULL, NULL);
            break;
        }
    }

    return input_size; // Return compressed size
}

// Clean up compression context
void free_compression_context(CompressionContext *ctx) {
    if (!ctx) return;

    switch (ctx->algorithm) {
        case ALGORITHM_ZLIB:
            if (ctx->stream) deflateEnd((z_stream *)ctx->stream);
            break;

        case ALGORITHM_LZMA:
            // Placeholder for LZMA cleanup
            break;

        case ALGORITHM_BZIP2:
            BZ2_bzWriteClose(&ctx, (BZFILE*)ctx->stream, 0, NULL, NULL);
            break;
    }

    free(ctx->buffer);
    free(ctx->stream);
    free(ctx);
}

// Example of a progress callback function
void example_progress_callback(int progress) {
    printf("Compression Progress: %d%%\n", progress);
}
