import os
import sys
from git import Repo, GitCommandError
from subprocess import run, CalledProcessError
import paramiko
from time import sleep

def clone_repository(repo_url, branch, dest_path):
    try:
        repo = Repo.clone_from(repo_url, dest_path, branch=branch)
        return repo
    except GitCommandError as e:
        print(f"Git error: {e}")
        sys.exit(1)

def modify_config_files(config_data, dest_path):
    for filename, settings in config_data.items():
        file_path = os.path.join(dest_path, filename)
        with open(file_path, 'r+') as f:
            content = f.read()
            for key, value in settings.items():
                content = content.replace(f'{{{{{key}}}}}', value)
            f.seek(0)
            f.write(content)
            f.truncate()

def install_dependencies(package_list):
    try:
        run(['pip', 'install'] + package_list, check=True)
    except CalledProcessError as e:
        print(f"Installation error: {e}")
        sys.exit(1)

def deploy_to_server(server_info, repo_path, remote_user, remote_host, remote_dir):
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    try:
        ssh.connect(remote_host, username=remote_user)
        sftp = ssh.open_sftp()

        # Upload the modified repository to the server
        for root, dirs, files in os.walk(repo_path):
            remote_root = os.path.join(remote_dir, os.path.relpath(root, repo_path))
            try:
                sftp.mkdir(remote_root)
            except IOError:
                pass  # Directory already exists
            for file in files:
                local_file = os.path.join(root, file)
                remote_file = os.path.join(remote_root, file)
                sftp.put(local_file, remote_file)

        # Execute the installation commands on the server
        command = "cd {}; python setup.py install".format(remote_dir)
        stdin, stdout, stderr = ssh.exec_command(command)
        if stdout.channel.recv_exit_status() != 0:
            raise Exception(stderr.read().decode())

    except (paramiko.SSHException, IOError) as e:
        print(f"SSH error: {e}")
        sys.exit(1)
    finally:
        sftp.close()
        ssh.close()

def commit_and_push_changes(repo_path):
    repo = Repo(repo_path)
    try:
        repo.git.add(update=True)
        repo.index.commit("Automated deployment changes")

        origin = repo.remote(name='origin')
        origin.push()
    except GitCommandError as e:
        print(f"Git push error: {e}")
        sys.exit(1)

def rollback_changes(repo_path):
    repo = Repo(repo_path)
    try:
        repo.git.reset('--hard', 'HEAD~1')
        commit_hash = 'HEAD~1'

        origin = repo.remote(name='origin')
        origin.push(refspec=f'{commit_hash}:refs/heads/{repo.active_branch}')
    except GitCommandError as e:
        print(f"Rollback error: {e}")
        sys.exit(1)

def deploy(config):
    for env, settings in config.items():
        try:
            repo_url = settings['repo_url']
            branch = settings.get('branch', 'main')
            dest_path = f"/tmp/{env}"
            package_list = settings['dependencies']
            server_info = settings['server']

            # Clone the repository
            if os.path.exists(dest_path):
                run(['rm', '-rf', dest_path])
            repo = clone_repository(repo_url, branch, dest_path)

            # Modify configuration files with environment-specific settings
            modify_config_files(settings['config'], dest_path)

            # Install dependencies
            install_dependencies(package_list)

            # Deploy to server
            deploy_to_server(server_info, dest_path, **settings['server_credentials'])

            # Commit changes and push back to remote repository
            commit_and_push_changes(dest_path)

        except Exception as e:
            print(f"Deployment error for {env}: {e}")

            rollback_changes(dest_path)

            # Optionally wait before retrying or moving on to the next environment
            sleep(5)

if __name__ == "__main__":
    config = {
        'development': {
            'repo_url': 'https://github.com/your/repo.git',
            'dependencies': ['requests', 'flask'],
            'config': {'DATABASE_URL': 'sqlite:///dev.db'},
            'server': {
                'host': 'dev.example.com',
                'dir': '/var/www/dev_app'
            },
            'server_credentials': {
                'user': 'deploy_user',
                'password': 'secure_password'
            }
        },
        # Add other environments similarly
    }

    deploy(config)
```

