#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SIZE 1000
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int value;
} record;

int allocate_and_initialize(int num_offsets, int num_keys, int num_records) {
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0)
        return -1; // Invalid input size

    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Memory allocation failed
    }

    srand((unsigned int)time(NULL));
    for (int i = 0; i < num_offsets; ++i)
        offsets[i] = rand() % MAX_SIZE;

    for (int j = 0; j < num_keys; ++j)
        keys[j] = rand() % MAX_SIZE;

    for (int k = 0; k < num_records; ++k) {
        records[k].value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
    }

    // Asynchronous execution simulation
    pthread_t async_thread;
    void *async_result = NULL;
    if (pthread_create(&async_thread, NULL, []() -> void* {
        printf("Asynchronous task running...\n");
        sleep(2); // Simulate time-consuming task
        printf("Asynchronous task completed.\n");
        return NULL;
    }, NULL)) != 0) {
        free(offsets);
        free(keys);
        free(records);
        return -3; // Failed to create async thread
    }

    pthread_join(async_thread, &async_result);

    free(offsets);
    free(keys);
    free(records);

    return 1; // Success
}

int main() {
    int result = allocate_and_initialize(10, 5, 20);
    if (result == 1)
        printf("All operations successful.\n");
    else
        printf("An error occurred. Code: %d\n", result);
    return 0;
}
