#include <iostream>
#include <vector>
#include <unordered_set>
#include <unordered_map>
#include <random>
#include <thread>
#include <chrono>

// Node structure
struct Node {
    long offset;
    int key;
    Node* nextNode;

    Node(long o, int k) : offset(o), key(k), nextNode(nullptr) {}
};

class DistributedNodeManager {
public:
    void initializeNetwork(int seed, int range, size_t nodeCount);
    void traverseAndConnect();
    void checkHealth();
    void printMetrics();

private:
    std::vector<Node*> nodes;
    std::unordered_set<int> keys; // To ensure unique keys
    int successfulConnections = 0;
    int failedAttempts = 0;
    int processingErrors = 0;

    void fetchInitialConfig(Node* node);
    bool establishConnection(Node* from, Node* to);

    static const int RETRY_LIMIT = 3;
};

void DistributedNodeManager::initializeNetwork(int seed, int range, size_t nodeCount) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> keyDist(0, range);
    std::uniform_int_distribution<> offsetDist(-100000, 100000);

    for (size_t i = 0; i < nodeCount; ++i) {
        int key;
        do {
            key = keyDist(gen);
        } while (!keys.insert(key).second); // Ensure unique keys

        Node* newNode = new Node(offsetDist(gen), key);
        nodes.push_back(newNode);

        fetchInitialConfig(newNode);
    }
}

void DistributedNodeManager::traverseAndConnect() {
    for (auto& node : nodes) {
        std::vector<Node*> potentialConnections;
        for (auto& other : nodes) {
            if (other != node && !keys.count(other->key)) {
                potentialConnections.push_back(other);
            }
        }

        for (auto candidate : potentialConnections) {
            if (establishConnection(node, candidate)) {
                successfulConnections++;
            } else {
                failedAttempts++;
            }
        }
    }
}

bool DistributedNodeManager::establishConnection(Node* from, Node* to) {
    int retry = 0;
    while (retry < RETRY_LIMIT) {
        try {
            if (!from->nextNode && !to->nextNode) {
                from->nextNode = to;
                to->nextNode = from;
                return true;
            }
            break; // Exit on successful connection
        } catch (...) {
            retry++;
        }
    }

    processingErrors++;
    return false;
}

void DistributedNodeManager::fetchInitialConfig(Node* node) {
    try {
        // Simulate metadata fetching
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    } catch (...) {
        processingErrors++;
    }
}

void DistributedNodeManager::checkHealth() {
    for (auto& node : nodes) {
        if (!node->nextNode) {
            failedAttempts++; // Report disconnected nodes
        }
    }
}

void DistributedNodeManager::printMetrics() {
    std::cout << "Successful Connections: " << successfulConnections << "\n";
    std::cout << "Failed Attempts: " << failedAttempts << "\n";
    std::cout << "Processing Errors: " << processingErrors << "\n";
}

int main() {
    DistributedNodeManager manager;
    manager.initializeNetwork(42, 1000, 100);
    manager.traverseAndConnect();
    manager.checkHealth();

    // Periodically check health and print metrics
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(10));
        manager.checkHealth();
        manager.printMetrics();
    }

    return 0;
}
```

### Key Points:
- **Node Initialization**: Nodes are initialized with a unique key and random offset.
- **Connection Establishment**: Ensures no self-loops or duplicate connections.
- **Retry Logic**: Handles connection retries gracefully.
- **Health Check**: Periodically checks network health.
- **Metrics Reporting**: Provides detailed metrics on network operations.

This code is designed to be modular, allowing for easy maintenance and future enhancements.']

