<?php

// PHP Component: Secure Random String Generation and Password Hashing

use Psr\Log\LoggerInterface;

require 'vendor/autoload.php'; // Assuming you use Composer for dependency management.

function createRandomStringGenerator(LoggerInterface $logger): callable {
    return function (int $length = 16) use ($logger) {
        try {
            $charset = getenv('CHARSET') ?: 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
            if (!$charset || strlen($charset) === 0) {
                throw new \InvalidArgumentException("Charset environment variable is not set or empty.");
            }

            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $randomString .= $charset[random_int(0, strlen($charset) - 1)];
            }

            return $randomString;
        } catch (\Exception $e) {
            $logger->error('Failed to generate random string: ' . $e->getMessage());
            throw new \RuntimeException('Random string generation failed.');
        }
    };
}

function createPasswordHasher(LoggerInterface $logger): callable {
    return function ($password, $algo = PASSWORD_DEFAULT) use ($logger) {
        try {
            if (!defined($algo)) {
                throw new \InvalidArgumentException("Unsupported hashing algorithm: $algo.");
            }

            return password_hash($password, $algo);
        } catch (\Exception $e) {
            $logger->error('Failed to hash password: ' . $e->getMessage());
            throw new \RuntimeException('Password hashing failed.');
        }
    };
}

