async function processOAuthRequest(oauthRequest, ipAddr) {
  try {
    const { provider, environment } = oauthRequest;

    // Rate limiting check
    await rateLimiter.consume(ipAddr);

    // Logging request patterns (non-blocking)
    logRequestPatterns({ provider, environment });

    // Cache key for secure storage endpoint
    const cacheKeyEndpoint = `${provider}-${environment}`;
    let secureStorageEndpoint = endpointCache.get(cacheKeyEndpoint);

    if (!secureStorageEndpoint) {
      secureStorageEndpoint = await resolveSecureStorageEndpoint(provider, environment);
      endpointCache.set(cacheKeyEndpoint, secureStorageEndpoint);
    }

    // Cache key for certificate
    const cacheKeyCert = `${provider}-${environment}-cert`;
    let certPEM = certificateCache.get(cacheKeyCert);

    if (!certPEM) {
      certPEM = await fetchCertificateFromSecureStorage(secureStorageEndpoint);
      certificateCache.set(cacheKeyCert, certPEM);
    }

    return certPEM;
  } catch (error) {
