}

void add_transaction(MemoryPool *pool, Transaction **transactions, int *transaction_count, double min_val, double max_val) {
    pthread_mutex_lock(&pool->lock);

    if (*transaction_count >= pool->pool_size / sizeof(Transaction)) {
