['Below is an implementation of the described functionality. This code assumes you have a basic understanding of C, threading, mutexes, and file I/O.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define CONFIG_FILE_MAX_SIZE 1024

typedef struct {
    int key;
    int value;
} record;

typedef struct {
    size_t pool_size;
    size_t max_records;
    int value_min;
    int value_max;
    size_t resize_threshold;
    void *memory_pool;
    pthread_mutex_t lock;
} memory_pool_config;

typedef struct {
    record *records;
    size_t capacity;
    size_t count;
    memory_pool_config config;
} record_array;

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

int read_config(const char *filename, memory_pool_config *config) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    char line[CONFIG_FILE_MAX_SIZE];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "pool_size=%zu", &config->pool_size) == 1) continue;
        if (sscanf(line, "max_records=%zu", &config->max_records) == 1) continue;
        if (sscanf(line, "value_min=%d", &config->value_min) == 1) continue;
        if (sscanf(line, "value_max=%d", &config->value_max) == 1) continue;
        if (sscanf(line, "resize_threshold=%zu", &config->resize_threshold) == 1) continue;
    }

    fclose(file);
    return 0;
}

void *allocate_memory_pool(memory_pool_config *config) {
    void *memory = malloc(config->pool_size);
    if (!memory) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&config->lock, NULL);
    config->memory_pool = memory;
    return memory;
}

void log_operation(const char *operation, int key) {
    FILE *log_file = fopen("operations.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s - Key: %d\n", ctime(&now), operation, key);
        fclose(log_file);
    }
}

void add_record(record_array *arr, int key, int value) {
    pthread_mutex_lock(&arr->config.lock);

    if (arr->count >= arr->capacity) {
        size_t new_capacity = arr->capacity == 0 ? 10 : arr->capacity * 2;
        if (new_capacity > arr->config.max_records) {
            new_capacity = arr->config.max_records;
        }

        record *temp = realloc(arr->records, new_capacity * sizeof(record));
        if (!temp) {
            perror("Failed to resize records array");
            exit(EXIT_FAILURE);
        }

        arr->records = temp;
        arr->capacity = new_capacity;
    }

    arr->records[arr->count].key = key;
    arr->records[arr->count].value = value;
    arr->count++;

    log_operation("ALLOCATED", key);

    pthread_mutex_unlock(&arr->config.lock);
}

void free_memory_pool(record_array *arr) {
    pthread_mutex_lock(&arr->config.lock);

    for (size_t i = 0; i < arr->count; ++i) {
        log_operation("DEALLOCATED", arr->records[i].key);
    }

    if (arr->records) {
        free(arr->records);
    }

    if (arr->config.memory_pool) {
        free(arr->config.memory_pool);
    }

    pthread_mutex_unlock(&arr->config.lock);

    pthread_mutex_destroy(&arr->config.lock);
}

record_array *initialize_record_array(const char *config_filename) {
    memory_pool_config config;
    record_array *arr = malloc(sizeof(record_array));

    if (read_config(config_filename, &config) != 0) {
        fprintf(stderr, "Failed to read configuration file\n");
        free(arr);
        return NULL;
    }

    allocate_memory_pool(&config);

    arr->records = NULL;
    arr->capacity = 0;
    arr->count = 0;
    arr->config = config;

    return arr;
}

void generate_records(record_array *arr) {
    srand(time(NULL));

    for (size_t i = 0; i < arr->config.max_records; ++i) {
        int key = rand();
        int value = rand() % (arr->config.value_max - arr->config.value_min + 1) + arr->config.value_min;

        add_record(arr, key, value);
    }
}

void destroy_record_array(record_array *arr) {
    if (!arr) return;

    free_memory_pool(arr);

    pthread_mutex_destroy(&global_lock);

    free(arr);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    record_array *arr = initialize_record_array(argv[1]);

    if (!arr) {
        return EXIT_FAILURE;
    }

    generate_records(arr);

    destroy_record_array(arr);

    return 0;
}
```

### Explanation of Key Components:
- **Configuration File**: The configuration parameters are read from a specified file.
- **Memory Pool**: A single memory pool is allocated for records, initialized with settings from the config file.
- **Mutex Locking**: Ensures thread safety when accessing or modifying shared resources such as the `record` array.
- **Dynamic Resizing**: The `add_record` function manages dynamic resizing of the `records` array to accommodate new entries and minimize fragmentation.
- **Logging**: Logs allocation and deallocation operations with timestamps. This log file helps track operations without affecting performance too much, though it's written synchronously.
- **Concurrent Access**: Thread safety is ensured via mutex locking.

This implementation aims for a balance between efficiency, memory management, and concurrency, following the requirements stated in your task description.']

