#include <errno.h>

#define POOL_SIZE 1024 * 64 // Define a size for the memory pool

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct MemoryPool {
    char* pool;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool mp = { .pool = NULL, .used = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void init_memory_pool(size_t size) {
    mp.pool = malloc(size);
    if (!mp.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&mp.lock);
    mp.used = 0;
    pthread_mutex_unlock(&mp.lock);
}

void* alloc_record(void) {
    pthread_mutex_lock(&mp.lock);
    if (mp.used + sizeof(Record) > POOL_SIZE) {
        pthread_mutex_unlock(&mp.lock);
        return NULL; // Memory pool exhausted
    }
    void* record = mp.pool + mp.used;
    mp.used += sizeof(Record);
    pthread_mutex_unlock(&mp.lock);
    return record;
}

void free_memory_pool() {
    free(mp.pool);
    mp.pool = NULL;
    pthread_mutex_lock(&mp.lock);
    mp.used = 0;
    pthread_mutex_unlock(&mp.lock);
}

int process_stream(int sockfd) {
    char buffer[256];
    while (1) {
        ssize_t bytes_read = recv(sockfd, buffer, sizeof(buffer), 0);
        if (bytes_read <= 0) {
            if (errno == EINTR || errno == EAGAIN)
                continue; // Non-blocking mode, retry
            perror("recv failed");
            break;
        }

        for (size_t i = 0; i < bytes_read; ) {
            int key;
            long offset;

            if (bytes_read - i < sizeof(int)) {
                fprintf(stderr, "Corrupted data received\n");
                return EXIT_FAILURE;
            }

            memcpy(&key, buffer + i, sizeof(int));
            i += sizeof(int);

            if (bytes_read - i < sizeof(long)) {
                fprintf(stderr, "Corrupted data received\n");
                return EXIT_FAILURE;
            }

            memcpy(&offset, buffer + i, sizeof(long));
            i += sizeof(long);

            Record* record = alloc_record();
            if (!record) {
                perror("Failed to allocate record from memory pool");
                return EXIT_FAILURE;
            }

            record->key = key;
            record->offset = offset;

            // Process the record (placeholder)
        }
    }

    return 0;
}

void start_server(int port) {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen))<0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK)
                continue; // Non-blocking mode
            perror("accept");
            close(server_fd);
            exit(EXIT_FAILURE);
        }

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, (void *(*)(void *))process_stream, (void *)(intptr_t)new_socket) != 0) {
            perror("Failed to create thread");
            close(new_socket);
        }
        pthread_detach(thread_id); // Automatically reclaim resources on completion
    }

    close(server_fd);
}

int main() {
    init_memory_pool(POOL_SIZE);

    int port = 8080;
    start_server(port);

    free_memory_pool();
    return 0;
}
