    LogEntry entry;
    struct Node* next;
} Node;

// Function prototypes
LogEntry process_network_traffic(Node** head, size_t window_size);
void update_metrics(LogEntry* processed_entry, int* redundancy_count, double* avg_packet_size);

// Global variables for metrics (thread-safe access required)
int redundancy_count = 0;
double total_packet_size = 0.0;
size_t log_count = 0;

LogEntry process_network_traffic(Node** head, size_t window_size) {
    Node *current = NULL, *prev = NULL;
    LogEntry processed_entry;
    time_t current_time = time(NULL);

    // Initialize metrics
    int redundancy_detected = 0;
    double avg_packet_size = 0.0;

    if (*head == NULL) return (LogEntry){NULL, 0, 0};

    Node* temp = *head;
    while (temp != NULL && log_count > window_size) {
        prev = current;
        current = temp;
        temp = temp->next;

        // Remove oldest entry
        if (*head == current) *head = current->next;
        else prev->next = current->next;

        free(current->entry.timestamp);
        free(current);
        log_count--;
    }

    while (current != NULL) {
        time_t log_time = /* Extract timestamp from current->entry */;

        // Check temporal relevance
        if (difftime(current_time, log_time) > /* MAX_TIME_DIFF */) {
            prev = current;
            temp = current->next;

            free(current->entry.timestamp);
            free(current);
            log_count--;

            if (*head == current) *head = temp;
            else prev->next = temp;

            continue;
        }

        // Check redundancy and packet integrity
        if (!current->entry.is_valid || current->entry.is_redundant) {
            redundancy_detected++;
            processed_entry = current->entry;  // Update with the most recent invalid or redundant entry

            prev = current;
            temp = current->next;

            free(current->entry.timestamp);
            free(current);
            log_count--;

            if (*head == current) *head = temp;
            else prev->next = temp;

            continue;
        }

        // Update metrics
        total_packet_size += current->entry.packet_size;
        processed_entry = current->entry;  // Assume this is the most reliable entry

        prev = current;
        current = current->next;
    }

    if (log_count > 0) {
        avg_packet_size = total_packet_size / log_count;
    }

    update_metrics(processed_entry, &redundancy_detected, &avg_packet_size);

    return processed_entry;
}

void update_metrics(LogEntry* processed_entry, int* redundancy_count, double* avg_packet_size) {
