#include <iostream>
#include <queue>
#include <vector>
#include <unordered_map>
#include <ctime>
#include <functional>
#include <thread>

// Global variables for cooldowns and resource management
const int MAX_GLOBAL_COOLDOWN = 45;
const int MAX_MANA_CONSUMPTION_PER_MINUTE = 10;

struct Attack {
    int id;
    int cooldown;
    int manaCost;
    std::time_t startTime;
};

std::unordered_map<int, std::pair<int, std::time_t>> activeAttacks; // Maps attack ID to (remaining cooldown, start time)
int currentManaUsage = 0;
std::priority_queue<std::function<void()>, std::vector<std::function<void()>>, std::greater<>> attackQueue;

// Log function
void logAttack(int id, int startTime, int manaCost, int priority) {
    std::cout << "Selected Attack: " << id 
              << ", Start Time: " << startTime 
              << ", Resource Cost: " << manaCost 
              << ", Priority Level: " << priority << std::endl;
}

// Simulate external system integration
void simulateExternalSystem(const Attack& attack) {
    try {
        // Synchronous simulation (blocking)
        if (attack.id % 2 == 0) { // Example condition for choosing sync vs async
            std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate delay
            std::cout << "Attack " << attack.id << " executed synchronously." << std::endl;
        } else {
            std::thread([attack]() {
                std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate delay
                std::cout << "Attack " << attack.id << " executed asynchronously." << std::endl;
            }).detach();
        }
    } catch (const std::exception& e) {
        std::cerr << "Failed to execute attack " << attack.id << ": " << e.what() << std::endl;
    }
}

// Function to select and manage attacks
void selectAttack() {
    // Define available attacks
    std::vector<Attack> attacks = {
        {1, 5, 1}, {2, 10, 2}, {3, 15, 3}, {4, 20, 5}
    };

    int currentTime = static_cast<int>(std::time(nullptr));
    int totalCooldown = 0;
    int totalManaUsage = currentManaUsage;

    // Calculate available attacks based on cooldowns and mana
    for (const auto& attack : attacks) {
        if (activeAttacks.find(attack.id) != activeAttacks.end()) {
            auto& [remainingCooldown, startTime] = activeAttacks[attack.id];
            totalCooldown += remainingCooldown;
            if (currentTime - startTime >= remainingCooldown) {
                activeAttacks.erase(attack.id);
            }
        }

        if ((totalCooldown + attack.cooldown <= MAX_GLOBAL_COOLDOWN) && 
            (totalManaUsage + attack.manaCost <= MAX_MANA_CONSUMPTION_PER_MINUTE)) {

            // Priority calculation (example: based on cooldown, mana cost)
            int priority = 100 - (attack.cooldown + attack.manaCost);

            logAttack(attack.id, currentTime, attack.manaCost, priority);

            activeAttacks[attack.id] = {attack.cooldown, currentTime};
            totalCooldown += attack.cooldown;
            totalManaUsage += attack.manaCost;

            // Push the attack to queue
            attackQueue.push([attack]() {
                simulateExternalSystem(attack);
            });

            break; // Select one attack at a time
        }
    }

    if (!attackQueue.empty()) {
        auto action = attackQueue.top();
        attackQueue.pop();
        action();  // Execute the highest priority attack
    }

    currentManaUsage = totalManaUsage;
}

int main() {
    selectAttack();
    return 0;
}
