{
    private readonly float minValue;
    private readonly float maxValue;
    private readonly float stepSize;

    public DynamicGraphPopulator(float minValue, float maxValue, float stepSize)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value must be less than maximum value.");
        if (stepSize <= 0)
            throw new ArgumentException("Step size must be positive.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.stepSize = stepSize;
    }

    public float GetRandomFloat()
    {
        Random rand = new Random();
        int steps = (int)((maxValue - minValue) / stepSize);
        return minValue + stepSize * rand.Next(steps + 1);
    }

    public int GetRandomInt()
    {
        Random rand = new Random();
        int steps = (int)((maxValue - minValue) / stepSize);
        return (int)(minValue + stepSize * rand.Next(steps + 1));
    }

