#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char identifier;
    unsigned int value;
} item;

typedef struct TreeNode {
    item *data;
    struct TreeNode *left, *right;
} TreeNode;

#define MAX_DEPTH 10

TreeNode* createNode(item* data) {
    TreeNode* newNode = (TreeNode*)malloc(sizeof(TreeNode));
    if (!newNode) return NULL;
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

void freeTree(TreeNode* node) {
    if (!node) return;
    freeTree(node->left);
    freeTree(node->right);
    free(node->data);
    free(node);
}

int depth(TreeNode *root) {
    if (root == NULL) return 0;
    int leftDepth = depth(root->left);
    int rightDepth = depth(root->right);
    return (leftDepth > rightDepth ? leftDepth : rightDepth) + 1;
}

TreeNode* insertBST(TreeNode* root, item* data, int *depth) {
    if (*depth >= MAX_DEPTH) {
        printf("Max depth reached. Consider rebalancing.\n");
        // Implement resizing or balancing logic here
    }

    if (root == NULL) {
        *depth = 1;
        return createNode(data);
    }

    if (data->identifier < root->data->identifier)
        root->left = insertBST(root->left, data, depth + 1);
    else if (data->identifier > root->data->identifier)
        root->right = insertBST(root->right, data, depth + 1);

    return root;
}

void* safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE); // Handle gracefully or retry logic
    }
    return ptr;
}

int main() {
    int doubleArraySize = 10;
    double* doubleArray = (double*)safeMalloc(doubleArraySize * sizeof(double));

    int structArraySize = 5;
    item** structArray = (item**)safeMalloc(structArraySize * sizeof(item*));

    TreeNode* root = NULL;
    for (int i = 0; i < structArraySize; ++i) {
        structArray[i] = (item*)safeMalloc(sizeof(item));
        if (!structArray[i]) continue;

        structArray[i]->identifier = 'A' + i;
        structArray[i]->value = i * 10;

        int depth = 0;
        root = insertBST(root, structArray[i], &depth);
    }

    // Example usage
    freeTree(root);
    for (int i = 0; i < structArraySize; ++i) {
        free(structArray[i]);
    }

    free(doubleArray);
    free(structArray);

    return 0;
}
