class DynamicGraphTestPopulator {
public:
    DynamicGraphTestPopulator(float minValue, float maxValue, float stepSize)
        : minValue(minValue), maxValue(maxValue), stepSize(stepSize) {
        if (minValue >= maxValue || stepSize <= 0) {
            throw std::invalid_argument("Invalid range or non-positive step size");
        }
    }

    float GetRandomFloat() const {
        std::lock_guard<std::mutex> lock(mutex_);
        std::uniform_real_distribution<float> distribution(minValue, maxValue);
        return static_cast<float>(std::round(distribution(generator_) / stepSize) * stepSize);
    }

    int GetRandomInt() const {
        std::lock_guard<std::mutex> lock(mutex_);
        std::uniform_int_distribution<int> distribution(static_cast<int>(minValue), 
                                                        static_cast<int>(maxValue));
        return distribution(generator_);
    }

    std::vector<int> GetRandomList(int count) const {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<int> result;
        for (int i = 0; i < count; ++i) {
            result.push_back(GetRandomInt());
        }
        return result;
    }

    void PopulateGraph(Graph& graph, int vertexCount, int edgeCount, int maxAttempts) const {
        for (int attempt = 0; attempt < maxAttempts; ++attempt) {
            try {
                // Add vertices
                for (int i = 0; i < vertexCount; ++i) {
                    float prop = GetRandomFloat();
                    if (!graph.AddVertex(prop)) throw std::runtime_error("Failed to add vertex");
                }

                // Add edges
                for (int i = 0; i < edgeCount; ++i) {
                    int src = graph.GetRandomVertexId();
                    int dest = graph.GetRandomVertexId();
                    float prop = GetRandomFloat();
                    if (!graph.AddEdge(src, dest, prop)) throw std::runtime_error("Failed to add edge");
                }
                break;
            } catch (const std::exception& e) {
                // Handle specific system limitations or retry logic
            }
        }
    }

    void runModuleTests() const {
        std::lock_guard<std::mutex> lock(mutex_);

        const int longArraySize = 10;
        const int intKeysSize = 5;
        const int recordArraySize = 15;

        // Allocate and initialize arrays
