            int value;
        };

        auto records = std::make_unique<Record[]>(recordArraySize);

        for (int i = 0; i < longArraySize; ++i) {
            longOffsets[i] = GetRandomInt();
        }

        for (int i = 0; i < intKeysSize; ++i) {
            intKeys[i] = GetRandomInt();
        }

        for (int i = 0; i < recordArraySize; ++i) {
            records[i].value = GetRandomInt();
        }

        // Logging information
        std::cout << "Module tests run with long offsets, int keys, and records initialized." << std::endl;

        // Memory is automatically managed by smart pointers
    }

    std::string ToString() const {
        return "[" + std::to_string(minValue) + ", " + std::to_string(maxValue) + "]";
    }

private:
    float minValue;
    float maxValue;
    float stepSize;
    mutable std::mutex mutex_;
    std::mt19937 generator_{std::random_device{}()};
};

