CipherContext* initialize_cipher(const char *password) {
    CipherContext *ctx = (CipherContext *)malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    if (!ctx->cipher_ctx) {
        free(ctx);
        return NULL;
    }

    unsigned char key[AES_KEY_SIZE];
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, PBKDF2_ITERATIONS, EVP_sha256(), AES_KEY_SIZE, key)) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        free(ctx);
        return NULL;
    }

    if (1 != RAND_bytes(ctx->iv, IV_LENGTH)) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        free(ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL, key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        free(ctx);
        return NULL;
    }

    return ctx;
}

