#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct memory_pool {
    size_t block_size;
    void *memory;
    size_t num_blocks;
    pthread_mutex_t lock;
} memory_pool;

// Mock function to simulate loading a module
void loadModule(const char *label) {
    printf("Loading module: %s\n", label);
}

// Mock function to reset the environment after each test
void resetEnvironment() {
    printf("Resetting environment.\n");
}

// Function to initialize memory pool
memory_pool* initMemoryPool(size_t block_size, size_t num_blocks) {
    memory_pool *pool = malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->memory = malloc(block_size * num_blocks);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to allocate memory from the pool
void* allocateFromPool(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    static size_t offset = 0;

    if (offset >= pool->num_blocks * pool->block_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *ptr = ((char*)pool->memory) + offset;
    offset += pool->block_size;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to free memory pool
void freeMemoryPool(memory_pool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory);
    free(pool);
}

// Thread-safe wrapper for executing tests
void* executeTest(void *args) {
    struct {
        const char *label;
        void (*test_func)();
    } *arg = (struct { const char *label; void (*test_func)(); } *) args;

    loadModule(arg->label);

    arg->test_func();

    resetEnvironment();

    return NULL;
}

// Function to execute module tests
void executeModuleTests(const char *label, void (*f)(void)) {
    memory_pool *pool = initMemoryPool(sizeof(record), 100);
    if (!pool) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return;
    }

    size_t num_records = 10;
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record **records = malloc(num_records * sizeof(record*));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        freeMemoryPool(pool);
        fprintf(stderr, "Failed to allocate arrays\n");
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 100;

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate record\n");
            for (size_t j = 0; j < i; ++j) free(records[j]);
            free(offsets);
            free(keys);
            free(records);
            freeMemoryPool(pool);
            return;
        }

        records[i]->value = rand() % 1000;

        // Allocate from pool as an example
        void *pool_mem = allocateFromPool(pool);
        if (pool_mem) {
            memcpy(pool_mem, &(records[i]->value), sizeof(int));
        }
    }

    pthread_t thread;
    struct {
        const char *label;
        void (*test_func)();
    } arg = { label, f };

    if (pthread_create(&thread, NULL, executeTest, &arg)) {
        fprintf(stderr, "Failed to create test thread\n");
        for (size_t i = 0; i < num_records; ++i) free(records[i]);
        free(offsets);
        free(keys);
        free(records);
        freeMemoryPool(pool);
        return;
    }

    pthread_join(thread, NULL);

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }

    free(offsets);
    free(keys);
    free(records);
    freeMemoryPool(pool);
}

// Mock test function
void mockTestFunction() {
    printf("Executing mock test.\n");
}
