        if (shape) add_shape(collection, shape);
    }

    // Assign render strategy
    collection->render_strategies.wireframe = wireframe_render;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        collection->render_strategies.wireframe(collection->shapes[i]);
    }
    pthread_mutex_unlock(&collection->lock);

    free_shape_collection(collection);

    return 0;
}
