    pthread_mutex_destroy(&((pthread_mutex_t*)&storage - 1)); // Destroy the mutex
    free_memory_pool(pool);
    free(storage);
}

void read_data(int file_descriptor, data_storage *storage) {
    char buffer[256];
    float value;
    char str[100];
    int counter;

    while (read(file_descriptor, buffer, sizeof(buffer)) > 0) {
        if (sscanf(buffer, "%f %99s %d", &value, str, &counter) == 3) {
