            pthread_mutex_unlock(&((pthread_mutex_t*)&storage - 1));
        }
    }
}

float calculate_average(const data_storage *storage) {
    float sum = 0;
    for (size_t i = 0; i < storage->num_floats; ++i) {
        sum += storage->floats[i];
    }
    return storage->num_floats > 0 ? sum / storage->num_floats : 0.0f;
}

void print_average(const data_storage *storage) {
