['To implement a thread-safe dynamic memory manager in C for records consisting of an integer key and value, we will use a combination of mutexes for synchronization, a custom allocator using a slab allocation strategy to minimize fragmentation, and atomic operations for statistics gathering.

Here is the code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define BLOCK_SIZE 1024 // Adjust based on system performance testing
#define INITIAL_SLAB_COUNT 10

typedef struct {
    int key;
    int value;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} MemoryPool;

static atomic_size_t allocation_count = 0;
static atomic_size_t deallocation_count = 0;
static atomic_size_t current_memory_usage = 0;

void initialize_pool(MemoryPool* pool) {
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

Node* allocate_node(MemoryPool* pool) {
    Node* node;

    // Allocate a new slab
    if (pthread_mutex_lock(&pool->lock) == 0) {
        if (!pool->head) {
            node = malloc(BLOCK_SIZE * sizeof(Node));
            if (!node) return NULL; // Handle allocation failure

            for (size_t i = 1; i < BLOCK_SIZE; ++i) {
                node[i - 1].next = &node[i];
            }
            node[BLOCK_SIZE - 1].next = NULL;
            pool->head = node;
        }

        node = pool->head;
        pool->head = node->next;

        if (pthread_mutex_unlock(&pool->lock) != 0) {
            free(node); // Unlock failed, release the allocated memory
            return NULL;
        }

        atomic_fetch_add(&allocation_count, 1);
        atomic_fetch_add(&current_memory_usage, sizeof(Record));
    } else {
        node = NULL; // Handle mutex lock failure
    }

    return node;
}

void deallocate_node(MemoryPool* pool, Node* node) {
    if (pthread_mutex_lock(&pool->lock) == 0) {
        node->next = pool->head;
        pool->head = node;

        atomic_fetch_add(&deallocation_count, 1);
        atomic_fetch_sub(&current_memory_usage, sizeof(Record));

        if (pthread_mutex_unlock(&pool->lock) != 0) {
            // Handle mutex unlock failure
        }
    } else {
        // Handle mutex lock failure
    }
}

void print_statistics() {
    printf("Allocations: %zu\n", allocation_count);
    printf("Deallocations: %zu\n", deallocation_count);
    printf("Current Memory Usage: %zu bytes\n", current_memory_usage);
}

void destroy_pool(MemoryPool* pool) {
    Node* node = pool->head;
    while (node != NULL) {
        Node* next = node->next;
        free(node);
        node = next;
    }

    pthread_mutex_destroy(&pool->lock);
}

int main() {
    MemoryPool pool;
    initialize_pool(&pool);

    // Example usage
    Node* record1 = allocate_node(&pool);
    if (record1) {
        record1->data.key = 1;
        record1->data.value = 100;

        deallocate_node(&pool, record1);
    }

    print_statistics();

    destroy_pool(&pool);

    return 0;
}
```

### Key Points:

- **Slab Allocation**: Preallocates blocks of nodes to minimize allocation/deallocation overhead and fragmentation.
- **Thread-Safety**: Uses `pthread_mutex_t` for mutual exclusion on critical sections.
- **Atomic Operations**: Tracks statistics without additional locks, ensuring thread-safe increments and decrements.
- **Scalability**: Configurable slab size (`BLOCK_SIZE`) allows adjustment based on performance requirements.
- **Error Handling**: Checks for potential failures in mutex operations and memory allocations.']

