void init_memory_pool(size_t total_size) {
    mem_pool.start = malloc(total_size);
    mem_pool.size = total_size;
    pthread_mutex_init(&mem_pool.lock, NULL);
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&mem_pool.lock);
    if (size > mem_pool.size) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&mem_pool.lock);
        return NULL;
    }
    void* ptr = mem_pool.start;
    mem_pool.start = (char*)ptr + size;
    mem_pool.size -= size;
    pthread_mutex_unlock(&mem_pool.lock);

    // Log allocation
    printf("Allocated %zu bytes, remaining pool size: %zu\n", size, mem_pool.size);

    return ptr;
}

