['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_DRBS 10

typedef struct {
    int size;
    char *data;
} RLC_PDU;

typedef struct {
    // Configuration details for DRB (Dedicated Radio Bearer)
    int bandwidth;
    int priority;
} DRBConfig;

typedef struct UEContext {
    int UE_ID;
    RLC_PDU **RLC_PDUs;  // Dynamic list of RLC PDU segments
    size_t num_RLC_PDUs;
    DRBConfig drbConfigs[MAX_DRBS];
    pthread_mutex_t mutex;  // Mutex for thread safety
} UEContext;

typedef struct {
    UEContext **contexts;
    size_t num_contexts;
    pthread_rwlock_t rwlock;  // Read-write lock for efficient access
} ContextManager;

// Function to initialize the Context Manager
void init_ContextManager(ContextManager *manager) {
    manager->contexts = NULL;
    manager->num_contexts = 0;
    pthread_rwlock_init(&manager->rwlock, NULL);
}

// Function to destroy the Context Manager and free resources
void destroy_ContextManager(ContextManager *manager) {
    pthread_rwlock_wrlock(&manager->rwlock);
    for (size_t i = 0; i < manager->num_contexts; ++i) {
        UEContext *context = manager->contexts[i];
        for (size_t j = 0; j < context->num_RLC_PDUs; ++j) {
            free(context->RLC_PDUs[j]->data);
            free(context->RLC_PDUs[j]);
        }
        free(context->RLC_PDUs);
        pthread_mutex_destroy(&context->mutex);
        free(context);
    }
    free(manager->contexts);
    pthread_rwlock_unlock(&manager->rwlock);
    pthread_rwlock_destroy(&manager->rwlock);
}

// Function to find a UEContext by UE_ID
UEContext *get_UEContext(ContextManager *manager, int UE_ID) {
    pthread_rwlock_rdlock(&manager->rwlock);
    for (size_t i = 0; i < manager->num_contexts; ++i) {
        UEContext *context = manager->contexts[i];
        if (context->UE_ID == UE_ID) {
            pthread_rwlock_unlock(&manager->rwlock);
            return context;
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);
    return NULL;
}

// Function to add or update a UEContext
void set_UEContext(ContextManager *manager, int UE_ID, RLC_PDU **rlc_pdus, size_t num_rlc_pdus, DRBConfig drbConfigs[MAX_DRBS]) {
    pthread_rwlock_wrlock(&manager->rwlock);

    // Check if the context already exists
    for (size_t i = 0; i < manager->num_contexts; ++i) {
        UEContext *context = manager->contexts[i];
        if (context->UE_ID == UE_ID) {
            pthread_mutex_lock(&context->mutex);

            // Free existing RLC PDUs and replace with new ones
            for (size_t j = 0; j < context->num_RLC_PDUs; ++j) {
                free(context->RLC_PDUs[j]->data);
                free(context->RLC_PDUs[j]);
            }
            free(context->RLC_PDUs);

            // Allocate new RLC PDUs
            context->RLC_PDUs = (RLC_PDU **)malloc(num_rlc_pdus * sizeof(RLC_PDU *));
            for (size_t j = 0; j < num_rlc_pdus; ++j) {
                context->RLC_PDUs[j] = rlc_pdus[j];
            }
            context->num_RLC_PDUs = num_rlc_pdus;

            // Update DRB configurations
            memcpy(context->drbConfigs, drbConfigs, sizeof(DRBConfig) * MAX_DRBS);

            pthread_mutex_unlock(&context->mutex);
            pthread_rwlock_unlock(&manager->rwlock);
            return;
        }
    }

    // Create a new context if not found
    UEContext *new_context = (UEContext *)malloc(sizeof(UEContext));
    new_context->UE_ID = UE_ID;

    // Allocate RLC PDUs
    new_context->RLC_PDUs = (RLC_PDU **)malloc(num_rlc_pdus * sizeof(RLC_PDU *));
    for (size_t i = 0; i < num_rlc_pdus; ++i) {
        new_context->RLC_PDUs[i] = rlc_pdus[i];
    }
    new_context->num_RLC_PDUs = num_rlc_pdus;

    // Initialize DRB configurations
    memcpy(new_context->drbConfigs, drbConfigs, sizeof(DRBConfig) * MAX_DRBS);

    pthread_mutex_init(&new_context->mutex, NULL);

    // Expand the context array and add new context
    manager->contexts = (UEContext **)realloc(manager->contexts, (++manager->num_contexts) * sizeof(UEContext *));
    manager->contexts[manager->num_contexts - 1] = new_context;

    pthread_rwlock_unlock(&manager->rwlock);
}

// Function to log operations (stub for demonstration)
void log_operation(const char *operation) {
    // Compact logging mechanism
    printf("Log: %s\n", operation);  // Replace with actual file logging if needed
}
