#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    char *buffer;
    struct Record *next;
} Record;

Record* createLinkedList() {
    return NULL;
}

void insertAt(Record **head, int index, int recordValue, const char *buffer) {
    if (index < 0 || head == NULL) return;

    Record *newNode = (Record *)malloc(sizeof(Record));
    if (!newNode) return;

    newNode->value = recordValue;
    newNode->buffer = strdup(buffer);
    newNode->next = NULL;

    if (*head == NULL || index == 0) {
        newNode->next = *head;
        *head = newNode;
        return;
    }

    Record *current = *head;
    for (int i = 1; current != NULL && i < index; ++i) {
        current = current->next;
    }

    if (current == NULL) {
        free(newNode->buffer);
        free(newNode);
    } else {
        newNode->next = current->next;
        current->next = newNode;
    }
}

void removeAt(Record **head, int index) {
    if (index < 0 || head == NULL || *head == NULL) return;

    Record *temp = *head;

    if (index == 0) {
        *head = temp->next;
        free(temp->buffer);
        free(temp);
        return;
    }

    for (int i = 1; temp != NULL && i < index; ++i) {
        temp = temp->next;
    }

    if (temp == NULL || temp->next == NULL) return;

    Record *nextNode = temp->next->next;
    free(temp->next->buffer);
    free(temp->next);

    temp->next = nextNode;
}

void freeLinkedList(Record *head) {
    while (head != NULL) {
        Record *temp = head;
        head = head->next;
        free(temp->buffer);
        free(temp);
    }
}

void* safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initializeData(long n, int m, int k, unsigned seed) {
    if (n <= 0 || m <= 0 || k <= 0) return;

    long *offsets = (long *)safeMalloc(n * sizeof(long));
    int *keys = (int *)safeMalloc(m * sizeof(int));

    for (long i = 0; i < n; ++i) {
        offsets[i] = rand_r(&seed) % 1000;
    }

    for (int j = 0; j < m; ++j) {
        keys[j] = rand_r(&seed) % 100;
    }

    Record *records = createLinkedList();
    srand(seed);

    for (int l = 0; l < k; ++l) {
        int value = rand() % 500;
        char buffer[10];
        snprintf(buffer, sizeof(buffer), "%d", value);
        insertAt(&records, l, value, buffer);
    }

    // Cleanup
    free(offsets);
    free(keys);
    freeLinkedList(records);
}

int main() {
    unsigned seed = time(NULL);
    initializeData(5, 10, 3, seed);
    return 0;
}
