#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_ID 1000

typedef struct {
    int segment_id;
    char data[256]; // Example size, adjust as needed
} RLC_PDU;

typedef struct {
    int drb_id;
    char config_data[128]; // Example size, adjust as needed
} DRBConfig;

typedef struct UEContextEntry {
    int UE_ID;
    RLC_PDU *rlc_pdu_list;
    int rlc_pdu_count;
    DRBConfig *drb_config_list;
    int drb_config_count;
    time_t last_used;
    struct UEContextEntry* next;
} UEContextEntry;

typedef struct {
    UEContextEntry *head;
    pthread_mutex_t lock;
} UEContextList;

// Function declarations
void initUEContextList(UEContextList *list);
void freeUEContextList(UEContextList *list, int cleanup_unused);
int addOrUpdateUEContext(UEContextList *list, int ue_id, RLC_PDU *rlc_pdu_list, int rlc_pdu_count,
                         DRBConfig *drb_config_list, int drb_config_count);
UEContextEntry* getUEContextByUEID(UEContextList *list, int ue_id);
int cleanupUnusedResources(UEContextList *list, time_t inactivity_threshold);
void serializeUEContextList(const UEContextList *list, const char *filename);
int deserializeUEContextList(UEContextList *list, const char *filename);

// Initialize the list
void initUEContextList(UEContextList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Free the list and optionally cleanup unused resources
void freeUEContextList(UEContextList *list, int cleanup_unused) {
    pthread_mutex_lock(&list->lock);

    UEContextEntry *current = list->head;
    while (current != NULL) {
        UEContextEntry *to_delete = current;
        current = current->next;

        if (cleanup_unused || time(NULL) - to_delete->last_used > 3600) { // Example threshold
            free(to_delete->rlc_pdu_list);
            free(to_delete->drb_config_list);
            free(to_delete);
        }
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Add or update a UEContext entry
int addOrUpdateUEContext(UEContextList *list, int ue_id, RLC_PDU *rlc_pdu_list, int rlc_pdu_count,
                         DRBConfig *drb_config_list, int drb_config_count) {
    pthread_mutex_lock(&list->lock);

    UEContextEntry **entry = &list->head;
    while (*entry != NULL) {
        if ((*entry)->UE_ID == ue_id) break;
        entry = &(*entry)->next;
    }

    UEContextEntry *ue_entry = *entry;

    if (ue_entry == NULL) { // Add new
        ue_entry = malloc(sizeof(UEContextEntry));
        if (!ue_entry) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        ue_entry->UE_ID = ue_id;
        ue_entry->next = list->head;
        list->head = ue_entry;
    }

    // Update last used time
    ue_entry->last_used = time(NULL);

    // Allocate memory for RLC_PDU and DRBConfig lists if necessary
    if (ue_entry->rlc_pdu_list == NULL || ue_entry->rlc_pdu_count != rlc_pdu_count) {
        free(ue_entry->rlc_pdu_list);
        ue_entry->rlc_pdu_list = malloc(sizeof(RLC_PDU) * rlc_pdu_count);
        if (!ue_entry->rlc_pdu_list) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
    }
    memcpy(ue_entry->rlc_pdu_list, rlc_pdu_list, sizeof(RLC_PDU) * rlc_pdu_count);

    if (ue_entry->drb_config_list == NULL || ue_entry->drb_config_count != drb_config_count) {
        free(ue_entry->drb_config_list);
        ue_entry->drb_config_list = malloc(sizeof(DRBConfig) * drb_config_count);
        if (!ue_entry->drb_config_list) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
    }
    memcpy(ue_entry->drb_config_list, drb_config_list, sizeof(DRBConfig) * drb_config_count);

    ue_entry->rlc_pdu_count = rlc_pdu_count;
    ue_entry->drb_config_count = drb_config_count;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Retrieve a specific UEContext by its UE_ID
UEContextEntry* getUEContextByUEID(UEContextList *list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    UEContextEntry *current = list->head;
    while (current != NULL) {
        if (current->UE_ID == ue_id) {
            current->last_used = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

// Cleanup unused resources based on inactivity threshold
int cleanupUnusedResources(UEContextList *list, time_t inactivity_threshold) {
    pthread_mutex_lock(&list->lock);

    UEContextEntry **entry = &list->head;
    while (*entry != NULL) {
        if (time(NULL) - (*entry)->last_used > inactivity_threshold) {
            UEContextEntry *to_delete = *entry;
            *entry = to_delete->next;

            free(to_delete->rlc_pdu_list);
            free(to_delete->drb_config_list);
            free(to_delete);
        } else {
            entry = &(*entry)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Serialize the list to a file
void serializeUEContextList(const UEContextList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    UEContextEntry *current = list->head;
    while (current != NULL) {
        fwrite(&current->UE_ID, sizeof(current->UE_ID), 1, file);
        fwrite(&current->rlc_pdu_count, sizeof(current->rlc_pdu_count), 1, file);
