    DRBConfig **drb_configs;  // Array of DRBConfig pointers
    size_t drb_config_count;
    struct UEContextNode* next;
} UEContextNode;

typedef struct {
    UEContextNode *head;
    pthread_mutex_t lock;
    unsigned int access_counter[MAX_UE_CONTEXTS];
} UEContextList;

// Initialize OpenSSL
void initialize_crypto() {
