// Function to log operations
void log_operation(const char* operation, unsigned int ue_id) {
    printf("Timestamp: %ld, Operation: %s, UE_ID: %u\n", time(NULL), operation, ue_id);
}

// Initialize the UE Context List
UEContextList* create_ue_context_list() {
    UEContextList *list = (UEContextList *)malloc(sizeof(UEContextList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    memset(list->access_counter, 0, sizeof(unsigned int) * MAX_UE_CONTEXTS);
    return list;
}

// Add or Update UE Context
void add_or_update_ue_context(UEContextList* list, unsigned int ue_id,
                              RLC_PDU *rlc_pdus, size_t rlc_pdu_count,
                              DRBConfig **drb_configs, size_t drb_config_count) {
    pthread_mutex_lock(&list->lock);

    UEContextNode *current = list->head;
    UEContextNode *prev = NULL;

    while (current != NULL && current->UE_ID != ue_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {  // Add new context
        current = (UEContextNode *)malloc(sizeof(UEContextNode));
        current->UE_ID = ue_id;
        current->rlc_pdus = rlc_pdus;
        current->rlc_pdu_count = rlc_pdu_count;
        current->drb_configs = drb_configs;
        current->drb_config_count = drb_config_count;

        if (prev == NULL) {
            list->head = current;
        } else {
            prev->next = current;
        }
    } else {  // Update existing context
        free(current->rlc_pdus);
        free(current->drb_configs);

        current->rlc_pdus = rlc_pdus;
        current->rlc_pdu_count = rlc_pdu_count;
        current->drb_configs = drb_configs;
        current->drb_config_count = drb_config_count;
    }

    // Update LRU counter
    list->access_counter[ue_id % MAX_UE_CONTEXTS]++;

    log_operation("Add/Update", ue_id);

    pthread_mutex_unlock(&list->lock);
}

// Retrieve UE Context by UE_ID
UEContextNode* get_ue_context(UEContextList* list, unsigned int ue_id) {
    pthread_mutex_lock(&list->lock);

    UEContextNode *current = list->head;

    while (current != NULL && current->UE_ID != ue_id) {
        current = current->next;
    }

    if (current != NULL) {
        // Update LRU counter
        list->access_counter[ue_id % MAX_UE_CONTEXTS]++;
    }

    log_operation("Get", ue_id);

    pthread_mutex_unlock(&list->lock);
    return current;
}

// Evict the least recently used UE Context
void evict_lru_ue_context(UEContextList* list) {
    pthread_mutex_lock(&list->lock);

    unsigned int lru_index = 0, min_access_count = UINT_MAX - 1;
    for (unsigned int i = 0; i < MAX_UE_CONTEXTS; i++) {
        if (list->access_counter[i] < min_access_count) {
            min_access_count = list->access_counter[i];
            lru_index = i;
        }
    }

    UEContextNode *current = list->head, *prev = NULL;

    while (current != NULL && current->UE_ID % MAX_UE_CONTEXTS != lru_index) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {  // Perform eviction
        if (prev == NULL) {
            list->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current->rlc_pdus);
        free(current->drb_configs);
        free(current);

        log_operation("Evict", lru_index);
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup
void destroy_ue_context_list(UEContextList* list) {
    UEContextNode *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current->rlc_pdus);
        free(current->drb_configs);
        free(current);

        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
