#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct item {
    char identifier;
    unsigned int value;
} Item;

typedef struct bst_node {
    char key;
    Item *item;
    struct bst_node *left, *right;
} BSTNode;

typedef struct {
    BSTNode *root;
    pthread_mutex_t lock;
} BST;

BST* initialize_bst() {
    BST *tree = malloc(sizeof(BST));
    tree->root = NULL;
    pthread_mutex_init(&tree->lock, NULL);
    return tree;
}

void free_bst_node(BSTNode *node) {
    if (node == NULL)
        return;
    free_bst_node(node->left);
    free_bst_node(node->right);
    free(node->item);
    free(node);
}

void delete_bst(BST *tree) {
    pthread_mutex_lock(&tree->lock);
    free_bst_node(tree->root);
    pthread_mutex_unlock(&tree->lock);
    pthread_mutex_destroy(&tree->lock);
    free(tree);
}

BSTNode* insert_bst_node(BSTNode *node, char key, Item *item) {
    if (node == NULL) {
        BSTNode *new_node = malloc(sizeof(BSTNode));
        new_node->key = key;
        new_node->item = item;
        new_node->left = new_node->right = NULL;
        return new_node;
    }
    if (key < node->key)
        node->left = insert_bst_node(node->left, key, item);
    else if (key > node->key)
        node->right = insert_bst_node(node->right, key, item);
    return node;
}

void insert_into_bst(BST *tree, char key, Item *item) {
    pthread_mutex_lock(&tree->lock);
    tree->root = insert_bst_node(tree->root, key, item);
    pthread_mutex_unlock(&tree->lock);
}

Item* find_in_bst(BSTNode *node, char key) {
    if (node == NULL || node->key == key)
        return node ? node->item : NULL;
    if (key < node->key)
        return find_in_bst(node->left, key);
    else
        return find_in_bst(node->right, key);
}

Item* search_in_bst(BST *tree, char key) {
    pthread_mutex_lock(&tree->lock);
    Item *item = find_in_bst(tree->root, key);
    pthread_mutex_unlock(&tree->lock);
    return item;
}

// Utility to generate random unsigned int safely
unsigned int safe_random(unsigned int min, unsigned int max, unsigned int seed) {
    srand(seed ^ (unsigned int)time(NULL));
    return rand() % (max - min + 1) + min;
}

void initialize_arrays_and_bst(int size, double *double_array, Item **item_pointers,
                               BST *tree, unsigned int value_min, unsigned int value_max, unsigned int seed) {
    for (int i = 0; i < size; ++i) {
        double_array[i] = (double)i;

        // Safely allocate and initialize item
        Item *new_item = malloc(sizeof(Item));
        new_item->identifier = 'A' + i % 26;

        unsigned long long temp_val = safe_random(value_min, value_max, seed + i);
        if ((temp_val > ULLONG_MAX - (unsigned int)(value_max - value_min)) ||
            (new_item->value = (unsigned int)temp_val) > value_max) {
            fprintf(stderr, "Integer overflow detected.\n");
            exit(EXIT_FAILURE);
        }

        item_pointers[i] = new_item;

        // Insert into BST
        insert_into_bst(tree, new_item->identifier, new_item);
    }
}

int main() {
    int size = 100;
    double *double_array = malloc(size * sizeof(double));
    Item **item_pointers = malloc(size * sizeof(Item *));
    unsigned int value_min = 1, value_max = 1000, seed = 42;

    BST *tree = initialize_bst();
    initialize_arrays_and_bst(size, double_array, item_pointers, tree, value_min, value_max, seed);

    // Example of searching in the BST
    char search_key = 'A';
    Item *found_item = search_in_bst(tree, search_key);
    if (found_item) {
        printf("Found item with ID %c: Value = %u\n", found_item->identifier, found_item->value);
    }

    // Cleanup
    delete_bst(tree);
    free(double_array);
    for (int i = 0; i < size; ++i)
        free(item_pointers[i]);
    free(item_pointers);

    return 0;
}
