#define MAX_SESSIONS 1000

typedef struct {
    int MessageID;
    char Content[256];
} Message;

typedef struct {
    int SubscriptionID;
    char ServiceName[50];
} Subscription;

typedef struct {
    int UserID;
    Message *Messages;
    size_t MessageCount;
    Subscription *Subscriptions;
    size_t SubscriptionsCount;
} UserSession;

typedef struct {
    UserSession Sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
    int count;
} SessionManager;

// Initialize the session manager
void initSessionManager(SessionManager *manager) {
    memset(manager, 0, sizeof(SessionManager));
    pthread_mutex_init(&manager->lock, NULL);
}

// Add or update a user session
int addUserSession(SessionManager *manager, UserSession session) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (manager->Sessions[i].UserID == session.UserID) {
            // Update existing session
            free(manager->Sessions[i].Messages);
            manager->Sessions[i].Messages = realloc(session.Messages, sizeof(Message) * session.MessageCount);
            memcpy(manager->Sessions[i].Messages, session.Messages, sizeof(Message) * session.MessageCount);

            free(manager->Sessions[i].Subscriptions);
            manager->Sessions[i].Subscriptions = realloc(session.Subscriptions, sizeof(Subscription) * session.SubscriptionsCount);
            memcpy(manager->Sessions[i].Subscriptions, session.Subscriptions, sizeof(Subscription) * session.SubscriptionsCount);

            pthread_mutex_unlock(&manager->lock);
            return 1; // Updated
        }
    }

    if (manager->count < MAX_SESSIONS) {
        manager->Sessions[manager->count++] = session;
        pthread_mutex_unlock(&manager->lock);
        return 2; // Added new session
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Failed to add/update due to capacity limits
}

// Retrieve a user session by UserID
UserSession *getUserSession(SessionManager *manager, int userID) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (manager->Sessions[i].UserID == userID) {
            UserSession *sessionCopy = malloc(sizeof(UserSession));
            memcpy(sessionCopy, &manager->Sessions[i], sizeof(UserSession));
            pthread_mutex_unlock(&manager->lock);
            return sessionCopy;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Session not found
}

// Placeholder for message broker integration (simplified)
