    int value;
    time_t timestamp;
} Record;

typedef struct {
    char *data;
    bool isActive;
} Metadata;

#define RECORD_COUNT 1000

// Custom memory pool structure
typedef struct {
    void *pool;
    size_t block_size;
    size_t total_blocks;
    size_t free_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = malloc(block_size * total_blocks);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->free_blocks = total_blocks;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* memory_pool_alloc(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_blocks == 0) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // No available blocks
    }

    void *block = mp->pool + ((mp->total_blocks - mp->free_blocks) * mp->block_size);
    mp->free_blocks--;
    pthread_mutex_unlock(&mp->lock);

    return block;
}

void memory_pool_free(MemoryPool* mp, void* ptr) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_blocks < mp->total_blocks) {
        size_t offset = ((char*)ptr - (char*)mp->pool) / mp->block_size;
        memcpy(mp->pool + (offset * mp->block_size), ptr, mp->block_size);
        mp->free_blocks++;
    }
    pthread_mutex_unlock(&mp->lock);
}

void destroy_memory_pool(MemoryPool* mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Function to initialize data structures
