                         Metadata*** metadata1, Metadata*** metadata2) {

    // Initialize memory pool for all allocations
    MemoryPool* mp = create_memory_pool(sizeof(Record), RECORD_COUNT * 4);
    if (!mp) return -1;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    offsets[0] = (long*)memory_pool_alloc(mp);
    keys[0] = (int*)memory_pool_alloc(mp);
    records1[0] = (Record**)malloc(RECORD_COUNT * sizeof(Record*));
    records2[0] = (Record**)malloc(RECORD_COUNT * sizeof(Record*));
    metadata1[0] = (Metadata**)malloc(RECORD_COUNT * sizeof(Metadata*));
    metadata2[0] = (Metadata**)malloc(RECORD_COUNT * sizeof(Metadata*));

    if (!offsets[0] || !keys[0] || !records1[0] || !records2[0] || !metadata1[0] || !metadata2[0]) {
        // Handle allocation failure
        destroy_memory_pool(mp);
        pthread_mutex_destroy(&lock);
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < RECORD_COUNT; ++i) {
        records1[0][i] = (Record*)memory_pool_alloc(mp);
        records2[0][i] = (Record*)memory_pool_alloc(mp);
