    pthread_mutex_t lock;
    size_t total_size;
    size_t used_size;
    void* pool;
} MemoryPool;

MemoryPool memory_pool = {PTHREAD_MUTEX_INITIALIZER, 0, 0, NULL};

void init_memory_pool(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (!memory_pool.pool) {
        memory_pool.pool = malloc(size);
        if (!memory_pool.pool) {
            perror("Failed to allocate memory pool");
            exit(EXIT_FAILURE);
        }
        memory_pool.total_size = size;
        memory_pool.used_size = 0;
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

void* allocate_memory(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (size + memory_pool.used_size > memory_pool.total_size) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL;
    }
    void* ptr = (char*)memory_pool.pool + memory_pool.used_size;
    memory_pool.used_size += size;
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

