### JavaScript Function: `getElementSelectors`

```javascript
function getElementSelectors(node, selector, callback) {
    const matches = [];

    function traverse(n) {
        if (n.nodeType === Node.ELEMENT_NODE && n.matches(selector)) {
            matches.push(n);
        }

        Array.from(n.children).forEach(traverse);
    }

    traverse(node);

    // Execute the callback with the collected matches
    callback(matches);

    return matches;
}

// Example usage:
document.addEventListener("DOMContentLoaded", () => {
    const container = document.querySelector('#container');
    getElementSelectors(container, '.target-class', (matches) => {
        console.log('Found elements:', matches);
    });
});
```

