            logging.error(f"Command failed: {e.output.decode()}")
            raise

    def construct_test_command(self, test_env_name, branch):
        return f"deploy --test-env {test_env_name} --branch {branch}"

    def construct_plugin_command(self, plugin, branch):
        return f"install-plugin --plugin {plugin['name']} --version {plugin['version']}"

