['Below is a C function that addresses the described requirements. The function manages dynamic memory allocation for records, ensuring constraints like monotonically increasing offsets and unique keys are satisfied.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    long min_offset;
    long max_offset;
} Config;

#define LOG_LEVEL_NONE 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_DEBUG 2

int global_log_level = LOG_LEVEL_INFO; // Configure log level here.

void log_message(int level, const char *message) {
    if (level <= global_log_level) {
        printf("%s\n", message);
    }
}

bool validate_config(Config config) {
    return config.min_offset < config.max_offset;
}

int initialize_records(Record **records_out, long offsets[], int keys[], size_t num_records, Config config) {
    if (!validate_config(config)) {
        log_message(LOG_LEVEL_INFO, "Invalid configuration range.");
        return -1; // Error: Invalid config.
    }

    if (num_records <= 0 || !offsets || !keys) {
        log_message(LOG_LEVEL_DEBUG, "Invalid input: zero or negative number of records.");
        return -2; // Error: Invalid input parameters.
    }

    *records_out = malloc(num_records * sizeof(Record));
    if (*records_out == NULL) {
        log_message(LOG_LEVEL_INFO, "Memory allocation failed for records array.");
        return -3; // Error: Memory allocation failure.
    }

    int seen_keys[256] = {0};  // Assuming keys are in range [0, 255].
    long last_offset = config.min_offset - 1;

    for (size_t i = 0; i < num_records; ++i) {
        if (offsets[i] <= last_offset || seen_keys[keys[i]]) {
            log_message(LOG_LEVEL_INFO, "Failed to meet constraints: Non-monotonic offset or duplicate key.");
            free(*records_out);
            return -4; // Error: Constraint violation.
        }

        (*records_out)[i].offset = offsets[i];
        (*records_out)[i].key = keys[i];
        last_offset = offsets[i];
        seen_keys[keys[i]] = 1;
    }

    log_message(LOG_LEVEL_INFO, "Records initialized successfully.");
    return 0; // Success
}

int main() {
    Config config = {100, 200};
    long offsets[] = {101, 102, 103};
    int keys[] = {10, 20, 30};
    size_t num_records = sizeof(offsets) / sizeof(long);

    Record *records;
    int result = initialize_records(&records, offsets, keys, num_records, config);

    if (result == 0 && records != NULL) {
        for (size_t i = 0; i < num_records; ++i) {
            printf("Record %zu: offset=%ld, key=%d\n", i, records[i].offset, records[i].key);
        }
        free(records); // Clean up allocated memory.
    } else {
        log_message(LOG_LEVEL_DEBUG, "Initialization failed with error code: %d", result);
    }

    return 0;
}
```

### Key Points:
- **Memory Management**: Memory is dynamically allocated for the records. If any allocation fails or constraints are not met, it frees all previously allocated memory to prevent leaks.
- **Error Handling**: The function returns specific error codes if validation fails, inputs are incorrect, or constraints (monotonic offset and unique keys) aren't satisfied.
- **Logging**: All operations are logged with a configurable log level for easy debugging and auditing. Adjust `global_log_level` as needed.
- **Validation**: Input values like configuration ranges and input arrays are validated to ensure robustness against invalid inputs.
- **Assumptions**: The code assumes key uniqueness is within a small range (0 to 255) suitable for the use of a simple array to track seen keys. Adjust if the expected key range is different.']

