    std::string source;
    std::chrono::time_point<std::chrono::steady_clock> timestamp;
    int priority;

    Message(const std::string& p, const std::string& s, int pr)
        : payload(p), source(s), priority(pr), 
          timestamp(std::chrono::steady_clock::now()) {}
};

class MemoryPool {
public:
