typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct HashTable {
    Node** buckets;
    size_t num_buckets;
    pthread_mutex_t* locks;
} HashTable;

static void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->num_buckets; ++i) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table->locks);
}

static size_t hash(int key, size_t num_buckets) {
    return key % num_buckets;
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->num_buckets = INITIAL_TABLE_SIZE;
    table->buckets = (Node**)calloc(table->num_buckets, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->locks = (pthread_mutex_t*)malloc(table->num_buckets * sizeof(pthread_mutex_t));
    if (!table->locks) {
        free(table->buckets);
        free(table);
        return NULL;
    }

    for (size_t i = 0; i < table->num_buckets; ++i)
        pthread_mutex_init(&table->locks[i], NULL);

    return table;
}

int resize_hash_table(HashTable* table) {
    size_t new_num_buckets = table->num_buckets * 2;
    Node** new_buckets = (Node**)calloc(new_num_buckets, sizeof(Node*));
    if (!new_buckets) return -1;

    for (size_t i = 0; i < table->num_buckets; ++i) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            size_t new_index = hash(node->record.key, new_num_buckets);
            Node* next_node = node->next;

            pthread_mutex_lock(&table->locks[new_index]);
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            pthread_mutex_unlock(&table->locks[new_index]);

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->num_buckets = new_num_buckets;

    pthread_mutex_t* new_locks = (pthread_mutex_t*)malloc(new_num_buckets * sizeof(pthread_mutex_t));
    if (!new_locks) return -1;

    for (size_t i = 0; i < new_num_buckets; ++i)
        pthread_mutex_init(&new_locks[i], NULL);

    free(table->locks);
    table->locks = new_locks;

    return 0;
}

int add_or_update_record(HashTable* table, int key, long offset) {
    size_t index = hash(key, table->num_buckets);
    pthread_mutex_lock(&table->locks[index]);

    Node* node = table->buckets[index];
    while (node != NULL) {
        if (node->record.key == key) {
            node->record.offset = offset;
            pthread_mutex_unlock(&table->locks[index]);
            return 0; // Updated
        }
        node = node->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->locks[index]);
        return -1; // Memory allocation failure
    }

    new_node->record.key = key;
    new_node->record.offset = offset;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    size_t count = 0;
    for (size_t i = 0; i < table->num_buckets; ++i) {
        Node* n = table->buckets[i];
        while (n != NULL) {
            ++count;
            n = n->next;
        }
    }

    if ((float)count / table->num_buckets > LOAD_FACTOR) {
        pthread_mutex_unlock(&table->locks[index]);
        if (resize_hash_table(table) != 0) {
            free(new_node);
            return -1; // Resizing failed
        }
        index = hash(key, table->num_buckets); // Rehash to new table size
        pthread_mutex_lock(&table->locks[index]);
    }

    pthread_mutex_unlock(&table->locks[index]);
    return 1; // Added
}

long get_record(HashTable* table, int key) {
    size_t index = hash(key, table->num_buckets);
    pthread_mutex_lock(&table->locks[index]);

    Node* node = table->buckets[index];
    while (node != NULL) {
        if (node->record.key == key) {
            long offset = node->record.offset;
            pthread_mutex_unlock(&table->locks[index]);
            return offset; // Found
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return -1; // Not found
}

void destroy_hash_table(HashTable* table) {
    free_hash_table(table);
}
