    size_t count;
    pthread_rwlock_t lock;
} Cache;

Cache cache = {NULL, 0, PTHREAD_RWLOCK_INITIALIZER};

// Function to dynamically load a library and retrieve function pointers
void *(*load_library_func)(const char *, const char *) = NULL;

void initialize_loader(void) {
    if (load_library_func == NULL) {
        void *handle = dlopen("libdynamicloader.so", RTLD_LAZY);
        if (!handle) {
            fprintf(stderr, "Failed to load dynamic loader: %s\n", dlerror());
            exit(EXIT_FAILURE);
        }

        *(void **)(&load_library_func) = dlsym(handle, "load_function");
        if (!load_library_func) {
            fprintf(stderr, "Failed to find function: %s\n", dlerror());
            dlclose(handle);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to retrieve available metrics and tools
MetricEntry *discover_metrics(size_t *count) {
    initialize_loader();

    pthread_rwlock_wrlock(&cache.lock);

    if (cache.entries != NULL) {
        // Return cached entries if available
        *count = cache.count;
        MetricEntry *entries = malloc(cache.count * sizeof(MetricEntry));
        memcpy(entries, cache.entries, cache.count * sizeof(MetricEntry));

        pthread_rwlock_unlock(&cache.lock);
        return entries;
    }

    // Example: Load metrics from hypothetical libraries
    const char *libraries[] = {"libmetric1.so", "libmetric2.so"};
    size_t total_entries = 0;

    for (size_t i = 0; i < sizeof(libraries) / sizeof(libraries[0]); ++i) {
        void *handle = dlopen(libraries[i], RTLD_LAZY);
        if (!handle) {
            fprintf(stderr, "Failed to load library %s: %s\n", libraries[i], dlerror());
            continue;
        }

        char func_name[] = "get_metric_function";
        void *(*func_ptr)(void *) = (void *(*)(void *))dlsym(handle, func_name);
        if (!func_ptr) {
            fprintf(stderr, "Failed to load function %s from %s: %s\n", func_name, libraries[i], dlerror());
            continue;
        }

        // Assuming the metric name and parameters can be retrieved by calling the function pointer
        char *metric_name = (char *)func_ptr(NULL);
        if (!metric_name) {
            fprintf(stderr, "Failed to retrieve metric name from %s\n", libraries[i]);
            continue;
        }

        total_entries++;
    }

    MetricEntry *entries = malloc(total_entries * sizeof(MetricEntry));
    size_t index = 0;

    for (size_t i = 0; i < sizeof(libraries) / sizeof(libraries[0]); ++i) {
        void *handle = dlopen(libraries[i], RTLD_LAZY);
        if (!handle) continue;

        char func_name[] = "get_metric_function";
        void *(*func_ptr)(void *) = (void *(*)(void *))dlsym(handle, func_name);
        if (!func_ptr) continue;

        entries[index].name = strdup((char *)func_ptr(NULL));
        entries[index].retrieve_func = func_ptr;
        entries[index++].params = NULL; // Assuming no additional parameters
    }

    cache.entries = entries;
    cache.count = total_entries;

    pthread_rwlock_unlock(&cache.lock);
    *count = total_entries;

    return entries;
}

void free_metrics(MetricEntry *entries, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(entries[i].name);
    }
    free(entries);

    pthread_rwlock_wrlock(&cache.lock);
    if (cache.entries != NULL) {
        free(cache.entries);
        cache.entries = NULL;
        cache.count = 0;
    }
    pthread_rwlock_unlock(&cache.lock);
}

// Example logging function
void log_usage(const char *message) {
    // Placeholder for configurable logging implementation
    printf("LOG: %s\n", message);
}
