#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structures
typedef struct {
    int rlc_pdu_id;
    char *data;
} RLC_PDU;

typedef struct {
    int drb_id;
    char *config_data;
} DRBConfig;

typedef struct {
    int ue_id;
    RLC_PDU *rlc_pdu_list;
    size_t rlc_pdu_count;
    DRBConfig *drb_config_list;
    size_t drb_config_count;
} UEContext;

// Thread-safe list management
typedef struct Node {
    UEContext *ue_context;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} UEList;

UEList ue_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function prototypes
void init_ue_list();
UEContext* get_ues_context_by_id(int ue_id);
int add_ue_context(UEContext *ue_context);
int update_ue_context(int ue_id, UEContext *new_data);
int delete_ue_context(int ue_id);

// Initialize list (for simplicity)
void init_ue_list() {
    pthread_mutex_init(&ue_list.lock, NULL);
}

// Retrieve UEContext by ID
UEContext* get_ues_context_by_id(int ue_id) {
    pthread_mutex_lock(&ue_list.lock);
    Node *current = ue_list.head;
    while (current != NULL) {
        if (current->ue_context->ue_id == ue_id) {
            pthread_mutex_unlock(&ue_list.lock);
            return current->ue_context;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&ue_list.lock);
    return NULL;
}

// Add UEContext
int add_ue_context(UEContext *ue_context) {
    pthread_mutex_lock(&ue_list.lock);

    Node *new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&ue_list.lock);
        return -1; // Memory allocation failed
    }

    new_node->ue_context = ue_context;
    new_node->next = ue_list.head;
    ue_list.head = new_node;

    pthread_mutex_unlock(&ue_list.lock);
    return 0;
}

// Update UEContext by ID
int update_ue_context(int ue_id, UEContext *new_data) {
    pthread_mutex_lock(&ue_list.lock);

    Node *current = ue_list.head;
    while (current != NULL) {
        if (current->ue_context->ue_id == ue_id) {
            // Free existing data and replace with new
            for (size_t i = 0; i < current->ue_context->rlc_pdu_count; ++i) {
                free(current->ue_context->rlc_pdu_list[i].data);
            }
            free(current->ue_context->rlc_pdu_list);

            for (size_t i = 0; i < current->ue_context->drb_config_count; ++i) {
                free(current->ue_context->drb_config_list[i].config_data);
            }
            free(current->ue_context->drb_config_list);

            // Update data
            *current->ue_context = *new_data;
            pthread_mutex_unlock(&ue_list.lock);
            return 0;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ue_list.lock);
    return -1; // UEContext not found
}

// Delete UEContext by ID
int delete_ue_context(int ue_id) {
    pthread_mutex_lock(&ue_list.lock);

    Node *current = ue_list.head, *prev = NULL;

    while (current != NULL && current->ue_context->ue_id != ue_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&ue_list.lock);
        return -1; // UEContext not found
    }

    if (prev == NULL) { // Head node
        ue_list.head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->ue_context->rlc_pdu_list);
    for (size_t i = 0; i < current->ue_context->drb_config_count; ++i) {
        free(current->ue_context->drb_config_list[i].config_data);
    }
    free(current->ue_context->drb_config_list);
    free(current->ue_context);

    free(current);
    pthread_mutex_unlock(&ue_list.lock);
    return 0;
}

// HTTP Request Handlers (Pseudo code, as C does not directly support web frameworks)
void handle_put_request(int ue_id, UEContext *new_data) {
    if (update_ue_context(ue_id, new_data) == 0) {
        printf("UEContext updated successfully\n");
    } else {
        printf("Failed to update UEContext\n");
    }
}

void handle_delete_request(int ue_id) {
    if (delete_ue_context(ue_id) == 0) {
        printf("UEContext deleted successfully\n");
    } else {
        printf("Failed to delete UEContext\n");
    }
}
```

This code provides a basic implementation for managing `UEContext` structures, ensuring thread safety using mutex locks. It includes functions to add, update, and delete entries by `ue_id`. Additionally, it outlines pseudo-code for handling HTTP PUT and DELETE requests, as C itself does not directly support web frameworks. For real-world applications, you would typically use a web framework like Express.js with Node.js or Django in Python, along with an appropriate database for persistence (e.g., PostgreSQL or MongoDB) to handle these operations more effectively.']

