#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_SIZE 10000

typedef struct {
    int key;
    time_t last_accessed;
} record;

typedef struct HashTableNode {
    record rec;
    struct HashTableNode* next;
} HashTableNode;

typedef struct {
    size_t capacity;
    size_t size;
    HashTableNode** buckets;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash(int key, size_t capacity) {
    return (unsigned int)key % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->size = 0;
    table->buckets = calloc(initial_capacity, sizeof(HashTableNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void resize_hash_table(HashTable* table) {
    size_t new_capacity = (size_t)(table->capacity * 1.5);
    HashTableNode** new_buckets = calloc(new_capacity, sizeof(HashTableNode*));
    if (!new_buckets) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            HashTableNode* next_node = node->next;
            unsigned int new_index = hash(node->rec.key, new_capacity);
            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

int insert_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);

    if (table->size >= table->capacity * 0.75) {
        resize_hash_table(table);
    }

    unsigned int index = hash(key, table->capacity);
    HashTableNode* node = malloc(sizeof(HashTableNode));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    node->rec.key = key;
    node->rec.last_accessed = time(NULL);
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->size++;

    pthread_mutex_unlock(&table->lock);
    return 0;
}

HashTableNode* find_record(HashTable* table, int key) {
    unsigned int index = hash(key, table->capacity);
    HashTableNode* node = table->buckets[index];

    while (node) {
        if (node->rec.key == key) {
            pthread_mutex_lock(&table->lock);
            node->rec.last_accessed = time(NULL);
            pthread_mutex_unlock(&table->lock);
            return node;
        }
        node = node->next;
    }

    return NULL;
}

size_t get_total_records(HashTable* table) {
    pthread_mutex_lock(&table->lock);
    size_t total_records = table->size;
    pthread_mutex_unlock(&table->lock);

    return total_records;
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            HashTableNode* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void initialize_hash_table(HashTable** table, size_t initial_capacity) {
    *table = create_hash_table(initial_capacity);
    if (!*table) {
        fprintf(stderr, "Failed to create hash table\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 100000; ++i) { // Simulate record initialization
        int key = rand() % 20000;
        insert_record(*table, key);
    }
}

int main() {
