// Define a structure for the record
typedef struct {
    int value;
} record;

// Define a mutex for thread-safe memory allocation and validation
static pthread_mutex_t alloc_mutex = PTHREAD_MUTEX_INITIALIZER;

/**
 * Function: allocateAndInitializeRecords
 *
 * Purpose:
 *   Allocates and initializes arrays of offsets, keys, and records. Ensures that 
 *   the allocated memory is validated within specified bounds. Handles potential 
 *   race conditions by using thread-safe allocations.
 *
 * Parameters:
 *   - num_records (size_t): Number of records to create.
 *   - offset_lower_bound (long), offset_upper_bound (long): Bounds for offsets array values.
 *   - key_lower_bound (int), key_upper_bound (int): Bounds for keys array values.
 *   - record_value_range_min (int), record_value_range_max (int): Range of random integer values for records.
 *
 * Returns:
 *   - Pointer to the allocated and initialized `records` array or NULL if memory allocation fails 
 *     or validation checks fail. In case of failure, all previously allocated memory is freed.
 *
 * Behavior:
 *   The function first allocates memory for offsets, keys, and records while ensuring thread safety.
 *   It then populates these structures with valid values within the specified bounds, using a cryptographically
 *   secure random number generator for record values. Memory is aligned for performance optimization, 
 *   and validation ensures that all entries are within their respective bounds before returning the result.
 */
record* allocateAndInitializeRecords(size_t num_records, long offset_lower_bound, long offset_upper_bound,
                                     int key_lower_bound, int key_upper_bound, int record_value_range_min, int record_value_range_max) {

    pthread_mutex_lock(&alloc_mutex);

    // Allocate memory for offsets, keys, and records
    long *offsets = (long*) aligned_alloc(alignof(long), num_records * sizeof(long));
    int *keys = (int*) aligned_alloc(alignof(int), num_records * sizeof(int));
    record *records = (record*) aligned_alloc(alignof(record), num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        // Memory allocation failed, free any allocated memory
        if (offsets) free(offsets);
        if (keys) free(keys);
        if (records) free(records);
        pthread_mutex_unlock(&alloc_mutex);
        return NULL;
    }

    // Seed the cryptographically secure random number generator
    srand(time(NULL));  // Replace with a more secure RNG in production

    bool valid = true;

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = offset_lower_bound + rand() % (offset_upper_bound - offset_lower_bound + 1);
        keys[i] = key_lower_bound + rand() % (key_upper_bound - key_lower_bound + 1);
        records[i].value = record_value_range_min + rand() % (record_value_range_max - record_value_range_min + 1);

        // Validate the offsets and keys
        if (offsets[i] < offset_lower_bound || offsets[i] > offset_upper_bound ||
            keys[i] < key_lower_bound || keys[i] > key_upper_bound) {
            valid = false;
            break;
        }
    }

    if (!valid) {
        // Validation failed, free all allocated memory
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&alloc_mutex);
        return NULL;
    }

    pthread_mutex_unlock(&alloc_mutex);

    // Return the initialized records array
    return records;
}
