#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    atomic_size_t count;
    pthread_mutex_t lock; // Use spinlocks if needed for better performance
} RecordsCollection;

RecordsCollection* create_records_collection(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_RECORDS)
        return NULL;

    RecordsCollection *collection = malloc(sizeof(RecordsCollection));
    if (!collection)
        return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    atomic_store(&collection->count, 0);

    pthread_mutex_init(&collection->lock, NULL); // Consider using spinlocks
    return collection;
}

int add_record(RecordsCollection *collection, int key, long offset) {
    if (!collection || key < 0 || offset < 0)
        return -1;

    size_t current_count = atomic_load(&collection->count);

    pthread_mutex_lock(&collection->lock);
    if (current_count >= collection->capacity) {
        // Reallocate to handle more records
        size_t new_capacity = collection->capacity * 2;
        Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    // Add the record
    collection->records[current_count].key = key;
    collection->records[current_count].offset = offset;
    atomic_store(&collection->count, current_count + 1);

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int validate_records(RecordsCollection *collection) {
    if (!collection)
        return -1;

    for (size_t i = 0; i < atomic_load(&collection->count); ++i) {
        Record rec = collection->records[i];
        if (rec.key < 0 || rec.offset < 0) // Extend validation as needed
            return -1;
    }
    return 0;
}

void free_records_collection(RecordsCollection *collection) {
    if (!collection)
        return;

    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}
