#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/time.h>
#include <unistd.h>

typedef struct {
    long timestamp;
    double temperature;
} record;

typedef struct {
    pthread_mutex_t lock;
    record *records;
    size_t count;
} RecordManager;

void log_performance(const char* message) {
    static FILE* log_file = NULL;
    if (!log_file) {
        log_file = fopen("performance.log", "a");
        if (!log_file) return; // If unable to open, exit function
    }
    fprintf(log_file, "%s\n", message);
    fflush(log_file);  // Ensure it's written immediately for real-time tracking
}

double fetch_initial_temperature() {
    // Simulate a network call with random latency and potential failure
    sleep(rand() % 3 + 1); // Random delay between 1 to 3 seconds

    if (rand() % 10 < 2) { // 20% chance of failure
        return -1; // Indicating failure in fetching data
    }

    return ((double) rand() / RAND_MAX * 100.0); // Return a random temperature value
}

void initialize_records(RecordManager* manager, size_t count, double min_temp, double max_temp) {
    if (manager == NULL || manager->records == NULL) return;

    pthread_mutex_lock(&manager->lock);

    struct timeval start_time;
    gettimeofday(&start_time, NULL);

    for (size_t i = 0; i < manager->count; ++i) {
        manager->records[i].timestamp = time(NULL); // Current timestamp
        double temp = fetch_initial_temperature();

        if (temp == -1) { // Handle failure in data source
            temp = min_temp + ((double) rand() / RAND_MAX * (max_temp - min_temp));
        }

        manager->records[i].temperature = temp;
    }

    struct timeval end_time;
    gettimeofday(&end_time, NULL);

    long elapsed_time = 1000000L * (end_time.tv_sec - start_time.tv_sec) + 
                        (end_time.tv_usec - start_time.tv_usec);

    char performance_message[256];
    snprintf(performance_message, sizeof(performance_message), "Initialized %zu records in %ld microseconds.", manager->count, elapsed_time);
    log_performance(performance_message);

    pthread_mutex_unlock(&manager->lock);
}

void allocate_records(RecordManager* manager, size_t count) {
    if (manager == NULL) return;

    pthread_mutex_init(&manager->lock, NULL);

    struct timeval start_alloc_time;
    gettimeofday(&start_alloc_time, NULL);

    manager->records = malloc(sizeof(record) * count);
    if (!manager->records) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    manager->count = count;

    struct timeval end_alloc_time;
    gettimeofday(&end_alloc_time, NULL);

    long alloc_time = 1000000L * (end_alloc_time.tv_sec - start_alloc_time.tv_sec) + 
                      (end_alloc_time.tv_usec - start_alloc_time.tv_usec);

    char alloc_message[256];
    snprintf(alloc_message, sizeof(alloc_message), "Allocated memory for %zu records in %ld microseconds.", count, alloc_time);
    log_performance(alloc_message);

}

void free_records(RecordManager* manager) {
    if (manager == NULL || manager->records == NULL) return;

    pthread_mutex_lock(&manager->lock);

    free(manager->records);
    manager->records = NULL;
    manager->count = 0;

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

int main() {
    RecordManager mgr;
    size_t num_entries = 100; // Example count
    double min_temp = -10.0, max_temp = 40.0;

    allocate_records(&mgr, num_entries);
    initialize_records(&mgr, num_entries, min_temp, max_temp);
    free_records(&mgr);

    return 0;
}
