#define MAX_MEMORY_USAGE 1048576 // Example limit: 1 MB

typedef struct {
    int value;
} Record;

void initializeArrays(int numRecords, long *offsets, int *keys, int minValue, int maxValue) {
    if (numRecords <= 0 || !offsets || !keys) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    size_t requiredMemory = sizeof(long) * numRecords + sizeof(int) * numRecords + sizeof(Record) * numRecords;

    if (requiredMemory > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory usage exceeds the predefined limit.\n");
        return;
    }

    Record *records = (Record *)malloc(sizeof(Record) * numRecords);
    if (!records) {
        perror("Failed to allocate memory for records.");
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = rand(); // Simple random assignment
        keys[i] = rand();

        records[i].value = minValue + rand() % (maxValue - minValue + 1);
    }

    printf("Initialization successful: %d records created.\n", numRecords);

    // Simulated operations for PUT and DELETE requests
    void updateResource(int resourceId, const char *updatedData) {
        // Find resource by resourceId in keys array
        int found = 0;
        for (int i = 0; i < numRecords; ++i) {
            if (keys[i] == resourceId) {
                printf("Updating resource ID %d with data: %s\n", resourceId, updatedData);
                records[i].value = rand() % (maxValue - minValue + 1); // Update value
                found = 1;
                break;
            }
        }

        if (!found) {
            fprintf(stderr, "Resource with ID %d not found.\n", resourceId);
        }
    }

    void deleteResource(int resourceId) {
        int found = 0;
        for (int i = 0; i < numRecords; ++i) {
            if (keys[i] == resourceId) {
                printf("Deleting resource ID %d and providing a new one with default values.\n", resourceId);
                keys[i] = rand(); // Assign new key
                records[i].value = minValue; // Set to default value
                found = 1;
                break;
            }
        }

        if (!found) {
            fprintf(stderr, "Resource with ID %d not found for deletion.\n", resourceId);
        }
    }

    // Example usage:
    updateResource(12345, "{\"name\": \"UpdatedName\"}");
    deleteResource(67890);

    free(records);
}

int main() {
    int numRecords = 100; // Number of records
    long *offsets = (long *)malloc(sizeof(long) * numRecords);
    int *keys = (int *)malloc(sizeof(int) * numRecords);

    if (!offsets || !keys) {
