    }

    std::string location = "Unknown Location";

    for (p = res; p != NULL; p = p->ai_next) {
        if (getnameinfo(p->ai_addr, p->ai_addrlen, nullptr, 0, nullptr, 0, NI_NUMERICHOST | NI_NUMERICSERV)) {
            continue;
        }
        location = "Resolved Location"; // Simplified for demonstration
