#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Assuming an external logging library with functions like log_info and log_error
extern void log_info(const char *message);
extern void log_error(const char *message);

typedef struct {
    int id;
    long value;
    double measurement;
    char *metadata;
} Record;

Record* initialize_records(size_t num_records, const char **metadata_sources) {
    if (num_records == 0 || metadata_sources == NULL) {
        log_error("Invalid input: number of records or metadata sources is null.");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        log_error("Memory allocation failed for record array.");
        pthread_mutex_destroy(&lock);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);

        records[i].id = i;
        records[i].value = (long)i * 1000;
        records[i].measurement = (double)i * 1.5;

        if (metadata_sources[i] != NULL) {
            size_t len = strlen(metadata_sources[i]);
            records[i].metadata = malloc(len + 1);
            if (!records[i].metadata) {
                log_error("Memory allocation failed for metadata string.");
                pthread_mutex_unlock(&lock);

                // Free already allocated memory
                for (size_t j = 0; j < i; ++j) {
                    free(records[j].metadata);
                }
                free(records);
                pthread_mutex_destroy(&lock);
                return NULL;
            }
            strcpy(records[i].metadata, metadata_sources[i]);
        } else {
            records[i].metadata = NULL;
        }

        log_info("Record initialized: ID=%d", records[i].id);

        pthread_mutex_unlock(&lock);
    }

    // Verification mechanism
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].id != i || records[i].metadata == NULL && metadata_sources[i] != NULL) {
            log_error("Data integrity check failed for record ID=%zu", i);
            // Handle verification failure
        }
    }

    pthread_mutex_destroy(&lock);

    return records;
}

void free_records(Record *records, size_t num_records) {
    if (!records) return;

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].metadata);
    }
    free(records);
}
```

### Key Points:

- **Dynamic Memory Allocation**: The function allocates memory for an array of `Record` structures and their associated metadata strings.

- **Error Handling**: Uses logging to document errors during memory allocation failures.

- **Thread Safety**: Utilizes a mutex lock to prevent race conditions when initializing records.

- **Verification**: Checks the integrity of initialized data.

- **Resource Management**: Properly frees allocated resources in case of failure.

This implementation is modular and can be easily extended or integrated with other systems.']

