['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Polly;

public class HttpRequestHandler
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<HttpRequestHandler> _logger;
    private int _maxConcurrentRequests = 10;
    private int _batchSize = 5;
    private double _targetResponseTimeMs = 500.0; // Example target response time in milliseconds

    public HttpRequestHandler(HttpClient httpClient, ILogger<HttpRequestHandler> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<IEnumerable<string>> ExecuteRequestsAsync(List<string> urls)
    {
        var tasks = SplitIntoBatches(urls).Select(batch => ProcessBatchAsync(batch)).ToList();
        var results = await Task.WhenAll(tasks);
        return results.SelectMany(result => result).ToArray();
    }

    private IEnumerable<List<string>> SplitIntoBatches(IEnumerable<string> items)
    {
        var batches = new List<List<string>>();

        for (var i = 0; i < items.Count(); i += _batchSize)
        {
            batches.Add(items.Skip(i).Take(_batchSize).ToList());
        }

        return batches;
    }

    private async Task<IEnumerable<string>> ProcessBatchAsync(List<string> batch)
    {
        var responses = new List<string>();
        var sem = new SemaphoreSlim(_maxConcurrentRequests);

        var tasks = batch.Select(async url =>
        {
            await sem.WaitAsync();
            try
            {
                var response = await ExecuteRequestWithRetryAsync(url);
                if (response.IsSuccessStatusCode)
                {
                    responses.Add(await response.Content.ReadAsStringAsync());
                    LogSuccess(url, response.RequestMessage, response);
                }
                else
                {
                    LogFailure(url, response.RequestMessage, response);
                }

                AdjustBatchSize(response);
            }
            finally
            {
                sem.Release();
            }
        });

        await Task.WhenAll(tasks);

        return responses;
    }

    private async Task<HttpResponseMessage> ExecuteRequestWithRetryAsync(string url)
    {
        var retryPolicy = Policy.Handle<HttpRequestException>()
                                .OrResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
                                .WaitAndRetryAsync(3, attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                                                   onRetry: (exception, timespan, retryCount, context) =>
                                                   {
                                                       _logger.LogWarning($"Retrying {context.OperationKey}. Attempt {retryCount}.");
                                                   });

        return await retryPolicy.ExecuteAsync(() => _httpClient.GetAsync(url));
    }

    private void AdjustBatchSize(HttpResponseMessage response)
    {
        var responseTime = response.Headers.Date.HasValue ? 
                           (DateTime.UtcNow - response.Headers.Date.Value).TotalMilliseconds : 0;

        if (response.IsSuccessStatusCode && responseTime > _targetResponseTimeMs && _batchSize > 1)
        {
            _batchSize--;
            _logger.LogInformation($"Reduced batch size to {_batchSize} due to high latency.");
        }
        else if (_batchSize < urls.Count / 2) // Example logic for increasing the batch size
        {
            _batchSize++;
            _logger.LogInformation($"Increased batch size to {_batchSize}.");
        }
    }

    private void LogSuccess(string url, HttpRequestMessage request, HttpResponseMessage response)
    {
        var logData = new
        {
            Url = url,
            StatusCode = response.StatusCode,
            DurationMs = (DateTime.UtcNow - response.RequestMessage.Headers.Date!.Value).TotalMilliseconds,
            Success = true
        };
        _logger.LogInformation("Request success: {@LogData}", logData);
    }

    private void LogFailure(string url, HttpRequestMessage request, HttpResponseMessage response)
    {
        var logData = new
        {
            Url = url,
            StatusCode = response.StatusCode,
            DurationMs = (DateTime.UtcNow - response.RequestMessage.Headers.Date!.Value).TotalMilliseconds,
            Success = false
        };
        _logger.LogError("Request failed: {@LogData}", logData);
    }
}
```

