#include <iostream>
#include <thread>
#include <mutex>
#include <chrono>
#include <unordered_map>
#include <random>
#include <future>
#include <vector>

// Enum representing strategy types
enum class StrategyType { AGGRESSIVE, DEFENSIVE };

struct Strategy {
    StrategyType type;
    int attackPower;
    std::chrono::milliseconds duration;
    std::chrono::seconds cooldown;

    Strategy(StrategyType t, int power, int dur, int cd)
        : type(t), attackPower(power), duration(std::chrono::milliseconds(dur)), cooldown(std::chrono::seconds(cd)) {}
};

// Metadata for strategies
struct StrategyMetadata {
    std::unordered_map<StrategyType, Strategy> strategies;
    mutable std::mutex mutex;

    Strategy getStrategy(StrategyType type) {
        std::lock_guard<std::mutex> lock(mutex);
        return strategies[type];
    }
};

class CombatSystem {
public:
    CombatSystem() : lastUsedTime(std::chrono::steady_clock::time_point::min()) {}

    void combatStrategyManager(StrategyType strategyType, StrategyMetadata& metadata) {
        std::lock_guard<std::mutex> lock(strategiesMutex);

        auto currentTime = std::chrono::steady_clock::now();
        if (currentTime - lastUsedTime < std::chrono::seconds(10)) {
            log("Cooldown period active. Strategy execution delayed.");
            return;
        }

        try {
            Strategy strategy = metadata.getStrategy(strategyType);

            // Simulate executing the strategy
            executeStrategy(strategy);

            // Log success and update last used time
            log("Successfully executed " + std::to_string(static_cast<int>(strategy.type)) + " strategy.");
            lastUsedTime = currentTime;
        } catch (const std::exception& e) {
            log("Error during strategy execution: " + std::string(e.what()));
        }
    }

private:
    mutable std::mutex strategiesMutex;
    std::chrono::steady_clock::time_point lastUsedTime;

    void executeStrategy(const Strategy& strategy) {
        // Simulate the effect of executing a strategy (e.g., logging, computation)
        std::this_thread::sleep_for(strategy.duration);
        log("Executed " + std::to_string(static_cast<int>(strategy.type)) + 
            " with attack power: " + std::to_string(strategy.attackPower));
    }

    void log(const std::string& message) {
        // Thread-safe logging mechanism
        static std::mutex logMutex;
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << "[Log] " << message << "\n";
    }
};

// Initialize strategies with random values within a specified range
void initializeStrategies(StrategyMetadata& metadata) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> powerDist(10, 100);
    std::uniform_int_distribution<> durDist(500, 1500);
    std::uniform_int_distribution<> cdDist(5, 15);

    metadata.strategies[StrategyType::AGGRESSIVE] = Strategy(
        StrategyType::AGGRESSIVE, powerDist(gen), durDist(gen), cdDist(gen));
    metadata.strategies[StrategyType::DEFENSIVE] = Strategy(
        StrategyType::DEFENSIVE, powerDist(gen), durDist(gen), cdDist(gen));
}

int main() {
    StrategyMetadata metadata;
    initializeStrategies(metadata);

    CombatSystem combatSystem;

    // Simulate multiple threads requesting strategies
    std::vector<std::future<void>> futures;
    for (int i = 0; i < 10; ++i) {
        futures.push_back(std::async(std::launch::async, [&combatSystem, &metadata]() {
            combatSystem.combatStrategyManager(StrategyType::AGGRESSIVE, metadata);
        }));

        futures.push_back(std::async(std::launch::async, [&combatSystem, &metadata]() {
            combatSystem.combatStrategyManager(StrategyType::DEFENSIVE, metadata);
        }));
    }

    for (auto& f : futures) {
        f.get();
    }

    return 0;
}
