```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;
import java.util.logging.Logger;

class Record {
    private final int id;
    private long lastAccessTimestamp;

    public Record(int id) {
        this.id = id;
        updateLastAccess();
    }

    public synchronized void updateLastAccess() {
        this.lastAccessTimestamp = System.currentTimeMillis();
    }

    public int getId() {
        return id;
    }

    public long getLastAccessTimestamp() {
        return lastAccessTimestamp;
    }
}

class RecordCollection {
    private final ConcurrentHashMap<Integer, Record> records;
    private AtomicLong successfulAllocations = new AtomicLong(0);
    private AtomicLong failedAttempts = new AtomicLong(0);

    public RecordCollection(int initialCapacity) {
        this.records = new ConcurrentHashMap<>(initialCapacity);
    }

    public boolean addRecord(int id) {
        if (records.putIfAbsent(id, new Record(id)) == null) {
            successfulAllocations.incrementAndGet();
            return true;
        }
        failedAttempts.incrementAndGet();
        return false;
    }

    public synchronized void resize() {
        int newSize = (int) Math.ceil(records.size() * 1.5);
        // Rehashing in concurrent map is managed internally
    }

    public Record getRecord(int id) {
        return records.get(id);
    }

    public long getTotalRecordsCount() {
        return records.size();
    }
}

class ServiceLifecycleManager implements Runnable {
    private final Logger logger = Logger.getLogger(ServiceLifecycleManager.class.getName());
    private final RecordCollection recordCollection;
    private volatile boolean running = true;
    private static final int INITIAL_CAPACITY = 10000;

    public ServiceLifecycleManager() {
        this.recordCollection = new RecordCollection(INITIAL_CAPACITY);
    }

    @Override
    public void run() {
        Random random = new Random();

        while (running) {
            try {
                Thread.sleep(random.nextInt(2000)); // Varying intervals

                for (int i = 0; i < 100; i++) { // Add records dynamically
                    recordCollection.addRecord(random.nextInt());
                }

                if ((recordCollection.getTotalRecordsCount() + 1) > recordCollection.records.size()) {
                    recordCollection.resize();
                }

                logger.info("Running service with " + recordCollection.getTotalRecordsCount() + 
                            " records. Successful allocations: " + recordCollection.successfulAllocations.get());

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }

            stopService();
        }
    }

    private void stopService() {
        logger.info("Stopping service and sending message...");

        // Simulate sending a message to an external messaging system
        System.out.println("Message sent: Service Stopped");
    }

    public void shutdown() {
        running = false;
    }

    public static void main(String[] args) throws InterruptedException {
        ServiceLifecycleManager manager = new ServiceLifecycleManager();
        Thread serviceThread = new Thread(manager);

        serviceThread.start();

        // Simulate service running for some time
        Thread.sleep(10000);

        manager.shutdown();
        if (serviceThread.isAlive()) {
            serviceThread.join();
        }

        logger.info("Service lifecycle completed.");
    }
}
```

### Key Features:
- **Concurrent Data Structure**: Utilizes `ConcurrentHashMap` to manage records for thread-safe operations.
- **Dynamic Resizing**: Automatically resizes when capacity is exceeded using a factor of 1.5, with minimal explicit rehashing since `ConcurrentHashMap` handles it efficiently internally.
- **Statistics Logging**: Logs successful allocations and failed attempts to monitor performance.
