- Handling null inputs with clear error messages.
- Efficient processing by managing resources properly, suitable for large datasets.']

['Below is a C code implementation for the described task. This example uses POSIX threads for thread safety and assumes that you have access to an external compression library (e.g., zlib) if needed.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <zlib.h>  // Include this only if using compression

// Constants for hash table size and rehash threshold
#define INITIAL_SIZE 101
#define REHASH_THRESHOLD 0.75

typedef struct Record {
    int key;
    float value;
    char *charData;
    long offset;
    time_t lastAccessTime;  // For pruning inactive records
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

typedef struct HashTable {
    size_t size;
    size_t count;
    Node **buckets;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(size_t initialSize) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->size = initialSize;
    table->count = 0;
    table->buckets = calloc(initialSize, sizeof(Node *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

unsigned long hashFunction(int key, size_t tableSize) {
    return (unsigned long)key % tableSize;
}

int insertRecord(HashTable *table, int key, float value, const char *charData, long offset) {
    pthread_mutex_lock(&table->lock);

    if ((float)table->count / table->size > REHASH_THRESHOLD) {
        // Rehashing logic here
        size_t newSize = table->size * 2;
        Node **newBuckets = calloc(newSize, sizeof(Node *));
        if (!newBuckets) {
            pthread_mutex_unlock(&table->lock);
            return -1; // Memory allocation failure
        }

        for (size_t i = 0; i < table->size; ++i) {
            Node *current = table->buckets[i];
            while (current) {
                unsigned long newIndex = hashFunction(current->record->key, newSize);
                Node *node = current;
                current = current->next;

                node->next = newBuckets[newIndex];
                newBuckets[newIndex] = node;
            }
        }

        free(table->buckets);
        table->buckets = newBuckets;
        table->size = newSize;
    }

    unsigned long index = hashFunction(key, table->size);
    Node *newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failure
    }

    newNode->record = malloc(sizeof(Record));
    if (!newNode->record) {
        free(newNode);
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failure
    }

    newNode->record->key = key;
    newNode->record->value = value;
    newNode->record->offset = offset;

    char *dataCopy = strdup(charData);  // Consider compression if needed
    if (!dataCopy) {
        free(newNode->record);
        free(newNode);
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failure
    }

    newNode->record->charData = dataCopy;
    newNode->record->lastAccessTime = time(NULL);

    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    ++table->count;

    pthread_mutex_unlock(&table->lock);
    return 0; // Success
}

Record* findRecord(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hashFunction(key, table->size);
    Node *current = table->buckets[index];

    while (current) {
        if (current->record->key == key) {
            current->record->lastAccessTime = time(NULL);  // Update access time
            pthread_mutex_unlock(&table->lock);
            return current->record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;  // Record not found
}

void pruneRecords(HashTable *table, time_t maxInactiveTime) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->size; ++i) {
        Node **current = &table->buckets[i];
        while (*current) {
            if (difftime(time(NULL), (*current)->record->lastAccessTime) > maxInactiveTime) {
                Node *toDelete = *current;
                *current = toDelete->next;

                free(toDelete->record->charData);
                free(toDelete->record);
                free(toDelete);

                --table->count;
            } else {
                current = &(*current)->next;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
}

void destroyHashTable(HashTable *table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        Node *current = table->buckets[i];
        while (current) {
            Node *toDelete = current;
            current = current->next;

            free(toDelete->record->charData);
            free(toDelete->record);
            free(toDelete);
        }
    }

    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

// Logging mechanism placeholder
void logOperation(const char *message) {
    // Non-blocking logging logic here, e.g., write to a file or use syslog.
}

int main() {
    HashTable *table = createHashTable(INITIAL_SIZE);

    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return EXIT_FAILURE;
    }

    insertRecord(table, 1, 3.14f, "Sample data", 1234);
    Record *record = findRecord(table, 1);

    if (record) {
        printf("Found record: %d, %.2f, %s, %ld\n",
               record->key,
               record->value,
               record->charData,
               record->offset);
    } else {
        printf("Record not found\n");
    }

    pruneRecords(table, 60 * 5); // Prune records inactive for more than 5 minutes
    destroyHashTable(table);

    return EXIT_SUCCESS;
}
```

### Notes:
- **Compression**: If using compression, integrate the library (e.g., zlib) to compress/decompress `charData`. Ensure that the memory allocation and access logic correctly handle compressed data.
- **Logging**: Implement logging with minimal performance impact. Consider using asynchronous logging techniques or dedicated logging threads.
- **Thread Safety**: Use mutexes for protecting shared resources accessed by multiple threads.
- **Error Handling**: Handle memory allocation failures gracefully by returning error codes.
- **Pruning**: Periodically prune inactive records based on a threshold to manage memory usage efficiently.']

