### C Code: Dynamic Collection Management

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ITEMS 1000
#define SLAB_SIZE sizeof(item)
#define POOL_SIZE (SLAB_SIZE * MAX_ITEMS)

typedef struct {
    float f;
    int i;
    char* str;
} item;

typedef struct {
    item items[MAX_ITEMS];
    size_t count;
    pthread_mutex_t lock;
} collection;

void init_pool(collection *c) {
    c->count = 0;
    pthread_mutex_init(&c->lock, NULL);
}

int is_full(const collection *c) {
    return c->count == MAX_ITEMS;
}

item* allocate_item(collection *c) {
    if (is_full(c)) return NULL;

    pthread_mutex_lock(&c->lock);

    item *new_item = &c->items[c->count++];

    // Initialize with random values
    new_item->f = ((float) rand() / RAND_MAX) * 100.0;
    new_item->i = rand() % 1000;
    new_item->str = strdup("RandomString");

    pthread_mutex_unlock(&c->lock);
    return new_item;
}

int remove_item(collection *c, int index) {
    if (index < 0 || index >= c->count) return -1;

    pthread_mutex_lock(&c->lock);

    free(c->items[index].str); // Free allocated string
    memmove(&c->items[index], &c->items[index + 1], (c->count - index - 1) * SLAB_SIZE);
    c->count--;

    pthread_mutex_unlock(&c->lock);
    return 0;
}

item* get_item(const collection *c, int index) {
    if (index < 0 || index >= c->count) return NULL;

    pthread_mutex_lock(&c->lock);
    item* result = &c->items[index];
    pthread_mutex_unlock(&c->lock);

    return result;
}
```

### PHP Code: OAuth 2.0 Authentication

```php
<?php
session_start();

function authenticateOAuth($clientId, $clientSecret, $redirectUri, $authUrl) {
    if (!isset($_GET['code'])) {
        // Generate auth URL and redirect user
        $url = "$authUrl?response_type=code&client_id=$clientId&redirect_uri=" . urlencode($redirectUri);
        header("Location: $url");
        exit();
    }

    // Exchange code for access token
    $tokenResponse = file_get_contents("$authUrl/token?grant_type=authorization_code"
        . "&code={$_GET['code']}&client_id=$clientId&client_secret=$clientSecret&redirect_uri=" 
        . urlencode($redirectUri));
    $tokenData = json_decode($tokenResponse, true);

    if (isset($tokenData['access_token'])) {
        // Securely store access token
        $_SESSION['accessToken'] = $tokenData['access_token'];

        // Retrieve user information using the access token
        $userInfoUrl = "$authUrl/userinfo?access_token=" . urlencode($_SESSION['accessToken']);
        $userResponse = file_get_contents($userInfoUrl);
        $userData = json_decode($userResponse, true);

        if ($userData) {
            // Log successful authentication
            error_log("User authenticated: " . print_r($userData, true));
            return $userData;
        }
    }

    // Log failed authentication attempt
    error_log("Authentication failed.");
    return false;
}

function rateLimitIP() {
    // Implement a simple in-memory rate limiter
    static $attempts = [];
    $ip = $_SERVER['REMOTE_ADDR'];
    if (!isset($attempts[$ip])) {
        $attempts[$ip] = 0;
    }

    $attempts[$ip]++;
    if ($attempts[$ip] > 5) { // Example limit
        return false; // Too many attempts
    }
    return true;
}

function getDomainIP($domain) {
    return gethostbyname($domain);
}
```

