struct Point {
    float x;
    float y;
};

struct Geometry {
    double value;
    std::string str;
    Point point;
};

class MemoryPool {
public:
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        void* ptr = nullptr;
        if (free_list_.empty()) {
            ptr = ::operator new(size);
        } else {
            ptr = free_list_.back();
            free_list_.pop_back();
        }
        allocations_[ptr] = size;
        return ptr;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = allocations_.find(ptr);
        if (it != allocations_.end()) {
            ::operator delete(ptr);
            allocations_.erase(it);
        }
    }

    ~MemoryPool() {
        for (const auto& alloc : allocations_) {
            ::operator delete(alloc.first);
        }
    }

private:
    std::mutex mutex_;
    std::vector<void*> free_list_;
    std::unordered_map<void*, size_t> allocations_;
};

class ConfigParserStrategy {
public:
    virtual void parse(const std::vector<char>& data, Geometry& geom) = 0;
};

class BinaryConfigParser : public ConfigParserStrategy {
public:
    void parse(const std::vector<char>& data, Geometry& geom) override {
        // Example parsing logic
