        char* str = reinterpret_cast<char*>(data.data() + sizeof(double));
        float* pt = reinterpret_cast<float*>(data.data() + sizeof(double) + strlen(str) + 1);

        geom.value = *val;
        geom.str.assign(str);
        geom.point.x = *pt++;
        geom.point.y = *pt;
    }
};

