#define POOL_SIZE 1024 * 64 // Adjust as needed

void* memory_pool[POOL_SIZE];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate from the custom memory pool
void* custom_alloc(size_t size) {
    pthread_mutex_lock(&pool_lock);
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

// Function to initialize a sensor with random values
void init_sensor(Sensor *sensor, int min_reading, int max_reading) {
    if (sensor == NULL) return;

    sensor->reading = rand() % (max_reading - min_reading + 1) + min_reading;
    sensor->timestamp = (float)(rand() / (RAND_MAX)) * 100.0; // Example timestamp
}

// Function to generate a random alphanumeric string
void random_string(char* str, size_t length) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";
    if (str == NULL || length < 1)
        return;

    for (size_t n = 0; n < length; ++n) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[n] = charset[key];
    }
    str[length] = '\0';
}

// Initialize the monitoring system
MonitoringSystem* init_monitoring_system(size_t size, int min_reading, int max_reading, size_t string_length) {
    MonitoringSystem *system = custom_alloc(sizeof(MonitoringSystem));
    if (system == NULL) return NULL;

    system->doubles_array = custom_alloc(size * sizeof(double));
    system->strings_array = custom_alloc(size * sizeof(char*));
    system->sensors_array = custom_alloc(size * sizeof(Sensor));
    system->size = size;

    for (size_t i = 0; i < size; ++i) {
        system->doubles_array[i] = (double)(rand() / (RAND_MAX)) * 100.0;
        system->strings_array[i] = custom_alloc((string_length + 1) * sizeof(char));
        random_string(system->strings_array[i], string_length);
        init_sensor(&system->sensors_array[i], min_reading, max_reading);
    }

    return system;
}

// Find the smallest integer in an array using a thread-safe function
int find_smallest_int(int* arr, size_t length) {
    if (arr == NULL || length == 0)
        return INT_MAX;

    int smallest = arr[0];
    for (size_t i = 1; i < length; ++i) {
        if (arr[i] < smallest) {
            smallest = arr[i];
        }
    }
    return smallest;
}

// Example usage of the functions
int main() {
    srand(time(NULL));

    // Initialize monitoring system with example parameters
    MonitoringSystem* system = init_monitoring_system(10, 1, 100, 8);

    int numbers[] = {5, 3, 9, 1, 4};
    size_t length = sizeof(numbers) / sizeof(numbers[0]);

    // Thread-safe operation to find the smallest integer
    int smallest_number = find_smallest_int(numbers, length);
    printf("Smallest number: %d\n", smallest_number);

    // Cleanup resources
    for (size_t i = 0; i < system->size; ++i) {
        free(system->strings_array[i]);
    }
    free(system->strings_array);
    free(system->sensors_array);
    free(system->doubles_array);
    free(system);

    return 0;
}
