#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <float.h>

typedef struct {
    int key;
    long offset;
    double measurement;
} sensor;

typedef enum { DEBUG, INFO, WARN, ERROR } LogLevel;

typedef struct MemoryPool {
    void* base;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    int *keys_array;
    long *offsets_array;
    double *measurements_array;
    sensor *sensors_array;
    int keys_count;
    LogLevel log_level;
    MemoryPool mem_pool;
    pthread_mutex_t median_lock;
} SensorData;

void* memory_pool_allocate(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used + size > pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Handle resizing logic here if needed
    }
    void *ptr = (char*)pool->base + pool->used;
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void memory_pool_init(MemoryPool* pool, size_t initial_size) {
    pool->base = malloc(initial_size);
    if (!pool->base) exit(EXIT_FAILURE);
    pool->size = initial_size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void log_message(SensorData *data, LogLevel level, const char* message) {
    if (level >= data->log_level) {
        printf("%s\n", message); // Replace with more sophisticated logging if needed
    }
}

int compare_int(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

double calculate_median(int* array, int count) {
    if (count % 2 == 0)
        return (array[count / 2 - 1] + array[count / 2]) / 2.0;
    else
        return array[count / 2];
}

void read_integers_from_stdin(SensorData* data) {
    int n, *input_array = NULL;
    log_message(data, DEBUG, "Reading integers from standard input.");

    while (scanf("%d", &n) == 1) {
        int *new_array = realloc(input_array, (data->keys_count + 1) * sizeof(int));
        if (!new_array) exit(EXIT_FAILURE);

        new_array[data->keys_count] = n;
        data->keys_count++;
        input_array = new_array;
    }

    qsort(input_array, data->keys_count, sizeof(int), compare_int);

    pthread_mutex_lock(&data->median_lock);
    double median = calculate_median(input_array, data->keys_count);
    printf("Median: %f\n", median);
    pthread_mutex_unlock(&data->median_lock);

    free(input_array);
}

void* initialize_sensors(void* arg) {
    SensorData *data = (SensorData*)arg;
    int i;

    log_message(data, DEBUG, "Initializing sensor arrays.");

    data->keys_array = memory_pool_allocate(&data->mem_pool, data->keys_count * sizeof(int));
    data->offsets_array = memory_pool_allocate(&data->mem_pool, data->keys_count * sizeof(long));
    data->measurements_array = memory_pool_allocate(&data->mem_pool, data->keys_count * sizeof(double));

    if (!data->keys_array || !data->offsets_array || !data->measurements_array) {
        log_message(data, ERROR, "Memory allocation failed for arrays.");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (i = 0; i < data->keys_count; ++i) {
        data->keys_array[i] = rand() % 100;
        data->offsets_array[i] = rand();
        data->measurements_array[i] = ((double)rand() / RAND_MAX) * 10.0 + 1.0;

        data->sensors_array[i].key = data->keys_array[i];
        data->sensors_array[i].offset = data->offsets_array[i];
        data->sensors_array[i].measurement = data->measurements_array[i];
    }

    return NULL;
}

void free_resources(SensorData* data) {
    log_message(data, DEBUG, "Freeing allocated resources.");
    pthread_mutex_destroy(&data->mem_pool.lock);
    pthread_mutex_destroy(&data->median_lock);
    free(data->sensors_array);
    free(data->keys_array);
    free(data->offsets_array);
    free(data->measurements_array);
    free(data->mem_pool.base);
}

SensorData* create_sensor_data(int keys_count, LogLevel log_level) {
    SensorData *data = (SensorData*)malloc(sizeof(SensorData));
    if (!data) exit(EXIT_FAILURE);

    data->keys_count = keys_count;
    data->log_level = log_level;

    memory_pool_init(&data->mem_pool, 1024 * 64); // Initial pool size

    pthread_mutex_init(&data->median_lock, NULL);

    data->sensors_array = (sensor*)malloc(keys_count * sizeof(sensor));
    if (!data->sensors_array) exit(EXIT_FAILURE);

    return data;
}

void destroy_sensor_data(SensorData* data) {
    free_resources(data);
    free(data);
}

int main() {
    SensorData *data = create_sensor_data(1000, DEBUG); // Example count and log level

    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_sensors, data) != 0) exit(EXIT_FAILURE);

    read_integers_from_stdin(data);

    pthread_join(thread, NULL);
    destroy_sensor_data(data);

    return 0;
}
```

