#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char identifier;
    float value;
} Item;

typedef struct {
    Item *items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->items = malloc(initial_capacity * sizeof(Item));
    if (!collection->items) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void resize_collection(Collection *collection, size_t new_capacity) {
    Item *new_items = realloc(collection->items, new_capacity * sizeof(Item));
    if (!new_items) return;

    collection->items = new_items;
    collection->capacity = new_capacity;
}

int add_item(Collection *collection, char identifier, float value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        resize_collection(collection, new_capacity);
        if (collection->items == NULL) { // Handle realloc failure
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i].identifier == identifier) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Identifier already exists
        }
    }

    Item new_item = { .identifier = identifier, .value = value };
    collection->items[collection->count++] = new_item;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_item_value(Collection *collection, char identifier, float new_value) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i].identifier == identifier) {
            collection->items[i].value = new_value;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Item not found
}

void free_collection(Collection *collection) {
    if (!collection) return;

    pthread_mutex_destroy(&collection->lock);
    free(collection->items);
    free(collection);
}

