#define CACHE_LINE_SIZE 64
#define LARGE_PAGE_SIZE (2 * 1024 * 1024)  // Assuming a large page size of 2MB for demonstration

typedef struct {
    int value;
} record_t;

// Structure to hold function arguments for threading
typedef struct {
    record_t *records;
    int start_index;
    int end_index;
    int lower_bound;
    int upper_bound;
} thread_args_t;

// Function prototypes
void initialize_random();
int generate_random(int min, int max);
void *initialize_records(void *args);

// The main memory management function
void manage_memory_allocation_and_initialization(
    atomic_int *size_ptr,
    int lower_bound,
    int upper_bound) {

    // Error handling and initialization setup
    if (!size_ptr || !atomic_load(size_ptr)) {
        fprintf(stderr, "Invalid size pointer or size is zero.\n");
        return;
    }

    int size = atomic_load(size_ptr);

    // Allocate memory for offset values and keys with aligned allocations
    long *offsets = (long *)aligned_alloc(CACHE_LINE_SIZE, size * sizeof(long));
    int *keys = (int *)aligned_alloc(CACHE_LINE_SIZE, size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation for offsets or keys failed.\n");
        // Ensure clean-up
        free(offsets);
        free(keys);
        return;
    }

    // Use memory pool manager to allocate records in a large page aligned manner
    record_t *records = (record_t *)mpm_allocate_aligned(LARGE_PAGE_SIZE, size * sizeof(record_t), CACHE_LINE_SIZE);

    if (!records) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize random number generator
    initialize_random();

    // Determine the number of threads based on the environment and workload
    int num_threads = 4; // This could be tuned based on hardware capabilities

    pthread_t *threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    thread_args_t *thread_args = (thread_args_t *)calloc(num_threads, sizeof(thread_args_t));

    if (!threads || !thread_args) {
        fprintf(stderr, "Memory allocation for threads or thread args failed.\n");
        // Ensure clean-up
        free(threads);
        free(thread_args);
        mpm_deallocate(records, size * sizeof(record_t));
        free(offsets);
        free(keys);
        return;
    }

    int records_per_thread = size / num_threads;

    // Launch threads to initialize records concurrently
    for (int i = 0; i < num_threads; ++i) {
        thread_args[i].records = records;
        thread_args[i].start_index = i * records_per_thread;
        thread_args[i].end_index = (i == num_threads - 1) ? size : (i + 1) * records_per_thread;
        thread_args[i].lower_bound = lower_bound;
        thread_args[i].upper_bound = upper_bound;

        if (pthread_create(&threads[i], NULL, initialize_records, &thread_args[i])) {
            fprintf(stderr, "Failed to create thread %d\n", i);
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    free(thread_args);

    // Free allocated resources at the end of function scope or upon error exit
    mpm_deallocate(records, size * sizeof(record_t));
    free(offsets);
    free(keys);
}

// Thread worker function to initialize records
void *initialize_records(void *args) {
    thread_args_t *t_args = (thread_args_t *)args;
    for (int i = t_args->start_index; i < t_args->end_index; ++i) {
        t_args->records[i].value = generate_random(t_args->lower_bound, t_args->upper_bound);
    }
    return NULL;
}

// Initialize random number generator
void initialize_random() {
    srand((unsigned int)time(NULL));  // Simple seeding for demonstration purposes
}

// Generate a pseudo-random number within a range
int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}
```

### Key Points:
- **Aligned Allocations**: Ensures cache line efficiency.
- **Large Page Allocations**: Reduces fragmentation and optimizes for distributed systems.
- **Thread Safety**: Uses pthreads with separate initialization ranges to avoid race conditions.
- **Custom Memory Pool Manager**: Assumed integration of an external memory management library (e.g., `memory_pool_manager.h`).
- **Error Handling**: Frees resources at each potential failure point.']

