#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <curl/curl.h>
#include <json-c/json.h>

#define MAX_REQUESTS_PER_MINUTE 10

// Function to write the response data into a buffer
size_t write_callback(void *ptr, size_t size, size_t nmemb, void *stream) {
    size_t real_size = size * nmemb;
    char **response_ptr = (char **)stream;

    // Allocate memory for new response part
    char *temp = realloc(*response_ptr, strlen(*response_ptr) + real_size + 1);
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        return 0;
    }
    *response_ptr = temp;

    // Copy data to the buffer
    memcpy(&( (*response_ptr)[strlen(*response_ptr)] ), ptr, real_size);
    (*response_ptr)[strlen(*response_ptr) + real_size] = '\0';

    return real_size;
}

// Function to perform HTTP request
int http_request(const char *url, char **response_body) {
    CURL *curl_handle;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_ALL);
    curl_handle = curl_easy_init();

    if (!curl_handle) {
        fprintf(stderr, "CURL initialization failed\n");
        return -1;
    }

    curl_easy_setopt(curl_handle, CURLOPT_URL, url);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, write_callback);

    // Set response_body as the callback's parameter
    curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)response_body);

    res = curl_easy_perform(curl_handle);

    if (res != CURLE_OK) {
        fprintf(stderr, "CURL request failed: %s\n", curl_easy_strerror(res));
        free(*response_body);
        *response_body = NULL;
        return -1;
    }

    curl_easy_cleanup(curl_handle);
    curl_global_cleanup();

    return 0; // Success
}

// Rate limiting function to ensure no more than 10 requests per minute
void rate_limit(int *request_count, time_t *last_reset_time) {
    if (*request_count >= MAX_REQUESTS_PER_MINUTE) {
        double elapsed = difftime(time(NULL), *last_reset_time);
        if (elapsed < 60.0) {
            sleep(60.0 - elapsed); // Sleep until a minute has passed
        }
        *request_count = 0; // Reset the request count after waiting
    } else {
        (*request_count)++;
    }

    if (difftime(time(NULL), *last_reset_time) >= 60.0) {
        *last_reset_time = time(NULL);
        *request_count = 1;
    }
}

// Function to process JSON configuration file and execute HTTP requests for URLs
void process_json_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Could not open file %s\n", filename);
        return;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *data = (char *)malloc(length + 1);
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return;
    }

    fread(data, 1, length, file);
    data[length] = '\0';
    fclose(file);

    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(data);
    if (!parsed_json) {
        fprintf(stderr, "JSON parsing failed\n");
        free(data);
        return;
    }

    struct json_object *urls_obj;
    if (json_object_object_get_ex(parsed_json, "urls", &urls_obj)) {
        size_t urls_count = 0;
        const char **urls = json_object_get_string_array(urls_obj, &urls_count);

        int request_count = 0;
        time_t last_reset_time = time(NULL);

        for (size_t i = 0; i < urls_count; ++i) {
            rate_limit(&request_count, &last_reset_time);

            char *response_body = NULL;
            if (http_request(urls[i], &response_body) == 0 && response_body) {
                printf("Response from %s:\n%s\n", urls[i], response_body);
                free(response_body);
            }
        }
    }

    json_object_put(parsed_json);
    free(data);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file.json>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_json_file(argv[1]);

    return EXIT_SUCCESS;
}
