#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

typedef struct {
    int value;
} record;

void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

unsigned int generate_random_number(int key) {
    srand(time(NULL) ^ key); // Seed with a combination of time and key
    return rand() % 101;     // Generate a number between 0 and 100
}

EVP_CIPHER *get_cipher_mode(const char *mode, int length) {
    if (strcmp(mode, "ECB") == 0) {
        return EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        return EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        return EVP_des_cfb64(); // Example for CFB with block size of 8 bytes
    }
    // Null encryption mode
    static const unsigned char zero_key[8] = {0};
    static const unsigned char iv[8] = {0};
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, NULL, NULL, zero_key, iv);
    return EVP_CIPHER_CTX_cipher(ctx);
}

EVP_CIPHER **manage_crypto_records(int num_records, int bit_shift) {
    long *offsets = safe_malloc(num_records * sizeof(long));
    int *keys = safe_malloc(num_records * sizeof(int));
    record *records = safe_malloc(num_records * sizeof(record));
    EVP_CIPHER **ciphers = safe_malloc(num_records * sizeof(EVP_CIPHER *));

    const char *modes[] = {"ECB", "EDE", "EDE3", "CFB"};
    int num_modes = 4;

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand(); // Example offset generation
        keys[i] = offsets[i] >> bit_shift;
        records[i].value = generate_random_number(keys[i]);

        const char *mode = modes[i % num_modes];
        ciphers[i] = get_cipher_mode(mode, 8); // DES key length is 8 bytes

        if (!ciphers[i]) {
            fprintf(stderr, "Cipher initialization failed\n");
            free(offsets);
            free(keys);
            free(records);
            for (int j = 0; j < i; ++j) {
                EVP_CIPHER_CTX_free(ciphers[j]);
            }
            free(ciphers);
            exit(EXIT_FAILURE);
        }
    }

    return ciphers;
}

int main() {
    int num_records = 10000;
    int bit_shift = 3;

    EVP_CIPHER **ciphers = manage_crypto_records(num_records, bit_shift);

    // Use the ciphers...

    for (int i = 0; i < num_records; ++i) {
        EVP_CIPHER_CTX_free(ciphers[i]);
    }
    free(ciphers);

    return 0;
}
```

### Key Points:
- **Memory Management**: Uses `safe_malloc` to handle memory allocation failures.
- **Random Number Generation**: Seeds with a combination of the current time and key for reproducibility.
- **Cipher Modes**: Supports ECB, EDE, EDE3, and CFB using OpenSSL's EVP interface. Null encryption is simulated by initializing an empty cipher context.
- **Error Handling**: Ensures all allocated memory is freed in case of failure during any step.
- **Performance Considerations**: Uses efficient data structures and operations to handle up to 10,000 records.

Ensure you have the OpenSSL library installed and linked when compiling this code.']

['Below is an outline of how you might implement the described file processing system in JavaScript using Node.js, along with a C-based component for the multi-threaded collection manager.

### JavaScript Asynchronous File Processing System

```javascript
const fs = require('fs');
const path = require('path');
const { pipeline } = require('stream/promises');
const zlib = require('zlib');

async function processDirectories(directories) {
    try {
        for (const directory of directories) {
            const files = await getFiles(directory);
            await processDirectory(files);
        }
    } catch (error) {
        console.error('Error processing directories:', error);
    }
}

function* getFilesRecursively(dir) {
    const entries = await fs.promises.readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
        const res = path.resolve(dir, entry.name);
        if (entry.isDirectory()) {
            yield* getFilesRecursively(res);
        } else {
            yield res;
        }
    }
}

async function getFiles(directory) {
    return [...getFilesRecursively(directory)];
}

async function processDirectory(files) {
    try {
        const pipelineStream = files.reduce((prev, file) => prev.pipe(fs.createReadStream(file)), fs.createWriteStream('output.gz'));
        await pipeline(pipelineStream, zlib.createGzip());
    } catch (error) {
        console.error(`Error processing file ${file}:`, error);
    }
}

// Example usage:
const directories = ['path/to/dir1', 'path/to/dir2'];
processDirectories(directories);
```

### C-based Multi-threaded Collection Manager

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdatomic.h>

#define MAX_ITEMS 10000
#define STRING_MAX_LEN 10

typedef struct {
    float value;
    int number;
    char *str;
} Item;

typedef struct {
    Item items[MAX_ITEMS];
    atomic_size_t count;
    pthread_mutex_t lock;
} CollectionManager;

CollectionManager manager = {.count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};

void* addItem(void* arg) {
    Item item = *(Item*)arg;
    pthread_mutex_lock(&manager.lock);

    if (atomic_fetch_add_explicit(&manager.count, 1, memory_order_relaxed) < MAX_ITEMS) {
        manager.items[manager.count - 1] = item;
    }

    pthread_mutex_unlock(&manager.lock);
    return NULL;
}

void* getItem(void* arg) {
    size_t index = *(size_t*)arg;
    Item *item = NULL;

    pthread_mutex_lock(&manager.lock);

    if (index < manager.count) {
        item = &manager.items[index];
    }

    pthread_mutex_unlock(&manager.lock);
    return item;
}

void initializeItem(Item* item, float value, int number, const char* str) {
    item->value = value;
    item->number = number;
    size_t len = strlen(str);
    if (len > STRING_MAX_LEN) len = STRING_MAX_LEN;

    item->str = (char*)malloc(len + 1);
    strncpy(item->str, str, len);
    item->str[len] = '\0';
}

void cleanup() {
    for (size_t i = 0; i < manager.count; ++i) {
        free(manager.items[i].str);
    }
}

int main() {
    pthread_t threads[10];
    Item items[10];

    // Initialize items
    for (int i = 0; i < 10; ++i) {
        char str[STRING_MAX_LEN + 1];
        snprintf(str, sizeof(str), "Str%d", rand() % STRING_MAX_LEN);
        initializeItem(&items[i], (float)i, i, str);

        pthread_create(&threads[i], NULL, addItem, &items[i]);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Retrieve an item
    size_t index = 5;
    Item* retrievedItem = getItem(&index);
    if (retrievedItem != NULL) {
        printf("Retrieved: %f, %d, %s\n", retrievedItem->value, retrievedItem->number, retrievedItem->str);
    }

    cleanup();
    return 0;
}
```

### Key Considerations

- **JavaScript Component**: Utilizes Node.js streams and `zlib` for efficient file handling and compression. Handles errors gracefully with try-catch blocks.

- **C-based Component**: Uses pthreads for concurrency, atomic operations for thread safety, and a mutex to manage access to the shared collection. Memory management is handled manually, including allocation and deallocation of strings.

- **Error Handling**: Both components include basic error handling. In production systems, more robust logging and recovery mechanisms would be necessary.

- **Scalability**: The JavaScript component leverages streaming to handle large files efficiently. The C-based manager uses a mutex to prevent race conditions, which could be optimized further with finer-grained locking or lock-free data structures for higher concurrency scenarios.

This design provides a foundation that can be expanded and refined based on specific application requirements and performance testing results.']

