bool safe_multiply(size_t a, size_t b, size_t *result) {
    if (a == 0 || b == 0) {
        *result = 0;
        return true;
    }
    __uint128_t large_a = (__uint128_t)a;
    __uint128_t large_b = (__uint128_t)b;
    if (large_b > ULLONG_MAX / a) {
        return false; // overflow
    }
    *result = (size_t)(large_a * large_b);
    return true;
}

int pseudo_random(int seed) {
