    float cameraSpeed = atof((char *)cameraSpeedAttr);
    xmlFree(cameraSpeedAttr);

    xmlFreeDoc(doc);

    // Initialize memory pool
    world.memory_pool = create_memory_pool(1024 * 1024); // Example size

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate and initialize arrays using the custom memory pool
    world.offsets = (long *)allocate_from_pool(world.memory_pool, sizeof(long) * 100);
    world.keys = (int *)allocate_from_pool(world.memory_pool, sizeof(int) * 100);

    // Example record count based on XML configuration
    size_t record_count = width * height;
    world.record_count = record_count;

    world.records = (Record *)allocate_from_pool(world.memory_pool, sizeof(Record) * record_count);

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < record_count; ++i) {
        world.records[i].tileSize = tileSize;
        world.records[i].width = width;
        world.records[i].height = height;
        world.records[i].cameraSpeed = cameraSpeed;
    }
    pthread_mutex_unlock(&mutex);

    return world;
}

void cleanupGameWorld(GameWorld *world) {
    if (world->memory_pool) destroy_memory_pool(world->memory_pool);
}
