void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->base == NULL || size > pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void *ptr = pool->base;
    pool->base += size;  // Move base pointer forward
    pool->size -= size;  // Reduce available size

