typedef struct {
    int tileSize;
    int width;
    int height;
    float cameraSpeed;
} Record;

typedef struct MemoryPool {
    size_t block_size;
    unsigned char* pool;
    size_t pool_size;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool mem_pool;

void initialize_memory_pool(size_t size, size_t block_size) {
    pthread_mutex_init(&mem_pool.lock, NULL);
    mem_pool.pool = (unsigned char*)malloc(size);
    mem_pool.pool_size = size;
    mem_pool.block_size = block_size;
    mem_pool.offset = 0;
}

void* allocate_from_pool() {
    pthread_mutex_lock(&mem_pool.lock);

    if (mem_pool.offset + mem_pool.block_size > mem_pool.pool_size) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&mem_pool.lock);
        return NULL;
    }

    void* block = &mem_pool.pool[mem_pool.offset];
    mem_pool.offset += mem_pool.block_size;

    pthread_mutex_unlock(&mem_pool.lock);
    return block;
}

void free_memory_pool() {
    free(mem_pool.pool);
    pthread_mutex_destroy(&mem_pool.lock);
}

