    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long* offsets = (long*)allocate_from_pool();
    int* keys = (int*)allocate_from_pool();

    size_t record_count = 10; // Assume some default or retrieved value
    Record* records = (Record*)malloc(record_count * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        if (offsets) free(offsets);
        if (keys) free(keys);
        if (records) free(records);
        pthread_mutex_destroy(&lock);
        return;
    }

    memset(records, 0, record_count * sizeof(Record));

    // Load configuration settings
    load_configuration_from_xml(xmlFilePath, &records, &record_count);

    if (!records || record_count == 0) {
        fprintf(stderr, "Invalid or missing XML data\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_destroy(&lock);
        return;
    }

    // Thread-safe initialization of records
    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&lock);

        // Assume values are loaded from XML
        records[i].tileSize = 32; // Example value
        records[i].width = 800;
        records[i].height = 600;
        records[i].cameraSpeed = 1.0f;

