#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

// Define structures
typedef struct {
    int value;
} Record;

typedef struct {
    char info[128];
} Metadata;

typedef struct {
    long offset;
    int key;
    Record record;
    Metadata metadata;
    time_t timestamp; // for garbage collection based on age
} DataRecord;

#define MAX_RECORDS 1000

// Memory pool and synchronization primitives
DataRecord* memory_pool[MAX_RECORDS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

// Helper functions
void initialize_memory_pool() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        memory_pool[i] = NULL;
    }
}

DataRecord* allocate_record(long offset, int key, Record record, Metadata metadata) {
    pthread_mutex_lock(&lock);

    // Find a free slot or perform garbage collection
    DataRecord* new_record = NULL;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (memory_pool[i] == NULL || time(NULL) - memory_pool[i]->timestamp > 60) { // 1-minute age threshold
            new_record = malloc(sizeof(DataRecord));
            if (!new_record) {
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            *new_record = (DataRecord){.offset = offset, .key = key, .record = record, .metadata = metadata, .timestamp = time(NULL)};
            memory_pool[i] = new_record;
            pthread_mutex_unlock(&lock);
            return new_record;
        }
    }

    // Memory exhausted
    fprintf(stderr, "Memory pool exhausted.\n");
    pthread_mutex_unlock(&lock);
    return NULL;
}

void free_record(DataRecord* record) {
    if (record) {
        free(record);
    }
}

DataRecord* get_record(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (memory_pool[i] && memory_pool[i]->key == key) {
            pthread_mutex_unlock(&lock);
            return memory_pool[i];
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void update_record(int key, Record new_record_data) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (memory_pool[i] && memory_pool[i]->key == key) {
            memory_pool[i]->record.value = new_record_data.value;
            memory_pool[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    pthread_mutex_unlock(&lock);
}

void simulate_workload() {
    // Initialize the pool
    initialize_memory_pool();

    // Simulate inserting records
    for (int i = 0; i < MAX_RECORDS + 50; i++) { // Exceed max to test exhaustion
        Record record = {.value = i};
        Metadata metadata = {.info = "Sample"};
        allocate_record(i, i, record, metadata);
    }

    // Simulate updates and queries
    for (int i = 0; i < MAX_RECORDS / 2; i++) {
        update_record(i, (Record){.value = i * 10});
        DataRecord* record = get_record(i);
        if (record) {
            printf("Record %d: Value %d\n", i, record->record.value);
        }
    }

    // Simulate concurrent access
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, (void* (*)(void*))simulate_workload, NULL);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    simulate_workload();
    return 0;
}
