['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 1000
#define METADATA_SIZE sizeof(int)
#define INITIAL_POOL_SIZE (MAX_RECORDS * (sizeof(int) + METADATA_SIZE))

typedef struct {
    int key;
    int metadata;
    size_t data_size;
    char *data;
} Record;

typedef struct {
    Record *records[MAX_RECORDS];
    pthread_mutex_t lock;
    size_t record_count;
    size_t memory_pool_size;
    unsigned char memory_pool[];
} RecordStore;

static void initialize_memory_pool(RecordStore *store) {
    store->record_count = 0;
}

RecordStore* create_record_store(size_t max_capacity, size_t initial_memory_pool_size) {
    if (max_capacity > MAX_RECORDS || initial_memory_pool_size < INITIAL_POOL_SIZE) {
        fprintf(stderr, "Invalid configuration.\n");
        return NULL;
    }

    RecordStore *store = (RecordStore*)malloc(sizeof(RecordStore) + initial_memory_pool_size);
    if (!store) {
        perror("Failed to allocate memory for record store");
        return NULL;
    }

    initialize_memory_pool(store);
    pthread_mutex_init(&store->lock, NULL);
    store->memory_pool_size = initial_memory_pool_size;

    return store;
}

void destroy_record_store(RecordStore *store) {
    if (!store) return;

    pthread_mutex_lock(&store->lock);

    for (size_t i = 0; i < store->record_count; ++i) {
        free(store->records[i]->data);
        free(store->records[i]);
    }

    pthread_mutex_unlock(&store->lock);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

int insert_record(RecordStore *store, int key, int metadata, const char *data, size_t data_size) {
    if (pthread_mutex_trylock(&store->lock) != 0) {
        return -1; // Could not acquire lock
    }

    if (store->record_count >= MAX_RECORDS || store->memory_pool_size < data_size + METADATA_SIZE + sizeof(int)) {
        fprintf(stderr, "Capacity reached or insufficient memory pool.\n");
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate record");
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    new_record->key = key;
    new_record->metadata = metadata;
    new_record->data_size = data_size;

    new_record->data = (char*)store->memory_pool + store->record_count * (METADATA_SIZE + sizeof(int));
    memcpy(new_record->data, data, data_size);

    store->records[store->record_count++] = new_record;
    store->memory_pool_size -= (data_size + METADATA_SIZE + sizeof(int));

    pthread_mutex_unlock(&store->lock);
    return 0;
}

Record* find_record(RecordStore *store, int key) {
    if (pthread_mutex_trylock(&store->lock) != 0) {
        return NULL; // Could not acquire lock
    }

    for (size_t i = 0; i < store->record_count; ++i) {
        if (store->records[i]->key == key) {
            pthread_mutex_unlock(&store->lock);
            return store->records[i];
        }
    }

    pthread_mutex_unlock(&store->lock);
    return NULL;
}

int main() {
    RecordStore *store = create_record_store(MAX_RECORDS, INITIAL_POOL_SIZE);

    if (!store) {
        fprintf(stderr, "Failed to create record store.\n");
        return EXIT_FAILURE;
    }

    char data[] = "Sample binary data";
    insert_record(store, 1, 100, data, sizeof(data));

    Record *record = find_record(store, 1);
    if (record) {
        printf("Record found: Key=%d, Metadata=%d, DataSize=%zu, Data=%s\n",
               record->key, record->metadata, record->data_size, record->data);
    }

    destroy_record_store(store);

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a thread-safe record store with dynamic memory management using a custom memory pool. It supports insertion and lookup operations, ensuring that concurrent access is handled appropriately with minimal lock contention for high-performance scenarios. The structure allows easy extension for more features such as advanced querying and additional metadata handling.']

