```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Item {
    char id;
    unsigned int value;
} Item;

typedef struct TreeNode {
    Item *item;
    struct TreeNode *left, *right;
    int height;
} TreeNode;

typedef struct BST {
    TreeNode *root;
    pthread_mutex_t lock;
    size_t node_count;
    double total_search_time;
    size_t search_operations;
} BST;

// Function prototypes
void initialize_memory_manager(size_t doubles_size, size_t structs_size);
Item* create_item(char id, unsigned int value);
BST* create_bst();
int insert_bst(BST *bst, Item *item);
int delete_bst(BST *bst, char id);
Item* find_bst(BST *bst, char id);
void rebalance_bst_if_needed(BST *bst);
void log_operation(const char *operation, const char *status, clock_t timestamp);
void serialize_bst(BST *bst, FILE *file);
BST* deserialize_bst(FILE *file);
int compare_items(Item *a, Item *b);

// Initialize the memory manager
void initialize_memory_manager(size_t doubles_size, size_t structs_size) {
    // Allocate arrays for double values and struct pointers with custom sizes.
    double *doubles_array = (double *)malloc(doubles_size * sizeof(double));
    Item **structs_array = (Item **)malloc(structs_size * sizeof(Item *));

