['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_SIZE 10
#define RESIZE_FACTOR 2
#define MAX_INT_VALUE 1000

typedef struct {
    int value;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} data_pool_t;

// Memory pool for optimized allocation
#define POOL_SIZE 1024 * 64 // 64KB pool

static char memory_pool[POOL_SIZE];
static size_t pool_offset = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* custom_malloc(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (pool_offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        return malloc(size);
    }
    void *ptr = &memory_pool[pool_offset];
    pool_offset += size;
    pthread_mutex_unlock(&pool_lock);
    log_allocation(size);
    return ptr;
}

void custom_free(void *ptr, size_t size) {
    // Custom free logic if necessary
    log_deallocation(size);
}

void log_allocation(size_t size) {
    printf("Allocated %zu bytes at %s\n", size, __func__);
}

void log_deallocation(size_t size) {
    printf("Deallocated %zu bytes at %s\n", size, __func__);
}

data_pool_t* create_data_pool() {
    data_pool_t *pool = custom_malloc(sizeof(data_pool_t));
    pool->capacity = INITIAL_SIZE;
    pool->count = 0;

    pool->offsets = custom_malloc(pool->capacity * sizeof(long));
    pool->keys = custom_malloc(pool->capacity * sizeof(int));
    pool->records = custom_malloc(pool->capacity * sizeof(record_t));

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void resize_data_pool(data_pool_t *pool) {
    size_t new_capacity = pool->capacity * RESIZE_FACTOR;

    long *new_offsets = custom_malloc(new_capacity * sizeof(long));
    int *new_keys = custom_malloc(new_capacity * sizeof(int));
    record_t *new_records = custom_malloc(new_capacity * sizeof(record_t));

    memcpy(new_offsets, pool->offsets, pool->count * sizeof(long));
    memcpy(new_keys, pool->keys, pool->count * sizeof(int));
    memcpy(new_records, pool->records, pool->count * sizeof(record_t));

    custom_free(pool->offsets, pool->capacity * sizeof(long));
    custom_free(pool->keys, pool->capacity * sizeof(int));
    custom_free(pool->records, pool->capacity * sizeof(record_t));

    pool->offsets = new_offsets;
    pool->keys = new_keys;
    pool->records = new_records;
    pool->capacity = new_capacity;
}

void initialize_record(record_t *record) {
    record->value = rand() % MAX_INT_VALUE + 1;
}

void add_record(data_pool_t *pool, long offset, int key) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        resize_data_pool(pool);
    }

    pool->offsets[pool->count] = offset;
    pool->keys[pool->count] = key;
    initialize_record(&pool->records[pool->count]);

    pool->count++;
    pthread_mutex_unlock(&pool->lock);
}

void serialize_data_pool(data_pool_t *pool, const char *filename, int binary_format) {
    FILE *file = fopen(filename, binary_format ? "wb" : "w");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&pool->lock);
    fwrite(&pool->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < pool->count; ++i) {
        if (binary_format) {
            fwrite(&(pool->offsets[i]), sizeof(long), 1, file);
            fwrite(&(pool->keys[i]), sizeof(int), 1, file);
            fwrite(&(pool->records[i].value), sizeof(int), 1, file);
        } else {
            fprintf(file, "%ld %d %d\n", pool->offsets[i], pool->keys[i], pool->records[i].value);
        }
    }

    pthread_mutex_unlock(&pool->lock);
    fclose(file);
}

void deserialize_data_pool(data_pool_t *pool, const char *filename, int binary_format) {
    FILE *file = fopen(filename, binary_format ? "rb" : "r");
    if (!file) {
        perror("Failed to open file for deserialization");
        return;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&pool->lock);
    if (count > pool->capacity) {
        resize_data_pool(pool);
    }
    pool->count = count;

    for (size_t i = 0; i < count; ++i) {
        if (binary_format) {
            fread(&(pool->offsets[i]), sizeof(long), 1, file);
            fread(&(pool->keys[i]), sizeof(int), 1, file);
            fread(&(pool->records[i].value), sizeof(int), 1, file);
        } else {
            fscanf(file, "%ld %d %d", &pool->offsets[i], &pool->keys[i], &pool->records[i].value);
        }
    }

    pthread_mutex_unlock(&pool->lock);
    fclose(file);
}

void free_data_pool(data_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);
    custom_free(pool->offsets, pool->capacity * sizeof(long));
    custom_free(pool->keys, pool->capacity * sizeof(int));
    custom_free(pool->records, pool->capacity * sizeof(record_t));
    custom_free(pool, sizeof(data_pool_t));

    pthread_mutex_unlock(&pool->lock);
}

int main() {
    srand(time(NULL));

    data_pool_t *data = create_data_pool();
    for (int i = 0; i < 15; ++i) { // Add more records to trigger resizing
        add_record(data, i * 10, i + 1);
    }

    serialize_data_pool(data, "data.txt", 0); // Serialize in text format
    deserialize_data_pool(data, "data.txt", 0);

    free_data_pool(data);
    return 0;
}
