extern int create_user_in_db(const char *name, const char *email, const char *password);
extern int update_user_in_db(int id, const char *name, const char *email, const char *password);
extern int delete_user_from_db(int id);
extern void log_error(const char *message);

pthread_mutex_t db_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    char message[50];
} JsonResponse;

JsonResponse* manage_user_account(int id, const char *name, const char *email, const char *password, const char *sub_action) {
    JsonResponse *response = malloc(sizeof(JsonResponse));
    if (!response) {
        log_error("Memory allocation failed");
        return NULL;
    }

    // Validate input data
    if (validate_user_data(name, email, password) != 0) {
        strcpy(response->message, "{\"message\": \"error\"}");
        return response;
    }

    pthread_mutex_lock(&db_lock);

    if (strcmp(sub_action, "delete") == 0) {
        if (id <= 0 || delete_user_from_db(id) != 0) {
            strcpy(response->message, "{\"message\": \"error\"}");
        } else {
            strcpy(response->message, "{\"message\": \"success\"}");
        }
    } else {
        int auth_success = authenticate_user_via_api(email, password);
        if (!auth_success) {
            pthread_mutex_unlock(&db_lock);
            log_error("Authentication failed");
            free(response);
            return NULL;
        }

        if (id > 0) {
            // Update user
            if (update_user_in_db(id, name, email, password) != 0) {
                strcpy(response->message, "{\"message\": \"error\"}");
            } else {
                strcpy(response->message, "{\"message\": \"success\"}");
            }
        } else {
            // Create new user
            if (create_user_in_db(name, email, password) != 0) {
                strcpy(response->message, "{\"message\": \"error\"}");
            } else {
                strcpy(response->message, "{\"message\": \"success\"}");
            }
        }
    }

    pthread_mutex_unlock(&db_lock);
    return response;
}

// Function to free allocated memory for JsonResponse
void free_json_response(JsonResponse *response) {
    if (response) {
        free(response);
    }
}
