    int value;
};

class MemoryPool {
private:
    struct Block {
        Block* next;
    };

    std::mutex pool_mutex;
    Block* free_list = nullptr;

public:
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        if (!free_list || reinterpret_cast<size_t>(free_list) % alignof(Block)) {
            size_t block_size = sizeof(Block) + size;
            Block* block = reinterpret_cast<Block*>(new char[block_size]);
            block->next = nullptr;
            return block->next = static_cast<void*>(block + 1);
        }
        Block* free_block = free_list;
        free_list = free_list->next;
        return free_block;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(pool_mutex);
        Block* block = reinterpret_cast<Block*>(reinterpret_cast<char*>(ptr) - sizeof(Block));
        block->next = free_list;
        free_list = block;
    }
};

