void randomizeData(double* doubles, char** strings, Point* points, Record* records,
                   size_t num_elements, int range_min, int range_max, int string_length) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis_double(0.0, 1.0);
    std::uniform_int_distribution<> dis_point(-100.0f, 100.0f);
    std::uniform_int_distribution<> dis_record(range_min, range_max);

    std::string alphanum = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    auto rand_char = [&]() -> char {
        return alphanum[dis(gen) % alphanum.size()];
    };

    for (size_t i = 0; i < num_elements; ++i) {
        *doubles++ = dis_double(gen);
        strings[i] = new char[string_length + 1];
        std::generate_n(strings[i], string_length, rand_char);
        strings[i][string_length] = '\0';
        points[i].x = static_cast<float>(dis_point(gen));
        points[i].y = static_cast<float>(dis_point(gen));
        records[i].value = dis_record(gen);
    }
}

int main() {
    ConfigurationManager config_manager;
    BinaryConfigurationParser parser;

    try {
        config_manager.loadConfiguration("config.bin", &parser);

        size_t num_elements = 10; // Example size
        MemoryPool pool;

        double* doubles = reinterpret_cast<double*>(pool.allocate(num_elements * sizeof(double)));
        char** strings = reinterpret_cast<char**>(pool.allocate(num_elements * sizeof(char*)));
        Point* points = reinterpret_cast<Point*>(pool.allocate(num_elements * sizeof(Point)));
        Record* records = reinterpret_cast<Record*>(pool.allocate(num_elements * sizeof(Record)));

        randomizeData(doubles, strings, points, records, num_elements, 0, 100, 8);

        readIntegersAndFindMax();

        config_manager.releaseResources();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
