['Here is the C code that implements the `initialize_records` function based on your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef struct {
    size_t num_offsets;
    size_t num_keys;
    size_t num_records;
} Summary;

void initialize_records(size_t num_records, Summary *summary) {
    if (num_records <= 0) {
        summary->num_offsets = 0;
        summary->num_keys = 0;
        summary->num_records = 0;
        return;
    }

    // Allocate memory for offsets and keys
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        summary->num_offsets = 0;
        summary->num_keys = 0;
        summary->num_records = 0;
        return;
    }

    size_t total_records = 2 * num_records;

    // Allocate memory for Records
    Record *records = malloc(total_records * sizeof(Record));

    if (!records) {
        free(offsets);
        free(keys);
        summary->num_offsets = 0;
        summary->num_keys = 0;
        summary->num_records = 0;
        return;
    }

    // Initialize the pseudo-random number generator
    srand((unsigned int)time(NULL));

    // Populate records with unique non-consecutive integers
    for (size_t i = 0; i < total_records; ++i) {
        int value;
        do {
            value = rand() % total_records;
        } while ((i > 0 && abs(value - records[i-1].value) == 1) || 
                 (i < total_records - 1 && abs(value - (records[(i+1) % total_records].value)) == 1));

        records[i].value = value;
    }

    // Fill offsets and keys with dummy data
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand();
        keys[i] = rand();
    }

    // Prepare the summary
    summary->num_offsets = num_records;
    summary->num_keys = num_records;
    summary->num_records = total_records;

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    Summary summary;
    initialize_records(5, &summary);

    printf("Offsets: %zu, Keys: %zu, Records: %zu\n", 
           summary.num_offsets, summary.num_keys, summary.num_records);

    return 0;
}
```

### Key Points:
- The function dynamically allocates memory for `offsets`, `keys`, and `records`.
- It ensures that no two adjacent records have consecutive integer values.
- Memory is freed after use to prevent leaks.
- Handles edge cases where `num_records` is zero or negative by setting summary counts to zero.
- Uses `rand()` to generate non-consecutive integers while populating the records.']

['Below is a C implementation for the described task. This code provides a framework for managing entries with unique identifiers, timestamps, and dependencies, including concurrency handling, synchronization, and efficient memory management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Dependency {
    char *id;
    struct Dependency *next;
} Dependency;

typedef struct Entry {
    char *identifier;
    time_t last_modified;
    Dependency *dependencies;
    struct Entry *next;
} Entry;

typedef struct {
    Entry *head;
    pthread_mutex_t lock;
    size_t count;
} Collection;

void init_collection(Collection *collection) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->count = 0;
}

Entry* create_entry(const char *id) {
    Entry *entry = (Entry *)malloc(sizeof(Entry));
    entry->identifier = strdup(id);
    entry->last_modified = time(NULL);
    entry->dependencies = NULL;
    entry->next = NULL;
    return entry;
}

Dependency* add_dependency(Entry *entry, const char *dep_id) {
    Dependency *new_dep = (Dependency *)malloc(sizeof(Dependency));
    new_dep->id = strdup(dep_id);
    new_dep->next = entry->dependencies;
    entry->dependencies = new_dep;
    return new_dep;
}

void insert_entry(Collection *collection, Entry *entry) {
    pthread_mutex_lock(&collection->lock);

    Entry **ptr = &collection->head;
    while (*ptr && strcmp((*ptr)->identifier, entry->identifier) != 0) {
        ptr = &(*ptr)->next;
    }

    if (*ptr == NULL) {
        entry->next = collection->head;
        collection->head = entry;
        collection->count++;
    } else {
        free(entry->identifier);
        free(entry);
    }

    pthread_mutex_unlock(&collection->lock);
}

void verify_integrity(Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    Entry *current = collection->head;
    while (current) {
        Dependency *dep = current->dependencies;
        while (dep) {
            Entry *find = collection->head;
            int found = 0;
            while (find) {
                if (strcmp(find->identifier, dep->id) == 0) {
                    found = 1;
                    break;
                }
                find = find->next;
            }
            if (!found) {
                fprintf(stderr, "Integrity error: Dependency %s not found for entry %s\n",
                        dep->id, current->identifier);
            }
            dep = dep->next;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

void cleanup_entry(Entry *entry) {
    while (entry) {
        Entry *temp = entry;
        entry = entry->next;

        free(temp->identifier);
        Dependency *dep = temp->dependencies;
        while (dep) {
            Dependency *d_temp = dep;
            dep = dep->next;
            free(d_temp->id);
            free(d_temp);
        }
        free(temp);
    }
}

void cleanup_collection(Collection *collection) {
    pthread_mutex_lock(&collection->lock);
    cleanup_entry(collection->head);
    collection->head = NULL;
    collection->count = 0;
    pthread_mutex_unlock(&collection->lock);
}

void fetch_data_from_api(Collection *collection) {
    // Simulate API call
    pthread_mutex_lock(&collection->lock);

    Entry *new_entries[] = {create_entry("entry1"), create_entry("entry2")};
    for (int i = 0; i < sizeof(new_entries)/sizeof(Entry*); ++i) {
        insert_entry(collection, new_entries[i]);
    }

    pthread_mutex_unlock(&collection->lock);
}

void* async_process_entries(void *arg) {
    Collection *collection = (Collection *)arg;
    // Process entries asynchronously
    verify_integrity(collection);
    return NULL;
}

int main() {
    Collection collection;
    init_collection(&collection);

    fetch_data_from_api(&collection);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, async_process_entries, &collection);
    pthread_join(thread_id, NULL);

    cleanup_collection(&collection);
    pthread_mutex_destroy(&collection.lock);

    return 0;
}
```

### Key Features:

- **Concurrency**: Uses mutex locks to handle concurrent access and modifications.
- **Memory Management**: Dynamically allocates memory for entries and dependencies, with cleanup functions.
- **Integrity Verification**: Checks that all dependencies exist within the collection.
- **API Integration**: Simulates data fetching from an external API.
- **Asynchronous Processing**: Provides a basic framework for asynchronous entry processing using pthreads.

This code serves as a foundational structure. Further enhancements can include more sophisticated error handling, logging, and integration with real APIs.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Item {
    int id;
    int ref_count;
    char *metadata; // Simplified metadata as a string for demonstration.
    pthread_mutex_t lock;
    struct Item* next;
} Item;

typedef struct Page {
    Item* items_head;
    pthread_rwlock_t rwlock;
} Page;

Page* create_page() {
    Page* page = (Page*)malloc(sizeof(Page));
    if (!page) return NULL;
    page->items_head = NULL;
    pthread_rwlock_init(&page->rwlock, NULL);
    return page;
}

Item* create_item(int id, const char* metadata) {
    Item* item = (Item*)malloc(sizeof(Item));
    if (!item) return NULL;
    item->id = id;
    item->ref_count = 1;
    item->metadata = strdup(metadata); // Assuming metadata is a string for simplicity.
    pthread_mutex_init(&item->lock, NULL);
    item->next = NULL;
    return item;
}

void add_item(Page* page, Item* item) {
    if (!page || !item) return;

    pthread_rwlock_wrlock(&page->rwlock);

    Item** current = &page->items_head;
    while (*current && (*current)->id < item->id) {
        current = &(*current)->next;
    }

    item->next = *current;
    *current = item;

    pthread_rwlock_unlock(&page->rwlock);
}

Item* find_item(Page* page, int id) {
    if (!page) return NULL;

    pthread_rwlock_rdlock(&page->rwlock);

    Item* current = page->items_head;
    while (current && current->id != id) {
        current = current->next;
    }

    pthread_rwlock_unlock(&page->rwlock);
    return current;
}

void update_item(Page* page, int id, const char* new_metadata) {
    if (!page) return;

    Item* item = find_item(page, id);
    if (item) {
        pthread_mutex_lock(&item->lock);

        free(item->metadata);
        item->metadata = strdup(new_metadata);

        pthread_mutex_unlock(&item->lock);
    }
}

void remove_item(Page* page, int id) {
    if (!page) return;

    pthread_rwlock_wrlock(&page->rwlock);

    Item** current = &page->items_head;
    while (*current && (*current)->id != id) {
        current = &(*current)->next;
    }

    if (*current) {
        Item* to_remove = *current;
        *current = (*current)->next;

        pthread_mutex_lock(&to_remove->lock);
        to_remove->ref_count--;
        if (to_remove->ref_count == 0) {
            free(to_remove->metadata);
            pthread_mutex_unlock(&to_remove->lock);
            pthread_mutex_destroy(&to_remove->lock);
            free(to_remove);
        } else {
            pthread_mutex_unlock(&to_remove->lock);
        }
    }

    pthread_rwlock_unlock(&page->rwlock);
}

void cleanup_page(Page* page) {
    if (!page) return;

    pthread_rwlock_wrlock(&page->rwlock);

    Item* current = page->items_head;
    while (current) {
        Item* next = current->next;

        pthread_mutex_lock(&current->lock);
        current->ref_count--;
        if (current->ref_count == 0) {
            free(current->metadata);
            pthread_mutex_unlock(&current->lock);
            pthread_mutex_destroy(&current->lock);
            free(current);
        } else {
            pthread_mutex_unlock(&current->lock);
        }

        current = next;
    }

    pthread_rwlock_unlock(&page->rwlock);
}

void destroy_page(Page* page) {
    if (!page) return;

    cleanup_page(page);

    pthread_rwlock_destroy(&page->rwlock);
    free(page);
}
```']

['Below is an example implementation of a C function that processes input files with the specified operations using OpenSSL, handles concurrent operations, manages resources efficiently, and supports distributed processing.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>

// Function prototypes
void process_file(const char* input_path, const char* target_dir, const char* intermediate_dir, int operation);
int encrypt_decrypt_file(const char* input_path, const char* output_path, int encrypt);
int generate_verify_signature(const char* input_path, const char* output_path, int generate);
int calculate_checksum(const char* file_path, unsigned char* checksum);
void handle_error(const char* message);

// Global mutex for thread safety
pthread_mutex_t lock;

typedef struct {
    const char* input_path;
    const char* target_dir;
    const char* intermediate_dir;
    int operation;
} FileTask;

// Thread function to process a file task
void* process_task(void* arg) {
    FileTask* task = (FileTask*)arg;
    pthread_mutex_lock(&lock);
    process_file(task->input_path, task->target_dir, task->intermediate_dir, task->operation);
    pthread_mutex_unlock(&lock);
    free(arg);
    return NULL;
}

void process_files(const char** input_paths, int num_files, const char* target_dir, const char* intermediate_dir, int operation) {
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; ++i) {
        FileTask* task = malloc(sizeof(FileTask));
        if (!task) handle_error("Failed to allocate memory for file task");

        task->input_path = input_paths[i];
        task->target_dir = target_dir;
        task->intermediate_dir = intermediate_dir;
        task->operation = operation;

        if (pthread_create(&threads[i], NULL, process_task, task)) {
            handle_error("Failed to create thread");
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void process_file(const char* input_path, const char* target_dir, const char* intermediate_dir, int operation) {
    // Determine output paths
    char output_path[1024];
    snprintf(output_path, sizeof(output_path), "%s/processed_%s", target_dir, basename(input_path));

    unsigned char checksum[SHA256_DIGEST_LENGTH];
    if (calculate_checksum(input_path, checksum)) {
        printf("Checksum for %s: ", input_path);
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            printf("%02x", checksum[i]);
        }
        printf("\n");
    }

    // Perform operations
    switch (operation) {
        case 1: // Encrypt
            if (!encrypt_decrypt_file(input_path, output_path, 1)) handle_error("Encryption failed");
            break;
        case 2: // Decrypt
            if (!encrypt_decrypt_file(output_path, input_path, 0)) handle_error("Decryption failed");
            break;
        case 3: // Generate signature
            if (!generate_verify_signature(input_path, output_path, 1)) handle_error("Signature generation failed");
            break;
        case 4: // Verify signature
            if (!generate_verify_signature(output_path, input_path, 0)) handle_error("Signature verification failed");
            break;
        default:
            handle_error("Invalid operation type");
    }

    // Additional operations such as logging and retry mechanisms can be added here
}

int encrypt_decrypt_file(const char* input_path, const char* output_path, int encrypt) {
    FILE *in = fopen(input_path, "rb"), *out = fopen(output_path, "wb");
    if (!in || !out) return 0;

    EVP_CIPHER_CTX *ctx;
    unsigned char key[32] = "0123456789abcdef0123456789abcdef"; // Example key
    unsigned char iv[16] = "abcdef9876543210"; // Example IV

    int len, ciphertext_len;
    if (encrypt) {
        ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    } else {
        ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    }

    unsigned char inbuf[1024], outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
    while ((len = fread(inbuf, 1, sizeof(inbuf), in)) > 0) {
        if (encrypt) {
            EVP_EncryptUpdate(ctx, outbuf, &len, inbuf, len);
        } else {
            EVP_DecryptUpdate(ctx, outbuf, &len, inbuf, len);
        }
        fwrite(outbuf, 1, len, out);
    }

    if (encrypt) {
        EVP_EncryptFinal_ex(ctx, outbuf, &len);
    } else {
        EVP_DecryptFinal_ex(ctx, outbuf, &len);
    }
    fwrite(outbuf, 1, len, out);

    fclose(in);
    fclose(out);
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

int generate_verify_signature(const char* input_path, const char* output_path, int generate) {
    FILE *in = fopen(input_path, "rb"), *out = fopen(output_path, "wb");
    if (!in || !out) return 0;

    EVP_PKEY *pkey = EVP_PKEY_new(); // Load or generate key
    EVP_MD_CTX *mdctx;
    unsigned char sigbuf[256];

    if (generate) {
        mdctx = EVP_MD_CTX_create();
        EVP_SignInit_ex(mdctx, EVP_sha256(), NULL);
        EVP_SignUpdate(mdctx, "data", strlen("data")); // Example data
        int siglen;
        EVP_SignFinal(mdctx, sigbuf, &siglen, pkey);
        fwrite(sigbuf, 1, siglen, out);
    } else {
        mdctx = EVP_MD_CTX_create();
        EVP_VerifyInit_ex(mdctx, EVP_sha256(), NULL);
        EVP_VerifyUpdate(mdctx, "data", strlen("data")); // Example data
        int siglen;
        fread(sigbuf, 1, sizeof(sigbuf), in);
        if (!EVP_VerifyFinal(mdctx, sigbuf, siglen, pkey)) {
            handle_error("Signature verification failed");
        }
    }

    fclose(in);
    fclose(out);
    EVP_MD_CTX_free(mdctx);
    EVP_PKEY_free(pkey);
    return 1;
}

int calculate_checksum(const char* file_path, unsigned char* checksum) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return 0;

    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    unsigned char buffer[1024];
    int bytes_read;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file))) {
        SHA256_Update(&sha256, buffer, bytes_read);
    }

    SHA256_Final(checksum, &sha256);
    fclose(file);
    return 1;
}

void handle_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}
```

### Key Points:
- **Concurrency**: Uses POSIX threads to process multiple files concurrently.
- **Encryption/Decryption**: Utilizes OpenSSL's EVP functions for AES encryption.
- **Digital Signatures**: Demonstrates signature generation and verification using SHA256.
- **Checksum Calculation**: Computes SHA256 checksums for file integrity checks.
- **Error Handling**: Includes basic error handling and logging.
- **Resource Management**: Frees allocated resources to prevent leaks.

This code is a starting point and should be extended with additional error handling, logging, retry mechanisms, and integration with external systems as needed.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Node structure definition
typedef struct node {
    char* data;
    size_t length;
    void* payload;
} node;

// Hash table entry for chaining in case of collisions
typedef struct hash_entry {
    node* node;
    struct hash_entry* next;
} hash_entry;

// Array management structure
typedef struct {
    node** nodes;          // Dynamic array of pointers to nodes
    size_t capacity;       // Total allocated slots in the array
    size_t count;          // Current number of elements
    pthread_mutex_t lock;  // Mutex for thread-safe operations

    // Hash table parameters
    hash_entry** hash_table;
    size_t hash_capacity;
} node_array;

// Function to calculate a simple hash value
static unsigned long hash(const char* data, size_t length) {
    unsigned long hash = 5381;
    const char *ptr = data;
    while (*ptr && length--) {
        hash = ((hash << 5) + hash) + *ptr++;
    }
    return hash;
}

// Initialize the node array structure
void init_node_array(node_array* arr, size_t initial_capacity) {
    arr->nodes = malloc(initial_capacity * sizeof(node*));
    arr->capacity = initial_capacity;
    arr->count = 0;

    pthread_mutex_init(&arr->lock, NULL);

    // Initialize hash table
    arr->hash_capacity = 16; // Choose a prime number for better distribution
    arr->hash_table = calloc(arr->hash_capacity, sizeof(hash_entry*));

    if (!arr->nodes || !arr->hash_table) {
        perror("Failed to initialize node array");
        exit(EXIT_FAILURE);
    }
}

// Resize the dynamic array when capacity is exceeded
void resize_node_array(node_array* arr) {
    size_t new_capacity = arr->capacity * 2;
    node** new_nodes = realloc(arr->nodes, new_capacity * sizeof(node*));

    if (!new_nodes) {
        perror("Failed to resize node array");
        exit(EXIT_FAILURE);
    }

    arr->nodes = new_nodes;
    arr->capacity = new_capacity;
}

// Add a new node to the array and hash table
void add_node(node_array* arr, const char* data, size_t length, void* payload) {
    pthread_mutex_lock(&arr->lock);

    // Resize if necessary
    if (arr->count >= arr->capacity) {
        resize_node_array(arr);
    }

    // Create new node
    node* new_node = malloc(sizeof(node));
    new_node->data = strdup(data);  // Copy the string data
    new_node->length = length;
    new_node->payload = payload;

    // Insert into dynamic array
    arr->nodes[arr->count++] = new_node;

    // Calculate hash index and insert into hash table
    unsigned long hash_index = hash(data, length) % arr->hash_capacity;
    hash_entry* entry = malloc(sizeof(hash_entry));
    entry->node = new_node;
    entry->next = arr->hash_table[hash_index];
    arr->hash_table[hash_index] = entry;

    pthread_mutex_unlock(&arr->lock);
}

// Retrieve a node by data content
node* get_node_by_data(node_array* arr, const char* data) {
    unsigned long hash_index = hash(data, strlen(data)) % arr->hash_capacity;
    for (hash_entry* entry = arr->hash_table[hash_index]; entry; entry = entry->next) {
        if (entry->node->length == strlen(data) && strcmp(entry->node->data, data) == 0) {
            return entry->node;
        }
    }
    return NULL; // Node not found
}

// Cleanup function to free resources
void cleanup_node_array(node_array* arr) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->nodes[i]->data);
        free(arr->nodes[i]);
    }

    for (size_t i = 0; i < arr->hash_capacity; ++i) {
        hash_entry* entry = arr->hash_table[i];
        while (entry) {
            hash_entry* next = entry->next;
            free(entry->node->data);
            free(entry->node);
            free(entry);
            entry = next;
        }
    }

    free(arr->nodes);
    free(arr->hash_table);

    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}

// Example usage
int main() {
    node_array arr;
    init_node_array(&arr, 10);

    add_node(&arr, "example", strlen("example"), (void*)1234);

    node* retrieved = get_node_by_data(&arr, "example");
    if (retrieved) {
        printf("Node found with data: %s\n", retrieved->data);
    }

    cleanup_node_array(&arr);

    return 0;
}
```

This code provides a basic implementation of managing an array of `node` structures with dynamic resizing and hash table for efficient lookups. It includes thread safety via mutexes, memory management for the nodes and their data fields, and proper cleanup functions.']

