    // Load strings (assuming a header with string count and lengths)
    size_t stringCount;
    file.read(reinterpret_cast<char*>(&stringCount), sizeof(stringCount));
    for (size_t i = 0; i < stringCount; ++i) {
        size_t length;
        file.read(reinterpret_cast<char*>(&length), sizeof(length));
        configData.strings.push_back(std::string(length, '\0'));
        file.read(&configData.strings.back()[0], length);
    }

    // Load points
    size_t pointCount;
    file.read(reinterpret_cast<char*>(&pointCount), sizeof(pointCount));
    configData.points.resize(pointCount);
    for (auto& p : configData.points) {
        file.read(reinterpret_cast<char*>(&p.x), sizeof(float));
        file.read(reinterpret_cast<char*>(&p.y), sizeof(float));
    }

    // Load records
    size_t recordCount;
    file.read(reinterpret_cast<char*>(&recordCount), sizeof(recordCount));
    for (size_t i = 0; i < recordCount; ++i) {
        Record rec;
        file.read(reinterpret_cast<char*>(&rec.offset), sizeof(rec.offset));
        file.read(reinterpret_cast<char*>(&rec.key), sizeof(rec.key));
        file.read(reinterpret_cast<char*>(&rec.value), sizeof(rec.value));
        configData.records[rec.key] = rec;
    }
}

// Save configuration to binary
void saveConfig(const char* filename) {
    std::lock_guard<std::mutex> lock(configMutex);
    std::ofstream file(filename, std::ios::binary);

    // Save doubles
    size_t doubleCount = configData.doubles.size();
    file.write(reinterpret_cast<char*>(&doubleCount), sizeof(doubleCount));
    file.write(reinterpret_cast<const char*>(configData.doubles.data()), doubleCount * sizeof(double));

    // Save strings (with length prefix)
    size_t stringCount = configData.strings.size();
    file.write(reinterpret_cast<char*>(&stringCount), sizeof(stringCount));
    for (const auto& str : configData.strings) {
        size_t length = str.length();
        file.write(reinterpret_cast<const char*>(&length), sizeof(length));
        file.write(str.c_str(), length);
    }

    // Save points
    size_t pointCount = configData.points.size();
    file.write(reinterpret_cast<char*>(&pointCount), sizeof(pointCount));
    for (const auto& p : configData.points) {
        file.write(reinterpret_cast<const char*>(&p.x), sizeof(float));
        file.write(reinterpret_cast<const char*>(&p.y), sizeof(float));
    }

    // Save records
    size_t recordCount = configData.records.size();
    file.write(reinterpret_cast<char*>(&recordCount), sizeof(recordCount));
    for (const auto& rec : configData.records) {
        const Record& r = rec.second;
        file.write(reinterpret_cast<const char*>(&r.offset), sizeof(r.offset));
        file.write(reinterpret_cast<const char*>(&r.key), sizeof(r.key));
        file.write(reinterpret_cast<const char*>(&r.value), sizeof(r.value));
    }
}

// Function to determine the median value of an integer array
int findMedian(std::vector<int>& nums) {
    if (nums.empty()) return -1;
    std::sort(nums.begin(), nums.end());
    size_t mid = nums.size() / 2;
    return (nums.size() % 2 == 0) ? (nums[mid - 1] + nums[mid]) / 2 : nums[mid];
}

// Read integers from standard input
std::vector<int> readIntegersFromStdin(size_t count) {
    std::vector<int> numbers(count);
    for (size_t i = 0; i < count; ++i) {
        std::cin >> numbers[i];
    }
    return numbers;
}

