    std::lock_guard<std::mutex> lock(configMutex);
    configData.strings.clear();
    for (size_t i = 0; i < numStrings; ++i) {
        int length = getRandomInt(5, 15); // Example string length
        std::string str(length, ' ');
        for (char& c : str) {
