            else c = '0' + rand() % 10;
        }
        configData.strings.push_back(str);
    }

    configData.points.clear();
    for (size_t i = 0; i < numPoints; ++i) {
        Point p = {getRandomFloat(-100.0f, 100.0f), getRandomFloat(-100.0f, 100.0f)};
        configData.points.push_back(p);
    }
}

// Reload configuration
void reloadConfig(const char* filename) {
    std::lock_guard<std::mutex> lock(configMutex);
    isReloading = true;
    loadConfig(filename);
    isReloading = false;
}

