    saveConfig("updated_config.bin");

    // Read integers from standard input and find median
    std::vector<int> numbers = readIntegersFromStdin(5);
    int median = findMedian(numbers);
    std::cout << "Median is: " << median << "\n";

    // Join logger thread before exiting
    logThread.join();

    return 0;
}
