class DOMMonitor {
  constructor(selector) {
    this.selector = selector;
    this.targets = new Set();
    this.cache = new Map();
    this.observer = null;
    this.config = {
      debounceTime: 100,
      cacheExpiration: 60000, // in milliseconds
    };

    this.initializeObserver();
  }

  initializeObserver() {
    const config = { childList: true, subtree: true };
    this.observer = new MutationObserver(this.handleMutations.bind(this));
    document.querySelectorAll(this.selector).forEach((el) => {
      this.targets.add(el);
      this.fetchMetadata(el); // Initial metadata fetch
    });
    this.observer.observe(document.body, config);

    window.addEventListener('resize', this.debounce(this.refreshTargets.bind(this), this.config.debounceTime));
  }

  handleMutations(mutationsList) {
    for (const mutation of mutationsList) {
      if (mutation.type === 'childList') {
        mutation.addedNodes.forEach(node => this.handleNodeAddition(node));
        mutation.removedNodes.forEach(node => this.targets.delete(node));
      }
    }
  }

  handleNodeAddition(node) {
    if (node.nodeType === Node.ELEMENT_NODE && node.matches(this.selector)) {
      this.targets.add(node);
      this.fetchMetadata(node); // Fetch metadata when a new target is added
    }
  }

  fetchMetadata(element) {
    const elementId = element.id || element.dataset.identifier;
    if (!elementId || this.cache.has(elementId)) return;

    // Simulate API call with caching and debouncing
    fetch(`https://api.example.com/metadata/${elementId}`)
      .then(response => response.json())
      .then(data => {
        this.cache.set(elementId, { data, timestamp: Date.now() });
        this.updateElementWithMetadata(element, data);
      })
      .catch(error => console.error('Fetch error:', error));
  }

  updateElementWithMetadata(element, metadata) {
    // Update element with fetched metadata
    element.setAttribute('data-meta', JSON.stringify(metadata));
  }

  refreshTargets() {
    const currentTargets = new Set(document.querySelectorAll(this.selector));
    this.targets.forEach(el => {
      if (!currentTargets.has(el)) {
        this.observer.takeRecords().forEach(record => record.removedNodes.forEach(node => node === el && this.targets.delete(node)));
      }
    });

    currentTargets.forEach(el => {
      if (!this.targets.has(el)) this.handleNodeAddition(el);
    });
  }

  debounce(func, wait) {
    let timeout;
    return function (...args) {
      clearTimeout(timeout);
      timeout = setTimeout(() => func.apply(this, args), wait);
    };
  }

  cleanup() {
    this.observer.disconnect();
    window.removeEventListener('resize', this.debounce(this.refreshTargets.bind(this), this.config.debounceTime));
    this.targets.clear();
    this.cache.clear();
  }
}

// Usage
const domMonitor = new DOMMonitor('.dynamic-element');

window.addEventListener('beforeunload', () => domMonitor.cleanup());
```

### Key Features:
- **MutationObserver**: Efficiently monitors the DOM for changes.
- **Caching**: Reduces redundant API requests and manages cache expiration.
- **Debouncing**: Optimizes performance by reducing the frequency of updates during rapid events like window resizing.
- **Garbage Collection**: Cleans up resources on page unload to prevent memory leaks.
- **Configuration Options**: Allows customization of debounce time and cache expiration.

This code is designed for integration into a larger application, handling dependencies and ensuring stability across various scenarios."]

