// Memory Pool implementation (simplified)
class MemoryPool {
public:
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (pool_.empty() || pool_.back().first < size) {
            return ::operator new(size);
        } else {
            auto it = --std::end(pool_);
            void* ptr = it->second;
            pool_.erase(it);
            return ptr;
        }
    }

    void deallocate(void* ptr, size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        pool_.emplace_back(size, ptr);
    }

private:
    struct PoolEntry {
        size_t first;
        void* second;

        bool operator<(const PoolEntry& other) const { return first < other.first; }
    };

    std::vector<PoolEntry> pool_;
    std::mutex mutex_;
};

