using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public class HttpClientPool
{
    private static readonly HttpClientHandler Handler = new();
    private static readonly HttpClient Client = new(Handler);
    private readonly ConcurrentDictionary<string, CachedResponse> _cache = new();
    private readonly SemaphoreSlim _connectionSemaphore;

    public HttpClientPool(int maxConnections)
    {
        _connectionSemaphore = new SemaphoreSlim(maxConnections);
    }

    public async Task<List<HttpResponseMessage>> ExecuteRequestsAsync(
        List<string> urls,
        string baseUri,
        TimeSpan timeout,
        int batchSize = 10)
    {
        var tasks = new List<Task<HttpResponseMessage>>();
        for (int i = 0; i < urls.Count; i += batchSize)
        {
            var batch = urls.GetRange(i, Math.Min(batchSize, urls.Count - i));
            tasks.AddRange(ProcessBatchAsync(baseUri, batch, timeout));
        }

        return await Task.WhenAll(tasks);
    }

    private async IAsyncEnumerable<Task<HttpResponseMessage>> ProcessBatchAsync(
        string baseUri,
        List<string> batchUrls,
        TimeSpan timeout)
    {
        foreach (var url in batchUrls)
        {
            yield return ProcessRequest(baseUri, url, timeout);
        }
    }

    private async Task<HttpResponseMessage> ProcessRequest(string baseUri, string url, TimeSpan timeout)
    {
        var cachedResponse = GetFromCache(url);
        if (cachedResponse != null)
        {
            return cachedResponse;
        }

        await _connectionSemaphore.WaitAsync();
        try
        {
            var fullUrl = new Uri(new Uri(baseUri), url).ToString();
            var response = await RetryRequest(fullUrl, timeout);

            CacheResponse(url, response);
            return response;
        }
        finally
        {
            _connectionSemaphore.Release();
        }
    }

    private HttpResponseMessage GetFromCache(string url)
    {
        if (_cache.TryGetValue(url, out var cachedResponse))
        {
            if (DateTime.UtcNow - cachedResponse.Timestamp < TimeSpan.FromHours(1))
            {
                return cachedResponse.Response;
            }
            else
            {
                _cache.TryRemove(url, out _);
            }
        }

        return null;
    }

    private void CacheResponse(string url, HttpResponseMessage response)
    {
        var cachedResponse = new CachedResponse(response);
        _cache[url] = cachedResponse;
    }

    private async Task<HttpResponseMessage> RetryRequest(string url, TimeSpan timeout)
    {
        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                using var cts = new CancellationTokenSource(timeout);
                var response = await Client.GetAsync(url, cts.Token);

                if (response.IsSuccessStatusCode)
                {
                    LogRequest(url, true, response.RequestMessage.Headers.UserAgent?.ToString());
                    return response;
                }

                response.Dispose();
            }
            catch (Exception ex)
            {
                LogRequest(url, false, ex.Message);
            }
        }

        throw new HttpRequestException($"Failed to retrieve {url} after 3 attempts.");
    }

    private void LogRequest(string url, bool success, string message)
    {
        Console.WriteLine($"{DateTime.UtcNow}: Request {url} {(success ? "succeeded" : "failed")}. Message: {message}");
    }

    public class CachedResponse
    {
        public HttpResponseMessage Response { get; }
        public DateTime Timestamp { get; }

        public CachedResponse(HttpResponseMessage response)
        {
            Response = response;
            Timestamp = DateTime.UtcNow;
        }
    }
}
