public class GraphPopulator
{
    private readonly double minValue;
    private readonly double maxValue;
    private readonly double stepSize;
    private readonly Random random;

    public GraphPopulator(double minValue, double maxValue, double stepSize, int seed)
    {
        if (minValue >= maxValue) throw new ArgumentException("minValue must be less than maxValue.");
        if (stepSize <= 0) throw new ArgumentException("Step size must be positive.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.stepSize = stepSize;
        random = new Random(seed);
    }

    private double GetNextMultiple(double value)
    {
        return Math.Ceiling(value / stepSize) * stepSize;
    }

    public float GetRandomFloat()
    {
        var range = (int)((maxValue - minValue) / stepSize);
        var randomIndex = random.Next(range);
        return (float)(minValue + randomIndex * stepSize);
    }

    public int GetRandomInt()
    {
        var range = (int)((maxValue - minValue) / stepSize);
        var randomIndex = random.Next(range);
        return (int)Math.Ceiling(minValue + randomIndex * stepSize);
    }

    public List<int> GetRandomList(int count)
    {
        var list = new List<int>(count);
        for (int i = 0; i < count; i++)
            list.Add(GetRandomInt());

        return list;
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }

