#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_ENTRIES 1000000
#define EVICTION_POLICY_SIZE 10000 // Example eviction policy size

typedef struct CacheEntry {
    int key;
    long offset;
    struct CacheEntry* next; // For handling collisions using chaining
} CacheEntry;

typedef struct {
    CacheEntry** table;
    unsigned int capacity;
    pthread_mutex_t lock;
    size_t current_size;
} DistributedCache;

// Function prototypes
int init_cache(DistributedCache* cache, unsigned int capacity);
void free_cache(DistributedCache* cache);
long generate_secure_random();
int insert_entry(DistributedCache* cache, int key, long offset);
long get_offset(DistributedCache* cache, int key);
void evict_entries(DistributedCache* cache);

// Function implementations
int init_cache(DistributedCache* cache, unsigned int capacity) {
    if (!cache || capacity == 0) return -1;

    cache->capacity = capacity;
    cache->table = (CacheEntry**)calloc(capacity, sizeof(CacheEntry*));
    if (!cache->table) return -2; // Memory allocation failure

    pthread_mutex_init(&cache->lock, NULL);
    cache->current_size = 0;

    srand(time(NULL)); // Initialize random number generator
    for (unsigned int i = 0; i < capacity; ++i) {
        int key = rand() % MAX_ENTRIES;
        long offset = generate_secure_random();
        insert_entry(cache, key, offset);
    }

    return 0;
}

void free_cache(DistributedCache* cache) {
    if (!cache) return;

    for (unsigned int i = 0; i < cache->capacity; ++i) {
        CacheEntry* entry = cache->table[i];
        while (entry) {
            CacheEntry* temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(cache->table);
    pthread_mutex_destroy(&cache->lock);
}

long generate_secure_random() {
    return rand(); // Placeholder for secure random generation
}

int insert_entry(DistributedCache* cache, int key, long offset) {
    if (!cache) return -1;

    unsigned int index = (unsigned int)(key % cache->capacity);
    CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    if (!new_entry) return -2; // Memory allocation failure

    new_entry->key = key;
    new_entry->offset = offset;
    new_entry->next = NULL;

    pthread_mutex_lock(&cache->lock);

    CacheEntry* entry = cache->table[index];
    if (!entry) {
        cache->table[index] = new_entry;
    } else {
        while (entry->next) {
            entry = entry->next;
        }
        entry->next = new_entry;
    }

    ++(cache->current_size);
    evict_entries(cache);

    pthread_mutex_unlock(&cache->lock);

    return 0;
}

long get_offset(DistributedCache* cache, int key) {
    if (!cache) return -1;

    unsigned int index = (unsigned int)(key % cache->capacity);
    CacheEntry* entry = cache->table[index];

    pthread_mutex_lock(&cache->lock);

    while (entry) {
        if (entry->key == key) {
            pthread_mutex_unlock(&cache->lock);
            return entry->offset;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&cache->lock);
    return -1; // Key not found
}

void evict_entries(DistributedCache* cache) {
    if (!cache || cache->current_size <= EVICTION_POLICY_SIZE) return;

    // Simple eviction policy: Remove one entry per eviction call
    for (unsigned int i = 0; i < cache->capacity && cache->current_size > EVICTION_POLICY_SIZE; ++i) {
        CacheEntry* entry = cache->table[i];
        if (!entry || !entry->next) continue;

        // Evict the first non-root node
        CacheEntry* to_evict = entry->next;
        entry->next = to_evict->next;
        free(to_evict);
        --(cache->current_size);
    }
}

// Example usage
int main() {
    DistributedCache cache;
    if (init_cache(&cache, 1000) != 0) {
        fprintf(stderr, "Failed to initialize cache\n");
        return -1;
    }

    insert_entry(&cache, 12345, 67890);
    long offset = get_offset(&cache, 12345);

    printf("Offset for key 12345: %ld\n", offset);

    free_cache(&cache);
    return 0;
}
