#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int processStringWithLimit(const char* str, int sizeLimit, char** result, bool allowTruncation) {
    if (!str || !result) return -1;

    int strLength = strlen(str);

    if (strLength >= sizeLimit && !allowTruncation) {
        *result = NULL;
        return -1;
    }

    int newLength = (strLength + 1 < sizeLimit) ? strLength + 2 : sizeLimit; // +1 for '\0', +1 for '/'

    char* buffer = (char*)malloc(newLength);
    if (!buffer) return -1;

    if (strLength >= sizeLimit && allowTruncation) {
        strncpy(buffer, str, sizeLimit - 15); // Reserve space for truncation message
        strcat(buffer, " [TRUNCATED]");
    } else {
        strcpy(buffer, str);
    }

    buffer[newLength - 2] = '/';  // Ensure '/' is added at the end before null terminator
    buffer[newLength - 1] = '\0';

    *result = buffer;
    return 0;
}
