function getElementSelectors(node, selector, testElement) {
    if (!node || !selector || typeof testElement !== 'function') {
        return Promise.resolve([]);
    }

    let results = [];

    function traverse(currentNode) {
        if (currentNode.nodeType === Node.ELEMENT_NODE && testElement(currentNode)) {
            const matchesSelector = document.querySelector(selector).contains(currentNode);
            if (matchesSelector) {
                results.push(currentNode);
            }
        }

        for (let i = 0; i < currentNode.childNodes.length; i++) {
            traverse(currentNode.childNodes[i]);
        }
    }

    return new Promise((resolve, reject) => {
        try {
            traverse(node);
            resolve(results);
        } catch (error) {
            console.error('Error while traversing the DOM:', error);
            reject(error);
        }
    });
}
