#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    int offsetsCount;
    int keysCount;
    int recordsCount;
} Summary;

// Union-Find structure and functions
int* parent;
void initUnionFind(int n) {
    parent = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }
}

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void unionSets(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);
    if (rootX != rootY)
        parent[rootY] = rootX;
}

// Function to check if two numbers are non-consecutive
int areNonConsecutive(int a, int b) {
    return abs(a - b) > 1;
}

Summary* createDataStructures(int size) {
    if (size <= 0) {
        printf("Invalid input size.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    long *offsets = (long*)malloc(size * sizeof(long));
    int *keys = (int*)malloc(size * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    int totalRecords = 2 * size;
    Record *records = (Record*)malloc(totalRecords * sizeof(Record));
    if (!records) {
        printf("Memory allocation for records failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Populate Records with non-consecutive random values
    int *usedValues = (int*)calloc(totalRecords, sizeof(int));
    if (!usedValues) {
        printf("Memory allocation for used values failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    int currentValue = 0;
    for (int i = 0; i < totalRecords; ++i) {
        do {
            currentValue = rand() % totalRecords;
        } while (usedValues[currentValue]);

        records[i].value = currentValue;
        usedValues[currentValue] = 1;

        // Ensure non-consecutive values
        if (i > 0 && !areNonConsecutive(records[i - 1].value, records[i].value)) {
            i--; // Retry this index
        }
    }

    free(usedValues);

    // Initialize Union-Find for disjoint pair calculation
    initUnionFind(totalRecords);

    Summary *summary = (Summary*)malloc(sizeof(Summary));
    if (!summary) {
        printf("Memory allocation for summary failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    summary->offsetsCount = size;
    summary->keysCount = size;
    summary->recordsCount = totalRecords;

    // Calculate disjoint pairs and measure time
    clock_t start, end;
    int disjointPairs = 0;
    for (int i = 0; i < totalRecords - 1; ++i) {
        if (areNonConsecutive(records[i].value, records[i + 1].value)) {
            start = clock();
            unionSets(i, i + 1);
            end = clock();

            printf("Time taken for disjoint pair (%d, %d): %f ms\n", i, i + 1, (double)(end - start) / CLOCKS_PER_SEC * 1000);

            if (find(i) != find(i + 1)) {
                disjointPairs++;
            }
        }
    }

    printf("Total disjoint pairs: %d\n", disjointPairs);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(parent);
    free(summary);

    return summary;
}

int main() {
    int size = 10; // Example input size
    Summary *summary = createDataStructures(size);
    if (summary) {
        printf("Offsets: %d, Keys: %d, Records: %d\n", summary->offsetsCount, summary->keysCount, summary->recordsCount);
        free(summary);
    }
    return 0;
}
```

This code dynamically allocates memory for arrays of `long` and `int`, manages an array of `Record` structs, and uses a Union-Find structure to determine disjoint pairs. It ensures non-consecutive random integer generation and handles edge cases like zero or negative input sizes. The function returns a pointer to a `Summary` struct containing counts of the different arrays. All allocated memory is freed after processing.']

