        // Add more handlers as needed
    }

    public DataHandler createDataHandler(String name, int updateFrequencySeconds, long timeoutMillis) {
        return new DataHandler(name, () -> fetchDataFromSource(name), updateFrequencySeconds, timeoutMillis);
    }

    private String fetchDataFromSource(String sourceName) {
        // Simulate fetching data from an external source
        logger.info("Fetching data from " + sourceName);
        // Implement actual fetch logic here
        return "data";
    }

    public void start() {
        for (DataHandler handler : dataHandlers.values()) {
            scheduler.scheduleAtFixedRate(handler::process, 0, handler.getUpdateFrequencySeconds(), TimeUnit.SECONDS);
        }
    }

    static class DataHandler {
        private final String name;
        private final Function<Void, String> fetchDataFunction;
        private final int updateFrequencySeconds;
        private final long timeoutMillis;

        public DataHandler(String name, Function<Void, String> fetchDataFunction, int updateFrequencySeconds, long timeoutMillis) {
            this.name = name;
            this.fetchDataFunction = fetchDataFunction;
            this.updateFrequencySeconds = updateFrequencySeconds;
            this.timeoutMillis = timeoutMillis;
        }

        public void process() {
            executorService.submit(() -> {
                try (ExecutorService taskExecutor = Executors.newSingleThreadExecutor()) {
                    Future<String> future = taskExecutor.submit(fetchDataFunction);
                    String data = future.get(timeoutMillis, TimeUnit.MILLISECONDS);

                    // Process the data
                    processData(data);
                } catch (TimeoutException e) {
                    logger.warning("Timeout while fetching data from " + name);
                } catch (InterruptedException | ExecutionException e) {
                    logger.severe("Error processing data from " + name + ": " + e.getMessage());
                }
            });
        }

        private void processData(String data) {
            // Implement data processing logic here
            logger.info("Processed data: " + data);
        }

        public int getUpdateFrequencySeconds() {
            return updateFrequencySeconds;
        }
    }

    public static void main(String[] args) {
        AsyncDataTransferService service = new AsyncDataTransferService();
        service.start();

        // Add shutdown hook to gracefully stop the service
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            logger.info("Shutting down service...");
            service.scheduler.shutdown();
            try {
                if (!service.scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                    service.scheduler.shutdownNow();
                }
                service.executorService.shutdown();
            } catch (InterruptedException e) {
                service.executorService.shutdownNow();
            }
        }));
    }
}
