// Helper function to generate a pseudo-random non-consecutive number
int get_non_consecutive(int current, int last_value) {
    int new_value;
    do {
        new_value = rand() % 1000000; // Arbitrary large range for distribution
    } while (new_value == last_value || abs(new_value - last_value) == 1);
    return new_value;
