Summary* initialize_records(long num_records) {
    if (num_records <= 0) {
        fprintf(stderr, "Invalid number of records: %ld\n", num_records);
        return NULL;
    }

    pthread_mutex_lock(&lock);

    long total_records = 2 * num_records; // Sum of offsets and keys lengths
    Summary* summary = malloc(sizeof(Summary));
    if (!summary) {
        fprintf(stderr, "Memory allocation failed for summary.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    Record* records = malloc(total_records * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed for one or more components.\n");
        free(offsets);
        free(keys);
        free(records);
        free(summary);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    summary->num_offsets = num_records;
    summary->num_keys = num_records;
    summary->num_records = total_records;

    int last_value = -2; // Start with an impossible previous value
    for (long i = 0; i < total_records; ++i) {
        records[i].value = get_non_consecutive(i, last_value);
        last_value = records[i].value;
    }

    pthread_mutex_unlock(&lock);

    free(offsets);
    free(keys);
    free(records);

    return summary;
}

// Example main function for testing
