#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import sysv_ipc;
#include <pthread.h>
#include <unistd.h>
#include <dirent.h>
#include <ctype.h>
#include <errno.h>

#define MAX_THREADS 8

// Configuration for logging and memory management
typedef struct {
    char *output_delimiter;
    size_t chunk_size;
    int max_threads;
} Config;

// Thread-safe shared data structures
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t condition_var = PTHREAD_COND_INITIALIZER;

// Cache node for LRU policy
typedef struct Node {
    char *filename;
    FILE *file_ptr;
    struct Node *prev, *next;
} Node;

Node* head = NULL; // Head of the doubly linked list (LRU cache)
int cache_size = 0; // Current size of the cache

// Function to convert string to float if possible
float str_to_float(const char *str) {
    char *endptr;
    float result = strtof(str, &endptr);
    return (*endptr == '\0') ? result : 0.0;
}

// Compute average of last two numeric fields in a line
void process_line(char *line, const char *delimiter, FILE *log_file) {
    char *token = strtok(line, delimiter);
    float num1 = 0, num2 = 0;
    int count = 0;

    while (token != NULL) {
        if (++count >= 3) break; // Only need the last two fields
        token = strtok(NULL, delimiter);
    }

    if (token) num1 = str_to_float(token);
    if ((token = strtok(NULL, delimiter))) num2 = str_to_float(token);

    float average = (num1 + num2) / 2;
    fprintf(log_file, "Average: %.2f\n", average);
}

// Process a file
void* process_file(void *arg) {
    char *filename = (char *)arg;
    FILE *file_ptr = fopen(filename, "r");
    if (!file_ptr) return NULL;

    // Open log file for performance monitoring
    FILE *log_file = fopen("performance_log.txt", "a");

    char line[1024];
    const char *delimiter = ":";  // Example: use a configurable delimiter

    while (fgets(line, sizeof(line), file_ptr)) {
        process_line(line, delimiter, log_file);
    }

    fclose(file_ptr);
    fclose(log_file);

    return NULL;
}

// Add filename to LRU cache
void add_to_cache(char *filename) {
    pthread_mutex_lock(&cache_mutex);

    // Check if already in cache
    Node *current = head;
    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            pthread_mutex_unlock(&cache_mutex);
            return; // Already in cache
        }
        current = current->next;
    }

    // Create new node and add to front of list
    Node *new_node = malloc(sizeof(Node));
    new_node->filename = strdup(filename);
    new_node->file_ptr = NULL;  // Lazy loading
    new_node->prev = NULL;
    new_node->next = head;

    if (head != NULL) head->prev = new_node;
    head = new_node;

    cache_size++;
    pthread_mutex_unlock(&cache_mutex);

    // Evict least recently used if needed
    while (cache_size > 1000) {  // Example: max size limit
        Node *lru = head;
        pthread_mutex_lock(&cache_mutex);

        head = lru->next;
        if (head != NULL) head->prev = NULL;

        fclose(lru->file_ptr);  // Close file if open
        free(lru->filename);
        free(lru);

        cache_size--;
        pthread_mutex_unlock(&cache_mutex);
    }
}

// Get a file from the cache, or load it if not present
FILE* get_file_from_cache(char *filename) {
    pthread_mutex_lock(&cache_mutex);

    Node *current = head;
    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            // Move accessed node to front of list for LRU policy
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;

            current->next = head;
            current->prev = NULL;
            if (head != NULL) head->prev = current;
            head = current;

            pthread_mutex_unlock(&cache_mutex);
            return current->file_ptr;  // Return open file pointer
        }
        current = current->next;
    }

    FILE *file_ptr = fopen(filename, "r");
    if (file_ptr) {
        add_to_cache(filename);
        pthread_mutex_lock(&cache_mutex);
        head->file_ptr = file_ptr;  // Associate with newly added node
        pthread_mutex_unlock(&cache_mutex);
    }

    pthread_mutex_unlock(&cache_mutex);
    return file_ptr;
}

// Worker function for threading
void* worker(void *arg) {
    Config *config = (Config *)arg;

    DIR *dir = opendir(".");
    struct dirent *entry;

    if (!dir) return NULL;

    while ((entry = readdir(dir))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char *filename = entry->d_name;
        FILE *file_ptr = get_file_from_cache(filename);

        if (file_ptr) process_file((void *)filename);
    }

    closedir(dir);
    return NULL;
}

int main(int argc, char *argv[]) {
    // Get system RAM and set memory usage limits
    long total_ram = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE) / (1024 * 1024); // in MB
    size_t memory_limit = total_ram * 0.6; // Use up to 60% of RAM

    Config config;
    strcpy(config.output_delimiter, ":");
    config.chunk_size = 1024;
    config.max_threads = MAX_THREADS;

    pthread_t threads[config.max_threads];

    for (int i = 0; i < config.max_threads; ++i) {
        if (pthread_create(&threads[i], NULL, worker, &config)) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < config.max_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Processing completed.\n");

    return EXIT_SUCCESS;
}
