#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char *data;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
} DynamicArray;

void initializeDynamicArray(DynamicArray *array, size_t initialCapacity) {
    array->capacity = initialCapacity;
    array->count = 0;
    array->records = (Record **)malloc(array->capacity * sizeof(Record *));
}

void freeDynamicArray(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i]) {
            free(array->records[i]->data);
            free(array->records[i]);
        }
    }
    free(array->records);
    array->records = NULL;
    array->capacity = 0;
    array->count = 0;
}

void resizeArrayIfNeeded(DynamicArray *array) {
    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        Record **newRecords = (Record **)realloc(array->records, newCapacity * sizeof(Record *));
        if (!newRecords) {
            perror("Failed to resize dynamic array");
            exit(EXIT_FAILURE);
        }
        array->records = newRecords;
        array->capacity = newCapacity;
    }
}

void generateRandomString(char **str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    *str = (char *)malloc((length + 1) * sizeof(char));
    if (*str == NULL) {
        perror("Failed to allocate memory for string");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < length; ++i) {
        size_t index = rand() % (sizeof(charset) - 1);
        (*str)[i] = charset[index];
    }
    (*str)[length] = '\0';
}

void insertRecord(DynamicArray *array, int id, time_t timestamp, char *data, size_t dataLength) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i]->id == id) {
            printf("Duplicate ID detected. Skipping insertion.\n");
            return;
        }
    }

    resizeArrayIfNeeded(array);

    Record *newRecord = (Record *)malloc(sizeof(Record));
    if (!newRecord) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    newRecord->id = id;
    newRecord->timestamp = timestamp;

    char *randomString;
    generateRandomString(&randomString, dataLength);
    free(newRecord->data); // Prevent double-free
    newRecord->data = randomString;

    array->records[array->count++] = newRecord;
}

void deleteRecord(DynamicArray *array, int id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->records[i]->id == id) {
            free(array->records[i]->data);
            free(array->records[i]);

            array->records[i] = array->records[--array->count];
            return;
        }
    }

    printf("Record with ID %d not found.\n", id);
}

void populateRecords(DynamicArray *array, size_t numRecords, size_t stringLength) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        int uniqueId = rand() % 10000 + 1;
        time_t currentTimestamp = time(NULL);
        char randomString[stringLength + 1];
        generateRandomString(&randomString, stringLength);

        insertRecord(array, uniqueId, currentTimestamp, randomString, stringLength);
    }
}

// Example usage
int main() {
    DynamicArray array;
    initializeDynamicArray(&array, 10);

    populateRecords(&array, 15, 8);

    // Assume some operations here (insertions/deletions)

    freeDynamicArray(&array);

    return 0;
}
