<?php

// Load vendor autoloader from a Git submodule
if (!file_exists(__DIR__ . '/vendor/autoload.php')) {
    shell_exec('git submodule update --init --recursive');
}
require __DIR__ . '/vendor/autoload.php';

// Load environment variables and configurations
$envConfig = parse_ini_file(__DIR__ . '/config/config.ini', true);
$environment = $envConfig['default_environment'] ?? 'production';
$currentEnvConfig = $envConfig[$environment] ?? [];

