#include <openssl/evp.h>
#include <openssl/ecdsa.h>
#include <openssl/hmac.h>
#include <stdlib.h>

typedef struct {
    unsigned char *keyBuffer;
    size_t keySize;
} CryptoLibrary;

void* generateKeyBuffer(size_t size) {
    void *buffer = malloc(size);
    if (buffer) {
        RAND_bytes(buffer, size);
    }
    return buffer;
}

unsigned char* encryptAes256(const unsigned char *plaintext, size_t plaintext_len,
                             const unsigned char *key, size_t key_size) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char ciphertext[1024];
    int len;

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        return NULL;
    }

    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    unsigned char *result = malloc(ciphertext_len + 1);
    memcpy(result, ciphertext, ciphertext_len);
    result[ciphertext_len] = '\0';

    return result;
}

int main() {
    // Sample key buffer generation
    CryptoLibrary lib;
    lib.keyBuffer = generateKeyBuffer(32); // AES-256 uses a 32-byte key
    lib.keySize = 32;

    if (lib.keyBuffer) {
        printf("Key generated successfully.\n");
        free(lib.keyBuffer);
    } else {
        fprintf(stderr, "Failed to generate key buffer.\n");
    }

    return 0;
}
