#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Item {
    int id;
    unsigned int ref_count;
    time_t last_accessed;
} Item;

typedef struct TreeNode {
    Item *items; // Dynamic array of items for this node.
    size_t num_items;
    size_t capacity;
    struct TreeNode **children; 
    size_t num_children;
    size_t children_capacity;
    pthread_rwlock_t lock;
} TreeNode;

TreeNode* create_node() {
    TreeNode *node = (TreeNode*)malloc(sizeof(TreeNode));
    if (!node) return NULL;

    node->items = NULL;
    node->num_items = 0;
    node->capacity = 4; // Initial capacity
    node->children = NULL;
    node->num_children = 0;
    node->children_capacity = 4; // Initial capacity
    pthread_rwlock_init(&node->lock, NULL);

    return node;
}

void destroy_node(TreeNode *node) {
    if (!node) return;

    for (size_t i = 0; i < node->num_items; ++i) {
        free(node->items[i].id); // Free any dynamically allocated memory
    }
    free(node->items);

    for (size_t i = 0; i < node->num_children; ++i) {
        destroy_node(node->children[i]);
    }
    free(node->children);

    pthread_rwlock_destroy(&node->lock);
    free(node);
}

void resize_items(TreeNode *node, size_t new_capacity) {
    Item *new_items = (Item*)realloc(node->items, new_capacity * sizeof(Item));
    if (!new_items) return;

    node->items = new_items;
    node->capacity = new_capacity;
}

void resize_children(TreeNode *node, size_t new_capacity) {
    TreeNode **new_children = (TreeNode**)realloc(node->children, new_capacity * sizeof(TreeNode*));
    if (!new_children) return;

    node->children = new_children;
    node->children_capacity = new_capacity;
}

int insert_item(TreeNode *root, Item item) {
    pthread_rwlock_wrlock(&root->lock);

    // Check for existing item and update
    for (size_t i = 0; i < root->num_items; ++i) {
        if (root->items[i].id == item.id) {
            root->items[i].ref_count++;
            root->items[i].last_accessed = time(NULL);
            pthread_rwlock_unlock(&root->lock);
            return 1;
        }
    }

    // If no space, resize
    if (root->num_items >= root->capacity) {
        resize_items(root, root->capacity * 2);
    }

    // Insert the new item
    root->items[root->num_items++] = item;
    pthread_rwlock_unlock(&root->lock);
    return 0;
}

int delete_item(TreeNode *root, int id) {
    pthread_rwlock_wrlock(&root->lock);

    for (size_t i = 0; i < root->num_items; ++i) {
        if (root->items[i].id == id) {
            free(root->items[i].id);
            memmove(&root->items[i], &root->items[i + 1],
                    (root->num_items - i - 1) * sizeof(Item));
            root->num_items--;

            pthread_rwlock_unlock(&root->lock);
            return 1;
        }
    }

    pthread_rwlock_unlock(&root->lock);
    return 0;
}

Item* search_item(TreeNode *root, int id) {
    pthread_rwlock_rdlock(&root->lock);

    for (size_t i = 0; i < root->num_items; ++i) {
        if (root->items[i].id == id) {
            root->items[i].last_accessed = time(NULL);
            Item *result = &root->items[i];
            pthread_rwlock_unlock(&root->lock);
            return result;
        }
    }

    pthread_rwlock_unlock(&root->lock);
    return NULL;
}

// Example of adding a child node for further expansion
int add_child(TreeNode *parent, TreeNode *child) {
    pthread_rwlock_wrlock(&parent->lock);

    if (parent->num_children >= parent->children_capacity) {
        resize_children(parent, parent->children_capacity * 2);
    }

    parent->children[parent->num_children++] = child;
    pthread_rwlock_unlock(&parent->lock);
    return 0;
}

// Example usage
int main() {
    TreeNode* root = create_node();

    Item item1 = {.id = 101, .ref_count = 1};
    insert_item(root, item1);

    Item *found = search_item(root, 101);
    if (found) {
        printf("Item found: %d\n", found->id);
    }

    delete_item(root, 101);

    destroy_node(root);
    return 0;
}
