['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int value;
    int ref_count;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
MemoryPool* create_memory_pool(size_t initial_capacity);
void free_memory_pool(MemoryPool *pool);
int add_record(MemoryPool *pool, int value);
Record* get_record(MemoryPool *pool, size_t index);
size_t total_records(const MemoryPool *pool);
int validate_range(int min, int max);

// Create a memory pool
MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->records = (Record *)calloc(initial_capacity, sizeof(Record));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;

    return pool;
}

// Free memory pool
void free_memory_pool(MemoryPool *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->records);
        free(pool);
    }
}

// Add a record to the pool
int add_record(MemoryPool *pool, int value) {
    if (!pool) return -1;

    pthread_mutex_lock(&pool->lock);

    // Resize if necessary
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record *new_records = (Record *)realloc(pool->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    // Add the record
    Record *record = &pool->records[pool->count++];
    record->value = value;
    record->ref_count = 1;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Get a record by index
Record* get_record(MemoryPool *pool, size_t index) {
    if (!pool || index >= pool->count) return NULL;

    pthread_mutex_lock(&pool->lock);

    Record *record = &pool->records[index];
    record->ref_count++;

    pthread_mutex_unlock(&pool->lock);
    return record;
}

// Total number of records
size_t total_records(const MemoryPool *pool) {
    if (!pool) return 0;

    pthread_mutex_lock((pthread_mutex_t *)&pool->lock);

    size_t count = pool->count;

    pthread_mutex_unlock((pthread_mutex_t *)&pool->lock);
    return count;
}

// Validate range for integer values
int validate_range(int min, int max) {
    if (min < INT_MIN || max > INT_MAX || min > max) {
        fprintf(stderr, "Invalid range specified.\n");
        return -1;
    }
    return 0;
}
```

