#include <string.h>
#include <dlfcn.h>
#include <openssl/evp.h>
#include <pthread.h>

#define LOG_ERROR(msg) fprintf(stderr, "Error: %s\n", msg)

typedef struct {
    void *handle;
    EVP_CIPHER *(*aes_init)(int cipher_type, const unsigned char *key, const unsigned char *iv, int enc);
    EVP_MD_CTX *(*md5_init)();
    EVP_MD_CTX *(*sha256_init)();
    RSA *(*rsa_init)(int bits, unsigned long e, BN_GENCB *cb);
} CryptoLibrary;

pthread_mutex_t crypto_lib_lock = PTHREAD_MUTEX_INITIALIZER;
CryptoLibrary cryptoLib = {NULL, NULL, NULL, NULL, NULL};

void* load_function(void *handle, const char *func_name) {
    return dlsym(handle, func_name);
}

void check_crypto_library() {
    pthread_mutex_lock(&crypto_lib_lock);

    if (cryptoLib.handle != NULL) {
        pthread_mutex_unlock(&crypto_lib_lock);
        return;
    }

    void *handle = dlopen("libcrypto.so", RTLD_LAZY | RTLD_DEEPBIND);
    if (!handle) {
        LOG_ERROR(dlerror());
        pthread_mutex_unlock(&crypto_lib_lock);
        return;
    }

    cryptoLib.handle = handle;

    cryptoLib.aes_init = (EVP_CIPHER *(*)(
                            int, const unsigned char *, const unsigned char *, int)) 
                        load_function(handle, "EVP_aes_256_cbc");
    if (!cryptoLib.aes_init) LOG_ERROR(dlerror());

    cryptoLib.md5_init = (EVP_MD_CTX *(*)()) load_function(handle, "MD5_Init");
    if (!cryptoLib.md5_init) LOG_ERROR(dlerror());

    cryptoLib.sha256_init = (EVP_MD_CTX *(*)()) load_function(handle, "SHA256_Init");
    if (!cryptoLib.sha256_init) LOG_ERROR(dlerror());

    cryptoLib.rsa_init = (RSA *(*)(
                           int, unsigned long, BN_GENCB *)) 
                        load_function(handle, "RSA_generate_key_ex");
    if (!cryptoLib.rsa_init) LOG_ERROR(dlerror());

    pthread_mutex_unlock(&crypto_lib_lock);
}

void initialize_crypto_library() {
    check_crypto_library();

    if (!cryptoLib.aes_init || !cryptoLib.md5_init || !cryptoLib.sha256_init || !cryptoLib.rsa_init) {
        LOG_ERROR("Failed to load cryptographic primitives.");
    } else {
        // Optional: Log successful initialization
        printf("Cryptographic library initialized successfully.\n");
    }
}

int main() {
    initialize_crypto_library();

    // Perform further operations with loaded primitives...

    if (cryptoLib.handle) {
        dlclose(cryptoLib.handle);
    }

    return 0;
}
