typedef union {
    double dval;
    char *sval;
} Value;

typedef struct {
    Value value;
    int timestamp;
} data_item;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

data_item* allocate_data_items(size_t count, int use_string) {
    pthread_mutex_lock(&mutex);

    // Allocate memory for the array of data items
    data_item *items = (data_item *)malloc(count * sizeof(data_item));
    if (!items) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    time_t current_time;
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        // Initialize the value
        if (use_string) {
            items[i].value.sval = (char *)malloc(20 * sizeof(char));
            if (!items[i].value.sval) {
                fprintf(stderr, "Memory allocation failed for string\n");
                free_data_items(items, count);
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
            snprintf(items[i].value.sval, 20, "%f", (double)(rand() % 1000) / 10.0);
        } else {
            items[i].value.dval = (double)(rand() % 1000) / 10.0;
        }

        // Set the timestamp
        current_time = time(NULL);
        items[i].timestamp = (int)current_time;
    }

    pthread_mutex_unlock(&mutex);

    return items;
}

void free_data_items(data_item *items, size_t count) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < count; ++i) {
        if (items[i].value.sval) {
            free(items[i].value.sval);
        }
    }

    free(items);

    pthread_mutex_unlock(&mutex);
}

int main() {
    size_t num_items = 10;
    int use_string = 1;

    data_item *data = allocate_data_items(num_items, use_string);
    if (data) {
        // Use the allocated items...

        free_data_items(data, num_items);
    }

    return 0;
}
