#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>  // For inet_pton and other networking functions
#include <netdb.h>      // For getaddrinfo
#include <time.h>       // For random number generation

// Define a record structure with an int value
typedef struct {
    int value;
} record;

#define MAX_RECORDS 1000
#define INT_RANGE_MIN -100
#define INT_RANGE_MAX 100

int resolve_hostname_to_ip(const char *hostname, char **ip_address) {
    if (hostname == NULL || ip_address == NULL) return -1; // Error code for null pointers

    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;       // Use IPv4
    hints.ai_socktype = SOCK_STREAM; // Stream socket

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -2; // Error code for failed resolution
    }

    char ipstr[INET_ADDRSTRLEN];
    if (inet_ntop(res->ai_family, &((struct sockaddr_in *)res->ai_addr)->sin_addr, ipstr, sizeof(ipstr)) == NULL) {
        freeaddrinfo(res);
        return -3; // Error code for failed IP conversion
    }

    *ip_address = strdup(ipstr);  // Allocate memory and copy the IP string

    freeaddrinfo(res);

    if (*ip_address == NULL) return -4; // Error code for allocation failure

    return 0; // Success code
}

int main() {
    char *ip_address;
    const char *hostname = "example.com";

    int status = resolve_hostname_to_ip(hostname, &ip_address);

    if (status != 0) {
        fprintf(stderr, "Error resolving hostname: %d\n", status);
        return EXIT_FAILURE;
    }

    printf("IP address of %s is %s\n", hostname, ip_address);
    free(ip_address);

    // Dynamic allocation for records
    record *records = malloc(MAX_RECORDS * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    srand(time(NULL));  // Seed the random number generator

    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i].value = rand() % (INT_RANGE_MAX - INT_RANGE_MIN + 1) + INT_RANGE_MIN;
    }

    free(records);
    return EXIT_SUCCESS;
}
