<?php

class WeatherService {
    private $apiUrl = 'https://api.weather.com/v1/location/';
    private $apiKey;
    private $cache;

    public function __construct($apiKey) {
        $this->apiKey = $apiKey;
        // Initialize cache (e.g., using a simple file-based approach)
        $this->cache = new CacheManager();
    }

    public function getWeather($locationId) {
        // Check cache first
        $cachedData = $this->cache->get($locationId);
        if ($cachedData !== null) {
            return $cachedData;
        }

        $retryCount = 3;
        while ($retryCount > 0) {
            try {
                $response = $this->fetchWeatherFromApi($locationId);

                // Cache the response
                $this->cache->set($locationId, $response);

                return $response;

            } catch (RateLimitException $e) {
                sleep(1); // Wait before retrying
                $retryCount--;
            } catch (Exception $e) {
                throw new Exception('Failed to fetch weather data: ' . $e->getMessage());
            }
        }

        throw new Exception('Max retries reached, failed to get weather data.');
    }

    private function fetchWeatherFromApi($locationId) {
        $url = $this->apiUrl . $locationId . '?apiKey=' . $this->apiKey;

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        $response = curl_exec($ch);

        if ($response === false) {
            throw new Exception(curl_error($ch));
        }

        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

        if ($httpCode == 429) { // Rate limit exceeded
            throw new RateLimitException('Rate limit exceeded');
        } elseif ($httpCode >= 400) {
            throw new Exception("Error fetching data: HTTP Code " . $httpCode);
        }

        curl_close($ch);

        return json_decode($response, true);
    }
}

class CacheManager {
    private $cacheDir = '/path/to/cache';
    private $ttl;

    public function __construct($ttl = 3600) {
        $this->ttl = $ttl;
    }

    public function get($key) {
        $filePath = $this->getCacheFilePath($key);

        if (!file_exists($filePath)) {
            return null;
        }

        $fileTime = filemtime($filePath);

        if (time() - $fileTime > $this->ttl) {
            unlink($filePath);
            return null;
        }

        return json_decode(file_get_contents($filePath), true);
    }

    public function set($key, $data) {
        $filePath = $this->getCacheFilePath($key);
        file_put_contents($filePath, json_encode($data));
    }

    private function getCacheFilePath($key) {
        return $this->cacheDir . '/' . md5($key) . '.json';
    }
}

class RateLimitException extends Exception {}

// Usage
$weatherService = new WeatherService('your_api_key');
try {
    $weatherData = $weatherService->getWeather(12345);
    print_r($weatherData);
} catch (Exception $e) {
    echo 'Error: ' . $e->getMessage();
}
