from pathlib import Path
from subprocess import check_call, CalledProcessError

class DeploymentManager:
    def __init__(self, config_sources):
        self.config = self.load_config(config_sources)

    def load_config(self, sources):
        config = {}

        # Load from local JSON file
        if 'local_json' in sources:
            with open(sources['local_json'], 'r') as f:
                config.update(json.load(f))

        # Load from external API
        if 'external_api_url' in sources:
            response = requests.get(sources['external_api_url'])
            config.update(response.json())

        # Add more configuration loading logic here if needed

        return config

    def deploy(self, environments):
        for env in environments:
            self.deploy_to_environment(env)

    def deploy_to_environment(self, environment):
        try:
            print(f"Deploying to {environment}...")

            repo_url = self.config.get('repository', {}).get(environment)
            branch = self.config.get('branch', 'main')

            if not repo_url:
                raise Exception("Repository URL not found for the environment")

            deploy_method = self.determine_deployment_method()
            clone_cmd = [deploy_method, repo_url, f"{environment}-repo"]
            check_call(clone_cmd)

            # Checkout specific branch
            check_call(['git', 'checkout', branch], cwd=f"{environment}-repo")

            # Execute deployment scripts
            self.execute_deployment_scripts(environment)

            print(f"Successfully deployed to {environment}")

        except (Exception, CalledProcessError) as e:
            print(f"Deployment failed for {environment}: {str(e)}")

    def determine_deployment_method(self):
        # Example logic to choose between HTTPS and SSH
        if self.config.get('use_ssh', False):
            return 'git clone --mirror'
        else:
            return 'git clone'

    def execute_deployment_scripts(self, environment):
        script_path = f"{environment}-repo/deploy.sh"

        try:
            check_call(['bash', script_path])
        except CalledProcessError as e:
            print(f"Deployment script failed: {str(e)}")

    def rollback(self, environments):
        # Rollback logic here (e.g., switch branches or restore backups)
        pass

    def manage_plugins(self):
        # Dynamic plugin loading and management
        plugins = self.config.get('plugins', [])

        for plugin in plugins:
            try:
                if plugin['enabled']:
                    print(f"Loading plugin: {plugin['name']}")
                    # Dynamically import and load the plugin module
                    __import__(plugin['module'])

            except ImportError as e:
                print(f"Failed to load plugin {plugin['name']}: {str(e)}")

# Example usage
