#define POOL_SIZE 1024

static DataItem* memory_pool[POOL_SIZE];
static size_t pool_index = 0;
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes for resource cleanup and error reporting
void release_data_item(DataItem* item);
void report_error(const char* message);

// Throttling mechanism
#define MAX_ITEMS_PER_SECOND 10
typedef struct {
    int tokens;
    time_t last_check;
} ThrottleControl;

ThrottleControl throttle = {MAX_ITEMS_PER_SECOND, 0};

// Function to manage allocations and initializations
DataItem* create_data_item(int is_string) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        report_error("Memory pool exhausted");
        return NULL;
    }

    DataItem* item = memory_pool[pool_index++];
    pthread_mutex_init(&item->lock, NULL);

    // Throttling logic
    time_t now = time(NULL);
    if (difftime(now, throttle.last_check) > 1.0) {
        throttle.tokens = MAX_ITEMS_PER_SECOND;
        throttle.last_check = now;
    }

    if (throttle.tokens <= 0) {
        pthread_mutex_unlock(&pool_lock);
        report_error("Throttling limit exceeded");
        return NULL;
    }

    throttle.tokens--;

    // Initialize the data item
    pthread_mutex_lock(&item->lock);

    item->timestamp = (int)now;

    if (is_string) {
        char* str = strdup("RandomString");  // Example string allocation
        if (!str) {
            report_error("Failed to allocate memory for string");
            pthread_mutex_unlock(&item->lock);
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }
        item->value.s = str;
    } else {
        item->value.d = (double)rand() / RAND_MAX;  // Example double allocation
    }

    pthread_mutex_unlock(&item->lock);
    pthread_mutex_unlock(&pool_lock);

    return item;
}

// Function to release resources for a data_item
void release_data_item(DataItem* item) {
    if (!item) return;

    pthread_mutex_lock(&item->lock);

    if (item->value.s) {
        free(item->value.s);
    }

    pthread_mutex_unlock(&item->lock);
    pthread_mutex_destroy(&item->lock);

    pthread_mutex_lock(&pool_lock);
    memory_pool[--pool_index] = item;
    pthread_mutex_unlock(&pool_lock);
}

// Error reporting function
void report_error(const char* message) {
    fprintf(stderr, "Error: %s at %ld\n", message, time(NULL));
}

int main() {
    srand(time(NULL));

    // Initialize memory pool for demonstration purposes
    for (size_t i = 0; i < POOL_SIZE; ++i) {
        memory_pool[i] = malloc(sizeof(DataItem));
        if (!memory_pool[i]) {
            fprintf(stderr, "Failed to initialize memory pool\n");
            return EXIT_FAILURE;
        }
    }

    // Example usage
    DataItem* item1 = create_data_item(0);  // Create with double
    DataItem* item2 = create_data_item(1);  // Create with string

    if (item1) {
        printf("Created data item with double: %f\n", item1->value.d);
        release_data_item(item1);
    }

    if (item2) {
        printf("Created data item with string: %s\n", item2->value.s);
        release_data_item(item2);
    }

    // Clean up
    for (size_t i = 0; i < POOL_SIZE; ++i) {
        free(memory_pool[i]);
    }

    return EXIT_SUCCESS;
}
```

This code implements a memory management system with features like memory pooling, throttling, resource cleanup, error reporting, and thread safety. It uses a simple token bucket algorithm for throttling and mutexes for synchronization to ensure thread-safe operations. The `report_error` function provides basic error logging with timestamps.']

