import os
import requests
from time import sleep
from typing import Optional, Dict, Any
import logging
import asyncio
import aiohttp

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class RateLimitError(Exception):
    pass

async def fetch_async(session: aiohttp.ClientSession, url: str, headers: dict) -> Dict[str, Any]:
    async with session.get(url, headers=headers) as response:
        if response.status == 429:
            raise RateLimitError("Rate limit exceeded")
        response.raise_for_status()
        return await response.json()

def fetch_sync(session: requests.Session, url: str, headers: dict) -> Dict[str, Any]:
    response = session.get(url, headers=headers)
    if response.status_code == 429:
        raise RateLimitError("Rate limit exceeded")
    response.raise_for_status()
    return response.json()

async def async_request(user_id: str, language: Optional[str] = None):
    url = f"https://api.usermanagement.com/profiles/{user_id}"
    headers = {
        "Authorization": f"Bearer {os.getenv('API_TOKEN')}",
        "Accept-Language": language if language else "en"
    }

    async with aiohttp.ClientSession() as session:
        retries, delay = 5, 1
        for attempt in range(retries):
            try:
                return await fetch_async(session, url, headers)
            except (aiohttp.ClientError, RateLimitError) as e:
                logger.warning(f"Attempt {attempt + 1} failed: {e}")
                if isinstance(e, aiohttp.ClientResponseError) and e.status == 429:
                    retry_after = int(e.headers.get('Retry-After', delay))
                    await asyncio.sleep(retry_after)
                else:
                    await asyncio.sleep(delay)
                    delay *= 2
        logger.error(f"Failed to fetch user data after {retries} attempts")
        return {}

def sync_request(user_id: str, language: Optional[str] = None):
    url = f"https://api.usermanagement.com/profiles/{user_id}"
    headers = {
        "Authorization": f"Bearer {os.getenv('API_TOKEN')}",
        "Accept-Language": language if language else "en"
    }

    with requests.Session() as session:
        retries, delay = 5, 1
        for attempt in range(retries):
            try:
                return fetch_sync(session, url, headers)
            except (requests.exceptions.RequestException, RateLimitError) as e:
                logger.warning(f"Attempt {attempt + 1} failed: {e}")
                if isinstance(e, requests.HTTPError) and e.response.status_code == 429:
                    retry_after = int(e.response.headers.get('Retry-After', delay))
                    sleep(retry_after)
                else:
                    sleep(delay)
                    delay *= 2
        logger.error(f"Failed to fetch user data after {retries} attempts")
        return {}

def get_user_profile(user_id: str, language: Optional[str] = None, async_call: bool = False) -> Dict[str, Any]:
    if async_call:
        return asyncio.run(async_request(user_id, language))
    else:
        return sync_request(user_id, language)
