typedef union {
    double dval;
    char* sval;
} ValueUnion;

typedef struct {
    ValueUnion value;
    int timestamp;
    unsigned long id;
} data_item;

#define MAX_ID_USAGE 10

// Mutex for protecting shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Structure to track ID usage
typedef struct {
    unsigned long id;
    int count;
} id_usage;

id_usage* id_tracker = NULL;
size_t tracker_size = 0;

void initialize_id_tracker(size_t size) {
    id_tracker = malloc(size * sizeof(id_usage));
    if (!id_tracker) {
        perror("Failed to allocate memory for ID tracker");
        exit(EXIT_FAILURE);
    }
    tracker_size = size;
}

int find_or_add_id(unsigned long id) {
    for (size_t i = 0; i < tracker_size; ++i) {
        if (id_tracker[i].id == id) return i;
    }

    // Expand array if necessary
    if (tracker_size >= size_t(-1) / sizeof(id_usage)) {
        fprintf(stderr, "ID usage limit exceeded\n");
        exit(EXIT_FAILURE);
    }

    int index = tracker_size++;
    id_tracker[index].id = id;
    id_tracker[index].count = 0;
    return index;
}

void* fetch_random_double(void* arg) {
    // Simulate network delay or failure
    if (rand() % 10 < 2) { // simulate a failure 20% of the time
        fprintf(stderr, "Failed to fetch random double\n");
        return NULL;
    }
    return malloc(sizeof(double));
}

data_item* initialize_data_item(unsigned long id, bool use_double) {
    pthread_mutex_lock(&mutex);

    int index = find_or_add_id(id);
    if (id_tracker[index].count >= MAX_ID_USAGE) {
        fprintf(stderr, "Max usage limit reached for ID %lu\n", id);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    data_item* item = malloc(sizeof(data_item));
    if (!item) {
        perror("Failed to allocate memory for data_item");
        pthread_mutex_unlock(&mutex);
        exit(EXIT_FAILURE);
    }

    int timestamp = time(NULL);
    item->timestamp = timestamp;

    if (use_double) {
        void* value_ptr = fetch_random_double(NULL);
        if (!value_ptr) {
            free(item);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        item->value.dval = *(double*)value_ptr;
        free(value_ptr);
    } else {
        char* str_value = strdup("Random String");
        if (!str_value) {
            free(item);
            pthread_mutex_unlock(&mutex);
            exit(EXIT_FAILURE);
        }
        item->value.sval = str_value;
    }

    item->id = id;
    id_tracker[index].count++;

    pthread_mutex_unlock(&mutex);

    return item;
}

void deallocate_data_item(data_item* item) {
    if (!item) return;

    pthread_rwlock_wrlock(&rwlock);

    int index = -1;
    for (size_t i = 0; i < tracker_size; ++i) {
        if (id_tracker[i].id == item->id) {
            index = i;
            break;
        }
    }

    if (index != -1 && id_tracker[index].count > 0) {
        id_tracker[index].count--;
    }

    pthread_rwlock_unlock(&rwlock);

    free(item->value.sval); // Safe to call even if not set
    free(item);
}

int main() {
    srand(time(NULL));

    size_t num_items = 100; // Example number of items

    initialize_id_tracker(num_items);

    data_item* item1 = initialize_data_item(1, true);
    data_item* item2 = initialize_data_item(1, false);

    if (item1) printf("Item 1: Double %f at time %d\n", item1->value.dval, item1->timestamp);
    if (item2) printf("Item 2: String %s at time %d\n", item2->value.sval, item2->timestamp);

    deallocate_data_item(item1);
    deallocate_data_item(item2);

    free(id_tracker);

    return 0;
}
