class MemoryPool {
public:
    MemoryPool(size_t size) : poolSize(size), pool(new char[size]), offset(0) {}

    ~MemoryPool() { delete[] pool; }

    void* allocate(size_t bytes) {
        if (offset + bytes > poolSize) throw std::bad_alloc();
        void* ptr = pool + offset;
        offset += bytes;
        return ptr;
    }

private:
    size_t poolSize;
    char* pool;
    size_t offset;
};

class CompressionStrategy {
public:
    virtual void decompress(const std::string& input, std::vector<char>& output) const = 0;
    virtual ~CompressionStrategy() {}
};

// Mock implementations for demonstration.
class ZlibDecompressor : public CompressionStrategy {
public:
    void decompress(const std::string& input, std::vector<char>& output) const override {
        // Simulate decompression
        output.assign(input.begin(), input.end());
    }
};

class LzmaDecompressor : public CompressionStrategy {
public:
    void decompress(const std::string& input, std::vector<char>& output) const override {
        // Simulate decompression
        output.assign(input.begin(), input.end());
    }
};

CompressionStrategy* createCompressor(const std::string& type) {
    if (type == "zlib") return new ZlibDecompressor();
    if (type == "lzma") return new LzmaDecompressor();
    throw std::invalid_argument("Unsupported compression type");
}

