    DataManager(const std::string& compressionType, MemoryPool& memPool)
        : compressStrategy(createCompressor(compressionType)), memoryPool(memPool) {}

    ~DataManager() {
        delete compressStrategy;
    }

    void loadDataFromFile(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filename << "\n";
