['Below is a C code implementation that addresses your requirements for managing a dynamic data structure using a custom memory pool, ensuring thread-safe operations, and allowing for future extensions.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Max memory usage in bytes (1 MB)
#define POOL_SIZE 1000               // Number of records the pool can hold

typedef struct {
    int key;
    float value;
} Record;

typedef struct {
    Record* data[POOL_SIZE];
    size_t used_size; // Current memory usage
    pthread_mutex_t lock;
} MemoryPool;

void initialize_pool(MemoryPool* pool) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        pool->data[i] = NULL;
    }
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

float random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

int add_record(MemoryPool* pool, int key, float value_range_min, float value_range_max) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used_size >= MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory usage limit exceeded\n");
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->data[i] == NULL) {
            pool->data[i] = malloc(sizeof(Record));
            if (!pool->data[i]) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&pool->lock);
                return -1;
            }
            pool->data[i]->key = key;
            pool->data[i]->value = random_float(value_range_min, value_range_max);
            pool->used_size += sizeof(Record);

            printf("Added record: Key=%d, Value=%.2f\n", key, pool->data[i]->value);
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    fprintf(stderr, "Memory pool is full\n");
    pthread_mutex_unlock(&pool->lock);
    return -1;
}

float get_record_value(MemoryPool* pool, int key) {
    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->data[i] && pool->data[i]->key == key) {
            float value = pool->data[i]->value;
            pthread_mutex_unlock(&pool->lock);
            return value;
        }
    }

    fprintf(stderr, "Record with Key=%d not found\n", key);
    pthread_mutex_unlock(&pool->lock);
    return -1.0f; // Indicate failure
}

void free_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->data[i]) {
            free(pool->data[i]);
            pool->data[i] = NULL;
        }
    }

    pool->used_size = 0;
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

int main() {
    srand(time(NULL));
    MemoryPool pool;
    initialize_pool(&pool);

    add_record(&pool, 1, 0.0f, 100.0f);
    add_record(&pool, 2, 10.0f, 20.0f);

    printf("Value for key 1: %.2f\n", get_record_value(&pool, 1));
    printf("Value for key 2: %.2f\n", get_record_value(&pool, 2));

    free_pool(&pool);
    return 0;
}
```

### Key Features:
- **Memory Pool**: Manages a fixed number of records and tracks memory usage.
- **Thread Safety**: Uses mutexes to ensure thread-safe operations.
- **Random Initialization**: Initializes record values with random floats within a specified range.
- **Logging**: Logs errors related to memory allocation and pool limits.
- **Extensibility**: The `Record` structure can be easily extended by adding new fields.

This implementation balances performance, safety, and extensibility while minimizing synchronization overhead.']

