        free(collection->data);

        fseek(file, 0, SEEK_END);
        long f_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        collection->data = malloc(f_size);
        fread(collection->data, sizeof(void*), f_size / sizeof(void*), file);
        collection->size = f_size / sizeof(void*);

        fclose(file);
    }
}

