// Thread-safe allocation from memory pool
void* allocateFromPool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->memory == NULL || pool->size < size) {
        void* newMemory = realloc(pool->memory, pool->size + size);
        if (!newMemory) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        pool->memory = newMemory;
        pool->size += size;
    }
    void* allocatedMemory = (char*)pool->memory + (pool->size - size);
    pthread_mutex_unlock(&pool->lock);
    return allocatedMemory;
}

