                throw std::runtime_error("Authentication failed");
            }

            auto data = compLib.decompress(filePath);
            deserializeData(data, memMgr);

            // Asynchronously process data
            std::future<void> asyncTask = std::async(std::launch::async, &DataProcessor::processAsynchronously, this, memMgr);
            asyncTask.wait();
        } catch (const std::exception& e) {
