    LoggingService logger_;

    std::mutex mtx_;  // For thread-safe operations

public:
    template<typename T>
    T* allocateMemory(size_t size, MemoryManager& memMgr) {
        std::lock_guard<std::mutex> lock(mtx_);
        if constexpr (std::is_same<T, double>::value)
            return reinterpret_cast<T*>(memMgr.doublePool.allocate(size));
        else if constexpr (std::is_same<T, char[]>::value)
            return reinterpret_cast<T*>(memMgr.charPool.allocate(size));
        else if constexpr (std::is_same<T, point>::value)
