typedef struct {
    char *buffer;
    unsigned long length;
} BufferInfo;

BufferInfo* allocateBuffers(unsigned int numBuffers, unsigned long bufferSize) {
    if (numBuffers <= 0 || bufferSize <= 0) return NULL;

    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for the array of structures
    BufferInfo *buffers = malloc(numBuffers * sizeof(BufferInfo));
    if (!buffers) {
        fprintf(stderr, "Memory allocation failed for buffer info structures\n");
        return NULL;
    }

    // Array to hold all buffers
    char **bufferArray = calloc(numBuffers, sizeof(char *));
    if (!bufferArray) {
        fprintf(stderr, "Memory allocation failed for buffer array\n");
        free(buffers);
        return NULL;
    }

    // Allocate memory for each buffer and fill with random data
    for (unsigned int i = 0; i < numBuffers; ++i) {
        bufferArray[i] = malloc(bufferSize);
        if (!bufferArray[i]) {
            fprintf(stderr, "Memory allocation failed for buffer %u\n", i);
            // Free previously allocated buffers and structures
            for (unsigned int j = 0; j < i; ++j) {
                free(bufferArray[j]);
            }
            free(bufferArray);
            free(buffers);
            return NULL;
        }

        // Fill the buffer with random data ensuring uniqueness
        if (!generateUniqueRandomData(bufferArray[i], bufferSize)) {
            fprintf(stderr, "Failed to generate unique random data for buffer %u\n", i);
            for (unsigned int j = 0; j <= i; ++j) {
                free(bufferArray[j]);
            }
            free(bufferArray);
            free(buffers);
            return NULL;
        }

        buffers[i].buffer = bufferArray[i];
        buffers[i].length = bufferSize;
    }

    // Return the array of BufferInfo
    return buffers;
}

// Function to generate unique random data for a given buffer
int generateUniqueRandomData(char *buffer, unsigned long length) {
    static char usedCharacters[256] = {0};
    unsigned long i;

    for (i = 0; i < length; ++i) {
        int randChar;
        do {
            randChar = rand() % 128 + 32; // Generate a printable ASCII character
        } while (usedCharacters[randChar]);

        buffer[i] = (char)randChar;
        usedCharacters[randChar] = 1;

        if (i > 0 && i % 256 == 0) {
            memset(usedCharacters, 0, sizeof(usedCharacters)); // Reset the usage array
        }
    }

    return 1; // Return success
}

// Function to free all allocated memory for buffers
void freeBuffers(BufferInfo *buffers, unsigned int numBuffers) {
    if (!buffers) return;

    for (unsigned int i = 0; i < numBuffers; ++i) {
        free(buffers[i].buffer);
    }
    free(buffers);
}

// Function to reset the state of buffer generation
void resetBufferState() {
    memset(usedCharacters, 0, sizeof(usedCharacters));
}

int main() {
    unsigned int numBuffers = 10;
    unsigned long bufferSize = 1024;

    BufferInfo *buffers = allocateBuffers(numBuffers, bufferSize);
    if (!buffers) {
        fprintf(stderr, "Failed to allocate buffers\n");
        return EXIT_FAILURE;
    }

    // Use the buffers...

    freeBuffers(buffers, numBuffers);

    return EXIT_SUCCESS;
}
