#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structures
typedef struct {
    int Server_ID;
    // Configuration data for StreamRequests, CodecCapabilities, etc.
} MediaServer;

typedef struct VersionedConfig {
    int Version_ID;
    MediaServer media_server;
    struct VersionedConfig* next;
} VersionedConfig;

typedef struct {
    int Server_ID;
    VersionedConfig* version_head;
    pthread_mutex_t lock;
    // Additional metadata for LRU caching, such as last access timestamp
    time_t last_access_time;
} MediaServerEntry;

// Global list of MediaServers
#define MAX_SERVERS 5000
MediaServerEntry media_server_list[MAX_SERVERS];
int server_count = 0;
pthread_rwlock_t global_lock = PTHREAD_RWLOCK_INITIALIZER;

// Function prototypes
void initialize_crypto();
void* add_media_server(void* args);
void* update_media_server_config(void* args);
MediaServerEntry* get_media_server_by_id(int Server_ID);
void log_operation(const char* operation, int Server_ID);

void initialize_crypto() {
    EVP_add_cipher(EVP_aes_128_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest_alias("MD5", "md5");
    // Add other cryptographic primitives as needed
}

// MediaServer operations
void add_media_server(int Server_ID) {
    pthread_rwlock_wrlock(&global_lock);
    if (server_count >= MAX_SERVERS) {
        pthread_rwlock_unlock(&global_lock);
        log_operation("Add failed: Max limit reached", Server_ID);
        return;
    }

    int index = server_count++;
    MediaServerEntry* entry = &media_server_list[index];
    entry->Server_ID = Server_ID;
    entry->version_head = NULL;
    pthread_mutex_init(&entry->lock, NULL);
    log_operation("Add", Server_ID);

    pthread_rwlock_unlock(&global_lock);
}

void update_media_server_config(int Server_ID, MediaServer media_server) {
    pthread_rwlock_wrlock(&global_lock);
    MediaServerEntry* entry = get_media_server_by_id(Server_ID);

    if (!entry) {
        pthread_rwlock_unlock(&global_lock);
        log_operation("Update failed: Not found", Server_ID);
        return;
    }

    pthread_mutex_lock(&entry->lock);

    // Add new version
    VersionedConfig* new_version = malloc(sizeof(VersionedConfig));
    new_version->media_server = media_server;
    new_version->next = entry->version_head;
    entry->version_head = new_version;

    // Update access time for LRU cache handling
    entry->last_access_time = time(NULL);

    pthread_mutex_unlock(&entry->lock);
    log_operation("Update", Server_ID);

    pthread_rwlock_unlock(&global_lock);
}

MediaServerEntry* get_media_server_by_id(int Server_ID) {
    for (int i = 0; i < server_count; ++i) {
        MediaServerEntry* entry = &media_server_list[i];
        if (entry->Server_ID == Server_ID) {
            // Update access time
            entry->last_access_time = time(NULL);
            return entry;
        }
    }
    return NULL;
}

void log_operation(const char* operation, int Server_ID) {
    time_t now = time(NULL);
    printf("[%s] Operation: %s, Server_ID: %d\n", ctime(&now), operation, Server_ID);
}

// Main function for testing
int main() {
    initialize_crypto();

    // Test adding a server
    add_media_server(1);

    // Update configuration for the server
    MediaServer media_server;
    update_media_server_config(1, media_server);

    return 0;
}
