#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    float x, y;
} point_t;

typedef struct {
    double num;
    char *str;
    point_t pt;
} geometry_t;

typedef struct {
    geometry_t geom1, geom2;
    int extra_field;
} complex_geometry_t;

#define POOL_SIZE 1024
#define STRING_LENGTH 10

// Memory pool for allocation and deallocation
char memory_pool[POOL_SIZE];
size_t pool_offset = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (pool_offset + size > POOL_SIZE) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(EXIT_FAILURE);
    }
    void *ptr = memory_pool + pool_offset;
    pool_offset += size;
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void reset_memory_pool() {
    pthread_mutex_lock(&pool_lock);
    pool_offset = 0;
    pthread_mutex_unlock(&pool_lock);
}

// Helper function to initialize a random float within range
float init_random_float(float min, float max) {
    return (float)(min + ((double)rand() / RAND_MAX) * (max - min));
}

// Helper function to generate a random alphanumeric string
void init_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length; i++) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length] = '\0';
}

// Helper function to find the largest integer in an array
int find_largest_integer(int *arr, size_t n) {
    int max_val = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
    return max_val;
}

// Thread-safe wrapper to find the largest integer
int thread_safe_find_largest_integer(int *arr, size_t n) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    int result = find_largest_integer(arr, n);
    pthread_mutex_unlock(&lock);
    return result;
}

// Function to read integers from standard input
void read_integers(int **arr, size_t *n) {
    printf("Enter the number of integers: ");
    scanf("%zu", n);
    *arr = (int*)malloc(*n * sizeof(int));
    for (size_t i = 0; i < *n; ++i) {
        scanf("%d", &((*arr)[i]));
    }
}

// Serialize data structures to disk
void serialize_data(FILE *file, int *arr, size_t n, double *double_arr, char **char_arr,
                    point_t *point_arr, geometry_t *geometry_arr, complex_geometry_t *complex_geom_arr,
                    size_t geom_count, size_t comp_geom_count) {
    fwrite(&n, sizeof(size_t), 1, file);
    fwrite(arr, sizeof(int), n, file);
    fwrite(double_arr, sizeof(double), n, file);
    for (size_t i = 0; i < n; ++i) {
        fwrite(char_arr[i], sizeof(char), strlen(char_arr[i]) + 1, file);
    }
    fwrite(point_arr, sizeof(point_t), n, file);
    fwrite(geometry_arr, sizeof(geometry_t), geom_count, file);
    fwrite(complex_geom_arr, sizeof(complex_geometry_t), comp_geom_count, file);
}

// Deserialize data structures from disk
void deserialize_data(FILE *file, int **arr, size_t *n, double **double_arr, char ***char_arr,
                      point_t **point_arr, geometry_t **geometry_arr, complex_geometry_t **complex_geom_arr,
                      size_t *geom_count, size_t *comp_geom_count) {
    fread(n, sizeof(size_t), 1, file);
    *arr = (int*)malloc(*n * sizeof(int));
    fread(*arr, sizeof(int), *n, file);
    *double_arr = (double*)allocate_from_pool(*n * sizeof(double));
    fread(*double_arr, sizeof(double), *n, file);
    *char_arr = (char**)allocate_from_pool(*n * sizeof(char*));
    for (size_t i = 0; i < *n; ++i) {
        (*char_arr)[i] = (char*)allocate_from_pool(STRING_LENGTH + 1);
        fread((*char_arr)[i], sizeof(char), STRING_LENGTH + 1, file);
    }
    *point_arr = (point_t*)allocate_from_pool(*n * sizeof(point_t));
    fread(*point_arr, sizeof(point_t), *n, file);
    *geom_count = *n; // Assuming same count for demonstration
    *geometry_arr = (geometry_t*)allocate_from_pool(*geom_count * sizeof(geometry_t));
    fread(*geometry_arr, sizeof(geometry_t), *geom_count, file);
    *comp_geom_count = *n / 2; // Example assumption
    *complex_geom_arr = (complex_geometry_t*)allocate_from_pool(*comp_geom_count * sizeof(complex_geometry_t));
    fread(*complex_geom_arr, sizeof(complex_geometry_t), *comp_geom_count, file);
}

// Main function to manage memory and handle concurrency
void dynamic_memory_management() {
    srand(time(NULL));

    size_t n;
    int *integers;

    read_integers(&integers, &n);

    double *double_array = (double*)allocate_from_pool(n * sizeof(double));
    char **char_strings = (char**)allocate_from_pool(n * sizeof(char*));
    point_t *points = (point_t*)allocate_from_pool(n * sizeof(point_t));
    geometry_t *geometries = (geometry_t*)allocate_from_pool(n * sizeof(geometry_t));
    complex_geometry_t *complex_geometries = (complex_geometry_t*)allocate_from_pool((n / 2) * sizeof(complex_geometry_t));

    for (size_t i = 0; i < n; ++i) {
        double_array[i] = init_random_float(0.0, 100.0);
        char_strings[i] = (char*)allocate_from_pool(STRING_LENGTH + 1);
        init_random_string(char_strings[i], STRING_LENGTH);

        points[i].x = init_random_float(-50.0, 50.0);
        points[i].y = init_random_float(-50.0, 50.0);

        geometries[i].num = double_array[i];
        strcpy(geometries[i].str, char_strings[i]);
        geometries[i].pt = points[i];

        if (i % 2 == 0) {
            complex_geometries[i / 2].geom1 = geometries[i];
            complex_geometries[i / 2].geom2 = geometries[i + 1];
            complex_geometries[i / 2].extra_field = rand() % 100;
        }
    }

    int max_int = thread_safe_find_largest_integer(integers, n);
    printf("Largest integer: %d\n", max_int);

    FILE *file = fopen("data.bin", "wb");
    if (file) {
        serialize_data(file, integers, n, double_array, char_strings, points,
                       geometries, complex_geometries, n, n / 2);
        fclose(file);
    }

    // Deserialization example
    int *des_integers;
    size_t des_n;
    double *des_double_arr;
    char **des_char_arr;
    point_t *des_point_arr;
    geometry_t *des_geometry_arr;
    complex_geometry_t *des_complex_geom_arr;
    size_t des_geom_count, des_comp_geom_count;

    file = fopen("data.bin", "rb");
    if (file) {
        deserialize_data(file, &des_integers, &des_n, &des_double_arr, &des_char_arr,
                         &des_point_arr, &des_geometry_arr, &des_complex_geom_arr,
                         &des_geom_count, &des_comp_geom_count);
        fclose(file);
    }

    reset_memory_pool();
    free(integers); // Note: Custom pool deallocation is not implemented
}

int main() {
    dynamic_memory_management();
    return 0;
}
