#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>
#include <errno.h>

#define MAX_URL_LENGTH 2048
#define CHUNK_SIZE 1024
#define RATE_LIMIT_SECONDS 1

typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

static pthread_mutex_t rate_limit_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned long last_request_time = 0;

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *) userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        fprintf(stderr, "Not enough memory\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = '\0';

    return realsize;
}

void rate_limit() {
    pthread_mutex_lock(&rate_limit_lock);
    unsigned long current_time = time(NULL);

    if (current_time - last_request_time < RATE_LIMIT_SECONDS) {
        usleep((RATE_LIMIT_SECONDS - (current_time - last_request_time)) * 1000000);
    }

    last_request_time = time(NULL);
    pthread_mutex_unlock(&rate_limit_lock);
}

char* http_get_request(const char *url) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if(curl) {
        MemoryStruct chunk;
        chunk.memory = malloc(1);  
        chunk.size = 0; 

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        rate_limit();

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("Response received for URL: %s\n", url);
        }

        curl_easy_cleanup(curl);

        char *response = chunk.memory;
        free(chunk.memory);
        return response;
    }
    curl_global_cleanup();
    return NULL;
}

int load_resource_bundle(const char* file_path, char ***bundle_items, size_t *item_count) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open resource bundle file: %s\n", strerror(errno));
        return -1;
    }

    char line[CHUNK_SIZE];
    int capacity = 10; 
    size_t count = 0;

    *bundle_items = malloc(capacity * sizeof(char*));
    if (!*bundle_items) {
        fprintf(stderr, "Memory allocation failed for resource bundle\n");
        fclose(file);
        return -1;
    }

    while (fgets(line, CHUNK_SIZE, file)) {
        line[strcspn(line, "\r\n")] = '\0'; // Remove newline characters

        if (count >= capacity) {
            capacity *= 2;
            *bundle_items = realloc(*bundle_items, capacity * sizeof(char*));
            if (!*bundle_items) {
                fprintf(stderr, "Memory reallocation failed for resource bundle\n");
                fclose(file);
                return -1;
            }
        }

        (*bundle_items)[count] = strdup(line);
        if (!(*bundle_items)[count]) {
            fprintf(stderr, "Memory allocation failed for line in resource bundle\n");
            for (size_t i = 0; i < count; ++i) free((*bundle_items)[i]);
            free(*bundle_items);
            fclose(file);
            return -1;
        }

        count++;
    }

    *item_count = count;
    fclose(file);

    printf("Loaded %zu items from resource bundle\n", count);
    return 0;
}

void free_resource_bundle(char **bundle_items, size_t item_count) {
    for (size_t i = 0; i < item_count; ++i) {
        free(bundle_items[i]);
    }
    free(bundle_items);
}

int main() {
    char *config_file_path = "config.json";
    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file: %s\n", strerror(errno));
        return 1;
    }

    char line[CHUNK_SIZE];
    size_t chunk_size = CHUNK_SIZE;

    while (fgets(line, sizeof(line), file)) {
        line[strcspn(line, "\r\n")] = '\0'; // Remove newline characters

        if (strncmp(line, "url:", 4) == 0) {
            char *url = line + 4;
            printf("Processing URL: %s\n", url);

            char *response = http_get_request(url);
            if (response) {
                printf("Response: %s\n", response);
                free(response); // Free the memory allocated by libcurl
            } else {
                fprintf(stderr, "Failed to retrieve data for URL: %s\n", url);
            }
        }
    }

    fclose(file);

    char **bundle_items = NULL;
    size_t item_count = 0;

    if (load_resource_bundle("resources.txt", &bundle_items, &item_count) == 0) {
        free_resource_bundle(bundle_items, item_count);
    }

    return 0;
}
