typedef struct {
    Record *head;
    pthread_mutex_t lock;
} LinkedList;

Record** allocate_and_initialize_records(int num_offsets, long **offsets, int **keys) {
    // Allocate and initialize offsets array
    *offsets = (long*)malloc(num_offsets * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = i;
    }

    // Allocate and initialize keys array with unique random values
    *keys = (int*)malloc(num_offsets * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    int range = 1000001;
    for (int i = 0; i < num_offsets; ++i) {
        int key;
        do {
            key = rand() % range;
        } while (key >= *keys[i]); // Ensure uniqueness
        (*keys)[i] = key;
    }

    // Allocate and initialize records array
    Record **records = (Record**)malloc(num_offsets * sizeof(Record*));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_offsets; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for a record.\n");
            // Free previously allocated memory
            while (--i >= 0) free(records[i]);
            free(*offsets);
            free(*keys);
            free(records);
            exit(EXIT_FAILURE);
        }
        records[i]->offset_ptr = &((*offsets)[i]);
        records[i]->key = (*keys)[i];
        records[i]->next = NULL;
    }

    return records;
}

LinkedList* initialize_linked_list(Record **records, int num_offsets) {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed for linked list.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&list->lock, NULL);
    list->head = records[0];

    Record* current = list->head;
    for (int i = 1; i < num_offsets; ++i) {
        current->next = records[i];
        current = current->next;
    }

    return list;
}

void free_resources(Record **records, long *offsets, int *keys, LinkedList *list, int num_offsets) {
    Record* current = list->head;
    while (current != NULL) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
    free(records);
    free(offsets);
    free(keys);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    int num_offsets = 100; // Example usage with 100 offsets
    long *offsets;
    int *keys;

    Record **records = allocate_and_initialize_records(num_offsets, &offsets, &keys);

    LinkedList *log_list = initialize_linked_list(records, num_offsets);

    // Example: Access the first record's key and offset value
    printf("First record's key: %d, Offset: %ld\n", log_list->head->key, *(log_list->head->offset_ptr));

    // Clean up resources
    free_resources(records, offsets, keys, log_list, num_offsets);

    return 0;
}
