#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 10000000

typedef struct Value {
    int value;
    struct Value* next;
} Value;

typedef struct Node {
    int key;
    Value* values; // Head of the linked list
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} Collection;

// Initialize a new collection
Collection* initialize_collection() {
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->head = NULL;
    if (pthread_mutex_init(&collection->lock, NULL) != 0) {
        free(collection);
        return NULL;
    }
    return collection;
}

// Create a new value node
Value* create_value_node(int value) {
    Value* new_val = (Value*)malloc(sizeof(Value));
    if (!new_val) return NULL;

    new_val->value = value;
    new_val->next = NULL;
    return new_val;
}

// Insert a value into the linked list, maintaining sorted order
void insert_value(Node* node, int value) {
    Value* new_val = create_value_node(value);
    if (!new_val) return;

    if (node->values == NULL || node->values->value > value) {
        // Insert at head
        new_val->next = node->values;
        node->values = new_val;
    } else {
        Value* current = node->values;
        while (current->next != NULL && current->next->value < value) {
            current = current->next;
        }
        new_val->next = current->next;
        current->next = new_val;
    }
}

// Create a new node
Node* create_node(int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->key = key;
    new_node->values = NULL;
    new_node->next = NULL;
    return new_node;
}

// Insert a node into the collection, maintaining sorted order
void insert_node(Collection* collection, int key, int value) {
    pthread_mutex_lock(&collection->lock);

    Node *new_node = create_node(key);
    if (!new_node) {
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    // Check if the node with this key already exists
    Node* current = collection->head;
    Node** prev_link = &collection->head;

    while (current != NULL && current->key < key) {
        prev_link = &(current->next);
        current = current->next;
    }

    if (current != NULL && current->key == key) {
        // Key already exists, just insert the value
        insert_value(current, value);
    } else {
        // Insert new node into list
        new_node->next = current;
        *prev_link = new_node;
    }

    pthread_mutex_unlock(&collection->lock);
}

// Retrieve values for a given key
Value* retrieve_values(Collection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current != NULL && current->key < key) {
        current = current->next;
    }

    Value* result = (current != NULL && current->key == key) ? current->values : NULL;

    pthread_mutex_unlock(&collection->lock);
    return result;
}

// Delete a node from the collection
void delete_node(Collection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    Node **prev_link = &collection->head;
    Node *current = collection->head;

    while (current != NULL && current->key < key) {
        prev_link = &(current->next);
        current = current->next;
    }

    if (current != NULL && current->key == key) {
        // Free the value list
        Value* val = current->values;
        while (val != NULL) {
            Value* temp = val;
            val = val->next;
            free(temp);
        }

        *prev_link = current->next; // Bypass deleted node
        free(current);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Clean up the collection, freeing all allocated memory
void cleanup_collection(Collection* collection) {
    pthread_mutex_lock(&collection->lock);

    Node* current = collection->head;
    while (current != NULL) {
        Node* temp_node = current;
        Value* val = current->values;

        // Free values list for each node
        while (val != NULL) {
            Value* temp_val = val;
            val = val->next;
            free(temp_val);
        }

        current = current->next;
        free(temp_node);
    }

    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

// Example usage
int main() {
    Collection* collection = initialize_collection();
    if (!collection) return 1;

    insert_node(collection, 10, 100);
    insert_node(collection, 20, 200);
    insert_node(collection, 15, 150);

    Value* values = retrieve_values(collection, 10);
    while (values != NULL) {
        printf("Value: %d\n", values->value);
        values = values->next;
    }

    delete_node(collection, 10);

    cleanup_collection(collection);
    return 0;
}
