#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
    void (*random_func)(int *);
} MemoryManager;

MemoryManager* create_manager(size_t initial_capacity, void (*random_func)(int *)) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->records = calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    // Open log file
    manager->log_file = fopen("memory_manager.log", "w");
    if (!manager->log_file) {
        free(manager->records);
        free(manager);
        return NULL;
    }

    fprintf(manager->log_file, "MemoryManager initialized with capacity %zu\n", initial_capacity);

    manager->random_func = random_func;

    return manager;
}

void destroy_manager(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    fclose(manager->log_file);

    fprintf(manager->log_file, "MemoryManager destroyed\n");
    free(manager);
}

void log_allocation(MemoryManager *manager, const char *message) {
    if (manager && manager->log_file) {
        fprintf(manager->log_file, "%s\n", message);
    }
}

int add_record(MemoryManager *manager, long offset, int key) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            log_allocation(manager, "Failed to allocate memory for resizing");
            return -1;
        }

        manager->records = new_records;
        manager->capacity = new_capacity;

        log_allocation(manager, "Resized records array to capacity");
    }

    manager->records[manager->count].offset = offset;
    manager->records[manager->count].key = key;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    log_allocation(manager, "Added a new record");

    return 0;
}

void update_records_from_source(MemoryManager *manager) {
    // Placeholder for updating records from an external source
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    int random_key;
    if (manager->random_func) {
        manager->random_func(&random_key);
    } else {
        srand(time(NULL));
        random_key = rand() % 100; // Example of generating a random key
    }

    for (size_t i = 0; i < manager->count; ++i) {
        manager->records[i].key = random_key;
    }

    pthread_mutex_unlock(&manager->lock);

    log_allocation(manager, "Updated records from external source");
}

void periodic_update(MemoryManager *manager) {
    while (1) {
        sleep(5); // Example: update every 5 seconds
        update_records_from_source(manager);
    }
}

void* random_func(void *arg) {
    int *key = (int *)arg;
    srand(time(NULL));
    *key = rand() % 100; // Custom random function implementation
}

int main() {
    MemoryManager *manager = create_manager(10, random_func);
    if (!manager) return EXIT_FAILURE;

    pthread_t updater_thread;
    pthread_create(&updater_thread, NULL, (void *(*)(void *))periodic_update, manager);

    add_record(manager, 1000L, 42);

    // Simulate work
    sleep(20);

    destroy_manager(manager);
    pthread_cancel(updater_thread);
    pthread_join(updater_thread, NULL);

    return EXIT_SUCCESS;
}
