    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % 100;  // Random value within range
    }

    // Initialize OpenSSL library
    if (!OPENSSL_init_crypto(0, NULL)) {
        fprintf(stderr, "Failed to initialize OpenSSL.\n");
        free(offsets);
        free(keys);
        free(*records);
        return NULL;
    }

    // Select and configure cipher mode
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create EVP_CIPHER context.\n");
        free(offsets);
        free(keys);
        free(*records);
        return NULL;
    }

    const char* cipher_name;
    switch (cipher_mode) {
        case 0: // ECB
            cipher_name = EVP_des_ecb();
            break;
        case 1: // EDE
            cipher_name = EVP_des_ede3_cbc();
            break;
        case 2: // EDE3
            cipher_name = EVP_des_ede3_cbc();
            break;
        case 3: // CFB
            cipher_name = EVP_des_cfb64();
            break;
        default:
            fprintf(stderr, "Invalid cipher mode.\n");
            EVP_CIPHER_CTX_free(ctx);
            free(offsets);
            free(keys);
            free(*records);
            return NULL;
    }

    EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_name);
    if (cipher == NULL) {
        fprintf(stderr, "Failed to get cipher by name: %s\n", cipher_name);
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(*records);
        return NULL;
    }

    // Configure cipher context
    if (!EVP_CipherInit_ex(ctx, cipher, NULL, keys, offsets, 1)) {
        fprintf(stderr, "Failed to initialize cipher.\n");
        EVP_CIPHER_CTX_free(ctx);
        free(offsets);
        free(keys);
        free(*records);
        return NULL;
    }

    // Return the selected cipher context
    return ctx;

    // Cleanup (not reached due to return)
    EVP_CIPHER_CTX_free(ctx);
    free(offsets);
    free(keys);
    free(*records);
    return NULL;
}
