#include <stdio.h>
#include <stdlib.h>

#define TABLE_SIZE 1024

typedef struct Record {
    long timestamp;
    int status_code;
    struct Record* next;
} Record;

typedef struct HashTable {
    Record** buckets;
} HashTable;

typedef struct MemoryPool {
    size_t block_size;
    unsigned char* pool;
    size_t total_blocks;
    unsigned char* free_list_head;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->block_size = block_size + sizeof(void*);
    mp->total_blocks = num_blocks;
    mp->pool = (unsigned char*)malloc(block_size * num_blocks);
    mp->free_list_head = mp->pool;

    unsigned char** current = (unsigned char**)mp->free_list_head;
    for (size_t i = 0; i < num_blocks - 1; ++i) {
        *current = mp->pool + ((i + 1) * block_size);
        current = (unsigned char**)(*current);
    }
    *current = NULL;

    return mp;
}

void* allocate_from_pool(MemoryPool* mp) {
    if (!mp->free_list_head) return NULL;
    void* block = mp->free_list_head;
    mp->free_list_head = *(unsigned char**)block;
    return (unsigned char*)block + sizeof(void*);
}

void free_memory_pool(MemoryPool* mp) {
    free(mp->pool);
    free(mp);
}

HashTable* create_hash_table(size_t num_buckets) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (Record**)calloc(num_buckets, sizeof(Record*));
    return ht;
}

void destroy_hash_table(HashTable* ht, MemoryPool* mp) {
    for (size_t i = 0; i < TABLE_SIZE; ++i) {
        Record* current = ht->buckets[i];
        while (current) {
            Record* next = current->next;
            free(current);
            current = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

unsigned int hash_function(int status_code) {
    return status_code % TABLE_SIZE;
}

void insert_record(HashTable* ht, long timestamp, int status_code, MemoryPool* mp) {
    unsigned int index = hash_function(status_code);
    Record* new_record = (Record*)allocate_from_pool(mp);
    if (!new_record) return;

    new_record->timestamp = timestamp;
    new_record->status_code = status_code;
    new_record->next = ht->buckets[index];
    ht->buckets[index] = new_record;
}

void delete_record(HashTable* ht, int status_code, MemoryPool* mp) {
    unsigned int index = hash_function(status_code);
    Record *current = ht->buckets[index], *prev = NULL;

    while (current) {
        if (current->status_code == status_code) {
            if (prev)
                prev->next = current->next;
            else
                ht->buckets[index] = current->next;

            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

Record* retrieve_record(HashTable* ht, int status_code) {
    unsigned int index = hash_function(status_code);
    Record* current = ht->buckets[index];

    while (current) {
        if (current->status_code == status_code)
            return current;
        current = current->next;
    }
    return NULL;
}

void garbage_collect(MemoryPool* mp) {
    // Implement any needed defragmentation or compaction
    // This is a placeholder for actual GC logic
}

void manage_records() {
    MemoryPool* mp = create_memory_pool(sizeof(Record), 10000);
    HashTable* ht = create_hash_table(TABLE_SIZE);

    // Simulate real-time event processing
    insert_record(ht, 1625234234, 200, mp);
    insert_record(ht, 1625234235, 404, mp);
    delete_record(ht, 200, mp);

    Record* record = retrieve_record(ht, 404);
    if (record) {
        printf("Retrieved record with timestamp: %ld\n", record->timestamp);
    }

    garbage_collect(mp);

    destroy_hash_table(ht, mp);
    free_memory_pool(mp);
}

int main() {
    manage_records();
    return 0;
}
