#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// External random number generator fallback
int default_random(int min, int max) {
    return min + rand() % (max - min + 1);
}

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t count;
    size_t capacity;
    const char* rng_func; // Function pointer for custom RNG
    pthread_mutex_t lock;
} DataStructure;

#define MEMORY_LIMIT 1024 * 1024 * 512 // Example: 512 MB limit

void log_memory_action(const char *action, size_t size) {
    printf("Memory %s: %zu bytes\n", action, size);
}

int resize_data_structure(DataStructure *ds, size_t new_capacity) {
    if (new_capacity <= ds->capacity)
        return 0; // No resizing needed

    long *new_offsets = realloc(ds->offsets, new_capacity * sizeof(long));
    int *new_keys = realloc(ds->keys, new_capacity * sizeof(int));
    record *new_records = realloc(ds->records, new_capacity * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        log_memory_action("REALLOC FAILED", 0);
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return -1;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;

    log_memory_action("RESIZED", (new_capacity - ds->count) * sizeof(record));
    return 0;
}

void initialize_data_structure(DataStructure *ds, size_t initial_capacity,
                               const char* rng_func) {
    pthread_mutex_init(&ds->lock, NULL);
    ds->capacity = initial_capacity;
    ds->count = 0;

    if (resize_data_structure(ds, ds->capacity)) {
        fprintf(stderr, "Failed to initialize memory\n");
        exit(EXIT_FAILURE);
    }

    ds->rng_func = rng_func ? rng_func : default_random;
}

void free_data_structure(DataStructure *ds) {
    pthread_mutex_lock(&ds->lock);

    if (ds->offsets)
        free(ds->offsets);
    if (ds->keys)
        free(ds->keys);
    if (ds->records)
        free(ds->records);

    log_memory_action("FREED", ds->capacity * sizeof(record));

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
}

int add_record(DataStructure *ds, int key, int value) {
    pthread_mutex_lock(&ds->lock);

    if (ds->count >= ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        if ((new_capacity * sizeof(record)) > MEMORY_LIMIT || 
            resize_data_structure(ds, new_capacity)) {
            log_memory_action("RETRY FAILED", 0);
            pthread_mutex_unlock(&ds->lock);
            return -1; // Out of memory or reallocation failed
        }
    }

    int index = ds->count;
    ds->offsets[index] = index * sizeof(record); // Example offset calculation
    ds->keys[index] = key;
    ds->records[index].value = value;

    ds->count++;
    pthread_mutex_unlock(&ds->lock);
    return 0;
}

// Usage example
int main() {
    srand(time(NULL));
    DataStructure ds;

    initialize_data_structure(&ds, 10, NULL);

    for (int i = 0; i < 20; ++i) { // Adding more than initial capacity to test resizing
        if (add_record(&ds, i, ds.rng_func(1, 100)) != 0) {
            fprintf(stderr, "Failed to add record %d\n", i);
            break;
        }
    }

    free_data_structure(&ds);

    return 0;
}
```

