int processStringWithLimit(const char* str, int sizeLimit, char** result) {
    if (!str) return -1;

    int length = strlen(str);
    if (length >= sizeLimit) {
        *result = NULL;
        return -1;
    }

    *result = (char*)malloc((length + 2) * sizeof(char)); // +1 for null-terminator, +1 for '/'
    if (!*result) {
        perror("Failed to allocate memory");
        return -1;
    }

    strncpy(*result, str, length);
    (*result)[length] = '/';
    (*result)[length + 1] = '\0';

    return 0; // Success
}

// Helper functions for dynamic list management

node* create_node(int key) {
    node* n = (node*)malloc(sizeof(node));
    if (!n) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    n->key = key;
    n->values_head = NULL;
    pthread_mutex_init(&n->lock, NULL);
    return n;
}

void insert_value(node* n, int val_key) {
    if (!n) return;

    pthread_mutex_lock(&n->lock);

    value** curr = &(n->values_head);
    while (*curr && (*curr)->key < val_key) {
        curr = &((*curr)->next);
    }

    value* new_value = (value*)malloc(sizeof(value));
    if (!new_value) {
        perror("Failed to allocate memory for value");
        pthread_mutex_unlock(&n->lock);
        return;
    }

    new_value->key = val_key;
    new_value->next = *curr;
    *curr = new_value;

    pthread_mutex_unlock(&n->lock);
}

value* search_linked_list(value* head, int key) {
    while (head) {
        if (head->key == key) return head;
        head = head->next;
    }
    return NULL; // Not found
}

void free_node_values(value* head) {
    value* temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

void free_node(node* n) {
    if (!n) return;

    pthread_mutex_lock(&n->lock);
    free_node_values(n->values_head);
    pthread_mutex_unlock(&n->lock);

    pthread_mutex_destroy(&n->lock);
    free(n);
}
```

