// Logger class for asynchronous logging
class Logger {
public:
    enum LogLevel { INFO, WARN, ERROR };

    Logger(const std::string& logFilePath) : logFile(logFilePath, std::ios_base::app), stopLogging(false) {
        workerThread = std::thread(&Logger::processLogs, this);
    }

    ~Logger() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stopLogging = true;
            cv.notify_all();
        }
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

    void log(LogLevel level, const std::string& message) {
        std::lock_guard<std::mutex> lock(queueMutex);
        logs.push({level, message});
        cv.notify_one();
    }

private:
    std::ofstream logFile;
    std::queue<std::pair<LogLevel, std::string>> logs;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::thread workerThread;
    bool stopLogging;

    void processLogs() {
        while (true) {
            std::pair<LogLevel, std::string> logEntry;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !logs.empty() || stopLogging; });
                if (stopLogging && logs.empty()) break;
                logEntry = logs.front();
                logs.pop();
            }
            // Write to file
            logFile << "[" << logLevelToString(logEntry.first) << "] " << logEntry.second << std::endl;
        }
    }

    std::string logLevelToString(LogLevel level) {
        switch (level) {
            case INFO: return "INFO";
            case WARN: return "WARN";
            case ERROR: return "ERROR";
            default: return "UNKNOWN";
        }
    }
};

