```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

// Define the structure for records.
typedef struct {
    long offset;
    int key;
    double precision_value;
} Record;

// Define a structure to manage collection with a mutex and log statistics.
typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    size_t allocations;
    size_t deallocations;
} CollectionManager;

// External data source handler function prototype
void (*external_data_source_handler)(CollectionManager *manager);

// Function to initialize the collection manager.
int init_collection_manager(CollectionManager *manager, size_t initial_capacity) {
    if (initial_capacity == 0)
        return -1; // Invalid capacity

    manager->records = malloc(initial_capacity * sizeof(Record));
    if (!manager->records)
        return -1; // Memory allocation failure

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->allocations = 1;
    manager->deallocations = 0;

    return 0;
}

// Function to resize the collection when needed.
int resize_collection(CollectionManager *manager) {
    size_t new_capacity = manager->capacity * 2; // Double the capacity
    Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
    if (!new_records)
        return -1;

    manager->records = new_records;
    manager->capacity = new_capacity;
    manager->allocations++;

    return 0;
}

// Function to add a record.
int add_record(CollectionManager *manager, long offset, int key, double precision_value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity && resize_collection(manager)) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Resizing failed
    }

    Record new_record = {offset, key, precision_value};
    manager->records[manager->count++] = new_record;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to refresh data from an external source periodically.
void *data_refresh_thread(void *arg) {
    CollectionManager *manager = (CollectionManager *)arg;

    while (1) { // Run indefinitely
        if (external_data_source_handler)
            external_data_source_handler(manager);

        sleep(5); // Refresh every 5 seconds; adjust as needed
    }
}

// Function to free resources and print statistics.
void cleanup_collection_manager(CollectionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->records);
    manager->deallocations++;
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);

    printf("Allocations: %zu, Deallocations: %zu\n", manager->allocations, manager->deallocations);
}

// Example external data source handler function
void example_data_source_handler(CollectionManager *manager) {
    // Placeholder for actual logic to update records from an external source.
    pthread_mutex_lock(&manager->lock);

    if (manager->count < manager->capacity) {
        Record new_record = {rand(), rand(), (double)rand() / RAND_MAX};
        manager->records[manager->count++] = new_record;
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    CollectionManager manager;

    if (init_collection_manager(&manager, 10)) {
        fprintf(stderr, "Failed to initialize collection manager.\n");
        return -1;
    }

    // Set up the external data source handler.
    external_data_source_handler = example_data_source_handler;

    pthread_t refresh_thread;
    pthread_create(&refresh_thread, NULL, data_refresh_thread, &manager);

    // Simulate some operations
    for (int i = 0; i < 20; ++i) {
        add_record(&manager, rand(), rand(), (double)rand() / RAND_MAX);
        sleep(1); // Simulate workload
    }

    pthread_cancel(refresh_thread); 
    pthread_join(refresh_thread, NULL);

    cleanup_collection_manager(&manager);

    return 0;
}
```

### Key Aspects of the Code:
- **Thread Safety**: The `pthread_mutex_t` is used to ensure that operations on the collection are thread-safe.
- **Dynamic Resizing**: Automatically resizes the memory allocation when capacity is exceeded, doubling the size for each resize.
- **External Integration**: Placeholder for an external data source handler function which can be defined by users.
- **Logging and Statistics**: Keeps track of memory allocations and deallocations, prints statistics at cleanup.
- **Periodic Refresh**: Uses a separate thread to periodically update records from an external source.
- **Cleanup**: Ensures all allocated resources are freed, and mutexes are destroyed when the program ends.

This implementation is designed for maintainability and scalability, allowing integration with various data sources and supporting future enhancements. Adjustments can be made based on specific needs or constraints of your environment.']

