typedef struct {
    pthread_mutex_t lock;
    void **pool;
    size_t pool_size;
    size_t current_index;
} MemoryPool;

// Helper functions
void init_memory_pool(MemoryPool *mp, size_t size) {
    mp->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    mp->pool = malloc(size);
    mp->pool_size = size;
    mp->current_index = 0;
}

void* allocate_from_pool(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->current_index + size > mp->pool_size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }
    void *ptr = mp->pool + mp->current_index;
    mp->current_index += size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void deallocate_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    mp->pool = NULL;
}

// Logging
