    custom_free(poly_array, 10 * sizeof(polygon));
}

void* custom_malloc(size_t size) {
    pthread_mutex_lock(&lock);
    if (memory_offset + size > MEMORY_POOL_SIZE) {
        log_error("Memory pool exhausted");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    void* ptr = &memory_pool[memory_offset];
    memory_offset += size;
    total_allocated_memory += size;
    pthread_mutex_unlock(&lock);
    return ptr;
}

void custom_free(void* ptr, size_t size) {
    // In a real implementation, we'd track allocations and free them properly.
    pthread_mutex_lock(&lock);
    // For simplicity, we're not actually freeing memory here in this example
    total_allocated_memory -= size;
    pthread_mutex_unlock(&lock);
}

double compute_polygon_area(polygon* poly) {
    double area = 0.0;
    int j = poly->num_vertices - 1;
    for (int i = 0; i < poly->num_vertices; ++i) {
        area += (poly->vertices[j].x + poly->vertices[i].x) *
                (poly->vertices[j].y - poly->vertices[i].y);
        j = i;
    }
    return fabs(area / 2.0);
}

void log_error(const char* message) {
    pthread_mutex_lock(&lock);
    if (log_size < strlen(message) + 1) {
        // Double the size of the log buffer
        log_size *= 2;
        log_buffer = realloc(log_buffer, log_size);
    }
    fprintf(stderr, "%s\n", message);
    pthread_mutex_unlock(&lock);
}

int main() {
    log_buffer = malloc(log_size);
    if (!log_buffer) {
        fprintf(stderr, "Failed to allocate memory for log buffer\n");
        return 1;
    }

    initialize_memory_and_compute_areas();

    free(log_buffer);
    return 0;
}
