```csharp
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Threading;

public class DynamicValueGenerator : IDisposable
{
    private readonly object _lock = new();
    private float _minValue;
    private float _maxValue;
    private float _stepSize;
    private Random _random = new();

    public DynamicValueGenerator(string range, float stepSize)
    {
        ParseRange(range);
        _stepSize = stepSize;

        if (_minValue >= _maxValue)
            throw new ArgumentException("Invalid range: minValue must be less than maxValue.");

        if (_stepSize <= 0)
            throw new ArgumentException("Step size must be greater than zero.");
    }

    private void ParseRange(string range)
    {
        var match = Regex.Match(range, @"^(-?\d+(\.\d+)?)-(-?\d+(\.\d+)?)$|^(.-.);$");

        if (!match.Success)
            throw new ArgumentException("Invalid range format.");

        _minValue = float.Parse(match.Groups[1].Value);
        _maxValue = float.Parse(match.Groups[3].Value);
    }

    public float GetRandomFloat()
    {
        lock (_lock)
        {
            int steps = (int)((_maxValue - _minValue) / _stepSize);
            if (steps == 0) return _minValue;

            int randomStep = _random.Next(steps + 1);
            return _minValue + randomStep * _stepSize;
        }
    }

    public int GetRandomInt()
    {
        lock (_lock)
        {
            int minInt = (int)Math.Ceiling(_minValue);
            int maxInt = (int)Math.Floor(_maxValue);

            if (minInt > maxInt) throw new InvalidOperationException("No valid integer range.");

            return _random.Next(minInt, maxInt + 1);
        }
    }

    public List<int> GetRandomList(int count)
    {
        var result = new List<int>(count);
        lock (_lock)
        {
            int minInt = (int)Math.Ceiling(_minValue);
            int maxInt = (int)Math.Floor(_maxValue);

            for (int i = 0; i < count; i++)
                result.Add(_random.Next(minInt, maxInt + 1));
        }
        return result;
    }

    public override string ToString()
    {
        return $"[{_minValue}, {_maxValue}]";
    }

    public void Dispose()
    {
        _random.Dispose();
    }
}
