```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define the Record structure
typedef struct {
    int value;
} record;

// Custom memory pool structure
typedef struct {
    void* pool;            // Pointer to memory block
    size_t blockSize;      // Size of each block
    size_t totalBlocks;    // Total number of blocks in pool
    size_t usedBlocks;     // Number of currently used blocks
    int cacheHits;
    int cacheMisses;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} MemoryPool;

// Function prototypes
void* memoryPoolAllocate(MemoryPool* pool);
void memoryPoolFreeAll(MemoryPool* pool);
MemoryPool* createMemoryPool(size_t blockSize, size_t totalBlocks);
void deleteMemoryPool(MemoryPool** pool);
void logCacheStats(const MemoryPool* pool);
void sendLogToExternalService(const char* message);

// Create a custom memory pool
MemoryPool* createMemoryPool(size_t blockSize, size_t totalBlocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);
    pool->blockSize = blockSize;
    pool->totalBlocks = totalBlocks;
    pool->usedBlocks = 0;
    pool->cacheHits = 0;
    pool->cacheMisses = 0;

    size_t poolSize = blockSize * totalBlocks;
    pool->pool = malloc(poolSize);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

// Allocate memory from the pool
void* memoryPoolAllocate(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->usedBlocks < pool->totalBlocks) {
        void* block = (char*)pool->pool + (pool->usedBlocks * pool->blockSize);
        pool->usedBlocks++;
        pthread_mutex_unlock(&pool->lock);
        return block;
    } else {
        pool->cacheMisses++;
        pthread_mutex_unlock(&pool->lock);
        return NULL;  // Out of memory
    }
}

// Free all memory in the pool
void memoryPoolFreeAll(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    pool->usedBlocks = 0;
    pthread_mutex_unlock(&pool->lock);
}

// Delete a custom memory pool
void deleteMemoryPool(MemoryPool** pool) {
    if (!pool || !(*pool)) return;

    MemoryPool* temp = *pool;
    memoryPoolFreeAll(temp);

    pthread_mutex_destroy(&temp->lock);
    free(temp->pool);
    free(temp);

    *pool = NULL;
}

// Log cache stats
void logCacheStats(const MemoryPool* pool) {
    printf("Memory Pool Cache Hits: %d, Cache Misses: %d\n", pool->cacheHits, pool->cacheMisses);
    sendLogToExternalService("Memory Pool Cache Stats logged.");
}

// Send a message to an external logging service
void sendLogToExternalService(const char* message) {
    // Simulated function for demonstration purposes
    printf("Sending log to external service: %s\n", message);
}

// Initialize and manage memory with dynamic resizing, error handling, etc.
void initializeAndManageMemory(size_t offsetArraySize, size_t keyArraySize,
                               size_t initialRecordCount, int minKey, int maxKey) {
    MemoryPool* pool = createMemoryPool(sizeof(record), 1000); // Example values
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return;
    }

    long* offsetArray = (long*)memoryPoolAllocate(pool);
    int* keyArray = (int*)memoryPoolAllocate(pool);

    if (!offsetArray || !keyArray) {
        fprintf(stderr, "Memory allocation failed\n");
        deleteMemoryPool(&pool);
        return;
    }

    record* records = (record*)memoryPoolAllocate(pool);
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        free(offsetArray);
        free(keyArray);
        deleteMemoryPool(&pool);
        return;
    }

    srand((unsigned int)time(NULL));

    // Initialize arrays and records
    for (size_t i = 0; i < offsetArraySize; ++i) {
        offsetArray[i] = rand() % 100; // Example initialization
    }

    for (size_t i = 0; i < keyArraySize; ++i) {
        keyArray[i] = minKey + rand() % (maxKey - minKey + 1);
    }

    for (size_t i = 0; i < initialRecordCount; ++i) {
        records[i].value = minKey + rand() % (maxKey - minKey + 1);
    }

    // Monitor and log cache stats
    logCacheStats(pool);

    // Simulate dynamic resizing logic, error handling, etc.

    deleteMemoryPool(&pool);  // Clean up memory pool
}

int main() {
    initializeAndManageMemory(10, 10, 10, 0, 100);
    return 0;
}
