['```csharp
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Threading;

public class DynamicValueGenerator
{
    private readonly double minValue, maxValue;
    private readonly double stepSize;
    private readonly Random random = new Random();
    private static readonly object syncLock = new object();

    public DynamicValueGenerator(double minValue, double maxValue, double stepSize)
    {
        if (minValue >= maxValue) throw new ArgumentException("minValue must be less than maxValue.");
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.stepSize = stepSize > 0 ? stepSize : 1.0;
    }

    public DynamicValueGenerator(string range, double stepSize = 1.0)
    {
        var parts = range.Replace("..", "-").Split('-');
        if (parts.Length != 2) throw new FormatException("Invalid range format.");

        minValue = double.Parse(parts[0], CultureInfo.InvariantCulture);
        maxValue = double.Parse(parts[1], CultureInfo.InvariantCulture);

        if (minValue >= maxValue) throw new ArgumentException("minValue must be less than maxValue.");
        this.stepSize = stepSize > 0 ? stepSize : 1.0;
    }

    public double GetRandomFloat()
    {
        lock (syncLock)
        {
            var steps = Math.Max(1, ((maxValue - minValue) / stepSize).RoundUp());
            int index = random.Next((int)steps);
            return minValue + index * stepSize;
        }
    }

    public int GetRandomInt()
    {
        lock (syncLock)
        {
            return random.Next((int)(minValue), (int)(maxValue) + 1);
        }
    }

    public List<int> GetRandomList(int count)
    {
        var list = new List<int>(count);
        lock (syncLock)
        {
            for (int i = 0; i < count; i++)
            {
                list.Add(GetRandomInt());
            }
        }
        return list;
    }

    public override string ToString()
    {
        return $"[{minValue}, {maxValue}]";
    }

    private static double RoundUp(this double value)
    {
        return Math.Ceiling(value);
    }
}
