#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef void (*LogCallback)(const char*);

// Function to initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Function to log messages using a callback
void safe_log(LogCallback log, const char* message) {
    if (log != NULL) {
        log(message);
    }
}

// Thread-safe function to allocate and initialize arrays
record** initialize_data(int dataset_size, int value_range_min, int value_range_max, LogCallback log_callback) {
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;

    // Allocate memory for offsets, keys, and records
    offsets = (long*)malloc(dataset_size * sizeof(long));
    if (!offsets) {
        safe_log(log_callback, "Failed to allocate memory for offsets");
        return NULL;
    }

    keys = (int*)malloc(dataset_size * sizeof(int));
    if (!keys) {
        safe_log(log_callback, "Failed to allocate memory for keys");
        free(offsets);
        return NULL;
    }

    records = (record**)malloc(dataset_size * sizeof(record*));
    if (!records) {
        safe_log(log_callback, "Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize mutex for thread safety
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Function to initialize each record with a random value
    void* init_record(void* arg) {
        int index = *(int*)arg;
        pthread_mutex_lock(&lock);

        records[index] = (record*)malloc(sizeof(record));
        if (!records[index]) {
            safe_log(log_callback, "Failed to allocate memory for a record");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        records[index]->value = value_range_min + rand() % (value_range_max - value_range_min + 1);

        // Example logging
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Initialized record at index %d with value %d", index, records[index]->value);
        safe_log(log_callback, log_message);

        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Create threads to initialize records
    pthread_t threads[dataset_size];
    for (int i = 0; i < dataset_size; ++i) {
        int* index_ptr = malloc(sizeof(int));
        *index_ptr = i;

        if (pthread_create(&threads[i], NULL, init_record, index_ptr) != 0) {
            safe_log(log_callback, "Failed to create thread");
            free(index_ptr);
        }
    }

    // Join threads
    for (int i = 0; i < dataset_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Validate data integrity
    int valid_data = 1;
    for (int i = 0; i < dataset_size; ++i) {
        if (!records[i] || records[i]->value < value_range_min || records[i]->value > value_range_max) {
            safe_log(log_callback, "Data validation failed at index");
            valid_data = 0;
            break;
        }
    }

    // Cleanup
    pthread_mutex_destroy(&lock);

    if (!valid_data) {
        for (int i = 0; i < dataset_size; ++i) {
            free(records[i]);
        }
        safe_log(log_callback, "Cleaning up due to validation failure");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    return records;
}

// Example usage
void log_to_console(const char* message) {
    printf("%s\n", message);
}

int main() {
    int dataset_size = 10000000; // Up to 10 million records
    int value_range_min = 1, value_range_max = 100;

    init_random();

    record** data = initialize_data(dataset_size, value_range_min, value_range_max, log_to_console);

    if (data != NULL) {
        printf("Data initialized successfully.\n");

        // Free allocated memory
        for (int i = 0; i < dataset_size; ++i) {
            free(data[i]);
        }
        free(data);
    } else {
        printf("Failed to initialize data.\n");
    }

    return 0;
}
