    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
        keys[i] = rand() % (key_max - key_min + 1) + key_min;
        records[i].value = rand() % record_value_range;
    }
    pthread_mutex_unlock(&mutex);

    // Placeholder for logging and validation mechanisms
    printf("Data initialized successfully.\n");

    return malloc(sizeof(long*) * 3);
}

void free_data(void* data) {
    if (data) {
        long** ptrs = (long**) data;
        free(ptrs[0]);
        free(ptrs[1]);
        free(ptrs[2]);
