const fs = require('fs').promises;
const path = require('path');
const { promisify } = require('util');
const execFile = promisify(require('child_process').execFile);

// Simple in-memory cache
let configCache = null;

async function readConfig(filePath) {
    if (configCache) return configCache;

    try {
        const fileData = await fs.readFile(path.resolve(filePath), 'utf8');
        const config = JSON.parse(fileData);

        // Validate configuration
        if (!config.apiKeys || !config.serverAddress) throw new Error('Invalid configuration');

        configCache = config;
        return config;
    } catch (error) {
        console.error('Error reading or parsing the configuration file:', error);
        throw error;
    }
}

async function processConfig(configPath) {
    try {
        const config = await readConfig(configPath);

        // Call C function for processing
        const result = execFile('./data_processor', [JSON.stringify(config)]);
        console.log('C function executed:', result.stdout);

        return result;
    } catch (error) {
        console.error('Failed to process configuration:', error);
    }
}

module.exports = { processConfig };
