typedef enum {
    SESSION_ACTIVE,
    SESSION_INACTIVE
} SessionState;

typedef struct {
    char *username;
    int userId;
    time_t lastActive;
    atomic_int refCount; // To manage references safely across threads
} UserMetadata;

typedef struct {
    time_t timestamp;
    char event[256];
} ActivityLog;

typedef struct {
    UserMetadata *userMeta;
    SessionState state;
    ActivityLog **activityLogs;
    size_t logCount;
    pthread_mutex_t lock;
} SessionData;

// Custom memory pool setup (simplified for illustration)
#define POOL_SIZE 1024
char memoryPool[POOL_SIZE];
size_t memoryOffset = 0;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

void *poolAlloc(size_t size) {
    pthread_mutex_lock(&poolMutex);
    if (memoryOffset + size > POOL_SIZE) {
        pthread_mutex_unlock(&poolMutex);
        return NULL; // Pool exhausted
    }
    void *ptr = memoryPool + memoryOffset;
    memoryOffset += size;
    pthread_mutex_unlock(&poolMutex);
    return ptr;
}

void initializeSessionData(SessionData **sessionDataPtr, const char *username, int userId) {
    if (!sessionDataPtr || !username) return;

    SessionData *sessionData = poolAlloc(sizeof(*sessionData));
    memset(sessionData, 0, sizeof(*sessionData));

    sessionData->userMeta = poolAlloc(sizeof(UserMetadata));
    sessionData->activityLogs = poolAlloc(sizeof(ActivityLog*)); // Start with one log

    sessionData->userMeta->username = strdup(username);
    sessionData->userMeta->userId = userId;
    sessionData->userMeta->lastActive = time(NULL);
    atomic_init(&sessionData->userMeta->refCount, 1);

    sessionData->state = SESSION_ACTIVE;

    pthread_mutex_init(&sessionData->lock, NULL);

    *sessionDataPtr = sessionData;
}

void addActivityLog(SessionData *sessionData, const char *event) {
    if (!sessionData || !event) return;

    pthread_mutex_lock(&sessionData->lock);

    // Resize activity logs array
    size_t newSize = sessionData->logCount + 1;
    ActivityLog **newLogs = poolAlloc(newSize * sizeof(ActivityLog*));
    memcpy(newLogs, sessionData->activityLogs, sessionData->logCount * sizeof(ActivityLog*));

    newLogs[sessionData->logCount] = poolAlloc(sizeof(ActivityLog));
    memset(newLogs[sessionData->logCount], 0, sizeof(ActivityLog));

    time_t currentTime = time(NULL);
    strcpy(newLogs[sessionData->logCount]->event, event);
    newLogs[sessionData->logCount]->timestamp = currentTime;

    if (sessionData->activityLogs) {
        free(sessionData->activityLogs); // Assume this is custom free from pool
    }

    sessionData->activityLogs = newLogs;
    sessionData->logCount = newSize;

    pthread_mutex_unlock(&sessionData->lock);
}

void decrementRefCount(UserMetadata *userMeta) {
    if (atomic_fetch_sub_explicit(&userMeta->refCount, 1, memory_order_relaxed) == 1) {
        // Clean up user metadata
        free(userMeta->username); // Assume this is custom free from pool
        free(userMeta); // Assume this is custom free from pool
    }
}

void cleanupSessionData(SessionData *sessionData) {
    if (!sessionData) return;

    pthread_mutex_lock(&sessionData->lock);

    for (size_t i = 0; i < sessionData->logCount; ++i) {
        free(sessionData->activityLogs[i]); // Assume this is custom free from pool
    }
    free(sessionData->activityLogs); // Assume this is custom free from pool

    decrementRefCount(sessionData->userMeta);

    pthread_mutex_unlock(&sessionData->lock);

    pthread_mutex_destroy(&sessionData->lock);
}

void processSessionUpdates(SessionData **sessions, size_t sessionCount) {
    // Simplified example: simulate handling updates
    for (size_t i = 0; i < sessionCount; ++i) {
        if (sessions[i]) {
            addActivityLog(sessions[i], "User action");
            sessions[i]->state = SESSION_INACTIVE;
        }
    }
}

int main() {
    SessionData *session1, *session2;

    initializeSessionData(&session1, "user1", 101);
    initializeSessionData(&session2, "user2", 102);

    processSessionUpdates((SessionData*[]){ session1, session2 }, 2);

    cleanupSessionData(session1);
    cleanupSessionData(session2);

    return 0;
}
```

