['Below is a C++ implementation of the `DynamicGraphGenerator` class based on your requirements:

```cpp
#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <thread>
#include <string>
#include <sstream>

class DynamicGraphGenerator {
private:
    int minValue;
    int maxValue;
    int stepSize;
    std::vector<void*> structItemPool;
    std::mutex poolMutex;

    void resizeStructItemPool(size_t newSize) {
        std::lock_guard<std::mutex> lock(poolMutex);
        structItemPool.resize(newSize, nullptr);
    }

public:
    DynamicGraphGenerator(const std::string& range, int step = 1) {
        parseRange(range);
        stepSize = step;
        if (stepSize <= 0 || (maxValue - minValue) % stepSize != 0) {
            throw std::invalid_argument("Invalid step size for the given range.");
        }
    }

private:
    void parseRange(const std::string& range) {
        int dashPos = range.find('-');
        if (dashPos == std::string::npos) {
            dashPos = range.find("..");
        }
        if (dashPos != std::string::npos) {
            std::istringstream iss(range.substr(0, dashPos));
            iss >> minValue;
            iss.clear();
            iss.str(range.substr(dashPos + 1));
            iss >> maxValue;

            if (!(iss && !iss.fail() && minValue < maxValue)) {
                throw std::invalid_argument("Invalid range format.");
            }
        } else {
            throw std::invalid_argument("Range not found in input string.");
        }
    }

public:
    float GetRandomFloatInRange(float lowerBound, float upperBound) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(lowerBound, upperBound);
        return dis(gen);
    }

    int GetRandomIntInRange(int lowerBound, int upperBound) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(lowerBound, upperBound);
        return dis(gen);
    }

    void* GetRandomVertexProperties(int vertexPropertiesCount) {
        std::lock_guard<std::mutex> lock(poolMutex);

        if (structItemPool.empty()) {
            resizeStructItemPool(vertexPropertiesCount);
        } else if (structItemPool.size() < vertexPropertiesCount) {
            resizeStructItemPool(vertexPropertiesCount * 2); // Resize to double the needed size
        }

        void* properties = structItemPool[vertexPropertiesCount % structItemPool.size()];
        return properties;
    }

    std::vector<int> GetRandomList(int count) {
        if (count <= 0 || stepSize <= 0 || (maxValue - minValue) % stepSize != 0) {
            throw std::invalid_argument("Invalid range or step size.");
        }

        std::vector<int> randomList;
        randomList.reserve(count);

        for (int i = 0; i < count; ++i) {
            int value = GetRandomIntInRange(minValue, maxValue);
            if ((value - minValue) % stepSize == 0) {
                randomList.push_back(value);
            } else {
                --i; // Retry
            }
        }

        return randomList;
    }

    double GetRandomDoubleInRange(double lowerBound, double upperBound) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(lowerBound, upperBound);
        return dis(gen);
    }

    int GetRandomIntInRange(int lowerBound, int upperBound) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(lowerBound, upperBound);
        return dis(gen);
    }

    void* GetRandomStruct(int count) {
        std::lock_guard<std::mutex> lock(poolMutex);

        if (structItemPool.empty()) {
            resizeStructItemPool(count);
        } else if (structItemPool.size() < count) {
            resizeStructItemPool(count * 2); // Resize to double the needed size
        }

        void* structData = structItemPool[count % structItemPool.size()];
        return structData;
    }
};
```

### Key Points:
- **Range Parsing**: The constructor parses a flexible range format and validates it.
- **Random Number Generation**: Uses `std::random_device` and `std::mt19937` for random float, int, and double generation.
- **Memory Management**: Implements dynamic resizing of the `structItemPool` with thread safety using mutexes.
- **Error Handling**: Validates input parameters to ensure valid operations.']

