#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} record;

int allocate_memory(long max_memory_budget_bytes,
                    size_t long_array_size,
                    size_t int_keys_size,
                    size_t records_size,
                    int (*get_record_value)(size_t index),
                    void **long_array_ptr, 
                    void **int_keys_ptr,
                    void **records_ptr) {

    if (max_memory_budget_bytes <= 0 || long_array_size < 0 || int_keys_size < 0 || records_size < 0) {
        return -1; // Invalid parameters
    }

    size_t long_array_mem = long_array_size * sizeof(long);
    size_t int_keys_mem = int_keys_size * sizeof(int);
    size_t records_mem = records_size * sizeof(record);

    if (long_array_mem + int_keys_mem + records_mem > max_memory_budget_bytes) {
        return -1; // Insufficient memory
    }

    *long_array_ptr = malloc(long_array_mem);
    *int_keys_ptr = malloc(int_keys_mem);
    *records_ptr = malloc(records_mem);

    if (*long_array_ptr == NULL || *int_keys_ptr == NULL || *records_ptr == NULL) {
        free(*long_array_ptr);
        free(*int_keys_ptr);
        free(*records_ptr);
        return -1; // Memory allocation failed
    }

    record *records = (record *)*records_ptr;
    for (size_t i = 0; i < records_size; ++i) {
        int value = get_record_value(i);
        if (value != -1) {  // Assuming -1 indicates failure to retrieve value
            records[i].value = value;
        }
    }

    return 0; // Successful allocation and initialization
}

int verify_memory(void *long_array_ptr, 
                  size_t long_array_size,
                  void *int_keys_ptr,
