using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;

public class WebApplicationManager
{
    private readonly ConcurrentDictionary<string, ApplicationMetadata> _applicationPool = new();
    private static readonly object _lockObject = new();

    public bool AddAndStartWebApplication(string directoryPath, string siteName, List<string> dependencies)
    {
        try
        {
            Log($"Starting to add web application '{siteName}' at '{directoryPath}'.");

            // Ensure thread safety using a lock for adding applications
            lock (_lockObject)
            {
                if (Directory.Exists(directoryPath))
                {
                    var metadata = new ApplicationMetadata(siteName, directoryPath, dependencies);
                    _applicationPool.TryAdd(metadata.Id, metadata);

                    Log($"Successfully added application '{siteName}' with id: {metadata.Id}.");

                    // Start the web application
                    return StartApplicationProcess(directoryPath, siteName, metadata);
                }
                else
                {
                    Log($"Directory does not exist: {directoryPath}");
                    return false;
                }
            }
        }
        catch (Exception ex)
        {
            Log($"Error adding web application '{siteName}': {ex.Message}");
            return false;
        }
    }

    private bool StartApplicationProcess(string directoryPath, string siteName, ApplicationMetadata metadata)
    {
        try
        {
            var processStartInfo = new ProcessStartInfo
            {
                FileName = "cmd.exe",
                Arguments = $"/c start \"\" {directoryPath}\\run.bat", // Assuming a run.bat script exists to start the application
                UseShellExecute = false,
                RedirectStandardOutput = true,
                CreateNoWindow = true
            };

            using (var process = new Process { StartInfo = processStartInfo })
            {
                process.Start();

                while (!process.HasExited)
                {
                    Thread.Sleep(100); // Prevent busy-waiting, adjust as necessary
                }

                if (process.ExitCode == 0)
                {
                    Log($"Web application '{siteName}' started successfully.");
                    ReportStatusToMonitoringService(siteName, "Started");
                    return true;
                }
                else
                {
                    Log($"Failed to start web application '{siteName}'. Exit Code: {process.ExitCode}");
                    ReportStatusToMonitoringService(siteName, "Failed", process.StandardOutput.ReadToEnd());
                    return false;
                }
            }
        }
        catch (Exception ex)
        {
            Log($"Error starting the process for '{siteName}': {ex.Message}");
            return false;
        }
    }

    private void Log(string message)
    {
        // Implement logging, possibly to a file or monitoring service
        Console.WriteLine($"{DateTime.UtcNow}: {message}");
    }

    private void ReportStatusToMonitoringService(string siteName, string status, string details = null)
    {
        // Implement communication with the monitoring service
        Console.WriteLine($"Reporting Status: {siteName} - {status}, Details: {details ?? "N/A"}");
    }
}

public class ApplicationMetadata
{
    public string Id { get; }
    public string SiteName { get; }
    public string DirectoryPath { get; }
    public List<string> Dependencies { get; }

    public ApplicationMetadata(string siteName, string directoryPath, List<string> dependencies)
    {
        Id = Guid.NewGuid().ToString();
        SiteName = siteName;
        DirectoryPath = directoryPath;
        Dependencies = dependencies ?? new List<string>();
    }
}
