#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    void *ptr; // Pointer to either a long or an int
} record;

enum Policy { LONG_PTR, INT_PTR };

// Function prototypes
int allocate_memory(long size_of_longs, int size_of_ints, int size_of_records,
                    long budget_in_bytes, long **long_array, int **int_array,
                    record ***records);
void verify_memory_structure(long *long_array, int size_of_longs,
                             int *int_array, int size_of_ints,
                             record *records, int size_of_records);

// Main allocation function
int allocate_memory(long size_of_longs, int size_of_ints, int size_of_records,
                    long budget_in_bytes, long **long_array, int **int_array,
                    record ***records) {
    if (budget_in_bytes <= 0 || size_of_longs < 0 || size_of_ints < 0 || 
        size_of_records < 0) return -1;

    long total_size = size_of_longs * sizeof(long) + 
                      size_of_ints * sizeof(int) +
                      size_of_records * sizeof(record);

    if (total_size > budget_in_bytes) {
        // Insufficient memory
        return -1;
    }

    void *memory_start = malloc(total_size);
    if (!memory_start) return -1;

    long *current_ptr = (long *)memory_start;
    int *int_array_temp = current_ptr + size_of_longs;
    record *records_temp = (record *)(int_array_temp + size_of_ints);

    // Initialize the random number generator
    srand(time(NULL));

    *long_array = current_ptr;
    *int_array = int_array_temp;
    *records = records_temp;

    for (int i = 0; i < size_of_records; ++i) {
        (*records)[i].value = rand() % 100; // Random value between 0 and 99

        enum Policy policy = rand() % 2; // Randomly choose LONG_PTR or INT_PTR
        if (policy == LONG_PTR) {
            (*records)[i].ptr = &(*long_array)[rand() % size_of_longs];
        } else {
            (*records)[i].ptr = &(*int_array)[rand() % size_of_ints];
        }
    }

    return 0;
}

// Function to verify memory structure consistency
void verify_memory_structure(long *long_array, int size_of_longs,
                             int *int_array, int size_of_ints,
                             record *records, int size_of_records) {
    for (int i = 0; i < size_of_records; ++i) {
        if (records[i].ptr != NULL) {
            // Check if the pointer points to a valid location within arrays
            void *target_ptr = records[i].ptr;
            if ((long)target_ptr >= (long)long_array && 
                (long)target_ptr < (long)(long_array + size_of_longs)) {
                printf("Record %d: Points to a long at offset %ld\n", i, *(long *)target_ptr);
            } else if ((long)target_ptr >= (long)int_array && 
                       (long)target_ptr < (long)(int_array + size_of_ints)) {
                printf("Record %d: Points to an int value of %d\n", i, *(int *)target_ptr);
            } else {
                fprintf(stderr, "Error: Record %d has invalid pointer address.\n", i);
            }
        }
    }
}

// Example usage
int main() {
    long *long_array;
    int *int_array;
    record *records;

    int result = allocate_memory(5, 3, 4, 1000, &long_array, &int_array, &records);

    if (result == 0) {
        verify_memory_structure(long_array, 5, int_array, 3, records, 4);

        // Free the allocated memory
        free(records); // This also frees long_array and int_array since they are part of this block.
    } else {
        printf("Memory allocation failed due to insufficient budget.\n");
    }

    return 0;
}
