function renderFooterScripts(scripts = [], config = {}, externalLoader) {
    const footer = document.querySelector('footer') || document.createElement('footer');
    if (!document.body.contains(footer)) {
        document.body.appendChild(footer);
    }

    const { delay = 0, order = 'end', externalDependencies = [] } = config;
    let cache = new Set();

    async function loadExternal(url) {
        if (cache.has(url)) return;

        try {
            await externalLoader(url); // Assume this is an async function
            cache.add(url);
        } catch (error) {
            console.error(`Failed to load ${url}:`, error);
            // Implement fallback logic here if necessary, e.g., retry with a timeout or skip
        }
    }

    async function loadDependencies() {
        const promises = externalDependencies.map(loadExternal);
        await Promise.all(promises);
    }

    function insertElement(type, content) {
        let element;
        if (type === 'javascript') {
            element = document.createElement('script');
            element.text = content;
        } else if (type === 'css') {
            element = document.createElement('link');
            element.rel = 'stylesheet';
            element.href = `data:text/css;charset=utf-8,${encodeURIComponent(content)}`;
        }

        return element;
    }

    async function processScripts() {
        await loadDependencies();

        const scriptMap = new Map();

        scripts.forEach(script => {
            if (!script.key || cache.has(script.key)) return;

            const element = insertElement(script.type, script.code);
            element.async = true; // Ensure async execution

            scriptMap.set(script.key, {
                element,
                executed: false
            });

            // Insert elements into the footer based on order preference
            if (order === 'start') {
                footer.prepend(element);
            } else {
                footer.appendChild(element);
            }
        });

        await Promise.all(Array.from(scriptMap.values()).map(async ({ element, key }) => {
            setTimeout(() => {
                try {
                    if (!scriptMap.get(key).executed) {
                        element.onload = () => {
                            console.log(`${key} script executed successfully.`);
                        };
                        element.onerror = () => {
                            console.error(`Error executing ${key} script.`);
                        };
                        scriptMap.set(key, { ...scriptMap.get(key), executed: true });
                    }
                } catch (error) {
                    console.error(`Error processing script with key: ${key}`, error);
                }
            }, delay);
        }));
    }

    processScripts();

    // Re-process scripts if they change dynamically
    window.addEventListener('beforeunload', () => {
        const observer = new MutationObserver(() => processScripts());
        observer.observe(footer, { childList: true, subtree: true });
    });
}
