// JavaScript function for an AngularJS application
function refreshDialogFields(resourceId, url, fieldNamesToRefresh, timeoutDuration) {
    const dialog = angular.element(document.querySelector('.dialog'));
    const maxRetries = 3;

    if (!dialog.length || !fieldNamesToRefresh || !Array.isArray(fieldNamesToRefresh)) return;

    dialog.find('input, select, textarea').each(function() {
        const fieldName = $(this).attr('name');
        if (fieldName && fieldNamesToRefresh.includes(fieldName)) {
            let retries = 0;
            function updateFieldValue() {
                const currentValue = $(this).val();

                // Check for parent window availability
                if (!window.opener) return;

                window.opener.postMessage({
                    resourceId,
                    fieldName,
                    value: currentValue,
                    url
                }, '*');

                setTimeout(() => {
                    try {
                        const response = JSON.parse(window.opener.onmessage);
                        if (response && response.success && response.newValue !== undefined) {
                            $(this).val(response.newValue);
                        } else if (retries < maxRetries) {
                            retries++;
                            updateFieldValue.call(this); // Retry
                        } else {
                            console.error(`Failed to update field ${fieldName} after ${maxRetries} attempts.`);
                        }
                    } catch (e) {
                        console.error(`Error processing response for field ${fieldName}:`, e);
                        if (retries < maxRetries) retries++;
                        else console.error(`Exceeded retry limit for field ${fieldName}.`);
                    }
                }, timeoutDuration);
            }

            updateFieldValue.call(this);
        }
    });
}

// Helper function for a forward list of strings
function insertStringAfterInForwardList(forwardList, target, toInsert) {
    if (typeof forwardList !== 'object' || typeof target !== 'string' || typeof toInsert !== 'string') return;

    let inserted = false;
    for (let i = 0; i < forwardList.length; i++) {
        if (forwardList[i] === target) {
            forwardList.splice(i + 1, 0, toInsert);
            inserted = true;
            break;
        }
    }

    if (!inserted && forwardList.length > 0) {
        forwardList.push(toInsert);
    }
}

// Unit tests
function runTests() {
    // Test refreshDialogFields functionality
    console.assert(
        typeof refreshDialogFields === 'function',
        "refreshDialogFields should be a function"
    );

    // Mock environment for testing AngularJS function would typically involve a testing framework.

    // Test insertStringAfterInForwardList functionality
    const list = ['a', 'b', 'c'];
    insertStringAfterInForwardList(list, 'b', 'x');
    console.assert(JSON.stringify(list) === JSON.stringify(['a', 'b', 'x', 'c']), "Test case 1 failed");

    insertStringAfterInForwardList(list, 'd', 'y');
    console.assert(JSON.stringify(list) === JSON.stringify(['a', 'b', 'x', 'c', 'y']), "Test case 2 failed");

    const emptyList = [];
    insertStringAfterInForwardList(emptyList, '', 'z');
    console.assert(JSON.stringify(emptyList) === JSON.stringify(['z']), "Empty list test failed");

    console.log("All tests passed!");
}

runTests();
