#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "json-c/json.h"

// Define the error handler type
typedef void (*errorHandler)(const char*);

// Define the transform function type
typedef json_object *(*transformFunc)(json_object *, int);

void parseAndTransformJSON(const char *jsonData, int maxDepth, transformFunc func, errorHandler err) {
    struct json_object *parsedJson = NULL;
    if (json_tokener_success(json_tokener_parse_ex(&parsedJson, jsonData, strlen(jsonData), 0))) {
        parsedJson = func(parsedJson, maxDepth);
        // Use the transformed JSON object as needed
        json_object_put(parsedJson); // Free memory when done
    } else {
        err("Failed to parse JSON data.");
    }
}
