```javascript
// JavaScript helper function for fetching and caching resources

async function fetchAndCacheResources(baseUrl, resourcePaths, cacheExpiration, netErr) {
    const cache = new Map();

    async function getResource(url) {
        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error(`Network response was not ok: ${response.statusText}`);
            return response.text();
        } catch (error) {
            netErr(error.message);
            throw error;
        }
    }

    for (const path of resourcePaths) {
        const url = baseUrl + path;

        if (cache.has(url)) {
            const cachedItem = cache.get(url);

            // Check if the cached item is still valid
            if ((Date.now() - cachedItem.timestamp) < cacheExpiration * 1000) {
                continue; // Serve from cache
            }
        }

        try {
            const content = await getResource(url);
            cache.set(url, { content: content, timestamp: Date.now() });
        } catch (error) {
            console.error(`Error fetching resource ${path}:`, error.message);
        }
    }

    // Return an object mapping each resource path to its cached content
    const result = {};
    for (const [url, { content }] of cache.entries()) {
        const relativePath = url.substring(baseUrl.length);
        result[relativePath] = content;
    }

    return result;
}
