typedef struct MemoryPool {
    void* pool;
    size_t offset;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* mem_pool = malloc(sizeof(MemoryPool));
    if (!mem_pool) return NULL;

    mem_pool->pool = malloc(size);
    if (!mem_pool->pool) {
        free(mem_pool);
        return NULL;
    }

    mem_pool->offset = 0;
    pthread_mutex_init(&mem_pool->mutex, NULL);
    return mem_pool;
}

void* memory_pool_alloc(MemoryPool* mem_pool, size_t size) {
    if (!mem_pool) return NULL;

    pthread_mutex_lock(&mem_pool->mutex);
    if (mem_pool->offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&mem_pool->mutex);
        return NULL;
    }

    void* ptr = (char*)mem_pool->pool + mem_pool->offset;
    mem_pool->offset += size;
    pthread_mutex_unlock(&mem_pool->mutex);

    return ptr;
}

void memory_pool_free(MemoryPool* mem_pool) {
    if (!mem_pool) return;

    free(mem_pool->pool);
    pthread_mutex_destroy(&mem_pool->mutex);
    free(mem_pool);
}

