#define AES_KEYLEN 32
#define AES_BLOCKSIZE 16
#define PBKDF2_ROUNDS 100000

typedef struct {
    unsigned char *iv;
    size_t iv_len;
    unsigned char *key;
    EVP_CIPHER_CTX *ctx;
} AESContext;

// Error handling function
void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}

int generate_key_iv(const char *passphrase, const unsigned char *salt,
                    int saltlen, unsigned char **key, unsigned char **iv) {
    if (!PKCS5_PBKDF2_HMAC_SHA1(passphrase, strlen(passphrase), salt, saltlen,
                                PBKDF2_ROUNDS, AES_KEYLEN, *key)) {
        handleErrors();
        return 0;
    }
    if (!RAND_bytes(*iv, AES_BLOCKSIZE)) {
        handleErrors();
        return 0;
    }
    return 1;
}

AESContext* aes_init(const char *passphrase, const unsigned char *salt,
                     int saltlen) {
    AESContext *aes_ctx = (AESContext*)malloc(sizeof(AESContext));
    if (!aes_ctx) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    unsigned char *key = NULL;
    unsigned char *iv = NULL;

    if (!generate_key_iv(passphrase, salt, saltlen, &key, &iv)) {
        free(aes_ctx);
        return NULL;
    }

    aes_ctx->key = key;
    aes_ctx->iv = iv;
    aes_ctx->iv_len = AES_BLOCKSIZE;

    aes_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!aes_ctx->ctx) {
        handleErrors();
    }

    if (1 != EVP_EncryptInit_ex(aes_ctx->ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        handleErrors();
    }

    return aes_ctx;
}

void encrypt_session_token(AESContext *aes_ctx, const unsigned char *plaintext,
                           size_t plaintext_len, unsigned char **ciphertext,
                           size_t *ciphertext_len) {
    int len;
    int ciphertext_temp_len = plaintext_len + AES_BLOCKSIZE;

    *ciphertext = (unsigned char*)malloc(ciphertext_temp_len);
    if (!*ciphertext) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptUpdate(aes_ctx->ctx, *ciphertext, &len,
                               plaintext, plaintext_len)) {
        handleErrors();
    }
    *ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(aes_ctx->ctx, *ciphertext + len, &len)) {
        handleErrors();
    }
    *ciphertext_len += len;
}

void aes_cleanup(AESContext *aes_ctx) {
    if (aes_ctx->key) free(aes_ctx->key);
    if (aes_ctx->iv) free(aes_ctx->iv);
    if (aes_ctx->ctx) EVP_CIPHER_CTX_free(aes_ctx->ctx);
    free(aes_ctx);
}

