#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_LENGTH 1024

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

typedef struct LogConfig {
    LogLevel level;
    char* format; // "plain", "json", or "syslog"
    size_t maxFileSize;
    time_t rotationInterval;
    pthread_mutex_t lock;
} LogConfig;

LogConfig* create_log_config(LogLevel level, const char* format, size_t maxFileSize, time_t rotationInterval) {
    LogConfig* config = (LogConfig*)malloc(sizeof(LogConfig));
    if (!config) return NULL;

    config->level = level;
    config->format = strdup(format);
    config->maxFileSize = maxFileSize;
    config->rotationInterval = rotationInterval;
    pthread_mutex_init(&config->lock, NULL);

    return config;
}

void free_log_config(LogConfig* config) {
    if (config) {
        free(config->format);
        pthread_mutex_destroy(&config->lock);
        free(config);
    }
}

const char* log_level_to_string(LogLevel level) {
    switch (level) {
        case DEBUG: return "DEBUG";
        case INFO: return "INFO";
        case WARNING: return "WARNING";
        case ERROR: return "ERROR";
        case CRITICAL: return "CRITICAL";
        default: return "UNKNOWN";
    }
}

void log_message(LogConfig* config, LogLevel level, const char* tag, const char* message) {
    if (!config || level < config->level) return;

    pthread_mutex_lock(&config->lock);

    time_t now = time(NULL);
    struct tm* tm_info = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    char logEntry[MAX_LOG_LENGTH];
    if (strcmp(config->format, "json") == 0) {
        snprintf(logEntry, MAX_LOG_LENGTH,
                 "{\"timestamp\":\"%s\",\"level\":\"%s\",\"tag\":\"%s\",\"message\":\"%s\"}",
                 timestamp, log_level_to_string(level), tag, message);
    } else if (strcmp(config->format, "syslog") == 0) {
        snprintf(logEntry, MAX_LOG_LENGTH,
                 "<%d>%s %s: %s",
                 level + 13, timestamp, tag, message); // Syslog priority
    } else { // plain text
        snprintf(logEntry, MAX_LOG_LENGTH,
                 "[%s] [%s] %s: %s\n", timestamp, log_level_to_string(level), tag, message);
    }

    // Output to file or stdout for demonstration
    printf("%s", logEntry);

    pthread_mutex_unlock(&config->lock);
}

int main() {
    LogConfig* config = create_log_config(DEBUG, "plain", 10 * 1024 * 1024, 3600);
    if (!config) {
        fprintf(stderr, "Failed to initialize log configuration\n");
        return EXIT_FAILURE;
    }

    log_message(config, INFO, "app", "Application started.");
    log_message(config, ERROR, "db", "Database connection failed.");

    free_log_config(config);

    return EXIT_SUCCESS;
}
```

This code provides a basic logging framework in C with support for multiple log levels and output formats. It includes memory management and thread safety using mutexes. The framework is designed to be extensible for more advanced features like file rotation based on size or time intervals.']

