#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <unistd.h>
#include <errno.h>

#define INITIAL_POOL_SIZE 1024 * 1024 // Initial memory pool size (1 MB)
#define MAX_FILES 1000                // Maximum number of files to handle
#define FILE_BUFFER_SIZE 4096         // Buffer size for file reading

typedef struct {
    char* start;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    MemoryPool pool;
    size_t used;
    size_t capacity;
} ThreadMemoryManager;

typedef struct {
    char path[PATH_MAX];
    char identifier[256];
} FileRecord;

static pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void* thread_function(void* arg);
ThreadMemoryManager create_memory_manager(size_t initial_capacity);
char* allocate_from_pool(ThreadMemoryManager* manager, size_t size);
void deallocate_to_pool(ThreadMemoryManager* manager, char* ptr, size_t size);
size_t generate_file_identifier(const char* filename, char* identifier, size_t max_len);
void process_directory(const char* dir_path);

// Main function to demonstrate functionality
int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_directory(argv[1]);

    return EXIT_SUCCESS;
}

void* thread_function(void* arg) {
    ThreadMemoryManager* manager = (ThreadMemoryManager*)arg;

    // Simulate file processing
    char* data = allocate_from_pool(manager, FILE_BUFFER_SIZE);
    if (!data) {
        perror("Allocation failed");
        pthread_exit(NULL);
    }

    // Dummy processing logic here

    deallocate_to_pool(manager, data, FILE_BUFFER_SIZE);

    pthread_exit(NULL);
}

ThreadMemoryManager create_memory_manager(size_t initial_capacity) {
    ThreadMemoryManager manager;
    manager.pool.start = (char*)malloc(initial_capacity);
    if (!manager.pool.start) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    manager.pool.size = initial_capacity;
    pthread_mutex_init(&manager.pool.lock, NULL);

    manager.used = 0;
    manager.capacity = initial_capacity;

    return manager;
}

char* allocate_from_pool(ThreadMemoryManager* manager, size_t size) {
    pthread_mutex_lock(&manager->pool.lock);

    if (manager->used + size > manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        char* new_start = (char*)realloc(manager->pool.start, new_capacity);
        if (!new_start) {
            perror("Failed to resize memory pool");
            pthread_mutex_unlock(&manager->pool.lock);
            return NULL;
        }
        manager->pool.start = new_start;
        manager->capacity = new_capacity;
    }

    char* ptr = manager->pool.start + manager->used;
    manager->used += size;

    pthread_mutex_unlock(&manager->pool.lock);

    return ptr;
}

void deallocate_to_pool(ThreadMemoryManager* manager, char* /*ptr*/, size_t size) {
    // Simple approach: just decrease the used memory
    pthread_mutex_lock(&manager->pool.lock);

    if (manager->used >= size) {
        manager->used -= size;
    }

    pthread_mutex_unlock(&manager->pool.lock);
}

size_t generate_file_identifier(const char* filename, char* identifier, size_t max_len) {
    int freq[256] = {0};
    for (const char* p = filename; *p; ++p) {
        freq[(unsigned char)*p]++;
    }

    snprintf(identifier, max_len, "%s_%zu", filename, freq[(unsigned char)filename[strlen(filename) - 1]]);

    return strlen(identifier);
}

void process_directory(const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    struct dirent* entry;
    pthread_t threads[MAX_FILES];
    ThreadMemoryManager managers[MAX_FILES];

    size_t idx = 0;

    while ((entry = readdir(dir)) && idx < MAX_FILES) {
        if (entry->d_type == DT_REG) { // Regular file
            char full_path[PATH_MAX];
            snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);

            managers[idx] = create_memory_manager(INITIAL_POOL_SIZE);

            FileRecord record;
            strcpy(record.path, full_path);
            generate_file_identifier(entry->d_name, record.identifier, sizeof(record.identifier));

            snprintf(full_path + strlen(full_path), sizeof(full_path) - strlen(full_path),
                     "_%s", record.identifier);

            if (pthread_create(&threads[idx], NULL, thread_function, &managers[idx]) != 0) {
                perror("Failed to create thread");
                closedir(dir);
                return;
            }

            idx++;
        }
    }

    for (size_t i = 0; i < idx; ++i) {
        pthread_join(threads[i], NULL);
        free(managers[i].pool.start); // Cleanup memory pool
    }

    closedir(dir);
}
