```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import "wand/MagickWand.h"
import "wand/api.h"

// Utility functions (not implemented here but necessary)
void handle_error(const char *message);
void initialize_image_mage();
void cleanup_image_magic();

typedef struct {
    char filepath[PATH_MAX];
    char metadata[256]; // Simplified for demo purposes
} ImageInfo;

// Thread-safe queue for image tasks
typedef struct TaskQueue {
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    ImageInfo **tasks;
    size_t head, tail, capacity;
    int count;
} TaskQueue;

TaskQueue* create_task_queue(size_t capacity);
void enqueue_task(TaskQueue *queue, ImageInfo *task);
ImageInfo* dequeue_task(TaskQueue *queue);

// Worker thread function
void* process_images(void* arg) {
    TaskQueue *queue = (TaskQueue*)arg;
    while (1) {
        ImageInfo *image_info = dequeue_task(queue);
        if (!image_info) continue; // Check for shutdown signal

        initialize_image_magic();
        MagickWand *magick_wand;

        magick_wand = NewMagickWand();

        // Read image
        if (MagickReadImage(magick_wand, image_info->filepath) == MagickFalse) {
            handle_error("Failed to read image");
            DestroyMagickWand(magick_wand);
            continue;
        }

        // Process metadata, validate checksums, etc.

        // Resize and convert
        if (MagickResizeImage(magick_wand, 800 /* width */, 600 /* height */, LanczosFilter, 1.0) == MagickFalse) {
            handle_error("Failed to resize image");
            DestroyMagickWand(magick_wand);
            continue;
        }

        // Convert format if needed
        if (MagickSetImageFormat(magick_wand, "JPEG") == MagickFalse) {
            handle_error("Failed to convert image format");
            DestroyMagickWand(magick_wand);
            continue;
        }

        // Write processed image
        char output_path[PATH_MAX];
        snprintf(output_path, PATH_MAX, "%s_resized.jpg", image_info->filepath);
        if (MagickWriteImage(magick_wand, output_path) == MagickFalse) {
            handle_error("Failed to write image");
            DestroyMagickWand(magick_wand);
            continue;
        }

        DestroyMagickWand(magick_wand);

        // Implement retry logic for failures
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char dir_path[PATH_MAX];
    strncpy(dir_path, argv[1], PATH_MAX);

    DIR *dir = opendir(dir_path);
    if (!dir) handle_error("Failed to open directory");

    TaskQueue *task_queue = create_task_queue(100); // Adjust capacity as needed

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            ImageInfo *image_info = malloc(sizeof(ImageInfo));
            snprintf(image_info->filepath, PATH_MAX, "%s/%s", dir_path, entry->d_name);
            // Populate metadata as needed

            enqueue_task(task_queue, image_info);
        }
    }

    closedir(dir);

    const int num_threads = 4; // Example thread count
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_images, task_queue) != 0) {
            handle_error("Failed to create worker thread");
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    cleanup_image_magic();

    return EXIT_SUCCESS;
}
