    pthread_spin_lock(&finder_args->max_lock);
    for (int i = 0; i < finder_args->size; ++i) {
        if (finder_args->array[i] > finder_args->max_value) {
            finder_args->max_value = finder_args->array[i];
        }
    }
    pthread_spin_unlock(&finder_args->max_lock);
    return NULL;
}

