void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&memory_lock);

    if (next_free + size > MEMORY_POOL_SIZE) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&memory_lock);
        return NULL;
    }

    void *ptr = &memory_pool[next_free];
    next_free += size;

    pthread_mutex_unlock(&memory_lock);
    return ptr;
}

int random_int(int min, int max) {
    global_seed ^= (global_seed << 13);
    global_seed ^= (global_seed >> 17);
    global_seed ^= (global_seed << 5);

    int range = max - min + 1;
    return min + (global_seed % range);
}

