    static pthread_mutex_t largest_lock = PTHREAD_MUTEX_INITIALIZER;
    int largest = INT_MIN;

    for (size_t i = 0; i < len; ++i) {
        if (arr[i] > largest) {
            pthread_mutex_lock(&largest_lock);
            if (arr[i] > largest) {
                largest = arr[i];
            }
            pthread_mutex_unlock(&largest_lock);
        }
    }

    return largest;
}

