#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1024
#define REALLOC_MULTIPLIER 2

typedef struct {
    int value;
} record;

typedef struct {
    unsigned char *pool;
    size_t pool_size;
    size_t used_size;
    pthread_mutex_t lock;
} memory_pool;

memory_pool mem_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

// Thread-safe random number generator
unsigned int seed = 12345; // Initial seed for RNG

int thread_safe_rand(int min, int max) {
    unsigned int x = atomic_fetch_add(&seed, 1);
    srand(x); // Seed with the new value
    return rand() % (max - min + 1) + min;
}

void init_memory_pool(size_t size) {
    pthread_mutex_lock(&mem_pool.lock);
    if (!mem_pool.pool) {
        mem_pool.pool = malloc(size);
        if (!mem_pool.pool) {
            perror("Failed to allocate memory pool");
            exit(EXIT_FAILURE);
        }
        mem_pool.pool_size = size;
        mem_pool.used_size = 0;
    } else {
        mem_pool.pool = realloc(mem_pool.pool, size);
        if (!mem_pool.pool) {
            perror("Failed to resize memory pool");
            exit(EXIT_FAILURE);
        }
        mem_pool.pool_size = size;
    }
    pthread_mutex_unlock(&mem_pool.lock);
}

void *allocate_from_pool(size_t size) {
    void *ptr = NULL;

    pthread_mutex_lock(&mem_pool.lock);

    if (size + mem_pool.used_size > mem_pool.pool_size) {
        init_memory_pool(mem_pool.pool_size * REALLOC_MULTIPLIER);
    }

    ptr = mem_pool.pool + mem_pool.used_size;
    mem_pool.used_size += size;

    // Logging memory usage
    printf("Allocated %zu bytes, total used: %zu\n", size, mem_pool.used_size);

    pthread_mutex_unlock(&mem_pool.lock);

    return ptr;
}

void deallocate_from_pool(void *ptr, size_t size) {
    pthread_mutex_lock(&mem_pool.lock);

    // For simplicity, this example does not implement actual garbage collection
    printf("Deallocated %zu bytes\n", size); 

    pthread_mutex_unlock(&mem_pool.lock);
}

record *manage_records(size_t record_count) {
    record *records = (record *)allocate_from_pool(record_count * sizeof(record));

    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = thread_safe_rand(1, 100); // Initialize with random value
    }

    return records;
}

void handle_memory_allocation_failure(void) {
    fprintf(stderr, "Out-of-memory scenario encountered. Attempting fallback...\n");
    init_memory_pool(INITIAL_POOL_SIZE); // Fallback strategy: reset pool size
}

// Thread-safe access to the record array
record safe_get_record(record *records, size_t index) {
    pthread_mutex_lock(&mem_pool.lock);
    if (index < mem_pool.used_size / sizeof(record)) {
        pthread_mutex_unlock(&mem_pool.lock);
        return records[index];
    }
    pthread_mutex_unlock(&mem_pool.lock);

    // Fallback to system allocation if out of bounds
    fprintf(stderr, "Out-of-bounds access detected. Falling back...\n");
    handle_memory_allocation_failure();

    record fallback_record;
    fallback_record.value = 0; // Default value for safety
    return fallback_record;
}

// Main function demonstrating usage
int main() {
    size_t initial_count = 10;

    init_memory_pool(INITIAL_POOL_SIZE);

    record *records = manage_records(initial_count);

    // Example of accessing records safely from multiple threads
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void *)manage_records, &initial_count) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);

    // Example access and deallocation
    for (size_t i = 0; i < initial_count; ++i) {
        record rec = safe_get_record(records, i);
        printf("Record %zu: Value = %d\n", i, rec.value);
    }

    deallocate_from_pool(records, initial_count * sizeof(record));

    free(mem_pool.pool); // Cleanup
    return 0;
}
```

