import java.util.concurrent.*;
import java.util.logging.*;
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.net.ssl.HttpsURLConnection;

public class BackgroundServiceManager {

    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(10);
    private final ExecutorService threadPool = Executors.newCachedThreadPool();
    private volatile boolean running = false;
    private static final Logger logger = Logger.getLogger("BackgroundServiceLogger");

    public void start() {
        running = true;
        scheduler.scheduleAtFixedRate(this::manageLifecycle, 0, 1, TimeUnit.MINUTES);
        Runtime.getRuntime().addShutdownHook(new Thread(this::stop));
    }

    private void manageLifecycle() {
        try {
            if (running) {
                stopService();
                Thread.sleep(getRandomDelay());
                startService();
            } else {
                Thread.sleep(getRandomDelay());
                startService();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void startService() {
        logger.info("Starting Service...");
        // Simulate starting service
        processTransaction(true);
    }

    private void stopService() {
        logger.info("Stopping Service...");
        sendNotification();
        processTransaction(false);
    }

    private void sendNotification() {
        try (HttpsURLConnection conn = setupConnection()) {
            logger.info("Sending notification to alerting system...");
            // Simulate sending notification
        } catch (Exception e) {
            logger.severe("Failed to send notification: " + e.getMessage());
        }
    }

    private void processTransaction(boolean startEvent) {
        int retryAttempts = 0;
        boolean success = false;

        while (!success && retryAttempts < 3) {
            try {
                if (startTransaction()) {
                    logger.info((startEvent ? "Processing start" : "Processing stop") + " transaction...");
                    // Simulate transaction processing
                    success = true;
                }
            } catch (Exception e) {
                retryAttempts++;
                if (retryAttempts >= 3) {
                    logger.severe("Transaction failed after retries: " + e.getMessage());
                }
            }

            try {
                Thread.sleep(1000);
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private boolean startTransaction() throws Exception {
        // Simulate a transaction with third-party service
        return Math.random() > 0.2; // Random success rate for simulation
    }

    private void stop() {
        running = false;
        scheduler.shutdownNow();
        threadPool.shutdown();
        logger.info("Service stopped.");
    }

    private long getRandomDelay() {
        return (long) (Math.random() * 10 + 5); // Delay between 5 to 15 seconds
    }

    private HttpsURLConnection setupConnection() throws Exception {
        String url = "https://example.com/notify";
        HttpsURLConnection conn = (HttpsURLConnection) new java.net.URL(url).openConnection();
        conn.setDoOutput(true);
        return conn;
    }

    public static void main(String[] args) {
