    double real;
    double imag;
} ComplexNumber;

// Memory pool structure
typedef struct {
    size_t block_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t initial_blocks) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->pool_size = block_size * initial_blocks;
    mp->pool = malloc(mp->pool_size);
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    void *ptr = mp->pool;
    memmove(mp->pool, (char*)mp->pool + mp->block_size, mp->pool_size - mp->block_size);
    mp->pool_size -= mp->block_size;
    pthread_mutex_unlock(&mp->lock);

    return ptr;
}

void memory_pool_free(MemoryPool *mp) {
    // Typically, you'd have a more complex deallocation strategy
    pthread_mutex_lock(&mp->lock);
    memmove(mp->pool + mp->pool_size, malloc(mp->block_size), mp->block_size);
    mp->pool_size += mp->block_size;
    pthread_mutex_unlock(&mp->lock);
}

