                json_object_object_get_ex(coordinates_obj, "y", &y_val) &&
                json_object_is_type(x_val, json_type_double) && 
                json_object_is_type(y_val, json_type_double)) {

                Point p = { .x = (float)json_object_get_double(x_val), .y = (float)json_object_get_double(y_val) };
                data->spatial_data[data->count] = p;
            }
        }

        json_object *frequency_obj = NULL;
        if (json_object_object_get_ex(parsed_json, "frequency", &frequency_obj) &&
            json_object_is_type(frequency_obj, json_type_object)) {

            json_object *real_val = NULL, *imag_val = NULL;
            if (json_object_object_get_ex(frequency_obj, "real", &real_val) &&
                json_object_object_get_ex(frequency_obj, "imag", &imag_val) &&
                json_object_is_type(real_val, json_type_double) && 
                json_object_is_type(imag_val, json_type_double)) {

                ComplexNumber cn = { .real = json_object_get_double(real_val), .imag = json_object_get_double(imag_val) };
                data->frequency_data[data->count] = cn;
            }
        }

        log_event("Processed a new sensor payload.");
    } else {
        log_event("Failed to parse JSON payload.");
    }

    json_object_put(parsed_json);
    pthread_exit(NULL);
}

