// Memory Pool for Dynamic Allocation
class MemoryPool {
private:
    struct Block {
        Block* next;
    };

    Block* freeList = nullptr;

public:
    MemoryPool(size_t blockSize, size_t blockCount) {
        // Allocate a big chunk of memory and divide it into blocks
        void* pool = malloc(blockSize * blockCount);
        for (size_t i = 0; i < blockCount; ++i) {
            auto* block = reinterpret_cast<Block*>(reinterpret_cast<char*>(pool) + i * blockSize);
            block->next = freeList;
            freeList = block;
        }
    }

    ~MemoryPool() {
        free(freeList);
    }

    void* allocate(size_t size) {
        if (freeList == nullptr) return malloc(size);  // Out of memory

        Block* head = freeList;
        freeList = freeList->next;
        return head;
    }

    void deallocate(void* ptr, size_t size) {
        auto* block = reinterpret_cast<Block*>(ptr);
        block->next = freeList;
        freeList = block;
    }
};

// Compression Library Loader
class CompressionLibraryLoader {
private:
    void* handle;

public:
    CompressionLibraryLoader(const std::string& libName) {
        handle = dlopen(libName.c_str(), RTLD_LAZY);
        if (!handle) throw std::runtime_error("Could not load library: " + libName);
    }

    ~CompressionLibraryLoader() {
        dlclose(handle);
    }

    // Load a function from the library
    template<typename Func>
    Func loadFunction(const std::string& funcName) {
        using func_ptr = Func;
        func_ptr func = (func_ptr)dlsym(handle, funcName.c_str());
        if (!func) throw std::runtime_error("Could not load symbol: " + funcName);
        return func;
    }
};

