#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define DEFAULT_POOL_SIZE 1024
#define DEFAULT_CONCURRENCY_LEVEL 4

typedef struct {
    float x;
    float y;
} point_t;

typedef struct {
    double value;
    char *name;
    point_t p;
} transaction_t;

typedef struct MemoryPool {
    size_t pool_size;
    void **memory_pool;
    pthread_mutex_t lock;
    int available_slots;
    condition_variable_t cond_var;
} memory_pool_t;

// Function prototypes
void initialize_memory_pool(memory_pool_t *pool, size_t pool_size);
void destroy_memory_pool(memory_pool_t *pool);
transaction_t* allocate_transaction(memory_pool_t *pool);
void free_transaction(transaction_t *trans, memory_pool_t *pool);
double get_random_double(double min, double max);
point_t generate_random_point();
char* copy_string(const char* str);

// Thread-safe logging
void log_message(const char *message) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_lock);
}

// Initialize the memory pool
void initialize_memory_pool(memory_pool_t *pool, size_t pool_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond_var, NULL);
    pool->memory_pool = malloc(pool_size * sizeof(void *));
    pool->available_slots = pool_size;
    pool->pool_size = pool_size;
}

// Destroy the memory pool
void destroy_memory_pool(memory_pool_t *pool) {
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond_var);
}

// Allocate a transaction from the memory pool
transaction_t* allocate_transaction(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);

    while (pool->available_slots == 0) {
        pthread_cond_wait(&pool->cond_var, &pool->lock);
    }

    void **slot = NULL;
    for (size_t i = 0; i < pool->pool_size && slot == NULL; i++) {
        if (!pool->memory_pool[i]) {
            slot = &(pool->memory_pool[i]);
        }
    }

    if (slot) {
        *slot = malloc(sizeof(transaction_t));
        pool->available_slots--;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    transaction_t *trans = (transaction_t *)*slot;

    trans->value = get_random_double(0.0, 100.0); // Example range
    trans->name = copy_string("Transaction Name");
    trans->p = generate_random_point();

    pthread_mutex_unlock(&pool->lock);
    return trans;
}

// Free a transaction back to the memory pool
void free_transaction(transaction_t *trans, memory_pool_t *pool) {
    if (!trans) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->pool_size; i++) {
        if (pool->memory_pool[i] == trans) {
            free(trans->name);
            free(pool->memory_pool[i]);
            pool->memory_pool[i] = NULL;
            pool->available_slots++;
            pthread_cond_signal(&pool->cond_var);
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

// Generate a random double
double get_random_double(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

// Generate a random point
point_t generate_random_point() {
    point_t p;
    p.x = get_random_double(-100.0, 100.0);
    p.y = get_random_double(-100.0, 100.0);
    return p;
}

// Copy string safely
char* copy_string(const char* str) {
    if (!str) return NULL;
    size_t len = strlen(str) + 1;
    char *copy = malloc(len);
    strcpy(copy, str);
    return copy;
}

// Find the largest integer in an array - example helper function for demonstrating thread safety
int find_largest_integer(const int *array, size_t length) {
    pthread_mutex_lock(&pool->lock); // Assuming 'pool' is accessible

    if (!array || length == 0)
        return INT_MIN;

    int max = array[0];
    for (size_t i = 1; i < length; i++) {
        if (array[i] > max) max = array[i];
    }

    pthread_mutex_unlock(&pool->lock);
    return max;
}

// Main function demonstrating the usage
int main() {
    srand(time(NULL)); // Seed random number generator

    memory_pool_t pool;
    initialize_memory_pool(&pool, DEFAULT_POOL_SIZE);

    transaction_t *trans1 = allocate_transaction(&pool);
    if (trans1) log_message("Transaction 1 allocated.");

    free_transaction(trans1, &pool);

    destroy_memory_pool(&pool);

    int numbers[] = {1, 2, 3, 4, 5};
    printf("Largest integer: %d\n", find_largest_integer(numbers, sizeof(numbers)/sizeof(int)));

    return 0;
}
