#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    float x;
    float y;
} point_t;

typedef struct {
    double d;
    char *s;
    point_t pt;
} geometry_t;

typedef struct node {
    int value;
    struct node* next;
} node_t;

typedef struct {
    size_t size;
    void** pool;
} memory_pool_t;

#define POOL_SIZE 1024

// Helper function to initialize a memory pool
void init_memory_pool(memory_pool_t *pool, size_t object_size) {
    pool->size = POOL_SIZE;
    pool->pool = malloc(POOL_SIZE * object_size);
}

// Allocate an object from the pool
void* allocate_from_pool(memory_pool_t *pool, size_t object_size) {
    static size_t index = 0;
    if (index >= POOL_SIZE) {
        return NULL; // Pool exhausted
    }
    void* obj = pool->pool + (index++ * object_size);
    return obj;
}

// Free the entire memory pool
void free_memory_pool(memory_pool_t *pool) {
    free(pool->pool);
}

// Function to initialize data structures with thread safety using mutexes
geometry_t* init_data_structures(double range_min, double range_max, size_t str_length, pthread_mutex_t* list_mutex);

// Helper function to generate a random alphanumeric string
void generate_random_string(char *str, size_t length) {
    const char alphanum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    for (size_t i = 0; i < length; ++i) {
        str[i] = alphanum[rand() % (sizeof(alphanum) - 1)];
    }
    str[length] = '\0';
}

// Initialize data structures
geometry_t* init_data_structures(double range_min, double range_max, size_t str_length, pthread_mutex_t* list_mutex) {
    srand(time(NULL));

    // Memory pool for allocations
    memory_pool_t mem_pool;
    init_memory_pool(&mem_pool, sizeof(node_t)); // Use node size as base

    // Arrays
    double* doubles_array = allocate_from_pool(&mem_pool, sizeof(double));
    char** strings_array = (char**)allocate_from_pool(&mem_pool, sizeof(char*));
    point_t* points_array = (point_t*)allocate_from_pool(&mem_pool, sizeof(point_t));
    geometry_t* geometries_array = (geometry_t*)allocate_from_pool(&mem_pool, sizeof(geometry_t));

    for (int i = 0; i < 6; ++i) {
        doubles_array[i] = (double)(rand() % 100); // Simple example
        strings_array[i] = allocate_from_pool(&mem_pool, str_length + 1);
        generate_random_string(strings_array[i], str_length);

        points_array[i].x = (float)(range_min + (rand() / (RAND_MAX / (range_max - range_min))));
        points_array[i].y = (float)(range_min + (rand() / (RAND_MAX / (range_max - range_min))));

        geometries_array[i].d = (double)(rand() % 100);
        generate_random_string(geometries_array[i].s, str_length);
        geometries_array[i].pt = points_array[i];
    }

    // Linked list with mutex
    node_t* head = allocate_from_pool(&mem_pool, sizeof(node_t));
    head->value = rand() % 100;
    head->next = NULL;

    pthread_mutex_lock(list_mutex);
    for (int i = 0; i < 5; ++i) {
        node_t* new_node = allocate_from_pool(&mem_pool, sizeof(node_t));
        new_node->value = rand() % 100;
        new_node->next = head;
        head = new_node;
    }
    pthread_mutex_unlock(list_mutex);

    // Hash map (simplified as a fixed-size array for demonstration)
    const int hash_map_size = 10;
    geometry_t* hash_map[10] = { NULL };

    for (int i = 0; i < 6; ++i) {
        int index = rand() % hash_map_size;
        hash_map[index] = &geometries_array[i];
    }

    return geometries_array; // Return for later use
}

// Helper function to find and print the largest integer in a linked list safely
void find_and_print_largest_in_list(node_t* head, pthread_mutex_t* list_mutex) {
    int max_val = INT_MIN;

    pthread_mutex_lock(list_mutex);
    node_t* current = head;
    while (current != NULL) {
        if (current->value > max_val) {
            max_val = current->value;
        }
        current = current->next;
    }
    pthread_mutex_unlock(list_mutex);

    printf("Largest integer in list: %d\n", max_val);
}

// Cleanup function
void cleanup(geometry_t* geometries, memory_pool_t *mem_pool, node_t* head, pthread_mutex_t* list_mutex) {
    free_memory_pool(mem_pool); // Release the pool
    // No explicit freeing needed for dynamically allocated strings in this example due to simplicity

    pthread_mutex_destroy(list_mutex);
}

int main() {
    pthread_mutex_t list_mutex;
    pthread_mutex_init(&list_mutex, NULL);

    geometry_t* geometries = init_data_structures(0.0, 10.0, 8, &list_mutex);

    // Example usage
    find_and_print_largest_in_list(head, &list_mutex);

    // Cleanup resources
    cleanup(geometries, &mem_pool, head, &list_mutex);

    return 0;
}
