typedef struct {
    size_t block_size;
    void *pool;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t block_size, size_t num_blocks) {
    memory_pool *mp = (memory_pool *)malloc(sizeof(memory_pool));
    mp->block_size = block_size;
    mp->total_blocks = num_blocks;
    mp->used_blocks = 0;
    mp->pool = malloc(block_size * num_blocks);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* allocate_from_pool(memory_pool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_blocks < mp->total_blocks) {
        void *ptr = ((char*)mp->pool) + (mp->block_size * mp->used_blocks++);
        pthread_mutex_unlock(&mp->lock);
        return ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL;
}

void destroy_memory_pool(memory_pool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

