import <pthread.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_OFFSETS 1000
#define MAX_KEYS 1000
#define MAX_RECORDS 1000
#define CPU_LIMIT 10000

typedef struct {
    double latitude;
    double longitude;
} location_t;

typedef struct {
    double temperature;
    char sensor_id[10];
    location_t coordinates;
} sensor_t;

typedef struct {
    sensor_t sensor;
    int timestamp;
    char status_message[50];
} device_t;

typedef struct memory_pool {
    void *memory;
    size_t size;
    size_t offset;
    pthread_mutex_t lock;
} memory_pool_t;

int process_records(int max_offsets, int max_keys, int max_records);

static inline void* pool_alloc(memory_pool_t *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->offset + size > pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void *ptr = ((char *)pool->memory) + pool->offset;
    pool->offset += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

static inline void pool_free(memory_pool_t *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory);
}

int process_records(int max_offsets, int max_keys, int max_records) {
    if (max_offsets > MAX_OFFSETS || max_keys > MAX_KEYS || max_records > MAX_RECORDS) {
        return -2;
    }

    memory_pool_t pool;
    pool.size = max_offsets * sizeof(sensor_t) + max_keys * sizeof(device_t);
    pool.memory = malloc(pool.size);
    if (!pool.memory) return 0;

    pthread_mutex_init(&pool.lock, NULL);

    sensor_t *sensors = (sensor_t *)pool_alloc(&pool, max_offsets * sizeof(sensor_t));
    device_t *devices = (device_t *)pool_alloc(&pool, max_keys * sizeof(device_t));

    if (!sensors || !devices) {
        pool_free(&pool);
        return 0;
    }

    for (int i = 0; i < max_records && i < CPU_LIMIT; ++i) {
        char device_id[10];
        scanf("%9s", device_id);

        int sensor_index = rand() % max_offsets;
        sensors[sensor_index].temperature = rand();
        strcpy(sensors[sensor_index].sensor_id, device_id);

        int device_index = rand() % max_keys;
        devices[device_index].sensor = sensors[sensor_index];
        devices[device_index].timestamp = time(NULL);
        snprintf(devices[device_index].status_message, sizeof(devices[device_index].status_message), "Active");

        double latitude = (double)rand() / RAND_MAX * 180.0 - 90.0;
        double longitude = (double)rand() / RAND_MAX * 360.0 - 180.0;

        sensors[sensor_index].coordinates.latitude = latitude;
        sensors[sensor_index].coordinates.longitude = longitude;
    }

    pid_t pid = fork();
    if (pid == 0) {
        execlp("your_command", "your_command", NULL);
        exit(1);
    } else if (pid > 0) {
        int status;
        wait(&status);
    } else {
        pool_free(&pool);
        return -1;
    }

    pthread_mutex_unlock(&pool.lock);

    // Calculate average temperature per device
    double total_temp = 0.0;
    int count = 0;

    for (int i = 0; i < max_keys; ++i) {
        total_temp += devices[i].sensor.temperature;
        count++;
    }

    if (count > 0) {
        printf("Average Temperature: %f\n", total_temp / count);
    }

    pool_free(&pool);
    return 1;
}

int main(int argc, char *argv[]) {
    int max_offsets = MAX_OFFSETS;
    int max_keys = MAX_KEYS;
    int max_records = MAX_RECORDS;

    if (argc >= 2) max_offsets = atoi(argv[1]);
    if (argc >= 3) max_keys = atoi(argv[2]);
    if (argc >= 4) max_records = atoi(argv[3]);

    return process_records(max_offsets, max_keys, max_records);
}
