        printf("Loaded config: Host=%s, Port=%d\n", config->hostname, config->port);

        free(config->hostname);  // Ensure allocated memory is freed after use
        free(config);
    }

    fclose(file);
}

// Function to watch the file for changes and reload configuration if necessary
void* monitor_config(void *arg) {
    const char *filename = (const char*)arg;
    struct stat prev_stat;

    while (1) {
        sleep(2);  // Check every 2 seconds

        struct stat current_stat;
        if (stat(filename, &current_stat) == -1) {
            continue;  // Could not get the file stats
        }

        if (memcmp(&prev_stat, &current_stat, sizeof(prev_stat)) != 0) {
            printf("Configuration updated\n");
            load_config(filename);
            prev_stat = current_stat;
        }
    }
}

int main() {
    fetch_latest_config();

    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitor_config, CONFIG_FILE)) {
        error_exit("Failed to create thread for monitoring config");
    }

    pthread_join(monitor_thread, NULL);

    return 0;
}
