// Custom Memory Pool
class MemoryPool {
private:
    std::vector<void*> pool;
    size_t blockSize;
    std::mutex mtx;

public:
    MemoryPool(size_t block_size, size_t num_blocks)
        : blockSize(block_size), pool(num_blocks) {
        for (auto& p : pool) {
            p = ::operator new(blockSize);
        }
    }

    void* allocate() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!pool.empty()) {
            void* ptr = pool.back();
            pool.pop_back();
            return ptr;
        } else {
            throw std::bad_alloc();
        }
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mtx);
        pool.push_back(ptr);
    }

    ~MemoryPool() {
        for (auto& p : pool) {
            ::operator delete(p);
        }
    }
};

