        std::uniform_real_distribution<> dis(0.0, 1.0);

        value = dis(gen) * range_value;
        snprintf(name, sizeof(name), "%s", (range_name + "Prefix").c_str());
        point.x = dis(gen) * range_x;
        point.y = dis(gen) * range_y;
    }
};

