typedef struct {
    double mean;
    double stddev;
} stats;

void calculate_stats(double* data, size_t n, stats *result) {
    double sum = 0.0;
    for (size_t i = 0; i < n; ++i) {
        sum += data[i];
    }
    result->mean = sum / n;

    double variance_sum = 0.0;
    #pragma omp parallel for reduction(+:variance_sum)
    for (size_t i = 0; i < n; ++i) {
        variance_sum += (data[i] - result->mean) * (data[i] - result->mean);
    }
    result->stddev = sqrt(variance_sum / n);
}

void handle_data() {
    double* numbers = NULL;
    size_t count = 0, capacity = 0;

    double num;
    while (scanf("%lf", &num) == 1) {
        if (count >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            numbers = realloc(numbers, capacity * sizeof(double));
        }
        numbers[count++] = num;
    }

    stats result;
    calculate_stats(numbers, count, &result);

    printf("Mean: %f\n", result.mean);
    printf("Standard Deviation: %f\n", result.stddev);

    free(numbers);
}

