        // Use the data point
        printf("Data Point: %f, %s, %d\n", dp->value, dp->string, dp->timestamp);

        destroy_data_points(dp, 1); // Clean up
    }

    handle_data();

    free_memory_pool(&mempool);
}

int main() {
