// Memory pool structure for managing memory blocks
typedef struct {
    size_t block_size;
    void* pool;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables for arrays and thread-safe mechanisms
pthread_mutex_t print_lock = PTHREAD_MUTEX_INITIALIZER;
int largest_int = INT_MIN;

// Function declarations
MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks);
void free_memory_pool(MemoryPool* pool);
void* allocate_from_pool(MemoryPool* pool);
Record* initialize_records(int count, int min_val, int max_val, MemoryPool* record_pool);

void read_integers_and_find_largest();
int find_largest_thread_safe(int* array, size_t size);
void log_operation(const char* message);

// Main function to manage memory and operations
void dynamic_memory_management() {
    // Create memory pools for offsets, keys, and records
    MemoryPool offset_pool = *create_memory_pool(sizeof(long), 1000); 
    MemoryPool key_pool = *create_memory_pool(sizeof(int), 1000);
    MemoryPool record_pool = *create_memory_pool(sizeof(Record), 1000);

    // Initialize arrays using memory pools
    long* offsets = (long*)allocate_from_pool(&offset_pool);
    int* keys = (int*)allocate_from_pool(&key_pool);
    Record* records = initialize_records(100, 1, 100, &record_pool);

    // Read integers from stdin and find the largest
    read_integers_and_find_largest();

    // Free allocated memory pools
    free_memory_pool(&offset_pool);
    free_memory_pool(&key_pool);
    free_memory_pool(&record_pool);
}

// Helper function to create a memory pool
MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->pool = malloc(block_size * total_blocks);
    pthread_mutex_init(&pool->lock, NULL);

    log_operation("Memory pool created.");
    return pool;
}

// Helper function to free a memory pool
void free_memory_pool(MemoryPool* pool) {
    if (pool) {
