#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock;
} MemoryPool;

void* thread_safe_malloc(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (size > mp->block_size || !(mp->pool)) {
        pthread_mutex_unlock(&mp->lock);
        return malloc(size); // Fallback to system allocation
    }
    void* block = mp->pool;
    mp->pool = realloc(mp->pool, mp->num_blocks * size);  // Adjust the pool
    pthread_mutex_unlock(&mp->lock);
    return block;
}

void thread_safe_free(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    free(mp->pool);
    mp->pool = NULL;
    pthread_mutex_unlock(&mp->lock);
}

int read_integers(int** arr, int* size) {
    *size = 0;
    int capacity = 10;
    *arr = malloc(capacity * sizeof(int));

    if (!*arr) return -1;

    while (scanf("%d", &((*arr)[*size])) == 1) {
        (*size)++;

        // Resize array if necessary
        if (*size >= capacity) {
            capacity *= 2;
            *arr = realloc(*arr, capacity * sizeof(int));
            if (!*arr) return -1;
        }
    }

    return 0;
}

int find_largest_int(int* arr, int size, int* largest) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int max_val = INT_MIN;
    for (int i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock);
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
        pthread_mutex_unlock(&lock);
    }

    *largest = max_val;
    pthread_mutex_destroy(&lock);

    return 0;
}

void usage_info() {
    printf("Usage: program [options]\n");
    printf("--manpage   Show manual page\n");
    printf("-cs         Enable custom synchronization\n");
    printf("-o <file>   Output to specified file\n");
}

int main(int argc, char** argv) {
    if (argc == 1 || (argc == 2 && strcmp(argv[1], "--manpage") == 0)) {
        usage_info();
        return 0;
    }

    int output_to_file = 0;
    char* output_filename = NULL;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-cs") == 0) {
            // Custom synchronization
        } else if (strncmp(argv[i], "-o", 2) == 0 && argv[i][2] != '\0') {
            output_to_file = 1;
            output_filename = argv[i] + 2;
        }
    }

    MemoryPool mp = { NULL, sizeof(long), 100, PTHREAD_MUTEX_INITIALIZER };

    long* offsets = (long*)thread_safe_malloc(&mp, sizeof(long) * 100);
    int* keys = (int*)thread_safe_malloc(&mp, sizeof(int) * 100);
    record* records = (record*)thread_safe_malloc(&mp, sizeof(record) * 100);

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        thread_safe_free(&mp);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 100; ++i) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;
    }

    int* numbers = NULL;
    int num_size = 0;

    if (read_integers(&numbers, &num_size) != 0) {
        perror("Failed to read integers");
        thread_safe_free(&mp);
        return EXIT_FAILURE;
    }

    int largest;
    find_largest_int(numbers, num_size, &largest);

    printf("Largest integer: %d\n", largest);

    if (numbers) free(numbers);

    if (output_to_file && output_filename) {
        FILE* file = fopen(output_filename, "w");
        if (!file) {
            perror("Failed to open file for writing");
            thread_safe_free(&mp);
            return EXIT_FAILURE;
        }

        fprintf(file, "%d\n", largest);
        fclose(file);
    }

    thread_safe_free(&mp);

    return 0;
}
