#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB for simplicity

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    size_t block_size;
    void* pool;
    pthread_mutex_t lock;
    size_t offset;
} MemoryPool;

typedef struct DataStructure {
    long* offsets;
    int* keys;
    record** records;
    size_t count;
} DataStructure;

pthread_mutex_t max_lock = PTHREAD_MUTEX_INITIALIZER;
int global_max = INT_MIN;

void log_event(const char* event, size_t size) {
    FILE* log_file = fopen("memory_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s: %zu bytes\n", ctime(&now), event, size);
        fclose(log_file);
    }
}

MemoryPool* create_memory_pool(size_t block_size) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    pthread_mutex_init(&mp->lock, NULL);
    mp->block_size = block_size;
    mp->pool = malloc(MEMORY_POOL_SIZE);
    mp->offset = 0;

    log_event("Memory pool created", MEMORY_POOL_SIZE);

    return mp;
}

void* allocate_from_pool(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);

    if (size > mp->block_size || mp->offset + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Allocation failed
    }

    void* block = ((char*)mp->pool) + mp->offset;
    mp->offset += size;

    log_event("Memory allocated", size);

    pthread_mutex_unlock(&mp->lock);
    return block;
}

void free_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);

        log_event("Memory pool destroyed", MEMORY_POOL_SIZE);
    }
}

int random_value_from_distribution(void (*pdf)(double, double*)) {
    // Simple uniform distribution for demonstration
    double rand_val = (double)rand() / RAND_MAX;
    return (int)(rand_val * 100); // Example transformation
}

void* populate_records(DataStructure* ds, void (*pdf)(double, double*)) {
    for (size_t i = 0; i < ds->count; ++i) {
        pthread_mutex_lock(&ds->records[i]->lock);
        ds->records[i]->value = random_value_from_distribution(pdf);
        pthread_mutex_unlock(&ds->records[i]->lock);
    }
    return NULL;
}

void* find_max(DataStructure* ds, int* result) {
    *result = INT_MIN;

    for (size_t i = 0; i < ds->count; ++i) {
        pthread_mutex_lock(&ds->records[i]->lock);

        if (ds->records[i]->value > *result) {
            *result = ds->records[i]->value;
        }

        pthread_mutex_unlock(&ds->records[i]->lock);
    }

    return NULL;
}

void initialize_data_structure(DataStructure* ds, size_t count) {
    MemoryPool* mp = create_memory_pool(sizeof(record));
    if (!mp) return;

    ds->count = count;
    ds->offsets = allocate_from_pool(mp, sizeof(long) * count);
    ds->keys = allocate_from_pool(mp, sizeof(int) * count);
    ds->records = (record**)allocate_from_pool(mp, sizeof(record*) * count);

    if (!ds->offsets || !ds->keys || !ds->records) {
        fprintf(stderr, "Memory allocation failed\n");
        free_memory_pool(mp);
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        ds->records[i] = allocate_from_pool(mp, sizeof(record));
        pthread_mutex_init(&ds->records[i]->lock, NULL);
    }
}

void destroy_data_structure(DataStructure* ds, MemoryPool* mp) {
    if (!mp || !ds) return;

    for (size_t i = 0; i < ds->count; ++i) {
        pthread_mutex_destroy(&ds->records[i]->lock);
        free(ds->records[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    free_memory_pool(mp);
}

void determine_largest_integer(DataStructure* ds, void (*pdf)(double, double*)) {
    pthread_t threads[2];
    int max_val = INT_MIN;

    populate_records(ds, pdf);

    pthread_create(&threads[0], NULL, find_max, (void*)ds);

    // Joining thread to ensure completion
    pthread_join(threads[0], NULL);

    pthread_mutex_lock(&max_lock);
    if (global_max < max_val) {
        global_max = max_val;
    }
    pthread_mutex_unlock(&max_lock);

    printf("Largest integer: %d\n", global_max);
}

int main() {
    srand(time(NULL));
    int numbers[1000];

    for (int i = 0; i < 1000; ++i) {
        scanf("%d", &numbers[i]);
    }

    DataStructure ds;
    initialize_data_structure(&ds, sizeof(numbers) / sizeof(numbers[0]));

    determine_largest_integer(&ds, NULL);

    destroy_data_structure(&ds, NULL);

    return 0;
}
