MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->mutex, NULL);
    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->offsets = NULL;
    pool->keys = NULL;
    pool->records = NULL;

    log_event("Memory pool created");

    return pool;
}

void free_memory_pool(MemoryPool* pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->mutex);

    deallocate_memory(pool, pool->offsets);
    deallocate_memory(pool, pool->keys);
    for (size_t i = 0; i < pool->used && pool->records[i]; ++i) {
        deallocate_memory(pool, pool->records[i]);
    }
    deallocate_memory(pool, pool->records);

    free(pool);
    log_event("Memory pool freed");
}

int allocate_memory(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->mutex);

    if (size == 0 || pool->used + size > pool->capacity) {
        resize_memory_pool(pool, pool->used + size);
        if (pool->used + size > pool->capacity) {
            log_event("Memory allocation failed after resizing");
            pthread_mutex_unlock(&pool->mutex);
            return -1;
        }
    }

    void* ptr = malloc(size);
    if (!ptr) {
        log_event("malloc failed");
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    pool->used += size;

    log_event("Memory allocated");
    pthread_mutex_unlock(&pool->mutex);

    return (int)(uintptr_t)ptr;
}

void deallocate_memory(MemoryPool* pool, void *ptr) {
    if (!ptr) return;

    pthread_mutex_lock(&pool->mutex);
    free(ptr);

    pool->used -= sizeof(*ptr); // Simplified for illustration

    log_event("Memory deallocated");
    pthread_mutex_unlock(&pool->mutex);
}

void resize_memory_pool(MemoryPool* pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return;

    log_event("Resizing memory pool");

    // Example of resizing strategy
    pool->capacity = new_capacity;
}

void log_event(const char* event) {
    time_t now;
    time(&now);
    printf("%s: %s\n", ctime(&now), event);
}
