#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

// Custom memory pool for records
typedef struct {
    size_t size;
    Record *pool;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t num_records) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->size = num_records;
    mp->pool = (Record*)calloc(num_records, sizeof(Record));
    pthread_mutex_init(&mp->lock, NULL);

    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed
    for (size_t i = 0; i < num_records; ++i)
        mp->pool[i].value = rand() % 100; // Random value between 0 and 99

    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (!mp) return;

    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

Record* get_record_from_pool(MemoryPool *mp, size_t index) {
    if (index >= mp->size) return NULL;

    pthread_mutex_lock(&mp->lock);
    Record *record = &mp->pool[index];
    pthread_mutex_unlock(&mp->lock);

    return record;
}

void DynamicResourceAndDataManager(size_t num_records) {
    MemoryPool *mp = create_memory_pool(num_records);
    if (!mp) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        return;
    }

    // Example of accessing a record
    Record *record = get_record_from_pool(mp, 0);
    if (record)
        printf("Record value: %d\n", record->value);

    destroy_memory_pool(mp);
}
