using System;
using System.Collections.Generic;

public class DynamicDataGenerator {
    private double minValue;
    private double maxValue;
    private double stepSize;

    public DynamicDataGenerator(double min, double max, double step) {
        if (min >= max || step <= 0)
            throw new ArgumentException("Invalid range or step size.");

        this.minValue = min;
        this.maxValue = max;
        this.stepSize = step;
    }

    public DynamicDataGenerator(string rangeStr) {
        var parts = rangeStr.Split(new[] { '-', ',' }, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length != 3)
            throw new ArgumentException("Invalid string format.");

        double min = Convert.ToDouble(parts[0]);
        double max = Convert.ToDouble(parts[1]);
        double step = Convert.ToDouble(parts[2]);

        this.minValue = min;
        this.maxValue = max;
        this.stepSize = step;

        if (min >= max || step <= 0)
            throw new ArgumentException("Invalid range or step size.");
    }

    public double GetRandomFloat() {
        Random rand = new Random();
        int steps = (int)((maxValue - minValue) / stepSize);
        return minValue + (rand.Next(steps) * stepSize);
    }

    public int GetRandomInt() {
        Random rand = new Random();
        return (int)(minValue + (rand.NextDouble() * (maxValue - minValue)));
    }

    public List<int> GetRandomList(int count) {
        Random rand = new Random();
        var list = new List<int>(count);

        for (int i = 0; i < count; i++)
            list.Add((int)(minValue + (rand.NextDouble() * (maxValue - minValue))));

        return list;
    }

    public void UpdateRange(double min, double max) {
        if (min >= max)
            throw new ArgumentException("Invalid range.");

        this.minValue = min;
        this.maxValue = max;
    }

    public override string ToString() {
        return $"[{minValue}, {maxValue}]";
    }
}
