#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <openssl/rand.h> // For cryptographically secure random numbers

// Define the record structure
typedef struct {
    int value;
} Record;

// Thread-safe hash map placeholder (e.g., using a third-party library)
typedef struct HashMap {
    // Implementation-specific fields
} HashMap;

extern void hashMapInit(HashMap* map);
extern void hashMapPut(HashMap* map, int key, Record* record);
extern Record* hashMapGet(HashMap* map, int key);

// Global mutex for thread-safe logging and memory operations
static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t allocMutex = PTHREAD_MUTEX_INITIALIZER;

/**
 * Function to allocate and initialize records.
 *
 * @param numRecords The number of records to create.
 * @param offsetLowerBound The lower bound for offsets.
 * @param offsetUpperBound The upper bound for offsets.
 * @param keyLowerBound The lower bound for keys.
 * @param keyUpperBound The upper bound for keys.
 * @param valueRange Lower and upper bounds for record values, passed as an array of two integers.
 * @param seed Optional seed for reproducibility. Use 0 for truly random numbers.
 *
 * @return Pointer to the allocated array of records, or NULL if allocation fails or validation fails.
 */
Record* allocateAndInitializeRecords(size_t numRecords, int offsetLowerBound, int offsetUpperBound,
                                     int keyLowerBound, int keyUpperBound, int valueRange[2],
                                     unsigned long seed) {
    pthread_mutex_lock(&allocMutex);

    // Allocate memory for offsets and keys
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    int *keys = (int *)malloc(numRecords * sizeof(int));

    if (!offsets || !keys) {
        logEvent("Memory allocation failed", 1);
        free(offsets); // Safe to call with NULL
        free(keys);
        pthread_mutex_unlock(&allocMutex);
        return NULL;
    }

    // Allocate memory for records, ensuring proper alignment
    Record *records = (Record *)aligned_alloc(64, numRecords * sizeof(Record));
    if (!records) {
        logEvent("Memory allocation failed", 1);
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&allocMutex);
        return NULL;
    }

    // Initialize random number generator
    unsigned char rndBuffer[8];
    if (seed != 0) {
        srand(seed); // Use deterministic RNG for reproducibility
    } else {
        RAND_bytes(rndBuffer, sizeof(rndBuffer));
    }

    // Populate offsets and keys with random values within bounds and validate them
    int valid = 1;
    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = offsetLowerBound + rand() % (offsetUpperBound - offsetLowerBound + 1);
        keys[i] = keyLowerBound + rand() % (keyUpperBound - keyLowerBound + 1);

        if (offsets[i] < offsetLowerBound || offsets[i] > offsetUpperBound ||
            keys[i] < keyLowerBound || keys[i] > keyUpperBound) {
            valid = 0;
            break;
        }
    }

    // If validation failed, free allocated memory
    if (!valid) {
        logEvent("Validation failed", 1);
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&allocMutex);
        return NULL;
    }

    // Populate records with random values within the specified range
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = valueRange[0] + rand() % (valueRange[1] - valueRange[0] + 1);
    }

    // Integrate into a thread-safe hash map (details omitted for brevity)
    HashMap recordMap;
    hashMapInit(&recordMap);

    for (size_t i = 0; i < numRecords; ++i) {
        hashMapPut(&recordMap, keys[i], &records[i]);
    }

    pthread_mutex_unlock(&allocMutex);
    logEvent("Memory allocated and initialized successfully", 0);

    return records;
}

/**
 * Logs memory allocation events with timestamps.
 *
 * @param message The message to be logged.
 * @param error Indicates if the event is an error (1) or successful operation (0).
 */
void logEvent(const char* message, int error) {
    pthread_mutex_lock(&logMutex);
    time_t now = time(NULL);
    const char* level = error ? "ERROR" : "INFO";

    printf("[%s] %s: %s\n", ctime(&now), level, message);

    pthread_mutex_unlock(&logMutex);
}

// External dependencies and their integration
/*
 * External Libraries:
 * - OpenSSL: Used for cryptographically secure random number generation.
 *   Integration involves linking with `-lcrypto` during compilation.
 *
 * - Third-party hash map library (e.g., uthash, jansson): Placeholder functions 
 *   demonstrate intended usage. Actual implementation would require integration
 *   and proper initialization based on the chosen library's documentation.
 */
```

