#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Entry {
    char *key;
    long offset;
    double value;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

// Function prototypes
List* create_list();
void destroy_list(List* list);
int add_entry(List* list, const char *key, long offset, double value);
Entry* get_entry(const List* list, const char *key);
int update_value(List* list, const char *key, double new_value);
void iterate_entries(const List* list);

// Create a new list
List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the list and free memory
void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->entry.key);  // Assuming keys are dynamically allocated
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add an entry to the list
int add_entry(List* list, const char *key, long offset, double value) {
    if (!key || strlen(key) == 0) return -1; // Validation check

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->entry.key = strdup(key);  // Duplicate key for safe storage
    if (!new_node->entry.key) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->entry.offset = offset;
    new_node->entry.value = value;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Retrieve an entry by key
Entry* get_entry(const List* list, const char *key) {
    if (!key || strlen(key) == 0) return NULL;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    while (current) {
        if (strcmp(current->entry.key, key) == 0) {
            pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
            return &current->entry;
        }
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return NULL; // Not found
}

// Update the value of an existing entry
int update_value(List* list, const char *key, double new_value) {
    Entry* entry = get_entry(list, key);
    if (!entry) return -1;

    pthread_mutex_lock(&list->lock);

    entry->value = new_value;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Iterate over all entries in the list
void iterate_entries(const List* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    Node* current = list->head;
    while (current) {
        printf("Key: %s, Offset: %ld, Value: %.2f\n", current->entry.key,
               current->entry.offset, current->entry.value);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

int main() {
    List* list = create_list();

    add_entry(list, "key1", 100, 3.14);
    add_entry(list, "key2", 200, 6.28);

    Entry* entry = get_entry(list, "key1");
    if (entry) printf("Retrieved: Key: %s, Offset: %ld, Value: %.2f\n",
                      entry->key, entry->offset, entry->value);

    update_value(list, "key1", 42.0);

    iterate_entries(list);

    destroy_list(list);

    return 0;
}
```

### Design Decisions and Trade-offs

- **Thread Safety**: A `pthread_mutex_t` is used to lock the list during modifications (additions, updates) to ensure thread safety in a high-concurrency environment.

- **Memory Management**: Dynamic memory allocation for keys ensures flexibility but requires careful management (e.g., freeing duplicated strings). Memory leaks are prevented by properly managing allocations and deallocations.

- **Efficiency**: Operations like adding an entry or updating an entry's value have been designed to lock only when necessary, minimizing contention. Iteration also locks the list temporarily to ensure a consistent view.

- **Scalability**: While the list is singly linked for simplicity, alternative data structures (like hash tables) could be considered for faster key lookups if scalability becomes an issue.

- **Garbage Collection and Memory Limits**: Not explicitly implemented here but can be integrated by tracking usage patterns or periodically checking for entries that haven't been accessed within a certain timeframe.']

