#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char status;
    double value;
    unsigned short timestamp;
} data_entry;

void log_message(const char *message) {
    printf("%s\n", message);
}

int load_data_from_csv(const char *filename, data_entry **entries, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_message("Error: Unable to open CSV file.");
        return -1;
    }

    char line[256];
    int capacity = 10;
    *entries = malloc(capacity * sizeof(data_entry *));
    if (*entries == NULL) {
        log_message("Error: Memory allocation failed for entries.");
        fclose(file);
        return -1;
    }
    *count = 0;

    while (fgets(line, sizeof(line), file)) {
        if (*count >= capacity) {
            capacity *= 2;
            data_entry **temp = realloc(*entries, capacity * sizeof(data_entry *));
            if (temp == NULL) {
                log_message("Error: Memory reallocation failed for entries.");
                free(*entries);
                fclose(file);
                return -1;
            }
            *entries = temp;
        }

        data_entry *entry = malloc(sizeof(data_entry));
        if (!entry) {
            log_message("Error: Memory allocation failed for a single entry.");
            continue; // Skip this entry on failure
        }

        char status;
        double value;
        unsigned short timestamp;

        if (sscanf(line, "%c,%lf,%hu", &status, &value, &timestamp) == 3) {
            entry->status = status;
            entry->value = value;
            entry->timestamp = timestamp;
        } else {
            log_message("Error: Failed to parse line from CSV.");
            free(entry);
            continue; // Skip this entry on parsing failure
        }

        (*entries)[*count] = entry;
        (*count)++;
    }

    fclose(file);
    return 0;
}

void initialize_arrays(int size, double *float_array, unsigned short *id_array,
                       data_entry ***entry_array, int seed, double max_value,
                       const char *csv_filename) {
    log_message("Initializing arrays...");

    srand(seed);

    for (int i = 0; i < size; ++i) {
        float_array[i] = ((double)rand() / RAND_MAX) * max_value;
        id_array[i] = rand() % 65536;

        data_entry *entry = malloc(sizeof(data_entry));
        if (!entry) {
            log_message("Error: Memory allocation failed for a single entry.");
            continue; // Skip this entry on failure
        }

        char status = 'A' + (rand() % 26);
        double value = ((double)rand() / RAND_MAX) * max_value;
        unsigned short timestamp = rand() % 65536;

        entry->status = status;
        entry->value = value;
        entry->timestamp = timestamp;

        (*entry_array)[i] = entry;
    }

    log_message("Loading initial data from CSV...");
    int count = 0;
    if (load_data_from_csv(csv_filename, *entry_array, &count) == -1) {
        log_message("Error: Failed to load data from CSV.");
    } else {
        for (int i = 0; i < count; ++i) {
            (*entry_array)[size + i] = (*entry_array)[i];
        }
    }

    int total_size = size + count;
    *entry_array = realloc(*entry_array, total_size * sizeof(data_entry *));
    if (*entry_array == NULL && total_size > size) {
        log_message("Error: Memory reallocation failed for entries.");
    }
}

int main() {
    int size = 100;
    double *float_array = malloc(size * sizeof(double));
    unsigned short *id_array = malloc(size * sizeof(unsigned short));
    data_entry **entry_array = malloc(size * sizeof(data_entry *));

    if (!float_array || !id_array || !entry_array) {
        log_message("Error: Memory allocation failed.");
        return -1;
    }

    initialize_arrays(size, float_array, id_array, &entry_array,
                      42, 100.0, "data.csv");

    // Cleanup
    for (int i = 0; i < size + 100; ++i) {
        free(entry_array[i]);
    }
    free(float_array);
    free(id_array);
    free(entry_array);

    return 0;
}
