['Below is a C implementation that addresses the requirements of managing a dynamic list of `entry` structures with thread safety, size limits, and CSV export capabilities:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Entry {
    char* key;
    long offset;
    double value;
    struct Entry* next;
} Entry;

typedef struct List {
    Entry* head;
    size_t size;
    size_t max_size;
    pthread_mutex_t lock;
} List;

typedef struct CSVConfig {
    const char* delimiter;
    int include_header;
} CSVConfig;

List* create_list(size_t max_size) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_entry(List* list, const char* key, long offset, double value) {
    if (!list || !key) return -1;

    pthread_mutex_lock(&list->lock);
    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    new_entry->key = strdup(key);
    if (!new_entry->key) {
        free(new_entry);
        pthread_mutex_unlock(&list->lock);
        return -4; // Memory allocation failed
    }
    new_entry->offset = offset;
    new_entry->value = value;
    new_entry->next = list->head;
    list->head = new_entry;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

Entry* get_entry(List* list, const char* key) {
    if (!list || !key) return NULL;

    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int update_entry(List* list, const char* key, long offset, double value) {
    if (!list || !key) return -1;

    pthread_mutex_lock(&list->lock);
    Entry* entry = get_entry(list, key);
    if (entry) {
        entry->offset = offset;
        entry->value = value;
        pthread_mutex_unlock(&list->lock);
        return 0;
    }
    pthread_mutex_unlock(&list->lock);
    return -5; // Entry not found
}

int delete_entry(List* list, const char* key) {
    if (!list || !key) return -1;

    pthread_mutex_lock(&list->lock);
    Entry** current = &list->head;
    while (*current) {
        if (strcmp((*current)->key, key) == 0) {
            Entry* to_delete = *current;
            *current = to_delete->next;
            free(to_delete->key);
            free(to_delete);
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -5; // Entry not found
}

void iterate_entries(List* list, void (*callback)(Entry*)) {
    if (!list || !callback) return;

    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void export_to_csv(List* list, const char* filename, CSVConfig config) {
    if (!list || !filename || !config.delimiter) return;

    FILE* file = fopen(filename, "a");
    if (!file) return;

    Entry* current;
    pthread_mutex_lock(&list->lock);
    if (config.include_header) {
        fprintf(file, "Key%sOffset%sValue\n", config.delimiter, config.delimiter);
    }
    for (current = list->head; current; current = current->next) {
        fprintf(file, "%s%s%ld%s%.2f\n", current->key, config.delimiter, current->offset, config.delimiter, current->value);
    }
    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void free_list(List* list) {
    if (!list) return;

    Entry* current;
    pthread_mutex_lock(&list->lock);
    while (list->head) {
        current = list->head;
        list->head = current->next;
        free(current->key);
        free(current);
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` is used to ensure thread-safe operations on the list.
- **Memory Management**: Proper allocation and deallocation are handled, with checks for failures.
- **CSV Export**: Configurable export with support for appending and headers.
- **Error Handling**: Returns error codes for various failure conditions.']

