#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_HASH_TABLE_SIZE 1024
#define PRUNE_INTERVAL 60 // seconds

typedef struct {
    long timestamp;
    int event_id;
    char *message;
} Event;

// Hash table entry
typedef struct HashNode {
    int key;
    Event value;
    struct HashNode* next;
} HashNode;

// Hash table structure
typedef struct {
    size_t size;
    HashNode** buckets;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
HashTable* create_hash_table(size_t initial_size);
unsigned long hash_function(int key, size_t table_size);
void insert_event(HashTable* table, int event_id, Event event);
Event* get_event(HashTable* table, int event_id);
void prune_old_events(HashTable* table, long current_time, long prune_threshold);

// Create a new hash table
HashTable* create_hash_table(size_t initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->buckets = (HashNode**)calloc(initial_size, sizeof(HashNode*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Custom hash function
unsigned long hash_function(int key, size_t table_size) {
    return ((unsigned long)key * 2654435761u) % table_size; // Knuth's multiplicative method
}

// Insert an event into the hash table
void insert_event(HashTable* table, int event_id, Event event) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(event_id, table->size);
    HashNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->key == event_id) {
            // Update existing entry
            free(node->value.message);  // Free old message memory
            node->value = event;
            pthread_mutex_unlock(&table->lock);
            return;
        }
        node = node->next;
    }

    // Create new node if not found
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->key = event_id;
    newNode->value = event;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;

    pthread_mutex_unlock(&table->lock);
}

// Retrieve an event from the hash table
Event* get_event(HashTable* table, int event_id) {
    unsigned long index = hash_function(event_id, table->size);
    HashNode* node = table->buckets[index];

    while (node != NULL) {
        if (node->key == event_id) {
            return &(node->value);
        }
        node = node->next;
    }

    return NULL; // Not found
}

// Prune old events based on the current time and threshold
void prune_old_events(HashTable* table, long current_time, long prune_threshold) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->size; ++i) {
        HashNode* node = table->buckets[i];
        HashNode* prev = NULL;

        while (node != NULL) {
            if ((current_time - node->value.timestamp) > prune_threshold) {
                if (prev == NULL) {
                    // Remove head
                    table->buckets[i] = node->next;
                } else {
                    // Remove middle or tail
                    prev->next = node->next;
                }
                Event* event = &node->value;
                free(event->message);
                HashNode* temp = node;
                node = node->next;
                free(temp);
            } else {
                prev = node;
                node = node->next;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Example usage and initialization
void initialize_logging_system(size_t initial_size) {
    HashTable* event_log = create_hash_table(initial_size);

    // Simulate inserting an event
    long timestamp = 1672531199; // Example timestamp
    int event_id = 12345;
    char* message = strdup("Event occurred");
    Event new_event = {timestamp, event_id, message};

    insert_event(event_log, event_id, new_event);

    // Simulate pruning old events
    long prune_threshold = 3600; // Prune events older than 1 hour
    prune_old_events(event_log, timestamp + PRUNE_INTERVAL * 2, prune_threshold);

    // Cleanup (not shown: freeing the hash table and its contents)
}

int main() {
    initialize_logging_system(INITIAL_HASH_TABLE_SIZE);
    return 0;
}
```

