class RecordManager {
private:
    using RecordMap = std::unordered_map<std::string, std::shared_ptr<Record>>;
    RecordMap records;
    mutable std::mutex mtx;

public:
    // Add a record to the collection
    bool addRecord(const std::string& key, int priority, const std::vector<int>& payload) {
        std::unique_lock lock(mtx);

        if (!validateKey(key)) {
            return false;  // Key validation failed
        }

        auto it = records.find(key);
        if (it != records.end()) {
            return false;  // Record with this key already exists
        }

        records.emplace(std::make_pair(key, std::make_shared<Record>(key, priority, payload)));
        return true;
    }

    // Retrieve a record by its key
    std::shared_ptr<Record> getRecord(const std::string& key) const {
        std::lock_guard lock(mtx);
        auto it = records.find(key);
        if (it != records.end()) {
            return it->second;
        }
        return nullptr;  // Record not found
    }

    // Update an existing record's payload
    bool updateRecordPayload(const std::string& key, const std::vector<int>& new_payload) {
        std::unique_lock lock(mtx);

        auto it = records.find(key);
        if (it != records.end()) {
            it->second->payload = new_payload;
            return true;
        }
        return false;  // Record not found
    }

    // Iterate over all records in the collection
    void forEachRecord(std::function<void(const std::shared_ptr<Record>&)> func) const {
        std::lock_guard lock(mtx);
        for (const auto& pair : records) {
            func(pair.second);
        }
