using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class LogEntry
{
    public DateTime Timestamp { get; set; }
    public string Message { get; set; }
    public string Category { get; set; } // "critical" or "non-critical"
}

public class LogProcessorConfig
{
    public TimeSpan EntryAgeThreshold { get; set; } = TimeSpan.FromDays(7);
    public int MinimumMessageOccurrences { get; set; } = 5;
    public int BatchSize { get; set; } = 1000; // Number of logs per batch for API call
}

public class LogProcessor
{
    private readonly ConcurrentQueue<LogEntry> _tempStorage = new();
    private readonly object _apiLock = new();

    public async Task ProcessLogsAsync(IEnumerable<LogEntry> logEntries, LogProcessorConfig config)
    {
        var filteredAndSortedEntries = FilterAndSort(logEntries, DateTime.UtcNow - config.EntryAgeThreshold);

        var messageFrequency = SummarizeMessages(filteredAndSortedEntries, config.MinimumMessageOccurrences);

        await SendBatchedToApiAsync(messageFrequency, config.BatchSize).ConfigureAwait(false);
    }

    private IEnumerable<LogEntry> FilterAndSort(IEnumerable<LogEntry> entries, DateTime threshold)
    {
        return entries
            .Where(entry => entry.Timestamp >= threshold)
            .OrderByDescending(e => e.Timestamp)
            .ThenBy(e => e.Category != "critical")
            .ToList();
    }

    private Dictionary<string, int> SummarizeMessages(IEnumerable<LogEntry> entries, int minOccurrences)
    {
        var messageCounts = new ConcurrentDictionary<string, int>();

        Parallel.ForEach(entries, entry =>
        {
            messageCounts.AddOrUpdate(entry.Message,
                1,
                (key, oldValue) => ++oldValue);
        });

        return messageCounts
            .Where(kvp => kvp.Value >= minOccurrences)
            .ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
    }

    private async Task SendBatchedToApiAsync(Dictionary<string, int> messageFrequency, int batchSize)
    {
        var batchedData = SplitIntoBatches(messageFrequency, batchSize);

        foreach (var batch in batchedData)
        {
            await TrySendToApiWithRetry(batch).ConfigureAwait(false);
        }
    }

    private IEnumerable<Dictionary<string, int>> SplitIntoBatches(Dictionary<string, int> data, int size)
    {
        var batches = new List<Dictionary<string, int>>();

        foreach (var chunk in data.Chunk(size))
        {
            batches.Add(chunk.ToDictionary(kvp => kvp.Key, kvp => kvp.Value));
        }

        return batches;
    }

    private async Task TrySendToApiWithRetry(Dictionary<string, int> batch)
    {
        const int maxRetries = 3;
        var retryCount = 0;

        while (retryCount < maxRetries)
        {
            try
            {
                await SendToExternalApiAsync(batch).ConfigureAwait(false);
                return;
            }
            catch (Exception)
            {
                if (++retryCount >= maxRetries)
                    _tempStorage.Enqueue(new LogEntry { Timestamp = DateTime.UtcNow, Message = "Failed to send log batch", Category = "error" });

                // Exponential backoff
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retryCount)));
            }
        }
    }

    private async Task SendToExternalApiAsync(Dictionary<string, int> batch)
    {
        lock (_apiLock) // Ensure only one API call at a time to avoid conflicts.
        {
            // Simulate sending data to an external logging service
            await Task.Delay(TimeSpan.FromSeconds(1)); // Mock network delay

            if (new Random().Next(10) < 2) // Random failure simulation for demonstration
                throw new Exception("Network error");
        }
    }

    public void UpdateConfig(LogProcessorConfig config)
    {
        // Update configuration dynamically without restarting the application
        // For example:
        // this.config.EntryAgeThreshold = config.EntryAgeThreshold;
        // this.config.MinimumMessageOccurrences = config.MinimumMessageOccurrences;
        // Note: Actual implementation may vary based on how configuration is used.
    }
}
```

