#define MAX_CACHE_SIZE 5

typedef struct {
    long offset;
    int key;
    double timestamp;
} entry;

typedef struct {
    int count;
    int* indices;
} log;

typedef struct cache_node {
    char *filename;
    char *data;
    time_t last_access_time;
    struct cache_node *prev, *next;
} cache_node;

cache_node *cache_head = NULL, *cache_tail = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

double get_system_memory() {
    return 16.0 * 1024 * 1024 * 1024; // Example: assume a system with 16 GB RAM
}

void *get_cache_node_data(const char *filename) {
    pthread_mutex_lock(&cache_lock);
    cache_node *current = cache_head;
    while (current != NULL) {
        if (strcmp(current->filename, filename) == 0) {
            current->last_access_time = time(NULL);
            if (current != cache_head) {
                if (current->prev) current->prev->next = current->next;
                if (current->next) current->next->prev = current->prev;
                if (cache_tail == current) cache_tail = current->prev;
                current->next = cache_head;
                if (cache_head) cache_head->prev = current;
                current->prev = NULL;
                cache_head = current;
            }
            pthread_mutex_unlock(&cache_lock);
            return current->data;
        }
        current = current->next;
    }

    // Load file and add to cache
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *data = malloc(length + 1);
    if (!data) {
        perror("malloc");
        fclose(file);
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }

    fread(data, 1, length, file);
    data[length] = '\0';
    fclose(file);

    // Add to cache
    if (cache_tail) {
        cache_node *new_node = malloc(sizeof(cache_node));
        new_node->filename = strdup(filename);
        new_node->data = data;
        new_node->last_access_time = time(NULL);
        new_node->prev = cache_tail;
        new_node->next = NULL;
        if (cache_head == NULL) {
            cache_head = new_node;
        } else {
            cache_tail->next = new_node;
        }
        cache_tail = new_node;

        // Remove least recently used node if necessary
        if (count_cache_nodes() > MAX_CACHE_SIZE) {
            cache_node *temp = cache_head;
            while (temp && temp->prev) {
                temp = temp->prev;
            }
            if (cache_head != NULL) {
                char *old_filename = cache_head->filename;
                char *old_data = cache_head->data;
                cache_head = cache_head->next;
                free(old_filename);
                free(old_data);
                free(temp);
            }
        }
    } else {
        // Cache is empty
        cache_node *new_node = malloc(sizeof(cache_node));
        new_node->filename = strdup(filename);
        new_node->data = data;
        new_node->last_access_time = time(NULL);
        new_node->prev = NULL;
        new_node->next = NULL;
        cache_head = new_node;
        cache_tail = new_node;
    }

    pthread_mutex_unlock(&cache_lock);
    return data;
}

int count_cache_nodes() {
    int count = 0;
    cache_node *current = cache_head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

void initialize_entries(int n, entry **entries) {
    double *timestamps = malloc(n * sizeof(double));
    if (!timestamps) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        timestamps[i] = ((double)rand() / RAND_MAX) * 100.0;
    }

    *entries = malloc(n * sizeof(entry));
    if (!(*entries)) {
        perror("malloc");
        free(timestamps);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n; ++i) {
        (*entries)[i].offset = i * 10;
        (*entries)[i].key = rand() % 100;
        (*entries)[i].timestamp = timestamps[i];
    }
    free(timestamps);
}

void initialize_logs(int m, log **logs, int entries_size) {
    *logs = malloc(m * sizeof(log));
    if (!(*logs)) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < m; ++i) {
        (*logs)[i].count = rand() % (entries_size / 2) + 1;
        (*logs)[i].indices = malloc((*logs)[i].count * sizeof(int));
        if (!(*logs)[i].indices) {
            perror("malloc");
            for (int j = 0; j < i; ++j) {
                free((*logs)[j].indices);
            }
            free(*logs);
            exit(EXIT_FAILURE);
        }

        for (int j = 0; j < (*logs)[i].count; ++j) {
            (*logs)[i].indices[j] = rand() % entries_size;
        }
    }
}

void process_config_files(const char *const *filenames, int num_files) {
    for (int i = 0; i < num_files; ++i) {
        const char *filename = filenames[i];
        char *data = get_cache_node_data(filename);

        if (!data) continue;

        char *line = strtok(data, "\n");
        while (line != NULL) {
            double field1 = 0.0, field2 = 0.0;
            int fields = sscanf(line, "%*s %lf %*s %lf", &field1, &field2);

            if (fields == 2) {
                printf("Average of last two numeric fields: %f\n", (field1 + field2) / 2);
            }

            line = strtok(NULL, "\n");
        }

        free(data);
    }
}

int main() {
    int entries_size = 100;
    entry *entries = NULL;
    initialize_entries(entries_size, &entries);

    int logs_size = 50;
    log *logs = NULL;
    initialize_logs(logs_size, &logs, entries_size);

