using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class SecureEncryptionService : IDisposable
{
    private readonly AesCryptoServiceProvider _aes16 = new AesCryptoServiceProvider { KeySize = 128 };
    private readonly AesCryptoServiceProvider _aes32 = new AesCryptoServiceProvider { KeySize = 256 };
    private static readonly HMACSHA256 _hmac = new HMACSHA256();
    private readonly object _lockObject = new object();

    public SecureEncryptionService(byte[] key16, byte[] key32)
    {
        if (key16 == null || key16.Length != 16) throw new ArgumentException("Key16 must be 16 bytes long.");
        if (key32 == null || key32.Length != 32) throw new ArgumentException("Key32 must be 32 bytes long.");

        _aes16.Key = key16;
        _aes32.Key = key32;
    }

    public byte[] Encrypt(byte[] data, bool useLongKey)
    {
        var aes = useLongKey ? _aes32 : _aes16;

        using (var encryptor = aes.CreateEncryptor())
        {
            var iv = new byte[16];
            RandomNumberGenerator.Fill(iv);
            aes.IV = iv;

            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                {
                    PadData(cs, data);
                    cs.FlushFinalBlock();

                    var encryptedData = ms.ToArray();
                    var hmac = _hmac.ComputeHash(encryptedData);

                    var result = new byte[hmac.Length + iv.Length + encryptedData.Length];
                    Buffer.BlockCopy(hmac, 0, result, 0, hmac.Length);
                    Buffer.BlockCopy(iv, 0, result, hmac.Length, iv.Length);
                    Buffer.BlockCopy(encryptedData, 0, result, hmac.Length + iv.Length, encryptedData.Length);

                    return result;
                }
            }
        }
    }

    public byte[] Decrypt(byte[] cipherText, bool useLongKey)
    {
        var aes = useLongKey ? _aes32 : _aes16;

        if (cipherText == null || cipherText.Length < 64) throw new ArgumentException("Cipher text is too short.");

        var hmacReceived = new byte[32];
        Buffer.BlockCopy(cipherText, 0, hmacReceived, 0, hmacReceived.Length);

        var iv = new byte[16];
        Buffer.BlockCopy(cipherText, 32, iv, 0, iv.Length);

        var encryptedData = new byte[cipherText.Length - 48];
        Buffer.BlockCopy(cipherText, 48, encryptedData, 0, encryptedData.Length);

        var hmacCalculated = _hmac.ComputeHash(encryptedData);
        if (!CompareByteArrays(hmacReceived, hmacCalculated))
            throw new CryptographicException("HMAC verification failed.");

        using (var decryptor = aes.CreateDecryptor())
        {
            aes.IV = iv;

            using (var ms = new MemoryStream(encryptedData))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    var result = UnpadData(cs);
                    return result;
                }
            }
        }
    }

    private void PadData(CryptoStream cryptoStream, byte[] data)
    {
        var paddingSize = 16 - (data.Length % 16);
        if (paddingSize != 0) 
            cryptoStream.Write(data.Concat(new byte[paddingSize]).ToArray(), 0, data.Length + paddingSize);
        else
            cryptoStream.Write(data, 0, data.Length);
    }

    private byte[] UnpadData(CryptoStream cryptoStream)
    {
        using (var ms = new MemoryStream())
        {
            cryptoStream.CopyTo(ms);
            var paddedData = ms.ToArray();

            if (paddedData[paddedData.Length - 1] > 16) throw new CryptographicException("Invalid padding.");

            var paddingSize = paddedData[paddedData.Length - 1];
            return paddedData.Take(paddedData.Length - paddingSize).ToArray();
        }
    }

    private bool CompareByteArrays(byte[] array1, byte[] array2)
    {
        lock (_lockObject)
        {
            if (array1.Length != array2.Length) return false;
            for (int i = 0; i < array1.Length; i++)
                if (array1[i] != array2[i]) return false;
            return true;
        }
    }

    public void LogDecryptionAttempt(bool success, Exception exception = null)
    {
        // External logging logic here
        Console.WriteLine($"Decryption attempt: {(success ? "Success" : "Failure")}, Exception: {exception?.Message}");
    }

    public void Dispose()
    {
        _aes16.Dispose();
        _aes32.Dispose();
        _hmac.Clear();
    }
}

public static class SecureEncryptionServiceExtensions
{
    public static async Task<byte[]> EncryptAsync(this SecureEncryptionService service, byte[] data, bool useLongKey)
    {
        return await Task.Run(() => service.Encrypt(data, useLongKey));
    }

    public static async Task<byte[]> DecryptAsync(this SecureEncryptionService service, byte[] cipherText, bool useLongKey)
    {
        try
        {
            var result = await Task.Run(() => service.Decrypt(cipherText, useLongKey));
            return result;
        }
        catch (Exception ex)
        {
            // Retry logic could be implemented here with exponential backoff if needed.
            throw; 
        }
    }

    public static async Task<byte[]> DecryptWithRetryAsync(this SecureEncryptionService service, byte[] cipherText, bool useLongKey, int maxRetries = 3)
    {
        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                return await service.DecryptAsync(cipherText, useLongKey);
            }
            catch (Exception ex) when (!(ex is OperationCanceledException))
            {
                // Log failure and retry logic
                if (attempt == maxRetries - 1)
                    throw;
                await Task.Delay(TimeSpan.FromSeconds(attempt + 1)); 
            }
        }

        return null; // This line should never be reached.
    }
}
