<?php

class MemoryPool {
    private $pool;
    private $initialSize;
    private $growthRate;
    private $maxCapacity;

    public function __construct($initialSize = 10, $growthRate = 5, $maxCapacity = 100) {
        $this->initialSize = $initialSize;
        $this->growthRate = $growthRate;
        $this->maxCapacity = $maxCapacity;
        $this->pool = array_fill(0, $initialSize, null);
    }

    public function allocate() {
        for ($i = 0; $i < count($this->pool); $i++) {
            if (is_null($this->pool[$i])) {
                return &$this->pool[$i];
            }
        }

        if (count($this->pool) + $this->growthRate <= $this->maxCapacity) {
            $this->pool = array_merge($this->pool, array_fill(0, $this->growthRate, null));
            return $this->allocate();
        } else {
            throw new Exception("Memory pool exhausted");
        }
    }

    public function deallocate(&$record) {
        foreach ($this->pool as &$slot) {
            if ($slot === $record) {
                $slot = null;
                break;
            }
        }
    }
}

class StrategyManager {
    private $memoryPool;
    private $lock;

    public function __construct($initialSize, $growthRate, $maxCapacity) {
        $this->memoryPool = new MemoryPool($initialSize, $growthRate, $maxCapacity);
        $this->lock = new \Mutex();
    }

    public function executeStrategy() {
        \Mutex::lock($this->lock);

        try {
            $record = $this->memoryPool->allocate();
            if (is_null($record)) {
                throw new Exception("Failed to allocate memory");
            }

            $strategyType = rand(1, 3);
            $lastActivationTime = microtime(true) - 10;
            $uniqueIdentifier = bin2hex(random_bytes(25));

            $record[0] = $strategyType;
            $record[1] = $lastActivationTime;
            $record[2] = $uniqueIdentifier;

            // Simulate strategy execution
            echo "Executing strategy type: $strategyType\n";
        } catch (Exception $e) {
            echo "Error: " . $e->getMessage();
        } finally {
            \Mutex::unlock($this->lock);
        }
    }

    public function findLargestStrategyType() {
        \Mutex::lock($this->lock);

        try {
            $largest = PHP_INT_MIN;
            foreach ($this->memoryPool->pool as $record) {
                if (!is_null($record)) {
                    if ($record[0] > $largest) {
                        $largest = $record[0];
                    }
                }
            }

            echo "Largest strategy type: $largest\n";
        } catch (Exception $e) {
            echo "Error: " . $e->getMessage();
        } finally {
            \Mutex::unlock($this->lock);
        }
    }
}

function validateUserInputs($name, $email, $password, $id = null, $sub_action = null) {
    if (strlen($name) < 2 || strlen($name) > 50) {
        return json_encode(['message' => 'Invalid name length', 'data' => null]);
