    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return json_encode(['message' => 'Invalid email format', 'data' => null]);
    }

    $passwordPattern = '/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/';
    if (!preg_match($passwordPattern, $password)) {
        return json_encode(['message' => 'Password must be at least 8 characters long and include uppercase, lowercase, numeric, and special characters', 'data' => null]);
    }

    // Simulate checking for duplicate emails
    $existingEmails = ['test@example.com'];
    if (in_array($email, $existingEmails)) {
        return json_encode(['message' => 'Duplicate email found', 'data' => null]);
    }

    // Handle user actions based on id and sub_action
    if ($sub_action === 'delete') {
        // Simulate checking for associated sessions
        $associatedSessions = false;
        if ($associatedSessions) {
            return json_encode(['message' => 'Cannot delete account with active sessions', 'data' => null]);
        }
    }

    return json_encode(['message' => 'Success', 'data' => ['id' => $id ?? uniqid()]]);
}

