function runTests(module) {
    const testResults = [];

    try {
        if (!module || typeof module.run !== 'function') {
            throw new Error("Invalid module");
        }

        module.run(tests => {
            tests.forEach(test => {
                try {
                    const result = test.fn();
                    if (result !== true) {
                        throw new Error(`Test failed: ${test.name}`);
                    }
                } catch (error) {
                    console.error(error.message);
                    testResults.push({ name: test.name, passed: false });
                }
            });

            tests.forEach(test => {
                if (!testResults.find(result => result.name === test.name)) {
                    testResults.push({ name: test.name, passed: true });
                }
            });

            const passedTests = testResults.filter(result => result.passed).length;
            console.log(`Passed ${passedTests} out of ${tests.length} tests.`);
        });
    } catch (error) {
        console.error("Test execution error:", error.message);
    }
}

// Example module with a run function
const exampleModule = {
    run: callback => {
        const tests = [
            { name: 'Test 1', fn: () => true },
            { name: 'Test 2', fn: () => false }, // This will fail
            { name: 'Test 3', fn: () => true }
        ];
        callback(tests);
    }
};

runTests(exampleModule);
