### C++ Function for Managing a Dynamic Task List

```cpp
#include <iostream>
#include <string>
#include <ctime>
#include <cstdlib>
#include <mutex>
#include <thread>

struct Task {
    int priority;
    std::string description;
    time_t dueDate;
    Task* next;

    Task(int p, const std::string& desc, time_t date)
        : priority(p), description(desc), dueDate(date), next(nullptr) {}
};

class TaskManager {
private:
    Task* head;
    std::mutex mtx;

public:
    TaskManager() : head(nullptr) {}

    void addTask(const std::string& description, const time_t dueDate) {
        int priority = rand() % 5 + 1;
        std::lock_guard<std::mutex> lock(mtx);
        Task* newTask = new Task(priority, description, dueDate);

        if (!head || head->priority > newTask->priority) {
            newTask->next = head;
            head = newTask;
        } else {
            Task* current = head;
            while (current->next && current->next->priority <= newTask->priority) {
                current = current->next;
            }
            newTask->next = current->next;
            current->next = newTask;
        }
    }

    void removeCompletedTasks() {
        std::lock_guard<std::mutex> lock(mtx);
        time_t now = time(nullptr);
        Task* prev = nullptr;
        Task* current = head;

        while (current) {
            if (difftime(current->dueDate, now) <= 0) { // Task is completed
                if (prev) {
                    prev->next = current->next;
                } else {
                    head = current->next;
                }
                Task* toDelete = current;
                current = current->next;
                delete toDelete;
            } else {
                prev = current;
                current = current->next;
            }
        }
    }

    void printTasks() {
        std::lock_guard<std::mutex> lock(mtx);
        Task* current = head;
        while (current) {
            std::cout << "Task: " << current->description
                      << ", Priority: " << current->priority
                      << ", Due Date: " << ctime(&current->dueDate)
                      << std::endl;
            current = current->next;
        }
    }

    ~TaskManager() {
        while (head) {
            Task* toDelete = head;
            head = head->next;
            delete toDelete;
        }
    }
};

void generateRandomDescription(std::string& desc) {
    const char charset[] =
        "0123456789"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz";
    for (int i = 0; i < rand() % 20 + 1; ++i) {
        desc += charset[rand() % (sizeof(charset) - 1)];
    }
}

void createTasks(TaskManager& manager, int numTasks) {
    time_t now = time(nullptr);
    for (int i = 0; i < numTasks; ++i) {
        std::string description;
        generateRandomDescription(description);
        // Random due date within the next 30 days
        time_t dueDate = now + rand() % (60 * 60 * 24 * 30);
        manager.addTask(description, dueDate);
    }
}

int main() {
    srand(static_cast<unsigned>(time(nullptr)));
    TaskManager manager;

    std::thread t1(createTasks, std::ref(manager), 10);
    std::thread t2(createTasks, std::ref(manager), 15);

    t1.join();
    t2.join();

    manager.printTasks();
    manager.removeCompletedTasks();
    manager.printTasks();

    return 0;
}
```

These implementations handle asynchronous image processing and task management with concurrency considerations. The Java function processes images using a fixed thread pool, applies filters, saves processed images, and retrieves metadata with retry logic. The C++ function manages tasks in a priority-sorted linked list with mutex-protected operations for concurrent access.']

