#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dns.h> // Assume a DNS library is available
#include <time.h>

#define MAX_ENTRIES 10000
#define LINE_BUFFER_SIZE 1024

typedef struct {
    int value;
} record;

// Function to initialize random numbers in records
void init_records(record *records, size_t count) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 100 + 1; // Random number between 1 and 100
    }
}

// Function to allocate memory safely
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// DNS caching mechanism
typedef struct {
    char *hostname;
    char *ip_address;
} dns_cache_entry;

#define CACHE_SIZE 1024
dns_cache_entry cache[CACHE_SIZE];
int cache_count = 0;

char* resolve_dns(const char* hostname) {
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            return strdup(cache[i].ip_address);
        }
    }

    // Resolve DNS
    char *ip_address = gethostbyname(hostname); // Assume this function exists in the DNS library
    if (!ip_address) {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        return NULL;
    }

    // Cache result
    if (cache_count < CACHE_SIZE) {
        cache[cache_count].hostname = strdup(hostname);
        cache[cache_count].ip_address = ip_address;
        cache_count++;
    }
    return ip_address;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input.csv> <output.csv>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    FILE *output_file = fopen(argv[2], "w");
    if (!output_file) {
        perror("Failed to open output file");
        fclose(input_file);
        return EXIT_FAILURE;
    }

    // Allocate and initialize data structures
    long *offsets = safe_malloc(MAX_ENTRIES * sizeof(long));
    int *keys = safe_malloc(MAX_ENTRIES * sizeof(int));
    record *records = safe_malloc(MAX_ENTRIES * sizeof(record));
    init_records(records, MAX_ENTRIES);

    char line[LINE_BUFFER_SIZE];
    size_t line_count = 0;

    while (fgets(line, LINE_BUFFER_SIZE, input_file) && line_count < MAX_ENTRIES) {
        // Extract last two numeric fields
        char *token;
        int num_fields[2] = {0, 0};
        int field_index = -1;

        token = strtok(line, ",");
        while (token != NULL) {
            field_index++;
            if (field_index >= 2 && sscanf(token, "%d", &num_fields[field_index - 2]) == 1) {
                // Found two numeric fields
                break;
            }
            token = strtok(NULL, ",");
        }

        if (field_index < 1 || field_index > 2) {
            fprintf(stderr, "Malformed entry: %s", line);
            continue; // Skip malformed entries
        }

        double average = (num_fields[0] + num_fields[1]) / 2.0;
        char *output_line = safe_malloc(strlen(line) + 30); // Additional space for average

        snprintf(output_line, strlen(line) + 30, "%s%.2f\n", line, average);
        fputs(output_line, output_file);

        free(offsets[line_count]); // Free previous allocation
        offsets[line_count] = safe_malloc(strlen(line) + 30); // Reallocate with new size
        strcpy(offsets[line_count], output_line);
        free(output_line);

        line_count++;
    }

    fclose(input_file);
    fclose(output_file);

    free(offsets);
    free(keys);
    for (size_t i = 0; i < cache_count; ++i) {
        free(cache[i].hostname);
        free(cache[i].ip_address);
    }
    free(records);

    return EXIT_SUCCESS;
}
