const AWS = require('aws-sdk');
const axios = require('axios');
const crypto = require('crypto');

// Initialize S3 client
const s3 = new AWS.S3();

async function processFile(file, metadata) {
  const allowedTypes = ['image/jpeg', 'image/png', 'application/pdf'];
  const maxFileSize = 10 * 1024 * 1024; // 10 MB

  if (!allowedTypes.includes(file.type)) {
    throw new Error('Unsupported file type');
  }

  if (file.size > maxFileSize) {
    throw new Error('File size exceeds limit');
  }

  let base64String = await convertToBase64(file);
  let retries = 0;

  while (retries < 3) {
    try {
      const s3Response = await uploadToS3(base64String, metadata.filename);
      const apiResponse = await sendMetadata(metadata);

      logSuccess(s3Response.Key);
      return { fileId: crypto.randomBytes(16).toString('hex'), url: s3Response.Location };
    } catch (error) {
      retries++;
      if (retries >= 3) {
        logFailure(error.message);
        throw new Error('Failed to process file after multiple attempts');
      }
    }
  }
}

async function convertToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

async function uploadToS3(base64String, filename) {
  const buffer = Buffer.from(base64String, 'base64');
  return s3.upload({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: `${crypto.randomBytes(16).toString('hex')}-${filename}`,
    Body: buffer,
    ContentType: file.type
  }).promise();
}

async function sendMetadata(metadata) {
  try {
    const response = await axios.post(process.env.API_GATEWAY_URL, metadata);
    return response.data;
  } catch (error) {
    throw new Error(`API Gateway error: ${error.message}`);
  }
}

function logSuccess(key) {
  // Log successful operations to a centralized analytics service
  console.log(`Successfully uploaded: ${key}`); // Placeholder for actual logging
}

function logFailure(message) {
  // Log failures minimally
  console.error(`Upload failed: ${message}`); // Placeholder for actual error logging
}
