['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_TABLE_SIZE 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    time_t timestamp;
    int event_id;
    char *message;
} Event;

typedef struct HashNode {
    int key; // Event ID
    Event data;
    struct HashNode *next;
} HashNode;

typedef struct {
    size_t capacity;
    size_t size;
    double load_factor_threshold;
    HashNode **buckets;
    pthread_mutex_t lock;
} HashTable;

// Utility functions for memory allocation and error handling
void check_allocation(void *ptr, const char* message) {
    if (!ptr) {
        fprintf(stderr, "Allocation failed: %s\n", message);
        exit(EXIT_FAILURE);
    }
}

HashTable* create_hash_table(size_t initial_capacity, double load_factor_threshold) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    check_allocation(table, "Creating hash table");

    table->capacity = initial_capacity;
    table->size = 0;
    table->load_factor_threshold = load_factor_threshold;
    table->buckets = (HashNode**)calloc(initial_capacity, sizeof(HashNode*));
    check_allocation(table->buckets, "Allocating buckets");

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

// Custom hash function
unsigned int hash_function(int key, size_t capacity) {
    return key % capacity;
}

// Resize and rehash the table
void resize_hash_table(HashTable *table);

// Insert event into the hash table
int insert_event(HashTable *table, Event event) {
    pthread_mutex_lock(&table->lock);

    if ((double)table->size / table->capacity > table->load_factor_threshold) {
        resize_hash_table(table);
    }

    unsigned int index = hash_function(event.event_id, table->capacity);
    HashNode *node = (HashNode*)malloc(sizeof(HashNode));
    check_allocation(node, "Allocating new node");

    node->key = event.event_id;
    node->data = event;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->size++;

    pthread_mutex_unlock(&table->lock);
    return 0; // Success
}

// Lookup an event by ID
Event* lookup_event(HashTable *table, int event_id) {
    unsigned int index = hash_function(event_id, table->capacity);
    HashNode *node = table->buckets[index];

    while (node) {
        if (node->key == event_id)
            return &node->data;
        node = node->next;
    }
    return NULL; // Not found
}

// Remove an event by ID
int remove_event(HashTable *table, int event_id) {
    pthread_mutex_lock(&table->lock);

    unsigned int index = hash_function(event_id, table->capacity);
    HashNode *node = table->buckets[index];
    HashNode *prev = NULL;

    while (node) {
        if (node->key == event_id) {
            if (prev)
                prev->next = node->next;
            else
                table->buckets[index] = node->next;

            free(node);
            table->size--;
            pthread_mutex_unlock(&table->lock);
            return 0; // Success
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1; // Not found
}

// Periodically prune old events
void prune_old_events(HashTable *table, time_t current_time, time_t age_threshold) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode **node = &table->buckets[i];
        while (*node) {
            if ((current_time - (*node)->data.timestamp) > age_threshold) {
                HashNode *to_remove = *node;
                *node = to_remove->next;

                free(to_remove->data.message);
                free(to_remove);
                table->size--;
            } else {
                node = &(*node)->next;
            }
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Resize and rehash the hash table
void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    HashNode **new_buckets = (HashNode**)calloc(new_capacity, sizeof(HashNode*));
    check_allocation(new_buckets, "Allocating new buckets");

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            unsigned int new_index = hash_function(node->key, new_capacity);
            HashNode *next_node = node->next;

            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

// Serialization functions
void serialize_to_file(HashTable *table, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fwrite(&table->capacity, sizeof(size_t), 1, file);
    fwrite(&table->size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            fwrite(&node->key, sizeof(int), 1, file);
            fwrite(&(node->data.timestamp), sizeof(time_t), 1, file);

            size_t msg_len = strlen(node->data.message) + 1;
            fwrite(&msg_len, sizeof(size_t), 1, file);
            fwrite(node->data.message, sizeof(char), msg_len, file);

            node = node->next;
        }
    }

    fclose(file);
}

// Deserialization functions
HashTable* deserialize_from_file(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return NULL;
    }

    HashTable *table = create_hash_table(INITIAL_TABLE_SIZE, LOAD_FACTOR_THRESHOLD);

    fread(&table->capacity, sizeof(size_t), 1, file);
    fread(&table->size, sizeof(size_t), 1, file);

    table->buckets = (HashNode**)calloc(table->capacity, sizeof(HashNode*));

    while (!feof(file)) {
        int key;
        time_t timestamp;
        size_t msg_len;

        if (fread(&key, sizeof(int), 1, file) != 1) break;
        fread(&timestamp, sizeof(time_t), 1, file);
        fread(&msg_len, sizeof(size_t), 1, file);

        Event event = { .timestamp = timestamp, .event_id = key };
        char *message = (char*)malloc(msg_len);
        check_allocation(message, "Allocating message");

        fread(message, sizeof(char), msg_len, file);
        event.message = message;

        insert_event(table, event);
    }

    fclose(file);
    return table;
}

// Query by timestamp
void query_by_timestamp(HashTable *table, time_t min_time, time_t max_time) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            if (node->data.timestamp >= min_time && node->data.timestamp <= max_time) {
                printf("Event ID: %d, Timestamp: %ld, Message: %s\n", 
                       node->key, node->data.timestamp, node->data.message);
            }
            node = node->next;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

// Clean up and free the hash table
void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *next = node->next;
            free(node->data.message);
            free(node);
            node = next;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Main function for testing
int main() {
    HashTable *log_table = create_hash_table(INITIAL_TABLE_SIZE, LOAD_FACTOR_THRESHOLD);

    Event event1 = { .timestamp = time(NULL), .event_id = 1, .message = "Event 1" };
    insert_event(log_table, event1);

    Event event2 = { .timestamp = time(NULL) - 1000, .event_id = 2, .message = "Event 2" };
    insert_event(log_table, event2);

    printf("Looking up event with ID 1:\n");
    Event *found_event = lookup_event(log_table, 1);
    if (found_event)
        printf("Found: %d, %ld, %s\n", found_event->event_id, found_event->timestamp, found_event->message);

    printf("\nQuerying events between now - 500 and now:\n");
    query_by_timestamp(log_table, time(NULL) - 500, time(NULL));

    serialize_to_file(log_table, "events.dat");

    destroy_hash_table(log_table);

    HashTable *loaded_table = deserialize_from_file("events.dat");
    printf("\nDeserialized Table Lookup for event ID 2:\n");
    found_event = lookup_event(loaded_table, 2);
    if (found_event)
        printf("Found: %d, %ld, %s\n", found_event->event_id, found_event->timestamp, found_event->message);

    destroy_hash_table(loaded_table);

    return 0;
}
