// Thread-safe random number generator
int thread_safe_rand(int min, int max) {
    static pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&rand_lock);
    return (rand() % (max - min + 1)) + min;
}

void initialize_system() {
    srand(time(NULL));

    long *timestamps = malloc(MAX_EVENTS * sizeof(long));
    int *event_ids = malloc(MAX_EVENTS * sizeof(int));
    Event *events = malloc(MAX_EVENTS * sizeof(Event));
    double *values = malloc(MAX_EVENTS * sizeof(double));
    unsigned short *identifiers = malloc(MAX_EVENTS * sizeof(unsigned short));

    for (size_t i = 0; i < MAX_EVENTS; ++i) {
        timestamps[i] = rand();
        event_ids[i] = thread_safe_rand(1, 10000);

        char message[MAX_MESSAGE_LENGTH];
        snprintf(message, MAX_MESSAGE_LENGTH, "Event %d", event_ids[i]);
        events[i].message = strdup(message);

        values[i] = (double)thread_safe_rand(-1000, 1000) / 100.0;
        if (fabs(values[i]) > MAX_VALUE_MAGNITUDE)
            values[i] = copysign(MAX_VALUE_MAGNITUDE, values[i]);

        identifiers[i] = thread_safe_rand(1, 65535);

        events[i].timestamp = timestamps[i];
        events[i].event_id = event_ids[i];

        pthread_t manager_thread;
        if (pthread_create(&manager_thread, NULL, event_log_manager, &events[i])) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
        pthread_detach(manager_thread); // Automatically clean up resources
    }

    HashTable hash_table;
    hash_table_init(&hash_table, 1024);

    for (size_t i = 0; i < MAX_EVENTS; ++i) {
        DataEntry entry = {'A', values[i], identifiers[i]};
        hash_table_insert(&hash_table, event_ids[i], entry);
    }

    load_initial_data("initial_data.csv");

    // Periodically prune old events
    while (1) {
        sleep(PRUNE_INTERVAL);
        prune_events();
    }
}

void *event_log_manager(void *arg) {
    Event *event = (Event *)arg;

    // Manage event logs here
    printf("Managing event ID: %d\n", event->event_id);

    free(event->message);
    pthread_exit(NULL);
}

void hash_table_init(HashTable *table, size_t capacity) {
    table->capacity = capacity;
    table->size = 0;
    table->entries = calloc(capacity, sizeof(DataEntry *));
    pthread_mutex_init(&table->lock, NULL);
}

unsigned int custom_hash(int event_id, size_t table_capacity) {
    return (event_id * 2654435761u) % table_capacity; // FNV-1a hash
}

DataEntry* hash_table_insert(HashTable *table, int event_id, DataEntry entry) {
    unsigned int index = custom_hash(event_id, table->capacity);

    pthread_mutex_lock(&table->lock);
    while (table->entries[index] != NULL) {
        if (((DataEntry *)table->entries[index])->event_id == event_id) {
            // Handle collision
            index = (index + 1) % table->capacity;
        } else {
            break;
        }
    }

    DataEntry *new_entry = malloc(sizeof(DataEntry));
    memcpy(new_entry, &entry, sizeof(DataEntry));
    new_entry->event_id = event_id; // Store ID in entry for easy lookup
    table->entries[index] = new_entry;

    pthread_mutex_unlock(&table->lock);
    return new_entry;
}

void prune_events() {
