    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Parse CSV and initialize data
        printf("Loading initial data: %s", line);
    }

    fclose(file);
}

int main() {
    initialize_system();
    return 0;
}
