```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    unsigned char *pool;
    size_t total_size;
    size_t used_size;
    pthread_mutex_t lock;
    void (*log)(const char *);
} memory_pool;

memory_pool* create_memory_pool(size_t initial_size, void (*log_func)(const char *)) {
    memory_pool *mp = malloc(sizeof(memory_pool));
    mp->pool = malloc(initial_size);
    mp->total_size = initial_size;
    mp->used_size = 0;
    pthread_mutex_init(&mp->lock, NULL);
    mp->log = log_func;
    return mp;
}

void* allocate_from_pool(memory_pool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_size + size > mp->total_size) {
        size_t new_size = mp->total_size * 2;
        unsigned char *new_pool = realloc(mp->pool, new_size);
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        mp->pool = new_pool;
        mp->total_size = new_size;
    }
    void *ptr = (void*)(mp->pool + mp->used_size);
    mp->used_size += size;
    pthread_mutex_unlock(&mp->lock);
    if (mp->log) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Allocated %zu bytes. Total used: %zu bytes.", size, mp->used_size);
        mp->log(log_msg);
    }
    return ptr;
}

void deallocate_from_pool(memory_pool *mp, void *ptr, size_t size) {
    pthread_mutex_lock(&mp->lock);
    // Simplified; real implementation would track allocations
    if (mp->log) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Deallocated %zu bytes.", size);
        mp->log(log_msg);
    }
    pthread_mutex_unlock(&mp->lock);
}

record* create_record(memory_pool *mp, int min_val, int max_val) {
    record *rec = (record*)allocate_from_pool(mp, sizeof(record));
    if (!rec) return NULL;
    rec->value = rand() % (max_val - min_val + 1) + min_val;
    return rec;
}

void serialize_records(record **records, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    fwrite(&count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < count; ++i) {
        fwrite(records[i], sizeof(record), 1, file);
    }
    fclose(file);
}

record** deserialize_records(const char *filename, size_t *count) {
    FILE *file = fopen(filename, "rb");
    fread(count, sizeof(size_t), 1, file);
    record **records = malloc(*count * sizeof(record*));
    for (size_t i = 0; i < *count; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        fread(records[i], sizeof(record), 1, file);
    }
    fclose(file);
    return records;
}

void log_memory_usage(const char *message) {
    printf("%s\n", message);
}

int main() {
    srand(time(NULL));

    memory_pool *mp = create_memory_pool(1024, log_memory_usage);

    int key_count = 10;
    record **records = malloc(key_count * sizeof(record*));
    for (int i = 0; i < key_count; ++i) {
        records[i] = create_record(mp, 1, 100);
    }

    serialize_records(records, key_count, "records.dat");

    size_t deserialized_count;
    record **deserialized_records = deserialize_records("records.dat", &deserialized_count);

    for (size_t i = 0; i < deserialized_count; ++i) {
        printf("Record %zu: Value = %d\n", i, deserialized_records[i]->value);
        free(deserialized_records[i]);
    }
    free(deserialized_records);
    free(records);
    free(mp->pool);
    free(mp);

    return 0;
}
