['```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
import <stdbool.h>
#include <time.h>

// Define structures
typedef struct {
    double x;
    double y;
} Point;

typedef struct {
    time_t timestamp;
    bool status_flag;
} Event;

typedef struct {
    Point point;
    double value;
    bool status;
} Transaction;

// Memory pool structure for transactions
typedef struct {
    size_t capacity;
    size_t used;
    size_t threshold;
    Transaction *transactions;
    pthread_mutex_t lock;
} TransactionPool;

// Logging mechanism
void log_memory_usage(const char *message, size_t current_usage) {
    printf("%s: %zu bytes\n", message, current_usage);
}

// Function to initialize memory pool
TransactionPool* init_transaction_pool(size_t initial_capacity, double threshold_percentage) {
    TransactionPool *pool = (TransactionPool *)malloc(sizeof(TransactionPool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->threshold = (size_t)(initial_capacity * threshold_percentage);
    pool->transactions = (Transaction *)calloc(initial_capacity, sizeof(Transaction));

    if (!pool->transactions) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to resize memory pool
int resize_transaction_pool(TransactionPool *pool) {
    size_t new_capacity = pool->capacity * 2;
    Transaction *new_transactions = (Transaction *)realloc(pool->transactions, new_capacity * sizeof(Transaction));

    if (!new_transactions) return -1;

    pool->transactions = new_transactions;
    pool->capacity = new_capacity;
    log_memory_usage("Resized memory pool", new_capacity * sizeof(Transaction));
    return 0;
}

// Function to add a transaction
int add_transaction(TransactionPool *pool, Point point, double value, bool status) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used >= pool->threshold && resize_transaction_pool(pool) != 0) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    Transaction new_transaction = { .point = point, .value = value, .status = status };
    pool->transactions[pool->used++] = new_transaction;

    log_memory_usage("Added transaction", (pool->used + 1) * sizeof(Transaction));

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Function to serialize transactions
int serialize_transactions(const TransactionPool *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t data_size = pool->used * sizeof(Transaction);
    fwrite(&data_size, sizeof(size_t), 1, file);
    fwrite(pool->transactions, sizeof(Transaction), pool->used, file);

    fclose(file);
    return 0;
}

// Function to deserialize transactions
TransactionPool* deserialize_transactions(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    size_t data_size;
    fread(&data_size, sizeof(size_t), 1, file);

    TransactionPool *pool = init_transaction_pool(data_size, 0.75);
    if (!pool) {
        fclose(file);
        return NULL;
    }

    fread(pool->transactions, sizeof(Transaction), data_size, file);
    pool->used = data_size;

    fclose(file);
    return pool;
}

// Function to clean up memory pool
void free_transaction_pool(TransactionPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->transactions);
    free(pool);
}

// Example function demonstrating usage
void manage_transactions() {
    TransactionPool *pool = init_transaction_pool(10, 0.75);

    if (!pool) {
        printf("Failed to initialize transaction pool\n");
        return;
    }

    Point p1 = { .x = 1.23, .y = 4.56 };
    double value = 789.01;
    bool status = rand() % 2;

    if (add_transaction(pool, p1, value, status) != 0) {
        printf("Failed to add transaction\n");
    }

    if (serialize_transactions(pool, "transactions.bin") != 0) {
        printf("Serialization failed\n");
    }

    TransactionPool *loaded_pool = deserialize_transactions("transactions.bin");

    if (!loaded_pool) {
        printf("Deserialization failed\n");
    } else {
        // Use loaded transactions
        free_transaction_pool(loaded_pool);
    }

    free_transaction_pool(pool);
}

int main() {
    srand(time(NULL));
    manage_transactions();
    return 0;
}
```

This C code demonstrates the creation and management of a memory pool for `Transaction` objects, along with serialization/deserialization capabilities. It includes thread-safe access using mutex locks and logs memory usage during operations. The resizing mechanism ensures efficient use of space by expanding the transaction pool when necessary.']

