function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp, $pdo) {
    // Configuration constants
    const MAX_RETRIES = 3;
    const LOG_LEVEL_UPDATE = 'INFO';
    const FALLBACK_CLINIC_ID = 1; // Example fallback clinic ID

    // Logger and cache instances (assumed to be initialized elsewhere)
    global $logger;
    global $cache;

    $attempts = 0;
    $success = false;

    while ($attempts < MAX_RETRIES && !$success) {
        try {
            $pdo->beginTransaction();

            // Check if clinic ID exists
            $stmt = $pdo->prepare('SELECT id FROM clinics WHERE id = :clinicId');
            $stmt->execute([':clinicId' => $clinicId]);
            $clinic = $stmt->fetch(PDO::FETCH_ASSOC);

            if ($clinic) {
                $updateClinicId = $clinic['id'];
            } elseif (($fallbackStmt = $pdo->prepare('SELECT id FROM clinics WHERE id = :fallbackClinicId'))->execute([':fallbackClinicId' => FALLBACK_CLINIC_ID]) && $fallbackStmt->fetch(PDO::FETCH_ASSOC)) {
                // Use fallback clinic
                $updateClinicId = FALLBACK_CLINIC_ID;
            } else {
                throw new Exception('No valid clinic ID found.');
            }

            // Update operation with locking to handle concurrency
            $stmt = $pdo->prepare('UPDATE clinics SET status = :status, last_modified_ip = :lastModifiedIp, last_modified_date = NOW() WHERE id = :clinicId FOR UPDATE');
            $stmt->execute([
                ':status' => $newStatus,
                ':lastModifiedIp' => $lastModifiedIp,
                ':clinicId' => $updateClinicId
            ]);

            $pdo->commit();

            // Log the update for auditing purposes
            $logger->log(LOG_LEVEL_UPDATE, "Updated clinic ID: $updateClinicId with status: $newStatus from IP: $lastModifiedIp");

            $success = true;
        } catch (Exception $e) {
            $pdo->rollBack();

            if ($attempts < MAX_RETRIES - 1) {
                // Retry logic
                usleep(500000); // Wait for half a second before retrying
            } else {
                // Handle database connection failures by attempting secondary DB, assume this is defined elsewhere
                global $secondaryPdo;
                try {
                    $pdo = $secondaryPdo;
                    continue; // Attempt operation with the secondary database
                } catch (Exception $dbFail) {
                    return "Failed to update clinic: " . $e->getMessage();
                }
            }

            $attempts++;
        }
    }

    if ($success) {
        return "Clinic updated successfully.";
    }

    return "Failed to update clinic after {$MAX_RETRIES} attempts.";
}

