['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

// Define structure for records
typedef struct {
    int value;
} record;

// Memory pool control block
typedef struct MemoryPool {
    size_t blockSize;
    void* freeListHead;
    pthread_mutex_t mutex;
} MemoryPool;

#define POOL_INIT(pool, blockSize) \
    do { \
        (pool)->blockSize = (blockSize); \
        (pool)->freeListHead = NULL; \
        pthread_mutex_init(&(pool)->mutex, NULL); \
    } while(0)

// Function to initialize memory pool
void* allocateFromPool(MemoryPool* pool, size_t size) {
    if (size > pool->blockSize)
        return NULL;

    void *ptr;
    pthread_mutex_lock(&pool->mutex);

    if (!pool->freeListHead) {
        ptr = malloc(size + sizeof(void*));
        if (!ptr) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }

        *(void**)(ptr) = pool->freeListHead; // Link to the previous block
    } else {
        ptr = pool->freeListHead;
        pool->freeListHead = *(void**)ptr;
    }

    pthread_mutex_unlock(&pool->mutex);
    return (char*)ptr + sizeof(void*);
}

// Function to free memory back to pool
void deallocateToPool(MemoryPool* pool, void *ptr) {
    if (!ptr)
        return;

    pthread_mutex_lock(&pool->mutex);

    *(void**)ptr = pool->freeListHead;
    pool->freeListHead = ptr;

    pthread_mutex_unlock(&pool->mutex);
}

// Function to dynamically allocate memory for arrays and records
void initializeArraysAndRecords(size_t numOffsets, size_t numKeys, int minValue, int maxValue) {
    MemoryPool offsetPool, keyPool, recordPool;

    // Initialize pools with appropriate block sizes
    POOL_INIT(&offsetPool, sizeof(long));
    POOL_INIT(&keyPool, sizeof(int));
    POOL_INIT(&recordPool, sizeof(record));

    long *offsets = (long*)allocateFromPool(&offsetPool, numOffsets * sizeof(long));
    if (!offsets) return;

    int *keys = (int*)allocateFromPool(&keyPool, numKeys * sizeof(int));
    if (!keys) {
        deallocateToPool(&offsetPool, offsets);
        return;
    }

    record *records = (record*)allocateFromPool(&recordPool, numOffsets * sizeof(record));
    if (!records) {
        deallocateToPool(&offsetPool, offsets);
        deallocateToPool(&keyPool, keys);
        return;
    }

    srand(time(NULL)); // Seed for random number generation

    // Initialize data
    for (size_t i = 0; i < numOffsets; ++i) {
        offsets[i] = (long)i;  // Example initialization logic
        records[i].value = minValue + rand() % (maxValue - minValue + 1);

        printf("Offset: %ld, Record Value: %d\n", offsets[i], records[i].value); // Logging
    }

    for (size_t i = 0; i < numKeys; ++i) {
        keys[i] = (int)i;  // Example initialization logic

        printf("Key: %d\n", keys[i]); // Logging
    }

    // Clean up resources on function exit
    deallocateToPool(&offsetPool, offsets);
    deallocateToPool(&keyPool, keys);
    deallocateToPool(&recordPool, records);
}

int main() {
    initializeArraysAndRecords(10, 5, 1, 100);

    return 0;
}
```

### Explanation of the Code Structure:
- **Memory Pool**: A custom memory pool is used to manage allocations with reduced fragmentation and improved performance. The pool uses a mutex for thread safety.

- **Allocation & Deallocation Functions**: These functions manage memory allocation from the pool, ensuring efficiency by reusing freed blocks.

- **Dynamic Initialization**: Arrays for offsets and keys are dynamically allocated using the custom memory pools, along with an array of `record` structures.

- **Random Value Assignment**: Each record's integer field is initialized to a random value within a specified range.

- **Thread Safety**: Mutexes in the memory pool ensure thread-safe operations.

- **Logging**: Print statements log the allocation and initialization processes for debugging purposes. 

- **Graceful Failure Handling**: The code checks for allocation failures and cleans up previously allocated resources if needed, ensuring robust error handling.

This implementation provides a balance between efficient memory usage and concurrency support, while logging and error-handling mechanisms help in tracking performance and diagnosing issues.']

