use mime_guess::from_path;
use thiserror::Error;
use flate2::read::GzDecoder;
use rayon::prelude::*;
use std::sync::Mutex;

#[derive(Error, Debug)]
pub enum ReportError {
    #[error("Failed to read file: {0}")]
    FileReadError(#[from] std::io::Error),
    #[error("Decompression error")]
    DecompressionError,
    #[error("Unsupported MIME type for file format")]
    UnsupportedFileType,
}

enum LogVerbosity {
    None,
    Basic,
    Detailed,
}

struct Logger {
    verbosity: LogVerbosity,
}

impl Logger {
    fn log(&self, message: &str) {
        match self.verbosity {
            LogVerbosity::None => {},
            LogVerbosity::Basic | LogVerbosity::Detailed => println!("{}", message),
        }
    }

    fn start_timer(&self) -> Instant {
        Instant::now()
    }

    fn end_timer<T>(&self, timer: Instant, task: T)
    where
        T: std::fmt::Display,
    {
        let duration = timer.elapsed();
        self.log(&format!("{} took {:?}", task, duration));
    }
}

struct Cache {
    data: Mutex<Vec<u8>>,
}

impl Cache {
    fn new() -> Self {
        Cache { data: Mutex::new(Vec::new()) }
    }

    fn get_or_load<F>(&self, path: &str, loader: F) -> Result<&[u8], ReportError>
    where
        F: FnOnce(&str) -> Result<Vec<u8>, std::io::Error>,
    {
        let mut data = self.data.lock().unwrap();

        if let Some(cached_data) = data.get(path.as_bytes()) {
            Ok(cached_data)
        } else {
            match loader(path)? {
                loaded_data => {
                    *data = loaded_data;
                    Ok(&data[..])
                }
                _ => Err(ReportError::FileReadError(std::io::Error::new(
                    std::io::ErrorKind::Other,
                    "Failed to load data",
                ))),
            }
        }
    }

    fn insert(&self, path: &str, data: Vec<u8>) {
        let mut data = self.data.lock().unwrap();
        *data = data
            .drain(..)
            .chain(data_from_slice(path.as_bytes()))
            .chain(std::iter::once(data))
            .collect();
    }
}

fn data_from_slice(slice: &[u8]) -> Vec<Vec<u8>> {
    vec![slice.to_vec()]
}

pub fn generate_report(
    path: &str,
    file_type: Option<&str>,
    cache_size: usize,
    verbosity: LogVerbosity,
) -> Result<(), ReportError> {
    let logger = Logger { verbosity };

    let start = logger.start_timer();

    let cache = Cache::new();

    let data = cache.get_or_load(path, |path| fs::read(path)).map_err(|e| {
        eprintln!("Error reading file: {}", e);
        e
    })?;

    if let Ok(mime_type) = from_path(path).first() {
        match mime_type.as_ref() {
            "application/gzip" => {
                let mut gz_decoder = GzDecoder::new(&data[..]);
                let decompressed_data = std::io::Read::read_to_end(&mut gz_decoder)?;

                cache.insert(path, decompressed_data.clone());

                // Handle the decompressed data in a parallel fashion if applicable
                decompressed_data.par_iter().for_each(|byte| {
                    // Process each byte (placeholder for actual processing)
                });
            }
            _ => {
                if let Some(ft) = file_type {
                    logger.log(&format!("Processing {} as {}", path, ft));
                } else if mime_type == "text/plain" || mime_type.starts_with("image/") {
                    logger.log(&format!("Detected MIME type: {}", mime_type));
                } else {
                    return Err(ReportError::UnsupportedFileType);
                }
            }
        }
    }

    let end = Instant::now();
    logger.end_timer(start, "Total Processing Time");

    Ok(())
}

fn main() -> Result<(), ReportError> {
    generate_report("example.txt", None, 1024 * 1024, LogVerbosity::Detailed)
}
