['Below is an implementation of a C function that dynamically manages memory for a collection of record structures within a custom memory pool. It includes features like handling multiple threads, logging access frequency, and efficient memory management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_RECORDS 10000
#define MEMORY_POOL_SIZE (MAX_RECORDS * sizeof(struct Record))
#define MAX_THREADS 10

typedef struct {
    int prime_value;
    unsigned int access_count;
    pthread_mutex_t lock;
} Record;

typedef struct {
    char *pool;
    size_t pool_size;
    size_t used;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool mem_pool = {NULL, MEMORY_POOL_SIZE, 0, PTHREAD_MUTEX_INITIALIZER};

bool is_prime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; ++i)
        if (n % i == 0) return false;
    return true;
}

void initialize_memory_pool() {
    mem_pool.pool = malloc(mem_pool.pool_size);
    if (!mem_pool.pool) {
        fprintf(stderr, "Failed to allocate memory pool.\n");
        exit(EXIT_FAILURE);
    }
    mem_pool.used = 0;
}

Record* allocate_record(int prime_value) {
    pthread_mutex_lock(&mem_pool.mutex);

    if (is_prime(prime_value)) {
        if (mem_pool.used + sizeof(Record) > mem_pool.pool_size) {
            fprintf(stderr, "Memory pool exhausted.\n");
            pthread_mutex_unlock(&mem_pool.mutex);
            return NULL;
        }

        Record *record = (Record*)(mem_pool.pool + mem_pool.used);
        record->prime_value = prime_value;
        record->access_count = 0;
        pthread_mutex_init(&record->lock, NULL);

        mem_pool.used += sizeof(Record);
        pthread_mutex_unlock(&mem_pool.mutex);
        return record;
    }

    pthread_mutex_unlock(&mem_pool.mutex);
    return NULL;
}

void deallocate_record(Record *record) {
    if (!record) return;

    pthread_mutex_lock(&record->lock);
    // Assuming some cleanup logic here if needed
    pthread_mutex_unlock(&record->lock);

    pthread_mutex_lock(&mem_pool.mutex);

    mem_pool.used -= sizeof(Record);

    pthread_mutex_unlock(&mem_pool.mutex);
}

void access_record(Record *record) {
    if (record && pthread_mutex_trylock(&record->lock) == 0) {
        record->access_count++;
        printf("Accessed Record: %d, Count: %u\n", record->prime_value, record->access_count);
        pthread_mutex_unlock(&record->lock);
    }
}

void cleanup_memory_pool() {
    free(mem_pool.pool);
    mem_pool.pool = NULL;
    mem_pool.used = 0;
}

int main() {
    initialize_memory_pool();

    // Example usage
    Record *r1 = allocate_record(11); // Should succeed
    access_record(r1);

    Record *r2 = allocate_record(4); // Should fail (not prime)
    if (!r2) printf("Failed to allocate non-prime record.\n");

    deallocate_record(r1);

    cleanup_memory_pool();
    return 0;
}
```

### Key Points:
- **Prime Checking**: A simple primality test is included for efficiency, designed to handle reasonable numbers.
- **Memory Pool Management**: Uses a contiguous memory block and maintains the size of used space. It's locked during allocation/deallocation to ensure thread safety.
- **Thread Safety**: Utilizes `pthread_mutex_t` for synchronization across threads accessing shared resources.
- **Access Logging**: Records access frequency, with mutex locks ensuring safe updates in multithreaded contexts.
- **Error Handling**: Returns specific error messages when allocations fail due to exhaustion or invalid input.

This implementation is a basic version and may require further enhancement for production use, particularly in scaling memory pool management under high concurrency.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

#define MAX_THREADS 10
#define POOL_SIZE 1024

typedef struct {
    float temperature;
    time_t timestamp;
} Event;

typedef struct Node {
    void *data;
    size_t size;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
    int access_count[MAX_THREADS];
    bool available[POOL_SIZE];
    int current_size;
    size_t allocated_memory;
} MemoryPool;

MemoryPool pool;

void init_pool() {
    pool.head = NULL;
    pthread_mutex_init(&pool.lock, NULL);
    memset(pool.available, 0, sizeof(pool.available));
    memset(pool.access_count, 0, sizeof(pool.access_count));
    pool.current_size = POOL_SIZE;
    pool.allocated_memory = 0;
}

void *allocate(size_t size) {
    pthread_mutex_lock(&pool.lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (!pool.available[i]) continue;

        Node *node = malloc(sizeof(Node));
        node->data = malloc(size);
        node->size = size;
        node->next = pool.head;
        pool.head = node;

        pool.available[i] = false;
        pool.allocated_memory += sizeof(Node) + size;
        pthread_mutex_unlock(&pool.lock);

        return node->data;
    }

    pthread_mutex_unlock(&pool.lock);
    fprintf(stderr, "Memory exhaustion: unable to allocate memory.\n");
    return NULL; // Indicate failure
}

void free_pool() {
    Node *current = pool.head;
    while (current) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pool.lock);
}

Event* create_event(float temperature, time_t timestamp) {
    Event *event = allocate(sizeof(Event));
    if (!event) return NULL;

    event->temperature = temperature;
    event->timestamp = timestamp;

    return event;
}

void log_access(int thread_id) {
    pool.access_count[thread_id]++;
}

bool is_temperature_unique(float temperature) {
    pthread_mutex_lock(&pool.lock);

    Node *current = pool.head;
    while (current) {
        Event *event = (Event *)current->data;
        if (fabs(event->temperature - temperature) < 0.0001f) {
            pthread_mutex_unlock(&pool.lock);
            return false;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool.lock);
    return true;
}

void update_event(Event *event, float new_temperature) {
    if (!is_temperature_unique(new_temperature)) {
        fprintf(stderr, "Temperature not unique: %f\n", new_temperature);
        return;
    }

    event->temperature = new_temperature;
    time(&event->timestamp);
}

void* thread_function(void *arg) {
    int thread_id = *(int *)arg;

    float temperature = (float)(rand() % 100);
    if (!is_temperature_unique(temperature)) {
        fprintf(stderr, "Thread %d: Temperature not unique.\n", thread_id);
        return NULL;
    }

    time_t timestamp = time(NULL);
    Event *event = create_event(temperature, timestamp);

    log_access(thread_id);

    if (event) {
        update_event(event, temperature + 1.0f);
    }

    return NULL;
}

int main() {
    init_pool();

    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Thread access counts:\n");
    for (int i = 0; i < MAX_THREADS; ++i) {
        printf("Thread %d: %d accesses\n", i, pool.access_count[i]);
    }

    free_pool();

    return EXIT_SUCCESS;
}
