        if (pool.count >= pool.capacity) {
            pool.capacity *= 2;
            pool.transactions = realloc(pool.transactions, pool.capacity * sizeof(Transaction));
        }
        pool.transactions[pool.count++] = (Transaction){.weight = rand() % 100 / 10.0, .id = i};
    }

    // Filter transactions
    double max_weight_sum = 0.0;
    int transaction_id = -1;
    filterTransactions(&pool, 30 * 24 * 60 * 60, 5, 50.0, &max_weight_sum, &transaction_id);

    printf("Max weighted sum: %f for transaction ID: %d\n", max_weight_sum, transaction_id);
}

