}

int filterTransactions(TransactionPool *pool, time_t age_limit, int transaction_window, double weight_sum_limit, double *max_weight_sum, int *transaction_id) {
    pthread_mutex_lock(&pool->lock);

    double current_weight_sum = 0;
    int recent_count = 0;

    for (size_t i = 0; i < pool->count; ++i) {
        // Mock age check
        if ((time(NULL) - (i * 86400)) > age_limit) continue; // Assuming transaction time is i*24h

        current_weight_sum += pool->transactions[i].weight;
        recent_count++;

        if (recent_count > transaction_window) break;

        if (current_weight_sum > *max_weight_sum) {
            *max_weight_sum = current_weight_sum;
