#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_BUFFER_SIZE 1024

typedef struct {
    char *buffer;
    unsigned long length;
} BufferStruct;

typedef struct {
    pthread_mutex_t lock;
    BufferStruct *array;
    size_t count;
    size_t capacity;
    size_t buffer_size;
} DynamicBufferArray;

void log_error(const char *message) {
    // Example logging function
    fprintf(stderr, "Error: %s\n", message);
}

DynamicBufferArray* create_dynamic_buffer_array(size_t initial_count, size_t buffer_size) {
    DynamicBufferArray *db_array = (DynamicBufferArray *)malloc(sizeof(DynamicBufferArray));
    if (!db_array) {
        log_error("Failed to allocate memory for DynamicBufferArray");
        return NULL;
    }

    pthread_mutex_init(&db_array->lock, NULL);
    db_array->count = 0;
    db_array->capacity = initial_count;
    db_array->buffer_size = buffer_size;

    db_array->array = (BufferStruct *)malloc(initial_count * sizeof(BufferStruct));
    if (!db_array->array) {
        log_error("Failed to allocate memory for BufferStruct array");
        free(db_array);
        return NULL;
    }

    for (size_t i = 0; i < initial_count; ++i) {
        db_array->array[i].buffer = (char *)malloc(buffer_size);
        if (!db_array->array[i].buffer) {
            log_error("Failed to allocate memory for char buffer");
            // Clean up previously allocated buffers
            while (i > 0) {
                free(db_array->array[--i].buffer);
            }
            free(db_array->array);
            pthread_mutex_destroy(&db_array->lock);
            free(db_array);
            return NULL;
        }
        db_array->array[i].length = buffer_size;

        // Populate with random data
        for (size_t j = 0; j < buffer_size; ++j) {
            db_array->array[i].buffer[j] = rand() % 256;
        }

        db_array->count++;
    }

    return db_array;
}

int resize_dynamic_buffer_array(DynamicBufferArray *db_array, size_t new_count) {
    pthread_mutex_lock(&db_array->lock);

    BufferStruct *new_array = (BufferStruct *)realloc(db_array->array, new_count * sizeof(BufferStruct));
    if (!new_array && new_count > db_array->capacity) {
        log_error("Failed to reallocate memory for resized BufferStruct array");
        pthread_mutex_unlock(&db_array->lock);
        return -1;
    }

    db_array->array = new_array;
    db_array->capacity = new_count;

    for (size_t i = db_array->count; i < new_count; ++i) {
        db_array->array[i].buffer = (char *)malloc(db_array->buffer_size);
        if (!db_array->array[i].buffer) {
            log_error("Failed to allocate memory for char buffer during resize");
            // Clean up newly allocated buffers
            while (i > db_array->count) {
                free(db_array->array[--i].buffer);
            }
            pthread_mutex_unlock(&db_array->lock);
            return -1;
        }

        for (size_t j = 0; j < db_array->buffer_size; ++j) {
            db_array->array[i].buffer[j] = rand() % 256;
        }

        db_array->count++;
    }

    pthread_mutex_unlock(&db_array->lock);
    return 0;
}

void serialize_buffer_array(DynamicBufferArray *db_array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&db_array->lock);

    fwrite(&db_array->count, sizeof(size_t), 1, file);
    fwrite(&db_array->buffer_size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < db_array->count; ++i) {
        fwrite(&db_array->array[i].length, sizeof(unsigned long), 1, file);
        fwrite(db_array->array[i].buffer, sizeof(char), db_array->array[i].length, file);
    }

    pthread_mutex_unlock(&db_array->lock);

    fclose(file);
}

void memory_monitor(void *arg) {
    size_t threshold = *(size_t *)arg;

    while (1) {
        // Simulate available memory check
        size_t available_memory = 1024 * 1024 * 512; // Example value

        if (available_memory < threshold) {
            log_error("Low memory warning");
        }

        sleep(10); // Check every 10 seconds
    }
}

void start_memory_monitor(size_t threshold) {
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, memory_monitor, &threshold);
}

void garbage_collect(DynamicBufferArray *db_array) {
    pthread_mutex_lock(&db_array->lock);

    for (size_t i = 0; i < db_array->count; ++i) {
        if (!db_array->array[i].buffer) continue;

        // Simulate condition to free memory
        if (rand() % 2 == 0) { 
            free(db_array->array[i].buffer);
            db_array->array[i].buffer = NULL;
            db_array->count--;
        }
    }

    pthread_mutex_unlock(&db_array->lock);
}

void cleanup_dynamic_buffer_array(DynamicBufferArray *db_array) {
    pthread_mutex_lock(&db_array->lock);

    for (size_t i = 0; i < db_array->count; ++i) {
        free(db_array->array[i].buffer);
    }

    free(db_array->array);

    pthread_mutex_unlock(&db_array->lock);
    pthread_mutex_destroy(&db_array->lock);
    free(db_array);
}

int main() {
    srand(time(NULL));

    size_t initial_count = 10;
    size_t buffer_size = 256;

    DynamicBufferArray *buffer_array = create_dynamic_buffer_array(initial_count, buffer_size);

    if (!buffer_array) return EXIT_FAILURE;

    resize_dynamic_buffer_array(buffer_array, initial_count + 5);
    serialize_buffer_array(buffer_array, "buffer_data.bin");

    start_memory_monitor(1024 * 1024 * 256); // Example threshold

    garbage_collect(buffer_array);

    cleanup_dynamic_buffer_array(buffer_array);

    return EXIT_SUCCESS;
}
