    void* start;     // Start address of the memory pool
    size_t size;     // Total size of the memory pool
    pthread_mutex_t lock;  // Mutex to ensure thread-safe access
    // Additional metadata fields for managing free blocks can be added here
} MemoryPool;

MemoryPool memPool;

// Initialize memory pool (should be called before using allocateAndInitializeRecords)
void initializeMemoryPool(void* start, size_t size) {
    memPool.start = start;
    memPool.size = size;
    pthread_mutex_init(&memPool.lock, NULL);
}

record* allocateAndInitializeRecords(int numRecords, long* offsets, int* keys, int minKey, int maxKey, int minValue, int maxValue) {
    if (numRecords <= 0 || !offsets || !keys) return NULL;

    // Calculate total size needed for records
    size_t recordSize = sizeof(record);
    size_t alignedRecordSize = (recordSize + (alignof(long) - 1)) & ~(alignof(long) - 1);

    // Ensure sufficient memory is available in the pool
    pthread_mutex_lock(&memPool.lock);
    if ((size_t)(numRecords * alignedRecordSize) > memPool.size) {
        pthread_mutex_unlock(&memPool.lock);
        return NULL;
    }

    // Allocate memory from the pool
    record* records = (record*)memPool.start;  // Simplified allocation for illustration

    // Move start pointer forward in the pool to simulate allocation
    memPool.start = (char*)memPool.start + numRecords * alignedRecordSize;

    pthread_mutex_unlock(&memPool.lock);

    for (int i = 0; i < numRecords; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        // Initialize value to a valid state
        if (keys[i] < minKey || keys[i] > maxKey) {
            // Cleanup and return NULL on validation failure
            pthread_mutex_lock(&memPool.lock);
            memPool.start = (char*)records - numRecords * alignedRecordSize;
            pthread_mutex_unlock(&memPool.lock);
            free(records);  // Assuming the records were allocated using malloc for simplification
            return NULL;
        }
        records[i].value = minValue;  // Set to a valid initial value
    }

    return records;
}
