#define INITIAL_CAPACITY 10

typedef struct {
    char identifier[256];
    double value;
    time_t timestamp;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int logging_enabled;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    collection->records = malloc(initial_capacity * sizeof(Record));
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    collection->logging_enabled = 1; // Default to logging enabled
    return collection;
}

void resize_collection(RecordCollection *collection) {
    size_t new_capacity = collection->capacity * 2;
    Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (new_records) {
        collection->records = new_records;
        collection->capacity = new_capacity;
    } else {
        perror("Failed to resize collection");
        exit(EXIT_FAILURE);
    }
}

void log_change(const char *message) {
    if (logging_enabled) {
        printf("%s\n", message);
    }
}

void add_record(RecordCollection *collection, const char *identifier, double value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        resize_collection(collection);
    }

    Record new_record;
    strncpy(new_record.identifier, identifier, sizeof(new_record.identifier));
    new_record.value = value;
    new_record.timestamp = time(NULL);

    collection->records[collection->count++] = new_record;

    char log_message[512];
    snprintf(log_message, sizeof(log_message), "Added record %s with value %.2f", identifier, value);
    log_change(log_message);

    pthread_mutex_unlock(&collection->lock);
}

void remove_record(RecordCollection *collection, const char *identifier) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->records[i].identifier, identifier) == 0) {
            memmove(&collection->records[i], &collection->records[i + 1],
                    (collection->count - i - 1) * sizeof(Record));
            collection->count--;

            char log_message[512];
            snprintf(log_message, sizeof(log_message), "Removed record %s", identifier);
            log_change(log_message);

            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void update_record(RecordCollection *collection, const char *identifier, double new_value) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->records[i].identifier, identifier) == 0) {
            collection->records[i].value = new_value;
            collection->records[i].timestamp = time(NULL);

            char log_message[512];
            snprintf(log_message, sizeof(log_message), "Updated record %s to value %.2f", identifier, new_value);
            log_change(log_message);

            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void set_logging(RecordCollection *collection, int enabled) {
    pthread_mutex_lock(&collection->lock);
    collection->logging_enabled = enabled;
    pthread_mutex_unlock(&collection->lock);
}

void free_collection(RecordCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
    free(collection);
}
