#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define INITIAL_POOL_SIZE 1024
#define RESIZE_THRESHOLD_PERCENTAGE 75

typedef struct {
    int value;
} record_t;

typedef struct {
    int value;
} event_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t **records;
    event_t **events;
    size_t records_size;
    size_t events_size;
    pthread_mutex_t lock;
    void (*logger)(const char *);
} memory_pool_t;

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%ld] %s\n", now, message);
}

memory_pool_t* create_memory_pool(memory_pool_t config) {
    memory_pool_t *pool = malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pthread_mutex_init(&pool->lock, NULL);

    pool->offsets = malloc(INITIAL_POOL_SIZE * sizeof(long));
    pool->keys = malloc(INITIAL_POOL_SIZE * sizeof(int));
    pool->records = malloc(INITIAL_POOL_SIZE * sizeof(record_t*));
    pool->events = malloc(INITIAL_POOL_SIZE * sizeof(event_t*));

    if (!pool->offsets || !pool->keys || !pool->records || !pool->events) {
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool->events);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
        return NULL;
    }

    pool->records_size = INITIAL_POOL_SIZE;
    pool->events_size = INITIAL_POOL_SIZE;
    pool->logger = config.logger;

    for (size_t i = 0; i < INITIAL_POOL_SIZE; ++i) {
        pool->records[i] = malloc(sizeof(record_t));
        pool->events[i] = malloc(sizeof(event_t));

        if (!pool->records[i] || !pool->events[i]) {
            // Handle allocation failure
            for (size_t j = 0; j <= i; ++j) {
                free(pool->records[j]);
                free(pool->events[j]);
            }
            free(pool->offsets);
            free(pool->keys);
            free(pool->records);
            free(pool->events);
            pthread_mutex_destroy(&pool->lock);
            free(pool);
            return NULL;
        }

        pool->records[i]->value = rand() % 100;
        pool->events[i]->value = rand() % 100;
    }

    return pool;
}

void resize_memory_pool(memory_pool_t *pool, size_t new_size) {
    if (new_size <= pool->records_size && new_size <= pool->events_size)
        return;

    record_t **new_records = realloc(pool->records, new_size * sizeof(record_t*));
    event_t **new_events = realloc(pool->events, new_size * sizeof(event_t*));

    if (!new_records || !new_events) {
        // Handle allocation failure
        free(new_records);
        free(new_events);
        return;
    }

    for (size_t i = pool->records_size; i < new_size; ++i) {
        new_records[i] = malloc(sizeof(record_t));
        new_events[i] = malloc(sizeof(event_t));

        if (!new_records[i] || !new_events[i]) {
            // Handle allocation failure
            for (size_t j = pool->records_size; j <= i; ++j) {
                free(new_records[j]);
                free(new_events[j]);
            }
            break;
        }

        new_records[i]->value = rand() % 100;
        new_events[i]->value = rand() % 100;
    }

    pool->records = new_records;
    pool->events = new_events;
    pool->records_size = new_size;
    pool->events_size = new_size;

    if (pool->logger) {
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Resized memory pool to %zu", new_size);
        pool->logger(log_buffer);
    }
}

void serialize_memory_pool(memory_pool_t *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    size_t records_count = 0;
    for (size_t i = 0; i < pool->records_size && pool->records[i]; ++i)
        records_count++;

    fwrite(&records_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < records_count; ++i) {
        fwrite(pool->records[i], sizeof(record_t), 1, file);
    }

    size_t events_count = 0;
    for (size_t i = 0; i < pool->events_size && pool->events[i]; ++i)
        events_count++;

    fwrite(&events_count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < events_count; ++i) {
        fwrite(pool->events[i], sizeof(event_t), 1, file);
    }

    fclose(file);
}

void deserialize_memory_pool(memory_pool_t *pool, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t records_count;
    fread(&records_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < records_count; ++i) {
        record_t *rec = malloc(sizeof(record_t));
        fread(rec, sizeof(record_t), 1, file);
        pool->records[i] = rec;
    }

    size_t events_count;
    fread(&events_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < events_count; ++i) {
        event_t *evt = malloc(sizeof(event_t));
        fread(evt, sizeof(event_t), 1, file);
        pool->events[i] = evt;
    }

    fclose(file);
}

void free_memory_pool(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->records_size; ++i)
        if (pool->records[i])
            free(pool->records[i]);

    for (size_t i = 0; i < pool->events_size; ++i)
        if (pool->events[i])
            free(pool->events[i]);

    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool->events);

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int main() {
    memory_pool_t config = { .logger = log_message };
    srand(time(NULL));

    memory_pool_t *pool = create_memory_pool(config);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return EXIT_FAILURE;
    }

    serialize_memory_pool(pool, "memory_state.dat");

    deserialize_memory_pool(pool, "memory_state.dat");

    free_memory_pool(pool);

    return EXIT_SUCCESS;
}
