#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

#define INITIAL_POOL_SIZE 1024
#define THRESHOLD_INCREMENT 512

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct MemoryPool {
    size_t block_size;
    size_t current_size;
    size_t threshold;
    char *pool;
    void **free_list;
    size_t free_count;
} MemoryPool;

void initialize_pool(MemoryPool *mp, size_t block_size) {
    mp->block_size = block_size;
    mp->current_size = INITIAL_POOL_SIZE * block_size;
    mp->threshold = INITIAL_POOL_SIZE * block_size;
    mp->pool = malloc(mp->current_size);
    mp->free_list = malloc(INITIAL_POOL_SIZE * sizeof(void *));

    for (size_t i = 0; i < INITIAL_POOL_SIZE - 1; ++i) {
        mp->free_list[i] = (char *)mp->pool + i * block_size;
        *(void **)(mp->free_list[i]) = mp->free_list[i + 1];
    }
    mp->free_list[INITIAL_POOL_SIZE - 1] = NULL;
    mp->free_count = INITIAL_POOL_SIZE;
}

void resize_pool(MemoryPool *mp) {
    size_t new_size = mp->current_size + THRESHOLD_INCREMENT * mp->block_size;
    char *new_pool = realloc(mp->pool, new_size);

    if (new_pool == NULL) {
        perror("Failed to resize memory pool");
        exit(EXIT_FAILURE);
    }

    void **new_free_list = realloc(mp->free_list, ((mp->current_size / mp->block_size) + THRESHOLD_INCREMENT) * sizeof(void *));
    if (new_free_list == NULL) {
        free(new_pool);
        perror("Failed to resize free list");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < THRESHOLD_INCREMENT - 1; ++i) {
        new_free_list[mp->current_size / mp->block_size + i] = new_pool + (mp->current_size + i * mp->block_size);
        *(void **)(new_free_list[mp->current_size / mp->block_size + i]) = new_free_list[mp->current_size / mp->block_size + i + 1];
    }

    new_free_list[(mp->current_size + THRESHOLD_INCREMENT - 1) / mp->block_size] = NULL;

    mp->pool = new_pool;
    mp->free_list = new_free_list;
    mp->current_size = new_size;
    mp->threshold += THRESHOLD_INCREMENT * mp->block_size;
    mp->free_count += THRESHOLD_INCREMENT;
}

void* allocate_block(MemoryPool *mp) {
    pthread_mutex_lock(&lock);

    if (mp->free_count == 0) {
        resize_pool(mp);
    }

    void *block = mp->free_list[mp->free_count - 1];
    mp->free_list[mp->free_count - 1] = *(void **)block;
    --mp->free_count;

    pthread_mutex_unlock(&lock);

    return block;
}

void deallocate_block(MemoryPool *mp, void *block) {
    pthread_mutex_lock(&lock);

    *(void **)block = mp->free_list[mp->free_count];
    mp->free_list[mp->free_count] = block;
    ++mp->free_count;

    pthread_mutex_unlock(&lock);
}

void log_memory_usage(const char* message, size_t usage) {
    printf("%s: %zu bytes\n", message, usage);
}

void cleanup_pool(MemoryPool *mp) {
    free(mp->pool);
    free(mp->free_list);
}

int allocate_records(int max_records, long range_min, long range_max) {
    MemoryPool pool;
    initialize_pool(&pool, sizeof(record));

    log_memory_usage("Initial memory allocation", pool.current_size);

    record *records = (record *)malloc(max_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate records");
        cleanup_pool(&pool);
        return EXIT_FAILURE;
    }

    srand(time(NULL)); // Seed for random number generation

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    void (*thread_function)(void *) = [](void *arg){
        long range_min = *(long*)(((char*)arg) + sizeof(max_records));
        long range_max = *(long*)(((char*)arg) + sizeof(max_records) + sizeof(long));

        for (int i = 0; i < max_records; ++i) {
            pthread_mutex_lock(&mutex);
            records[i].value = rand() % (range_max - range_min + 1) + range_min;
            void *block = allocate_block(&pool);
            deallocate_block(&pool, block);
            pthread_mutex_unlock(&mutex);
        }
    };

    pthread_t threads[2];
    long args[] = {max_records, range_min, range_max};

    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, thread_function, &args[i * sizeof(long)]);
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_memory_usage("Final memory usage", pool.current_size - pool.free_count * sizeof(record));

    free(records);
    cleanup_pool(&pool);

    return EXIT_SUCCESS;
}

int main() {
    int max_records = 1000;
    long range_min = 1, range_max = 100;

    if (allocate_records(max_records, range_min, range_max) == EXIT_FAILURE) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    printf("Records allocated successfully.\n");

    return EXIT_SUCCESS;
}
```

### Explanation:
- **Memory Pool Management:** A custom memory pool is initialized and dynamically resized as needed.
- **Thread Safety:** POSIX mutexes are used to ensure thread-safe operations on shared data structures.
- **Logging Mechanism:** Simple logging is implemented to track memory usage at key points.
- **Resource Cleanup:** Proper deallocation of resources is ensured to prevent leaks.

This code provides a starting point for managing dynamic arrays and records efficiently in a concurrent environment. Adjustments may be needed based on specific system constraints and additional requirements.']

