typedef struct MemoryPool {
    void *memory;
    size_t item_size;
    size_t pool_size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

static MemoryPool record_pool, item_pool;

void init_memory_pool(MemoryPool *pool, size_t item_size) {
    pool->item_size = item_size;
    pool->memory = malloc(INITIAL_POOL_SIZE * item_size);
    pool->pool_size = INITIAL_POOL_SIZE;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void expand_memory_pool(MemoryPool *pool) {
    size_t new_pool_size = pool->pool_size * 2;
    void *new_memory = realloc(pool->memory, new_pool_size * pool->item_size);
    if (new_memory) {
        pool->memory = new_memory;
        pool->pool_size = new_pool_size;
    } else {
        fprintf(stderr, "Failed to expand memory pool\n");
        exit(EXIT_FAILURE);
    }
}

Record* allocate_record() {
    pthread_mutex_lock(&record_pool.lock);

    if ((double)record_pool.used / record_pool.pool_size > EXPAND_THRESHOLD) {
        expand_memory_pool(&record_pool);
    }

    void *space = (char*)record_pool.memory + record_pool.used * sizeof(Record);
    record_pool.used++;

    Record *rec = (Record *)space;
    rec->key = rand() % 100; // Example range
    rec->value = rand() % 100; // Example range
    pthread_mutex_unlock(&record_pool.lock);

    return rec;
}

Item* allocate_item() {
    pthread_mutex_lock(&item_pool.lock);

    if ((double)item_pool.used / item_pool.pool_size > EXPAND_THRESHOLD) {
        expand_memory_pool(&item_pool);
    }

    void *space = (char*)item_pool.memory + item_pool.used * sizeof(Item);
    item_pool.used++;

    Item *itm = (Item *)space;
    itm->number = ((float)rand() / RAND_MAX) * 100.0f; // Example range
    itm->index = rand() % 50; // Example limit

    size_t string_length = rand() % 10 + 1;
    char *str = malloc(string_length + 1);
    for (size_t i = 0; i < string_length; ++i) {
        str[i] = 'a' + rand() % 26;
    }
    str[string_length] = '\0';
    itm->string = str;

    pthread_mutex_unlock(&item_pool.lock);

    return itm;
}

void free_item(Item *itm) {
    if (itm) {
        free(itm->string);
        pthread_mutex_lock(&item_pool.lock);
        item_pool.used--;
        pthread_mutex_unlock(&item_pool.lock);
    }
}

void free_record(Record *rec) {
    pthread_mutex_lock(&record_pool.lock);
    record_pool.used--;
    pthread_mutex_unlock(&record_pool.lock);
}

void initialize_system() {
    srand(time(NULL));
    init_memory_pool(&record_pool, sizeof(Record));
    init_memory_pool(&item_pool, sizeof(Item));
}

int main() {
    initialize_system();

    Record *rec = allocate_record();
    Item *itm = allocate_item();

    printf("Allocated record: key=%d, value=%d\n", rec->key, rec->value);
    printf("Allocated item: number=%.2f, index=%d, string=%s\n", itm->number, itm->index, itm->string);

    free_record(rec);
    free_item(itm);

    return 0;
}
