    if (*offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = (long)i;
    }

    // Allocate and initialize keys
    *keys = (int *)malloc(num_offsets * sizeof(int));
    if (*keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < num_offsets; ++i) {
        (*keys)[i] = rand() % 1000001;
    }

    // Allocate and initialize records
    *records = (Record **)malloc(num_offsets * sizeof(Record *));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        (*records)[i] = (Record *)malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            perror("Failed to allocate memory for record");
            for (size_t j = 0; j <= i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            exit(EXIT_FAILURE);
        }

        (*records)[i]->offset_ptr = &(*offsets)[i];
        (*records)[i]->key = (*keys)[i];
    }

    // Verify integrity of records
    for (size_t i = 0; i < num_offsets; ++i) {
        if ((*records)[i]->offset_ptr != &(*offsets)[i] || 
            *(*records)[i]->offset_ptr != (long)i ||
            (*records)[i]->key != (*keys)[i]) {
            fprintf(stderr, "Error: Record %zu is inconsistent\n", i);
            exit(EXIT_FAILURE);
        }
    }

    printf("All records are consistent.\n");
}

void serialize_records(const Record **records, size_t num_offsets, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for serialization");
        return;
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        long offset = *(*records)[i]->offset_ptr;
        int key = (*records)[i]->key;

        if (fwrite(&offset, sizeof(long), 1, file) != 1 ||
            fwrite(&key, sizeof(int), 1, file) != 1) {
            perror("Failed to serialize records");
            fclose(file);
            return;
        }
    }

    if (fclose(file) != 0) {
        perror("Failed to close file after serialization");
    } else {
        printf("Serialization successful.\n");
    }
}

void free_resources(long *offsets, int *keys, Record **records, size_t num_offsets) {
    for (size_t i = 0; i < num_offsets; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
}

