// Helper function to find the median of an array
double findMedian(double* arr, int size) {
    qsort(arr, size, sizeof(double), compareDoubles);
    if (size % 2 == 0)
        return (arr[size / 2 - 1] + arr[size / 2]) / 2.0;
    else
        return arr[size / 2];
}

int compareDoubles(const void* a, const void* b) {
    double arg1 = *(const double*)a;
    double arg2 = *(const double*)b;

    if (arg1 < arg2) return -1;
    if (arg1 > arg2) return 1;
    return 0;
}

// Thread-safe function to dynamically manage and find the median
double* processAndFindMedian(double* incomingData, int numSamples,
                             void* pipeline, int lastProcessedIndex,
                             int maxBufferedSamples, double** medianResult) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    double* buffer = NULL;
    int bufferSize = 0;

    pthread_mutex_lock(&lock);

    if (buffer == NULL || bufferSize < maxBufferedSamples) {
        if (buffer != NULL) free(buffer);
        buffer = malloc(maxBufferedSamples * sizeof(double));
        if (!buffer) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        bufferSize = maxBufferedSamples;
    }

    // Copy new samples into the buffer
    for (int i = lastProcessedIndex + 1; i < numSamples && bufferSize > 0; ++i, --bufferSize) {
        buffer[bufferSize - 1] = incomingData[i];
    }

    pthread_mutex_unlock(&lock);

    if (!buffer || bufferSize == maxBufferedSamples) { // Check overflow scenario
        *medianResult = NULL;
        return NULL;
    }

    double median = findMedian(buffer, numSamples - lastProcessedIndex - 1);
    *medianResult = &median;

    return buffer; // Return the pointer to the sample sequence
}

void releaseBuffer(double* buffer) {
    if (buffer) {
        free(buffer);
    }
}

int main() {
    // Example usage of processAndFindMedian function
    double incomingData[] = {1.0, 3.5, 2.2, 8.1, 4.6};
    int numSamples = sizeof(incomingData) / sizeof(incomingData[0]);

    void* pipeline = NULL; // Placeholder for the actual data processing pipeline
    double* medianResult;
    double* buffer = processAndFindMedian(incomingData, numSamples, pipeline, -1, 10, &medianResult);

    if (buffer && medianResult) {
        printf("Median: %f\n", *medianResult);
        releaseBuffer(buffer);
    } else {
        printf("Error processing data or insufficient memory.\n");
    }

    return 0;
}
