// Global mutex for thread safety
pthread_mutex_t bufferMutex = PTHREAD_MUTEX_INITIALIZER;

SampleSequence* manageAndFindMedian(double *samples, int num_samples,
                                    void *pipeline, int last_index,
                                    int max_buffer_size) {
    pthread_mutex_lock(&bufferMutex);

    // Check if we have enough memory to allocate the sequence
    SampleSequence *seq = (SampleSequence *)malloc(sizeof(SampleSequence));
    if (!seq) {
        pthread_mutex_unlock(&bufferMutex);
        return NULL;
    }

    // Calculate the number of samples to buffer
    size_t buffer_size = num_samples > max_buffer_size ? max_buffer_size : num_samples;

    seq->data = (double *)malloc(buffer_size * sizeof(double));
    if (!seq->data) {
        free(seq);
        pthread_mutex_unlock(&bufferMutex);
        return NULL;
    }

    // Copy data into the sequence
    for (int i = 0; i < buffer_size; ++i) {
        seq->data[i] = samples[(last_index + i) % num_samples];
    }

    seq->size = buffer_size;

    double median = findMedian(seq->data, seq->size);
    printf("Median: %.2f\n", median);

    pthread_mutex_unlock(&bufferMutex);
    return seq;
}

double findMedian(double *sequence, size_t length) {
    // Simple implementation using a sorting algorithm
    double sorted[length];
    for (size_t i = 0; i < length; ++i) {
        sorted[i] = sequence[i];
    }

    qsort(sorted, length, sizeof(double), (int (*)(const void *, const void *))strcmp);

    if (length % 2 == 0) {
        return (sorted[length / 2 - 1] + sorted[length / 2]) / 2.0;
    } else {
        return sorted[length / 2];
    }
}

void freeSampleSequence(SampleSequence *seq) {
    if (seq) {
        free(seq->data);
        free(seq);
    }
}
