    if (!offsets) return NULL;
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }
    return offsets;
}

int* initialize_keys(int num_offsets) {
    int* keys = (int*)malloc(num_offsets * sizeof(int));
    if (!keys) return NULL;

    // Using a simple hash table for collision resolution
    unsigned char used[1000001] = {0};
    for (int i = 0; i < num_offsets;) {
        int key = generate_random_key(0, 1000000);
        while (used[key]) {
            key = generate_random_key(0, 1000000);
        }
        keys[i++] = key;
        used[key] = 1;
    }

    return keys;
}

Record* initialize_records(long* offsets, int* keys, int num_offsets) {
    Record* records = (Record*)malloc(num_offsets * sizeof(Record));
    if (!records) return NULL;

    for (int i = 0; i < num_offsets; ++i) {
        records[i].offset_ptr = &offsets[i];
        records[i].key = keys[i];

        // Integrity checks
        if ((long)records[i].offset_ptr - (long)offsets >= sizeof(long) * num_offsets) {
            fprintf(stderr, "Error: Invalid offset pointer detected.\n");
            free_resources(offsets, keys, records);
            exit(EXIT_FAILURE);
