            fprintf(stderr, "Error: Key mismatch detected.\n");
            free_resources(offsets, keys, records);
            exit(EXIT_FAILURE);
        }
    }

    return records;
}

void serialize_records(Record* records, int num_offsets, char** output, size_t* output_size) {
    *output = (char*)malloc(num_offsets * sizeof(Record));
    if (!(*output)) {
        fprintf(stderr, "Serialization failed: Memory allocation error.\n");
        exit(EXIT_FAILURE);
    }

    memcpy(*output, records, num_offsets * sizeof(Record));
    *output_size = num_offsets * sizeof(Record);

    // Check for buffer overflow
    if (*output_size > SIZE_MAX) {
        free(*output);
        fprintf(stderr, "Serialization failed: Output size too large.\n");
        exit(EXIT_FAILURE);
    }
}

int deserialize_records(char* input, size_t input_size, Record** records, int* num_offsets) {
    if (input == NULL || input_size % sizeof(Record) != 0) {
        fprintf(stderr, "Deserialization failed: Invalid input data.\n");
        return -1;
    }

    *num_offsets = input_size / sizeof(Record);
    *records = (Record*)malloc(input_size);
    if (!(*records)) {
        fprintf(stderr, "Deserialization failed: Memory allocation error.\n");
        return -1;
