void destroy_memory_pool(MemoryPool *mp);
void* allocate_from_pool(MemoryPool *mp);
record* initialize_data_structures(size_t dataset_size, int value_range, const char *metadata_format);

// Create a memory pool
MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = aligned_alloc(alignof(long), block_size * pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->block_size = block_size;
    mp->pool_size = pool_size;
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

// Destroy a memory pool
void destroy_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

// Allocate memory from the pool in a thread-safe manner
void* allocate_from_pool(MemoryPool *mp) {
    void *block = NULL;
    pthread_mutex_lock(&mp->lock);

    if (mp->pool_size > 0) {
        block = mp->pool + (--mp->pool_size) * mp->block_size;
    }

    pthread_mutex_unlock(&mp->lock);
    return block;
}

// Initialize data structures
record* initialize_data_structures(size_t dataset_size, int value_range, const char *metadata_format) {
    MemoryPool *long_pool = create_memory_pool(sizeof(long), dataset_size);
    if (!long_pool) return NULL;

    MemoryPool *int_pool = create_memory_pool(sizeof(int), dataset_size);
    if (!int_pool) goto cleanup;

    MemoryPool *record_pool = create_memory_pool(sizeof(record), dataset_size);
    if (!record_pool) goto cleanup;

    MemoryPool *timestamp_pool = create_memory_pool(sizeof(long), dataset_size);
    if (!timestamp_pool) goto cleanup;

    MemoryPool *metadata_pool = create_memory_pool(strlen(metadata_format) + 1, dataset_size);
    if (!metadata_pool) goto cleanup;

    record *records = (record*)allocate_from_pool(record_pool);
    if (!records) goto cleanup;

    for (size_t i = 0; i < dataset_size; ++i) {
        records[i].value = rand() % value_range;
        records[i].timestamp = (long*)allocate_from_pool(timestamp_pool);

        char *metadata = (char*)allocate_from_pool(metadata_pool);
        if (!metadata) goto cleanup;

        strncpy(metadata, metadata_format, strlen(metadata_format));
        metadata[strlen(metadata_format)] = '\0';
        records[i].metadata = metadata;
    }

    destroy_memory_pool(long_pool);
    destroy_memory_pool(int_pool);
    destroy_memory_pool(timestamp_pool);
    destroy_memory_pool(metadata_pool);

    return records;

cleanup:
    if (long_pool) destroy_memory_pool(long_pool);
    if (int_pool) destroy_memory_pool(int_pool);
    if (record_pool) destroy_memory_pool(record_pool);
    if (timestamp_pool) destroy_memory_pool(timestamp_pool);
    if (metadata_pool) destroy_memory_pool(metadata_pool);

    return NULL;
}

// Main function for testing
