    long* offsets;
    int* keys;
    Record** records;
    size_t num_records;
    pthread_mutex_t mutex;
} CryptoManager;

typedef enum {
    MODE_ECB,
    MODE_CBC,
    MODE_CFB,
    MODE_GCM,
    MODE_NULL
} EncryptionMode;

typedef enum {
    ALGORITHM_DES,
