#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record_t;

typedef struct memory_pool {
    size_t block_size;
    void *memory;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} memory_pool_t;

// Function prototypes
void initialize_memory_pool(memory_pool_t *pool, size_t num_records);
void destroy_memory_pool(memory_pool_t *pool);
record_t *allocate_record(memory_pool_t *pool, int min_value, int max_value);
void free_record(record_t *rec);

static void log_usage(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void initialize_memory_pool(memory_pool_t *pool, size_t num_records) {
    if (num_records == 0 || num_records > MAX_RECORDS) {
        fprintf(stderr, "Invalid number of records requested.\n");
        return;
    }

    pool->block_size = sizeof(record_t);
    pool->memory = malloc(num_records * pool->block_size);

    if (!pool->memory) {
        fprintf(stderr, "Memory allocation failed for memory pool.\n");
        return;
    }

    pool->total_blocks = num_records;
    pool->used_blocks = 0;

    pthread_mutex_init(&pool->lock, NULL);
    log_usage("Memory pool initialized successfully.");
}

void destroy_memory_pool(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->memory) {
        free(pool->memory);
        log_usage("Memory pool destroyed successfully.");
    }

    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

record_t *allocate_record(memory_pool_t *pool, int min_value, int max_value) {
    if (min_value > max_value) {
        fprintf(stderr, "Invalid range for random value generation.\n");
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);

    if (pool->used_blocks >= pool->total_blocks) {
        log_usage("Memory pool allocation limit reached.");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    record_t *new_record = (record_t *)((char *)pool->memory + (pool->used_blocks++ * pool->block_size));

    // Initialize with a random value
    srand((unsigned int)time(NULL));  // Note: This should be done once per application
    new_record->value = rand() % (max_value - min_value + 1) + min_value;

    pthread_mutex_unlock(&pool->lock);
    log_usage("Record allocated successfully.");
    return new_record;
}

void free_record(record_t *rec) {
    // Note: Actual deallocation logic is complex and depends on how memory blocks are tracked.
    // Here, we assume that the record will be reused rather than freed immediately.
    pthread_mutex_lock(&rec->pool->lock);

    // Mark block as unused
    size_t offset = (char *)rec - (char *)rec->pool->memory;
    rec->pool->used_blocks--;

    pthread_mutex_unlock(&rec->pool->lock);
}
