typedef struct {
    long offset;
    int key;
    char data[32];
} Record;

void initialize_records(Record *records, size_t count) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; ++i) {
        records[i].offset = rand() % 1000000L;
        records[i].key = rand() % 1000;

        for (int j = 0; j < sizeof(records[i].data); ++j) {
            records[i].data[j] = 'a' + (rand() % 26);
        }
    }
}

Record *allocate_memory(size_t num_records, size_t max_threshold) {
    if (num_records == 0 || max_threshold < sizeof(Record)) {
        return NULL;
    }

    size_t record_size = sizeof(Record);
    size_t total_size = record_size;

    while ((total_size / record_size) < num_records && total_size + record_size <= max_threshold) {
        ++num_records;
        total_size += record_size;
    }

    if (total_size == 0 || total_size > max_threshold) {
        return NULL;
    }

    Record *records = (Record *)malloc(total_size);

    if (!records && total_size >= record_size) {
        // Try allocating at least one record
        records = (Record *)malloc(record_size);
        num_records = 1; // Only allocate space for a single record
    }

    if (records) {
        initialize_records(records, num_records);
    }

    return records;
}

void release_memory(Record *memory_block) {
    free(memory_block);
}
