// Define record structure
typedef struct {
    int value;
} Record;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize random number generator
void init_random() {
    srand(time(NULL));
}

// Function to generate a sample sequence and find the median
Record* create_sample_sequence(double *data_samples, int num_samples, 
                               void *data_pipeline, int last_index_processed,
                               int max_buffer_size, double **median) {

    if (num_samples > max_buffer_size || data_samples == NULL) {
        return NULL;
    }

    // Allocate memory for records
    Record* sequence = (Record*)malloc(num_samples * sizeof(Record));
    if (!sequence) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize sequence with random values within a specified range
    int lower_bound = INT_MIN;  // Define your own range limits
    int upper_bound = INT_MAX;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_samples; ++i) {
        sequence[i].value = (rand() % (upper_bound - lower_bound + 1)) + lower_bound;
    }

    // Sort the array to find the median
    qsort(sequence, num_samples, sizeof(Record), 
          (int (*)(const void*, const void*))strcmp);

    if (num_samples % 2 == 0) {
        *median = ((double)sequence[num_samples / 2 - 1].value + 
                   (double)sequence[num_samples / 2].value) / 2.0;
    } else {
        *median = (double)sequence[num_samples / 2].value;
    }

    pthread_mutex_unlock(&mutex);

    return sequence;
}

// Function to free the allocated memory for sample sequences
void release_sample_sequence(Record* sequence) {
    if (sequence != NULL) {
        free(sequence);
    }
}
