    let home_dir = dirs::home_dir().expect("Unable to find home directory");
    let config_dir = home_dir.join(CONFIG_DIR_NAME);

    match fs::create_dir_all(&config_dir) {
        Ok(_) => info!("Created configuration directory at {:?}", config_dir),
