void* initializeEvent(Event *event, size_t metadataSize) {
    event->timestamp = ((double)rand() / RAND_MAX) * 100.0; // Random timestamp between 0 and 100
    event->eventType = rand() % 10 + 1; // Random event type between 1 and 10

    size_t bufferLength = getBufferLength(event->eventType);
    if (bufferLength < MIN_BUFFER_SIZE || bufferLength > MAX_BUFFER_SIZE) {
        bufferLength = MIN_BUFFER_SIZE;
    }

    for (size_t i = 0; i < bufferLength; ++i) {
        event->data[i] = rand() % 256; // Random data between 0 and 255
    }

    event->metadata = malloc(metadataSize);
    if (!event->metadata) return NULL;

    memset(event->metadata, rand() % 256, metadataSize); // Initialize with random bytes

    return (void*)(event + 1); // Return pointer to the memory after the Event struct
}

void* allocateEvents(size_t maxMemory, size_t numEventsRequested, ...) {
    if (maxMemory == 0 || numEventsRequested == 0) return NULL;

    va_list args;
    va_start(args, numEventsRequested);

    for (size_t n = numEventsRequested; n > 0; --n) {
        va_list currentArgs;
        va_copy(currentArgs, args);

        size_t totalSize = sizeof(Event) + maxMemory - sizeof(Event); // Initial memory block
        void* memBlock = malloc(totalSize);

        if (!memBlock) continue;

        Event *events = (Event*)memBlock;
        for (size_t i = 0; i < n; ++i) {
            size_t metadataSize = va_arg(currentArgs, size_t);

            if ((totalSize - sizeof(Event)) < (sizeof(Event) + metadataSize + getBufferLength(events[i].eventType))) {
                free(memBlock);
                continue;
            }

            if (!initializeEvent(&events[i], metadataSize)) {
                for (size_t j = 0; j < i; ++j) {
                    free(events[j].metadata); // Cleanup previous allocations
                }
                free(memBlock);
                break;
            }
        }

        va_end(currentArgs);

        if (i == n) { // Successfully initialized all events
            va_end(args);
            return memBlock;
        } else {
            free(memBlock);
        }
    }

    va_end(args);
    return NULL; // Return NULL if unable to allocate memory for any events
}

int main() {
    srand(time(0)); // Seed random number generator

    size_t maxMemory = 1024 * 1024; // Max memory allocation of 1 MB
    size_t numEventsRequested = 10;

    void* eventBlock = allocateEvents(maxMemory, numEventsRequested, 128, 256, 64, 32, 16, 512, 128, 64, 256, 32, 128);

    if (eventBlock) {
        printf("Successfully allocated memory for events.\n");
    } else {
        printf("Failed to allocate memory for events.\n");
    }

    return 0;
}
