```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <stdbool.h>

#define MAX_RECORDS 10000000
#define CACHE_SIZE 1000

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
    pthread_mutex_t lock;
} Dataset;

typedef struct {
    Record records[CACHE_SIZE];
    size_t count;
    pthread_rwlock_t rwlock;
} Cache;

// External logging system mockup
void log_error(const char* message) {
    // Implement integration with an actual logging system here.
    fprintf(stderr, "Error: %s\n", message);
}

void log_performance(const char* message) {
    // Implement performance logging here.
    printf("Performance: %s\n", message);
}

// Memory pool implementation
typedef struct {
    void *pool;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;

    pthread_mutex_init(&mp->lock, NULL);
    mp->pool = malloc(block_size * total_blocks);

    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    return mp;
}

void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_blocks < mp->total_blocks) {
        void *block = (char*)mp->pool + mp->used_blocks * mp->block_size;
        mp->used_blocks++;
        pthread_mutex_unlock(&mp->lock);
        return block;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL;
}

void free_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

// Initialize dataset
Dataset* initialize_dataset(size_t size, int min_val, int max_val) {
    Dataset *ds = malloc(sizeof(Dataset));
    if (!ds) return NULL;

    ds->size = size;
    ds->offsets = (long*)allocate_from_pool(create_memory_pool(sizeof(long), size));
    ds->keys = (int*)allocate_from_pool(create_memory_pool(sizeof(int), size));
    ds->records = (Record*)allocate_from_pool(create_memory_pool(sizeof(Record), size));

    if (!ds->offsets || !ds->keys || !ds->records) {
        free_dataset(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        ds->offsets[i] = rand() % 100000;
        ds->keys[i] = rand() % 1000;
        ds->records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    return ds;
}

void free_dataset(Dataset *ds) {
    if (!ds) return;

    pthread_mutex_destroy(&ds->lock);

    MemoryPool *offset_pool = create_memory_pool(sizeof(long), ds->size);
    MemoryPool *key_pool = create_memory_pool(sizeof(int), ds->size);
    MemoryPool *record_pool = create_memory_pool(sizeof(Record), ds->size);

    free_memory_pool(offset_pool);
    free_memory_pool(key_pool);
    free_memory_pool(record_pool);

    free(ds);
}

// Cache implementation
void initialize_cache(Cache *cache) {
    pthread_rwlock_init(&cache->rwlock, NULL);
    cache->count = 0;
}

void cache_record(Cache *cache, size_t index, const Record *record) {
    pthread_rwlock_wrlock(&cache->rwlock);

    if (cache->count < CACHE_SIZE) {
        cache->records[cache->count++] = *record;
    } else {
        pthread_rwlock_unlock(&cache->rwlock);
        log_error("Cache is full");
    }

    pthread_rwlock_unlock(&cache->rwlock);
}

Record* get_cached_record(Cache *cache, size_t index) {
    pthread_rwlock_rdlock(&cache->rwlock);

    if (index < cache->count) {
        Record *record = &cache->records[index];
        pthread_rwlock_unlock(&cache->rwlock);
        return record;
    }

    pthread_rwlock_unlock(&cache->rwlock);
    return NULL;
}

// Serialization/Deserialization
int serialize_dataset(const Dataset *ds, const char *filename, bool binary) {
    FILE *file = fopen(filename, binary ? "wb" : "w");
    if (!file) {
        log_error("Failed to open file for serialization.");
        return -1;
    }

    pthread_mutex_lock(&ds->lock);

    size_t written_bytes = 0;
    if (binary) {
        fwrite(ds->offsets, sizeof(long), ds->size, file);
        fwrite(ds->keys, sizeof(int), ds->size, file);
        for (size_t i = 0; i < ds->size; ++i) {
            Record record = ds->records[i];
            written_bytes += fwrite(&record, sizeof(Record), 1, file);
        }
    } else {
        for (size_t i = 0; i < ds->size; ++i) {
            fprintf(file, "%ld %d %d\n", ds->offsets[i], ds->keys[i], ds->records[i].value);
            written_bytes += snprintf(NULL, 0, "%ld %d %d\n", ds->offsets[i], ds->keys[i], ds->records[i].value);
        }
    }

    pthread_mutex_unlock(&ds->lock);

    fclose(file);
    return written_bytes;
}

Dataset* deserialize_dataset(const char *filename, bool binary) {
    FILE *file = fopen(filename, binary ? "rb" : "r");
    if (!file) {
        log_error("Failed to open file for deserialization.");
        return NULL;
    }

    Dataset *ds = malloc(sizeof(Dataset));
    if (!ds) {
        fclose(file);
        return NULL;
    }

    size_t size;
    if (binary) {
        fseek(file, 0L, SEEK_END);
        size = ftell(file) / (sizeof(long) + sizeof(int) + sizeof(Record));
        rewind(file);

        ds->size = size;
        ds->offsets = (long*)allocate_from_pool(create_memory_pool(sizeof(long), size));
        ds->keys = (int*)allocate_from_pool(create_memory_pool(sizeof(int), size));
        ds->records = (Record*)allocate_from_pool(create_memory_pool(sizeof(Record), size));

        if (!ds->offsets || !ds->keys || !ds->records) {
            free(file);
            free_dataset(ds);
            return NULL;
        }

        pthread_mutex_init(&ds->lock, NULL);

        fread(ds->offsets, sizeof(long), size, file);
        fread(ds->keys, sizeof(int), size, file);
        for (size_t i = 0; i < size; ++i) {
            fread(&ds->records[i], sizeof(Record), 1, file);
        }
    } else {
        // Implement text-based deserialization logic here.
        log_error("Text-based deserialization not implemented.");
        free(file);
        free_dataset(ds);
        return NULL;
    }

    fclose(file);
    return ds;
}

// Resource accounting and testing omitted for brevity
