// Point struct definition
struct Point {
    float x;
    float y;
};

// Geometry struct definition
struct Geometry {
    double value;
    std::string str;
    Point point;

    // Function to initialize with random data
    void initRandom(size_t string_length) {
        value = static_cast<double>(rand()) / RAND_MAX;

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 25);
        str.clear();
        for (size_t i = 0; i < string_length; ++i) {
            char ch = (dis(gen) % 2 == 0) ? 'A' + dis(gen) : 'a' + dis(gen);
            str.push_back(ch);
        }

        point.x = static_cast<float>(rand()) / RAND_MAX;
        point.y = static_cast<float>(rand()) / RAND_MAX;
    }
};

// MemoryPool class definition
class MemoryPool {
public:
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        void* ptr = malloc(size);
        if (!ptr) throw std::bad_alloc();
        allocated_memory_.push_back(ptr);
        return ptr;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = std::find(allocated_memory_.begin(), allocated_memory_.end(), ptr);
        if (it != allocated_memory_.end()) {
            free(*it);
            allocated_memory_.erase(it);
        }
    }

    ~MemoryPool() {
        for (void* ptr : allocated_memory_) {
            free(ptr);
        }
    }

private:
    std::vector<void*> allocated_memory_;
    std::mutex mutex_;
};

// Thread-safe function to find the largest integer
int findLargestInteger(std::vector<int>& data, int& result) {
    static std::mutex mtx;
    int local_max = INT_MIN;

    auto task = [&local_max](const std::vector<int>::iterator start, const std::vector<int>::iterator end) {
        int local_max_in_range = INT_MIN;
        for (auto it = start; it != end; ++it) {
            if (*it > local_max_in_range) {
                local_max_in_range = *it;
            }
        }

        std::lock_guard<std::mutex> lock(mtx);
        if (local_max_in_range > local_max) {
            local_max = local_max_in_range;
        }
    };

    size_t num_threads = std::thread::hardware_concurrency();
    size_t chunk_size = data.size() / num_threads;

    std::vector<std::thread> threads;
    for (size_t i = 0; i < num_threads; ++i) {
        auto start_it = data.begin() + i * chunk_size;
        auto end_it = (i == num_threads - 1) ? data.end() : start_it + chunk_size;
        threads.emplace_back(task, start_it, end_it);
    }

    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    result = local_max;
    return 0;
}

// Strategy Pattern
class IDataStrategy {
public:
    virtual void process(Geometry* data, size_t count) = 0;
};

class ConcreteDataStrategy : public IDataStrategy {
public:
    void process(Geometry* data, size_t count) override {
        for (size_t i = 0; i < count; ++i) {
            data[i].value *= 2.0;
            std::transform(data[i].str.begin(), data[i].str.end(), data[i].str.begin(),
                           [](char c) { return std::islower(c) ? std::toupper(c) : c; });
