// C function for dynamic memory allocation
struct Record {
    long offset;
    int key;
};

extern "C" void manageRecords(const long* offsets, const int* keys, size_t count, Record* records) {
    if (count == 0 || !offsets || !keys || !records) return;

    for (size_t i = 0; i < count - 1; ++i) {
        if (offsets[i] >= offsets[i + 1]) throw std::invalid_argument("Offsets must be monotonically increasing.");
    }

    std::vector<int> seen_keys;
    for (size_t i = 0; i < count; ++i) {
        auto it = std::find(seen_keys.begin(), seen_keys.end(), keys[i]);
        if (it != seen_keys.end()) throw std::invalid_argument("Keys must be unique.");

        records[i].offset = offsets[i];
        records[i].key = keys[i];
        seen_keys.push_back(keys[i]);
    }
}

int main() {
    // Example usage
    MemoryPool pool;

    size_t num_geometries = 10;
    Geometry* geometries = static_cast<Geometry*>(pool.allocate(num_geometries * sizeof(Geometry)));

    std::vector<int> integers = {3, 1, 4, 1, 5, 9, 2, 6, 5};
