#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a record structure
typedef struct {
    int value;
} Record;

// Function to manage memory for data structures
void manage_memory(size_t num_offsets, size_t num_keys, size_t num_records,
                   int min_value, int max_value, unsigned long seed,
                   int enable_logging, int track_max_usage) {

    // Thread safety: mutex for concurrent access
    static pthread_mutex_t lock;
    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Mutex init has failed\n");
        return;
    }

    srand(seed);
    long *offsets = NULL;
    int *keys = NULL;
    Record **records = NULL;

    size_t max_size = num_offsets > num_keys ? num_offsets : num_keys;
    if (num_records > max_size) {
        max_size = num_records;
    }

    // Allocate memory for offsets
    pthread_mutex_lock(&lock);
    offsets = (long *)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        goto cleanup;
    }
    memset(offsets, 0, num_offsets * sizeof(long));

    // Allocate memory for keys
    keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        goto cleanup;
    }
    memset(keys, 0, num_keys * sizeof(int));

    // Allocate memory for records
    records = (Record **)malloc(num_records * sizeof(Record *));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        goto cleanup;
    }

    size_t max_memory_usage = 0;

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            goto cleanup;
        }

        records[i] = record;
        record->value = rand() % (max_value - min_value + 1) + min_value;

        size_t current_memory_usage = num_offsets * sizeof(long)
                                     + num_keys * sizeof(int)
                                     + (i + 1) * sizeof(Record *);
                                     + (i + 1) * sizeof(Record);

        if (track_max_usage && current_memory_usage > max_memory_usage) {
            max_memory_usage = current_memory_usage;
        }
    }

    if (enable_logging) {
        printf("Memory usage: %zu bytes\n", num_offsets * sizeof(long)
               + num_keys * sizeof(int)
               + num_records * (sizeof(Record *) + sizeof(Record)));
        if (track_max_usage) {
            printf("Maximum memory usage: %zu bytes\n", max_memory_usage);
        }
    }

cleanup:
    // Free allocated resources
    pthread_mutex_lock(&lock);

    free(offsets);
    offsets = NULL;
    free(keys);
    keys = NULL;
    for (size_t i = 0; i < num_records && records[i]; ++i) {
        free(records[i]);
    }
    free(records);
    records = NULL;

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    // Return error if any allocation failed
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory management encountered an issue\n");
    }
}
