#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Structure definition for a record
typedef struct {
    int key;
} record;

// Logging function to track operations
void log_operation(const char *message) {
    printf("%s\n", message);
}

// Function to handle memory allocation failure
void handle_allocation_failure(void *ptr, const char *message) {
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", message);
        exit(EXIT_FAILURE);
    }
}

// Initialize records with random integers within a specified range
record* initialize_records(size_t count, int min_value, int max_value, size_t *initialized_count) {
    record *records = (record *)malloc(count * sizeof(record));
    handle_allocation_failure(records, "Failed to allocate memory for records");

    log_operation("Initializing records with random values");
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        records[i].key = min_value + rand() % (max_value - min_value + 1);
    }

    *initialized_count = count;
    return records;
}

// Recursive function to filter records that match a given range
record* filter_records_recursive(const record *records, size_t count, int low, int high, size_t *filtered_count) {
    if (count == 0) return NULL;

    // Base case: single element array
    if (count == 1) {
        if ((records[0].key >= low && records[0].key <= high)) {
            *filtered_count = 1;
            record *result = (record *)malloc(sizeof(record));
            handle_allocation_failure(result, "Failed to allocate memory for filtered result");
            result->key = records[0].key;
            return result;
        }
        *filtered_count = 0;
        return NULL;
    }

    // Recursive case
    size_t mid = count / 2;
    record *left_result = filter_records_recursive(records, mid, low, high, filtered_count);
    if (left_result == NULL) {
        return filter_records_recursive(records + mid, count - mid, low, high, filtered_count);
    }

    size_t left_count = *filtered_count;

    record *right_result = filter_records_recursive(records + mid, count - mid, low, high, filtered_count);
    if (right_result != NULL) {
        size_t right_count = *filtered_count - left_count;
        record *result = (record *)malloc((left_count + right_count) * sizeof(record));
        handle_allocation_failure(result, "Failed to allocate memory for combined result");

        memcpy(result, left_result, left_count * sizeof(record));
        memcpy(result + left_count, right_result, right_count * sizeof(record));

        free(left_result);
        free(right_result);

        return result;
    }

    free(left_result);
    *filtered_count = left_count;
    return left_result;
}

// Serialize records to a binary file
void serialize_records(const record *records, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", filename);
        return;
    }

    log_operation("Serializing records to binary file");
    fwrite(records, sizeof(record), count, file);
    fclose(file);
}

// Deserialize records from a binary file
record* deserialize_records(size_t *count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading: %s\n", filename);
        return NULL;
    }

    log_operation("Deserializing records from binary file");

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    *count = size / sizeof(record);

    record *records = (record *)malloc(size);
    handle_allocation_failure(records, "Failed to allocate memory for deserialized records");

    rewind(file);
    fread(records, sizeof(record), *count, file);
    fclose(file);

    return records;
}

// Example usage
int main() {
    size_t count = 1000;
    int min_value = 1;
    int max_value = 100;

    size_t initialized_count;
    record *records = initialize_records(count, min_value, max_value, &initialized_count);

    log_operation("Filtering records with key between 10 and 50");
    size_t filtered_count;
    record *filtered_records = filter_records_recursive(records, initialized_count, 10, 50, &filtered_count);

    if (filtered_records != NULL) {
        printf("Filtered %zu records\n", filtered_count);
        serialize_records(filtered_records, filtered_count, "records.bin");

        size_t deserialized_count;
        record *deserialized_records = deserialize_records(&deserialized_count, "records.bin");
        printf("Deserialized %zu records\n", deserialized_count);

        free(deserialized_records);
    } else {
        printf("No records matched the filter criteria.\n");
    }

    free(filtered_records);
    free(records);
    return 0;
}
