void manage_memory(int seed, size_t num_pdu, size_t num_offsets, size_t num_keys, size_t num_records,
                   int min_val, int max_val, int enable_logging, int track_max_usage) {

    // Seed the random number generator
    srand(seed);

    // Dynamic allocation of structures and arrays
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    record_t **records = NULL;

    // Allocate memory for pdus
    pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for pdus\n");
        return;
    }

    // Allocate memory for offsets and keys
    offsets = (long *)calloc(num_offsets, sizeof(long));
    keys = (int *)malloc(num_keys * sizeof(int));
    if (!offsets || !keys) {
        fprintf(stderr, "Failed to allocate memory for offsets or keys\n");
        free(pdus);
        free(offsets);
        free(keys);
        return;
    }

    // Allocate and initialize records
    records = (record_t **)malloc(num_records * sizeof(record_t *));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(pdus);
        free(offsets);
        free(keys);
        return;
    }

    int max_memory_usage = 0;

    for (size_t i = 0; i < num_records; ++i) {
        // Allocate each record
        records[i] = (record_t *)malloc(sizeof(record_t));
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate memory for record %zu\n", i);
            while (--i >= 0)
                free(records[i]);
            free(pdus);
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        // Initialize with a random value
        records[i]->value = rand() % (max_val - min_val + 1) + min_val;

        if (enable_logging) {
            printf("Record %zu initialized with value: %d\n", i, records[i]->value);
        }

        long current_usage = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdu +
                             sizeof(long) * num_offsets +
                             sizeof(int) * num_keys +
                             (i + 1) * sizeof(record_t *);
        if (track_max_usage && current_usage > max_memory_usage) {
            max_memory_usage = current_usage;
        }
    }

    // Randomly populate pdus with data
    for (size_t i = 0; i < num_pdu; ++i) {
        pdus[i].ue_info.RNTI = rand() % 10000;  // Example RNTI value
        pdus[i].crc_indication.CRCFLAG = rand() & 1;

        if (enable_logging) {
            printf("PDU %zu: RNTI=%d, CRCFLAG=%d\n", i, pdus[i].ue_info.RNTI, pdus[i].crc_indication.CRCFLAG);
        }
    }

    // Populate offsets and keys with random values
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % 100000;
    }

    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = rand() % 10000;
    }

    if (enable_logging) {
        printf("Offsets and Keys populated.\n");
    }

    // Deallocate resources
    free(pdus);
    free(offsets);
    free(keys);

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);

    if (track_max_usage && enable_logging) {
        printf("Maximum memory usage: %ld bytes\n", max_memory_usage);
    }
}

// Example usage
int main() {
    manage_memory(42, 10, 5, 3, 7, 0, 100, 1, 1);
    return 0;
}
