#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 100

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    double *doubles;
    char **strings;
    Point *points;
    size_t count;
} DataSet;

typedef struct {
    void *pool;
    size_t total_size;
    pthread_mutex_t lock;
} MemoryPool;

void* memory_pool_alloc(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->total_size < size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Not enough space
    }
    void *ptr = mp->pool;
    mp->pool = ((char*)mp->pool) + size;
    mp->total_size -= size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void memory_pool_init(MemoryPool *mp, size_t total_size) {
    mp->pool = malloc(total_size);
    mp->total_size = total_size;
    pthread_mutex_init(&mp->lock, NULL);
}

void memory_pool_destroy(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

DataSet* initialize_dataset_from_csv(const char *filename, MemoryPool *mp) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    DataSet *dataset = memory_pool_alloc(mp, sizeof(DataSet));
    dataset->doubles = (double*)memory_pool_alloc(mp, 0); // Allocate as needed
    dataset->strings = (char**)memory_pool_alloc(mp, 0);
    dataset->points = (Point*)memory_pool_alloc(mp, 0);

    char line[256];
    size_t count = 0;
    while (fgets(line, sizeof(line), file)) {
        double d_value;
        char str[MAX_STRING_LENGTH + 1];
        float x, y;

        if (sscanf(line, "%lf,%100[^,],%f,%f", &d_value, str, &x, &y) == 4) {
            dataset->count++;
            dataset->doubles = realloc(dataset->doubles, sizeof(double) * dataset->count);
            dataset->strings = realloc(dataset->strings, sizeof(char*) * dataset->count);
            dataset->points = realloc(dataset->points, sizeof(Point) * dataset->count);

            dataset->doubles[count] = d_value;
            dataset->strings[count] = strdup(str);
            dataset->points[count].x = x;
            dataset->points[count].y = y;
            count++;
        } else {
            fprintf(stderr, "Malformed input line: %s", line);
        }
    }

    fclose(file);
    return dataset;
}

void free_dataset(DataSet *dataset) {
    if (!dataset) return;

    for (size_t i = 0; i < dataset->count; ++i) {
        free(dataset->strings[i]);
    }
    free(dataset->doubles);
    free(dataset->strings);
    free(dataset->points);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t pool_size = 1024 * 1024; // 1MB memory pool
    MemoryPool mp;
    memory_pool_init(&mp, pool_size);

    DataSet *dataset = initialize_dataset_from_csv(argv[1], &mp);
    if (!dataset) {
        fprintf(stderr, "Failed to load dataset\n");
        return EXIT_FAILURE;
    }

    // Use the dataset...

    free_dataset(dataset);
    memory_pool_destroy(&mp);

    return EXIT_SUCCESS;
}
