public:
    MemoryPool(size_t size) : totalSize(size), availableSize(size) {}

    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mtx);
        if (availableSize >= size) {
            void* ptr = currentPtr;
            currentPtr += size;
            availableSize -= size;
            return ptr;
        }
        return nullptr; // Out of memory
    }

