struct Point {
    float x, y;
};

struct Geometry {
    double value;
    std::string str;
    Point point;

    void randomize(float minRange, float maxRange, size_t stringLength) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(minRange, maxRange);
        point.x = dis(gen);
        point.y = dis(gen);

        static std::uniform_int_distribution<> charDis(48, 122); // ASCII range for alphanumerics
        str.clear();
        for (size_t i = 0; i < stringLength; ++i) {
            char c = charDis(gen);
            if ((c > 57 && c < 65) || (c > 90 && c < 97)) continue;
            str.push_back(c);
        }
    }
};

class Strategy {
public:
    virtual void execute() = 0;
};

class DataProcessingTask : public Strategy {
public:
    DataProcessingTask(MemoryPool& pool, size_t doubleArraySize, size_t stringArraySize, size_t pointArraySize)
        : memoryPool(pool), doubleArray(nullptr), stringArray(nullptr), pointArray(nullptr) {

        // Allocate and initialize arrays
        doubleArray = static_cast<double*>(memoryPool.allocate(doubleArraySize * sizeof(double)));
        std::fill_n(doubleArray, doubleArraySize, 0.0);

        char* stringMem = static_cast<char*>(memoryPool.allocate(stringArraySize * sizeof(std::string) + stringArraySize));
        for (size_t i = 0; i < stringArraySize; ++i) {
            stringArray[i].assign(&stringMem[i * std::string::max_size()]);
        }

        pointArray = static_cast<Point*>(memoryPool.allocate(pointArraySize * sizeof(Point)));
        for (size_t i = 0; i < pointArraySize; ++i) {
            pointArray[i] = {0.0f, 0.0f};
        }
    }

    void execute() override {
        std::cout << "Data processing task executed." << std::endl;
    }

    ~DataProcessingTask() {
        if (doubleArray) memoryPool.deallocate(doubleArray, sizeof(double) * doubleArraySize);
        if (stringArray) memoryPool.deallocate(static_cast<void*>(static_cast<char*>(stringArray[0].c_str()) - stringArraySize), sizeof(std::string) * stringArraySize + stringArraySize);
        if (pointArray) memoryPool.deallocate(pointArray, sizeof(Point) * pointArraySize);
    }

private:
    MemoryPool& memoryPool;
    double* doubleArray;
    std::vector<std::string> stringArray;
    Point* pointArray;
    size_t doubleArraySize = 100; // Example size
    size_t stringArraySize = 100; // Example size
    size_t pointArraySize = 100;  // Example size
};

class ThreadSafeMaxFinder {
public:
    void addValue(int value) {
        std::lock_guard<std::mutex> lock(mtx);
        maxValue = std::max(maxValue, value);
    }

    int getMaxValue() const {
        std::lock_guard<std::mutex> lock(mtx);
        return maxValue;
    }

private:
    mutable std::mutex mtx;
    int maxValue = INT_MIN;
};

void loadDataFromFile(const std::string& filename) {
    MemoryPool pool(1024 * 1024); // 1 MB for example
    DataProcessingTask task(pool, 100, 100, 100);
    task.execute();
}

int main() {
    loadDataFromFile("data.bin");

    ThreadSafeMaxFinder maxFinder;
    std::vector<std::thread> threads;

    // Reading integers from standard input
    int number;
    while (std::cin >> number) {
        threads.emplace_back([&maxFinder, number]() { maxFinder.addValue(number); });
    }

    for (auto& t : threads) {
        if (t.joinable()) t.join();
    }

    std::cout << "Largest integer: " << maxFinder.getMaxValue() << std::endl;

    return 0;
}
