}

typedef struct StateNode {
    int state;
    struct StateNode* next;
} StateNode;

// Thread-safe mechanism
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

StateNode* StateListManager(int *states, int numStates, StateNode *fsa, int lastStateIndex) {
    pthread_mutex_lock(&lock);

    // Memory pool and data cache initialization (simplified for this example)
    StateNode **statePool = malloc(sizeof(StateNode*) * 10);
    if (!statePool) {
        log_message("Memory allocation failed for state pool.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int allocatedStates = 0;

    // Create new state list
    StateNode *newListHead = NULL, *newListTail = NULL;
    for (int i = 0; i < numStates; ++i) {
        if (!states[i]) continue;  // Add only non-zero states

        StateNode* newNode = malloc(sizeof(StateNode));
        if (!newNode) {
            log_message("Memory allocation failed for state node.");
            pthread_mutex_unlock(&lock);
            free(statePool); // Clean up
            return NULL;
        }

        newNode->state = states[i];
        newNode->next = NULL;

        if (newListHead == NULL) newListHead = newNode;
        if (newListTail != NULL) newListTail->next = newNode;

        newListTail = newNode;
        statePool[allocatedStates++] = newNode; // Add to pool
    }

    if (lastStateIndex >= 0 && fsa) {
        StateNode *temp = fsa;
        for (int i = 0; temp != NULL && i < lastStateIndex; ++i)
            temp = temp->next;

        if (temp != NULL) temp->next = newListHead; // Link to new list
    }

    pthread_mutex_unlock(&lock);
    return newListHead;
}

void cleanup(StateNode *list) {
    while (list != NULL) {
        StateNode* next = list->next;
        free(list);
        list = next;
    }
}
