using System;
using System.Collections.Generic;

public class DynamicStateGenerator
{
    private long _minValue, _maxValue, _stepSize;

    public DynamicStateGenerator(long minValue, long maxValue, long stepSize)
    {
        if (minValue >= maxValue) throw new ArgumentException("minValue must be less than maxValue");
        UpdateRange(minValue, maxValue);
        _stepSize = stepSize;
    }

    public DynamicStateGenerator(string rangeString)
    {
        var parts = rangeString.Split('-');
        if (parts.Length != 2) throw new ArgumentException("Invalid range string format");

        long minValue = long.Parse(parts[0]);
        long maxValue = long.Parse(parts[1]);

        UpdateRange(minValue, maxValue);
        _stepSize = 1; // Default step size
    }

    public int GetRandomInt()
    {
        Random random = new Random();
        return (int)(GetNextValidState(random.Next(_minValue, _maxValue + 1)));
    }

    public List<int> GetRandomList(int count)
    {
        List<int> result = new List<int>();
        for (int i = 0; i < count; ++i)
            result.Add(GetRandomInt());

        return result;
    }

    private long GetNextValidState(long value)
    {
        long offset = value - _minValue;
        long adjusted = (_minValue + ((_stepSize * ((offset / _stepSize) + 1))));
        return Math.Min(adjusted, _maxValue);
    }

    public void UpdateRange(long minValue, long maxValue)
    {
        if (minValue >= maxValue) throw new ArgumentException("minValue must be less than maxValue");
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public override string ToString()
    {
        return $"[{_minValue}, {_maxValue}]";
    }
}
