// Custom slab allocator (simplified for this example)
class SlabAllocator {
public:
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!freeList_.empty() && freeList_.back().size >= size) {
            auto ptr = freeList_.back();
            freeList_.pop_back();
            return ptr.ptr;
        }

        // Allocate new slab
        void* memory = std::malloc(size);
        usedSlabs_.emplace_back(memory, size);
        return memory;
    }

    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = usedSlabs_.begin(); it != usedSlabs_.end(); ++it) {
            if (it->ptr == ptr) {
                freeList_.emplace_back(it->size, ptr);
                usedSlabs_.erase(it);
                std::free(ptr);
                return;
            }
        }
    }

private:
    struct Slab {
        void* ptr;
        size_t size;
    };

    std::vector<Slab> usedSlabs_;
    std::vector<Slab> freeList_;
    std::mutex mutex_;
};

class AudioStreamProcessor {
public:
    AudioStreamProcessor(const std::string& config) {
        parseConfig(config);
        if (sampleRate == 0 || channels == 0) {
            fallbackInit();
        }
    }

    int GetRandomSampleValue() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(-32768, 32767);

        return dis(gen);
    }

    void GetRandomAudioFrame(std::vector<int16_t>& frame) {
        frame.resize(channels);
        for (auto& sample : frame) {
            sample = static_cast<int16_t>(GetRandomSampleValue());
        }
    }

    std::vector<std::vector<int16_t>> GetRandomAudioBuffer(int frameCount) {
        std::vector<std::vector<int16_t>> buffer(frameCount, std::vector<int16_t>(channels));

        for (auto& frame : buffer) {
            GetRandomAudioFrame(frame);
        }

        return buffer;
    }

private:
    int sampleRate = 0;
    int channels = 0;
    SlabAllocator audioPool;
    std::mutex bufferManager;

    void parseConfig(const std::string& config) {
        size_t pos = config.find('/');
        if (pos != std::string::npos) {
            std::string rateStr = config.substr(0, pos);
            std::string chanStr = config.substr(pos + 1);

            sampleRate = std::stoi(rateStr.substr(0, rateStr.size() - 2));
            channels = chanStr == "mono" ? 1 : (chanStr == "stereo" ? 2 : (chanStr == "quad" ? 4 : 0));

            if (sampleRate <= 0 || channels <= 0) {
                sampleRate = 0;
                channels = 0;
            }
        }
    }

    void fallbackInit() {
        // Default to a common configuration
        sampleRate = 44100; // Hz
        channels = 2;       // Stereo
    }
};

int main() {
    AudioStreamProcessor processor("48000Hz/stereo");
    auto buffer = processor.GetRandomAudioBuffer(10);

    for (const auto& frame : buffer) {
        for (auto sample : frame) {
            std::cout << sample << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
