#define LOG_FILE "performance.log"
#define INITIAL_POOL_SIZE 1024

typedef struct {
    float floatValue;
    double doubleValue;
    char* stringValue;
} Record;

typedef struct MemoryBlock {
    size_t size;
    struct MemoryBlock* next;
    int in_use;
} MemoryBlock;

typedef struct {
    void* start;
    MemoryBlock* blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t records_lock = PTHREAD_RWLOCK_INITIALIZER;

void* custom_malloc(size_t size) {
    static int initialized = 0;
    if (!initialized) {
        void* memory = malloc(INITIAL_POOL_SIZE);
        pool.start = memory;
        pool.blocks = (MemoryBlock*)memory;
        pool.blocks->size = INITIAL_POOL_SIZE - sizeof(MemoryBlock);
        pool.blocks->next = NULL;
        pool.blocks->in_use = 0;
        initialized = 1;
    }
    pthread_mutex_lock(&pool.lock);

    MemoryBlock* current = pool.blocks;
    while (current) {
        if (!current->in_use && current->size >= size) {
            current->in_use = 1;
            pthread_mutex_unlock(&pool.lock);
            return (char*)current + sizeof(MemoryBlock);
        }
        current = current->next;
    }

    // No block found, allocate new
    size_t total_size = size + sizeof(MemoryBlock);
    void* new_block = malloc(total_size);
    MemoryBlock* new_memory_block = (MemoryBlock*)new_block;

    new_memory_block->size = total_size - sizeof(MemoryBlock);
    new_memory_block->next = pool.blocks;
    new_memory_block->in_use = 1;

    pool.blocks = new_memory_block;
    pthread_mutex_unlock(&pool.lock);

    return new_block + sizeof(MemoryBlock);
}

void custom_free(void* ptr) {
    if (!ptr) return;

    char* adjusted_ptr = (char*)ptr - sizeof(MemoryBlock);
    MemoryBlock* block_to_free = (MemoryBlock*)adjusted_ptr;

    pthread_mutex_lock(&pool.lock);

    MemoryBlock* current = pool.blocks;
    while (current != block_to_free) {
        if (!current->next) break;
        current = current->next;
    }

    if (current == block_to_free) {
        block_to_free->in_use = 0;

        // Coalesce adjacent free blocks
        if (current->next && !current->next->in_use) {
            MemoryBlock* next_block = current->next;
            current->size += sizeof(MemoryBlock) + next_block->size;
            current->next = next_block->next;
            free(next_block);
        }
    }

    pthread_mutex_unlock(&pool.lock);
}

void log_time(const char* message, double duration) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        time_t rawtime;
        struct tm* timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        pthread_mutex_lock(&log_lock);
        fprintf(file, "[%s] %s took %.6f seconds\n", asctime(timeinfo), message, duration);
        fflush(file);
        fclose(file);
        pthread_mutex_unlock(&log_lock);
    }
}

