    pthread_rwlock_wrlock(&records_lock);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    record->stringValue = (char*)custom_malloc(strlen(record->stringValue) + 1);

    if (!record->stringValue) {
