// Define a structure for managing sample sequence with thread safety
typedef struct {
    double *buffer;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for ensuring thread safety
} SampleSequence;

// Function prototypes
SampleSequence* create_sample_sequence(double *data, int num_samples, void *pipeline, int last_index, int max_buffer_size);
double find_median(SampleSequence *seq);
void release_sample_sequence(SampleSequence **seq);

// Helper function to perform a quickselect algorithm for finding median
static double quickselect(double arr[], int left, int right, int k);

SampleSequence* create_sample_sequence(double *data, int num_samples, void *pipeline, int last_index, int max_buffer_size) {
    SampleSequence *seq = (SampleSequence *)malloc(sizeof(SampleSequence));
    if (!seq) return NULL; // Check for memory allocation failure

    seq->capacity = (num_samples <= max_buffer_size) ? num_samples : max_buffer_size;
    seq->buffer = (double *)malloc(seq->capacity * sizeof(double));
    if (!seq->buffer) {
        free(seq);
        return NULL; // Check for memory allocation failure
    }

    pthread_mutex_init(&seq->lock, NULL);

    // Copy data to buffer with consideration of last_index processed and max_buffer_size constraints
    int start = (last_index + 1) % seq->capacity;
    int end = start + num_samples;

    for (int i = 0; i < num_samples && i < seq->capacity; ++i) {
        seq->buffer[(start + i) % seq->capacity] = data[i];
    }
    seq->count = num_samples;

    return seq;
}

double find_median(SampleSequence *seq) {
    if (!seq || seq->count == 0) return NAN; // Handle empty sequence

    pthread_mutex_lock(&seq->lock);

    int n = seq->count;
    double *sorted_arr = (double *)malloc(n * sizeof(double));
    if (!sorted_arr) {
        pthread_mutex_unlock(&seq->lock);
        return NAN; // Memory allocation failure
    }

    for (int i = 0; i < n; ++i) {
        sorted_arr[i] = seq->buffer[i % seq->capacity];
    }

    double median;
    if (n % 2 == 1) { 
        median = quickselect(sorted_arr, 0, n - 1, n / 2);
    } else {
        double left_median = quickselect(sorted_arr, 0, n - 1, n / 2 - 1);
        double right_median = quickselect(sorted_arr, 0, n - 1, n / 2);
        median = (left_median + right_median) / 2.0;
    }

    free(sorted_arr);
    pthread_mutex_unlock(&seq->lock);

    return median;
}

void release_sample_sequence(SampleSequence **seq) {
    if (!seq || !*seq) return;

    SampleSequence *temp_seq = *seq;
    pthread_mutex_destroy(&temp_seq->lock);
    free(temp_seq->buffer);
    free(temp_seq);

    *seq = NULL;
}

static double quickselect(double arr[], int left, int right, int k) {
    if (left == right) return arr[left];

    int pivot_index = partition(arr, left, right); // Implement partitioning logic

    if (k == pivot_index) 
        return arr[k];
    else if (k < pivot_index)
        return quickselect(arr, left, pivot_index - 1, k);
    else
        return quickselect(arr, pivot_index + 1, right, k);
}

// Example partition function for quickselect
static int partition(double arr[], int left, int right) {
    double pivot = arr[right];
    int i = left;

    for (int j = left; j < right; ++j) {
        if (arr[j] <= pivot) {
            swap(&arr[i], &arr[j]);
            ++i;
        }
    }

    swap(&arr[i], &arr[right]);
    return i;
}

// Helper function to swap elements
static void swap(double *a, double *b) {
    double temp = *a;
    *a = *b;
    *b = temp;
}
