typedef struct {
    float f_value;
    int i_value;
    char* str_value;
} item;

#define MAX_RECORDS 1000
#define MAX_ITEMS 1000

#define RECORD_SLAB_SIZE 64
#define ITEM_SLAB_SIZE 64

pthread_mutex_t memory_pool_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct Slab {
    size_t size;
    void *memory;
    struct Slab *next;
} Slab;

Slab *record_slabs = NULL;
Slab *item_slabs = NULL;

void log_memory_usage(const char* message) {
    printf("%s\n", message);
}

void initialize_random() {
    srand((unsigned int)time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

float random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *string = malloc(length + 1);
    if (string) {
        for (size_t i = 0; i < length; i++) {
            string[i] = charset[random_int(0, sizeof(charset) - 2)];
        }
        string[length] = '\0';
    }
    return string;
}

void* allocate_slab(size_t size, Slab **slabs) {
    pthread_mutex_lock(&memory_pool_lock);

    if (*slabs == NULL || (*slabs)->next == NULL) {
        Slab *new_slab = malloc(sizeof(Slab));
        new_slab->size = size;
        new_slab->memory = malloc(size * sizeof(void*)); // Assuming each element is of the same type
        new_slab->next = NULL;

        if (*slabs == NULL) {
            *slabs = new_slab;
        } else {
            Slab *current = *slabs;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_slab;
        }

        log_memory_usage("Allocated new slab");
    }

    pthread_mutex_unlock(&memory_pool_lock);

    return (*slabs)->memory; // Simplified for demonstration
}

record* create_record(long offset, int key) {
    record *rec = (record*)allocate_slab(sizeof(record), &record_slabs);

    rec->offset = offset;
    rec->key = key;
    rec->value = random_int(1, 100); // Random value within specified range

    return rec;
}

item* create_item(float f_value) {
    item *itm = (item*)allocate_slab(sizeof(item), &item_slabs);

    itm->f_value = random_float(-10.0, 10.0); // Random float in range
    itm->i_value = random_int(1, 1000);
    size_t str_len = random_int(1, 10);
    itm->str_value = generate_random_string(str_len);

    return itm;
}

void deallocate_memory(void) {
    pthread_mutex_lock(&memory_pool_lock);

    Slab *current, *next;

    // Deallocate record slabs
    current = record_slabs;
    while (current != NULL) {
        next = current->next;
        free(current->memory);
        free(current);
        current = next;
    }
    record_slabs = NULL;

    // Deallocate item slabs
    current = item_slabs;
    while (current != NULL) {
        next = current->next;
        for (size_t i = 0; i < ITEM_SLAB_SIZE; ++i) {
            free(((item*)current->memory)[i].str_value);
        }
        free(current->memory);
        free(current);
        current = next;
    }
    item_slabs = NULL;

    pthread_mutex_unlock(&memory_pool_lock);

    log_memory_usage("Deallocated all memory");
}

int main() {
    initialize_random();

    // Example usage
    record *r1 = create_record(100, 5);
    item *i1 = create_item(3.14f);

    printf("Record: offset=%ld, key=%d, value=%d\n", r1->offset, r1->key, r1->value);
    printf("Item: f_value=%.2f, i_value=%d, str_value=%s\n",
           i1->f_value, i1->i_value, i1->str_value);

    // Clean up
    deallocate_memory();

    return 0;
}
