function reduce(array, initialValue, callback) {
    return array.reduce(callback, initialValue);
}

// Example usage
const numbers = [1, 2, 3, 4, 5];
const sum = reduce(numbers, 0, (acc, value) => acc + value);

console.log('Sum:', sum); // Output: Sum: 15

function asyncReduce(array, initialValue, callback, finalCallback) {
    const result = array.reduce((acc, current, index, arr) => {
        if (index === arr.length - 1) {
            return finalCallback(acc);
        } else {
            return callback(acc, current);
        }
    }, initialValue);

    return result;
}

// Example usage
asyncReduce(numbers, 0, 
    (acc, value) => new Promise(resolve => setTimeout(() => resolve(acc + value), 100)), 
    result => console.log('Async Sum:', result)
); // Output: Async Sum: 15 after a delay
