        median = (copy[pipelineData->count / 2 - 1] + copy[pipelineData->count / 2]) / 2.0;
    } else {
        median = copy[pipelineData->count / 2];
    }

    free(copy);
    return median;
}

// Function to dynamically manage and find the median of sequences
PipelineData* processSampleSequence(double *samples, size_t numSamples,
                                    void* pipelinePointer, size_t lastProcessedIndex,
