    if (pipelineData->count + numSamples > pipelineData->capacity) {
        size_t newCapacity = (pipelineData->count + numSamples <= maxBufferCapacity)
            ? pipelineData->count + numSamples : maxBufferCapacity;

        double* newSamples = realloc(pipelineData->samples, newCapacity * sizeof(double));
        if (!newSamples) {
            pthread_mutex_unlock(&pipelineData->lock);
            return NULL;
        }

        pipelineData->samples = newSamples;
        pipelineData->capacity = newCapacity;
