           numSamples * sizeof(double));
    pipelineData->count += numSamples;

    double medianValue = findMedian(pipelineData);

    pthread_mutex_unlock(&pipelineData->lock);

    return pipelineData;
}

// Function to release memory allocated for a sequence
void freePipelineData(PipelineData* pipelineData) {
    if (pipelineData) {
        pthread_mutex_lock(&pipelineData->lock);
        free(pipelineData->samples);
        pthread_mutex_unlock(&pipelineData->lock);
        free(pipelineData);
