#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

// Function prototypes
bool is_prime(int num);
void serialize_records(const long* offsets, const int* keys, size_t num_offsets, const void** records, size_t* out_size);
void initialize_data(size_t num_offsets, long*** offsets, int*** keys, void*** records, size_t* performance_counter);
void free_resources(long** offsets, int** keys, void** records);

// Struct for Records
typedef struct {
    long* offset_ptr;
    int key;
} Record;

bool is_prime(int num) {
    if (num <= 1) return false;
    if (num == 2 || num == 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;
    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0)
            return false;
    }
    return true;
}

void serialize_records(const long* offsets, const int* keys, size_t num_offsets, const void** records, size_t* out_size) {
    // Create a buffer to hold the serialized data
    *out_size = sizeof(long) + sizeof(int) + (num_offsets * (sizeof(long*) + sizeof(int)));
    char* buffer = malloc(*out_size);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for serialization\n");
        return;
    }

    // Copy offsets and keys
    memcpy(buffer, offsets, num_offsets * sizeof(long));
    memcpy(buffer + num_offsets * sizeof(long), keys, num_offsets * sizeof(int));

    // Copy record data (offset pointers and keys)
    for (size_t i = 0; i < num_offsets; ++i) {
        Record* rec = (Record*)(records[i]);
        char* offset_ptr_bytes = (char*)rec->offset_ptr;
        memcpy(buffer + 2 * num_offsets * sizeof(long), offset_ptr_bytes, sizeof(long));
        memcpy(buffer + 2 * num_offsets * sizeof(long) + (i + 1) * sizeof(long), &rec->key, sizeof(int));
    }

    // Store the buffer in records
    *records = buffer;
}

void initialize_data(size_t num_offsets, long*** offsets, int*** keys, void*** records, size_t* performance_counter) {
    *performance_counter = 0;

    // Allocate and initialize offsets
    *offsets = malloc(num_offsets * sizeof(long));
    if (!(*offsets)) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = i;
    }

    // Allocate and initialize keys
    *keys = malloc(num_offsets * sizeof(int));
    if (!(*keys)) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    bool valid_keys_found = false;
    while (!valid_keys_found) {
        int key_pool[num_offsets];
        for (size_t i = 0; i < num_offsets; ++i) {
            key_pool[i] = rand() % 1000001; // Ensure keys are in the range [0, 1000000]
        }

        // Sort and ensure unique values
        qsort(key_pool, num_offsets, sizeof(int), (int(*)(const void*, const void*))strcmp);

        for (size_t i = 0; i < num_offsets; ++i) {
            (*keys)[i] = key_pool[i];
        }

        int sum_keys = 0;
        for (size_t i = 0; i < num_offsets; ++i) {
            sum_keys += (*keys)[i];
        }

        valid_keys_found = is_prime(sum_keys);
    }

    // Allocate records
    *records = malloc(num_offsets * sizeof(Record));
    if (!(*records)) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    // Initialize and sort the records based on keys
    for (size_t i = 0; i < num_offsets; ++i) {
        (*records)[i].offset_ptr = &((*offsets)[i]);
        (*records)[i].key = (*keys)[i];
    }

    qsort(*records, num_offsets, sizeof(Record), (int(*)(const void*, const void*))strcmp);

    // Verify integrity
    for (size_t i = 0; i < num_offsets; ++i) {
        (*performance_counter)++;

        if (((long*)(*records)[i].offset_ptr - *offsets + *performance_counter) < 0 ||
            ((long*)(*records)[i].offset_ptr - *offsets + *performance_counter) >= (int)num_offsets) {
            fprintf(stderr, "Integrity check failed: offset pointer out of bounds\n");
            free_resources(*offsets, *keys, *records);
            exit(EXIT_FAILURE);
        }

        if ((*records)[i].key != (*keys)[(long*)(*records)[i].offset_ptr - *offsets + *performance_counter]) {
            fprintf(stderr, "Integrity check failed: key mismatch\n");
            free_resources(*offsets, *keys, *records);
            exit(EXIT_FAILURE);
        }
    }
}

void free_resources(long** offsets, int** keys, void** records) {
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*records) free(*records);
}
