} StateSequence;

static pthread_mutex_t fsa_lock = PTHREAD_MUTEX_INITIALIZER;

// AES encryption setup using SHA-256 for key derivation
void initialize_aes(EVP_CIPHER_CTX **ctx, const char *password) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)password, strlen(password), hash);

    unsigned char iv[EVP_MAX_IV_LENGTH] = {0};
    *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, hash, iv);
}

// Dynamic memory management function
StateSequence* manage_and_encrypt_states(int *initial_states, size_t num_states, 
                                        const FSA *fsa, int last_state, 
                                        size_t max_alloc) {
    if (num_states == 0 || fsa == NULL) return NULL;

    StateSequence *sequence = malloc(sizeof(StateSequence));
    if (!sequence) return NULL;

    pthread_mutex_init(&sequence->lock, NULL);

    size_t required_size = num_states + last_state;
    sequence->states = realloc(NULL, sizeof(int) * required_size);
    if (!sequence->states) {
        free(sequence);
        return NULL;
    }
    sequence->length = required_size;

    for (size_t i = 0; i < num_states; ++i) {
        pthread_mutex_lock(&fsa_lock); // Ensure thread safety
        int next_state = initial_states[i]; // Hypothetical state transition
        sequence->states[i] = next_state;
        pthread_mutex_unlock(&fsa_lock);
    }

    unsigned char *encrypted_data = malloc(sequence->length * sizeof(int));
    if (!encrypted_data) {
        free(sequence->states);
        free(sequence);
        return NULL;
    }

    EVP_CIPHER_CTX *aes_ctx;
    initialize_aes(&aes_ctx, "your_password");

    int outlen, tmplen;
    EVP_EncryptInit_ex(aes_ctx, NULL, NULL, NULL, NULL);
    EVP_EncryptUpdate(aes_ctx, encrypted_data, &outlen, (unsigned char *)sequence->states, sequence->length * sizeof(int));
    EVP_EncryptFinal_ex(aes_ctx, encrypted_data + outlen, &tmplen);

    sequence->states = realloc(sequence->states, 0); // Release original state data
    free(encrypted_data);
    EVP_CIPHER_CTX_free(aes_ctx);

    return sequence;
}

// Function to release allocated memory for a StateSequence
void release_state_sequence(StateSequence *sequence) {
    if (!sequence) return;

    pthread_mutex_destroy(&sequence->lock);
    free(sequence->states);
    free(sequence);
}

