typedef struct item {
    char name[ITEM_NAME_LEN];
    int quantity;
} Item;

typedef struct order {
    Item **items;
    size_t num_items;
    double amount;
} Order;

typedef struct customer {
    char id[CUSTOMER_NAME_LEN];
    Order *order;
} Customer;

typedef struct TreeNode {
    Customer *customer;
    struct TreeNode *left, *right;
} TreeNode;

typedef struct MemoryPool {
    void *start;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

pthread_mutex_t bst_lock = PTHREAD_MUTEX_INITIALIZER;

MemoryPool create_memory_pool(size_t size) {
    MemoryPool pool;
    pool.start = malloc(size);
    pool.size = size;
    pthread_mutex_init(&pool.lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= size) {
        ptr = pool.start;
        pool->start = ((char*)pool.start) + size;
        pool->size -= size;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void deallocate_memory_pool(MemoryPool *pool) {
    free(pool->start);
    pthread_mutex_destroy(&pool->lock);
}

TreeNode* insert_bst(TreeNode **root, Customer *customer) {
    if (*root == NULL) {
        *root = (TreeNode*)allocate_from_pool(&memory_pool, sizeof(TreeNode));
        if (*root) {
            (*root)->customer = customer;
            (*root)->left = (*root)->right = NULL;
        }
        return *root;
    }

    pthread_mutex_lock(&bst_lock);
    int cmp = strcmp(customer->id, (*root)->customer->id);

    if (cmp < 0)
        return insert_bst(&((*root)->left), customer);
    else if (cmp > 0)
        return insert_bst(&((*root)->right), customer);

    pthread_mutex_unlock(&bst_lock);
    return *root;
}

void free_tree(TreeNode *node) {
    if (node == NULL) return;
    free_tree(node->left);
    free_tree(node->right);
    free(node->customer->order->items);
    free(node->customer->order);
    free(node->customer);
    free(node);
}

double calculate_order_amount(Order *order) {
    double total = 0.0;
    for (size_t i = 0; i < order->num_items; ++i)
        total += order->items[i]->quantity;
    return total;
}

void read_and_parse_input(MemoryPool *pool, TreeNode **root) {
    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        // Parse input data into Customer, Order, and Item structures.
        // For simplicity, assuming a specific input format is used here:
        // id,name1:qty1,name2:qty2,...,nameN:qtyN

        char *id = strtok(line, ",");
        if (id == NULL) continue;

        char customer_id[CUSTOMER_NAME_LEN];
        strncpy(customer_id, id, CUSTOMER_NAME_LEN);
        customer_id[CUSTOMER_NAME_LEN - 1] = '\0';

        Customer *customer = (Customer*)allocate_from_pool(pool, sizeof(Customer));
        strcpy(customer->id, customer_id);

        Order *order = (Order*)allocate_from_pool(pool, sizeof(Order));
        size_t num_items = 0;
        Item **items = NULL;

        char *token = strtok(NULL, ",");
        while (token) {
            if (num_items == 0)
                items = (Item**)allocate_from_pool(pool, sizeof(Item*));

            int idx = num_items++;
            Item *item = (Item*)allocate_from_pool(pool, sizeof(Item));
            sscanf(token, "%[^:]:%d", item->name, &item->quantity);

            // Randomize quantity within a range for demonstration
            srand(time(NULL) ^ (intptr_t)item);
            item->quantity += rand() % 10;

            items[idx] = item;

            token = strtok(NULL, ",");
        }

        if (num_items > 0 && items != NULL) {
            order->items = items;
            order->num_items = num_items;
            order->amount = calculate_order_amount(order);
            customer->order = order;
        } else {
            free(order); // Order allocation failed
            continue;
        }

        insert_bst(root, customer);
    }
}

double calculate_average_highest_frequency_orders(MemoryPool *pool, TreeNode *root) {
    if (root == NULL)
        return 0.0;

    pthread_mutex_t order_amount_lock = PTHREAD_MUTEX_INITIALIZER;
    double total_sum = 0.0;
    int count = 0;

    void process_node(TreeNode *node) {
        double amount = node->customer->order ? node->customer->order->amount : 0;
        pthread_mutex_lock(&order_amount_lock);
        total_sum += amount;
        count++;
        pthread_mutex_unlock(&order_amount_lock);

        if (node->left)
            process_node(node->left);
        if (node->right)
            process_node(node->right);
    }

    process_node(root);
    pthread_mutex_destroy(&order_amount_lock);

    return count ? total_sum / count : 0.0;
}

int main() {
    MemoryPool memory_pool = create_memory_pool(MEMORY_POOL_SIZE);

    TreeNode *root = NULL;

    read_and_parse_input(&memory_pool, &root);

    double average_order_amount = calculate_average_highest_frequency_orders(&memory_pool, root);
    printf("Average order amount: %f\n", average_order_amount);

    free_tree(root);
    deallocate_memory_pool(&memory_pool);

    return 0;
}
