// Memory pool structure
typedef struct {
    void *pool;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;
    mp->pool = malloc(block_size * total_blocks);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_blocks < mp->total_blocks) {
        void *block = (char*)mp->pool + mp->used_blocks * mp->block_size;
        mp->used_blocks++;
        pthread_mutex_unlock(&mp->lock);
        return block;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

void memory_pool_free(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Logger for debugging and auditing
