    fprintf(logger->log_file, "%s\n", message);
    fflush(logger->log_file);
    pthread_mutex_unlock(&logger->log_lock);
}

void free_logger(Logger *logger) {
    fclose(logger->log_file);
    pthread_mutex_destroy(&logger->log_lock);
    free(logger);
}

// Data validation function
int validate_spatial_entity(const SpatialEntity *entity) {
    if (entity->point.x < 0 || entity->point.y < 0)
        return 0; // Invalid coordinates
    return 1;
}

// Compression and decompression functions
size_t compress_data(void *data, size_t data_size, void **compressed_data) {
    uLongf compressed_size = compressBound(data_size);
    *compressed_data = malloc(compressed_size);
    if (compress((Bytef*)*compressed_data, &compressed_size, (const Bytef*)data, data_size) != Z_OK)
        return 0;
    return compressed_size;
}

size_t decompress_data(void *compressed_data, size_t compressed_size, void **decompressed_data, size_t original_size) {
    *decompressed_data = malloc(original_size);
    if (uncompress((Bytef*)*decompressed_data, &original_size, (const Bytef*)compressed_data, compressed_size) != Z_OK)
        return 0;
    return original_size;
}

// Main function to manage spatial entities
void manage_spatial_entities(const char *csv_filename) {
    Logger *logger = create_logger("spatial_entities.log");
    MemoryPool *mp = create_memory_pool(sizeof(SpatialEntity), 10000);

    FILE *file = fopen(csv_filename, "r");
    if (!file) {
        log_message(logger, "Failed to open CSV file.");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        SpatialEntity *entity = memory_pool_alloc(mp);
        if (!entity) {
            log_message(logger, "Memory pool exhausted.");
            continue;
        }

        // Parse CSV line and populate entity
        sscanf(line, "%lf,%100[^,],%f,%f", &entity->number, entity->string, &entity->point.x, &entity->point.y);

        if (!validate_spatial_entity(entity)) {
            log_message(logger, "Invalid spatial entity encountered.");
            continue;
        }

        // Track entity lifecycle
        entity->id = rand(); // Example unique ID generation

        void *compressed_data;
        size_t compressed_size = compress_data(entity, sizeof(SpatialEntity), &compressed_data);
        if (compressed_size) {
            log_message(logger, "Data compressed successfully.");
        } else {
            log_message(logger, "Compression failed.");
        }

        // Example decompression
        void *decompressed_data;
        size_t original_size = decompress_data(compressed_data, compressed_size, &decompressed_data, sizeof(SpatialEntity));
        if (original_size) {
            log_message(logger, "Data decompressed successfully.");
        } else {
            log_message(logger, "Decompression failed.");
        }

        free(compressed_data);
    }

    fclose(file);
    memory_pool_free(mp);
    free_logger(logger);
}

int main() {
    manage_spatial_entities("spatial_data.csv");
    return 0;
}
