// Define the record structure
typedef struct {
    int value;
    float average;
    char status;
} Record;

// Memory pool definition
#define POOL_SIZE 1024 * 1024 // 1 MB

char memory_pool[POOL_SIZE];
size_t next_free = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Cache structure for managing reused allocations
typedef struct {
    void* ptr;
    size_t size;
} MemoryCacheEntry;

#define CACHE_MAX_ENTRIES 128
MemoryCacheEntry cache[CACHE_MAX_ENTRIES];
int cache_count = 0;
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_memory_event(const char *event, const char *details) {
#ifdef LOG_MEMORY_EVENTS
    printf("%s: %s\n", event, details);
#endif
}

// Memory allocation from pool with logging
void* pool_alloc(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (next_free + size > POOL_SIZE) {
        log_memory_event("Allocation failed", "Out of memory in the pool");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    void *allocated = &memory_pool[next_free];
    next_free += size;
    log_memory_event("Memory allocated", "From pool");
    pthread_mutex_unlock(&pool_mutex);
    return allocated;
}

// Memory deallocation to cache with logging
void pool_dealloc(void* ptr, size_t size) {
    pthread_mutex_lock(&cache_mutex);
    if (cache_count < CACHE_MAX_ENTRIES) {
        cache[cache_count].ptr = ptr;
        cache[cache_count].size = size;
        cache_count++;
    }
    log_memory_event("Memory deallocated", "To cache");
    pthread_mutex_unlock(&cache_mutex);
}

// Memory allocation with caching
void* cached_alloc(size_t size) {
    pthread_mutex_lock(&cache_mutex);
    for (int i = 0; i < cache_count; i++) {
        if (cache[i].size == size) {
            void *cached_ptr = cache[i].ptr;
            memmove(&cache[i], &cache[cache_count - 1], sizeof(MemoryCacheEntry));
            cache_count--;
            pthread_mutex_unlock(&cache_mutex);
            return cached_ptr;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    // If no suitable entry in cache, allocate from pool
    void *new_alloc = pool_alloc(size);
    if (new_alloc) {
        log_memory_event("Memory allocated", "From cache or pool");
    }
    return new_alloc;
}

void manage_large_data(int num_records, int offset_range_min, int offset_range_max, 
                       double multiplier, float threshold) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for arrays
    long *offsets = (long *) cached_alloc(num_records * sizeof(long));
    int *keys = (int *) cached_alloc(num_records * sizeof(int));
    double *data_values = (double *) cached_alloc(num_records * sizeof(double));

    if (!offsets || !keys || !data_values) {
        log_memory_event("Allocation failed", "One or more arrays");
        return;
    }

    // Allocate memory for records
    Record *records = (Record *) cached_alloc(num_records * sizeof(Record));
    if (!records) {
        log_memory_event("Allocation failed", "Records array");
        pool_dealloc(offsets, num_records * sizeof(long));
        pool_dealloc(keys, num_records * sizeof(int));
        pool_dealloc(data_values, num_records * sizeof(double));
        return;
    }

    // Initialize arrays and records
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (offset_range_max - offset_range_min + 1) + offset_range_min;

        keys[i] = rand() % 1000; // Random key between 0-999

        data_values[i] = ((double)keys[i]) * multiplier;

        records[i].value = keys[i];
        records[i].average = (float)data_values[i];
        records[i].status = (data_values[i] > threshold) ? 'S' : 'F';
    }

    // Free resources at the end
    pool_dealloc(offsets, num_records * sizeof(long));
    pool_dealloc(keys, num_records * sizeof(int));
    pool_dealloc(data_values, num_records * sizeof(double));
    pool_dealloc(records, num_records * sizeof(Record));

    pthread_mutex_destroy(&lock);
}

int main() {
    // Example usage
    manage_large_data(10000, 0, 1000, 1.5, 1500.0);

    return 0;
}
