#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <dlfcn.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t count;
    pthread_mutex_t lock;
    void **metrics;
    size_t metrics_count;
} data_pool;

static inline void log_message(const char *message) {
    // Dummy logger for demonstration
    printf("%s\n", message);
}

data_pool* create_data_pool(size_t record_count, int min_val, int max_val) {
    if (record_count == 0 || min_val > max_val) return NULL;

    data_pool *pool = malloc(sizeof(data_pool));
    if (!pool) goto error;

    pthread_mutex_init(&pool->lock, NULL);
    pool->count = record_count;
    pool->metrics = NULL;
    pool->metrics_count = 0;

    // Allocate memory for offsets and keys
    pool->offsets = calloc(record_count, sizeof(long));
    if (!pool->offsets) goto error;
    pool->keys = malloc(record_count * sizeof(int));
    if (!pool->keys) goto error;

    // Initialize records with random values
    pool->records = malloc(record_count * sizeof(record));
    if (!pool->records) goto error;

    for (size_t i = 0; i < record_count; ++i) {
        pool->records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    // Simulate dynamic metric discovery
    char *metrics[] = {"metric1", "metric2"};
    size_t metrics_to_load = sizeof(metrics) / sizeof(char*);

    pool->metrics = malloc(metrics_to_load * sizeof(void *));
    if (!pool->metrics) goto error;

    for (size_t i = 0; i < metrics_to_load; ++i) {
        void *handle = dlopen("libmetric.so", RTLD_LAZY);
        if (!handle) continue;

        typedef double (*metric_func)(void);
        metric_func func = dlsym(handle, metrics[i]);
        if (func) {
            pool->metrics[pool->metrics_count++] = func;
        }
        dlclose(handle);
    }

    return pool;

error:
    destroy_data_pool(pool);
    return NULL;
}

void destroy_data_pool(data_pool *pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->lock);

    free(pool->offsets);
    free(pool->keys);
    free(pool->records);

    for (size_t i = 0; i < pool->metrics_count; ++i) {
        free(pool->metrics[i]);
    }
    free(pool->metrics);

    free(pool);
}

double get_metric_value(void *metric_func_ptr, void *params) {
    if (!metric_func_ptr) return -1.0;

    typedef double (*metric_func)(void *);
    metric_func func = (metric_func)metric_func_ptr;
    return func(params);
}

// Example usage
int main() {
    srand((unsigned int)time(NULL));
    data_pool *pool = create_data_pool(10, 1, 100);

    if (!pool) {
        fprintf(stderr, "Failed to initialize data pool\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < pool->metrics_count; ++i) {
        pthread_mutex_lock(&pool->lock);
        double value = get_metric_value(pool->metrics[i], NULL);
        pthread_mutex_unlock(&pool->lock);

        printf("Metric %zu: %.2f\n", i, value);
    }

    destroy_data_pool(pool);
    return EXIT_SUCCESS;
}
```

