#define MAX_CACHE_SIZE 1024

typedef struct {
    time_t timestamp;
    unsigned long transaction_id;
    double amount;
    bool status; // true if successful, false otherwise
} Transaction;

typedef struct {
    void* memory;
    size_t size;
