import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicLong;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

// Custom memory allocator for efficient memory management
class MemoryAllocator {
    // Implementation details omitted
}

// Log metadata structure
class LogMetadata {
    String level;
    String source;
    Map<String, Object> contextInfo;

    public LogMetadata(String level, String source, Map<String, Object> contextInfo) {
        this.level = level;
        this.source = source;
        this.contextInfo = contextInfo;
    }
}

// Cache to store frequently accessed log metadata
class MetadataCache {
    private final ConcurrentHashMap<LogMetadata, Boolean> cache = new ConcurrentHashMap<>();
    private final int capacity;

    public MetadataCache(int capacity) {
        this.capacity = capacity;
    }

    public boolean put(LogMetadata metadata) {
        return cache.putIfAbsent(metadata, true) == null && cache.size() <= capacity;
    }
}

// Main log processing function
public class LogProcessor {

    private static final Logger logger = LogManager.getLogger(LogProcessor.class);
    private final MemoryAllocator allocator = new MemoryAllocator();
    private final ObjectMapper objectMapper = new ObjectMapper();
    private final CopyOnWriteArrayList<Long> timestamps = new CopyOnWriteArrayList<>();
    private final CopyOnWriteArrayList<String> messages = new CopyOnWriteArrayList<>();
    private final CopyOnWriteArrayList<LogMetadata> metadataList = new CopyOnWriteArrayList<>();
    private final MetadataCache cache = new MetadataCache(1000);
    private final AtomicLong totalProcessingTime = new AtomicLong();
    private final AtomicLong processedLogsCount = new AtomicLong();

    public void processLogEntry(String jsonLog) {
        long startTime = System.nanoTime();

        try {
            JsonNode logNode = objectMapper.readTree(jsonLog);

            if (!isValid(logNode)) {
                reportError("Invalid log structure", logNode);
                return;
            }

            String timestampStr = logNode.get("timestamp").asText();
            Long timestamp = Long.parseLong(timestampStr);
            timestamps.add(timestamp);

            String message = logNode.get("message").asText();
            messages.add(message);

            String level = logNode.get("level").asText();
            String source = logNode.get("source").asText();
            JsonNode contextInfo = logNode.get("context");

            Map<String, Object> contextMap = new HashMap<>();
            if (contextInfo != null) {
                for (JsonNode node : contextInfo) {
                    contextMap.put(node.fieldNames().next(), node.asText());
                }
            }

            LogMetadata metadata = new LogMetadata(level, source, contextMap);

            if (!cache.put(metadata)) {
                // Cache is full; handle eviction strategy here
            }

            metadataList.add(metadata);

        } catch (Exception e) {
            reportError("Failed to process log entry", jsonLog);
        } finally {
            long processingTime = System.nanoTime() - startTime;
            totalProcessingTime.addAndGet(processingTime);
            processedLogsCount.incrementAndGet();
        }
    }

    public double getAverageProcessingDuration() {
        return (double) totalProcessingTime.get() / processedLogsCount.get() / 1_000_000.0; // in milliseconds
    }

    private boolean isValid(JsonNode logNode) {
        try {
            String timestampStr = logNode.get("timestamp").asText();
            Long.parseLong(timestampStr);
            return logNode.has("message") && logNode.has("level") && logNode.has("source");
        } catch (Exception e) {
            return false;
        }
    }

    private void reportError(String errorMessage, String context) {
        logger.error(errorMessage + " | Context: " + context);
        // Integration with external logging service
    }

    public static void main(String[] args) {
        LogProcessor processor = new LogProcessor();

        // Simulate log processing in a high-throughput environment
        for (int i = 0; i < 1_000_000; i++) {
            String jsonLog = generateSampleLog(i);
            processor.processLogEntry(jsonLog);
        }

        System.out.println("Average Processing Duration: " + processor.getAverageProcessingDuration() + " ms");
    }

    private static String generateSampleLog(int index) {
        // Generate a sample log entry in JSON format
        return "{\"timestamp\":\"" + System.currentTimeMillis() + "\", \"message\":\"Sample message\", \"level\":\"INFO\", \"source\":\"System\"}";
    }
}
