#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

typedef struct {
    char* errorMessage;
    int errorCode;
    void* additionalContext;
} Status;

// Custom memory pool management structure
typedef struct {
    size_t blockSize;
    size_t blockCount;
    unsigned char* data;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t blockCount) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    pool->blockCount = blockCount;
    pool->data = malloc(blockSize * blockCount);
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void freeMemoryPool(MemoryPool* pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->data);
        free(pool);
    }
}

void* allocateFromPool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (!pool || size > pool->blockSize * pool->blockCount)
        pthread_mutex_unlock(&pool->lock), return NULL;

    void* block = pool->data;
    pool->data += size;

    pthread_mutex_unlock(&pool->lock);
    return block;
}

unsigned long hashFunction(unsigned long timestamp, unsigned int seed) {
    // Simple hash function for demonstration
    return (timestamp ^ seed) & 0xFFFFFFFF;
}

char* generateIdentifier(MemoryPool* pool, unsigned long timestamp) {
    unsigned int randomSeed = rand();
    unsigned long hash = hashFunction(timestamp, randomSeed);
    char* identifier = allocateFromPool(pool, sizeof(char) * (20 + 1));
    snprintf(identifier, 21, "%lx-%u", hash, randomSeed);
    return identifier;
}

void initializeArrays(unsigned long** timestamps, char*** buffers,
                      float** values, Status** statuses, size_t n, MemoryPool* pool) {
    *timestamps = malloc(n * sizeof(unsigned long));
    *buffers = malloc(n * sizeof(char*));
    *values = malloc(n * sizeof(float));
    *statuses = malloc(n * sizeof(Status));

    for (size_t i = 0; i < n; ++i) {
        (*timestamps)[i] = time(NULL);
        (*buffers)[i] = generateIdentifier(pool, (*timestamps)[i]);

        (*values)[i] = 0.0f;
        (*statuses)[i].errorMessage = strdup("");
        (*statuses)[i].errorCode = 0;
        (*statuses)[i].additionalContext = NULL;
    }
}

void freeResources(unsigned long* timestamps, char** buffers,
                   float* values, Status* statuses, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        free(buffers[i]);
        free(statuses[i].errorMessage);
    }

    free(timestamps);
    free(buffers);
    free(values);
    free(statuses);
}

void readInput(float* values, char*** strings, unsigned long* timestamps,
               size_t* numFloats, size_t* numStrings, size_t* numTimestamps) {
    float temp;
    char buffer[256];

    *numFloats = 0;
    *numStrings = 0;
    *numTimestamps = 0;

    while (scanf("%f", &temp) == 1 || fgets(buffer, sizeof(buffer), stdin)) {
        if (*buffer != '\n') {  // String input
            buffer[strcspn(buffer, "\n")] = '\0';
            ++*numStrings;
        } else { // Float input
            ++*numFloats;
        }
    }

    *values = malloc(*numFloats * sizeof(float));
    *strings = malloc(*numStrings * sizeof(char*));
    *timestamps = malloc(*numTimestamps * sizeof(unsigned long));

    rewind(stdin);  // Reset stdin for re-reading

    size_t i = 0;
    while (scanf("%f", &temp) == 1 || fgets(buffer, sizeof(buffer), stdin)) {
        if (*buffer != '\n') {  // String input
            buffer[strcspn(buffer, "\n")] = '\0';
            (*strings)[i++] = strdup(buffer);
        } else { // Float input
            (*values)[i - *numStrings] = temp;
        }
    }
}

void findMostFrequentString(char** strings, size_t numStrings) {
    if (numStrings == 0) return;

    int maxCount = 0;
    char* mostFrequent = NULL;

    for (size_t i = 0; i < numStrings; ++i) {
        int count = 1;
        for (size_t j = i + 1; j < numStrings; ++j) {
            if (strcmp(strings[i], strings[j]) == 0) {
                ++count;
            }
        }

        if (count > maxCount) {
            maxCount = count;
            mostFrequent = strings[i];
        }
    }

    printf("Most frequent string: %s\n", mostFrequent);
}

void calculateAverageFloat(float* values, size_t numValues) {
    if (numValues == 0) return;

    float sum = 0.0f;
    for (size_t i = 0; i < numValues; ++i) {
        sum += values[i];
    }

    printf("Average float value: %f\n", sum / numValues);
}

void findLatestTimestamp(unsigned long* timestamps, size_t numTimestamps) {
    if (numTimestamps == 0) return;

    unsigned long latest = timestamps[0];

    for (size_t i = 1; i < numTimestamps; ++i) {
        if (timestamps[i] > latest) {
            latest = timestamps[i];
        }
    }

    printf("Latest timestamp: %lu\n", latest);
}

int main() {
    size_t numFloats, numStrings, numTimestamps;

    readInput(NULL, NULL, NULL, &numFloats, &numStrings, &numTimestamps);

    MemoryPool* pool = createMemoryPool(1024 * 1024, 10); // Example block size and count

    unsigned long* timestamps;
    char** buffers;
    float* values;
    Status* statuses;

    initializeArrays(&timestamps, &buffers, &values, &statuses,
                     numFloats + numStrings + numTimestamps, pool);

    readInput(values, NULL, timestamps, &numFloats, &numStrings, &numTimestamps);

    findMostFrequentString(buffers, numStrings);
    calculateAverageFloat(values, numFloats);
    findLatestTimestamp(timestamps, numTimestamps);

    freeResources(timestamps, buffers, values, statuses, numFloats + numStrings + numTimestamps);
    freeMemoryPool(pool);

    return 0;
}
