using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net.Http;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

public class HtmlContentController : ControllerBase
{
    private readonly IRateLimiter _rateLimiter;
    private readonly IHtmlValidator _htmlValidator;
    private readonly IElementService _elementService;
    private readonly ILogger<HtmlContentController> _logger;
    private readonly IConfiguration _configuration;
    private static readonly ConcurrentDictionary<string, DateTime> LastUpdatedCache = new();

    public HtmlContentController(IRateLimiter rateLimiter,
                                 IHtmlValidator htmlValidator,
                                 IElementService elementService,
                                 ILogger<HtmlContentController> logger,
                                 IConfiguration configuration)
    {
        _rateLimiter = rateLimiter;
        _htmlValidator = htmlValidator;
        _elementService = elementService;
        _logger = logger;
        _configuration = configuration;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElement(
        string pageSectionId,
        string elementId,
        string htmlContent,
        string version = null)
    {
        var userId = User.Identity?.Name ?? "Anonymous";
        var ipAddress = HttpContext.Connection.RemoteIpAddress.ToString();

        // Rate Limiting
        if (!_rateLimiter.IsRequestAllowed(ipAddress))
        {
            _logger.LogWarning($"Rate limit exceeded for IP: {ipAddress}");
            return StatusCode(429, "Too Many Requests");
        }

        // Validate HTML content
        var validationResult = _htmlValidator.Validate(htmlContent);
        if (!validationResult.IsValid)
        {
            _logger.LogError($"Invalid HTML content from IP: {ipAddress} User: {userId}. Error: {validationResult.ErrorMessage}");
            return BadRequest(validationResult.ErrorMessage);
        }

        // Trusted Domain Check
        var requestingDomain = HttpContext.Request.Headers["Host"].ToString();
        if (!_configuration.GetTrustedDomains().Contains(requestingDomain))
        {
            _logger.LogError($"Untrusted domain attempt from: {requestingDomain} IP: {ipAddress}");
            return Unauthorized("Access denied.");
        }

        // Lock handling for concurrent updates
        using (var updateLock = new ConcurrentDictionary<string, object>().GetOrAdd(elementId, new object()))
        {
            lock (updateLock)
            {
                try
                {
                    var success = _elementService.TryUpdateElement(pageSectionId, elementId, htmlContent, version);

                    if (!success && LastUpdatedCache.TryGetValue(elementId, out var lastUpdated))
                    {
                        return Conflict("Concurrent update conflict. Please retry.");
                    }

                    // Set or reset the timestamp on successful update
                    LastUpdatedCache[elementId] = DateTime.UtcNow;
                }
                catch (Exception ex)
                {
                    _logger.LogError($"Failed to update element {elementId} by User: {userId}, IP: {ipAddress}. Error: {ex.Message}");
                    return StatusCode(500, "Internal Server Error");
                }
            }
        }

        // Prepare response
        var lastUpdated = LastUpdatedCache[elementId];
        Response.Headers.Add("Content-Last-Updated", lastUpdated.ToString("o"));
        Response.Headers.Add("Cache-Control", "no-cache");

        _logger.LogInformation($"Element {elementId} updated successfully by User: {userId}, IP: {ipAddress}");
        return Ok(new { message = "Page should be refreshed" });
    }
}

public interface IRateLimiter
{
    bool IsRequestAllowed(string ipAddress);
}

public interface IHtmlValidator
{
    ValidationResult Validate(string htmlContent);
}

public interface IElementService
{
    bool TryUpdateElement(string pageSectionId, string elementId, string htmlContent, string version = null);
}

public class ValidationResult
{
    public bool IsValid { get; set; }
    public string ErrorMessage { get; set; }
}
