```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <sys/types.h>
#include <unistd.h>

#define BLOCK_SIZE 1024 // Size of each block in the memory pool

typedef struct MemoryBlock {
    size_t size;
    int free;
    void *ptr;
    struct MemoryBlock *next;
} MemoryBlock;

typedef struct {
    void *pool;
    size_t total_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->total_size = size;
    mp->pool = malloc(size);
    if (!mp->pool) return NULL;

    mp->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    ((MemoryBlock*)mp->pool)->size = size - sizeof(MemoryBlock);
    ((MemoryBlock*)mp->pool)->free = 1;
    ((MemoryBlock*)mp->pool)->next = NULL;
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);

    MemoryBlock *current = (MemoryBlock *)mp->pool;
    while (current != NULL) {
        if (current->free && current->size >= size) {
            current->free = 0;
            pthread_mutex_unlock(&mp->lock);
            return (void*)(++current);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mp->lock);
    return NULL; // No suitable block found
}

void memory_pool_free(MemoryPool *mp, void *ptr) {
    if (!ptr) return;

    MemoryBlock *block_ptr = (MemoryBlock*)ptr - 1;
    pthread_mutex_lock(&mp->lock);

    block_ptr->free = 1;
    pthread_mutex_unlock(&mp->lock);
}

void process_directory(const char *dir_path, MemoryPool *pool) {
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(dir_path)) == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char *file_name = entry->d_name;
            size_t name_len = strlen(file_name);

            // Generate unique identifier based on character frequency
            int freq[256] = {0};
            for (size_t i = 0; i < name_len; ++i)
                freq[(unsigned char)file_name[i]]++;

            char id_str[10];
            snprintf(id_str, sizeof(id_str), "%d", freq[(unsigned char)file_name[name_len - 1]]);

            // Allocate memory for the new file path
            size_t new_path_size = name_len + strlen(id_str) + 2; // Include '/' and null-terminator
            char *new_file_path = (char *)memory_pool_alloc(pool, new_path_size);
            if (!new_file_path) {
                fprintf(stderr, "Memory allocation failed for file path\n");
                continue;
            }

            snprintf(new_file_path, new_path_size, "%s/%s%s", dir_path, file_name, id_str);
            printf("Processing file: %s\n", new_file_path);

            // Simulate processing
            sleep(1);

            memory_pool_free(pool, new_file_path);
        }
    }

    closedir(dir);
}

void* read_numbers(void *arg) {
    int *int_array = (int *)malloc(100 * sizeof(int));
    float *float_array = (float *)malloc(100 * sizeof(float));
    int int_count = 0, float_count = 0;

    int num;
    while (scanf("%d", &num) == 1) {
        if (int_count < 100)
            int_array[int_count++] = num;
    }

    rewind(stdin);

    float fnum;
    while (scanf("%f", &fnum) == 1) {
        if (float_count < 100)
            float_array[float_count++] = fnum;
    }

    int max_int = int_array[0];
    for (int i = 1; i < int_count; ++i)
        if (int_array[i] > max_int)
            max_int = int_array[i];

    float min_float = float_array[0];
    for (int i = 1; i < float_count; ++i)
        if (float_array[i] < min_float)
            min_float = float_array[i];

    printf("Max Integer: %d\n", max_int);
    printf("Min Float: %.2f\n", min_float);

    free(int_array);
    free(float_array);

    return NULL;
}

int main() {
    MemoryPool *pool = create_memory_pool(1024 * 1024); // 1MB pool
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, read_numbers, NULL)) {
            perror("pthread_create");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    process_directory(".", pool);

    free(pool->pool);
    free(pool);

    return EXIT_SUCCESS;
}
