#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

#define POOL_SIZE 1024

typedef struct {
    int key;
    long offset;
    char* identifier;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    _Atomic size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Initialize a new memory pool
void init_pool() {
    pthread_mutex_lock(&pool.lock);
    pool.head = NULL;
    pool.count = 0;
    pthread_mutex_unlock(&pool.lock);
}

// Free the entire memory pool
void free_pool() {
    Node* current = pool.head;
    while (current) {
        Node* next = current->next;
        free(current->record.identifier);
        free(current);
        current = next;
    }
    pthread_mutex_lock(&pool.lock);
    pool.head = NULL;
    pool.count = 0;
    pthread_mutex_unlock(&pool.lock);
}

// Allocate a record from the memory pool
Node* allocate_record(int key, long offset) {
    Node* node = NULL;

    pthread_mutex_lock(&pool.lock);
    if (pool.head != NULL) {
        node = pool.head;
        pool.head = node->next;
        pool.count--;
    }
    pthread_mutex_unlock(&pool.lock);

    if (!node) {
        node = malloc(sizeof(Node));
        if (!node) return NULL; // Allocation failed
    }

    node->record.key = key;
    node->record.offset = offset;

    char* id_str = malloc(20); // Enough space for long
    if (!id_str) {
        free(node);
        return NULL; // Allocation failed
    }
    snprintf(id_str, 20, "%ld", offset);
    node->record.identifier = id_str;

    node->next = NULL;
    return node;
}

// Free a record back to the memory pool
void deallocate_record(Node* node) {
    pthread_mutex_lock(&pool.lock);
    node->next = pool.head;
    pool.head = node;
    pool.count++;
    pthread_mutex_unlock(&pool.lock);
}

// Add or update a record by key
Node* add_or_update_record(int key, long min_offset, long max_offset) {
    long offset = rand() % (max_offset - min_offset + 1) + min_offset;
    Node* new_node = allocate_record(key, offset);

    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for record.\n");
        return NULL;
    }

    pthread_mutex_lock(&pool.lock);

    Node* current = pool.head;
    while (current != NULL) {
        if (current->record.key == key) {
            deallocate_record(current);
            break;
        }
        current = current->next;
    }

    new_node->next = pool.head;
    pool.head = new_node;

    pthread_mutex_unlock(&pool.lock);

    return new_node;
}

// Retrieve a record by key
Node* get_record(int key) {
    pthread_mutex_lock(&pool.lock);

    Node* current = pool.head;
    while (current != NULL) {
        if (current->record.key == key) {
            pthread_mutex_unlock(&pool.lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool.lock);
    return NULL;
}

// Main function to demonstrate usage
int main() {
    init_pool();

    add_or_update_record(1, 0, 100000);
    add_or_update_record(2, 0, 100000);

    Node* record = get_record(1);
    if (record) {
        printf("Key: %d, Offset: %ld, Identifier: %s\n", 
               record->record.key, 
               record->record.offset,
               record->record.identifier);
    }

    free_pool();
    return 0;
}
```

This code provides a basic implementation of a memory pooling mechanism and thread-safe operations for managing records in C. It initializes a collection of records with unique identifiers and random offset values within specified ranges, while allowing concurrent access using mutex locks. The `MemoryPool` structure facilitates reusing allocated nodes to minimize dynamic allocation overhead. Each record consists of an integer key, a long offset value, and a string identifier dynamically generated based on the offset. The code includes functions for adding or updating records, retrieving them by key, and managing memory efficiently with proper cleanup routines.']

