void* allocate_and_initialize(size_t n, size_t m, int interval) {
    if (n <= 0 || m <= 0 || interval > MAX_INTERVAL) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    pthread_mutex_lock(&init_mutex);

    // Step 1 & 2: Allocate and initialize the size_t array
    size_t *data_sizes = malloc(n * sizeof(size_t));
    if (!data_sizes) {
        perror("Failed to allocate memory for data sizes");
        pthread_mutex_unlock(&init_mutex);
        return NULL;
    }
    for (size_t i = 0; i < n; ++i) {
        data_sizes[i] = (i + 1) * 1024; // Initialize with sequential values starting from 1 KB
    }

    // Step 3: Allocate and initialize the timestamp_t array
    time_t *timestamps = malloc(n * sizeof(time_t));
    if (!timestamps) {
        perror("Failed to allocate memory for timestamps");
        free(data_sizes);
        pthread_mutex_unlock(&init_mutex);
        return NULL;
    }
    time_t current_time = time(NULL); // Get current time once to minimize overhead
    for (size_t i = 0; i < n; ++i) {
        timestamps[i] = current_time;
    }

    // Step 4: Allocate and initialize the file_info array
    file_info *files = malloc(m * sizeof(file_info));
    if (!files) {
        perror("Failed to allocate memory for file info");
        free(data_sizes);
        free(timestamps);
        pthread_mutex_unlock(&init_mutex);
        return NULL;
    }

    // Step 5: Set each file_info's timestamp_t field
    current_time = time(NULL); // Get current time again
    for (size_t i = 0; i < m; ++i) {
        files[i].timestamp = current_time + interval;
    }

    pthread_mutex_unlock(&init_mutex);

    // Step 7: Monitor and manage memory usage dynamically
    // In a real-world scenario, you would add logic here to monitor and adjust as needed

    return (void*)files; // Return the file_info array for further processing
}

void free_resources(void *resources) {
    if (resources) {
        free(resources);
    }
}

int main() {
    size_t n = 10;
    size_t m = 5;
    int interval = 100;

    void* result = allocate_and_initialize(n, m, interval);

    if (result) {
        // Use the allocated resources
