#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Custom random number generator (LCG - Linear Congruential Generator)
typedef struct {
    uint32_t state;
} RNG;

void rng_init(RNG *rng, uint32_t seed) {
    rng->state = seed ? seed : 1; // Ensure non-zero
}

uint8_t rng_random(RNG *rng) {
    const uint32_t a = 1664525U;
    const uint32_t c = 1013904223U;
    rng->state = (a * rng->state + c);
    return (uint8_t)(rng->state >> 24);
}

typedef struct {
    int key;
    int offset;
} Record;

// Memory pool structure
typedef struct {
    size_t block_size;
    void **free_list;
    size_t list_size;
    pthread_mutex_t lock;
} MemPool;

void mempool_init(MemPool *pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->list_size = 0;

    // Allocate memory for the free list
    pool->free_list = malloc(num_blocks * sizeof(void *));
    if (!pool->free_list) {
        perror("Failed to allocate free list");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&pool->lock, NULL);

    // Preallocate blocks and add them to the free list
    for (size_t i = 0; i < num_blocks; ++i) {
        void *block = malloc(block_size);
        if (!block) {
            perror("Failed to allocate memory block");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&pool->lock);
        pool->free_list[pool->list_size++] = block;
        pthread_mutex_unlock(&pool->lock);
    }
}

void *mempool_alloc(MemPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->list_size > 0) {
        void **block_ptr = &pool->free_list[pool->list_size - 1];
        void *block = *block_ptr;
        pool->list_size--;

        pthread_mutex_unlock(&pool->lock);
        return block;
    }

    pthread_mutex_unlock(&pool->lock);

    // Allocate a new block if none are available in the free list
    return malloc(pool->block_size);
}

void mempool_free(MemPool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);

    pool->free_list[pool->list_size++] = ptr;

    pthread_mutex_unlock(&pool->lock);
}

void manage_memory(int n, int m, int min_offset, int max_offset) {
    if (n <= 0 || m <= 0 || min_offset > max_offset || min_offset < 0 || max_offset < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Simulate system-defined limit for demonstration purposes
    const int SYSTEM_LIMIT = 1024;

    MemPool pool;
    mempool_init(&pool, sizeof(Record), 128); // Initialize memory pool with block size of Record

    int adjusted_n = (n > SYSTEM_LIMIT) ? SYSTEM_LIMIT : n; 
    int *offsets = malloc(adjusted_n * sizeof(int));
    if (!offsets) {
        perror("Failed to allocate offsets array");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < adjusted_n; ++i) {
        offsets[i] = i;
    }

    int *keys = malloc(adjusted_n * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate keys array");
        exit(EXIT_FAILURE);
    }

    RNG rng;
    rng_init(&rng, 42); // Seed for reproducibility

    for (int i = 0; i < adjusted_n; ++i) {
        keys[i] = rng_random(&rng);
    }

    Record *records = malloc(m * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate records array");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < m; ++i) {
        records[i].key = keys[i % adjusted_n]; // Cycle through keys
        records[i].offset = min_offset + rng_random(&rng) % (max_offset - min_offset + 1); // Random within range
    }

    // Free memory and cleanup
    free(offsets);
    free(keys);
    for (int i = 0; i < m; ++i) {
        mempool_free(&pool, &records[i]); // Return each record block to the pool
    }
    free(records); // This is not technically needed as blocks are individually freed

    // Free memory pool resources
    for (size_t i = 0; i < pool.list_size; ++i) {
        free(pool.free_list[i]);
    }
    free(pool.free_list);
    pthread_mutex_destroy(&pool.lock);
}

int main() {
    manage_memory(100, 50, 10, 20); // Example usage
    return 0;
}
```

