```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the Metadata struct as per requirements
struct Metadata {
    const char* sourceInfo;
};

int processStringWithComplexConstraints(const char* str, int sizeLimit, char** result, bool allowTruncation, struct Metadata* metadata) {
    if (str == NULL || result == NULL || metadata == NULL) {
        return -1;
    }

    int originalLength = strlen(str);
    int requiredSize;

    if (originalLength + 1 <= sizeLimit) { // +1 for the '/'
        requiredSize = originalLength + 2; // +1 for '\0' and +1 for '/'
    } else {
        if (!allowTruncation) {
            *result = NULL;
            return -1;
        }
        requiredSize = sizeLimit > 1 ? sizeLimit : 2; // Ensure space for '/' and '\0'
    }

    char* buffer = (char*)malloc(requiredSize);
    if (buffer == NULL) {
        return -1;
    }

    int copyLength = originalLength < sizeLimit ? originalLength : sizeLimit - 2; // Reserve space for '/' and '\0'

    strncpy(buffer, str, copyLength);
    buffer[copyLength] = '/';
    buffer[copyLength + 1] = '\0';

    if (originalLength > sizeLimit && allowTruncation) {
        strcat(buffer, " [TRUNCATED: ");
        strcat(buffer, metadata->sourceInfo);
        strcat(buffer, "]");
    }

    *result = buffer;
    return 0;
}
```

