    void *configData;
    size_t dataSize;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    size_t capacity;
    pthread_mutex_t lock;
} LRUCache;

LRUCache cache = {0};

void initCache(size_t capacity) {
    cache.capacity = capacity;
    cache.head = cache.tail = NULL;
    pthread_mutex_init(&cache.lock, NULL);
}

void* loadConfig(const char *filename) {
