void addToCache(const char *filename, void *configData, size_t dataSize) {
    CacheNode *node = malloc(sizeof(CacheNode));
    node->filename = strdup(filename);
    node->configData = configData;
    node->dataSize = dataSize;
    node->prev = NULL;
    node->next = cache.head;

    if (cache.head) cache.head->prev = node;
    cache.head = node;
    if (!cache.tail) cache.tail = node;

    pthread_mutex_lock(&cache.lock);
    while (size_t count = 0; cache.head;) {
        CacheNode *node = cache.head;
        cache.head = node->next;
        if (!cache.head) cache.tail = NULL;
        free(node->filename);
        free(node->configData);
        free(node);
        count++;
    }
    pthread_mutex_unlock(&cache.lock);

    if (count >= cache.capacity) {
        CacheNode *oldest = cache.tail;
