 * @param keysSize Size of the int keys array.
 * @param recordsSize Size of the record array.
 * @param minValue Minimum value for random number generation.
 * @param maxValue Maximum value for random number generation.
 * @param maxMemoryLimit User-defined maximum memory limit in bytes.
 *
 * @return Error code indicating success or failure.
 */
int initializeData(long offsetsSize, int keysSize, int recordsSize,
                   int minValue, int maxValue, size_t maxMemoryLimit) {
    // Calculate required memory
    size_t offsetArraySize = sizeof(long) * offsetsSize;
    size_t keyArraySize = sizeof(int) * keysSize;
    size_t recordArraySize = sizeof(record) * recordsSize;

    // Total memory required
    size_t totalRequiredMemory = offsetArraySize + keyArraySize + recordArraySize;

    if (getCurrentMemoryUsage() + totalRequiredMemory > maxMemoryLimit) {
        enforceMemoryLimit(maxMemoryLimit);
        return MEM_LIMIT_EXCEEDED;
    }

    // Allocate and initialize arrays with error checks
    long *offsets = (long *)aligned_alloc(16, offsetArraySize);
    int *keys = (int *)aligned_alloc(16, keyArraySize);
    record *records = (record *)aligned_alloc(16, recordArraySize);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return MEM_ALLOC_FAIL;
    }

    // Initialize arrays
    memset(offsets, 0, offsetArraySize);
    memset(keys, 0, keyArraySize);

    // Seed random number generator for predictable distribution
    srand((unsigned int)time(NULL));

    // Populate records array with random values
    for (int i = 0; i < recordsSize; ++i) {
