    printf("Memory allocated: %zu bytes\n", size);
}

// Function to initialize records with random and key values
Record* allocate_records(int array_size, int min_value, int max_value, const int* keys, int num_keys) {
    if (array_size <= 0 || min_value > max_value || keys == NULL || num_keys < array_size) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    Record *records = (Record*)malloc(array_size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    log_memory_usage(array_size * sizeof(Record));

    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < array_size; ++i) {
        records[i].field1 = rand() % (max_value - min_value + 1) + min_value;
        if (i < num_keys) {
            records[i].field2 = keys[i];
        } else {
            fprintf(stderr, "Insufficient key values provided for record initialization.\n");
            free(records);
            return NULL;
        }
    }

    return records;
}

// Function to reset all records to zero
void reset_records(Record *records, int array_size) {
    if (!records) return;

    for (int i = 0; i < array_size; ++i) {
        records[i].field1 = 0;
        records[i].field2 = 0;
    }
}

// Function to free allocated memory
void free_records(Record *records) {
    if (records) {
        free(records);
        log_memory_usage(0); // Log zero allocation when freeing memory
    }
}

