#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *name;
    int value;
    long id; // Unique identifier
    time_t last_accessed;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} RecordList;

RecordList* create_record_list() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_node(Node* node) {
    free(node->record.name);
    free(node);
}

void clear_record_list(RecordList* list) {
    Node *current, *next;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current) {
        next = current->next;
        destroy_node(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}

void free_record_list(RecordList* list) {
    clear_record_list(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_record(RecordList* list, const char* name, int value, long id) {
    if (!name || strlen(name) == 0) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->record.name = strdup(name);
    new_node->record.value = value;
    new_node->record.id = id;
    new_node->record.last_accessed = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

Record* get_record(RecordList* list, long id) {
    Node *current;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current) {
        if (current->record.id == id) {
            current->record.last_accessed = time(NULL); // Update last accessed
            pthread_mutex_unlock(&list->lock);
            return &current->record;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int update_record_value(RecordList* list, long id, int new_value) {
    Node *current;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current) {
        if (current->record.id == id) {
            current->record.value = new_value;
            current->record.last_accessed = time(NULL); // Update last accessed
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

void iterate_and_print(RecordList* list) {
    Node *current;
    pthread_mutex_lock(&list->lock);
    current = list->head;
    while (current) {
        printf("ID: %ld, Name: %s, Value: %d\n", 
               current->record.id,
               current->record.name,
               current->record.value);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void cleanup_unused_records(RecordList* list) {
    time_t now = time(NULL);
    Node *current, **tracer;
    pthread_mutex_lock(&list->lock);

    tracer = &list->head;
    while (*tracer) {
        current = *tracer;
        if (difftime(now, current->record.last_accessed) > 30*24*60*60) { // 30 days
            *tracer = current->next; // Remove the node from list
            destroy_node(current);
            list->count--;
        } else {
            tracer = &current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Sample usage in a threaded context
void* record_manager_thread(void* arg) {
    RecordList *record_list = (RecordList*)arg;

    // Example operations, real implementation should handle external data source and periodic tasks

    add_record(record_list, "Sample Record 1", 42, 1);
    sleep(2); // Simulate time passing
    update_record_value(record_list, 1, 100);

    iterate_and_print(record_list);

    cleanup_unused_records(record_list); // This would be run periodically in practice

    free_record_list(record_list);
    return NULL;
}

int main() {
    RecordList* record_list = create_record_list();
    pthread_t thread_id;

    if (record_list) {
        pthread_create(&thread_id, NULL, record_manager_thread, (void*)record_list);

        // Wait for the thread to finish
        pthread_join(thread_id, NULL);
    }

    return 0;
}
