#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the Record structure
typedef struct {
    char* string;
    int value;
} Record;

// Node for linked list to manage records
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Dynamic List structure
typedef struct {
    Node* head;
    size_t size;
} RecordList;

// Memory pool manager interface (stub)
void* memory_pool_alloc(size_t size, const char* subsystem);
void memory_pool_free(void* ptr, const char* subsystem);

// Function to create a new record list
RecordList* create_record_list() {
    RecordList* list = (RecordList*)memory_pool_alloc(sizeof(RecordList), "RecordListPool");
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    return list;
}

// Function to add a new record
int add_record(RecordList* list, const char* str, int value) {
    if (!list || !str) return -1;

    Node* new_node = (Node*)memory_pool_alloc(sizeof(Node), "ListNodePool");
    if (!new_node) return -1;

    // Allocate and copy string
    size_t len = strlen(str) + 1;
    char* copied_str = (char*)memory_pool_alloc(len, "StringPool");
    if (!copied_str) {
        memory_pool_free(new_node, "ListNodePool");
        return -1;
    }
    memcpy(copied_str, str, len);

    // Set record data
    new_node->record.string = copied_str;
    new_node->record.value = value;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    return 0;
}

// Function to remove a record by index
int remove_record(RecordList* list, size_t index) {
    if (!list || index >= list->size) return -1;

    Node *prev = NULL, *current = list->head;
    for (size_t i = 0; i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    memory_pool_free(current->record.string, "StringPool");
    memory_pool_free(current, "ListNodePool");
    list->size--;

    return 0;
}

// Function to clear the record list
void clear_record_list(RecordList* list) {
    if (!list) return;

    Node *current = list->head, *next;
    while (current) {
        next = current->next;
        memory_pool_free(current->record.string, "StringPool");
        memory_pool_free(current, "ListNodePool");
        current = next;
    }
    list->head = NULL;
    list->size = 0;
}

// Function to free the record list
void destroy_record_list(RecordList* list) {
    if (!list) return;

    clear_record_list(list);
    memory_pool_free(list, "RecordListPool");
}

// Example usage
int main() {
    RecordList* list = create_record_list();
    add_record(list, "Hello", 1);
    add_record(list, "World", 2);

    remove_record(list, 0);
    clear_record_list(list);
    destroy_record_list(list);

    return 0;
}
```

### Key Points:
- **Memory Management**: Uses a memory pool manager to allocate and free memory, ensuring efficient use of resources.
- **Performance**: Minimizes allocations by using linked lists for dynamic resizing.
- **Data Integrity**: Ensures all allocated strings are freed when records are removed or the list is cleared.
- **Maintainability**: Modular design with clear function separation for creating, adding, removing, clearing, and destroying the list.']

