        }

        snprintf(data_points[i].char_buffer, 20, "ID_%d", i); // Unique identifier
        pthread_mutex_unlock(&buffer_update_mutex[i % 100]);
    }

    // Check memory usage after allocation
    pthread_mutex_lock(&memory_check_mutex);
    if (getCurrentMemoryUsage() > max_memory) {
        for (int i = 0; i < size_data_points; ++i)
            free(data_points[i].char_buffer);

        free(data_points);
        free(array_doubles);
        free(array_shorts);
        pthread_mutex_unlock(&memory_check_mutex);
        return MEMORY_LIMIT_EXCEEDED;
    }
    pthread_mutex_unlock(&memory_check_mutex);

    // Enforce memory limit
    if (enforceMemoryLimit(max_memory) != 0) {
        for (int i = 0; i < size_data_points; ++i)
            free(data_points[i].char_buffer);

        free(data_points);
        free(array_doubles);
        free(array_shorts);
        return MEMORY_LIMIT_EXCEEDED;
    }

