#include <stdlib.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define a record structure
typedef struct {
    int value;
} record;

// Error codes
#define SUCCESS 0
#define MEM_ALLOC_FAILED -1
#define EXCEEDED_MEMORY_LIMIT -2

// Function to allocate and initialize arrays for long offsets, int keys, and records
int allocate_and_initialize(
    size_t num_offsets, 
    size_t num_keys,
    size_t num_records,
    long *offsets,
    int *keys,
    record **records,
    size_t max_memory_limit,
    int min_value, 
    int max_value,
    void (*external_mem_monitor)(size_t used_memory)) {

    // Calculate required memory
    size_t offset_size = num_offsets * sizeof(long);
    size_t key_size = num_keys * sizeof(int);
    size_t record_size = num_records * sizeof(record);

    // Total required memory with alignment and padding considered
    size_t total_required_memory = align_to_cache_line(offset_size) + 
                                   align_to_cache_line(key_size) + 
                                   align_to_cache_line(record_size);

    // Check against the maximum memory limit
    if (total_required_memory > max_memory_limit) {
        return EXCEEDED_MEMORY_LIMIT;
    }

    // Allocate memory for offsets and keys with alignment
    void *aligned_offsets = aligned_alloc(alignof(long), offset_size);
    void *aligned_keys = aligned_alloc(alignof(int), key_size);

    if (!aligned_offsets || !aligned_keys) {
        free(aligned_offsets);
        free(aligned_keys);
        return MEM_ALLOC_FAILED;
    }

    offsets = (long *)aligned_offsets;
    keys = (int *)aligned_keys;

    // Initialize offsets and keys
    memset(offsets, 0, offset_size);
    memset(keys, 0, key_size);

    // Allocate memory for records
    *records = malloc(record_size);
    if (!(*records)) {
        free(aligned_offsets);
        free(aligned_keys);
        return MEM_ALLOC_FAILED;
    }

    // Initialize record array
    memset(*records, 0, record_size);

    // Set random values in records' int fields
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    // Update external memory monitor, if provided
    if (external_mem_monitor) {
        size_t used_memory = total_required_memory;
        external_mem_monitor(used_memory);
    }

    return SUCCESS;

}

// Helper function to align sizes to cache line boundaries for optimization
size_t align_to_cache_line(size_t size) {
    const size_t cache_line_size = 64; // Common cache line size in bytes
    return (size + (cache_line_size - 1)) & ~(cache_line_size - 1);
}

// Example external memory monitor function
void example_external_mem_monitor(size_t used_memory) {
    printf("Memory Used: %zu bytes\n", used_memory);
}
