#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Structure to hold a record
typedef struct {
    int unique_id;
    char *unique_identifier; // Pointer to dynamically allocated string
} Record;

// Global mutex for thread safety during memory operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
Record* create_records(int num_records, const char* static_key);
void free_records(Record* records, int num_records);

Record* create_records(int num_records, const char* static_key) {
    if (num_records <= 0 || !static_key) return NULL;

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    // Generate and initialize records
    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < num_records; ++i) {
        int offset = rand() % 1000; // Random offset
        time_t timestamp = time(NULL);

        // Construct unique ID using static key, offset, and timestamp
        records[i].unique_id = ((unsigned long)static_key << 16) | (offset ^ (int)(timestamp & 0xFFFF));

        // Allocate memory for unique identifier string
        size_t id_length = snprintf(NULL, 0, "ID-%d", records[i].unique_id) + 1;
        records[i].unique_identifier = malloc(id_length);
        if (!records[i].unique_identifier) {
            fprintf(stderr, "Memory allocation for unique identifier failed\n");

            // Cleanup partially allocated memory
            while (i-- > 0)
                free(records[i].unique_identifier);
            free(records);

            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        snprintf(records[i].unique_identifier, id_length, "ID-%d", records[i].unique_id);
    }

    pthread_mutex_unlock(&mutex);
    return records;
}

void free_records(Record* records, int num_records) {
    if (!records) return;

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_records; ++i) {
        free(records[i].unique_identifier); // Free the string
    }

    free(records); // Free the record array

    pthread_mutex_unlock(&mutex);
}

// Example usage
int main() {
    const char *static_key = "KEY";
    int num_records = 10;

    Record *records = create_records(num_records, static_key);
    if (records) {
        for (int i = 0; i < num_records; ++i) {
            printf("Record %d: ID=%d, Unique Identifier=%s\n", i, records[i].unique_id, records[i].unique_identifier);
        }

        free_records(records, num_records);
    } else {
        fprintf(stderr, "Failed to create records\n");
    }

    pthread_mutex_destroy(&mutex); // Clean up mutex
    return 0;
}
```

### Design Decisions and Assumptions:
1. **Thread Safety**: A global mutex is used for thread safety during memory allocation and deallocation operations.
2. **Error Handling**: The function checks for `NULL` pointers after each dynamic memory allocation and handles errors by freeing any previously allocated resources to avoid leaks.
3. **Unique ID Generation**: Combines a static key, random offset, and timestamp to create a unique integer identifier.
4. **Memory Management**: Ensures all dynamically allocated memory is freed to prevent leaks, especially when handling large datasets or concurrent access.
5. **Scalability and Performance**: The function is designed to efficiently handle dynamic allocation with minimal overhead for high-throughput scenarios.
6. **Modularity**: Separates record creation and cleanup logic into distinct functions for easier testing and integration.

This implementation assumes that the system has enough resources to handle the specified number of records and manages memory to avoid leaks in multithreaded environments.']

