#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int field1;
    int field2;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t num_records;
    pthread_mutex_t lock;
} MemoryManager;

#define INITIAL_CAPACITY 16
#define RESIZE_FACTOR 2

MemoryManager* initialize_memory_manager(size_t initial_capacity, int min_val, int max_val) {
    MemoryManager *manager = malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->capacity = (initial_capacity > 0) ? initial_capacity : INITIAL_CAPACITY;
    manager->num_records = 0;

    pthread_mutex_init(&manager->lock, NULL);

    manager->offsets = calloc(manager->capacity, sizeof(long));
    if (!manager->offsets) {
        free(manager);
        return NULL;
    }

    manager->keys = calloc(manager->capacity, sizeof(int));
    if (!manager->keys) {
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    manager->records = malloc(manager->capacity * sizeof(Record*));
    if (!manager->records) {
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < manager->capacity; ++i) {
        manager->records[i] = malloc(sizeof(Record));
        if (!manager->records[i]) {
            for (size_t j = 0; j <= i; ++j)
                free(manager->records[j]);
            free(manager->records);
            free(manager->keys);
            free(manager->offsets);
            free(manager);
            return NULL;
        }
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < manager->capacity; ++i) {
        manager->records[i]->field1 = rand() % (max_val - min_val + 1) + min_val;
        manager->records[i]->field2 = rand() % (max_val - min_val + 1) + min_val;
    }

    return manager;
}

void resize_records(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->num_records < manager->capacity * 0.75)
        goto unlock_and_return;

    size_t new_capacity = manager->capacity * RESIZE_FACTOR;
    Record **new_records = malloc(new_capacity * sizeof(Record*));
    if (!new_records) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    for (size_t i = 0; i < new_capacity; ++i)
        new_records[i] = calloc(1, sizeof(Record));

    memcpy(new_records, manager->records, manager->num_records * sizeof(Record*));
    free(manager->records);

    manager->records = new_records;
    manager->capacity = new_capacity;

unlock_and_return:
    pthread_mutex_unlock(&manager->lock);
}

void shuffle_records(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = manager->num_records - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        Record *temp = manager->records[i];
        manager->records[i] = manager->records[j];
        manager->records[j] = temp;
    }

    pthread_mutex_unlock(&manager->lock);
}

void reset_records(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->num_records; ++i) {
        manager->records[i]->field1 = 0;
        manager->records[i]->field2 = 0;
    }

    pthread_mutex_unlock(&manager->lock);
}

int verify_records(MemoryManager *manager) {
    for (size_t i = 0; i < manager->num_records; ++i) {
        if (manager->records[i]->field1 != 0 || manager->records[i]->field2 != 0)
            return 0;
    }
    return 1;
}

void free_memory_manager(MemoryManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->records[i]) free(manager->records[i]);
    }

    free(manager->records);
    free(manager->keys);
    free(manager->offsets);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void *thread_function(void *arg) {
    MemoryManager *manager = (MemoryManager *)arg;
    // Simulate work
    shuffle_records(manager);
    reset_records(manager);
    return NULL;
}

int main() {
    MemoryManager *manager = initialize_memory_manager(INITIAL_CAPACITY, 1, 100);
    if (!manager) {
        fprintf(stderr, "Failed to initialize memory manager\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, manager)) {
            fprintf(stderr, "Error creating thread\n");
            free_memory_manager(manager);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (!verify_records(manager))
        fprintf(stderr, "Record verification failed\n");

    free_memory_manager(manager);

    return EXIT_SUCCESS;
}
