#define INITIAL_POOL_SIZE 10
#define MAX_RECORDS 100

typedef struct {
    int field1;
    int field2;
} Record;

typedef struct MemoryPool {
    size_t block_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool mem_pool = {sizeof(Record), NULL, 0, PTHREAD_MUTEX_INITIALIZER};

