pthread_mutex_t freq_lock = PTHREAD_MUTEX_INITIALIZER;
typedef struct {
    int value;
    int count;
} Frequency;

Frequency* frequency_table = NULL;
size_t freq_size = 0, freq_capacity = 10;

void update_frequency(int number) {
    pthread_mutex_lock(&freq_lock);
    for (size_t i = 0; i < freq_size; ++i) {
        if (frequency_table[i].value == number) {
            frequency_table[i].count++;
            break;
        }
    }

    if (!frequency_table[freq_size - 1].count && freq_size < freq_capacity) {
        frequency_table[freq_size].value = number;
        frequency_table[freq_size++].count = 1;
    } else if (freq_size == freq_capacity) {
        for (size_t i = 0; i < freq_capacity - 1; ++i) {
            frequency_table[i] = frequency_table[i + 1];
        }
        frequency_table[--freq_size].value = number;
        frequency_table[freq_size].count = 1;
    }

    pthread_mutex_unlock(&freq_lock);
}

void print_top_frequencies() {
    pthread_mutex_lock(&freq_lock);

    for (size_t i = 0; i < freq_size - 1; ++i) {
        for (size_t j = i + 1; j < freq_size; ++j) {
            if (frequency_table[i].count < frequency_table[j].count) {
                Frequency temp = frequency_table[i];
                frequency_table[i] = frequency_table[j];
                frequency_table[j] = temp;
            }
        }
    }

    printf("Top 10 Frequencies:\n");
    for (size_t i = 0; i < freq_size && i < 10; ++i) {
        printf("%d: %d\n", frequency_table[i].value, frequency_table[i].count);
    }

    pthread_mutex_unlock(&freq_lock);
}

void initialize_memory_pool(MemoryPool *mp, size_t initial_size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->pool == NULL) {
        mp->block_size = sizeof(Record);
        mp->pool_size = initial_size;
        mp->pool = malloc(mp->block_size * mp->pool_size);
        memset(mp->pool, 0, mp->block_size * mp->pool_size);
    }
    pthread_mutex_unlock(&mp->lock);
}

Record* allocate_record(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->pool == NULL || ((char*)mp->pool + (mp->pool_size * mp->block_size)) - (char*)malloc(mp->block_size) < 0) {
        size_t new_size = mp->pool_size * 2;
        char* new_pool = realloc(mp->pool, new_size * mp->block_size);

        if (!new_pool) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }

        memset((char*)new_pool + (mp->pool_size * mp->block_size), 0, (new_size - mp->pool_size) * mp->block_size);
        mp->pool = new_pool;
        mp->pool_size = new_size;
    }

    Record* record = (Record*)((char*)mp->pool + ((mp->pool_size - mp->pool_size / 2) * mp->block_size));
    memset(record, 0, mp->block_size);
    mp->pool_size -= 1;

    pthread_mutex_unlock(&mp->lock);

    return record;
}

void deallocate_records(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->pool != NULL) {
        memset(mp->pool, 0, mp->block_size * mp->pool_size);
        free(mp->pool);
        mp->pool = NULL;
        mp->pool_size = 0;
    }

    pthread_mutex_unlock(&mp->lock);
}

void reset_records_to_zero(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->pool != NULL) {
        memset(mp->pool, 0, mp->block_size * mp->pool_size);
    }

    pthread_mutex_unlock(&mp->lock);
}

int add_record_from_input(MemoryPool *mp) {
    int field1, field2;
    printf("Enter two integers: ");
    if (scanf("%d %d", &field1, &field2) != 2) {
        printf("Invalid input\n");
        return -1;
    }

    Record* record = allocate_record(mp);
    if (record == NULL) {
        printf("Failed to allocate record\n");
        return -1;
    }

    record->field1 = field1;
    record->field2 = field2;

    update_frequency(field1);
    update_frequency(field2);

    return 0;
}

int main() {
    initialize_memory_pool(&mem_pool, INITIAL_POOL_SIZE);
    frequency_table = malloc(freq_capacity * sizeof(Frequency));

    while (1) {
        printf("Options:\n");
        printf("1. Add record from input\n");
        printf("2. Print top frequencies\n");
        printf("3. Reset records to zero\n");
        printf("4. Exit\n");

        int choice;
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                add_record_from_input(&mem_pool);
                break;
            case 2:
                print_top_frequencies();
                break;
            case 3:
                reset_records_to_zero(&mem_pool);
                break;
            case 4:
                deallocate_records(&mem_pool);
                free(frequency_table);
                return 0;
        }
    }

    return 0;
}
```

### Key Features:

1. **Custom Memory Pool**: Allocates a block of memory to store records, resizing as needed.
2. **Thread Safety**: Uses mutexes to ensure safe concurrent access.
3. **Frequency Tracking**: Utilizes a simple array for tracking frequencies, protected by a mutex.
4. **Input Handling and Validation**: Reads integers safely from standard input with validation.
5. **Reset Functionality**: Resets all records in the memory pool to zero without causing leaks.
6. **Command-Line Interface**: Provides user interaction through console options.

This program is structured to support dynamic allocation, thread-safe operations, and efficient management of resources within a defined scope. Adjustments might be necessary for specific use cases or integration with other systems.']

