public static class RateLimiter
{
    private static readonly ConcurrentDictionary<string, (DateTime lastRequestTimeUtc, int requestCount)> Requests = new();

    public static bool AllowRequest(string userIp)
    {
        var now = DateTime.UtcNow;
        var entry = Requests.GetOrAdd(userIp, _ => (lastRequestTimeUtc: now, requestCount: 0));

        if (entry.lastRequestTimeUtc.AddMinutes(1) < now)
        {
            Requests[userIp] = (now, 1);
            return true;
        }

        if (entry.requestCount >= MaxRequestsPerMinute)
        {
            return false;
        }

        Requests[userIp] = (entry.lastRequestTimeUtc, entry.requestCount + 1);
        return true;
    }
}

public static class RetryPolicy
{
    public static async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
    {
        int retryCount = 3;
        for (int attempt = 0; attempt < retryCount; attempt++)
        {
            try
            {
                return await action();
            }
            catch (Exception ex) when (attempt < retryCount - 1)
            {
                // Log the exception or handle transient failure.
            }
        }

        throw new Exception("Operation failed after retries.");
    }
}

