// Custom memory pool for efficient allocation and deallocation.
template<typename T>
class MemoryPool {
public:
    explicit MemoryPool(size_t blockSize) : _blockSize(blockSize), _freeList(nullptr) {}

    ~MemoryPool() {
        while (_blocks) {
            auto* block = _blocks;
            _blocks = block->next;
            ::operator delete(block);
        }
    }

    T* allocate() {
        if (!_freeList) {
            size_t blockSize = _blockSize * sizeof(T);
            auto* newBlock = static_cast<T*>(::operator new(blockSize));
            for (size_t i = 0; i < _blockSize - 1; ++i) {
                newBlock[i].next = &newBlock[i + 1];
            }
            newBlock[_blockSize - 1].next = nullptr;
            newBlock->next = _blocks;
            _blocks = newBlock;
        }

        T* head = _freeList;
        _freeList = _freeList->next;
        return head;
    }

    void deallocate(T* ptr) {
        ptr->next = _freeList;
        _freeList = ptr;
    }

private:
    struct FreeNode {
        FreeNode* next;
    };

    size_t _blockSize;
    FreeNode* _blocks;
    FreeNode* _freeList;
};

