public class SentimentProcessor {

    private static final Logger logger = Logger.getLogger(SentimentProcessor.class.getName());
    private final ConcurrentMap<String, String> cache = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private final List<SentimentAnalysisService> analysisServices;
    private final BlockingQueue<Post> postQueue = new LinkedBlockingQueue<>();
    private volatile boolean running = true;

    public SentimentProcessor(List<SentimentAnalysisService> services) {
        this.analysisServices = services;
        startWorkerThreads();
    }

    public void processPosts(List<Post> posts) {
        for (Post post : posts) {
            if (!cache.containsKey(post.getId())) {
                postQueue.offer(post);
            }
        }
    }

    private void startWorkerThreads() {
        int initialThreadCount = Runtime.getRuntime().availableProcessors();
        for (int i = 0; i < initialThreadCount; i++) {
            executorService.submit(this::processPostsFromQueue);
        }
    }

    private void processPostsFromQueue() {
        try {
            while (running) {
                Post post = postQueue.take();
                String sentiment = analyzeSentiment(post);
                cache.put(post.getId(), sentiment);

                // Simulate checkpointing
                saveCheckpoint(post);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private String analyzeSentiment(Post post) {
        for (SentimentAnalysisService service : analysisServices) {
            try {
                return service.analyze(post.getContent());
            } catch (RateLimitException e) {
                logger.log(Level.WARNING, "Rate limit hit on service: " + service.getName(), e);
                Thread.sleep(1000); // Simple backoff strategy
            }
        }
        return "Neutral"; // Default sentiment if all services fail
    }

    private void saveCheckpoint(Post post) {
