        return EXIT_SUCCESS;
    }

    MemoryPool* pool = create_memory_pool(MEMORY_POOL_SIZE);
    Record* records = initialize_records(RECORD_COUNT, 0, 100, pool);

    char** lines = malloc(100000 * sizeof(char*));
    FILE* file;

    if (input_file) {
        file = fopen(input_file, "r");
        read_last_lines(file, lines, RECORD_COUNT);
    } else {
        file = stdin;
        // Read from standard input
    }

    for (int i = 0; i < RECORD_COUNT && lines[i] != NULL; ++i) {
        int key = parse_int(lines[i]);
        if (key == -1) continue; // Skip invalid entries
        printf("Key: %d, Record Value: %d\n", key, records[i].value);
    }

    for (int i = 0; i < RECORD_COUNT && lines[i] != NULL; ++i) {
        free(lines[i]);
    }
    free(lines);

    destroy_memory_pool(pool);
    return EXIT_SUCCESS;
}

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->size = size;
    pool->start = malloc(size);
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->start);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->mutex);

    // Simplistic allocation for demonstration
    void* ptr = malloc(size); 

    pthread_mutex_unlock(&pool->mutex);
    return ptr;
}

Record* initialize_records(int count, int min_val, int max_val, MemoryPool* pool) {
    Record* records = (Record*)allocate_from_pool(pool, count * sizeof(Record));
    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
    return records;
}

int parse_int(const char* str) {
    char* endptr;
    long val = strtol(str, &endptr, 10);
    if (*endptr != '\0') return -1; // Not a valid integer
    return (int)val;
}

char* read_last_lines(FILE* file, char** lines, int line_count) {
    char buffer[1024];
    long pos = ftell(file);

    fseek(file, 0, SEEK_END);
    long end_pos = ftell(file);

    fseek(file, pos > end_pos - line_count * 100 ? pos - (end_pos - pos) / 2 : end_pos - line_count * 100, SEEK_SET);

    int i = 0;
    while (fgets(buffer, sizeof(buffer), file) && i < line_count) {
        lines[i] = strdup(buffer);
        ++i;
    }

    fseek(file, pos, SEEK_SET); // Reset position
    return NULL;
}

void print_help() {
    printf("Usage: program [options]\n");
    printf("--help     Show this help message\n");
    printf("--version  Show version information\n");
    printf("<input_file>   Specify the input file (optional)\n");
}

void print_version() {
    printf("Version 1.0\n");
}
```

