        function resetBlueslip() {
            return new Promise((resolve) => {
                setTimeout(() => resolve(), Math.random() * 100);
            });
        }

        async function manageResets() {
            while (totalResetTime < timeoutBudget) {
                const resetStart = performance.now();
                await resetBlueslip();
                const resetEnd = performance.now();

                totalResetTime += (resetEnd - resetStart);

                if (totalResetTime >= timeoutBudget) break;
            }
        }

        manageResets().then(() => {
            console.log(`Module: ${label}`);
            console.log(`Total Reset Time: ${totalResetTime.toFixed(2)} ms`);
            const endTime = performance.now();
            console.log(`Duration: ${(endTime - startTime).toFixed(2)} ms`);
        });
