#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

typedef struct {
    int value;
} record;

// Memory pool and logging structures
#define POOL_SIZE 1024 * 1024 // Example size, adjust as necessary
char memory_pool[POOL_SIZE];
size_t offset_pointer = 0;
pthread_mutex_t pool_lock;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void* custom_malloc(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (offset_pointer + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        log_error("Memory allocation failed");
        return NULL;
    }
    void* ptr = memory_pool + offset_pointer;
    offset_pointer += size;
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void custom_free(void) {
    // Reset the pool for simplicity in this example
    pthread_mutex_lock(&pool_lock);
    offset_pointer = 0;
    pthread_mutex_unlock(&pool_lock);
}

// Helper function to find and print the largest integer
pthread_mutex_t max_lock;
int global_max = INT_MIN;

void* find_max(void* args) {
    int *keys = (int*)args;
    size_t length = *((size_t*)args + 1);

    pthread_mutex_lock(&max_lock);
    for (size_t i = 0; i < length; ++i) {
        if (keys[i] > global_max) {
            global_max = keys[i];
        }
    }
    pthread_mutex_unlock(&max_lock);
    return NULL;
}

void print_global_max() {
    printf("Largest integer: %d\n", global_max);
}

// Structure for parsing command-line arguments
typedef struct {
    const char* input_source;
    int is_file;
} options_t;

options_t parse_args(int argc, char *argv[]) {
    options_t opts = { .input_source = NULL, .is_file = 0 };
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <integers_list> or --file <filename>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (strcmp(argv[1], "--file") == 0 && argc >= 3) {
        opts.input_source = argv[2];
        opts.is_file = 1;
    } else {
        opts.input_source = argv[1];
    }
    return opts;
}

int main(int argc, char *argv[]) {
    pthread_mutex_init(&pool_lock, NULL);
    pthread_mutex_init(&max_lock, NULL);

    srand(time(NULL));

    options_t options = parse_args(argc, argv);

    FILE* input;
    if (options.is_file) {
        input = fopen(options.input_source, "r");
        if (!input) {
            log_error("Failed to open file");
            return EXIT_FAILURE;
        }
    } else {
        input = stdin;
    }

    size_t num_entries = 0;
    int temp;

    while (fscanf(input, "%x", &temp) == 1 || fscanf(input, "%d", &temp) == 1) {
        num_entries++;
    }

    long* offsets = custom_malloc(num_entries * sizeof(long));
    if (!offsets) return EXIT_FAILURE;

    int* keys = custom_malloc(num_entries * sizeof(int));
    if (!keys) return EXIT_FAILURE;

    record* records = custom_malloc(num_entries * sizeof(record));
    if (!records) return EXIT_FAILURE;

    rewind(input);
    for (size_t i = 0; i < num_entries; ++i) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 100 + 1;
        records[i].value = rand() % 100;
    }

    size_t arr_size[] = { num_entries };
    pthread_t thread;

    pthread_create(&thread, NULL, find_max, &arr_size);
    pthread_join(thread, NULL);

    print_global_max();

    custom_free();

    if (options.is_file) {
        fclose(input);
    }

    pthread_mutex_destroy(&pool_lock);
    pthread_mutex_destroy(&max_lock);

    return EXIT_SUCCESS;
}
