#include <pthread.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>

#define MAX_POOL_SIZE 1024 * 1024 // 1MB

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    int key;
    int count;
} KeyFrequency;

// Global variables
MemoryPool pool;
pthread_mutex_t log_lock;
FILE *log_file;
KeyFrequency* freq_table;
size_t freq_capacity = 1024;
pthread_mutex_t freq_lock;

void init_pool(size_t initial_size) {
    pthread_mutex_init(&pool.lock, NULL);
    pool.size = 0;
    pool.capacity = initial_size;
    pool.offsets = malloc(sizeof(long) * initial_size);
    pool.keys = malloc(sizeof(int) * initial_size);
    pool.records = malloc(sizeof(Record) * initial_size);
    if (!pool.offsets || !pool.keys || !pool.records) {
        perror("Failed to initialize memory pool");
        exit(EXIT_FAILURE);
    }
}

void log_event(const char* event, size_t size) {
    pthread_mutex_lock(&log_lock);
    time_t now = time(NULL);
    fprintf(log_file, "%s: %zu bytes\n", event, size);
    fflush(log_file);
    pthread_mutex_unlock(&log_lock);
}

int add_record(int key, int value) {
    pthread_mutex_lock(&pool.lock);
    if (pool.size >= pool.capacity) {
        pthread_mutex_unlock(&pool.lock);
        return -1; // Pool full
    }
    pool.keys[pool.size] = key;
    pool.records[pool.size].value = value;
    log_event("Allocate", sizeof(Record));
    pool.size++;
    pthread_mutex_unlock(&pool.lock);
    return 0;
}

void resize_pool(size_t new_size) {
    if (new_size > MAX_POOL_SIZE || new_size <= pool.size) return;
    long* new_offsets = realloc(pool.offsets, sizeof(long) * new_size);
    int* new_keys = realloc(pool.keys, sizeof(int) * new_size);
    Record* new_records = realloc(pool.records, sizeof(Record) * new_size);

    if (!new_offsets || !new_keys || !new_records) {
        perror("Failed to resize memory pool");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&pool.lock);
    pool.offsets = new_offsets;
    pool.keys = new_keys;
    pool.records = new_records;
    pool.capacity = new_size;
    log_event("Resize", sizeof(Record) * (new_size - pool.size));
    pthread_mutex_unlock(&pool.lock);
}

void* process_key_frequency(void* arg) {
    while (1) {
        sleep(5); // Report every 5 seconds
        pthread_mutex_lock(&freq_lock);

        for (size_t i = 0; i < freq_capacity; ++i) {
            if (freq_table[i].count > 0) {
                printf("Key %d appears %d times\n", freq_table[i].key, freq_table[i].count);
                fprintf(log_file, "Key %d appears %d times\n", freq_table[i].key, freq_table[i].count);
            }
        }

        pthread_mutex_unlock(&freq_lock);
    }
}

