        pthread_mutex_unlock(&freq_lock);

        resize_pool(pool.size * 2); // Double the pool size as needed
    }
}

void cleanup() {
    free(pool.offsets);
    free(pool.keys);
    free(pool.records);
    fclose(log_file);
}

int main(int argc, char* argv[]) {
