// Memory pool structure
typedef struct {
    size_t block_size;
    size_t total_blocks;
    char *pool;
} MemoryPool;

// Helper functions for memory pool management
MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->pool = (char*)calloc(block_size * total_blocks, sizeof(char));
    return mp;
}

void* pool_alloc(MemoryPool *mp) {
    static size_t next_block = 0;
    if (next_block >= mp->total_blocks) return NULL;
    void *block = &mp->pool[next_block * mp->block_size];
    next_block++;
    return block;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

// Function to find the largest integer in an array
int find_largest(int *array, size_t size) {
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

// Thread-safe helper function to calculate average of positive floats
pthread_mutex_t avg_mutex = PTHREAD_MUTEX_INITIALIZER;

float calculate_average_positive_floats(float *float_array, size_t size) {
    float sum = 0.0f;
    int count = 0;
    pthread_mutex_lock(&avg_mutex);
    for (size_t i = 0; i < size; ++i) {
        if (float_array[i] > 0) {
            sum += float_array[i];
            count++;
        }
    }
    pthread_mutex_unlock(&avg_mutex);
    return (count > 0) ? (sum / count) : 0.0f;
}

// Main function
int main() {
    int n, i;
    printf("Enter number of integers: ");
    scanf("%d", &n);

    MemoryPool *int_pool = create_memory_pool(sizeof(int), n);
    int *int_array = (int*)malloc(n * sizeof(int));

    for (i = 0; i < n; ++i) {
        scanf("%d", &int_array[i]);
    }

    printf("Largest integer: %d\n", find_largest(int_array, n));

    // Floats memory allocation
    MemoryPool *float_pool = create_memory_pool(sizeof(float), n);
    float *float_array = (float*)malloc(n * sizeof(float));

    for (i = 0; i < n; ++i) {
        scanf("%f", &float_array[i]);
    }

    printf("Average of positive floats: %f\n", calculate_average_positive_floats(float_array, n));

    // Clean up
    destroy_memory_pool(int_pool);
    destroy_memory_pool(float_pool);
    free(int_array);
    free(float_array);

    return 0;
}
