char* generateRandomString(size_t length) {
    static const char charset[] =
        "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString = malloc(length + 1);

    if (!randomString) return NULL;

    for (size_t i = 0; i < length; i++) {
        randomString[i] = charset[rand() % (sizeof(charset) - 1)];
    }

    randomString[length] = '\0';
    return randomString;
}

int initializeDynamicEnvironment(const char *configFilePath, simulationRecord ***simulationRecordsOut, size_t *countOut) {
    FILE *file = fopen(configFilePath, "r");
    if (!file) {
        fprintf(stderr, "Failed to open configuration file.\n");
        return -1;
    }

