    buffer[1023] = '\0';
    fclose(file);

    parsed_json = json_tokener_parse(buffer);

    if (!parsed_json) {
        fprintf(stderr, "Error parsing JSON.\n");
        return -1;
    }

    if (!json_object_object_get_ex(parsed_json, "simulationCount", &configArray)) {
        fprintf(stderr, "No simulation count in configuration.\n");
        json_object_put(parsed_json);
        return -1;
    }

    *countOut = json_object_get_int(configArray);

    *simulationRecordsOut = malloc(*countOut * sizeof(simulationRecord*));
    if (!*simulationRecordsOut) {
        fprintf(stderr, "Memory allocation failed for simulation records.\n");
        json_object_put(parsed_json);
        return -1;
    }

    for (size_t i = 0; i < *countOut; ++i) {
        (*simulationRecordsOut)[i] = malloc(sizeof(simulationRecord));
        if (!(*simulationRecordsOut)[i]) {
            fprintf(stderr, "Memory allocation failed for a simulation record.\n");
            freeSimulationRecords(*simulationRecordsOut, i);
            json_object_put(parsed_json);
            return -1;
        }

        atomic_init(&((*simulationRecordsOut)[i]->value), (double)rand() / RAND_MAX * 100.0);

        (*simulationRecordsOut)[i]->str = generateRandomString(10);
        if (!(*simulationRecordsOut)[i]->str) {
            fprintf(stderr, "Failed to allocate string for simulation record.\n");
            free((*simulationRecordsOut)[i]);
            freeSimulationRecords(*simulationRecordsOut, i);
            json_object_put(parsed_json);
