        (*simulationRecordsOut)[i]->coordinates.x = (float)(rand() % 100) / 10.0f;
        (*simulationRecordsOut)[i]->coordinates.y = (float)(rand() % 100) / 10.0f;

        // Assume some registration function with simulation engine interface
    }

    json_object_put(parsed_json);

    return 0;
}

