#include "bzlib.h"

// Define compression levels and dictionary sizes
typedef enum {
    COMP_LEVEL_DEFAULT = 6,
    COMP_LEVEL_LOW,
    COMP_LEVEL_HIGH
} CompressionLevel;

typedef struct {
    size_t dict_size;
} DictSizeConfig;

// Callback function type for progress notifications
typedef void (*ProgressCallback)(int percentage);

// Compression interface structure
typedef struct {
    int algorithm; // ZLIB, LZMA, BZIP2
    CompressionLevel level;
    DictSizeConfig dict_config;
    ProgressCallback progress_callback;
} CompressionContext;

// Function prototypes
void compress_data(void *input, size_t input_size, void **output, size_t *output_size,
                   CompressionContext context);
void decompress_data(void *compressed_input, size_t compressed_input_size, void **output,
                     size_t *output_size, CompressionContext context);

// Example compression function using ZLIB
static void compress_with_zlib(void *input, size_t input_size, void **output,
                               size_t *output_size, CompressionLevel level) {
    uLongf dest_size = compressBound(input_size);
    *output = malloc(dest_size);
    if (*output == NULL) return;

    int res = compress2((Bytef *)*output, &dest_size, (const Bytef*)input, input_size,
                        level < COMP_LEVEL_LOW ? Z_BEST_SPEED : 
                        (level > COMP_LEVEL_HIGH ? Z_BEST_COMPRESSION : Z_DEFAULT_COMPRESSION));
    if (res != Z_OK) {
        free(*output);
        *output = NULL;
        *output_size = 0;
    } else {
        *output_size = dest_size;
    }
}

// Example decompression function using ZLIB
static void decompress_with_zlib(void *compressed_input, size_t compressed_input_size,
                                 void **output, size_t *output_size) {
    uLongf dest_size = *output_size; // Must be known or estimated in advance
    *output = malloc(dest_size);
    if (*output == NULL) return;

    int res = uncompress((Bytef *)*output, &dest_size, (const Bytef*)compressed_input,
                         compressed_input_size);
    if (res != Z_OK) {
        free(*output);
        *output = NULL;
        *output_size = 0;
    } else {
        *output_size = dest_size;
    }
}

// Main compression function
void compress_data(void *input, size_t input_size, void **output, size_t *output_size,
                   CompressionContext context) {
    switch (context.algorithm) {
        case ZLIB:
            compress_with_zlib(input, input_size, output, output_size, context.level);
            break;
        // Implement LZMA and BZIP2 compression similarly
        default:
            *output = NULL;
            *output_size = 0;
            break;
    }
}

// Main decompression function
void decompress_data(void *compressed_input, size_t compressed_input_size,
                     void **output, size_t *output_size, CompressionContext context) {
    switch (context.algorithm) {
        case ZLIB:
            decompress_with_zlib(compressed_input, compressed_input_size, output, output_size);
            break;
        // Implement LZMA and BZIP2 decompression similarly
        default:
            *output = NULL;
            *output_size = 0;
            break;
    }
}

// Function to set logging level and destination (stub for actual implementation)
void configure_logging(int log_level, const char* output_destination) {
    // Placeholder: Configure logging according to the system's needs.
}

int main() {
    CompressionContext ctx = {ZLIB, COMP_LEVEL_DEFAULT, {4096}, NULL};

    unsigned char input[] = "Example data for compression";
    size_t input_size = sizeof(input);
    void *output;
    size_t output_size;

    compress_data(input, input_size, &output, &output_size, ctx);

    if (output != NULL) {
        printf("Compression successful. Output size: %zu\n", output_size);
        free(output);
    } else {
        printf("Compression failed.\n");
    }

    return 0;
}
```

This code provides a modular implementation of a compression library supporting ZLIB as an example, with placeholders for LZMA and BZIP2 implementations. It incorporates adjustable compression levels, dictionary sizes, and progress notifications via callbacks. Additional functionalities like monitoring and logging are suggested but would need further integration based on system requirements.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_DEVICES 10000
#define MEMORY_LIMIT_PER_SECOND 50000
#define REPORT_INTERVAL_SECONDS 60

typedef struct {
    float temperature;
    float humidity;
} Sensor;

typedef struct {
    char id[16];
    double latitude;
    double longitude;
    Sensor *sensors;
    int sensor_count;
} Station;

typedef struct {
    char id[16];
    time_t timestamp;
    char status_message[256];
    Sensor *associated_sensor;
} Device;

typedef struct {
    pthread_mutex_t lock;
    size_t current_allocation_size;
    size_t peak_allocation_size;
    float fragmentation_ratio;
    size_t allocated_memory;
} MemoryPool;

MemoryPool pool = {PTHREAD_MUTEX_INITIALIZER, 0, 0, 0.0f, MEMORY_LIMIT_PER_SECOND};

void* memory_pool_alloc(size_t size) {
    pthread_mutex_lock(&pool.lock);
    if (size + pool.current_allocation_size > pool.allocated_memory) {
        printf("Memory limit exceeded\n");
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    void *mem = malloc(size);
    if (!mem) {
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    pool.current_allocation_size += size;
    if (pool.current_allocation_size > pool.peak_allocation_size) {
        pool.peak_allocation_size = pool.current_allocation_size;
    }

    float fragmentation = ((float)malloc_usable_size(mem) - size) / size;
    if (fragmentation > pool.fragmentation_ratio) {
        pool.fragmentation_ratio = fragmentation;
    }

    pthread_mutex_unlock(&pool.lock);
    return mem;
}

void memory_pool_free(void *ptr, size_t size) {
    pthread_mutex_lock(&pool.lock);
    free(ptr);
    pool.current_allocation_size -= size;
    pthread_mutex_unlock(&pool.lock);
}

Station* create_station(const char *id, double lat, double lon, int sensor_count) {
    Station *station = (Station*) memory_pool_alloc(sizeof(Station));
    if (!station) return NULL;

    strncpy(station->id, id, sizeof(station->id) - 1);
    station->latitude = lat;
    station->longitude = lon;
    station->sensor_count = sensor_count;
    station->sensors = (Sensor *)memory_pool_alloc(sensor_count * sizeof(Sensor));

    return station;
}

Device* create_device(const char *id, Sensor *sensor) {
    Device *device = (Device*) memory_pool_alloc(sizeof(Device));
    if (!device) return NULL;

    strncpy(device->id, id, sizeof(device->id) - 1);
    time(&device->timestamp);
    strcpy(device->status_message, "Initialized");
    device->associated_sensor = sensor;

    return device;
}

void report_memory_usage() {
    while (1) {
        sleep(REPORT_INTERVAL_SECONDS);

        pthread_mutex_lock(&pool.lock);
        printf("Current allocation size: %zu bytes\n", pool.current_allocation_size);
        printf("Peak allocation size: %zu bytes\n", pool.peak_allocation_size);
        printf("Fragmentation ratio: %.2f%%\n", pool.fragmentation_ratio * 100);
        pthread_mutex_unlock(&pool.lock);
    }
}

float compute_average_temperature(Device *devices, int device_count) {
    float total_temp = 0;
    int count = 0;

    for (int i = 0; i < device_count; ++i) {
        if (devices[i].associated_sensor) {
            total_temp += devices[i].associated_sensor->temperature;
            count++;
        }
    }

    return count > 0 ? total_temp / count : 0.0f;
}

void* handle_device_requests(void *arg) {
    Station *stations = (Station*) arg;
    int station_count = *(int *)(((char*)arg) + sizeof(Station*) * MAX_DEVICES);

    while (1) {
        char device_id[16];
        printf("Enter device ID: ");
        scanf("%15s", device_id);

        for (int i = 0; i < station_count; ++i) {
            for (int j = 0; j < stations[i].sensor_count; ++j) {
                Device *device = create_device(device_id, &stations[i].sensors[j]);
                if (device) {
                    printf("Average temperature: %.2f\n", compute_average_temperature(&device, 1));
                    memory_pool_free(device, sizeof(Device));
                }
            }
        }
    }

    return NULL;
}

int main() {
    pthread_t report_thread, request_thread;

    pthread_create(&report_thread, NULL, (void*)report_memory_usage, NULL);

    int station_count = 10; // Example number
    Station *stations = (Station *)memory_pool_alloc(station_count * sizeof(Station));

    for (int i = 0; i < station_count; ++i) {
        char id[16];
        sprintf(id, "station_%d", i);
        stations[i] = *(create_station(id, rand() % 180 - 90, rand() % 360, 5));
    }

    pthread_create(&request_thread, NULL, handle_device_requests, (void*)stations);

    pthread_join(report_thread, NULL);
    pthread_join(request_thread, NULL);

    for (int i = 0; i < station_count; ++i) {
        memory_pool_free(stations[i].sensors, stations[i].sensor_count * sizeof(Sensor));
        memory_pool_free(&stations[i], sizeof(Station));
    }

    memory_pool_free(stations, station_count * sizeof(Station));

    return 0;
}
```

This code demonstrates dynamic management of interconnected data structures representing a network of environmental monitoring stations with sensors and devices. It utilizes a custom memory pool for efficient allocation while adhering to constraints on allocation limits per second and total device count. Thread-safe mechanisms ensure atomic updates, concurrent access handling, and periodic reporting of memory usage statistics.']

