            logging.info(f"Starting deployment for {env_config['name']}")
            config_dir = self.fetch_config(env_config['repo_url'], env_config['branch'])
            self.apply_environment_modifications(config_dir)
            self.install_dependencies()
            if env_config['method'] == 'ssh':
                self.deploy_via_ssh(env_config['host'], env_config['user'], env_config['key_file'], env_config['command'])
            elif env_config['method'] == 'https':
                self.deploy_via_https(env_config['url'])
            self.test_deployment()
        except Exception as e:
            logging.error(f"Deployment failed for {env_config['name']}: {e}")
            self.rollback(env_config.get('version'))
