char* append_slash_if_within_limit(const char *input, size_t limit) {
    size_t input_len = strlen(input);
    if (input_len >= limit) {
        return NULL;
    }

    // Allocate space for the new string with a slash and null terminator
    char *result = malloc(limit + 1);
    if (!result) {
        return NULL; // Memory allocation failed
    }

    strcpy(result, input); // Copy input to result
    result[input_len] = '/'; // Append slash
    result[input_len + 1] = '\0'; // Null terminator

    return result;
}
