void initialize_memory_pool(memory_pool *pool, size_t size) {
    pool->start = malloc(size);
    if (pool->start == NULL) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pool->size = size;
    pool->offset = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void *memory_pool_alloc(memory_pool *pool, size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->offset + size <= pool->size) {
        ptr = (char *)pool->start + pool->offset;
        pool->offset += size;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_memory_pool(memory_pool *pool) {
    free(pool->start);
    pthread_mutex_destroy(&pool->lock);
}

