float calculate_average_positive_floats(FloatNode **list_head) {
    float sum = 0.0;
    size_t count = 0;
    FloatNode *current = *list_head;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    while (current != NULL) {
        pthread_mutex_lock(&lock);
        if (current->value > 0) {
            sum += current->value;
            count++;
        }
        pthread_mutex_unlock(&lock);
        current = current->next;
    }

    pthread_mutex_destroy(&lock);

    return count == 0 ? 0 : sum / count;
}

void process_data_stream() {
    FloatNode *float_list_head = NULL;
    StringFloatTuple *tuple_list = NULL;
    size_t tuple_count = 0;
    AlertLog *alert_logs = NULL;
    size_t alert_count = 0;
    Metrics metrics[100]; // Adjust as necessary

    char buffer[1024];
    int data_type;

    while (fscanf(stdin, "%d %[^\n]", &data_type, buffer) != EOF) {
        switch (data_type) {
            case INT_TYPE:
                // Process integer
                break;
            case FLOAT_TYPE: {
                FloatNode *new_node = malloc(sizeof(FloatNode));
                new_node->value = atof(buffer);
                new_node->next = float_list_head;
                float_list_head = new_node;
                break;
            }
            case STRING_FLOAT_TUPLE_TYPE: {
                StringFloatTuple *tuple = malloc(sizeof(StringFloatTuple));
                tuple->str = strdup(buffer); // Assume format "string,float"
                char *comma = strchr(tuple->str, ',');
                if (comma) {
                    *comma = '\0';
                    comma++;
                    tuple->num = atof(comma);
                }
                tuple_list = realloc(tuple_list, sizeof(StringFloatTuple) * (tuple_count + 1));
                tuple_list[tuple_count++] = *tuple;
                break;
            }
            case ALERT_LOG_TYPE: {
                AlertLog *new_log = malloc(sizeof(AlertLog));
                // Assume format "description,timestamp"
                char *comma = strchr(buffer, ',');
                if (comma) {
                    *comma = '\0';
                    comma++;
                    new_log->description = strdup(buffer);
                    new_log->timestamp = atol(comma);
                }
                alert_logs = realloc(alert_logs, sizeof(AlertLog) * (alert_count + 1));
                alert_logs[alert_count++] = *new_log;
                break;
            }
            default:
                fprintf(stderr, "Unknown data type: %d\n", data_type);
        }
    }

    // Process metrics
    for (size_t i = 0; i < sizeof(metrics) / sizeof(Metrics); ++i) {
        metrics[i].metric_value = rand() / (float)RAND_MAX * 100;
        metrics[i].tuples = tuple_list;
        metrics[i].tuple_count = tuple_count;
        if (alert_count > 0) {
            int index = rand() % alert_count;
            metrics[i].alert_log = alert_logs[index];
        }
    }

    float average = calculate_average_positive_floats(&float_list_head);

    printf("Average of positive floats: %.2f\n", average);

    // Clean up
    FloatNode *current = float_list_head;
    while (current) {
        FloatNode *next = current->next;
        free(current);
        current = next;
    }

    for (size_t i = 0; i < tuple_count; ++i) {
        free(tuple_list[i].str);
    }
    free(tuple_list);

    for (size_t i = 0; i < alert_count; ++i) {
        free(alert_logs[i].description);
    }
    free(alert_logs);

    // Placeholder for additional cleanup and external monitoring
}

