class CustomSerializer {
    private static final String ALGORITHM = "AES";

    public static byte[] serialize(Object obj) throws Exception {
        // Simplified serialization logic using JSON for illustration purposes.
        return new JSONObject(obj).toString().getBytes(StandardCharsets.UTF_8);
