    public static <T> T deserialize(byte[] data, Class<T> clazz) throws JSONException {
        return new JSONObject(new String(data)).toMap().entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, e -> {
                    try {
                        if (BigDecimal.class.isAssignableFrom(e.getValue().getClass())) {
                            return new BigDecimal((String) e.getValue());
                        } else if (String.class.isAssignableFrom(e.getValue().getClass())) {
                            return (String) e.getValue();
                        }
                        // Add more type handlers as needed
                        return e.getValue();
                    } catch (Exception ex) {
                        throw new JSONException("Deserialization error");
                    }
                })).entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, e -> {
                    try {
                        if (BigDecimal.class.isAssignableFrom(clazz.getDeclaredField(e.getKey()).getType())) {
                            return (T) ((Number) e.getValue()).bigDecimalValue();
                        } else if (String.class.isAssignableFrom(clazz.getDeclaredField(e.getKey()).getType())) {
                            return (T) e.getValue();
                        }
                        // Add more type handlers as needed
                        throw new JSONException("Unsupported field type");
                    } catch (Exception ex) {
                        throw new JSONException("Deserialization error");
                    }
                })).entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue))
                .entrySet().stream().findFirst()
                .map(e -> {
                    try {
                        T instance = clazz.getDeclaredConstructor().newInstance();
                        for (Map.Entry<String, Object> entry : e.getValue().entrySet()) {
                            clazz.getDeclaredField(entry.getKey()).set(instance, entry.getValue());
                        }
                        return instance;
                    } catch (Exception ex) {
                        throw new JSONException("Deserialization error");
                    }
                }).orElseThrow(() -> new JSONException("Empty data"));
    }

    public static byte[] encrypt(byte[] data, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, key);
        return cipher.doFinal(data);
    }

    public static byte[] decrypt(byte[] encryptedData, SecretKey key) throws Exception {
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, key);
        return cipher.doFinal(encryptedData);
    }
