#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float x, y;
} Point;

typedef struct {
    char *name;
    float area;
} Geometry;

typedef struct QueueNode {
    void *data;
    struct QueueNode *next;
} QueueNode;

typedef struct {
    QueueNode *head;
    QueueNode *tail;
    pthread_mutex_t lock;
} ThreadSafeQueue;

// Memory pool
typedef struct {
    size_t blockSize;
    unsigned char *pool;
    size_t poolSize;
    unsigned char *freeList;
} MemoryPool;

void initializeMemoryPool(MemoryPool *mp, size_t poolSize, size_t blockSize) {
    mp->blockSize = blockSize;
    mp->poolSize = poolSize;
    mp->pool = malloc(poolSize);
    mp->freeList = mp->pool;

    for (size_t i = 0; i < poolSize - blockSize; i += blockSize) {
        *(void**)(mp->pool + i) = mp->pool + i + blockSize;
    }
    *(void**)(mp->pool + poolSize - blockSize) = NULL;
}

void* allocateFromPool(MemoryPool *mp) {
    if (!mp->freeList) return NULL;
    void *block = mp->freeList;
    mp->freeList = *(void**)block;
    return block;
}

void deallocateToPool(MemoryPool *mp, void *ptr) {
    *(void**)ptr = mp->freeList;
    mp->freeList = ptr;
}

void freeMemoryPool(MemoryPool *mp) {
    free(mp->pool);
}

// Initialize thread-safe queue
ThreadSafeQueue* createQueue() {
    ThreadSafeQueue *q = malloc(sizeof(ThreadSafeQueue));
    q->head = q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enqueue(ThreadSafeQueue *q, void *data) {
    QueueNode *node = allocateFromPool(&memoryPool); // Assume memoryPool is globally defined
    if (node) {
        node->data = data;
        node->next = NULL;
        pthread_mutex_lock(&q->lock);
        if (!q->tail) q->head = q->tail = node;
        else {
            q->tail->next = node;
            q->tail = node;
        }
        pthread_mutex_unlock(&q->lock);
    }
}

void* dequeue(ThreadSafeQueue *q) {
    pthread_mutex_lock(&q->lock);
    if (!q->head) {
        pthread_mutex_unlock(&q->lock);
        return NULL;
    }
    QueueNode *node = q->head;
    void *data = node->data;
    q->head = node->next;
    if (!q->head) q->tail = NULL;
    deallocateToPool(&memoryPool, node); // Assume memoryPool is globally defined
    pthread_mutex_unlock(&q->lock);
    return data;
}

void destroyQueue(ThreadSafeQueue *q) {
    while (dequeue(q));
    pthread_mutex_destroy(&q->lock);
    free(q);
}

// Initialize read-write lock
pthread_rwlock_t rwLock;

void initializeRWLock() {
