#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char **strings;
    int index;
} data;

// Function to calculate the length of a string safely
size_t safe_strlen(const char *str) {
    size_t len = 0;
    while (str[len] != '\0') {
        len++;
    }
    return len;
}

data* allocate_and_initialize_data(const char* text, int num_structures, int max_memory_bytes) {
    if (!text || num_structures <= 0 || max_memory_bytes <= 0) {
        return NULL; // Invalid input parameters
    }

    size_t text_length = safe_strlen(text);
    size_t total_memory_used = 0;

    data* structures = (data*)malloc(num_structures * sizeof(data));
    if (!structures) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_structures; ++i) {
        int string_length = text_length / (num_structures - i);
        char* substring = (char*)malloc((string_length + 1) * sizeof(char));

        if (!substring || total_memory_used + (string_length + 1) > max_memory_bytes) {
            // Free allocated memory in case of failure
            for (int j = 0; j < i; ++j) {
                free(structures[j].strings[0]);
                free(structures[j].strings);
            }
            free(structures);
            return NULL;
        }

        strncpy(substring, text + string_length * i, string_length);
        substring[string_length] = '\0';

        structures[i].strings = (char**)malloc(sizeof(char*));
        if (!structures[i].strings) {
            // Free allocated memory in case of failure
            free(substring);
            for (int j = 0; j < i; ++j) {
                free(structures[j].strings[0]);
                free(structures[j].strings);
            }
            free(structures);
            return NULL;
        }

        structures[i].strings[0] = substring;
        total_memory_used += sizeof(char*) + (string_length + 1) * sizeof(char);

        structures[i].index = i;
    }

    return structures;
}

void free_data(data* structures, int num_structures) {
    if (!structures) return;

    for (int i = 0; i < num_structures; ++i) {
        free(structures[i].strings[0]);
        free(structures[i].strings);
    }
    free(structures);
}
```

