#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Custom memory pool functions (assumed to be provided)
void* custom_alloc(size_t size);
void custom_free(void* ptr);

// Structure for holding the data collections
typedef struct {
    long *offsets;     // Array of 'long' offset values
    int *keys;         // Array of 'int' keys
    record *records;   // Array of records
    size_t count;      // Number of elements in each collection
    pthread_rwlock_t lock;  // Read-write lock for thread safety
} collections;

// Function to initialize and manage memory for the collections
collections* init_collections(size_t count, int min_value, int max_value) {
    collections *data = (collections*)custom_alloc(sizeof(collections));
    if (!data) return NULL;

    data->offsets = (long*)custom_alloc(count * sizeof(long));
    data->keys = (int*)custom_alloc(count * sizeof(int));
    data->records = (record*)custom_alloc(count * sizeof(record));
    data->count = count;

    // Initialize the lock
    pthread_rwlock_init(&data->lock, NULL);

    if (!data->offsets || !data->keys || !data->records) {
        custom_free(data);
        return NULL;
    }

    srand(time(NULL));  // Seed for random number generation

    // Populate collections with values
    for (size_t i = 0; i < count; ++i) {
        data->offsets[i] = rand();  // Assign some long value
        data->keys[i] = rand() % 100;  // Random key example
        atomic_init(&data->records[i].value, min_value + (rand() % (max_value - min_value + 1)));
    }

    return data;
}

// Function to release resources for the collections
void destroy_collections(collections *data) {
    if (!data) return;

    custom_free(data->offsets);
    custom_free(data->keys);
    custom_free(data->records);

    pthread_rwlock_destroy(&data->lock);
    custom_free(data);
}
