void init_frequency_list(FrequencyList* list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

Node* create_node(const char *substring) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->substring = strdup(substring);
    node->frequency = 1;
    node->next = NULL;

    return node;
}

void insert_frequency_list(FrequencyList* list, const char *substring) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && strcmp(current->substring, substring) < 0) {
        prev = current;
        current = current->next;
    }

    if (current != NULL && strcmp(current->substring, substring) == 0) {
        current->frequency++;
    } else {
        Node* new_node = create_node(substring);
        if (new_node) {
            new_node->next = current;
            if (prev == NULL) list->head = new_node; // Insert at head
            else prev->next = new_node;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_frequency_list(FrequencyList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp->substring);
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void init_resource_pool(ResourcePool *pool, const char* text, int max_input_length, ReplacementPolicy policy) {
