            free(d->strings[i]);
        }
        free(d->strings);
    }
}

data* allocate_data_structure(ResourcePool *pool, size_t required_memory) {
    pthread_mutex_lock(&global_lock);

    if ((pool->current_memory_usage + required_memory) > MEMORY_LIMIT) {
        // Evict based on policy
        switch (pool->policy) {
            case LRU:
                // Implement LRU eviction here
                break;
            case LFU:
                // Use the frequency list to find and remove least frequently used item
                break;
            case RANDOM:
                int random_index = rand() % pool->count;
                free_data_structure(&pool->structures[random_index]);
                pool->current_memory_usage -= sizeof(data); // Simplified, adjust as needed
                break;
        }
    }

    for (int i = 0; i < pool->capacity && pool->count >= MAX_STRUCTS; ++i) {
        if (pool->structures[i].strings == NULL) { // Find first available or empty slot
            data* d = &pool->structures[i];
            pool->current_memory_usage += sizeof(data);
            return d;
        }
    }

    pthread_mutex_unlock(&global_lock);

    return NULL; // Allocation failed, implement alternative strategy if necessary
}

void free_resource_pool(ResourcePool *pool) {
    for (int i = 0; i < pool->capacity; ++i) {
        free_data_structure(&pool->structures[i]);
    }

    pool->count = 0;
    pool->current_memory_usage = 0;

    free_frequency_list(&pool->freq_list);
}

void resource_managed_data_structures(ResourcePool *pool, const char* text, int max_input_length, ReplacementPolicy policy) {
    pthread_mutex_lock(&global_lock);

    init_resource_pool(pool, text, max_input_length, policy);

    // Initialize the structures with unique substrings
    for (int i = 0; i < pool->capacity && pool->count < MAX_STRUCTS; ++i) {
        data* d = allocate_data_structure(pool, sizeof(data));
        if (!d) break;

        char *substring = strndup(text + rand() % strlen(text), max_input_length);
        insert_frequency_list(&pool->freq_list, substring);

        d->strings = (char**)malloc(sizeof(char*) * 10); // Assume a fixed size for simplicity
        if (!d->strings) continue;

        int j = 0;
        do {
            d->strings[j++] = substring;
            substring = strndup(text + rand() % strlen(text), max_input_length);
            insert_frequency_list(&pool->freq_list, substring);
        } while (j < 10 && pool->current_memory_usage <= MEMORY_LIMIT);

        free(substring); // Free the last allocated but unused string
        d->strings[j] = NULL;
        d->index = i;

        pool->count++;
    }

    pthread_mutex_unlock(&global_lock);
}
