#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_GEOMETRIES 10000

typedef struct {
    float x;
    float y;
} point;

typedef struct {
    char* name;
    float area;
    float perimeter;
    pthread_rwlock_t lock; // For thread-safe access
} geometry;

typedef struct cache_entry {
    geometry* geom;
    int accessed_count;
    pthread_mutex_t mutex;
} cache_entry;

// Memory pool for efficient memory management
typedef struct {
    void* pool;
    size_t unit_size;
    size_t total_units;
    size_t used_units;
    pthread_mutex_t lock;
} memory_pool;

void initialize_memory_pool(memory_pool *mp, size_t unit_size, size_t total_units) {
    mp->pool = malloc(unit_size * total_units);
    if (!mp->pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mp->unit_size = unit_size;
    mp->total_units = total_units;
    mp->used_units = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void* allocate_from_pool(memory_pool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_units < mp->total_units) {
        void* ptr = (char*)mp->pool + (mp->unit_size * mp->used_units++);
        pthread_mutex_unlock(&mp->lock);
        return ptr;
    } else {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool is full
    }
}

void free_memory_pool(memory_pool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

// Calculate area and perimeter for a given point (treated as a circle)
float calculate_area(float radius) {
    return 3.14159f * radius * radius;
}

float calculate_perimeter(float radius) {
    return 2 * 3.14159f * radius;
}

int initialize_geometries(memory_pool* mp, geometry** geometries, cache_entry** cache, size_t num_points, point* points) {
    if (num_points > MAX_GEOMETRIES) {
        fprintf(stderr, "Exceeded maximum number of geometries\n");
        return -1;
    }

    *geometries = malloc(num_points * sizeof(geometry));
    if (!*geometries) {
        perror("Failed to allocate memory for geometries");
        return -1;
    }

    *cache = malloc(num_points * sizeof(cache_entry));
    if (!*cache) {
        perror("Failed to allocate memory for cache entries");
        free(*geometries);
        return -1;
    }

    for (size_t i = 0; i < num_points; ++i) {
        geometry* geom = &((*geometries)[i]);
        pthread_rwlock_init(&geom->lock, NULL);

        // Calculate radius as distance from origin
        float radius = sqrt(points[i].x * points[i].x + points[i].y * points[i].y);
        geom->area = calculate_area(radius);
        geom->perimeter = calculate_perimeter(radius);

        // Allocate memory for the name using the pool
        char* name = (char*)allocate_from_pool(mp);
        if (!name) {
            fprintf(stderr, "Memory pool exhausted\n");
            free(*geometries);
            free(*cache);
            return -1;
        }
        snprintf(name, 64, "Geometry %zu", i); // Assuming max length of 63 for name
        geom->name = name;

        cache_entry* entry = &((*cache)[i]);
        entry->geom = geom;
        entry->accessed_count = 0;
        pthread_mutex_init(&entry->mutex, NULL);
    }

    return 0; // Success
}

void cleanup_geometries(geometry* geometries, size_t num_points) {
    for (size_t i = 0; i < num_points; ++i) {
        geometry* geom = &geometries[i];
        pthread_rwlock_destroy(&geom->lock);
    }
    free(geometries);
}

void cleanup_cache(cache_entry* cache, size_t num_entries) {
    for (size_t i = 0; i < num_entries; ++i) {
        cache_entry* entry = &cache[i];
        pthread_mutex_destroy(&entry->mutex);
    }
    free(cache);
}

// Serialize geometries to a binary file
int serialize_geometries(const char* filename, geometry* geometries, size_t num_points) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    fwrite(&num_points, sizeof(size_t), 1, file);
    for (size_t i = 0; i < num_points; ++i) {
        pthread_rwlock_rdlock(&geometries[i].lock);
        size_t name_length = strlen(geometries[i].name) + 1;
        fwrite(&name_length, sizeof(size_t), 1, file);
        fwrite(geometries[i].name, sizeof(char), name_length, file);
        fwrite(&geometries[i].area, sizeof(float), 1, file);
        fwrite(&geometries[i].perimeter, sizeof(float), 1, file);
        pthread_rwlock_unlock(&geometries[i].lock);
    }

    fclose(file);
    return 0;
}

// Deserialize geometries from a binary file
int deserialize_geometries(const char* filename, geometry** geometries, size_t* num_points) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    fread(num_points, sizeof(size_t), 1, file);
    *geometries = malloc(*num_points * sizeof(geometry));
    if (!*geometries) {
        perror("Failed to allocate memory for geometries");
        fclose(file);
        return -1;
    }

    for (size_t i = 0; i < *num_points; ++i) {
        geometry* geom = &((*geometries)[i]);
        pthread_rwlock_init(&geom->lock, NULL);

        size_t name_length;
        fread(&name_length, sizeof(size_t), 1, file);
        char* name = (char*)malloc(name_length * sizeof(char));
        if (!name) {
            perror("Failed to allocate memory for geometry name");
            fclose(file);
            cleanup_geometries(*geometries, i);
            free(*geometries);
            return -1;
        }
        fread(name, sizeof(char), name_length, file);

        fread(&geom->area, sizeof(float), 1, file);
        fread(&geom->perimeter, sizeof(float), 1, file);
        geom->name = name;
    }

    fclose(file);
    return 0;
}

int main() {
    memory_pool mp;
    initialize_memory_pool(&mp, 64, MAX_GEOMETRIES); // Assuming max name length of 63

    point points[MAX_GEOMETRIES];
    for (size_t i = 0; i < MAX_GEOMETRIES; ++i) {
        points[i].x = rand() % 100;
        points[i].y = rand() % 100;
    }

    geometry* geometries = NULL;
    cache_entry* cache = NULL;

    if (initialize_geometries(&mp, &geometries, &cache, MAX_GEOMETRIES, points) == 0) {
        serialize_geometries("geometries.bin", geometries, MAX_GEOMETRIES);

        geometry* loaded_geometries = NULL;
        size_t num_loaded_points = 0;
        if (deserialize_geometries("geometries.bin", &loaded_geometries, &num_loaded_points) == 0) {
            // Use loaded_geometries
        }

        cleanup_cache(cache, MAX_GEOMETRIES);
        cleanup_geometries(geometries, MAX_GEOMETRIES);
        free(loaded_geometries);
    }

    free_memory_pool(&mp);
    return 0;
}
