// Initialize the custom memory pool
void init_memory_pool(memory_pool *pool, size_t block_size) {
    pool->block_size = block_size;
    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);
}

// Allocate a block from the memory pool or create a new one if necessary
void* allocate_block(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (!pool->free_list) {
        pool->free_list = (pool_block*)malloc(pool->block_size);
        pool->free_list->size = pool->block_size - sizeof(pool_block*);
        pool->free_list->memory = (char*)pool->free_list + sizeof(pool_block*);
        pool->free_list->next = NULL;
    }

    void *allocated_memory = pool->free_list->memory;
    pool_block *new_free_list = pool->free_list->next;
    free(pool->free_list);
    pool->free_list = new_free_list;

    pthread_mutex_unlock(&pool->lock);

    return allocated_memory;
}

// Free all memory in the pool
void destroy_memory_pool(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    while (pool->free_list) {
        pool_block *to_free = pool->free_list;
        pool->free_list = to_free->next;
        free(to_free);
    }
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

// Initialize asynchronous update queue
void init_async_update_queue(async_update_queue *queue) {
    queue->head = NULL;
    queue->tail = NULL;
    pthread_rwlock_init(&queue->rwlock, NULL);
}

// Enqueue an update to the geometry structure
void enqueue_geometry_update(async_update_queue *queue, const geometry *update) {
    queue_node *new_node = (queue_node*)allocate_block(pool); // Assume pool is accessible globally or passed in.
    new_node->update = *update;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&queue->rwlock);
    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;
    pthread_rwlock_unlock(&queue->rwlock);
}

// Dequeue an update from the geometry structure
int dequeue_geometry_update(async_update_queue *queue, geometry *update) {
    pthread_rwlock_rdlock(&queue->rwlock);
    if (queue->head == NULL) {
        pthread_rwlock_unlock(&queue->rwlock);
        return 0;
    }

    queue_node *node_to_dequeue = queue->head;
    *update = node_to_dequeue->update;

    queue->head = node_to_dequeue->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    pthread_rwlock_unlock(&queue->rwlock);

    free(node_to_dequeue);
    return 1;
}

