// Helper function to calculate the average of positive floats
float calculate_average_of_positive_floats(const float* array, int length, pthread_mutex_t* lock) {
    pthread_mutex_lock(lock);

    float sum = 0.0f;
    int count = 0;

    for (int i = 0; i < length; ++i) {
        if (array[i] > 0) {
            sum += array[i];
            count++;
        }
    }

    pthread_mutex_unlock(lock);

    return (count == 0) ? 0.0f : sum / count;
}

