int find_largest_integer(int* array, int length) {
    if (!array || length <= 0)
        return -1; // Error code for invalid input

    int largest = array[0];

    for (int i = 1; i < length; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

