int resolve_dns(const char* hostname, u_char* ip_address_buffer) {
    struct hostent *he;
    struct in_addr **addr_list;

    // Resolve the hostname into an IP address list
    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return -1;  // Error code for DNS resolution failure
    }

    addr_list = (struct in_addr **) he->h_addr_list;

    for(int i = 0; addr_list[i] != NULL; i++) {
        inet_ntop(AF_INET, &addr_list[i]->s_addr, (char*)ip_address_buffer, INET_ADDRSTRLEN);
        return 0; // Success
    }

    return -2; // Error code if no addresses found
}

