pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

MemoryPool* create_memory_pool(size_t int_size, size_t record_size, size_t event_size) {
    pthread_mutex_lock(&pool_mutex);

    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        perror("Failed to allocate memory pool");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }

    pool->int_array = malloc(int_size * sizeof(int));
    if (!pool->int_array) {
        perror("Failed to allocate int array");
        free(pool);
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    memset(pool->int_array, 0, int_size * sizeof(int));

    pool->record_array = malloc(record_size * sizeof(record));
    if (!pool->record_array) {
        perror("Failed to allocate record array");
        free(pool->int_array);
        free(pool);
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    for (size_t i = 0; i < record_size; ++i) {
        pool->record_array[i].name[0] = '\0';
        pool->record_array[i].value = 0.0f;
    }

    pool->event_array = malloc(event_size * sizeof(event));
    if (!pool->event_array) {
        perror("Failed to allocate event array");
        free(pool->record_array);
        free(pool->int_array);
        free(pool);
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    time_t now = time(NULL);
    for (size_t i = 0; i < event_size; ++i) {
        pool->event_array[i].timestamp = now;
        strftime(pool->event_array[i].message, sizeof(pool->event_array[i].message), "%c", localtime(&now));
        pool->event_array[i].rec.name[0] = '\0';
        pool->event_array[i].rec.value = 0.0f;
    }

    pool->int_size = int_size;
    pool->record_size = record_size;
    pool->event_size = event_size;

    pthread_mutex_unlock(&pool_mutex);
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    if (pool) {
        pthread_mutex_lock(&pool_mutex);

        free(pool->int_array);
        free(pool->record_array);
        free(pool->event_array);
        free(pool);

        pthread_mutex_unlock(&pool_mutex);
    }
}

