import threading
from kubernetes import client, config, utils
from docker import DockerClient, APIClient
from kubernetes.client.rest import ApiException
import logging
import os

logging.basicConfig(level=logging.INFO)

class DeploymentManager:
    def __init__(self, config_dict):
        self.config = config_dict
        config.load_kube_config()
        self.k8s_client = client.ApiClient()
        self.docker_client = DockerClient(base_url='unix://var/run/docker.sock')
        self.api_instance = client.AppsV1Api(self.k8s_client)
        self.core_v1_api = client.CoreV1Api(self.k8s_client)

    def authenticate_docker_registry(self):
        for registry in self.config['private_registries']:
            os.environ["DOCKER_USERNAME"] = registry['username']
            os.environ["DOCKER_PASSWORD"] = registry['password']
            self.docker_client.login(username=registry['username'], 
                                     password=registry['password'],
                                     registry=registry['url'])

    def pull_docker_image(self, image):
        try:
            logging.info(f"Pulling Docker Image: {image}")
            api_client = APIClient(base_url='unix://var/run/docker.sock')
            api_client.pull(image, stream=True)
        except Exception as e:
            raise Exception(f"Failed to pull image {image}: {e}")

    def deploy_service(self, service_name):
        try:
            logging.info(f"Deploying Service: {service_name}")
            namespace = self.config['namespace']
            deployment_body = client.V1Deployment(
                metadata=client.V1ObjectMeta(name=service_name),
                spec=client.V1DeploymentSpec(
                    replicas=self.config['replicas'],
                    selector={'matchLabels': {'app': service_name}},
                    template=client.V1PodTemplateSpec(
                        metadata=client.V1ObjectMeta(labels={'app': service_name}),
                        spec=client.V1PodSpec(containers=[
                            client.V1Container(name=service_name,
                                               image=self.config['services'][service_name]['image'],
                                               ports=[client.V1ContainerPort(container_port=80)])
                        ])
                    )
                )
            )
            self.api_instance.create_namespaced_deployment(namespace, deployment_body)
        except ApiException as e:
            raise Exception(f"Deployment failed for {service_name}: {e}")

    def update_configmap(self):
        namespace = self.config['namespace']
        config_map_data = {key: val.encode('utf-8') for key, val in self.config['config'].items()}
        try:
            body = client.V1ConfigMap(
                metadata=client.V1ObjectMeta(name="service-config"),
                data=config_map_data
            )
            self.core_v1_api.create_namespaced_config_map(namespace, body)
        except ApiException as e:
            raise Exception(f"Failed to update ConfigMap: {e}")

    def monitor_services(self):
        for service_name in self.config['services']:
            pods = self.core_v1_api.list_namespaced_pod(
                namespace=self.config['namespace'],
                label_selector=f'app={service_name}'
            )
            if not all(pod.status.phase == "Running" for pod in pods.items):
                raise Exception(f"Service {service_name} is not healthy")

    def rollback_service(self, service_name):
        logging.info(f"Rolling back Service: {service_name}")
        # Implement rollback logic here

    def deploy_all_services(self):
        threads = []
        for service_name in self.config['services']:
            thread = threading.Thread(target=self.deploy_service, args=(service_name,))
            thread.start()
            threads.append(thread)

        for t in threads:
            t.join()

def main():
    config_dict = {
        'namespace': 'default',
        'replicas': 3,
        'private_registries': [
            {'url': 'https://my-private-registry.com', 
             'username': 'user', 
             'password': 'pass'}
        ],
        'config': {'key1': 'value1'},
        'services': {
            'service1': {'image': 'public-image:latest'},
            'service2': {'image': 'private-image:latest'}
        }
    }

    manager = DeploymentManager(config_dict)
    manager.authenticate_docker_registry()
    for service in config_dict['services']:
        manager.pull_docker_image(service['image'])
    manager.deploy_all_services()
    manager.update_configmap()
    manager.monitor_services()

if __name__ == '__main__':
    main()


