"""
#include <stdio.h>
#include <string.h>

char* append_dash_if_within_limit(const char* input, size_t limit) {
    size_t length = strlen(input);

    if (length >= limit)
        return strdup(input);

    char *output = malloc(length + 2); // +1 for dash, +1 for null terminator
    if (!output)
        return NULL;

    strcpy(output, input);
    strcat(output, "-");
    return output;
}

int main() {
    const char* test_str = "example";
    size_t limit = 10;

    char *result = append_dash_if_within_limit(test_str, limit);
    printf("%s\n", result);
    free(result);

    return 0;
}
