// Memory pool structure
typedef struct {
    void* buffer;
    pthread_mutex_t lock;
    unsigned int used_size;
} MemoryPool;

MemoryPool memory_pool = { .buffer = malloc(POOL_SIZE), .lock = PTHREAD_MUTEX_INITIALIZER, .used_size = 0 };

// Function to allocate memory from the custom pool
void* mem_pool_alloc(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used_size + size > POOL_SIZE) {
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL; // Pool out of space
    }
    void* ptr = (char*) memory_pool.buffer + memory_pool.used_size;
    memory_pool.used_size += size;
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

// Function to reset the memory pool, for reuse in tests or reinitializations
void mem_pool_reset() {
    pthread_mutex_lock(&memory_pool.lock);
    memory_pool.used_size = 0;
    pthread_mutex_unlock(&memory_pool.lock);
}

// Log function (simple implementation)
void log_memory_usage(const char* message) {
    printf("%s - Used: %u, Free: %lu\n", message, memory_pool.used_size, POOL_SIZE - memory_pool.used_size);
}

typedef struct {
    int fd;
    Measurement* measurements;
    Record* records;
    size_t measurement_count;
    size_t record_count;
} ThreadData;

pthread_mutex_t data_lock = PTHREAD_MUTEX_INITIALIZER;
float total_value_sum = 0.0;
size_t valid_floats_count = 0;

// Function to read, validate, and sanitize data from file descriptor
void* process_file(void* arg) {
    ThreadData* thread_data = (ThreadData*)arg;

    char buffer[256];
    while (read(thread_data->fd, buffer, sizeof(buffer)) > 0) {
        pthread_mutex_lock(&data_lock);

        // Process and validate data here...
        for (size_t i = 0; i < thread_data->measurement_count; ++i) {
            Measurement* measurement = &thread_data->measurements[i];

            // Example validation logic
            if (sscanf(buffer, "%f %31s %d", &measurement->value, measurement->string, &measurement->counter) == 3) {
                total_value_sum += measurement->value;
                valid_floats_count++;

                // Sanitize string to remove non-alphanumeric characters
                for (char* p = measurement->string; *p != '\0'; ++p) {
                    if (!isalnum((unsigned char)*p)) {
                        *p = '_';
                    }
                }
            }
        }

        pthread_mutex_unlock(&data_lock);
    }

    return NULL;
}

// Helper function to calculate and print the average of all valid float values
void calculate_and_print_average() {
    pthread_mutex_lock(&data_lock);
    if (valid_floats_count > 0) {
        float average = total_value_sum / valid_floats_count;
        printf("Average of valid measurements: %.2f\n", average);
    } else {
        printf("No valid measurements to calculate an average.\n");
    }
    pthread_mutex_unlock(&data_lock);
}

// Function to free allocated memory
void cleanup() {
    free(memory_pool.buffer);
    mem_pool_reset();
}

int main() {
    // Example initialization and thread creation
    int fd1 = 0; // Standard input for demonstration purposes
    Measurement* measurements = (Measurement*)mem_pool_alloc(10 * sizeof(Measurement));
    Record* records = (Record*)mem_pool_alloc(5 * sizeof(Record));

    ThreadData data = { .fd = fd1, .measurements = measurements, .records = records, 
                        .measurement_count = 10, .record_count = 5 };

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_file, &data) != 0) {
        perror("Failed to create thread");
        cleanup();
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    calculate_and_print_average();

    log_memory_usage("After processing");

    cleanup();

    return 0;
}
