#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // Example limit in bytes
#define RANDOM_STRING_LENGTH 10

typedef struct {
    float x, y;
} point;

typedef struct {
    double value;
    char str[RANDOM_STRING_LENGTH + 1];
    point pt;
} geometry;

// Custom memory pool structure
typedef struct MemoryPool {
    size_t total_size;
    void *memory;
    pthread_mutex_t lock;
} MemoryPool;

void* custom_malloc(MemoryPool *pool, size_t size);
void custom_free_all(MemoryPool *pool);

// Global memory pool
MemoryPool g_memory_pool = { .total_size = MAX_MEMORY_LIMIT, .lock = PTHREAD_MUTEX_INITIALIZER };

// External dependency for random number generation
double generate_random_double(double min, double max) {
    return (rand() / (RAND_MAX + 1.0)) * (max - min) + min;
}

char* generate_random_string(size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString = malloc(length + 1);
    if (!randomString) return NULL;

    for (size_t i = 0; i < length; i++) {
        randomString[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    randomString[length] = '\0';
    return randomString;
}

// Function to find the largest integer in an array
int find_largest(int *array, size_t n) {
    int max_value = array[0];
    for (size_t i = 1; i < n; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

// Thread-safe function to handle concurrent access
int thread_safe_find_largest(int *array, size_t n, pthread_mutex_t *mutex) {
    int largest;
    pthread_mutex_lock(mutex);
    largest = find_largest(array, n);
    pthread_mutex_unlock(mutex);
    return largest;
}

void initialize_geometry(geometry *geom, double min_val, double max_val) {
    geom->value = generate_random_double(min_val, max_val);
    char* randomStr = generate_random_string(RANDOM_STRING_LENGTH);
    if (randomStr) {
        strncpy(geom->str, randomStr, RANDOM_STRING_LENGTH);
        free(randomStr);
    }
    geom->pt.x = rand() / (RAND_MAX + 1.0);
    geom->pt.y = rand() / (RAND_MAX + 1.0);
}

void* custom_malloc(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->total_size < size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *allocated_memory = malloc(size);
    if (!allocated_memory) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pool->total_size -= size;

    pthread_mutex_unlock(&pool->lock);
    return allocated_memory;
}

void custom_free_all(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->memory) {
        free(pool->memory);
        pool->memory = NULL;
    }

    pool->total_size = MAX_MEMORY_LIMIT;

    pthread_mutex_unlock(&pool->lock);
}

// Main function demonstrating usage
void process_geometries() {
    double *doubles_array;
    char **char_arrays;
    point *points_array;
    geometry *geometry_array;

    // Initialize memory pool
    g_memory_pool.memory = malloc(g_memory_pool.total_size);
    if (!g_memory_pool.memory) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return;
    }

    size_t double_array_size = 100;
    size_t char_array_count = 50;
    size_t point_array_size = 50;
    size_t geometry_array_size = 30;

    // Allocate and initialize arrays
    doubles_array = (double*)custom_malloc(&g_memory_pool, double_array_size * sizeof(double));
    char_arrays = (char**)custom_malloc(&g_memory_pool, char_array_count * sizeof(char*));
    points_array = (point*)custom_malloc(&g_memory_pool, point_array_size * sizeof(point));
    geometry_array = (geometry*)custom_malloc(&g_memory_pool, geometry_array_size * sizeof(geometry));

    if (!doubles_array || !char_arrays || !points_array || !geometry_array) {
        fprintf(stderr, "Memory allocation failed\n");
        custom_free_all(&g_memory_pool);
        return;
    }

    // Initialize char arrays
    for (size_t i = 0; i < char_array_count; ++i) {
        char_arrays[i] = generate_random_string(RANDOM_STRING_LENGTH);
    }

    // Initialize points array
    for (size_t i = 0; i < point_array_size; ++i) {
        points_array[i].x = rand() / (RAND_MAX + 1.0f);
        points_array[i].y = rand() / (RAND_MAX + 1.0f);
    }

    // Initialize geometry array
    for (size_t i = 0; i < geometry_array_size; ++i) {
        initialize_geometry(&geometry_array[i], 0.0, 100.0);
    }

    // Read integers from standard input
    size_t n;
    printf("Enter the number of integers: ");
    scanf("%zu", &n);

    int *integers = (int*)custom_malloc(&g_memory_pool, n * sizeof(int));
    if (!integers) {
        fprintf(stderr, "Failed to allocate memory for integer array\n");
        custom_free_all(&g_memory_pool);
        return;
    }

    printf("Enter integers:\n");
    for (size_t i = 0; i < n; ++i) {
        scanf("%d", &integers[i]);
    }

    // Find the largest integer
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int largest = thread_safe_find_largest(integers, n, &mutex);
    printf("The largest integer is: %d\n", largest);

    // Cleanup
    custom_free_all(&g_memory_pool);
}

int main() {
    srand((unsigned)time(NULL));
    process_geometries();
    return 0;
}
