```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1024
#define MAX_THREADS 10

typedef struct {
    float x, y;
} Point;

typedef struct {
    double value;
    Point *location;
} Transaction;

typedef struct {
    void **memory_pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->memory_pool = (void**)malloc(initial_size * sizeof(void*));
    for (size_t i = 0; i < initial_size; ++i) {
        pool->memory_pool[i] = NULL;
    }
    pool->pool_size = initial_size;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void resize_memory_pool(MemoryPool *pool, size_t new_size) {
    void **new_pool = (void**)realloc(pool->memory_pool, new_size * sizeof(void*));
    for (size_t i = pool->pool_size; i < new_size; ++i) {
        new_pool[i] = NULL;
    }
    pool->memory_pool = new_pool;
    pool->pool_size = new_size;
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->pool_size; ++i) {
        if (pool->memory_pool[i] == NULL) {
            pool->memory_pool[i] = malloc(size);
            pthread_mutex_unlock(&pool->lock);
            return pool->memory_pool[i];
        }
    }
    resize_memory_pool(pool, pool->pool_size * 2);
    pthread_mutex_unlock(&pool->lock);
    return allocate_from_pool(pool, size); // Retry allocation after resizing
}

void free_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->pool_size; ++i) {
        if (pool->memory_pool[i] != NULL) {
            free(pool->memory_pool[i]);
        }
    }
    free(pool->memory_pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void initialize_random_point(Point *p) {
    p->x = rand() / (float)RAND_MAX;
    p->y = rand() / (float)RAND_MAX;
}

double random_double(double min, double max) {
    return min + (rand() / (RAND_MAX + 1.0)) * (max - min);
}

void initialize_transaction(Transaction *t, Point *p) {
    t->value = random_double(10.0, 100.0);
    t->location = p;
}

int main() {
    srand(time(NULL));

    MemoryPool *pool = create_memory_pool(INITIAL_POOL_SIZE);

    // Example: Allocate and initialize a Transaction
    Point *point = (Point*)allocate_from_pool(pool, sizeof(Point));
    initialize_random_point(point);
    Transaction *transaction = (Transaction*)allocate_from_pool(pool, sizeof(Transaction));
    initialize_transaction(transaction, point);

    printf("Transaction Value: %f\n", transaction->value);
    printf("Point Coordinates: (%f, %f)\n", point->x, point->y);

    free_memory_pool(pool);

    return 0;
}
```

