['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define data structures
typedef struct {
    int id;
    char *name;
    float value;
} Record;

typedef struct EventNode {
    time_t timestamp;
    int priority;
    char *details;
    struct EventNode* next;
} EventNode;

typedef struct Session {
    char *username;
    int access_count;
    Record record;
} Session;

typedef struct Category {
    int category_id;
    char *category_name;
    struct Category *subcategories;  // Pointer to a linked list of subcategories
} Category;

// Memory pool management structures and functions
#define POOL_SIZE 1024

typedef struct MemBlock {
    size_t size;
    struct MemBlock* next;
    int in_use;
} MemBlock;

static pthread_mutex_t mem_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static MemBlock* memory_pool_head = NULL;

void init_memory_pool() {
    void *pool_memory = malloc(POOL_SIZE);
    for (size_t i = 0; i < POOL_SIZE - sizeof(MemBlock); i += sizeof(MemBlock) + 128) { // Allocate in chunks
        MemBlock* block = (MemBlock*) ((char*) pool_memory + i);
        block->size = 128;
        block->next = memory_pool_head;
        block->in_use = 0;
        memory_pool_head = block;
    }
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&mem_pool_mutex);

    MemBlock *current = memory_pool_head;
    while (current != NULL) {
        if (!current->in_use && current->size >= size) {
            current->in_use = 1;
            pthread_mutex_unlock(&mem_pool_mutex);
            return (void*)(++current);
        }
        current = current->next;
    }

    // If no suitable block, expand pool
    void* new_memory = malloc(POOL_SIZE);
    for (size_t i = 0; i < POOL_SIZE - sizeof(MemBlock); i += sizeof(MemBlock) + 128) {
        MemBlock *block = (MemBlock*) ((char*) new_memory + i);
        block->size = 128;
        block->next = memory_pool_head;
        block->in_use = 0;
        memory_pool_head = block;
    }

    pthread_mutex_unlock(&mem_pool_mutex);

    return malloc(size); // Fallback to regular allocation if pool is still insufficient
}

void free_to_pool(void *ptr) {
    if (!ptr) return;

    MemBlock *block_ptr = (MemBlock*) ptr - 1;
    pthread_mutex_lock(&mem_pool_mutex);

    block_ptr->in_use = 0;

    pthread_mutex_unlock(&mem_pool_mutex);
}

// Data structure initializations
void initialize_data_structures(int array_size, const char* filename) {
    int **int_array = (int**) allocate_from_pool(sizeof(int*) * array_size);
    Record *records_array = (Record*) allocate_from_pool(sizeof(Record) * array_size);

    // Initialize record array with random values
