                std::cerr << "Failed to load and process data in thread." << std::endl;
            }
        });
    }

    for (auto& t : threads) {
        t.join();
    }
}

int main() {
    unitTest();

    // Call the helper function
    findAndPrintLargestInteger();

    return 0;
}
