typedef struct {
    long sensor_value;
    int key;
    char *sensor_name;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    unsigned long seed;
    // Add more fields for memory pool and logging as needed
} DynamicList;

// Custom memory pool structure (simplified)
typedef struct MemoryBlock {
    size_t size;
    bool free;
    void *ptr;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryBlock *memory_pool_head = NULL;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void *custom_malloc(size_t size) {
    pthread_mutex_lock(&pool_mutex);

    MemoryBlock *current = memory_pool_head;
    while (current) {
        if (current->free && current->size >= size) {
            current->free = false;
            pthread_mutex_unlock(&pool_mutex);
            return current->ptr;
        }
        current = current->next;
    }

    // Allocate new block if no suitable one found
    MemoryBlock *new_block = malloc(sizeof(MemoryBlock));
    new_block->size = size + sizeof(MemoryBlock);
    new_block->free = false;
    new_block->ptr = (char *)new_block + sizeof(MemoryBlock);
    new_block->next = memory_pool_head;

    pthread_mutex_unlock(&pool_mutex);
    return new_block->ptr;
}

void custom_free(void *ptr) {
    if (!ptr) return;

    pthread_mutex_lock(&pool_mutex);

    MemoryBlock *current = memory_pool_head;
    while (current) {
        if ((char *)current + sizeof(MemoryBlock) == ptr) {
            current->free = true;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool_mutex);
}

// Thread-safe function to initialize and populate the dynamic list
void initialize_dynamic_list(DynamicList *list, size_t initial_capacity, unsigned long seed) {
    if (!list) return;

    pthread_mutex_init(&list->mutex, NULL);

    list->records = (Record **)custom_malloc(initial_capacity * sizeof(Record *));
    list->capacity = initial_capacity;
    list->count = 0;
    list->seed = seed;

    srand(seed); // Initialize random number generator

    for (size_t i = 0; i < initial_capacity; ++i) {
        Record *record = (Record *)custom_malloc(sizeof(Record));

        record->sensor_value = rand() % 1000; // Random value within a range
        record->key = rand() % 100;
        size_t name_length = rand() % 20 + 1;

        record->sensor_name = (char *)custom_malloc(name_length);
        snprintf(record->sensor_name, name_length, "Sensor_%d", i);

        list->records[i] = record;
    }
}

// Thread-safe function to resize the dynamic list
void resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    if (!list || new_capacity <= list->capacity) return;

    pthread_mutex_lock(&list->mutex);

    Record **new_records = (Record **)custom_malloc(new_capacity * sizeof(Record *));
    memcpy(new_records, list->records, list->count * sizeof(Record *));

    custom_free(list->records);
    list->records = new_records;
    list->capacity = new_capacity;

    pthread_mutex_unlock(&list->mutex);
}

// Thread-safe helper function to compute statistics
void compute_statistics(const DynamicList *list, long *mean, long *median, long *max) {
    if (!list || !mean || !median || !max) return;

    pthread_mutex_lock(&list->mutex);

    long sum = 0;
    *max = list->records[0]->sensor_value;
    for (size_t i = 0; i < list->count; ++i) {
        Record *record = list->records[i];
        sum += record->sensor_value;
        if (record->sensor_value > *max) *max = record->sensor_value;
    }

    *mean = sum / list->count;

    // Calculate median
    long *values = (long *)custom_malloc(list->count * sizeof(long));
    for (size_t i = 0; i < list->count; ++i) {
        values[i] = list->records[i]->sensor_value;
    }

    qsort(values, list->count, sizeof(long), compare_long);
    if (list->count % 2 == 0) {
        *median = (values[list->count / 2 - 1] + values[list->count / 2]) / 2;
    } else {
        *median = values[list->count / 2];
    }

    custom_free(values);

    pthread_mutex_unlock(&list->mutex);
}

int compare_long(const void *a, const void *b) {
    return (*(long *)a - *(long *)b);
}

// Function to free the dynamic list and clean up resources
void cleanup_dynamic_list(DynamicList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        Record *record = list->records[i];
        custom_free(record->sensor_name);
        custom_free(record);
    }

    custom_free(list->records);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);

    // Clean up memory pool
    while (memory_pool_head) {
        MemoryBlock *current = memory_pool_head;
        memory_pool_head = current->next;
        free(current);
    }
}

// Example usage
int main() {
    DynamicList list;
    initialize_dynamic_list(&list, 10, 42);

    long mean, median, max;
    compute_statistics(&list, &mean, &median, &max);
    printf("Mean: %ld, Median: %ld, Max: %ld\n", mean, median, max);

    cleanup_dynamic_list(&list);
    return 0;
}
