#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_GEOMETRIES 10000

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    double value;
    char str[256];
    Point point;
    time_t timestamp;
    int active_flag;
} Geometry;

typedef struct {
    Geometry *geometries[MAX_GEOMETRIES];
    pthread_rwlock_t rwlock;
} GeometryPool;

typedef struct {
    size_t used;
    void *pool;
    size_t chunk_size;
    pthread_mutex_t lock;
} MemoryPool;

void* memory_pool_init(size_t total_size, size_t chunk_size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->used = 0;
    mp->chunk_size = chunk_size;
    mp->pool = malloc(total_size);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used + mp->chunk_size > sizeof(mp->pool)) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Out of memory
    }
    void *ptr = (char*)mp->pool + mp->used;
    mp->used += mp->chunk_size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void memory_pool_free(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

GeometryPool* geometry_pool_init() {
    GeometryPool *gp = malloc(sizeof(GeometryPool));
    for (int i = 0; i < MAX_GEOMETRIES; ++i) {
        gp->geometries[i] = NULL;
    }
    pthread_rwlock_init(&gp->rwlock, NULL);
    return gp;
}

Geometry* geometry_create(MemoryPool *mp) {
    Geometry *geom = memory_pool_alloc(mp);
    if (!geom) return NULL;
    geom->value = 0.0;
    strcpy(geom->str, "");
    geom->point.x = 0.0f;
    geom->point.y = 0.0f;
    geom->timestamp = time(NULL);
    geom->active_flag = 1;
    return geom;
}

void geometry_destroy(GeometryPool *gp, Geometry *geom) {
    pthread_rwlock_wrlock(&gp->rwlock);
    for (int i = 0; i < MAX_GEOMETRIES; ++i) {
        if (gp->geometries[i] == geom) {
            gp->geometries[i] = NULL;
            break;
        }
    }
    pthread_rwlock_unlock(&gp->rwlock);
}

void geometry_set(GeometryPool *gp, int index, Geometry *geom) {
    pthread_rwlock_wrlock(&gp->rwlock);
    if (index >= 0 && index < MAX_GEOMETRIES) {
        gp->geometries[index] = geom;
    }
    pthread_rwlock_unlock(&gp->rwlock);
}

Geometry* geometry_get(GeometryPool *gp, int index) {
    pthread_rwlock_rdlock(&gp->rwlock);
    Geometry *geom = NULL;
    if (index >= 0 && index < MAX_GEOMETRIES) {
        geom = gp->geometries[index];
    }
    pthread_rwlock_unlock(&gp->rwlock);
    return geom;
}

void log_geometry_change(Geometry *geom) {
    // Simple logging mechanism
    printf("Geometry changed: value=%f, str=%s\n", geom->value, geom->str);
}

void* memory_profiler(void *arg) {
    MemoryPool *mp = (MemoryPool*) arg;
    while (1) {
        pthread_mutex_lock(&mp->lock);
        size_t used = mp->used;
        printf("Memory usage: %zu bytes\n", used);
        pthread_mutex_unlock(&mp->lock);
        sleep(5); // Sample interval
    }
    return NULL;
}

void run_profiler(MemoryPool *mp) {
    pthread_t profiler_thread;
    pthread_create(&profiler_thread, NULL, memory_profiler, mp);
    pthread_detach(profiler_thread);
}

int main() {
    MemoryPool *mp = (MemoryPool*)memory_pool_init(1024 * 1024, sizeof(Geometry));
    GeometryPool *gp = geometry_pool_init();

    run_profiler(mp);

    Geometry *geom1 = geometry_create(mp);
    if (geom1) {
        geom1->value = 3.14;
        strcpy(geom1->str, "Test");
        geometry_set(gp, 0, geom1);
        log_geometry_change(geom1);
    }

    Geometry *geom2 = geometry_get(gp, 0);
    if (geom2) {
        printf("Retrieved: value=%f, str=%s\n", geom2->value, geom2->str);
    }

    memory_pool_free(mp);
    free(gp);

    return 0;
}
