// Custom memory pool for efficient resource management
template<typename T, size_t PoolSize>
class MemoryPool {
    std::unique_ptr<T[]> pool;
    std::queue<T*> freeList;

public:
    MemoryPool() : pool(std::make_unique<T[]>(PoolSize)) {
        for (size_t i = 0; i < PoolSize; ++i) {
            freeList.push(&pool[i]);
        }
    }

    T* allocate() {
        if (freeList.empty()) throw std::bad_alloc();
        T* ptr = freeList.front();
        freeList.pop();
        return ptr;
    }

    void deallocate(T* ptr) {
        freeList.push(ptr);
    }
};

// Point structure
struct point {
    float x, y;
};

// Geometry structure
struct geometry {
    double d;
    std::string s;
    point p;

    static geometry create_random(double range_min, double range_max, size_t string_length) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(range_min, range_max);
        geometry g;
        g.d = dis(gen);

        const char alphanum[] =
            "0123456789"
            "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
            "abcdefghijklmnopqrstuvwxyz";
        std::uniform_int_distribution<> dis_char(0, sizeof(alphanum) - 2);
        g.s.reserve(string_length);
        for (size_t i = 0; i < string_length; ++i) {
            g.s += alphanum[dis_char(gen)];
        }
        return g;
    }
};

// Concurrent queue
template<typename T>
class ThreadSafeQueue {
    std::queue<T> q;
    mutable std::mutex m;
    std::condition_variable cv;

public:
    void push(T value) {
        std::lock_guard<std::mutex> lock(m);
        q.push(std::move(value));
        cv.notify_one();
    }

    bool try_pop(T& value) {
        std::unique_lock<std::mutex> lock(m);
        if (q.empty()) return false;
        value = std::move(q.front());
        q.pop();
        return true;
    }

    void wait_and_pop(T& value) {
        std::unique_lock<std::mutex> lock(m);
        cv.wait(lock, [this] { return !q.empty(); });
        value = std::move(q.front());
        q.pop();
    }
};

// Helper function to find the largest integer
int find_largest(ThreadSafeQueue<int>& queue) {
    int max_val = INT_MIN;
    while (true) {
        int val;
        if (!queue.try_pop(val)) break;
        if (val > max_val) max_val = val;
    }
    return max_val;
}

