    // Allocate and initialize records
    records = (Record *)aligned_alloc(64, num_offsets * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation for records failed.\n");
        free_memory(offsets, keys, NULL);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_offsets; ++i) {
        records[i].offset_ptr = &offsets[i];
        records[i].key_ref = &keys[i];
    }

    // Validate the records
    if (validate_records(records, offsets, num_offsets) != 0) {
        fprintf(stderr, "Validation failed.\n");
        free_memory(offsets, keys, records);
        exit(EXIT_FAILURE);
    }

    return records;
}

int main() {
    int num_offsets = 100; // Example size
    Record *records = initialize_memory_blocks(num_offsets);

    // Use the initialized memory blocks...

    // Free allocated memory when done.
    free_memory(NULL, NULL, records);

    return 0;
}
