#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    float minValue;
    float maxValue;
    float stepSize;
    pthread_mutex_t lock;
} DynamicValueGenerator;

DynamicValueGenerator* createDynamicValueGenerator(const char* range) {
    DynamicValueGenerator* generator = (DynamicValueGenerator*)malloc(sizeof(DynamicValueGenerator));
    if (!generator) return NULL;

    // Initialize mutex
    pthread_mutex_init(&generator->lock, NULL);

    // Parse range string
    float minVal, maxVal;
    if (sscanf(range, "%f-%f", &minVal, &maxVal) == 2 || sscanf(range, "%f..%f", &minVal, &maxVal) == 2 ||
        sscanf(range, "%f-%f", &minVal, &maxVal) == 2 || sscanf(range, "%f..%f", &minVal, &maxVal) == 2) {

        // Default step size
        float step = (maxVal - minVal) / 100.0;

        pthread_mutex_lock(&generator->lock);
        generator->minValue = minVal;
        generator->maxValue = maxVal;
        generator->stepSize = step;
        pthread_mutex_unlock(&generator->lock);

    } else {
        fprintf(stderr, "Invalid range format.\n");
        free(generator);
        return NULL;
    }

    // Seed random number generator
    srand(time(NULL));

    return generator;
}

float get_random_float(DynamicValueGenerator* generator) {
    if (!generator) return 0.0;

    pthread_mutex_lock(&generator->lock);

    float range = generator->maxValue - generator->minValue;
    int steps = (int)(range / generator->stepSize);
    float randomStep = ((float)rand() / RAND_MAX) * steps;
    float value = generator->minValue + (randomStep * generator->stepSize);

    pthread_mutex_unlock(&generator->lock);

    return value;
}

int get_random_int(DynamicValueGenerator* generator) {
    if (!generator) return 0;

    pthread_mutex_lock(&generator->lock);

    int minInt = (int)(generator->minValue + 0.5);
    int maxInt = (int)(generator->maxValue - 0.5);
    int value = rand() % (maxInt - minInt + 1) + minInt;

    pthread_mutex_unlock(&generator->lock);

    return value;
}

void* get_random_list(DynamicValueGenerator* generator, int count, int** result) {
    if (!generator || !result) return NULL;

    *result = (int*)malloc(count * sizeof(int));
    if (!*result) return NULL;

    pthread_mutex_lock(&generator->lock);

    for (int i = 0; i < count; ++i) {
        (*result)[i] = get_random_int(generator);
    }

    pthread_mutex_unlock(&generator->lock);

    return *result;
}

void destroyDynamicValueGenerator(DynamicValueGenerator* generator) {
    if (!generator) return;

    pthread_mutex_destroy(&generator->lock);
    free(generator);
}

const char* toString(DynamicValueGenerator* generator) {
    static char str[50];
    if (!generator) return "null";

    pthread_mutex_lock(&generator->lock);

    snprintf(str, sizeof(str), "[%f, %f]", generator->minValue, generator->maxValue);

    pthread_mutex_unlock(&generator->lock);

    return str;
}

int main() {
    DynamicValueGenerator* generator = createDynamicValueGenerator("10.5-20.5");
    if (!generator) return 1;

    printf("Random Float: %f\n", get_random_float(generator));
    printf("Random Int: %d\n", get_random_int(generator));

    int* randomList;
    get_random_list(generator, 5, &randomList);
    printf("Random List: ");
    for (int i = 0; i < 5; ++i) {
        printf("%d ", randomList[i]);
    }
    printf("\n");

    free(randomList);
    destroyDynamicValueGenerator(generator);

    return 0;
}
```

