    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < size; ++i) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &arr[i]);
    }
    pthread_mutex_unlock(&mutex);

    int max_val = arr[0];
