}

// Main function to manage memory and initialize structures
void* manage_memory(void *arg) {
    int num_elements = *((int*)arg);

    long *offsets = malloc(num_elements * sizeof(long));
    int *keys = malloc(num_elements * sizeof(int));
    record *records = malloc(num_elements * sizeof(record));
    double *doubles = malloc(num_elements * sizeof(double));
    char **strings = malloc(num_elements * sizeof(char*));
    geometry *geometries = malloc(num_elements * sizeof(geometry));

    if (!offsets || !keys || !records || !doubles || !strings || !geometries) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        free(doubles);
        for (int i = 0; i < num_elements; ++i) free(strings[i]);
        free(strings);
        free(geometries);
        return NULL;
    }

    init_random();

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_elements; ++i) {
        offsets[i] = random_int(1, 10000);
        keys[i] = random_int(1, 10000);
        records[i].val = random_int(1, 10000);
        doubles[i] = random_double(0.0, 10.0);

