class NetworkDataAggregator {
private:
    std::unordered_set<std::string> sourceList;
    std::unordered_set<std::string> metricTypes;
    int intervalDuration; // in seconds
    mutable std::mutex mtx;

public:
    // Constructor with validation logic
    NetworkDataAggregator(const std::vector<std::string>& sources, 
                          const std::vector<std::string>& metrics,
                          int duration) {
        if (duration <= 0) throw std::invalid_argument("Interval duration must be positive.");

        for (const auto& source : sources) {
            if (!source.empty()) sourceList.insert(source);
        }
        for (const auto& metric : metrics) {
            if (!metric.empty()) metricTypes.insert(metric);
        }

        intervalDuration = duration;
    }

    // Add a data source
    void AddDataSource(const std::string& source) {
        std::lock_guard<std::mutex> lock(mtx);
        if (!source.empty()) sourceList.insert(source);
    }

    // Remove a data source
    void RemoveDataSource(const std::string& source) {
        std::lock_guard<std::mutex> lock(mtx);
        sourceList.erase(source);
    }

    // Asynchronous metric collection
    std::unordered_map<std::string, double> CollectMetrics() const {
        auto collect = [this]() -> std::unordered_map<std::string, double> {
            std::unordered_map<std::string, double> results;

            for (const auto& source : sourceList) {
                try {
                    // Simulate metric retrieval
                    std::this_thread::sleep_for(std::chrono::milliseconds(100)); // simulate network delay

                    // Dummy data collection logic
                    for (const auto& metricType : metricTypes) {
                        results[metricType] = static_cast<double>(rand()) / RAND_MAX * 100; // Dummy value
                    }
                } catch (...) {
                    std::cerr << "Failed to collect metrics from source: " << source << "\n";
                    // Implement fallback mechanism here if needed
                }
            }
            return results;
        };

        std::future<std::unordered_map<std::string, double>> futureResult = std::async(std::launch::async, collect);
        return futureResult.get();
    }

    // ToString method for displaying current configuration and status
    std::string ToString() const {
        std::lock_guard<std::mutex> lock(mtx);

        std::ostringstream oss;
        oss << "NetworkDataAggregator Configuration:\n";
        oss << "Active Data Sources: ";
        for (const auto& source : sourceList) {
            oss << source << ", ";
        }
        oss << "\nMetric Types: ";
        for (const auto& metric : metricTypes) {
            oss << metric << ", ";
        }
        oss << "\nAggregation Interval Duration: " << intervalDuration << " seconds\n";

        return oss.str();
    }

    // Destructor
    ~NetworkDataAggregator() = default;
};
