        auto fullPath = fs::path(rootDirectory) / filePath;
        if (!fs::exists(fullPath)) {
            return;
        }

        FileType fileType = determineFileType(filePath);
        if (std::find(fileTypeFilters.begin(), fileTypeFilters.end(), fileType) == fileTypeFilters.end()) {
            return;
        }

        // Assume a structure to update metadata exists
    }

    void GetFileList(std::vector<std::string>& fileNames, FileType type) const {
        std::lock_guard<std::mutex> lock(metadataMutex);

        for (const auto& entry : fs::recursive_directory_iterator(rootDirectory)) {
            if (!fs::is_regular_file(entry.status())) continue;

            auto fileType = determineFileType(entry.path().filename());
            if (fileType != type) continue;

            fileNames.push_back(entry.path().string());
        }
    }

    std::string ToString() const {
        std::lock_guard<std::mutex> lock(metadataMutex);

        std::ostringstream oss;
        oss << "Directory: " << rootDirectory << "\n";

        for (const auto& entry : fs::recursive_directory_iterator(rootDirectory)) {
            if (!fs::is_regular_file(entry.status())) continue;

            oss << entry.path().string() << ", Size: "
                << fs::file_size(entry.path()) << ", Type: " 
                << determineFileType(entry.path().filename()).name() << "\n";
        }

        return oss.str();
    }

private:
    FileType determineFileType(const std::filesystem::path& filePath) const {
        // Simplistic example, you can extend this logic as needed
        std::string ext = filePath.extension().string();
        if (ext == ".txt") return FileType::TEXT;
        if (ext == ".bin") return FileType::BINARY;
        if (ext == ".jpg" || ext == ".png") return FileType::IMAGE;

        throw std::runtime_error("Unsupported file type.");
    }
};
