// Session manager handling dynamic session management
class SessionManager {
public:
    using AllocFunc = std::function<void*(size_t)>;

    SessionManager() : allocFunc([](size_t size) { return ::operator new(size); }) {}

    void setAllocator(const AllocFunc& allocator) {
        allocFunc = allocator;
    }

    void* operator new(std::size_t size) {
        return memoryPool.allocate<char>(size);
    }

    void operator delete(void* ptr, std::size_t size) noexcept {
        memoryPool.deallocate(ptr, size);
    }

    SessionPtr createSession(const std::string& sessionId, const std::string& authToken) {
        auto session = std::shared_ptr<Session>(
            static_cast<Session*>(allocFunc(sizeof(Session))), [this](Session* p) { deallocate(p); });
        new (session.get()) Session(sessionId, authToken);
        return session;
