    CharStringArray *charStringArray;
    PointArray *pointArray;
    GeometryArray *geometryArray;
    IntegerArray *integerArray;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int activeThreads;
} ThreadData;

// Custom memory pool
#define POOL_SIZE 1024 * 1024 // 1 MB
static unsigned char memoryPool[POOL_SIZE];
static size_t poolOffset = 0;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateFromPool(size_t size) {
    pthread_mutex_lock(&poolMutex);
    if (poolOffset + size > POOL_SIZE) {
        pthread_mutex_unlock(&poolMutex);
        return NULL; // Pool exhausted
    }
    void *ptr = &memoryPool[poolOffset];
    poolOffset += size;
    pthread_mutex_unlock(&poolMutex);
    return ptr;
}

void freeMemory() {
    poolOffset = 0; // Reset the pool offset for reuse
}

// Function to generate a random alphanumeric string
char* generateRandomString(size_t length) {
    char *str = (char*)allocateFromPool(length + 1);
    if (!str) return NULL;
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length > 0 && str) {
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    }
    return str;
}

// Function to initialize structures
ThreadData* initStructures(size_t doubleArraySize, size_t charStringArraySize, size_t pointArraySize,
                           size_t geometryArraySize, size_t integerArraySize) {
    srand(time(NULL));

    ThreadData *threadData = (ThreadData*)allocateFromPool(sizeof(ThreadData));
    if (!threadData) return NULL;

    pthread_mutex_init(&threadData->mutex, NULL);
    pthread_cond_init(&threadData->cond, NULL);

    threadData->doubleArray = (DoubleArray*)allocateFromPool(sizeof(DoubleArray));
    threadData->charStringArray = (CharStringArray*)allocateFromPool(sizeof(CharStringArray));
    threadData->geometryArray = (GeometryArray*)allocateFromPool(sizeof(GeometryArray));
    threadData->integerArray = (IntegerArray*)allocateFromPool(sizeof(IntegerArray));

    if (!threadData->doubleArray || !threadData->charStringArray ||
        !threadData->geometryArray || !threadData->integerArray) {
        freeMemory();
        return NULL;
    }

    // Initialize DoubleArray
    threadData->doubleArray->data = (double*)allocateFromPool(doubleArraySize * sizeof(double));
    threadData->doubleArray->length = doubleArraySize;

    // Initialize CharStringArray
    threadData->charStringArray->strings = (char**)allocateFromPool(charStringArraySize * sizeof(char*));
    for (size_t i = 0; i < charStringArraySize; ++i) {
        size_t strLength = rand() % 10 + 1;
        threadData->charStringArray->strings[i] = generateRandomString(strLength);
    }
    threadData->charStringArray->length = charStringArraySize;

    // Initialize GeometryArray
    threadData->geometryArray->geometries = (struct {
        double value;
        char *string;
        Geometry geometry;
    }*)allocateFromPool(geometryArraySize * sizeof(struct {
        double value;
        char *string;
        Geometry geometry;
    }));
    for (size_t i = 0; i < geometryArraySize; ++i) {
        threadData->geometryArray->geometries[i].value = ((double)rand() / RAND_MAX) * 100.0;
        size_t strLength = rand() % 10 + 1;
        threadData->geometryArray->geometries[i].string = generateRandomString(strLength);
        threadData->geometryArray->geometries[i].geometry.point.x = ((float)rand() / RAND_MAX) * 100.0f;
        threadData->geometryArray->geometries[i].geometry.point.y = ((float)rand() / RAND_MAX) * 100.0f;
    }
    threadData->geometryArray->length = geometryArraySize;

    // Initialize IntegerArray
    printf("Enter %zu integers:\n", integerArraySize);
    threadData->integerArray->numbers = (int*)allocateFromPool(integerArraySize * sizeof(int));
    for (size_t i = 0; i < integerArraySize; ++i) {
        if (scanf("%d", &threadData->integerArray->numbers[i]) != 1) {
            freeMemory();
            return NULL;
        }
    }
    threadData->integerArray->length = integerArraySize;

    threadData->activeThreads = 0;

    return threadData;
}

// Function to calculate average of DoubleArray
double calculateAverage(DoubleArray *array) {
    if (!array || !array->data || array->length == 0) return 0.0;

    double sum = 0.0;
    for (size_t i = 0; i < array->length; ++i) {
        sum += array->data[i];
    }
    return sum / array->length;
}

// Cleanup function
void cleanup(ThreadData *threadData) {
    if (!threadData) return;

    free(threadData->doubleArray->data);
    for (size_t i = 0; i < threadData->charStringArray->length; ++i) {
        free(threadData->charStringArray->strings[i]);
    }
    free(threadData->charStringArray->strings);

    for (size_t i = 0; i < threadData->geometryArray->length; ++i) {
        free(threadData->geometryArray->geometries[i].string);
    }
    free(threadData->geometryArray->geometries);

    free(threadData->integerArray->numbers);
    pthread_mutex_destroy(&threadData->mutex);
    pthread_cond_destroy(&threadData->cond);
    free(threadData);
}

int main() {
    ThreadData *data = initStructures(10, 5, 0, 7, 3);
    if (!data) {
        fprintf(stderr, "Failed to initialize structures.\n");
        return EXIT_FAILURE;
    }

    double avg = calculateAverage(data->doubleArray);
    printf("Average of DoubleArray: %f\n", avg);

    cleanup(data);
    return EXIT_SUCCESS;
}
