#define MAX_INTS 10000

void process_integers(int sockfd) {
    int *ints = NULL;
    size_t current_size = 0;
    size_t count = 0;
    long total_memory_usage_kb = 0;
    long largest_integer = LONG_MIN;
    long sum_of_integers = 0;

    while (count < MAX_INTS) {
        int received_int;

        // Receive integer from socket
        ssize_t bytes_received = recv(sockfd, &received_int, sizeof(int), 0);
        if (bytes_received <= 0) {
            fprintf(stderr, "Error receiving data or connection closed\n");
            break;
        }

        // Allocate more memory if needed
        if (count >= current_size) {
            size_t new_size = count == 0 ? 1024 : current_size * 2; // Start with 1024 and double each time
            int *new_ints = realloc(ints, new_size * sizeof(int));
            if (!new_ints) {
                fprintf(stderr, "Memory allocation failed\n");
                close(sockfd);
                free(ints);
                return;
            }
            ints = new_ints;
            current_size = new_size;
            total_memory_usage_kb += (current_size - count) * sizeof(int) / 1024; // Track memory usage in KB
        }

        // Store integer and update statistics
        ints[count] = received_int;
        if (received_int > largest_integer) {
            largest_integer = received_int;
        }
        sum_of_integers += received_int;
        count++;
    }

    if (count == 0) {
        fprintf(stderr, "No integers were processed\n");
        close(sockfd);
        return;
    }

    double average = (double)sum_of_integers / count;

    // Print results
    printf("Largest integer: %ld\n", largest_integer);
    printf("Average of integers: %.2f\n", average);
    printf("Total memory usage: %.2lf KB\n", total_memory_usage_kb);

    // Free allocated memory and close socket
    free(ints);
    close(sockfd);
}
