// Memory Pool Definitions (Simple Example)
typedef struct {
    size_t size;
    void *memory;
} memory_pool_t;

memory_pool_t pool;

void init_memory_pool(size_t size) {
    pool.size = size;
    pool.memory = malloc(pool.size);
}

void* allocate_from_pool(size_t size) {
    if (pool.memory == NULL || size > pool.size) return NULL;
    void *block = pool.memory;
    pool.memory = ((char*)pool.memory) + size;
    pool.size -= size;
    return block;
}

void free_memory_pool() {
    free(pool.memory);
}

// Random Number Generator
double random_double(double min, double max) {
    return (rand() / (RAND_MAX + 1.0)) * (max - min) + min;
}

// Helper Functions for Initialization and Cleanup
void initialize_geometries(size_t num) {
    geometries = allocate_from_pool(num * sizeof(geometry_t));
    if (!geometries) {
        fprintf(stderr, "Failed to allocate memory for geometries.\n");
        exit(EXIT_FAILURE);
    }

    char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
