        geom->pt.x = random_double(0.0, 100.0);
        geom->pt.y = random_double(0.0, 100.0);
    }
}

void cleanup() {
    free_memory_pool();
    pthread_mutex_destroy(&lock);
}

// Thread-safe helper function to find the largest integer
