    int max_val = -1;
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < array_size; ++i) {
        if (integer_array[i] > max_val) {
            max_val = integer_array[i];
        }
    }

    pthread_mutex_unlock(&lock);
    return max_val;
}

// Thread function to handle input
void* process_input(void *arg) {
    int number;
    while (scanf("%d", &number) == 1) {
        pthread_mutex_lock(&lock);

        if (array_size < array_capacity) { // Assuming a defined array_capacity
            integer_array[array_size++] = number;
        }

        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

// Main Function
