    srand(time(NULL));
    size_t geometry_count = 10;  // Example count

    // Initialize memory pool and lock
    init_memory_pool(1024 * 1024);  // Example size: 1MB
    pthread_mutex_init(&lock, NULL);

    initialize_geometries(geometry_count);

    // Handle integer input in a separate thread
    pthread_t input_thread;
    if (pthread_create(&input_thread, NULL, process_input, NULL) != 0) {
