use reqwest::{Client, Error};
use std::sync::Arc;

fn create_http_client(url: &str, insecure: bool) -> Result<(), Error> {
    let client_builder = if insecure {
        ClientBuilder::new().danger_accept_invalid_certs(true)
    } else {
        ClientBuilder::new()
    };

    let client = Arc::new(client_builder.build()?)?;  // Use `Arc` for shared ownership in multithreading

    // Perform a GET request
    match client.get(url).send() {
        Ok(response) => {
            println!("Status: {}", response.status());
            if response.text().await.is_ok() {
                println!("Response text available.");
            }
        },
        Err(e) => eprintln!("Error sending request: {:?}", e),
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let url = "https://httpbin.org/get";  // Example URL
    create_http_client(url, false).await?;

    Ok(())
}
