    char identifier[16];
    void *metadata;
} GeoObject;

typedef struct {
    GeoObject *objects;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} MemoryPool;

void initialize_memory_pool(MemoryPool *pool, size_t initial_capacity) {
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->objects = (GeoObject *)malloc(sizeof(GeoObject) * pool->capacity);
    if (!pool->objects) exit(EXIT_FAILURE);

    pthread_mutex_init(&pool->mutex, NULL);
}

GeoObject *add_geo_object(MemoryPool *pool, float coordinate, const char *identifier, void *metadata) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        GeoObject *new_objects = (GeoObject *)realloc(pool->objects, sizeof(GeoObject) * new_capacity);
        if (!new_objects) exit(EXIT_FAILURE);

        pool->objects = new_objects;
        pool->capacity = new_capacity;
    }

    GeoObject *obj = &pool->objects[pool->count++];
    obj->coordinate = coordinate;
    snprintf(obj->identifier, sizeof(obj->identifier), "%s", identifier);
    obj->metadata = metadata;

    pthread_mutex_unlock(&pool->mutex);
    return obj;
}

void find_and_print_largest(const int *array, size_t size) {
    static pthread_mutex_t largest_mutex = PTHREAD_MUTEX_INITIALIZER;
    static int global_largest = INT_MIN;

    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&largest_mutex);
        if (array[i] > global_largest) {
            global_largest = array[i];
        }
        pthread_mutex_unlock(&largest_mutex);
    }

    printf("Largest integer: %d\n", global_largest);
}

void read_integers_and_find_largest(MemoryPool *pool, size_t num_ints) {
    int *array = (int *)malloc(sizeof(int) * num_ints);
    if (!array) exit(EXIT_FAILURE);

    for (size_t i = 0; i < num_ints; ++i) {
        if (scanf("%d", &array[i]) != 1) {
            free(array);
            exit(EXIT_FAILURE);
        }
    }

    find_and_print_largest(array, num_ints);
    free(array);
}

void deallocate_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    free(pool->objects);
    pool->count = 0;
    pool->capacity = 0;
    pthread_mutex_unlock(&pool->mutex);

    pthread_mutex_destroy(&pool->mutex);
