// Custom memory pool (simplified)
class MemoryPool {
public:
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        void* ptr = malloc_pool.allocate(size);
        if (!ptr) {
            ptr = ::operator new(size);
        }
        return ptr;
    }

    void deallocate(void* ptr, size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        free(ptr); // Simplified for demonstration
    }

private:
    tcmalloc::CentralFreeList malloc_pool{64 * 1024}; // Example pool size
    std::mutex mutex_;
};

// Point struct definition
struct Point {
    float x, y;
};

// Record struct definition
struct Record {
    int value;
    Point point;
};

// Deserialize and load function
void loadCompressedData(const std::string& filename) {
    MemoryPool memory_pool;

    // Open file
    std::ifstream file(filename, std::ios::binary | std::ios::in);
    if (!file.is_open()) return;

    // Decompress data (ZLIB example)
    const size_t bufferSize = 10 * 1024 * 1024; // 10 MB buffer
    char* buffer = static_cast<char*>(memory_pool.allocate(bufferSize));

    uLongf decompressed_size = bufferSize;
    if (uncompress(reinterpret_cast<Bytef*>(buffer), &decompressed_size,
                   reinterpret_cast<const Bytef*>("\x00\x00"), 2) != Z_OK) {
        memory_pool.deallocate(buffer, bufferSize);
        return;
    }

    // Deserialize data into custom structure
    size_t num_records = *reinterpret_cast<size_t*>(buffer); // Example header

    auto* offsets = reinterpret_cast<long*>(memory_pool.allocate(num_records * sizeof(long)));
    auto* keys = reinterpret_cast<int*>(memory_pool.allocate(num_records * sizeof(int)));
    auto* points = reinterpret_cast<Point*>(memory_pool.allocate(num_records * sizeof(Point)));
    auto* records = reinterpret_cast<Record*>(memory_pool.allocate(num_records * sizeof(Record)));

    // Populate arrays (simplified deserialization)
    std::memcpy(offsets, buffer + sizeof(size_t), num_records * sizeof(long));
    std::memcpy(keys, buffer + sizeof(size_t) + num_records * sizeof(long), num_records * sizeof(int));
    std::memcpy(points, buffer + sizeof(size_t) + num_records * (sizeof(long) + sizeof(int)), num_records * sizeof(Point));

    // Initialize records with random values
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100);

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = dis(gen);
        records[i].point = points[i];
    }

    // Clean up
    memory_pool.deallocate(offsets, num_records * sizeof(long));
    memory_pool.deallocate(keys, num_records * sizeof(int));
    memory_pool.deallocate(points, num_records * sizeof(Point));
    memory_pool.deallocate(records, num_records * sizeof(Record));
    memory_pool.deallocate(buffer, bufferSize);

    file.close();
}

// Thread-safe maximum finder
std::atomic<int> max_value{INT_MIN};
std::mutex mtx;

void findMaxInList(const std::vector<int>& list) {
    for (int value : list) {
        int current_max = max_value.load(std::memory_order_relaxed);
        while (value > current_max && !max_value.compare_exchange_weak(current_max, value,
                                                                        std::memory_order_release,
                                                                        std::memory_order_relaxed));
    }
}

void readInputAndFindMax() {
    std::vector<std::thread> threads;
    std::vector<int> global_list;

    for (int i = 0; i < 4; ++i) { // Example with 4 threads
        threads.emplace_back([&, i]() {
            int num_values;
            std::cin >> num_values;
            std::vector<int> local_list(num_values);
            for (int& value : local_list) {
                std::cin >> value;
            }

            // Lock-free addition to global list
            std::lock_guard<std::mutex> lock(mtx);
            global_list.insert(global_list.end(), local_list.begin(), local_list.end());

            findMaxInList(local_list);
        });
    }

    for (auto& t : threads) {
        if (t.joinable()) {
            t.join();
        }
    }

    std::cout << "Maximum value: " << max_value.load() << std::endl;
}

