        log_event("Failed to allocate memory for a new user.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    new_user->user_id = user_id;
    new_user->name = strdup(name);  // Assuming strdup is safe
    new_user->email = strdup(email);
    new_user->pending_requests_count = 0;
    new_user->pending_request_ids = (int*)malloc(sizeof(int) * INITIAL_REQUEST_CAPACITY);

    if (!new_user->name || !new_user->email || !new_user->pending_request_ids) {
        log_event("Failed to allocate memory for user details.");
        pthread_mutex_unlock(&mutex);
        // Cleanup
        memory_pool_free(&pool, new_user);
        return NULL;
    }

    user_profiles[user_count++] = new_user;

    pthread_mutex_unlock(&mutex);
    log_event("New user created successfully.");
    return new_user;
}

// Add a friend request from one user to another
void add_friend_request(int from_user_id, int to_user_id) {
    pthread_mutex_lock(&mutex);

    UserProfile *from_user = NULL, *to_user = NULL;

    for (int i = 0; i < user_count; ++i) {
        if (user_profiles[i]->user_id == from_user_id)
            from_user = user_profiles[i];
        if (user_profiles[i]->user_id == to_user_id)
            to_user = user_profiles[i];

        if (from_user && to_user)
            break;
    }

    if (!to_user) {
        log_event("User not found for friend request.");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Handle potential reallocation of pending_request_ids
    if (to_user->pending_requests_count >= INITIAL_REQUEST_CAPACITY) {
        int *new_array = (int*)realloc(to_user->pending_request_ids, sizeof(int) * (INITIAL_REQUEST_CAPACITY * 2));
        if (!new_array) {
            log_event("Failed to expand friend request list.");
            pthread_mutex_unlock(&mutex);
            return;
        }
        to_user->pending_request_ids = new_array;
    }

    to_user->pending_request_ids[to_user->pending_requests_count++] = from_user_id;

    pthread_mutex_unlock(&mutex);
    log_event("Friend request added successfully.");
}

// Retrieve a user profile by ID
UserProfile* get_user_profile(int user_id) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < user_count; ++i) {
        if (user_profiles[i]->user_id == user_id) {
            pthread_mutex_unlock(&mutex);
            return user_profiles[i];
        }
    }

    pthread_mutex_unlock(&mutex);
    log_event("User profile not found.");
    return NULL;
}

// Process pending friend requests for a given user
void process_friend_requests(int user_id) {
    pthread_mutex_lock(&mutex);

    UserProfile *user = get_user_profile(user_id);
    if (!user) {
        log_event("Failed to find user for processing requests.");
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (int i = 0; i < user->pending_requests_count; ++i) {
        // Process each friend request (pseudo-code)
        int requester_id = user->pending_request_ids[i];

        // Assume a function to accept or deny requests
        if (accept_or_deny_request(requester_id, user_id)) {
            log_event("Friend request accepted.");
        } else {
            log_event("Friend request denied.");
        }
    }

    // Clear pending requests after processing
    free(user->pending_request_ids);
    user->pending_requests_count = 0;
    user->pending_request_ids = (int*)malloc(sizeof(int) * INITIAL_REQUEST_CAPACITY);

    pthread_mutex_unlock(&mutex);
}

// Log events for monitoring and debugging purposes
void log_event(const char *event) {
    // Efficient logging implementation that minimizes performance impact
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen("system.log", "a");
        if (!log_file) return;  // Handle failure to open log file
    }

    pthread_mutex_lock(&mutex);
    fprintf(log_file, "%s\n", event);
    fflush(log_file);  // Ensure immediate write for high reliability
    pthread_mutex_unlock(&mutex);
}
