#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure for records
typedef struct {
    long offset;
    int key;
    int value;
    time_t timestamp;
    char* metadata;
    double latitude;
    double longitude;
} Record;

// Define the memory pool
#define POOL_SIZE 1024 * 1024 // 1 MB pool size for demonstration

typedef struct {
    unsigned char* start;
    unsigned char* current;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool create_memory_pool() {
    MemoryPool pool;
    pool.start = (unsigned char*)malloc(POOL_SIZE);
    pool.current = pool.start;
    pthread_mutex_init(&pool.lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->start);
    pthread_mutex_destroy(&pool->lock);
}

// Function to allocate memory from the pool
void* pool_alloc(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current + size > pool->start + POOL_SIZE) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Out of memory
    }
    void* ptr = pool->current;
    pool->current += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to create records with dynamic allocation and initialization
Record** create_records(int num_records, MemoryPool* mem_pool) {
    Record** records = (Record**)pool_alloc(mem_pool, num_records * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record pointers\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        Record* record = (Record*)pool_alloc(mem_pool, sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for a record at index %d\n", i);
            // Free previously allocated records
            while (--i >= 0)
                free(records[i]);
            free(records);
            return NULL;
        }

        record->offset = (long)i; // Example initialization
        record->key = rand() % 100; // Example initialization
        record->value = rand() % 100; // Example initialization
        record->timestamp = time(NULL); // Current timestamp
        record->metadata = strdup("Example metadata"); // Example initialization

        if (!record->metadata) {
            fprintf(stderr, "Failed to allocate memory for metadata at index %d\n", i);
            free(record); // Free the record
            while (--i >= 0)
                free(records[i]);
            free(records);
            return NULL;
        }

        record->latitude = (double)(rand() % 180 - 90) / 10.0; // Random latitude
        record->longitude = (double)(rand() % 360 - 180) / 10.0; // Random longitude

        records[i] = record;
    }

    return records;
}

// Thread-safe logging function
void log_message(const char* message, int level) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&log_lock);
    printf("Log [%d]: %s\n", level, message); // Placeholder for actual logging integration
    pthread_mutex_unlock(&log_lock);
}

// Example of usage with thread safety
void* record_worker(void* args) {
    int num_records = *((int*)args);
    MemoryPool mem_pool = create_memory_pool();

    Record** records = create_records(num_records, &mem_pool);
    if (records) {
        log_message("Records created successfully", 1);

        // Simulate processing...

        for (int i = 0; i < num_records; ++i) {
            free(records[i]->metadata); // Free the metadata string
            free(records[i]); // Free each record
        }
        free(records); // Free the array of pointers
    } else {
        log_message("Failed to create records", 0);
    }

    destroy_memory_pool(&mem_pool);
    return NULL;
}

int main() {
    const int num_threads = 4;
    pthread_t threads[num_threads];
    int thread_args[num_threads] = {100, 200, 300, 400}; // Example: different record counts per thread

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, record_worker, &thread_args[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_message("All threads completed", 2);

    return 0;
}
