#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    float x;
    float y;
} point;

typedef struct {
    double value;
    char *str;
    point pt;
} geometry;

typedef struct {
    double *data;
    size_t length;
} DoubleArray;

typedef struct {
    char **strings;
    size_t count;
} CharStringArray;

typedef struct {
    point *points;
    size_t count;
} PointArray;

typedef struct {
    geometry *geometries;
    size_t count;
} GeometryArray;

typedef struct {
    int *numbers;
    size_t capacity;
    size_t used;
} IntegerArray;

#define ALPHANUMERIC_CHARS "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Memory pool structure
typedef struct {
    void *memory_pool;
    size_t total_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool global_memory_pool;

void init_memory_pool(size_t size) {
    pthread_mutex_init(&global_memory_pool.lock, NULL);
    global_memory_pool.memory_pool = malloc(size);
    global_memory_pool.total_size = size;
}

void free_memory_pool() {
    pthread_mutex_destroy(&global_memory_pool.lock);
    free(global_memory_pool.memory_pool);
}

void* pool_alloc(size_t size) {
    pthread_mutex_lock(&global_memory_pool.lock);
    if (size <= global_memory_pool.total_size) {
        void *allocated_memory = malloc(size);
        pthread_mutex_unlock(&global_memory_pool.lock);
        return allocated_memory;
    }
    pthread_mutex_unlock(&global_memory_pool.lock);
    return NULL;
}

void pool_free(void *ptr) {
    free(ptr);
}

char* generate_random_string(size_t length) {
    char *str = (char*)pool_alloc(length + 1);
    for (size_t i = 0; i < length; ++i) {
        str[i] = ALPHANUMERIC_CHARS[rand() % (sizeof(ALPHANUMERIC_CHARS) - 1)];
    }
    str[length] = '\0';
    return str;
}

void init_structures(DoubleArray *da, CharStringArray *csa, PointArray *pa, GeometryArray *ga, IntegerArray *ia) {
    pthread_mutex_lock(&mutex);

    // Initialize DoubleArray
    da->length = 10; // Example size
    da->data = (double*)pool_alloc(da->length * sizeof(double));
    for (size_t i = 0; i < da->length; ++i) {
        da->data[i] = (double)i;
    }

    // Initialize CharStringArray
    csa->count = 5; // Example count
    csa->strings = (char**)pool_alloc(csa->count * sizeof(char*));
    for (size_t i = 0; i < csa->count; ++i) {
        csa->strings[i] = generate_random_string(10);
    }

    // Initialize PointArray
    pa->count = 5; // Example count
    pa->points = (point*)pool_alloc(pa->count * sizeof(point));
    for (size_t i = 0; i < pa->count; ++i) {
        pa->points[i].x = rand() % 100;
        pa->points[i].y = rand() % 100;
    }

    // Initialize GeometryArray
    ga->count = 5; // Example count
    ga->geometries = (geometry*)pool_alloc(ga->count * sizeof(geometry));
    for (size_t i = 0; i < ga->count; ++i) {
        ga->geometries[i].value = ((double)rand() / RAND_MAX) * 100.0;
        ga->geometries[i].str = generate_random_string(15);
        ga->geometries[i].pt.x = rand() % 100;
        ga->geometries[i].pt.y = rand() % 100;
    }

    // Initialize IntegerArray
    ia->capacity = 10; // Example capacity
    ia->used = 0;
    ia->numbers = (int*)pool_alloc(ia->capacity * sizeof(int));

    pthread_mutex_unlock(&mutex);
}

void append_integer(IntegerArray *ia, int value) {
    pthread_mutex_lock(&mutex);

    if (ia->used == ia->capacity) {
        ia->capacity *= 2;
        ia->numbers = (int*)pool_alloc(ia->capacity * sizeof(int));
        memcpy(ia->numbers, ia->numbers, ia->used * sizeof(int)); // Move data
    }

    ia->numbers[ia->used++] = value;

    pthread_mutex_unlock(&mutex);
}

void read_integers_from_stdin(IntegerArray *ia) {
    char input[256];
    while (fgets(input, sizeof(input), stdin)) {
        int num;
        if (sscanf(input, "%d", &num) == 1) {
            append_integer(ia, num);
        } else {
            printf("Invalid input. Please enter a valid integer.\n");
        }
    }
}

void persist_integers_to_disk(const IntegerArray *ia, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (file != NULL) {
        for (size_t i = 0; i < ia->used; ++i) {
            fprintf(file, "%d\n", ia->numbers[i]);
        }
        fclose(file);
    }
}

void free_structures(DoubleArray *da, CharStringArray *csa, PointArray *pa, GeometryArray *ga, IntegerArray *ia) {
    pthread_mutex_lock(&mutex);

    if (da->data != NULL) pool_free(da->data);
    for (size_t i = 0; i < csa->count; ++i) {
        pool_free(csa->strings[i]);
    }
    pool_free(csa->strings);

    if (pa->points != NULL) pool_free(pa->points);
    for (size_t i = 0; i < ga->count; ++i) {
        pool_free(ga->geometries[i].str);
    }
    pool_free(ga->geometries);

    if (ia->numbers != NULL) pool_free(ia->numbers);

    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL));
    init_memory_pool(1024 * 1024); // Initialize memory pool with 1 MB

    DoubleArray da;
    CharStringArray csa;
    PointArray pa;
    GeometryArray ga;
    IntegerArray ia;

    init_structures(&da, &csa, &pa, &ga, &ia);

    printf("Enter integers (Ctrl+D to finish):\n");
    read_integers_from_stdin(&ia);

    persist_integers_to_disk(&ia, "integers.txt");

    free_structures(&da, &csa, &pa, &ga, &ia);
    free_memory_pool();

    return 0;
}
