#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char *metadata;
} Record;

typedef struct MemoryPool {
    void *memory;          // Pointer to the pool memory
    size_t total_size;     // Total allocated size of the pool
    size_t used_size;      // Currently used memory within the pool
    pthread_mutex_t lock;  // Mutex for thread-safe access
} MemoryPool;

typedef struct ReferenceCounted {
    void *data;
    int ref_count;
    pthread_mutex_t lock;
} ReferenceCounted;

// Function prototypes
MemoryPool* create_memory_pool(size_t size);
void destroy_memory_pool(MemoryPool *pool, ReferenceCounted **records, size_t record_count);
Record* allocate_record(MemoryPool *pool, const char *metadata_template, size_t *record_size);
int initialize_data_structures(size_t thread_limit, size_t num_keys,
                               long ***offsets, int **keys, Record ***records);

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory = malloc(size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pool->total_size = size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool *pool, ReferenceCounted **records, size_t record_count) {
    if (!pool) return;

    for (size_t i = 0; i < record_count; ++i) {
        if (--records[i]->ref_count == 0) {
            free(records[i]->data);
            pthread_mutex_destroy(&records[i]->lock);
            free(records[i]);
        }
    }

    pthread_mutex_lock(&pool->lock);
    free(pool->memory);
    pool->used_size = 0;
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record* allocate_record(MemoryPool *pool, const char *metadata_template, size_t *record_size) {
    ReferenceCounted *ref_counted;

    pthread_mutex_lock(&pool->lock);
    if (pool->used_size + sizeof(Record) + strlen(metadata_template) >= pool->total_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    ref_counted = malloc(sizeof(ReferenceCounted));
    if (!ref_counted) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_init(&ref_counted->lock, NULL);

    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        free(ref_counted);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    record->value = 0; // Initialize with a default value
    record->metadata = malloc(strlen(metadata_template) + 1);
    if (!record->metadata) {
        free(record);
        free(ref_counted);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    strcpy(record->metadata, metadata_template);

    ref_counted->data = record;
    ref_counted->ref_count = 1;

    pool->used_size += sizeof(Record) + strlen(metadata_template) + 1;

    pthread_mutex_unlock(&pool->lock);
    *record_size = sizeof(Record) + strlen(metadata_template) + 1;

    return record;
}

int initialize_data_structures(size_t thread_limit, size_t num_keys,
                               long ***offsets, int **keys, Record ***records) {
    MemoryPool *pool = create_memory_pool(thread_limit);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return -1;
    }

    ReferenceCounted **ref_records = calloc(num_keys, sizeof(ReferenceCounted *));
    if (!ref_records) {
        destroy_memory_pool(pool, NULL, 0);
        fprintf(stderr, "Memory allocation failed for reference records\n");
        return -1;
    }

    *offsets = malloc(sizeof(long *) * num_keys);
    *keys = malloc(sizeof(int) * num_keys);
    *records = malloc(sizeof(Record *) * num_keys);

    if (!(*offsets || *keys || *records)) {
        for (size_t i = 0; i < num_keys; ++i) free(ref_records[i]);
        free(ref_records);
        destroy_memory_pool(pool, ref_records, num_keys);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    size_t record_size;
    for (size_t i = 0; i < num_keys; ++i) {
        (*offsets)[i] = malloc(sizeof(long));
        if (!(*offsets)[i]) goto error;

        (*keys)[i] = i; // Simple key initialization

        ref_records[i] = malloc(sizeof(ReferenceCounted));
        if (!ref_records[i]) goto error;
        pthread_mutex_init(&ref_records[i]->lock, NULL);

        const char *metadata_template = "Metadata"; // Example template
