typedef struct MemoryPool {
    void* start;
    void* current;
    pthread_mutex_t lock;
} MemoryPool;

// Initialize the memory pool
void init_memory_pool(MemoryPool* pool, size_t size) {
    pool->start = malloc(size);
    pool->current = pool->start;
    pthread_mutex_init(&pool->lock, NULL);
}

// Allocate memory from the pool
void* pool_allocate(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current + size > pool->start + POOL_SIZE) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(EXIT_FAILURE);
    }
    void* ptr = pool->current;
    pool->current += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Deallocate the entire memory pool
void free_memory_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->start);
}

