    record* records = malloc(record_array_size);
    log_memory_operation(record_array_size, "allocate");
    if (!records) {
        perror("Failed to allocate memory for record array");
        free(keys);
        log_memory_operation(int_array_size, "deallocate");
        free(offsets);
        log_memory_operation(long_array_size, "deallocate");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Set each record's value to a random integer within the specified range
    for (int i = 0; i < max_records; ++i) {
        records[i].value = rand() % 100 + 1; // Example range: [1, 100]
