        struct ListNode* new_node = malloc(sizeof(struct ListNode));
        log_memory_operation(sizeof(struct ListNode), "allocate");
        if (!new_node) {
            perror("Failed to allocate memory for list node");
            pthread_mutex_unlock(&list_lock);
            return;
        }
        new_node->data = data;
        new_node->next = *head;
        *head = new_node;
        pthread_mutex_unlock(&list_lock);
    }

    // Example insertion
