        free(offsets);
        log_memory_operation(sizeof(long) * max_records, "deallocate");

        free(keys);
        log_memory_operation(sizeof(int) * max_records, "deallocate");

        while (head) {
            struct ListNode* temp = head;
            head = head->next;
            free(temp);
            log_memory_operation(sizeof(struct ListNode), "deallocate");
        }

        pthread_mutex_destroy(&list_lock);
