#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>

#define MAX_HASH_TABLE_SIZE 10000

typedef struct {
    int value;
    time_t last_accessed;
} Record;

typedef struct HashNode {
    int key;
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // For resizing and basic operations
    pthread_rwlock_t rwlock; // For read-write access to hash table
} HashTable;

static inline uint32_t hash_function(int key, size_t capacity) {
    return (uint32_t)(key % capacity);
}

HashTable* create_hash_table(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_HASH_TABLE_SIZE) {
        fprintf(stderr, "Invalid table capacity\n");
        return NULL;
    }

    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }

    table->buckets = calloc(initial_capacity, sizeof(HashNode*));
    if (!table->buckets) {
        perror("Failed to allocate memory for buckets");
        free(table);
        return NULL;
    }

    table->capacity = initial_capacity;
    table->size = 0;

    pthread_mutex_init(&table->lock, NULL);
    pthread_rwlock_init(&table->rwlock, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next_node = node->next;
            free(node);
            node = next_node;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    pthread_rwlock_destroy(&table->rwlock);
    free(table);
}

int hash_table_insert(HashTable* table, int key, Record record) {
    if (!table || !table->buckets) return 0;

    size_t index = hash_function(key, table->capacity);

    HashNode* node = malloc(sizeof(HashNode));
    if (!node) {
        perror("Failed to allocate memory for new hash node");
        return 0;
    }

    node->key = key;
    node->record = record;
    node->next = NULL;

    pthread_mutex_lock(&table->lock);

    HashNode* head = table->buckets[index];
    if (!head) {
        table->buckets[index] = node;
    } else {
        while (head->next)
            head = head->next;
        head->next = node;
    }

    ++table->size;

    if ((double)table->size / (double)table->capacity >= 1.5) {
        // Resize logic
        size_t new_capacity = table->capacity * 2;
        if (new_capacity > MAX_HASH_TABLE_SIZE) break;

        HashNode** new_buckets = calloc(new_capacity, sizeof(HashNode*));
        if (!new_buckets) {
            perror("Failed to allocate memory for new buckets");
            pthread_mutex_unlock(&table->lock);
            free(node);
            return 0;
        }

        for (size_t i = 0; i < table->capacity; ++i) {
            HashNode* head = table->buckets[i];
            while (head) {
                size_t index = hash_function(head->key, new_capacity);
                HashNode* next_node = head->next;

                head->next = new_buckets[index];
                new_buckets[index] = head;

                head = next_node;
            }
        }

        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }

    pthread_mutex_unlock(&table->lock);

    return 1;
}

Record* hash_table_get(HashTable* table, int key) {
    if (!table || !table->buckets) return NULL;

    size_t index = hash_function(key, table->capacity);
    HashNode* node = table->buckets[index];

    pthread_rwlock_rdlock(&table->rwlock);

    while (node) {
        if (node->key == key) {
            node->record.last_accessed = time(NULL); // Update last accessed time
            pthread_rwlock_unlock(&table->rwlock);
            return &(node->record);
        }
        node = node->next;
    }

    pthread_rwlock_unlock(&table->rwlock);

    return NULL;
}

size_t hash_table_size(HashTable* table) {
    if (!table || !table->buckets) return 0;

    size_t size = 0;

    pthread_mutex_lock(&table->lock);
    size = table->size;
    pthread_mutex_unlock(&table->lock);

    return size;
}

// Example usage
int main() {
    HashTable* table = create_hash_table(100); // Starting with capacity of 100

    if (!table) exit(EXIT_FAILURE);

    for (int i = 0; i < 1500; ++i) { // Insert more than initial capacity to trigger resize
        Record record = { .value = rand() % 100, .last_accessed = time(NULL) };
        hash_table_insert(table, rand() % 2000, record); // Random keys between 0 and 1999
    }

    for (int i = 0; i < 10; ++i) {
        int key_to_find = rand() % 2000;
        Record* record = hash_table_get(table, key_to_find);
        if (record) {
            printf("Key: %d, Value: %d\n", key_to_find, record->value);
        } else {
            printf("Key not found: %d\n", key_to_find);
        }
    }

    printf("Total records in hash table: %zu\n", hash_table_size(table));

    destroy_hash_table(table);

    return 0;
}
