    void *pool;           // Pointer to the memory pool
    size_t total_size;    // Total size of the memory pool in bytes
    size_t used_size;     // Currently used size of the memory pool
    pthread_mutex_t lock; // Mutex for thread-safe operations
} MemoryPool;

// Function prototypes
MemoryPool* create_memory_pool(size_t initial_size);
void destroy_memory_pool(MemoryPool *mpool);
Record* allocate_record(MemoryPool *mpool, int key, const char *initial_metadata);
void free_record(Record *record);

// Utility function to log memory allocation failures and resource limits exceeded
static void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mpool = malloc(sizeof(MemoryPool));
    if (!mpool) {
        log_error("Failed to allocate memory for memory pool.");
        return NULL;
    }

    pthread_mutex_init(&mpool->lock, NULL);
    mpool->pool = malloc(initial_size);
    if (!mpool->pool) {
        free(mpool);
        log_error("Failed to allocate initial memory pool.");
        return NULL;
    }

    mpool->total_size = initial_size;
    mpool->used_size = 0;

    return mpool;
}

void destroy_memory_pool(MemoryPool *mpool) {
    if (mpool) {
        pthread_mutex_destroy(&mpool->lock);
        free(mpool->pool);
        free(mpool);
    }
}

Record* allocate_record(MemoryPool *mpool, int key, const char *initial_metadata) {
    pthread_mutex_lock(&mpool->lock);

    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        log_error("Failed to allocate memory for record.");
        pthread_mutex_unlock(&mpool->lock);
        return NULL;
    }

    size_t metadata_size = strlen(initial_metadata) + 1; // Include null terminator
    if (metadata_size > METADATA_INITIAL_SIZE)
        metadata_size = METADATA_INITIAL_SIZE;

    char *metadata = malloc(metadata_size);
    if (!metadata) {
        free(record);
        log_error("Failed to allocate memory for metadata.");
        pthread_mutex_unlock(&mpool->lock);
        return NULL;
    }

    strncpy(metadata, initial_metadata, metadata_size - 1);
    metadata[metadata_size - 1] = '\0';

    record->key = key;
    record->value = 0; // Default value
    record->metadata = metadata;

    pthread_mutex_unlock(&mpool->lock);

    return record;
}

void free_record(Record *record) {
    if (record) {
        free(record->metadata);
        free(record);
    }
}
```

### Explanation:
- **MemoryPool Structure**: Manages memory allocation and keeps track of the used size. It includes a mutex for thread-safe operations.

- **create_memory_pool()**: Initializes a memory pool with a specified initial size, setting up necessary locks.

- **destroy_memory_pool()**: Cleans up resources when a memory pool is no longer needed.

- **allocate_record()**: Allocates and initializes a `Record` within the context of a given memory pool. It employs an initial fixed allocation for metadata that can grow based on requirements.

- **free_record()**: Frees the allocated `Record`, ensuring all associated dynamic memory (like the metadata string) is released correctly.

This implementation provides a scalable, thread-safe foundation for processing variable-sized data structures efficiently, with room for further optimization and enhancement as needed.']

