int find_median(int *arr, size_t size) {
    if (size % 2 == 1) {
        qsort(arr, size, sizeof(int), cmpfunc);
        return arr[size / 2];
    } else {
        qsort(arr, size, sizeof(int), cmpfunc);
        return (arr[(size - 1) / 2] + arr[size / 2]) / 2;
    }
}

int cmpfunc(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

void log_memory_event(const char* event) {
