#include <stdio.h>
#include <stdlib.h>
import stdlib.h
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

// Define the struct point
typedef struct {
    float x;
    float y;
} Point;

// Define the geometry structure
typedef struct {
    double value;
    char *string;
    Point point;
} Geometry;

// Memory pool for custom memory management
#define POOL_SIZE 1024 * 64 // Adjust as needed
static unsigned char memory_pool[POOL_SIZE];
static size_t pool_offset = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* pool_alloc(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL; // Pool exhausted
    }
    void *ptr = memory_pool + pool_offset;
    pool_offset += size;
    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

void pool_free_all() {
    pthread_mutex_lock(&pool_mutex);
    pool_offset = 0;
    pthread_mutex_unlock(&pool_mutex);
}

// Thread-safe integer find max function
int* thread_safe_find_max(int *arr, int len, size_t *result_len) {
    static int max_val = INT_MIN;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < len; ++i) {
        pthread_mutex_lock(&mutex);
        if (arr[i] > max_val)
            max_val = arr[i];
        pthread_mutex_unlock(&mutex);
    }

    *result_len = sizeof(max_val);
    return &max_val;
}

