#define ALPHANUMERIC_CHARS "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
#define NUM_ALPHANUMERIC 62

typedef struct Node {
    void *data;
    struct Node *next;
} Node;

typedef struct Record {
    char string[50];
    float score;
    struct Node *linked_list;
} Record;

typedef struct Event {
    time_t event_time;
    int priority;
    char *description;
    struct Event *next;
} Event;

typedef struct {
    void *memory_pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t event_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to initialize memory pool
MemoryPool* init_memory_pool(size_t pool_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory_pool = malloc(pool_size);
    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }
    pool->pool_size = pool_size;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

// Helper function to allocate from memory pool
void* allocate_from_pool(MemoryPool *pool, size_t size) {
    if (size > pool->pool_size) return NULL;

    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc(size); // Simulate allocation; consider managing a free list in practice
    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

// Helper function to deallocate from memory pool
void deallocate_from_pool(MemoryPool *pool, void *ptr) {
    if (ptr) {
        pthread_mutex_lock(&pool->lock);
        free(ptr); // Simulate deallocation; manage a free list in practice
        pthread_mutex_unlock(&pool->lock);
    }
}

// Helper function to generate random alphanumeric string
void random_string(char *str, size_t length) {
    const char *characters = ALPHANUMERIC_CHARS;
    for (size_t i = 0; i < length; i++) {
        str[i] = characters[rand() % NUM_ALPHANUMERIC];
    }
    str[length] = '\0';
}

// Function to initialize collections
void init_collections(int num_records, float score_min, float score_max) {
    MemoryPool *int_pool = init_memory_pool(num_records * sizeof(int));
    MemoryPool *record_pool = init_memory_pool(num_records * sizeof(Record));

    if (!int_pool || !record_pool) return;

    int *int_array = (int*)allocate_from_pool(int_pool, num_records * sizeof(int));
    Record *records = (Record*)allocate_from_pool(record_pool, num_records * sizeof(Record));

    for (int i = 0; i < num_records; ++i) {
        random_string(records[i].string, 10);
        records[i].score = score_min + ((float)rand() / RAND_MAX) * (score_max - score_min);
        records[i].linked_list = NULL;
        int_array[i] = rand(); // Random int value
    }

    deallocate_from_pool(record_pool, records);
    deallocate_from_pool(int_pool, int_array);
    free(int_pool->memory_pool);
    free(int_pool);
    free(record_pool->memory_pool);
    free(record_pool);
}

// Thread-safe function to find and print the highest-priority event
void* highest_priority_event(Event *head) {
    pthread_mutex_lock(&event_list_lock);

    Event *current = head;
    Event *highest_priority_event = NULL;

    while (current != NULL) {
        if (!highest_priority_event || current->priority > highest_priority_event->priority) {
            highest_priority_event = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&event_list_lock);

    if (highest_priority_event) {
        printf("Highest priority event: %s\n", highest_priority_event->description);
    }

    return NULL;
}

// Thread-safe function to read integers and find the median
void* find_median(int *arr, int size) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    qsort(arr, size, sizeof(int), (int (*)(const void *, const void *))strcmp);

    if (size % 2 == 0)
        printf("Median: %.1f\n", (arr[size/2 - 1] + arr[size/2]) / 2.0);
    else
        printf("Median: %d\n", arr[size/2]);

    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    srand(time(NULL));

    int num_records = 100;
    float score_min = 0.0f, score_max = 10.0f;

    init_collections(num_records, score_min, score_max);

    // Example of event list management and median calculation
    int data[] = {5, 3, 8, 6, 2};
    size_t num_elements = sizeof(data) / sizeof(data[0]);

    find_median(data, num_elements);

    return 0;
}
