#define MAX_THREADS 8

typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *md_ctx;
    RSA *rsa_key;
    unsigned char key_buffer[256];
    size_t key_length;
} CryptoContext;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
