// Thread-safe key cache (simplified)
typedef struct {
    pthread_mutex_t mutex;
    CryptoContext **cache;
    int capacity;
} KeyCache;

KeyCache key_cache = {PTHREAD_MUTEX_INITIALIZER, NULL, 0};

CryptoContext* get_cached_key(int key_id) {
    pthread_mutex_lock(&key_cache.mutex);
    if (key_id < key_cache.capacity && key_cache.cache[key_id]) {
        CryptoContext *ctx = key_cache.cache[key_id];
        pthread_mutex_unlock(&key_cache.mutex);
        return ctx;
    }
    pthread_mutex_unlock(&key_cache.mutex);
    return NULL;
}

void cache_key(CryptoContext *ctx, int key_id) {
    pthread_mutex_lock(&key_cache.mutex);
    if (key_id >= key_cache.capacity) {
        key_cache.capacity = key_id + 1;
        key_cache.cache = realloc(key_cache.cache, sizeof(CryptoContext*) * key_cache.capacity);
    }
    key_cache.cache[key_id] = ctx;
    pthread_mutex_unlock(&key_cache.mutex);
}

// Initialize cryptographic system
void initialize_crypto_system(const char *config_path) {
    load_config(config_path);

    // Add supported ciphers and digests
    EVP_add_cipher(EVP_aes_128_cbc());
    EVP_add_digest(EVP_md5());
