// User profile data structure
class UserProfile {
    String name;
    int age;
    String email;
    List<String> interests;

    // Constructor, getters and setters omitted for brevity
}

// Strategy pattern interface for filtering criteria
interface FilterStrategy {
    boolean match(UserProfile profile);
}

// DAO class with filtering capabilities
class UserDAO {
    private final MemoryPool namePool = new MemoryPool();
    private final MemoryPool emailPool = new MemoryPool();

    public List<UserProfile> filterProfiles(List<UserProfile> profiles, List<FilterStrategy> strategies) {
        return profiles.stream()
                .filter(profile -> strategies.stream().allMatch(strategy -> strategy.match(profile)))
                .collect(Collectors.toList());
    }

    // Pagination method omitted for brevity
}

// Doubly linked list node
class ProfileNode {
    UserProfile profile;
    ProfileNode prev, next;

    public ProfileNode(UserProfile profile) {
        this.profile = profile;
    }
}

// Doubly linked list class
class ProfileList {
    private final ProfileNode head = new ProfileNode(null);
    private final ProfileNode tail = new ProfileNode(null);

    public ProfileList() {
        head.next = tail;
        tail.prev = head;
    }

    // Insert after a specific email or at the end if not found
    public synchronized void insertProfile(UserProfile profile, String targetEmail) {
        ProfileNode current = head.next;
        while (current != tail && !targetEmail.equals(current.profile.email)) {
            current = current.next;
        }

        ProfileNode newNode = new ProfileNode(profile);
        newNode.prev = current;
        newNode.next = current.next;

        if (current == tail) {
            tail.prev = newNode;
        } else {
            current.next.prev = newNode;
        }

        current.next = newNode;
    }
}

// Main processing function
public class UserProfileProcessor {

    public static void main(String[] args) throws Exception {
        ObjectMapper objectMapper = new ObjectMapper();
        BufferedReader reader = new BufferedReader(new FileReader("user_profiles.txt"));

        List<UserProfile> profiles = new ArrayList<>();
        String line;

        while ((line = reader.readLine()) != null) {
            JsonNode jsonNode = objectMapper.readTree(line);
            UserProfile profile = new UserProfile();
            profile.name = objectMapper.treeToValue(jsonNode.get("name"), String.class);
            profile.age = jsonNode.get("age").asInt();
            profile.email = objectMapper.treeToValue(jsonNode.get("email"), String.class);
            profile.interests = Arrays.stream(jsonNode.get("interests").toString().split(","))
                    .map(String::trim)
                    .collect(Collectors.toList());
            profiles.add(profile);
        }

        reader.close();

        // Example usage of DAO and ProfileList
        UserDAO dao = new UserDAO();
        List<FilterStrategy> strategies = Arrays.asList(
                profile -> profile.age >= 18,
                profile -> profile.interests.contains("coding"),
                profile -> profile.email.endsWith("@example.com")
        );

        List<UserProfile> filteredProfiles = dao.filterProfiles(profiles, strategies);

        ProfileList list = new ProfileList();
        for (UserProfile profile : filteredProfiles) {
            list.insertProfile(profile, "specific@example.com");
        }
    }
}
