    configRecord record;
    struct CacheNode *next;
} CacheNode;

// Define the distributed configuration cache structure
typedef struct {
    pthread_rwlock_t rwlock;
    CacheNode *head; // Head of the linked list storing cache nodes
    size_t nodeCount;
    size_t maxNodes;
