void clearConfigList(ConfigCache *cache);
void printConfigRecords(const ConfigCache *cache);

// Initialize the distributed configuration cache
void configCacheInit(ConfigCache **cache, size_t maxNodes) {
    if (!cache || maxNodes == 0) return;

    *cache = (ConfigCache *)malloc(sizeof(ConfigCache));
    if (*cache == NULL) return;

    pthread_rwlock_init(&(*cache)->rwlock, NULL);
    (*cache)->head = NULL;
    (*cache)->nodeCount = 0;
    (*cache)->maxNodes = maxNodes;
    atomic_store(&(*cache)->hits, 0);
    atomic_store(&(*cache)->misses, 0);

