    if (!cache || !key) return;

    pthread_rwlock_wrlock(&cache->rwlock);

    if (cache->nodeCount >= cache->maxNodes) {
        // Handle eviction policy here before adding a new node
    }

    CacheNode *newNode = (CacheNode *)malloc(sizeof(CacheNode));
    if (!newNode) {
        pthread_rwlock_unlock(&cache->rwlock);
        return;
    }

    newNode->record.key = strdup(key);
    newNode->record.value = value;
    newNode->next = cache->head;
    cache->head = newNode;
    cache->nodeCount++;

    pthread_rwlock_unlock(&cache->rwlock);
}

// Clear the dynamic list of configRecords
void clearConfigList(ConfigCache *cache) {
    if (!cache) return;

    pthread_rwlock_wrlock(&cache->rwlock);

    CacheNode *current = cache->head;
    while (current != NULL) {
        CacheNode *next = current->next;
        free(current->record.key);
        free(current);
        current = next;
    }

    cache->head = NULL;
    cache->nodeCount = 0;

    pthread_rwlock_unlock(&cache->rwlock);
}

// Iterate over the list and print each record
void printConfigRecords(const ConfigCache *cache) {
    if (!cache) return;

    pthread_rwlock_rdlock(&cache->rwlock);

    CacheNode *current = cache->head;
    while (current != NULL) {
        printf("Key: %s, Value: %d\n", current->record.key, current->record.value);
        current = current->next;
    }

    pthread_rwlock_unlock(&cache->rwlock);
}

// Main function for demonstration purposes
int main() {
    ConfigCache *myCache;
    configCacheInit(&myCache, 100); // Initialize cache with a max of 100 nodes

    addConfigRecord(myCache, "exampleKey1", 42);
    addConfigRecord(myCache, "exampleKey2", 84);

    printConfigRecords(myCache);

    clearConfigList(myCache);

    free(myCache); // Clean up
    return 0;
}
