#define LOW_THROUGHPUT false

typedef enum { SUCCESS, FAILURE } status_t;

typedef struct {
    pthread_rwlock_t lock;
    size_t read_count;
} reader_writer_lock;

void initialize_reader_writer_lock(reader_writer_lock *lock) {
    pthread_rwlock_init(&lock->lock, NULL);
    lock->read_count = 0;
}

void acquire_read_lock(reader_writer_lock *lock) {
    pthread_mutex_lock(&lock->lock);
    lock->read_count++;
    if (lock->read_count == 1) {
        pthread_rwlock_wrlock(&lock->lock);
    }
    pthread_mutex_unlock(&lock->lock);
    pthread_rwlock_rdlock(&lock->lock);
}

void release_read_lock(reader_writer_lock *lock) {
    pthread_rwlock_unlock(&lock->lock);
    pthread_mutex_lock(&lock->lock);
    lock->read_count--;
    if (lock->read_count == 0) {
        pthread_rwlock_unlock(&lock->lock);
    }
    pthread_mutex_unlock(&lock->lock);
}

void acquire_write_lock(reader_writer_lock *lock) {
    pthread_rwlock_wrlock(&lock->lock);
}

void release_write_lock(reader_writer_lock *lock) {
    pthread_rwlock_unlock(&lock->lock);
}

status_t initialize_and_process_data(size_t num_records, long offset_range, int key_range, bool high_throughput) {
    if (num_records == 0 || offset_range <= 0 || key_range <= 0) return FAILURE;

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (!offsets || !keys) return FAILURE;

