        free(offsets);
        free(keys);
        return FAILURE;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;
        records[i].value = rand() % key_range; // Random value within the specified range
    }

    reader_writer_lock lock;
    initialize_reader_writer_lock(&lock);

    if (high_throughput) {
        acquire_write_lock(&lock);
        printf("Processing with high-throughput pipeline...\n");
        release_write_lock(&lock);
    } else {
        acquire_read_lock(&lock);
        printf("Processing with low-throughput, memory-efficient pipeline...\n");
        release_read_lock(&lock);
    }

    // Simulate processing and metrics collection
    double latency = (double)rand() / RAND_MAX;
    printf("Processing latency: %.2f\n", latency);

    free(offsets);
    free(keys);
    free(records);
    pthread_rwlock_destroy(&lock.lock);

    return SUCCESS;
}

int main() {
