#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int timestamp;
} log_record_t;

typedef struct {
    long *offsets;
    int *keys;
    log_record_t *records;
    char *log_buffer;
    size_t offset_size, key_size, record_size, buffer_size;
    pthread_mutex_t mutex;
} logging_system_t;

// Memory pool structure
typedef struct {
    void **free_list;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} memory_pool_t;

void initialize_memory_pool(memory_pool_t *pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->total_blocks = num_blocks;
    pool->used_blocks = 0;
    pool->free_list = malloc(num_blocks * sizeof(void *));
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocate_from_pool(memory_pool_t *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_blocks < pool->total_blocks) {
        void *block = malloc(pool->block_size);
        pool->free_list[pool->used_blocks++] = block;
        pthread_mutex_unlock(&pool->lock);
        return block;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // No more memory available
}

void deallocate_from_pool(memory_pool_t *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->used_blocks; ++i) {
        if (pool->free_list[i] == block) {
            free(block);
            pool->free_list[i] = pool->free_list[--pool->used_blocks];
            pthread_mutex_unlock(&pool->lock);
            return;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void cleanup_memory_pool(memory_pool_t *pool) {
    for (size_t i = 0; i < pool->total_blocks; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
    pthread_mutex_destroy(&pool->lock);
}

logging_system_t* initialize_logging_system(size_t offset_size, size_t key_size, 
                                            size_t record_size, size_t buffer_size) {
    logging_system_t *system = (logging_system_t*)allocate_from_pool(&memory_pool);
    if (!system) return NULL;

    system->offsets = (long*)malloc(offset_size * sizeof(long));
    system->keys = (int*)malloc(key_size * sizeof(int));
    system->records = (log_record_t*)malloc(record_size * sizeof(log_record_t));
    system->log_buffer = (char*)malloc(buffer_size);
    system->offset_size = offset_size;
    system->key_size = key_size;
    system->record_size = record_size;
    system->buffer_size = buffer_size;

    pthread_mutex_init(&system->mutex, NULL);

    if (!system->offsets || !system->keys || !system->records || !system->log_buffer) {
        cleanup_logging_system(system);
        return NULL;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < offset_size; ++i)
        system->offsets[i] = i;

    for (size_t i = 0; i < key_size; ++i)
        system->keys[i] = i + 1;

