#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define POOL_SIZE 1024 // Example pool size, adjust as necessary

typedef struct Node {
    char *data;
    int priority;
    struct Node *next;
} Node;

typedef struct MemoryPool {
    void *pool[POOL_SIZE];
    pthread_mutex_t lock;
    size_t used;
} MemoryPool;

MemoryPool mem_pool = {.used = 0};

void init_memory_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        mem_pool.pool[i] = NULL;
    }
    pthread_mutex_init(&mem_pool.lock, NULL);
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&mem_pool.lock);

    for (size_t i = 0; i < POOL_SIZE; ++i) {
        if (!mem_pool.pool[i]) {
            mem_pool.pool[i] = malloc(size);
            if (!mem_pool.pool[i]) {
                pthread_mutex_unlock(&mem_pool.lock);
                return NULL;
            }
            mem_pool.used++;
            pthread_mutex_unlock(&mem_pool.lock);
            return mem_pool.pool[i];
        }
    }

    pthread_mutex_unlock(&mem_pool.lock);
    return NULL; // Pool is full
}

void free_memory_pool() {
    pthread_mutex_lock(&mem_pool.lock);

    for (size_t i = 0; i < POOL_SIZE; ++i) {
        if (mem_pool.pool[i]) {
            free(mem_pool.pool[i]);
            mem_pool.pool[i] = NULL;
        }
    }

    mem_pool.used = 0;
    pthread_mutex_unlock(&mem_pool.lock);
    pthread_mutex_destroy(&mem_pool.lock);
}

void random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length; // Leave space for null terminator
        for (size_t n = 0; n < length; n++) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[n] = charset[key];
        }
        str[length] = '\0';
    } else {
        *str = '\0';
    }
}

Node* create_node(const char *data, int priority) {
    Node *node = allocate_from_pool(sizeof(Node));
    if (!node) return NULL;

    node->data = allocate_from_pool(strlen(data) + 1);
    if (!node->data) {
        free(node);
        return NULL;
    }
    strcpy(node->data, data);

    node->priority = priority;
    node->next = NULL;

    random_string((char*)allocate_from_pool(10), 10); // Example length for random string
    return node;
}

typedef struct List {
    Node *head;
    pthread_mutex_t lock;
} List;

void init_list(List *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(List *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        Node *temp = current;
        current = current->next;

        free(temp->data);
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void insert_node(List *list, const char *data, int priority) {
    Node *node = create_node(data, priority);

    if (!node) return;

    pthread_mutex_lock(&list->lock);

    node->next = list->head;
    list->head = node;

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(const char *filename, List *list) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "w");
    if (!file) return;

    Node *current = list->head;
    while (current) {
        fprintf(file, "%s %d\n", current->data, current->priority);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(const char *filename, List *list) {
    destroy_list(list);

    FILE *file = fopen(filename, "r");
    if (!file) return;

    char buffer[256];
    int priority;
    while (fscanf(file, "%255s %d\n", buffer, &priority) == 2) {
        insert_node(list, buffer, priority);
    }

    fclose(file);
}

int main() {
    srand(time(NULL));
    init_memory_pool();

    List node_list;
    init_list(&node_list);

    // Example usage
    insert_node(&node_list, "example1", 10);
    insert_node(&node_list, "example2", 5);

    serialize_list("list.txt", &node_list);
    deserialize_list("list.txt", &node_list);

    destroy_list(&node_list);
    free_memory_pool();

    return 0;
}
