#include <iostream>
#include <cstring>
#include <cstdlib>
#include <ctime>
#include <mutex>

struct Task {
    int priority;
    char description[21]; // Max length of 20 + null terminator
    time_t dueDate;
    Task* next;

    Task(int p, const char* d, time_t dd)
        : priority(p), dueDate(dd) {
        strncpy(description, d, 20);
        description[20] = '\0';
    }
};

class TaskManager {
public:
    TaskManager() : head(nullptr) {}

    ~TaskManager() {
        clear();
    }

    void addTask(int priority, const std::string& desc, time_t dueDate) {
        std::lock_guard<std::mutex> lock(mtx);
        Task* newTask = new Task(priority, desc.c_str(), dueDate);
        if (!head || head->priority < priority) {
            newTask->next = head;
            head = newTask;
        } else {
            Task* current = head;
            while (current->next && current->next->priority >= priority) {
                current = current->next;
            }
            newTask->next = current->next;
            current->next = newTask;
        }
    }

    void removeTask(const char* desc) {
        std::lock_guard<std::mutex> lock(mtx);
        Task* current = head;
        Task* prev = nullptr;

        while (current && strcmp(current->description, desc)) {
            prev = current;
            current = current->next;
        }

        if (!current) return; // Not found

        if (prev) {
            prev->next = current->next;
        } else {
            head = current->next;
        }
        delete current;
    }

    void printTasks() const {
        std::lock_guard<std::mutex> lock(mtx);
        Task* current = head;
        while (current) {
            std::cout << "Priority: " << current->priority
                      << ", Description: " << current->description
                      << ", Due Date: " << ctime(&current->dueDate)
                      << std::endl;
            current = current->next;
        }
    }

private:
    Task* head;
    mutable std::mutex mtx;

    void clear() {
        while (head) {
            Task* temp = head;
            head = head->next;
            delete temp;
        }
    }
};

int main() {
    srand(static_cast<unsigned int>(time(nullptr)));
    TaskManager manager;

    // Simulate adding tasks
    for (int i = 0; i < 10; ++i) {
        std::string desc(randStr(1, 20));
        time_t dueDate = time(nullptr) + rand() % (7 * 24 * 60 * 60); // Random date within a week
        manager.addTask(rand() % 5 + 1, desc, dueDate);
    }

    manager.printTasks();

    // Simulate removing tasks
    manager.removeTask("Some description");
    manager.printTasks();

    return 0;
}

std::string randStr(int minLen, int maxLen) {
    std::string str;
    int len = rand() % (maxLen - minLen + 1) + minLen;
    for (int i = 0; i < len; ++i) {
        char c = 'a' + rand() % 26;
        str += c;
    }
    return str;
}
