void manageMemory(int numOffsets, int numKeys, int numRecords, int minVal, int maxVal) {
    if (numOffsets <= 0 || numKeys <= 0 || numRecords <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    long* offsets = malloc(numOffsets * sizeof(long));
    int* keys = malloc(numKeys * sizeof(int));
    Record* records = malloc(numRecords * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    for (int i = 0; i < numOffsets; ++i) {
        offsets[i] = rand() % 1000; // Example offset value
    }
    for (int i = 0; i < numKeys; ++i) {
        keys[i] = rand() % 1000; // Example key value
    }
    srand(time(NULL));
    for (int i = 0; i < numRecords; ++i) {
        records[i].field1 = minVal + rand() % (maxVal - minVal + 1);
        records[i].field2 = minVal + rand() % (maxVal - minVal + 1);
    }

    // Simulate usage of arrays
    for (int i = 0; i < numRecords; ++i) {
        printf("Record %d: Field1 = %d, Field2 = %d\n", i, records[i].field1, records[i].field2);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    manageMemory(10, 5, 8, 0, 100);
    return 0;
}
