#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define CONFIG_FILE "config.txt"

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t rec;
    char *extra;
} data_record_t;

typedef struct {
    size_t max_size;
    int rand_min, rand_max;
    size_t resize_threshold;
    size_t initial_extra_size;
} config_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char* operation, int key, size_t extra_size) {
    time_t now;
    time(&now);
    printf("[%s] Operation: %s, Key: %d, Extra Size: %zu\n", ctime(&now), operation, key, extra_size);
}

int load_config(config_t *config) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) return -1;

    fscanf(file, "%zu %d %d %zu %zu",
           &config->max_size,
           &config->rand_min,
           &config->rand_max,
           &config->resize_threshold,
           &config->initial_extra_size);

    fclose(file);
    return 0;
}

void initialize_memory_pool(size_t *pool, size_t pool_size) {
    pthread_mutex_lock(&lock);
    memset(pool, 0, pool_size);
    pthread_mutex_unlock(&lock);
}

void deallocate_record(data_record_t **records, int index, size_t *used_space) {
    if (records[index]) {
        free(records[index]->extra);
        records[index] = NULL;
        (*used_space) -= sizeof(data_record_t) + strlen(records[index]->extra) + 1;
    }
}

void manage_records(config_t config) {
    size_t pool_size = config.max_size;
    unsigned char *memory_pool = malloc(pool_size);
    if (!memory_pool) return;

    initialize_memory_pool((size_t *)memory_pool, pool_size);

    data_record_t **records = malloc(10 * sizeof(data_record_t *));
    int num_records = 0;
    size_t used_space = 0;

    while (1) {
        pthread_mutex_lock(&lock);

        if ((used_space + sizeof(data_record_t) + config.initial_extra_size > pool_size) || 
            (num_records >= config.resize_threshold)) {

            size_t new_pool_size = pool_size * 2;
            unsigned char *new_memory_pool = realloc(memory_pool, new_pool_size);

            if (!new_memory_pool) {
                log_operation("Error", -1, 0);
                break;
            }

            memory_pool = new_memory_pool;
            initialize_memory_pool((size_t *)memory_pool + (pool_size - used_space), pool_size * 2 - used_space);
            pool_size = new_pool_size;

            records = realloc(records, num_records * 2 * sizeof(data_record_t *));
            if (!records) {
                log_operation("Error", -1, 0);
                break;
            }
        }

        data_record_t *new_record = (data_record_t *)(memory_pool + used_space);

        new_record->key = rand() % 10000; // Simple unique key generation
        new_record->rec.value = rand() % (config.rand_max - config.rand_min + 1) + config.rand_min;
        new_record->extra = malloc(config.initial_extra_size);

        snprintf(new_record->extra, config.initial_extra_size, "Template for Key: %d", new_record->key);

        records[num_records++] = new_record;

        used_space += sizeof(data_record_t) + strlen(new_record->extra) + 1;
        log_operation("Allocate", new_record->key, strlen(new_record->extra));

        pthread_mutex_unlock(&lock);

        // Simulate some work
        sleep(1);
    }

    for (int i = 0; i < num_records; ++i) {
        deallocate_record(records, i, &used_space);
        log_operation("Deallocate", records[i]->key, strlen(records[i]->extra));
    }

    free(memory_pool);
    free(records);
}

void cleanup() {
    pthread_mutex_destroy(&lock);
}

int main() {
    config_t config;
    if (load_config(&config) != 0) {
        fprintf(stderr, "Failed to load configuration.\n");
        return EXIT_FAILURE;
    }

    manage_records(config);

    cleanup();
    return EXIT_SUCCESS;
}
