typedef struct MemoryPool {
    size_t block_size;
    size_t total_blocks;
    void *pool;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void init_memory_pool(MemoryPool *mp, size_t block_size, size_t num_blocks);
void* allocate_from_pool(MemoryPool *mp, size_t size);
void free_memory_pool(MemoryPool *mp);

geometry_t* initialize_geometries(size_t count, double min_val, double max_val, int str_len);
char* generate_random_alphanumeric(int length);
int find_largest_in_array(const int *array, size_t size);
void read_integers_to_array(int **array, size_t *size);

// Random number generator class
typedef struct {
    unsigned int seed;
} RNG;

void rng_init(RNG *rng, unsigned int seed) {
    rng->seed = seed ? seed : (unsigned int)time(NULL);
}

int rng_next(RNG *rng) {
    return rand_r(&rng->seed);
}

double rng_uniform_double(RNG *rng, double min_val, double max_val) {
    return ((double)rng_next(rng) / RAND_MAX) * (max_val - min_val) + min_val;
}

// Helper functions
geometry_t* initialize_geometries(size_t count, double min_val, double max_val, int str_len) {
    RNG rng;
    rng_init(&rng, 0);

    MemoryPool mp = { sizeof(geometry_t), count, NULL, PTHREAD_MUTEX_INITIALIZER };
    init_memory_pool(&mp, sizeof(geometry_t), count);

    geometry_t *geometries = (geometry_t*)allocate_from_pool(&mp, sizeof(geometry_t) * count);
    if (!geometries) {
        free_memory_pool(&mp);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        geometries[i].num = rng_uniform_double(&rng, min_val, max_val);

        geometries[i].str = generate_random_alphanumeric(str_len);
        if (!geometries[i].str) {
            // Handle allocation failure
            for (size_t j = 0; j < i; ++j) free(geometries[j].str);
            free_memory_pool(&mp);
            return NULL;
        }

        geometries[i].pt.x = (float)rng_uniform_double(&rng, -100.0, 100.0);
        geometries[i].pt.y = (float)rng_uniform_double(&rng, -100.0, 100.0);
    }

    free_memory_pool(&mp);
    return geometries;
}

char* generate_random_alphanumeric(int length) {
    const char charset[] =
        "0123456789"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz";
    if (length <= 0) return NULL;

    char *str = malloc(length + 1);
    if (!str) return NULL;

    for (int n = 0; n < length; n++) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[n] = charset[key];
    }

    str[length] = '\0';
    return str;
}

int find_largest_in_array(const int *array, size_t size) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest)
            largest = array[i];
    }

    pthread_mutex_unlock(&lock);
    return largest;
}

void read_integers_to_array(int **array, size_t *size) {
    printf("Enter the number of integers: ");
    scanf("%zu", size);

    *array = malloc(*size * sizeof(int));
    if (!*array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter the integers:\n");
    for (size_t i = 0; i < *size; ++i) {
        scanf("%d", &((*array)[i]));
    }
}

void init_memory_pool(MemoryPool *mp, size_t block_size, size_t num_blocks) {
    mp->block_size = block_size;
    mp->total_blocks = num_blocks;
    pthread_mutex_init(&mp->lock, NULL);
    mp->pool = malloc(block_size * num_blocks);
    if (!mp->pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
}

void* allocate_from_pool(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);

    void *block = mp->pool;
    if (size <= mp->block_size && mp->total_blocks > 0) {
        mp->pool += mp->block_size;
        --mp->total_blocks;
    } else {
        block = NULL; // Allocation failed
    }

    pthread_mutex_unlock(&mp->lock);
    return block;
}

void free_memory_pool(MemoryPool *mp) {
    if (mp->pool) {
        free(mp->pool);
        mp->pool = NULL;
    }
    pthread_mutex_destroy(&mp->lock);
}
