#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include "json-c/json.h" // Assume this is the JSON library being used

#define INITIAL_HASH_TABLE_SIZE 16
#define LOAD_FACTOR 0.75

typedef struct {
    float x, y;
} Point;

typedef struct {
    double value;
    char *name;
    Point point;
} Geometry;

typedef struct ListNode {
    int data;
    struct ListNode *next;
} ListNode;

typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
} LinkedList;

typedef struct HashNode {
    char *key;
    Geometry *value;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
} HashMap;

typedef struct {
    int value;
} Record;

double array_doubles[] = {0.0, 1.1, 2.2};
char *array_strings[] = {"one", "two"};
Point points[] = {{1.0f, 2.0f}, {3.0f, 4.0f}};
Geometry geometries[] = {
    {1.5, "Geom1", {1.0f, 2.0f}},
    {2.5, "Geom2", {3.0f, 4.0f}}
};

LinkedList linked_list;
HashMap hash_map;

void init_linked_list(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_linked_list(LinkedList *list) {
    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *tmp = current;
        current = current->next;
        free(tmp);
    }
    pthread_mutex_destroy(&list->lock);
}

int add_to_linked_list(LinkedList *list, int value) {
    ListNode *new_node = malloc(sizeof(ListNode));
    if (!new_node) return -1;

    new_node->data = value;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int find_largest_in_linked_list(LinkedList *list, int *largest) {
    ListNode *current;
    int max_val = INT_MIN;

    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current != NULL) {
        if (current->data > max_val) {
            max_val = current->data;
        }
        current = current->next;
    }

    *largest = max_val;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

unsigned long hash_function(const char *key, size_t size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }

    return hash % size;
}

HashMap* create_hash_map(size_t size) {
    HashMap *map = malloc(sizeof(HashMap));
    if (!map) return NULL;

    map->buckets = calloc(size, sizeof(HashNode *));
    if (!map->buckets) {
        free(map);
        return NULL;
    }

    map->size = size;
    map->count = 0;
    pthread_mutex_init(&map->mutex, NULL);

    return map;
}

void destroy_hash_map(HashMap *map) {
    for (size_t i = 0; i < map->size; ++i) {
        HashNode *current = map->buckets[i];
        while (current != NULL) {
            HashNode *tmp = current;
            current = current->next;

            free(tmp->key);
            free(tmp->value);
            free(tmp);
        }
    }

    free(map->buckets);
    pthread_mutex_destroy(&map->mutex);
    free(map);
}

int resize_hash_map(HashMap *map) {
    size_t new_size = map->size * 2;
    HashNode **new_buckets = calloc(new_size, sizeof(HashNode *));
    if (!new_buckets) return -1;

    for (size_t i = 0; i < map->size; ++i) {
        HashNode *current = map->buckets[i];
        while (current != NULL) {
            HashNode *next_node = current->next;
            unsigned long new_index = hash_function(current->key, new_size);

            current->next = new_buckets[new_index];
            new_buckets[new_index] = current;

            current = next_node;
        }
    }

    free(map->buckets);
    map->buckets = new_buckets;
    map->size = new_size;

    return 0;
}

int add_to_hash_map(HashMap *map, const char *key, Geometry *value) {
    unsigned long index = hash_function(key, map->size);

    pthread_mutex_lock(&map->mutex);

    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&map->mutex);
        return -1;
    }

    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;

    map->count++;
    if ((double)map->count / map->size >= LOAD_FACTOR) {
        int resize_status = resize_hash_map(map);
        if (resize_status == -1) {
            free(new_node->key);
            free(new_node);
            pthread_mutex_unlock(&map->mutex);
            return -1;
        }
    }

    pthread_mutex_unlock(&map->mutex);

    return 0;
}

Geometry* get_from_hash_map(HashMap *map, const char *key) {
    unsigned long index = hash_function(key, map->size);

    pthread_mutex_lock(&map->mutex);

    HashNode *current = map->buckets[index];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            Geometry *result = current->value;
            pthread_mutex_unlock(&map->mutex);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&map->mutex);

    return NULL;
}

void init_data_structures() {
    init_linked_list(&linked_list);

    hash_map = create_hash_map(INITIAL_HASH_TABLE_SIZE);
    if (!hash_map) {
        fprintf(stderr, "Failed to initialize hash map\n");
        exit(EXIT_FAILURE);
    }
}

void destroy_data_structures() {
    destroy_linked_list(&linked_list);
    destroy_hash_map(hash_map);
}

