    {
        var logger = new ConsoleLogger();
        var gameEngine = new GameEngine(logger);

        await gameEngine.ProcessDataAsync(new List<string> { "Sample input 1", "Sample input 2" });
        gameEngine.UpdateConfiguration("Dimensions", 200);
    }
}
