```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define constants for random value ranges and string lengths
#define MAX_GEOMETRIES 100
#define POINT_MAX_X 1000.0
#define POINT_MAX_Y 1000.0
#define RANDOM_STRING_LENGTH 10

typedef struct {
    double x, y;
} Point;

typedef struct {
    double attribute;
    char name[RANDOM_STRING_LENGTH + 1];
    Point location;
} Geometry;

typedef struct {
    time_t timestamp;
    int active;
} Metadata;

typedef struct {
    Geometry geometries[MAX_GEOMETRIES];
    Metadata metadata;
} ComplexGeometry;

// Memory pool for efficient memory management
#define POOL_SIZE 1024 * 1024 // 1 MB
char memory_pool[POOL_SIZE];
size_t current_offset = 0;

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (current_offset + size > POOL_SIZE) {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    void* ptr = &memory_pool[current_offset];
    current_offset += size;
    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

// Function to initialize random values
void initialize_random() {
    srand((unsigned int)time(NULL));
}

double generate_random_double(double min, double max) {
    return min + (rand() % ((int)((max - min) * 1000))) / 1000.0;
}

void fill_random_string(char* str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length; ++i) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[length] = '\0';
}

// Initialize data structures
void initialize_structures(ComplexGeometry* complex_geometry, size_t num_geometries) {
    for (size_t i = 0; i < num_geometries; ++i) {
        Geometry* geo = &complex_geometry->geometries[i];

        // Initialize geometry attributes with random values
        geo->attribute = generate_random_double(0.0, 100.0);
        fill_random_string(geo->name, RANDOM_STRING_LENGTH);

        // Initialize point coordinates within specified range
        geo->location.x = generate_random_double(0.0, POINT_MAX_X);
        geo->location.y = generate_random_double(0.0, POINT_MAX_Y);
    }

    // Metadata initialization with current timestamp and active flag
    complex_geometry->metadata.timestamp = time(NULL);
    complex_geometry->metadata.active = 1;
}

// Linked list node for dynamic resizing mechanism
typedef struct Node {
    void* data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void insert_record(void* record, size_t index) {
    pthread_mutex_lock(&list_mutex);

    if (index == 0 || head == NULL) {
        Node* new_node = (Node*)allocate_from_pool(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for new node\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        new_node->data = record;
        new_node->next = head;
        head = new_node;
    } else {
        Node* current = head;
        size_t count = 0;

        while (current != NULL && count < index - 1) {
            current = current->next;
            ++count;
        }

        if (current == NULL) {
            fprintf(stderr, "Index out of bounds\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        Node* new_node = (Node*)allocate_from_pool(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for new node\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        new_node->data = record;
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void remove_record(size_t index) {
    pthread_mutex_lock(&list_mutex);

    if (index == 0 && head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    } else {
        Node* current = head;
        size_t count = 0;

        while (current != NULL && current->next != NULL && count < index - 1) {
            current = current->next;
            ++count;
        }

        if (current == NULL || current->next == NULL) {
            fprintf(stderr, "Index out of bounds\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }

        Node* temp = current->next;
        current->next = temp->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

// Example usage
int main() {
    initialize_random();

    ComplexGeometry complex_geometry;
    initialize_structures(&complex_geometry, 5);

    // Insert and remove records from the linked list
    insert_record(&complex_geometry.geometries[0], 0);
    insert_record(&complex_geometry.geometries[1], 1);
    remove_record(0);

    return 0;
}
```

This code provides a modular approach to managing spatial indexing data structures with efficient memory usage and concurrency handling. It includes a custom memory pool for allocation, random initialization of various fields, thread-safe operations on linked lists, and comprehensive error handling.']

