#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define ALPHANUMERIC_LEN 10

typedef struct node {
    int value;
    struct node* next;
} Node;

typedef struct item {
    char string[20];
    struct entry* entry_ptr;
    struct node* node_ptr;
    struct item* next;
} Item;

typedef struct entry {
    char string[ALPHANUMERIC_LEN + 1];
    double weight;
    struct item* item_ptr;
    struct entry* next;
} Entry;

// Memory pool structure
typedef struct memory_pool {
    size_t block_size;
    unsigned char* pool;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool int_pool, entry_pool, item_pool;

void init_memory_pool(MemoryPool* mp, size_t block_size, size_t total_blocks) {
    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->used_blocks = 0;
    pthread_mutex_init(&mp->lock, NULL);
    mp->pool = malloc(block_size * total_blocks);
}

void* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used_blocks >= mp->total_blocks) {
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }
    void* block = mp->pool + (mp->used_blocks * mp->block_size);
    ++mp->used_blocks;
    pthread_mutex_unlock(&mp->lock);
    return block;
}

void free_memory_pool(MemoryPool* mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

// Helper functions
char random_alphanumeric_string(char* str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length] = '\0';
}

double random_weight(double min, double max) {
    return min + ((double)rand() / RAND_MAX * (max - min));
}

void log_memory_event(const char* event, void* ptr) {
    printf("%s: %p\n", event, ptr);
}

// Linked list management functions
Node* add_node_to_list(Node** head, int value) {
    Node* new_node = (Node*)allocate_from_pool(&int_pool);
    if (!new_node) return NULL;
    log_memory_event("Allocated Node", new_node);

    new_node->value = value;
    new_node->next = *head;
    *head = new_node;
    return new_node;
}

Entry* add_entry_to_list(Entry** head, const char* string, double weight) {
    Entry* new_entry = (Entry*)allocate_from_pool(&entry_pool);
    if (!new_entry) return NULL;
    log_memory_event("Allocated Entry", new_entry);

    strncpy(new_entry->string, string, ALPHANUMERIC_LEN);
    new_entry->weight = weight;
    new_entry->next = *head;
    *head = new_entry;
    return new_entry;
}

Item* add_item_to_list(Item** head, const char* id) {
    Item* new_item = (Item*)allocate_from_pool(&item_pool);
    if (!new_item) return NULL;
    log_memory_event("Allocated Item", new_item);

    snprintf(new_item->string, sizeof(new_item->string), "ID-%s", id);
    new_item->next = *head;
    *head = new_item;
    return new_item;
}

// Helper function for computing weighted average
double compute_weighted_average(Node* head) {
    double total_weight = 0.0;
    double weighted_sum = 0.0;

    while (head) {
        weighted_sum += head->value * ((Entry*)head)->weight;
        total_weight += ((Entry*)head)->weight;
        head = head->next;
    }

    return total_weight ? (weighted_sum / total_weight) : 0.0;
}

void handle_input_and_compute(Node** int_list, Entry** entry_list, Item** item_list) {
    srand(time(NULL));

    Node* current_node = NULL;
    Entry* current_entry = NULL;
    Item* current_item = NULL;

    int value;
    while (scanf("%d", &value) == 1) {
        char str[ALPHANUMERIC_LEN + 1];
        random_alphanumeric_string(str, ALPHANUMERIC_LEN);
        double weight = random_weight(0.1, 10.0);

        current_node = add_node_to_list(int_list, value);
        if (current_node) {
            ((Entry*)current_node)->weight = weight;
            ((Entry*)current_node)->item_ptr = add_item_to_list(item_list, "UniqueID");
            add_entry_to_list(entry_list, str, weight);
        }
    }

    printf("Weighted Average: %f\n", compute_weighted_average(*int_list));
}

int main() {
    init_memory_pool(&int_pool, sizeof(Node), 1000);
    init_memory_pool(&entry_pool, sizeof(Entry), 1000);
    init_memory_pool(&item_pool, sizeof(Item), 1000);

    Node* int_list = NULL;
    Entry* entry_list = NULL;
    Item* item_list = NULL;

    handle_input_and_compute(&int_list, &entry_list, &item_list);

    // Cleanup
    free_memory_pool(&int_pool);
    free_memory_pool(&entry_pool);
    free_memory_pool(&item_pool);

    return 0;
}
