# Example of implementing strategy pattern for password validation
def length_strategy(password):
    return len(password) >= 8

def complexity_strategy(password):
    has_upper = any(c.isupper() for c in password)
    has_lower = any(c.islower() for c in password)
    has_digit = any(c.isdigit() for c in password)
    has_special = any(not c.isalnum() for c in password)
    return has_upper and has_lower and has_digit and has_special

def validate_password(password, strategies):
    return all(strategy(password) for strategy in strategies)

