typedef struct {
    MemoryBlock* head;
    pthread_mutex_t lock;
    size_t total_allocated;
    size_t total_free;
    int successful_operations;
    int failed_operations;
    double time_taken;
    FILE* log_file;
} MemoryPool;

MemoryPool* create_memory_pool() {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->total_allocated = 0;
    pool->total_free = 0;
    pool->successful_operations = 0;
    pool->failed_operations = 0;
    pool->time_taken = 0.0;
    pool->log_file = fopen("local_log.txt", "a");
    return pool;
}

void* allocate_memory(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    MemoryBlock* block = malloc(sizeof(MemoryBlock));
    if (!block) {
        log_error(pool, "Memory allocation failed");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    block->ptr = malloc(size);
    if (!block->ptr) {
        free(block);
        log_error(pool, "Memory allocation for data failed");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    block->size = size;
    block->next = pool->head;
    pool->head = block;
    pool->total_allocated += size;

    pthread_mutex_unlock(&pool->lock);
    log_info(pool, "Memory allocated successfully");
    return block->ptr;
}

void deallocate_memory(MemoryPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->lock);

    MemoryBlock** current = &pool->head;
    while (*current) {
        if ((*current)->ptr == ptr) {
            MemoryBlock* to_free = *current;
            *current = (*current)->next;

            free(to_free->ptr);
            free(to_free);

            pool->total_allocated -= to_free->size;
            pool->total_free += to_free->size;

            log_info(pool, "Memory deallocated successfully");
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&pool->lock);
}

void log_message(MemoryPool* pool, const char* message, int level) {
    if (level >= LOG_LEVEL_INFO) {
        fprintf(pool->log_file, "%s\n", message);
        fflush(pool->log_file);
    }
}

void log_error(MemoryPool* pool, const char* message) {
    log_message(pool, message, LOG_LEVEL_ERROR);
    pool->failed_operations++;
}

void log_info(MemoryPool* pool, const char* message) {
    log_message(pool, message, LOG_LEVEL_INFO);
    pool->successful_operations++;
}

void* process_data_stream(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;
    SensorData* data = allocate_memory(pool, sizeof(SensorData));
    if (!data) return NULL;

    // Simulate reading and validating sensor data
    data->sensor_value = 42.0f; // Example value
    data->count = 1;
    data->offset = 100L;
    data->nested.average = 50.5f;
    data->nested.status = 1;

    log_info(pool, "Sensor data processed");

    deallocate_memory(pool, data);
    return NULL;
}

void calculate_and_print_average(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);

    // Example calculation
    float total = 42.0f; // Example value
    int count = 1;

    if (count > 0) {
        printf("Average: %f\n", total / count);
    }

    pthread_mutex_unlock(&pool->lock);
}

void cleanup_memory_pool(MemoryPool* pool) {
    MemoryBlock* current = pool->head;
    while (current) {
        MemoryBlock* to_free = current;
        current = current->next;

        free(to_free->ptr);
        free(to_free);
    }

    fclose(pool->log_file);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int main() {
    MemoryPool* pool = create_memory_pool();

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, process_data_stream, pool);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    calculate_and_print_average(pool);

    cleanup_memory_pool(pool);
    return 0;
}
```

This code implements a custom memory management system using a simple linked list to manage memory blocks. It includes thread-safe operations for allocating and deallocating memory, logging mechanisms with different verbosity levels, and a basic example of processing data streams in parallel threads. The code also demonstrates how to calculate an average from processed data.']

