// Thread-safe function to find and print the largest integer in an array
void *find_and_print_largest(void *args) {
    int *array;
    int size;
    pthread_mutex_t *mutex;

    // Unpack arguments
    void *arg_array[3];
    arg_array[0] = &array;
    arg_array[1] = &size;
    arg_array[2] = &mutex;
    memcpy(arg_array, args, 3 * sizeof(void*));

    int largest = find_largest_number(array, size);

    pthread_mutex_lock(mutex);
    printf("Largest integer: %d\n", largest);
    pthread_mutex_unlock(mutex);

    return NULL;
}

// Implementation
memory_pool_t* create_memory_pool(size_t initial_capacity) {
    memory_pool_t *pool = malloc(sizeof(memory_pool_t));
    if (!pool) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_capacity;
    pool->used = 0;
    pool->pool = malloc(initial_capacity * sizeof(void*));
    if (!pool->pool) {
        free(pool);
        perror("Failed to allocate memory for memory pool elements");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool_t *pool) {
    if (pool) {
        free(pool->pool);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

void* pool_allocate(memory_pool_t *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used + 1 > pool->capacity) {
        void **new_pool = realloc(pool->pool, (pool->capacity * 2) * sizeof(void*));
        if (!new_pool) {
            perror("Failed to resize memory pool");
            pthread_mutex_unlock(&pool->lock);
            exit(EXIT_FAILURE);
        }
        pool->pool = new_pool;
        pool->capacity *= 2;
    }

    void *ptr = malloc(size);
    if (!ptr) {
        perror("Failed to allocate memory from the pool");
        pthread_mutex_unlock(&pool->lock);
        exit(EXIT_FAILURE);
    }

    pool->pool[pool->used++] = ptr;

    pthread_mutex_unlock(&pool->lock);

    return ptr;
}

geometry_t* initialize_geometries(memory_pool_t *pool, int num_geom, double range_min, double range_max, int str_length) {
    geometry_t **geoms = malloc(num_geom * sizeof(geometry_t*));
    if (!geoms) {
        perror("Failed to allocate memory for geometries array");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_geom; ++i) {
        geoms[i] = pool_allocate(pool, sizeof(geometry_t));

        geoms[i]->value = RandomValueGenerator::get_float(range_min, range_max);
        geoms[i]->str = generate_random_string(str_length);

        geoms[i]->pt.x = (float)RandomValueGenerator::get_float(-100.0, 100.0);
        geoms[i]->pt.y = (float)RandomValueGenerator::get_float(-100.0, 100.0);
    }

    return geoms;
}

char* generate_random_string(int length) {
    const char charset[] =
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789";

    char *str = malloc((length + 1) * sizeof(char));
    if (!str) {
        perror("Failed to allocate memory for random string");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < length; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[length] = '\0';

