    u_char *pool;
    size_t size;
} MemoryPool;

void initMemoryPool(MemoryPool *mp, size_t size) {
    mp->pool = (u_char *)malloc(size);
    mp->size = size;
}

void freeMemoryPool(MemoryPool *mp) {
    if (mp->pool) {
        free(mp->pool);
        mp->pool = NULL;
    }
