// DNS Resolution Function
typedef struct {
    u_char ip[16];  // Supports both IPv4 and IPv6
} IPAddress;

int resolveDNS(const char *hostname, IPAddress *ipAddress, MemoryPool *mp) {
    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET || p->ai_family == AF_INET6) {
            void *addr;
            size_t addr_size = p->ai_addrlen;

            if (p->ai_family == AF_INET) {  // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
            } else {  // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
            }

            memcpy(ipAddress->ip, addr, addr_size);
            break;
        }
    }

    freeaddrinfo(res);
    return 0; // Success
}

// Strategy Pattern for Rule-Based Filtering
typedef struct {
    void (*filter)(IPAddress *ipAddress);  // Function pointer for filtering logic
} FilterStrategy;

void applyFilter(FilterStrategy *strategy, IPAddress *ipAddress) {
    if (strategy && strategy->filter) {
        strategy->filter(ipAddress);
    }
}

// Helper function to calculate the largest integer from an array
int findLargestInt(int *arr, size_t length) {
    int max = arr[0];
    for (size_t i = 1; i < length; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Helper function to calculate the average of positive floats
float averageOfPositiveFloats(float *numbers, size_t length) {
    float sum = 0.0f;
    int count = 0;

    for (size_t i = 0; i < length; ++i) {
        if (numbers[i] > 0) {
            sum += numbers[i];
            count++;
        }
    }

    return (count > 0) ? (sum / count) : 0.0f;
}

// Thread-safe mechanism for average calculation
pthread_mutex_t avgMutex = PTHREAD_MUTEX_INITIALIZER;

float threadSafeAverage(float *numbers, size_t length) {
    pthread_mutex_lock(&avgMutex);
    float result = averageOfPositiveFloats(numbers, length);
    pthread_mutex_unlock(&avgMutex);
    return result;
}

// Main Function to demonstrate usage
int main() {
    // Memory pool for IP addresses
    MemoryPool ipMemoryPool;
    initMemoryPool(&ipMemoryPool, 1024); // Example size

    IPAddress resolvedIP;
    const char *hostname = "example.com";

    if (resolveDNS(hostname, &resolvedIP, &ipMemoryPool) == 0) {
        printf("Resolved IP: ");
        for (int i = 0; i < sizeof(resolvedIP.ip); ++i) {
            printf("%02x", resolvedIP.ip[i]);
            if (i < sizeof(resolvedIP.ip) - 1) printf(":");
        }
        printf("\n");
    } else {
        fprintf(stderr, "DNS resolution failed.\n");
    }

    // Example usage of findLargestInt
