    printf("Average of positive floats: %.2f\n", threadSafeAverage(floatNumbers, sizeof(floatNumbers) / sizeof(floatNumbers[0])));

    // Cleanup
    freeMemoryPool(&ipMemoryPool);

    return 0;
}
