// Custom memory pool for efficient memory management
typedef struct {
    size_t block_size;
    void* memory_pool;
    size_t total_blocks;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->memory_pool = malloc(block_size * total_blocks);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    static void* next_free_block = NULL;
    if (!next_free_block) next_free_block = pool->memory_pool;
    if (next_free_block - pool->memory_pool + pool->block_size > pool->total_blocks * pool->block_size) return NULL; // Out of memory
    void* block = next_free_block;
    next_free_block += pool->block_size;
    return block;
}

void free_memory_pool(MemoryPool* pool) {
    free(pool->memory_pool);
    free(pool);
}

