    *result = sum / count;
}

void exponential_smoothing(const float* data, size_t count, float* result, float alpha) {
    if (count == 0) return;
    *result = data[0];
    for (size_t i = 1; i < count; ++i) {
        *result = alpha * data[i] + (1 - alpha) * (*result);
    }
}

