# Define custom data structures
OrderSummary = namedtuple('OrderSummary', ['ProductID', 'Quantity', 'Price'])
TradeMetrics = namedtuple('TradeMetrics', ['value', 'pairs', 'order_summary'])

# Memory Pool for efficient memory management
class MemoryPool:
    def __init__(self):
        self.lock = threading.Lock()
        self.floats_pool = []
        self.tuples_list_pool = []
        self.order_summaries_pool = []

    def allocate(self, data_type):
        with self.lock:
            if data_type == 'float':
                return self._allocate_float()
            elif data_type == 'List[Tuple[str, float]]':
                return self._allocate_tuples_list()
            elif data_type == 'OrderSummary':
                return self._allocate_order_summary()

    def _allocate_float(self):
        return random.random()  # Simulate allocation

    def _allocate_tuples_list(self):
        return [('random_str', random.random()) for _ in range(5)]

    def _allocate_order_summary(self):
        return OrderSummary(ProductID='1234', Quantity=10, Price=random.uniform(100.0, 500.0))

    def deallocate_all(self):
        with self.lock:
            self.floats_pool.clear()
            self.tuples_list_pool.clear()
            self.order_summaries_pool.clear()

# Strategy Pattern for Rule-based Filtering
class FilterStrategy:
    def filter(self, trade_metrics: TradeMetrics) -> bool:
        raise NotImplementedError

class PriceDeviationFilter(FilterStrategy):
    def __init__(self, threshold: float):
        self.threshold = threshold

    def filter(self, trade_metrics: TradeMetrics) -> bool:
        return abs(trade_metrics.order_summary.Price - 250.0) > self.threshold

# Trading Processor
class TradingProcessor:
    def __init__(self, memory_pool: MemoryPool, strategy: FilterStrategy):
        self.memory_pool = memory_pool
        self.strategy = strategy
        self.cache = {}
        self.lock = threading.Lock()

    async def process_data_stream(self, data_source):
        try:
            async for data in data_source:
                # Deserialize and allocate memory using custom framework
                trade_metrics = TradeMetrics(
                    value=self.memory_pool.allocate('float'),
                    pairs=self.memory_pool.allocate('List[Tuple[str, float]]'),
                    order_summary=self.memory_pool.allocate('OrderSummary')
                )

                if self.strategy.filter(trade_metrics):
                    await self.handle_trade(trade_metrics)

        except Exception as e:
            logging.error(f"Error processing data stream: {e}")
        finally:
            self.cleanup()

    async def handle_trade(self, trade_metrics: TradeMetrics):
        with self.lock:
            # Simulate handling the trade
            if trade_metrics.order_summary.ProductID in self.cache:
                order_summary = self.cache[trade_metrics.order_summary.ProductID]
            else:
                order_summary = trade_metrics.order_summary
                self.cache[trade_metrics.order_summary.ProductID] = order_summary

    def cleanup(self):
        # Proper memory management and deallocation
        self.memory_pool.deallocate_all()

# Helper function for average calculation
def calculate_average_positives(sock: socket.socket) -> float:
    lock = threading.Lock()
    total, count = 0.0, 0

    while True:
        data = sock.recv(1024)
        if not data:
            break

        floats_list = list(map(float, data.decode().split(',')))

        with lock:
            for num in floats_list:
                if num > 0:
                    total += num
                    count += 1

    return total / count if count != 0 else 0.0

# Example of using the TradingProcessor
async def main():
    memory_pool = MemoryPool()
    strategy = PriceDeviationFilter(threshold=50)
    processor = TradingProcessor(memory_pool, strategy)

    # Simulate data source (network socket, etc.)
    class DummyDataSource:
        async def __aiter__(self):
            for _ in range(10):  # simulate 10 data points
                yield None

    await processor.process_data_stream(DummyDataSource())

if __name__ == "__main__":
    asyncio.run(main())
