// Memory Pool Configuration
#define POOL_SIZE 1024 * 1024 // 1MB pool size
#define CONCURRENCY_LEVEL 4

typedef struct {
    uint8_t *pool;
    size_t block_size;
    size_t total_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool mem_pool = {NULL, sizeof(void*), POOL_SIZE / sizeof(void*), PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(size_t block_size) {
    if (mem_pool.pool != NULL) return;
    mem_pool.block_size = block_size;
    mem_pool.pool = malloc(POOL_SIZE);
    if (!mem_pool.pool) exit(EXIT_FAILURE);
}

void* allocate_from_pool() {
    pthread_mutex_lock(&mem_pool.lock);
    if (mem_pool.total_blocks > 0) {
        mem_pool.total_blocks--;
        void *ptr = mem_pool.pool + (mem_pool.block_size * (POOL_SIZE / mem_pool.block_size - mem_pool.total_blocks));
        pthread_mutex_unlock(&mem_pool.lock);
        return ptr;
    }
    pthread_mutex_unlock(&mem_pool.lock);
    return NULL; // Pool exhausted
}

void free_to_pool(void* ptr) {
    pthread_mutex_lock(&mem_pool.lock);
    if (ptr >= mem_pool.pool && ptr < (uint8_t*)mem_pool.pool + POOL_SIZE) {
        mem_pool.total_blocks++;
    }
    pthread_mutex_unlock(&mem_pool.lock);
}

