['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Task structure
typedef struct Task {
    int priority;
    char *identifier;
    int status; // 0 for incomplete, 1 for complete
    struct Task* next;
} Task;

// Node in the linked list (priority queue)
typedef struct Node {
    Task* task;
    struct Node* next;
} Node;

// Priority Queue
typedef struct PriorityQueue {
    Node* head;
    pthread_mutex_t lock; // Lock for thread safety
} PriorityQueue;

// Hash Table Entry
typedef struct HashEntry {
    char *identifier;
    Task* task;
    struct HashEntry* next;
} HashEntry;

// Hash Table
typedef struct HashTable {
    int size;
    HashEntry** table;
    pthread_mutex_t locks[]; // Array of mutexes for each bucket
    pthread_rwlock_t resize_lock; // Read-write lock for resizing the hash table
} HashTable;

// Constants
#define INITIAL_HASH_SIZE 16

// Function prototypes
unsigned long hash_function(const char *str, int size);
PriorityQueue* create_priority_queue();
void destroy_priority_queue(PriorityQueue* pq);
int add_task(PriorityQueue* pq, HashTable* ht, const char* identifier, int priority, int status);
Task* get_task_by_id(HashTable* ht, const char* identifier);
int update_task_status(HashTable* ht, const char* identifier, int new_status);
int resize_hash_table(HashTable* ht);

// Priority Queue Functions
PriorityQueue* create_priority_queue() {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (!pq) return NULL;
    pq->head = NULL;
    pthread_mutex_init(&pq->lock, NULL);
    return pq;
}

void destroy_priority_queue(PriorityQueue* pq) {
    Node* current = pq->head;
    while (current) {
        Node* next = current->next;
        free(current->task->identifier);
        free(current->task);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&pq->lock);
    free(pq);
}

int add_task(PriorityQueue* pq, HashTable* ht, const char* identifier, int priority, int status) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) return -1;

    new_task->identifier = strdup(identifier);
    new_task->priority = priority;
    new_task->status = status;
    new_task->next = NULL;

    // Add to priority queue
    pthread_mutex_lock(&pq->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        free(new_task->identifier);
        free(new_task);
        pthread_mutex_unlock(&pq->lock);
        return -1;
    }
    new_node->task = new_task;

    if (!pq->head || pq->head->task->priority < priority) {
        new_node->next = pq->head;
        pq->head = new_node;
    } else {
        Node* current = pq->head;
        while (current->next && current->next->task->priority >= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&pq->lock);

    // Add to hash table
    unsigned long index = hash_function(identifier, ht->size);
    pthread_mutex_lock(&ht->locks[index]);

    HashEntry* entry = (HashEntry*)malloc(sizeof(HashEntry));
    if (!entry) {
        free(new_task->identifier);
        free(new_task);
        free(new_node);
        pthread_mutex_unlock(&ht->locks[index]);
        return -1;
    }
    entry->identifier = strdup(identifier);
    entry->task = new_task;
    entry->next = ht->table[index];
    ht->table[index] = entry;

    pthread_mutex_unlock(&ht->locks[index]);

    return 0;
}

// Hash Table Functions
unsigned long hash_function(const char *str, int size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % size;
}

HashTable* create_hash_table(int size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->size = size;
    ht->table = (HashEntry**)calloc(size, sizeof(HashEntry*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    ht->locks = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t) * size);
    if (!ht->locks) {
        free(ht->table);
        free(ht);
        return NULL;
    }
    for (int i = 0; i < size; ++i)
        pthread_mutex_init(&ht->locks[i], NULL);

    pthread_rwlock_init(&ht->resize_lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable* ht) {
    for (int i = 0; i < ht->size; ++i) {
        HashEntry* entry = ht->table[i];
        while (entry) {
            HashEntry* next = entry->next;
            free(entry->identifier);
            free(entry);
            entry = next;
        }
        pthread_mutex_destroy(&ht->locks[i]);
    }

    free(ht->table);
    free(ht->locks);
    pthread_rwlock_destroy(&ht->resize_lock);
    free(ht);
}

Task* get_task_by_id(HashTable* ht, const char* identifier) {
    unsigned long index = hash_function(identifier, ht->size);
    pthread_mutex_lock(&ht->locks[index]);

    HashEntry* entry = ht->table[index];
    while (entry) {
        if (strcmp(entry->identifier, identifier) == 0) {
            Task* task = entry->task;
            pthread_mutex_unlock(&ht->locks[index]);
            return task;
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->locks[index]);
    return NULL;
}

int update_task_status(HashTable* ht, const char* identifier, int new_status) {
    unsigned long index = hash_function(identifier, ht->size);
    pthread_mutex_lock(&ht->locks[index]);

    HashEntry* entry = ht->table[index];
    while (entry) {
        if (strcmp(entry->identifier, identifier) == 0) {
            entry->task->status = new_status;
            pthread_mutex_unlock(&ht->locks[index]);
            return 0; // Success
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->locks[index]);
    return -1; // Task not found
}

int resize_hash_table(HashTable* ht) {
    int new_size = ht->size * 2;

    HashTable* new_ht = create_hash_table(new_size);
    if (!new_ht) return -1;

    for (int i = 0; i < ht->size; ++i) {
        pthread_mutex_lock(&ht->locks[i]);
        HashEntry* entry = ht->table[i];
        while (entry) {
            unsigned long new_index = hash_function(entry->identifier, new_size);
            pthread_mutex_lock(&new_ht->locks[new_index]);

            HashEntry* new_entry = (HashEntry*)malloc(sizeof(HashEntry));
            if (!new_entry) {
                pthread_mutex_unlock(&ht->locks[i]);
                pthread_mutex_unlock(&new_ht->locks[new_index]);
                destroy_hash_table(new_ht);
                return -1;
            }
            new_entry->identifier = strdup(entry->identifier);
            new_entry->task = entry->task;
            new_entry->next = new_ht->table[new_index];
            new_ht->table[new_index] = new_entry;

            pthread_mutex_unlock(&new_ht->locks[new_index]);
            entry = entry->next;
        }
        pthread_mutex_unlock(&ht->locks[i]);
    }

    // Replace old hash table with the resized one
    destroy_hash_table(ht);
    ht->size = new_size;
    ht->table = new_ht->table;
    ht->locks = new_ht->locks;

    return 0; // Success
}
