['Below is a C implementation that addresses your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int value;
} record;

typedef struct {
    size_t total_size;
    void *memory_pool;
    pthread_mutex_t lock;
    atomic_size_t allocated;
    atomic_size_t free_space;
} memory_pool_t;

// Initialize a custom memory pool
int init_memory_pool(memory_pool_t *pool, size_t size) {
    if (!pool) return -1;

    pool->total_size = size;
    pool->memory_pool = malloc(size);
    if (!pool->memory_pool) return -1;

    pthread_mutex_init(&pool->lock, NULL);
    atomic_store(&pool->allocated, 0);
    atomic_store(&pool->free_space, size);

    return 0;
}

// Allocate memory from the custom pool
void* allocate_from_pool(memory_pool_t *pool, size_t size) {
    if (!pool || !size) return NULL;

    pthread_mutex_lock(&pool->lock);
    if (atomic_load(&pool->allocated) + size > pool->total_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *ptr = (char*)pool->memory_pool + atomic_load(&pool->allocated);
    atomic_fetch_add(&pool->allocated, size);
    atomic_fetch_sub(&pool->free_space, size);

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Free all memory in the pool
void free_memory_pool(memory_pool_t *pool) {
    if (pool) {
        free(pool->memory_pool);
        pthread_mutex_destroy(&pool->lock);
    }
}

// Initialize arrays and records with a secure random generator
int initialize_data(long num_offsets, int num_keys, long min_value, long max_value,
                    long **offsets, int **keys, record **records, memory_pool_t *pool) {
    if (!offsets || !keys || !records || !pool) return -1;

    // Allocate and initialize offsets
    *offsets = (long*)allocate_from_pool(pool, num_offsets * sizeof(long));
    if (!*offsets) return -1;

    // Allocate and initialize keys
    *keys = (int*)allocate_from_pool(pool, num_keys * sizeof(int));
    if (!*keys) {
        free(*offsets);
        return -1;
    }

    // Allocate and initialize records
    *records = (record*)allocate_from_pool(pool, num_offsets * sizeof(record));
    if (!*records) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    pthread_mutex_t record_lock[num_offsets];
    for (long i = 0; i < num_offsets; ++i) {
        record_lock[i] = PTHREAD_MUTEX_INITIALIZER;
        (*offsets)[i] = rand() % (max_value - min_value + 1) + min_value;
        (*keys)[i % num_keys] = rand() % (max_value - min_value + 1) + min_value;
        pthread_mutex_lock(&record_lock[i]);
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
        pthread_mutex_unlock(&record_lock[i]);
    }

    return 0;
}

// Thread-safe function to update a record
void update_record(record *rec, int new_value, pthread_mutex_t *lock) {
    pthread_mutex_lock(lock);
    rec->value = new_value;
    pthread_mutex_unlock(lock);
}

// Function to provide memory usage statistics
void report_memory_usage(memory_pool_t *pool) {
    if (pool) {
        printf("Total Size: %zu\n", pool->total_size);
        printf("Allocated: %zu\n", atomic_load(&pool->allocated));
        printf("Free Space: %zu\n", atomic_load(&pool->free_space));
    }
}

// Example usage
int main() {
    memory_pool_t pool;
    if (init_memory_pool(&pool, 1024 * 1024) != 0) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return EXIT_FAILURE;
    }

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    if (initialize_data(100, 10, 1, 100, &offsets, &keys, &records, &pool) != 0) {
        fprintf(stderr, "Failed to initialize data.\n");
        free_memory_pool(&pool);
        return EXIT_FAILURE;
    }

    report_memory_usage(&pool);

    // Example of updating a record
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    update_record(&records[0], 42, &lock);

    // Cleanup
    free_memory_pool(&pool);
    return EXIT_SUCCESS;
}
