                self.flush_batch()

    def flush_batch(self):
        with self.lock:
            # Send batch to NoSQL DB
            self.batch = []

class UserAuthenticationStrategy(LogProcessingStrategy):
    def process(self, processed_data, log_entry):
        user_id = log_entry['user_id']
        timestamp = log_entry['timestamp']
        event_type = log_entry['event_type']
        score = log_entry['score']

        # Example processing logic
