#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char logBuffer[256];
} Record;

typedef struct MemoryBlock {
    size_t blockSize;
    void *data;
    struct MemoryBlock *next;
} MemoryBlock;

typedef struct {
    MemoryBlock *freeList;
    size_t block_size;
    pthread_mutex_t mutex;
    size_t totalAllocated;
    size_t peakMemoryUsage;
} MemoryPool;

void initMemoryPool(MemoryPool *pool, size_t block_size) {
    pool->block_size = block_size;
    pool->freeList = NULL;
    pool->totalAllocated = 0;
    pool->peakMemoryUsage = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

void* allocateBlock(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);

    MemoryBlock *block = pool->freeList;
    if (block) {
        pool->freeList = block->next;
    } else {
        block = malloc(pool->block_size + sizeof(MemoryBlock));
        if (!block) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&pool->mutex);
            exit(EXIT_FAILURE);
        }
    }

    void *data = (char*)block + sizeof(MemoryBlock);
    size_t currentUsage = pool->totalAllocated + pool->block_size;
    if (currentUsage > pool->peakMemoryUsage) {
        pool->peakMemoryUsage = currentUsage;
    }
    pool->totalAllocated += pool->block_size;

    pthread_mutex_unlock(&pool->mutex);
    return data;
}

void freeAll(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);

    MemoryBlock *current = pool->freeList;
    while (current) {
        MemoryBlock *next = current->next;
        free(current);
        current = next;
    }

    pool->totalAllocated = 0;
    pool->peakMemoryUsage = 0;

    pthread_mutex_unlock(&pool->mutex);
}

Record* createRecords(MemoryPool *pool, size_t num_records, int min_val, int max_val) {
    Record *records = (Record*)allocateBlock(pool);
    if (!records) return NULL;

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        snprintf(records[i].logBuffer, sizeof(records[i].logBuffer),
                 "Record ID: %zu, Value: %d", i, records[i].value);
    }

    return records;
}

void destroyRecords(MemoryPool *pool, Record *records) {
    if (records) {
        freeAll(pool);
    }
}

int main() {
    srand(time(NULL));

    MemoryPool pool;
    initMemoryPool(&pool, sizeof(Record) * 100);

    size_t num_records = 500;
    int min_val = 0, max_val = 100;

    Record *records = createRecords(&pool, num_records, min_val, max_val);
    if (records) {
        // Use records here
        destroyRecords(&pool, records);
    }

    return 0;
}
```

### Key Points:
- **Memory Pool**: A simple memory pool is implemented to manage allocations efficiently.
- **Thread Safety**: Mutexes are used to ensure thread-safe access to the memory pool.
- **Logging**: Basic logging is included in the `logBuffer` of each record.
- **Lifecycle Management**: Proper allocation and deallocation functions are provided to handle records' lifecycle.

This code provides a foundation for managing memory efficiently while allowing concurrent access, with room for further enhancements like more detailed logging or performance metrics.']

