        principal = null;
        try
        {
            var tokenHandler = new JwtSecurityTokenHandler();
            var key = Encoding.ASCII.GetBytes(secretKey);
            principal = tokenHandler.ValidateToken(token, new TokenValidationParameters
            {
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new SymmetricSecurityKey(key),
                ValidateIssuer = false,
                ValidateAudience = false
            }, out SecurityToken validatedToken);

            return principal.Identity.IsAuthenticated;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Authentication error: {ex.Message}");
            return false;
        }
    }

    public interface IAlertFilterStrategy
    {
        bool ShouldAlert(AlertLog alert);
    }

    // Example strategy implementation
    private class SimpleAlertFilter : IAlertFilterStrategy
    {
        public bool ShouldAlert(AlertLog alert)
        {
            return !string.IsNullOrWhiteSpace(alert.Description) && alert.Timestamp > DateTime.Now.AddMinutes(-5);
        }
    }
}
```

