['Here is a C code implementation for managing a dynamic collection of `record` structures with the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>

#define MAX_SLABS 10

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    size_t size;
    void *memory;
    pthread_mutex_t lock;
} slab;

typedef struct {
    slab slabs[MAX_SLABS];
    size_t slab_size;
    pthread_mutex_t mutex;
    FILE *file;
} memory_pool;

void init_memory_pool(memory_pool *pool, size_t slab_size) {
    pool->slab_size = slab_size;
    for (int i = 0; i < MAX_SLABS; ++i) {
        pool->slabs[i].size = 0;
        pool->slabs[i].memory = NULL;
        pthread_mutex_init(&pool->slabs[i].lock, NULL);
    }
    pthread_mutex_init(&pool->mutex, NULL);
}

void* allocate_record(memory_pool *pool) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < MAX_SLABS; ++i) {
        pthread_mutex_lock(&pool->slabs[i].lock);
        if (pool->slabs[i].size == 0) {
            pool->slabs[i].memory = malloc(pool->slab_size);
            if (!pool->slabs[i].memory) {
                pthread_mutex_unlock(&pool->slabs[i].lock);
                pthread_mutex_unlock(&pool->mutex);
                return NULL;
            }
            pool->slabs[i].size = pool->slab_size / sizeof(record);
        }
        record *record_ptr = (record*)pool->slabs[i].memory + pool->slabs[i].size - 1;
        --(pool->slabs[i].size);
        pthread_mutex_unlock(&pool->slabs[i].lock);

        pthread_mutex_unlock(&pool->mutex);
        return record_ptr;
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL; // No available slab
}

void free_memory_pool(memory_pool *pool) {
    for (int i = 0; i < MAX_SLABS; ++i) {
        if (pool->slabs[i].memory) {
            free(pool->slabs[i].memory);
        }
        pthread_mutex_destroy(&pool->slabs[i].lock);
    }
    pthread_mutex_destroy(&pool->mutex);
}

int serialize_record(const record *rec, unsigned char **buffer, size_t *size) {
    unsigned char *buf = (unsigned char*)malloc(16); // 8 bytes for long + 2*4 bytes for int
    if (!buf) return -1;

    memcpy(buf, &rec->offset, sizeof(rec->offset));
    memcpy(buf + sizeof(rec->offset), &rec->key, sizeof(rec->key));
    memcpy(buf + sizeof(rec->offset) + sizeof(rec->key), &rec->value, sizeof(rec->value));

    *buffer = buf;
    *size = 16;
    return 0;
}

void write_to_file(memory_pool *pool, const char *file_path) {
    pool->file = fopen(file_path, "wb");
    if (!pool->file) return;

    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < MAX_SLABS; ++i) {
        pthread_mutex_lock(&pool->slabs[i].lock);
        if (pool->slabs[i].memory) {
            size_t record_count = pool->slab_size / sizeof(record);
            unsigned char *buf;
            size_t buf_size;

            for (size_t j = 0; j < record_count - pool->slabs[i].size; ++j) {
                const record *rec = (record*)pool->slabs[i].memory + j;
                if (serialize_record(rec, &buf, &buf_size) == 0) {
                    fwrite(buf, buf_size, 1, pool->file);
                    free(buf);
                }
            }
        }
        pthread_mutex_unlock(&pool->slabs[i].lock);
    }
    fclose(pool->file);
    pthread_mutex_unlock(&pool->mutex);
}

int main() {
    memory_pool pool;
