```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_SIZE 256

typedef struct {
    int id;
    char log_message[MAX_LOG_SIZE];
} record;

typedef struct MemoryBlock {
    size_t size;
    void *ptr;
    struct MemoryBlock *next;
} MemoryBlock;

typedef struct {
    MemoryBlock *free_list;
    pthread_mutex_t lock;
    size_t total_size;
    size_t allocated_size;
    size_t peak_allocated_size;
} MemoryPool;

void initialize_pool(MemoryPool *pool, size_t initial_size) {
    pool->free_list = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->total_size = 0;
    pool->allocated_size = 0;
    pool->peak_allocated_size = 0;

    void *ptr = malloc(initial_size);
    if (ptr) {
        MemoryBlock *block = (MemoryBlock *)ptr;
        block->size = initial_size - sizeof(MemoryBlock);
        block->next = NULL;
        pool->free_list = block;
        pool->total_size += initial_size;
    }
}

void *allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    MemoryBlock **curr = &pool->free_list;
    while (*curr) {
        if ((*curr)->size >= size) {
            void *ptr = (char *)(*curr) + sizeof(MemoryBlock);
            *curr = (*curr)->next;

            pool->allocated_size += size + sizeof(MemoryBlock);
            if (pool->allocated_size > pool->peak_allocated_size) {
                pool->peak_allocated_size = pool->allocated_size;
            }

            pthread_mutex_unlock(&pool->lock);
            return ptr;
        }
        curr = &(*curr)->next;
    }

    // No suitable block found, allocate a new one
    void *ptr = malloc(size + sizeof(MemoryBlock) + 64); // Align to 64 bytes
    if (ptr) {
        MemoryBlock *new_block = (MemoryBlock *)ptr;
        new_block->size = size + 64 - sizeof(MemoryBlock);
        new_block->next = pool->free_list;

        pool->free_list = new_block;
        pool->allocated_size += new_block->size + sizeof(MemoryBlock);
        if (pool->allocated_size > pool->peak_allocated_size) {
            pool->peak_allocated_size = pool->allocated_size;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_pool(MemoryPool *pool) {
    MemoryBlock *curr = pool->free_list;
    while (curr) {
        MemoryBlock *next = curr->next;
        free(curr);
        curr = next;
    }
    pthread_mutex_destroy(&pool->lock);
}

record* create_records(size_t num_records, int id_range_min, int id_range_max, size_t log_size, MemoryPool *pool) {
    if (log_size > MAX_LOG_SIZE) {
        fprintf(stderr, "Log size exceeds maximum buffer size.\n");
        return NULL;
    }

    record *records = (record *)allocate_from_pool(pool, num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].id = id_range_min + rand() % (id_range_max - id_range_min + 1);
        snprintf(records[i].log_message, log_size,
                 "Record ID: %d, Value: %d", records[i].id, records[i].id);
    }

    return records;
}

int main() {
    MemoryPool pool;
    initialize_pool(&pool, 1024);

    size_t num_records = 100;
    int id_range_min = 1, id_range_max = 1000;
    size_t log_size = MAX_LOG_SIZE;

    record *records = create_records(num_records, id_range_min, id_range_max, log_size, &pool);
    if (records) {
        for (size_t i = 0; i < num_records; ++i) {
            printf("%s\n", records[i].log_message);
        }
        // Normally you'd free the memory using your pool's deallocation strategy
    }

    free_pool(&pool);
    return 0;
}
```

