#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 10 // Example: 10 MB limit

typedef struct {
    long *offset;
    int *key;
    int *value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} RecordCollection;

// Function prototypes
int init_record_collection(RecordCollection *collection, size_t initial_capacity, float growth_factor);
int resize_record_collection(RecordCollection *collection, size_t new_capacity);
void free_record_collection(RecordCollection *collection);
int validate_record_collection(const RecordCollection *collection);

extern int random_value(int min, int max); // Provided by user

// Initialize a record collection with specified capacity and growth factor
int init_record_collection(RecordCollection *collection, size_t initial_capacity, float growth_factor) {
    if (initial_capacity == 0 || growth_factor <= 1.0) return -1;

    pthread_mutex_init(&collection->lock, NULL);
    collection->capacity = initial_capacity;

    // Calculate required memory
    size_t offset_size = sizeof(long) * initial_capacity;
    size_t key_size = sizeof(int) * initial_capacity;
    size_t record_size = sizeof(record) * initial_capacity;

    if (offset_size + key_size + record_size > MAX_MEMORY_LIMIT) return -1;

    // Allocate memory
    collection->offsets = malloc(offset_size);
    collection->keys = malloc(key_size);
    collection->records = malloc(record_size);

    if (!collection->offsets || !collection->keys || !collection->records) {
        free_record_collection(collection);
        return -1;
    }

    // Initialize records
    for (size_t i = 0; i < initial_capacity; ++i) {
        collection->records[i].offset = &collection->offsets[i];
        collection->records[i].key = &collection->keys[i];
        collection->records[i].value = malloc(sizeof(int));
        if (!collection->records[i].value) {
            free_record_collection(collection);
            return -1;
        }
        *collection->records[i].value = random_value(0, 100); // Example range
    }

    return 0; // Success
}

// Resize the record collection
int resize_record_collection(RecordCollection *collection, size_t new_capacity) {
    if (new_capacity <= collection->capacity) return -1;

    size_t offset_size = sizeof(long) * new_capacity;
    size_t key_size = sizeof(int) * new_capacity;
    size_t record_size = sizeof(record) * new_capacity;

    if ((offset_size + key_size + record_size) > MAX_MEMORY_LIMIT) return -1;

    pthread_mutex_lock(&collection->lock);

    long *new_offsets = realloc(collection->offsets, offset_size);
    int *new_keys = realloc(collection->keys, key_size);
    record *new_records = realloc(collection->records, record_size);

    if (!new_offsets || !new_keys || !new_records) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    collection->offsets = new_offsets;
    collection->keys = new_keys;
    collection->records = new_records;

    for (size_t i = collection->capacity; i < new_capacity; ++i) {
        collection->records[i].offset = &collection->offsets[i];
        collection->records[i].key = &collection->keys[i];
        collection->records[i].value = malloc(sizeof(int));
        if (!collection->records[i].value) {
            pthread_mutex_unlock(&collection->lock);
            free_record_collection(collection);
            return -1;
        }
        *collection->records[i].value = random_value(0, 100); // Example range
    }

    collection->capacity = new_capacity;

    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

// Free the record collection
void free_record_collection(RecordCollection *collection) {
    if (!collection) return;

    for (size_t i = 0; i < collection->capacity; ++i) {
        free(collection->records[i].value);
    }

    free(collection->records);
    free(collection->keys);
    free(collection->offsets);

    pthread_mutex_destroy(&collection->lock);
}

// Validate the record collection
int validate_record_collection(const RecordCollection *collection) {
    if (!collection || !collection->offsets || !collection->keys || !collection->records) return -1;

    for (size_t i = 0; i < collection->capacity; ++i) {
        if (!collection->records[i].value) return -1;
        if (!collection->records[i].offset || !collection->records[i].key) return -1;
    }

    return 0; // Valid
}

int main() {
    RecordCollection collection;
    float growth_factor = 1.5;

    if (init_record_collection(&collection, 10, growth_factor) != 0) {
        fprintf(stderr, "Failed to initialize record collection\n");
        return -1;
    }

    if (validate_record_collection(&collection) != 0) {
        fprintf(stderr, "Record collection validation failed\n");
        free_record_collection(&collection);
        return -1;
    }

    // Example usage
    printf("Record collection initialized and validated successfully.\n");

    // Resize example
    if (resize_record_collection(&collection, 20) != 0) {
        fprintf(stderr, "Failed to resize record collection\n");
    } else {
        printf("Record collection resized successfully.\n");
    }

    free_record_collection(&collection);
    return 0;
}
