#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 16

typedef struct {
    long offset;
    int key;
    time_t timestamp; // Creation time
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    size_t max_records;
} MemoryPool;

MemoryPool* create_memory_pool(size_t max_records) {
    MemoryPool *pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    pool->records = (Record*) calloc(INITIAL_CAPACITY, sizeof(Record));
    pool->capacity = INITIAL_CAPACITY;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond_var, NULL);
    pool->max_records = max_records;
    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond_var);
    free(pool->records);
    free(pool);
}

void resize_memory_pool(MemoryPool *pool);

void insert_record(MemoryPool *pool, long offset, int key) {
    pthread_mutex_lock(&pool->mutex);

    while (pool->count == pool->max_records) {
        pthread_cond_wait(&pool->cond_var, &pool->mutex);
    }

    if (pool->count == pool->capacity) {
        resize_memory_pool(pool);
    }

    Record *record = &pool->records[pool->count++];
    record->offset = offset;
    record->key = key;
    record->timestamp = time(NULL);

    printf("Record inserted: offset=%ld, key=%d, timestamp=%ld\n", 
           record->offset, record->key, (long)record->timestamp);

    pthread_cond_signal(&pool->cond_var);
    pthread_mutex_unlock(&pool->mutex);
}

void resize_memory_pool(MemoryPool *pool) {
    size_t new_capacity = pool->capacity * 2;
    Record *new_records = (Record*) realloc(pool->records, new_capacity * sizeof(Record));

    if (!new_records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pool->records = new_records;
    pool->capacity = new_capacity;
}

void serialize_memory_pool(MemoryPool *pool, const char *filename) {
    pthread_mutex_lock(&pool->mutex);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    fwrite(pool->records, sizeof(Record), pool->count, file);
    fclose(file);

    printf("Serialization complete.\n");

    pthread_mutex_unlock(&pool->mutex);
}

void deserialize_memory_pool(MemoryPool *pool, const char *filename) {
    pthread_mutex_lock(&pool->mutex);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    size_t record_count = fread(pool->records, sizeof(Record), pool->capacity, file);
    if (ferror(file)) {
        perror("Error reading from file");
        fclose(file);
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    pool->count = record_count;
    fclose(file);

    printf("Deserialization complete. %zu records loaded.\n", pool->count);

    pthread_cond_broadcast(&pool->cond_var);
    pthread_mutex_unlock(&pool->mutex);
}

int main() {
    MemoryPool *pool = create_memory_pool(32);

    // Example usage
    insert_record(pool, 12345L, 1);
    serialize_memory_pool(pool, "records.dat");

    deserialize_memory_pool(pool, "records.dat");

    free_memory_pool(pool);

    return 0;
}
```

### Key Points:
- **Memory Pool**: Manages a dynamic array of `Record` structures with resizing.
- **Thread Safety**: Uses mutexes and condition variables to ensure thread-safe access.
- **Dynamic Resizing**: Doubles the capacity when needed, maintaining efficient memory use.
- **Serialization/Deserialization**: Saves and loads records to/from a file.
- **Logging**: Simple print statements for tracking operations.

### Trade-offs:
- **Efficiency vs. Complexity**: Mutexes provide safety but can introduce latency.
- **Resizing Overhead**: Doubling capacity balances between resizing frequency and memory waste.
- **Serialization Speed**: Binary format optimizes speed over human readability.
- **Scalability**: Shared memory pool across threads improves performance but requires careful synchronization.

This implementation provides a foundation for further enhancements, such as more sophisticated logging or alternative concurrency mechanisms like read-write locks.']

