    char* next_free;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    pthread_mutex_init(&mp->lock, NULL);
    mp->block_size = block_size;
    mp->pool_size = block_size * num_blocks;
    mp->pool = malloc(mp->pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    mp->next_free = (char*)mp->pool;

    return mp;
}

void* pool_allocate(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);

    if ((size > mp->block_size) || (mp->next_free + size > (char*)mp->pool + mp->pool_size)) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // No suitable block available
    }

    void* block = mp->next_free;
    mp->next_free += size;

    pthread_mutex_unlock(&mp->lock);
    return block;
}

void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

