typedef struct {
    float some_float;
    char *identifier;
    size_t id_length;
} entry;

// Define a simple memory pool for allocations
#define POOL_SIZE 1024 * 1024 // 1MB pool

typedef struct MemoryPool {
    void *pool;
    size_t offset;
    pthread_mutex_t lock; // Mutex to make the memory pool thread-safe
} MemoryPool;

void init_memory_pool(MemoryPool *mp, size_t size) {
    mp->pool = malloc(size);
    if (!mp->pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mp->offset = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void* allocate_from_pool(MemoryPool *mp, size_t size) {
    void *ptr = NULL;
    pthread_mutex_lock(&mp->lock);
    if (size + mp->offset <= POOL_SIZE) {
        ptr = (char*)mp->pool + mp->offset;
        mp->offset += size;
    }
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

// Initialize and manage arrays using a custom memory pool
int initialize_data_structures(double **doubles, char ***strings,
                               entry **entries, size_t num_entries) {

    MemoryPool mp;
    init_memory_pool(&mp, POOL_SIZE);

    *doubles = allocate_from_pool(&mp, num_entries * sizeof(double));
    if (!*doubles) return -1;

    // Allocate space for string pointers
    *strings = allocate_from_pool(&mp, num_entries * sizeof(char*));
    if (!*strings) {
        free(*doubles);
        return -1;
    }

    // Allocate space for entries
    *entries = allocate_from_pool(&mp, num_entries * sizeof(entry));
    if (!*entries) {
        free(*doubles);
        free(*strings);
        return -1;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize arrays and simulate DBMS integration & API handling
    for (size_t i = 0; i < num_entries; ++i) {
        (*doubles)[i] = (double)i + 0.5;

        size_t id_length = snprintf(NULL, 0, "ID-%zu", i) + 1;
        (*strings)[i] = allocate_from_pool(&mp, id_length);
        if (!(*strings)[i]) {
            fprintf(stderr, "Failed to allocate string for ID %zu\n", i);
            continue;
        }
        snprintf((char*)*strings[i], id_length, "ID-%zu", i);

        (*entries)[i].some_float = (float)i;
        pthread_mutex_lock(&lock);
        // Simulate interaction with DBMS
        pthread_mutex_unlock(&lock);

        (*entries)[i].identifier = *strings[i];
        (*entries)[i].id_length = id_length;
    }

    // Cleanup and verify data integrity
    free_memory_pool(&mp);
    return 0; // Return success or handle errors as appropriate
}

// Usage example
