['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_SIZE 1048576 // 1 MB

struct Record {
    int key;
    long offset;
};

struct MemoryManager {
    struct Record *firstArray;
    struct Record *secondArray;
    size_t firstArraySize;
    size_t secondArraySize;
    size_t totalAllocatedMemory;
    time_t lastAccessTime[1000]; // Assuming maximum 1000 records for LRU tracking
    int accessedRecordIndex[1000];
};

void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

size_t getCurrentMemoryUsage(struct MemoryManager *manager) {
    return manager->totalAllocatedMemory;
}

int allocateFirstArray(struct MemoryManager *manager, size_t size) {
    struct Record *array = (struct Record *)malloc(size * sizeof(struct Record));
    if (!array) {
        logError("Failed to allocate first array");
        return 0;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i].key = 0;
        array[i].offset = (long)&(array[i]);
        manager->lastAccessTime[i] = time(NULL);
        manager->accessedRecordIndex[i] = i;
    }
    manager->firstArray = array;
    manager->firstArraySize = size;
    manager->totalAllocatedMemory += size * sizeof(struct Record);
    return 1;
}

int allocateSecondArray(struct MemoryManager *manager, size_t size) {
    struct Record *array = (struct Record *)malloc(size * sizeof(struct Record));
    if (!array) {
        logError("Failed to allocate second array");
        return 0;
    }
    manager->secondArray = array;
    manager->secondArraySize = size;
    manager->totalAllocatedMemory += size * sizeof(struct Record);
    return 1;
}

void freeLeastRecentlyUsed(struct MemoryManager *manager, size_t needed) {
    if (manager->firstArray == NULL || manager->firstArraySize == 0) return;

    // Sort accessedRecordIndex based on lastAccessTime for LRU
    for (size_t i = 0; i < manager->firstArraySize - 1; ++i) {
        for (size_t j = i + 1; j < manager->firstArraySize; ++j) {
            if (manager->lastAccessTime[manager->accessedRecordIndex[i]] > 
                manager->lastAccessTime[manager->accessedRecordIndex[j]]) {
                int temp = manager->accessedRecordIndex[i];
                manager->accessedRecordIndex[i] = manager->accessedRecordIndex[j];
                manager->accessedRecordIndex[j] = temp;
            }
        }
    }

    size_t freedMemory = 0;
    for (size_t i = 0; i < manager->firstArraySize && needed > freedMemory; ++i) {
        struct Record *record = &manager->firstArray[manager->accessedRecordIndex[i]];
        free(record);
        manager->totalAllocatedMemory -= sizeof(struct Record);
        freedMemory += sizeof(struct Record);
    }
}

int initializeSecondArrayKeys(struct MemoryManager *manager) {
    if (manager->secondArray == NULL || manager->secondArraySize == 0) return 0;

    srand(time(NULL));
    int initializedCount = 0;
    for (size_t i = 0; i < manager->secondArraySize / 2; ++i) {
        int key;
        do {
            key = rand() % 1001;
        } while (!isUniqueKey(manager, key));

        struct Record *record = &manager->secondArray[i];
        record->key = key;
        record->offset = (long)&(record);
        initializedCount++;
    }
    return initializedCount;
}

int isUniqueKey(struct MemoryManager *manager, int key) {
    for (size_t i = 0; i < manager->secondArraySize / 2; ++i) {
        if (manager->secondArray[i].key == key) {
            return 0;
        }
    }
    return 1;
}

int manageArrays(struct MemoryManager *manager, size_t firstArraySize, size_t secondArraySize) {
    if (!allocateFirstArray(manager, firstArraySize)) {
        return -1;
    }

    while (getCurrentMemoryUsage(manager) + secondArraySize * sizeof(struct Record) > MAX_MEMORY_SIZE) {
        freeLeastRecentlyUsed(manager, secondArraySize * sizeof(struct Record));
        if (manager->totalAllocatedMemory + secondArraySize * sizeof(struct Record) > MAX_MEMORY_SIZE) {
            logError("Unable to allocate memory within limits");
            return -1;
        }
    }

    if (!allocateSecondArray(manager, secondArraySize)) {
        free(manager->firstArray);
        manager->firstArray = NULL;
        return -1;
    }

    int initializedCount = initializeSecondArrayKeys(manager);

    // Log current memory usage
    printf("Total allocated memory: %zu bytes\n", getCurrentMemoryUsage(manager));

    return initializedCount;
}

int main() {
    struct MemoryManager manager = {0};
    size_t firstArraySize = 100; // Example sizes
    size_t secondArraySize = 200;

    int result = manageArrays(&manager, firstArraySize, secondArraySize);
    if (result >= 0) {
