#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct Node {
    record data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} Cache;

Cache cache = {NULL, PTHREAD_MUTEX_INITIALIZER};

void init_cache() {
    pthread_mutex_lock(&cache.lock);
    if (cache.head == NULL) {
        cache.head = malloc(sizeof(Node));
        if (!cache.head) {
            perror("Failed to initialize cache");
            exit(EXIT_FAILURE);
        }
        cache.head->next = NULL;
    }
    pthread_mutex_unlock(&cache.lock);
}

void serialize_to_json(record* rec, char** json_out) {
    static pthread_mutex_t json_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&json_lock);

    // Check if cached JSON exists
    Node* current = cache.head;
    while (current) {
        if (current->data.value == rec->value) {
            *json_out = strdup("Cached JSON");
            pthread_mutex_unlock(&json_lock);
            return;
        }
        current = current->next;
    }

    // Generate new JSON
    char* json = malloc(50); // Allocate more if necessary
    snprintf(json, 50, "{\"value\": %d}", rec->value);

    // Cache the result
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to cache JSON");
        pthread_mutex_unlock(&json_lock);
        exit(EXIT_FAILURE);
    }
    new_node->data.value = rec->value;
    new_node->next = cache.head;
    cache.head = new_node;

    *json_out = json;

    pthread_mutex_unlock(&json_lock);
}

record* allocate_records(int num_records, int range_min, int range_max, size_t max_memory_mb) {
    if (num_records <= 0 || range_min >= range_max || max_memory_mb == 0) {
        return NULL; // Invalid input
    }

    const size_t record_size = sizeof(record);
    const size_t max_memory_bytes = max_memory_mb * 1024 * 1024;
    int available_records = (int)(max_memory_bytes / record_size);

    if (num_records > available_records) {
        fprintf(stderr, "Requested number of records exceeds memory limit.\n");
        return NULL; // Too many records
    }

    pthread_mutex_t alloc_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&alloc_lock);
    record* records = malloc(num_records * record_size);
    if (!records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&alloc_lock);
        return NULL;
    }
    pthread_mutex_unlock(&alloc_lock);

    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < num_records; ++i) {
        records[i].value = range_min + rand() % (range_max - range_min + 1);
    }

    return records;
}

void free_records(record* records) {
    if (!records) return;

    pthread_mutex_t alloc_lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&alloc_lock);
    free(records);
    pthread_mutex_unlock(&alloc_lock);

    // Clear cache
    pthread_mutex_lock(&cache.lock);
    Node* current = cache.head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    cache.head = NULL;
    pthread_mutex_unlock(&cache.lock);
}

int main() {
    init_cache();

    int num_records = 1000;
    int range_min = 1, range_max = 100;
    size_t max_memory_mb = 10;

    record* records = allocate_records(num_records, range_min, range_max, max_memory_mb);
    if (!records) return EXIT_FAILURE;

    char* json_output;
    serialize_to_json(&records[0], &json_output);
    printf("%s\n", json_output);

    free(records);
    free(json_output);

    return 0;
}
