#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>

#define MAX_TASKS 10000000
#define RETRY_LIMIT 3

typedef struct Task {
    time_t timestamp;
    char *description;
    pid_t process_id;
} Task;

typedef struct Node {
    Task tasks[MAX_TASKS];
    int task_count;
    pthread_mutex_t lock;
} Node;

Node nodes[10]; // Assuming a fixed number of nodes for simplicity
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void init_node(int node_index) {
    nodes[node_index].task_count = 0;
    pthread_mutex_init(&nodes[node_index].lock, NULL);
}

Task* add_task(int node_index, time_t timestamp, const char *description, pid_t process_id) {
    pthread_mutex_lock(&global_lock);

    if (node_index < 0 || node_index >= 10) {
        pthread_mutex_unlock(&global_lock);
        return NULL;
    }

    Node *node = &nodes[node_index];

    pthread_mutex_lock(&node->lock);
    if (node->task_count >= MAX_TASKS) {
        pthread_mutex_unlock(&node->lock);
        pthread_mutex_unlock(&global_lock);
        return NULL;
    }

    Task *new_task = &node->tasks[node->task_count++];
    new_task->timestamp = timestamp;
    new_task->description = strdup(description);
    new_task->process_id = process_id;

    pthread_mutex_unlock(&node->lock);
    pthread_mutex_unlock(&global_lock);

    // Simulate message queue interaction
    if (!send_to_message_queue(node_index, new_task)) {
        retry_send_to_message_queue(node_index, new_task);
    }

    return new_task;
}

int send_to_message_queue(int node_index, Task *task) {
    // Placeholder for actual message queue sending logic
    printf("Sending task to message queue: %s\n", task->description);
    return 1; // Simulate success
}

void retry_send_to_message_queue(int node_index, Task *task) {
    int retries = 0;
    while (retries < RETRY_LIMIT && !send_to_message_queue(node_index, task)) {
        retries++;
        usleep(100000); // Wait for 100ms before retrying
    }
}

Task* get_task(int node_index, int index) {
    pthread_mutex_lock(&global_lock);

    if (node_index < 0 || node_index >= 10) {
        pthread_mutex_unlock(&global_lock);
        return NULL;
    }

    Node *node = &nodes[node_index];

    pthread_mutex_lock(&node->lock);
    if (index < 0 || index >= node->task_count) {
        pthread_mutex_unlock(&node->lock);
        pthread_mutex_unlock(&global_lock);
        return NULL;
    }

    Task *task = &node->tasks[index];
    pthread_mutex_unlock(&node->lock);
    pthread_mutex_unlock(&global_lock);

    return task;
}

int remove_task(int node_index, int index) {
    pthread_mutex_lock(&global_lock);

    if (node_index < 0 || node_index >= 10) {
        pthread_mutex_unlock(&global_lock);
        return -1;
    }

    Node *node = &nodes[node_index];

    pthread_mutex_lock(&node->lock);
    if (index < 0 || index >= node->task_count) {
        pthread_mutex_unlock(&node->lock);
        pthread_mutex_unlock(&global_lock);
        return -1;
    }

    free(node->tasks[index].description);
    memmove(&node->tasks[index], &node->tasks[index + 1],
            (node->task_count - index - 1) * sizeof(Task));
    node->task_count--;

    pthread_mutex_unlock(&node->lock);
    pthread_mutex_unlock(&global_lock);

    return 0;
}

void cleanup_node(int node_index) {
    pthread_mutex_lock(&nodes[node_index].lock);
    for (int i = 0; i < nodes[node_index].task_count; ++i) {
        free(nodes[node_index].tasks[i].description);
    }
    nodes[node_index].task_count = 0;
    pthread_mutex_unlock(&nodes[node_index].lock);
}

int main() {
    for (int i = 0; i < 10; ++i) {
        init_node(i);
    }

    add_task(0, time(NULL), "Task 1", getpid());
    Task *retrieved_task = get_task(0, 0);

    if (retrieved_task) {
        printf("Retrieved task: %s\n", retrieved_task->description);
    }

    remove_task(0, 0);
    cleanup_node(0);

    return 0;
}
```

