```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.IO.Compression;
using System.Net.Http;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using System.Threading.Tasks;

public class CustomDataStructure
{
    // Define the structure of your custom data here.
}

public class Record
{
    public int TimeSinceLastQuery { get; set; }
    public string Hostname { get; set; }
}

public class DataLoader
{
    private readonly ConcurrentDictionary<string, Record> _cache = new();
    private readonly TimeSpan _refreshInterval = TimeSpan.FromMinutes(5);
    private readonly HttpClient _httpClient;

    public DataLoader()
    {
        _httpClient = new HttpClient();

        // Start background scheduler to refresh cache.
        Task.Run(() => RefreshCacheLoop());
    }

    public async Task<CustomDataStructure> LoadAndResolveData(string filePath)
    {
        try
        {
            using (var stream = await OpenFileStreamAsync(filePath))
            using (var decompressedStream = DecompressIfNeeded(stream, filePath))
            {
                var formatter = new BinaryFormatter();

                // Deserialize data asynchronously to optimize performance.
                return await Task.Run(() => (CustomDataStructure)formatter.Deserialize(decompressedStream));
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading and resolving data: {ex.Message}");
            throw;  // Or handle specific exceptions based on your requirements
        }
    }

    private async Task<Stream> OpenFileStreamAsync(string filePath)
    {
        return new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.None, bufferSize: 4096, useAsync: true);
    }

    private Stream DecompressIfNeeded(Stream stream, string filePath)
    {
        if (filePath.EndsWith(".gz"))
        {
            return new GZipStream(stream, CompressionMode.Decompress);
        }

        // Add support for additional compression types as needed.

        return stream;
    }

    private async Task RefreshCacheLoop()
    {
        while (true)
        {
            try
            {
                foreach (var entry in _cache.Keys)
                {
                    var record = await ResolveDnsAsync(entry);
                    if (record != null)
                    {
                        _cache[entry] = record;
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error refreshing cache: {ex.Message}");
            }

            // Wait for the next refresh cycle.
            await Task.Delay(_refreshInterval);
        }
    }

    private async Task<Record> ResolveDnsAsync(string hostname)
    {
        try
        {
            var response = await _httpClient.GetHostEntryAsync(hostname);

            if (response.AddressList.Length > 0)
            {
                return new Record { Hostname = hostname, TimeSinceLastQuery = 0 };
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"DNS resolution failed for {hostname}: {ex.Message}");
        }

        // Return null or handle DNS resolution failure appropriately.
        return null;
    }
}

// Usage example:
public class Program
{
    public static async Task Main(string[] args)
    {
        var dataLoader = new DataLoader();

        try
        {
            var customDataStructure = await dataLoader.LoadAndResolveData("path/to/your/file.bin.gz");
            // Use the deserialized data as needed.
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
```

