AggregationNode* find_or_insert_node(AggregationsTable *table, const char *id, long start_time, long end_time) {
    size_t index = hash_function(id, table->size);
    for (int i = 0; i < table->size; ++i) {
        AggregationNode *node = &table->nodes[(index + i) % table->size];
        if (!strcmp(node->id, id) && node->start_time == start_time && node->end_time == end_time)
            return node;
    }

    // Insert new node
    for (int i = 0; i < table->size; ++i) {
        AggregationNode *node = &table->nodes[(index + i) % table->size];
        if (!node->id[0]) { // Empty slot found
            strncpy(node->id, id, MAX_IDENTIFIER_LENGTH);
            node->start_time = start_time;
            node->end_time = end_time;
            node->sum_metric = 0.0;
            node->count = 0;
            return node;
        }
    }

    // Handle table resizing if necessary
    size_t new_size = table->size * 2;
    AggregationNode *new_nodes = realloc(table->nodes, new_size * sizeof(AggregationNode));
    if (!new_nodes) {
        free(table->nodes);
        return NULL;
    }

    memset(new_nodes + table->size, 0, (new_size - table->size) * sizeof(AggregationNode));
    table->nodes = new_nodes;
    table->size = new_size;

    // Retry finding or inserting the node
    return find_or_insert_node(table, id, start_time, end_time);
}

