    if (node) {
        for (int i = 0; i < METRICS_COUNT; ++i) {
            node->sum_metric += row->metrics[i];
        }
        node->count++;
    }
    pthread_rwlock_unlock(&rwlock);

    free(row->identifier);
    free(row->metrics);
    free(row);
