void processAndAggregateData(const char *file_path, long time_window) {
    mem_pool = create_memory_pool(POOL_SIZE);
    row_queue = create_lockfree_queue(QUEUE_SIZE);

    FILE *file = fopen(file_path, "r");
    if (!file) return;

    global_aggregations = create_aggregations_table(INITIAL_TABLE_SIZE);

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    char buffer[LINE_BUFFER_SIZE];

    while (fgets(buffer, sizeof(buffer), file)) {
        DataRow *row = allocate_from_memory_pool(mem_pool);
        if (!parse_row(buffer, row)) continue;

        // Enqueue the data row for processing
        enqueue_to_lockfree_queue(row_queue, row);

        if (thread_count < MAX_THREADS) {
            pthread_create(&threads[thread_count++], NULL, process_row, dequeue_from_lockfree_queue(row_queue));
        } else {
            for (int i = 0; i < MAX_THREADS; ++i) {
                void *result;
                pthread_join(threads[i], &result);
            }
            thread_count = 1;
            pthread_create(&threads[0], NULL, process_row, dequeue_from_lockfree_queue(row_queue));
        }
    }

    // Join remaining threads
    for (int i = 0; i < thread_count; ++i) {
        void *result;
        pthread_join(threads[i], &result);
    }

    fclose(file);

    // Cleanup and memory deallocation
    destroy_memory_pool(mem_pool);
    destroy_lockfree_queue(row_queue);
    free(global_aggregations->nodes);
    free(global_aggregations);
}

