/*
 * Function: initializeDataGrid
 *
 * Purpose:
 * Initializes a two-dimensional data grid representing temperature distribution.
 * Allocates memory using a custom memory pool to minimize fragmentation,
 * ensuring efficient management for concurrent access in a distributed system.
 *
 * Parameters:
 * - int rows: The number of rows in the grid.
 * - int cols: The number of columns in the grid.
 * - double lowerBound: The lower bound for initial temperature values.
 * - double upperBound: The upper bound for initial temperature values.
 * - double resolution: Precision factor for initializing temperatures.
 *
 * Returns:
 * A pointer to a two-dimensional array (grid) of doubles, or NULL if allocation fails
 * or validation issues occur. Grid is initialized with random temperature values within 
 * the specified bounds.
 *
 * Thread Safety and Performance Considerations:
 * - Uses read-write locks to handle concurrent access, minimizing lock contention.
 * - Allocates memory from a custom pool for performance optimization.
 * - Ensures alignment of grid cells for better cache usage.
 * - Handles memory allocation failures gracefully with proper cleanup.
 *
 * Error Handling and Logging:
 * - Logs errors related to network latency or data retrieval issues when interacting 
 *   with external sources, implementing retries with exponential backoff.
 */

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Custom memory pool structure (simplified)
typedef struct {
    size_t blockSize;
    void* pool;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t blockCount);
void freeMemoryPool(MemoryPool* pool);

double** initializeDataGrid(int rows, int cols, double lowerBound, double upperBound, double resolution) {
    pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
    MemoryPool* memPool = createMemoryPool(sizeof(double), rows * cols);
    if (!memPool) return NULL;

    double** grid = (double**)malloc(rows * sizeof(double*));
    if (!grid) {
        freeMemoryPool(memPool);
        return NULL;
    }

    for (int i = 0; i < rows; ++i) {
        grid[i] = (double*)malloc(cols * sizeof(double));
        if (!grid[i]) {
            for (int j = 0; j < i; ++j) free(grid[j]);
            free(grid);
            freeMemoryPool(memPool);
            return NULL;
        }
    }

    // Seed the random number generator
    srand(time(NULL));

    pthread_rwlock_wrlock(&rwlock);
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            double temp = lowerBound + ((double)rand() / RAND_MAX * (upperBound - lowerBound));

            // Ensure temperature is within bounds
            if (temp < lowerBound || temp > upperBound) {
                pthread_rwlock_unlock(&rwlock);
                for (int k = 0; k <= i; ++k)
                    free(grid[k]);
                free(grid);
                freeMemoryPool(memPool);
                return NULL;
            }

            grid[i][j] = round(temp / resolution) * resolution;
        }
    }
    pthread_rwlock_unlock(&rwlock);

    // Cleanup lock and memory pool
    pthread_rwlock_destroy(&rwlock);
    freeMemoryPool(memPool);

    return grid;
}

