```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int year;
    int month;
    int day;
    int hour;
    int minute;
    int second;
} timestamp_t;

typedef struct {
    int value;
    char string[256];
    timestamp_t creation_time;
} record_t;

#define INITIAL_SIZE 16
#define LOAD_FACTOR 0.75

typedef struct node_t {
    int key;
    record_t record;
    struct node_t *next;
    pthread_mutex_t lock;
} node_t;

typedef struct {
    node_t **buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t resize_lock;
} hash_table_t;

hash_table_t* create_hash_table(size_t initial_capacity) {
    hash_table_t *table = malloc(sizeof(hash_table_t));
    table->capacity = initial_capacity;
    table->count = 0;
    table->buckets = calloc(table->capacity, sizeof(node_t *));
    pthread_mutex_init(&table->resize_lock, NULL);
    return table;
}

size_t hash_function(int key, size_t capacity) {
    return key % capacity;
}

void lock_node(node_t *node) {
    pthread_mutex_lock(&node->lock);
}

void unlock_node(node_t *node) {
    pthread_mutex_unlock(&node->lock);
}

void resize_hash_table(hash_table_t *table);

void insert_record(hash_table_t *table, int key, record_t record) {
    size_t index = hash_function(key, table->capacity);
    node_t *new_node = malloc(sizeof(node_t));
    new_node->key = key;
    new_node->record = record;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    lock_node(new_node);
    lock_node(table->buckets[index]);

    if (!table->buckets[index]) {
        table->buckets[index] = new_node;
    } else {
        node_t *current = table->buckets[index];
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    unlock_node(table->buckets[index]);
    unlock_node(new_node);

    pthread_mutex_lock(&table->resize_lock);
    if ((float)table->count / table->capacity > LOAD_FACTOR) {
        resize_hash_table(table);
    }
    table->count++;
    pthread_mutex_unlock(&table->resize_lock);
}

record_t* get_record(hash_table_t *table, int key) {
    size_t index = hash_function(key, table->capacity);
    node_t *current = table->buckets[index];

    lock_node(current);

    while (current) {
        if (current->key == key) {
            record_t *result = malloc(sizeof(record_t));
            *result = current->record;
            unlock_node(current);
            return result;
        }
        current = current->next;
    }

    unlock_node(current);
    return NULL;
}

void resize_hash_table(hash_table_t *table) {
    size_t new_capacity = table->capacity * 2;
    node_t **new_buckets = calloc(new_capacity, sizeof(node_t *));

    for (size_t i = 0; i < table->capacity; i++) {
        node_t *current = table->buckets[i];

        while (current) {
            size_t new_index = hash_function(current->key, new_capacity);

            lock_node(current);

            if (!new_buckets[new_index]) {
                new_buckets[new_index] = current;
                current->next = NULL;
            } else {
                node_t *bucket_head = new_buckets[new_index];

                while (bucket_head->next) {
                    bucket_head = bucket_head->next;
                }

                bucket_head->next = current;
                current->next = NULL;
            }

            unlock_node(current);

            node_t *temp = current;
            current = current->next;
            temp->next = table->buckets[i];
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void cleanup_hash_table(hash_table_t *table) {
    for (size_t i = 0; i < table->capacity; i++) {
        node_t *current = table->buckets[i];

        while (current) {
            node_t *temp = current;
            current = current->next;

            pthread_mutex_destroy(&temp->lock);
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->resize_lock);
    free(table);
}

int main() {
    hash_table_t *store = create_hash_table(INITIAL_SIZE);

    timestamp_t ts = {2023, 10, 5, 15, 30, 0};
    record_t rec = {42, "Sample Record", ts};

    insert_record(store, 1, rec);

    record_t *fetched_rec = get_record(store, 1);
    if (fetched_rec) {
        printf("Fetched Record: %d, %s\n", fetched_rec->value, fetched_rec->string);
        free(fetched_rec);
    }

    cleanup_hash_table(store);

    return 0;
}
```

### Key Points:
- **Concurrency**: Fine-grained locking is used with each node to minimize contention.
- **Memory Management**: A simple custom hash table manages memory allocations and resizes dynamically as needed.
- **Error Handling**: Basic error checks are implemented, but real-world scenarios would require more comprehensive handling.
- **Performance**: The design balances between speed and memory usage by resizing based on a load factor.']

