    pthread_mutex_lock(&mutex);
    if (size + sizeof(size_t) > POOL_SIZE) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    void *ptr = memory_pool;
    *(size_t *)ptr = size;
    ptr += sizeof(size_t);
    memory_pool += size + sizeof(size_t);
    pthread_mutex_unlock(&mutex);
    return ptr;
}

void deallocate_memory(void) {
    memset(memory_pool, 0, POOL_SIZE); // Reset the pool
}

// Helper functions
char *generate_random_string(int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *random_str = (char *)allocate_from_pool(length + 1);
    if (!random_str) return NULL;

    for (int i = 0; i < length; i++) {
        random_str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    random_str[length] = '\0';
    return random_str;
}

float generate_random_float(float min, float max) {
    return ((float)rand() / RAND_MAX) * (max - min) + min;
}

void initialize_records(record **records, size_t num_records) {
    for (size_t i = 0; i < num_records; i++) {
        records[i] = (record *)allocate_from_pool(sizeof(record));
        if (!records[i]) return;

        records[i]->val = rand() / (float)RAND_MAX;
        records[i]->string = generate_random_string(10);
        records[i]->obj_item.id = rand();
        records[i]->obj_item.value = generate_random_float(0.0f, 100.0f);
    }
}

void initialize_containers(container **containers, size_t num_containers) {
    for (size_t i = 0; i < num_containers; i++) {
        containers[i] = (container *)allocate_from_pool(sizeof(container));
        if (!containers[i]) return;

        containers[i]->number = rand() / (float)RAND_MAX;
        containers[i]->str = generate_random_string(10);
        containers[i]->ptr_item = (item *)allocate_from_pool(sizeof(item));
        if (!containers[i]->ptr_item) return;

        containers[i]->ptr_item->id = rand();
        containers[i]->ptr_item->value = generate_random_float(0.0f, 100.0f);
    }
}

// Median function
void find_and_print_median(int *numbers, size_t count) {
    qsort(numbers, count, sizeof(int), (int (*)(const void *, const void *))strcmp);

    if (count % 2 == 0) {
        printf("Median: %.1f\n", (numbers[count / 2 - 1] + numbers[count / 2]) / 2.0);
    } else {
        printf("Median: %d\n", numbers[count / 2]);
    }
}

// Thread-safe input function
void read_integers_and_find_median() {
    size_t count = 10;
    int *numbers = (int *)allocate_from_pool(count * sizeof(int));
    if (!numbers) return;

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < count; i++) {
        printf("Enter integer %zu: ", i + 1);
        scanf("%d", &numbers[i]);
    }
    pthread_mutex_unlock(&mutex);

    find_and_print_median(numbers, count);
    free((void *)numbers); // Freeing memory after use
}

// Main function demonstrating usage
int main() {
    srand(time(NULL));

    size_t num_records = 5;
    record *records[num_records];
    initialize_records(records, num_records);

    size_t num_containers = 3;
    container *containers[num_containers];
    initialize_containers(containers, num_containers);

    read_integers_and_find_median();

    // Cleanup
    for (size_t i = 0; i < num_records; i++) {
        free(records[i]->string);
        free((void *)records[i]);
    }

    for (size_t i = 0; i < num_containers; i++) {
        free(containers[i]->str);
        free((void *)containers[i]->ptr_item);
        free((void *)containers[i]);
    }

    deallocate_memory();

    return 0;
}
