        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[str_len] = '\0';

    geometry->s = str;
}

void free_memory_pool() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < pool_index; ++i) {
