        return NULL; // Error: invalid input
    }

    // Allocate memory for the shapes array
    Shape *shapes = (Shape *)malloc(num_shapes * sizeof(Shape));
    if (!shapes) {
        *error_code = -1; // Allocation failed
        return NULL;
    }

    // Allocate and initialize memory for points, areas, perimeters
    double *areas = (double *)malloc(num_shapes * sizeof(double));
    unsigned long *perimeters = (unsigned long *)malloc(num_shapes * sizeof(unsigned long));
    Point *points = (Point *)malloc(num_shapes * sizeof(Point));

    if (!areas || !perimeters || !points) {
        free(shapes);
        free(areas);  // Only free if allocated
        free(perimeters);  // Only free if allocated
        free(points);  // Only free if allocated

        *error_code = -2; // Allocation failed for any component
        return NULL;
    }

    // Initialize each shape with dummy values or actual computations
    for (size_t i = 0; i < num_shapes; ++i) {
        areas[i] = 1.0;      // Example area initialization
        perimeters[i] = 4UL; // Example perimeter initialization

