        points[i].y = 0.0f;   // Example center y coordinate

        shapes[i].area = areas[i];
        shapes[i].perimeter = perimeters[i];
        shapes[i].center = &points[i]; // Assign pointer to the point in the array
    }

    *error_code = 0; // Success

    return shapes;
}

// Function to free allocated memory
void destroy_shapes_array(Shape *shapes, size_t num_shapes) {
    if (shapes != NULL) {
        free(shapes);
    }
}

// Accessor function for iterating over shapes safely
const Shape* get_shape_at(const Shape *shapes, size_t index) {
    return (index < ARRAY_SIZE(shapes)) ? &shapes[index] : NULL;
}

int main() {
    int error_code = 0;
    size_t num_shapes = 5; // Example number of shapes

    Shape *shapes = create_shapes_array(num_shapes, &error_code);

    if (!shapes) {
        printf("Failed to allocate memory for shapes with error code: %d\n", error_code);
        return 1;
    }

    // Iterate over shapes and access their attributes
    for (size_t i = 0; i < num_shapes; ++i) {
        const Shape *shape = get_shape_at(shapes, i);
        if (shape != NULL) {
            printf("Shape %zu: Area=%.2f, Perimeter=%lu, Center=(%.1f, %.1f)\n",
                   i, shape->area, shape->perimeter,
                   shape->center->x, shape->center->y);
        }
    }

    // Free allocated memory
