    Account account;
    std::chrono::system_clock::time_point timestamp;
};

class Strategy {
public:
    virtual void process(std::vector<TransactionEvent>& data) = 0;
    virtual ~Strategy() {}
};

class SortStrategy : public Strategy {
public:
    void process(std::vector<TransactionEvent>& data) override {
        std::sort(data.begin(), data.end(),
            [](const TransactionEvent& a, const TransactionEvent& b) {
                return a.amount < b.amount; // Example: sort by amount
            });
    }
};

class FilterStrategy : public Strategy {
public:
    void process(std::vector<TransactionEvent>& data) override {
        data.erase(std::remove_if(data.begin(), data.end(),
            [](const TransactionEvent& e) { return e.amount < 0.0; }), // Example: filter out negative amounts
            data.end());
    }
};

class AggregationStrategy : public Strategy {
public:
    void process(std::vector<TransactionEvent>& data) override {
        double totalAmount = 0;
        for (const auto& event : data) {
            totalAmount += event.amount;
        }
        std::cout << "Total Amount: " << totalAmount << "\n";
    }
};

class DataProcessor {
private:
    std::unique_ptr<Strategy> strategy;

public:
    void setStrategy(std::unique_ptr<Strategy> strat) {
        strategy = std::move(strat);
    }

    void processTransactions(std::vector<TransactionEvent>& data) {
        if (strategy) {
            strategy->process(data);
        }
    }
};

void initializeRandomFields(TransactionEvent& event, int maxAccountID, float minBalance, float maxBalance, size_t descriptionLength) {
    std::random_device rd;
    std::mt19937 gen(rd());

    // Random Account ID
    std::uniform_int_distribution<> idDist(1, maxAccountID);
    event.account.id = idDist(gen);

    // Random Balance
    std::uniform_real_distribution<float> balanceDist(minBalance, maxBalance);
    event.account.balance = balanceDist(gen);

    // Random Description
    const char alphanum[] =
        "0123456789"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz";
    for (size_t i = 0; i < descriptionLength; ++i) {
        std::uniform_int_distribution<> descDist(0, sizeof(alphanum) - 2);
        event.description += alphanum[descDist(gen)];
    }

    // Set timestamp to current time
    event.timestamp = std::chrono::system_clock::now();
}

void processFinancialDataStream(std::vector<TransactionEvent>& transactions, int maxAccountID, float minBalance, float maxBalance, size_t descriptionLength) {
    for (auto& transaction : transactions) {
        initializeRandomFields(transaction, maxAccountID, minBalance, maxBalance, descriptionLength);
    }

    DataProcessor processor;

    // Example usage of strategy pattern
    auto sortStrategy = std::make_unique<SortStrategy>();
    processor.setStrategy(std::move(sortStrategy));
    processor.processTransactions(transactions);

    auto filterStrategy = std::make_unique<FilterStrategy>();
    processor.setStrategy(std::move(filterStrategy));
    processor.processTransactions(transactions);

    auto aggregationStrategy = std::make_unique<AggregationStrategy>();
    processor.setStrategy(std::move(aggregationStrategy));
    processor.processTransactions(transactions);
}

int main() {
    try {
        int maxAccountID = 10000;
        float minBalance = 0.0f;
        float maxBalance = 1000000.0f;
        size_t descriptionLength = 20;

        std::vector<TransactionEvent> transactions(100000); // Simulate a large number of transactions

        processFinancialDataStream(transactions, maxAccountID, minBalance, maxBalance, descriptionLength);

    } catch (const std::exception& e) {
        std::cerr << "Exception caught: " << e.what() << '\n';
    }

    return 0;
}
