class MemoryPool {
public:
    template<typename T>
    T* allocate(size_t size) {
        auto ptr = std::make_unique<T[]>(size);
        log_allocation(ptr.get(), sizeof(T) * size);
        return ptr.release();
    }

    template<typename T>
    void deallocate(T* ptr, size_t size) {
        log_deallocation(ptr, sizeof(T) * size);
        delete[] ptr;
    }

private:
    void log_allocation(void* ptr, size_t size) const {
        std::ofstream logFile("memory_log.txt", std::ios_base::app);
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);

        logFile << "Allocated at " << std::ctime(&in_time_t)
                << "Size: " << size << " bytes, Address: " << ptr << '\n';
    }

    void log_deallocation(void* ptr, size_t size) const {
        std::ofstream logFile("memory_log.txt", std::ios_base::app);
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);

        logFile << "Deallocated at " << std::ctime(&in_time_t)
                << "Size: " << size << " bytes, Address: " << ptr << '\n';
