#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <inttypes.h>
#include "md5.h" // Assume an MD5 library is available

#define MAX_INPUT_SIZE 1024
#define LOG_FILE_NAME "app.log"
#define LOG_MAX_SIZE (1 * 1024 * 1024) // 1 MB
#define RAND_RANGE_LOW 0
#define RAND_RANGE_HIGH 100
#define INITIAL_POOL_SIZE 1024

typedef struct {
    int value;
} Record;

typedef struct MemoryPoolNode {
    void* memory;
    size_t size;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct MemoryPool {
    MemoryPoolNode* head;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

void initializeMemoryPool(MemoryPool* mp, size_t initialSize) {
    mp->head = malloc(sizeof(MemoryPoolNode));
    mp->head->memory = malloc(initialSize);
    mp->head->size = initialSize;
    mp->head->next = NULL;
    pthread_mutex_init(&mp->lock, NULL);
}

void* allocateMemory(MemoryPool* mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    MemoryPoolNode* node = mp->head;

    while (node != NULL && ((char*)node->memory + node->size - sizeof(size_t)) < (char*)node->memory + node->size) {
        node = node->next;
    }

    if (node == NULL || size > node->size - sizeof(size_t)) {
        MemoryPoolNode* newNode = malloc(sizeof(MemoryPoolNode));
        newNode->memory = malloc(initialSize);
        newNode->size = initialSize;
        newNode->next = mp->head;
        mp->head = newNode;
        node = mp->head;
    }

    void* allocatedMemory = (char*)node->memory + sizeof(size_t);
    *(size_t*)((char*)allocatedMemory - sizeof(size_t)) = size;

    pthread_mutex_unlock(&mp->lock);

    return allocatedMemory;
}

void freeMemoryPool(MemoryPool* mp) {
    MemoryPoolNode* current = mp->head;
    while (current != NULL) {
        MemoryPoolNode* next = current->next;
        free(current->memory);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&mp->lock);
}

void logMessage(const char* message) {
    static FILE* logFile = NULL;
    static pthread_mutex_t logLock = PTHREAD_MUTEX_INITIALIZER;

    if (!logFile) {
        logFile = fopen(LOG_FILE_NAME, "a");
        fseek(logFile, 0, SEEK_END);
        if (ftell(logFile) > LOG_MAX_SIZE) {
            fclose(logFile);
            logFile = fopen(LOG_FILE_NAME, "w"); // Rotate the log
        }
    }

    pthread_mutex_lock(&logLock);
    fprintf(logFile, "%s\n", message);
    fflush(logFile); // Ensure message is written immediately
    pthread_mutex_unlock(&logLock);
}

void* hashInput(void* arg) {
    int* number = (int*)arg;
    unsigned char digest[MD5_DIGEST_LENGTH];
    md5((unsigned char*)number, sizeof(int), digest);

    char hexOutput[33];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i)
        sprintf(&hexOutput[i * 2], "%02x", (unsigned int)digest[i]);

    logMessage(hexOutput);
    return NULL;
}

long processInputAndAggregate() {
    initializeMemoryPool(&pool, INITIAL_POOL_SIZE);

    int* keys = allocateMemory(&pool, MAX_INPUT_SIZE * sizeof(int));
    long* offsets = allocateMemory(&pool, MAX_INPUT_SIZE * sizeof(long));
    Record* records = (Record*)allocateMemory(&pool, MAX_INPUT_SIZE * sizeof(Record));

    int input[MAX_INPUT_SIZE];
    int count = 0;

    while (scanf("%d", &input[count]) == 1 && count < MAX_INPUT_SIZE) {
        pthread_t thread_id;

        // Calculate the MD5 hash for each integer in parallel
        if (pthread_create(&thread_id, NULL, hashInput, (void*)&input[count])) {
            logMessage("Failed to create a hashing thread");
        }
        pthread_join(thread_id, NULL);

        keys[count] = input[count];
        offsets[count] = rand() % 1000;
        records[count].value = RAND_RANGE_LOW + rand() % (RAND_RANGE_HIGH - RAND_RANGE_LOW + 1);

        count++;
    }

    long largestInt = (count > 0) ? keys[0] : 0;

    for (int i = 1; i < count; ++i) {
        if (keys[i] > largestInt)
            largestInt = keys[i];
    }

    freeMemoryPool(&pool);

    return largestInt;
}

int main() {
    long result = processInputAndAggregate();
    printf("Largest Integer: %ld\n", result);
    return 0;
}
