    if (records_size > MAX_SIZE) {
        fprintf(stderr, "Error: Size exceeds maximum limit.\n");
        return NULL;
    }

    long *offsets = malloc(offsets_size * sizeof(long));
    int *keys = malloc(keys_size * sizeof(int));

    record *records = malloc(records_size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free_resources(offsets, keys, records, records_size);
        return NULL;
    }

    printf("Enter range for random values (min max): ");
    scanf("%d %d", &range_min, &range_max);
    if (range_min > range_max || range_max - range_min > INT_MAX) {
