    for (size_t i = 0; i < offsets_size; ++i) {
        offsets[i] = rand();
    }
    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = rand() % (range_max - range_min + 1) + range_min;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < records_size; ++i) {
        pthread_mutex_lock(&lock);
        records[i].value = rand() % (range_max - range_min + 1) + range_min;

        char buffer[STRING_LENGTH];
        snprintf(buffer, STRING_LENGTH, "Record_%zu", i);
        records[i].name = strdup(buffer);

        if (!records[i].name) {
            fprintf(stderr, "Failed to allocate memory for record name.\n");
            free_resources(offsets, keys, records, records_size);
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        pthread_mutex_unlock(&lock);
    }

    // Simulate logging
    printf("Function executed successfully at %ld\n", time(NULL));

    free_resources(offsets, keys, records, records_size);
    pthread_mutex_destroy(&lock);

    return NULL;
}

int main() {
    allocate_and_initialize(NULL);
    return 0;
}
