#define MAX_THRESHOLD 1000000

typedef struct {
    int key;
    long offset;
} Record;

// Function prototypes
void initializeRecords(int *recordCount, Record **records);
void adjustRecordSizes(Record **records, int *recordCount);
void populateRecords(Record *records, int recordCount, const char *distributionType);
void serializeRecords(const Record *records, int recordCount, FILE *file);
int deserializeRecords(Record **records, int *recordCount, FILE *file);
void manageFileIO(const char *filename);

// Helper functions
long getAvailableRAM();
void logAdjustment(int newRecordCount);
void handleMemoryError();

void initializeRecords(int *recordCount, Record **records) {
    size_t availableRAM = getAvailableRAM();
    int maxRecords = (availableRAM / 2) / (sizeof(int) + sizeof(long));

    *recordCount = rand() % maxRecords;
    if (*recordCount == 0) *recordCount = 1;

    *records = malloc(*recordCount * sizeof(Record));
    if (!*records) handleMemoryError();

    adjustRecordSizes(records, recordCount);
}

void adjustRecordSizes(Record **records, int *recordCount) {
    size_t availableRAM = getAvailableRAM();
    long totalMemoryUsage = (*recordCount) * (sizeof(int) + sizeof(long));

    while (totalMemoryUsage > availableRAM / 2) {
        *recordCount /= 2;
        totalMemoryUsage = (*recordCount) * (sizeof(int) + sizeof(long));
        logAdjustment(*recordCount);

        Record *newRecords = realloc(*records, *recordCount * sizeof(Record));
        if (!newRecords) handleMemoryError();
        *records = newRecords;
    }
}

void populateRecords(Record *records, int recordCount, const char *distributionType) {
    long totalOffsetSum = 0;

    for (int i = 0; i < recordCount; ++i) {
        records[i].key = rand() % 10000;

        if (strcmp(distributionType, "uniform") == 0) {
            records[i].offset = rand() % 1000;
        } else if (strcmp(distributionType, "normal") == 0) {
            double mean = 500.0;
            double stddev = 100.0;
            records[i].offset = (long)(mean + stddev * ((double)rand() / RAND_MAX));
        }

        totalOffsetSum += records[i].offset;
    }

    if (totalOffsetSum > MAX_THRESHOLD) {
        for (int i = 0; i < recordCount; ++i) {
            records[i].offset = (long)((double)records[i].offset * MAX_THRESHOLD / totalOffsetSum);
        }
    }
}

void serializeRecords(const Record *records, int recordCount, FILE *file) {
    if (!fwrite(records, sizeof(Record), recordCount, file)) {
        perror("Serialization failed");
    }
}

int deserializeRecords(Record **records, int *recordCount, FILE *file) {
    size_t readSize = fread(*records, sizeof(Record), *recordCount, file);
    if (readSize != (size_t)*recordCount) {
        perror("Deserialization mismatch");
        return 0;
    }
    return 1;
}

void manageFileIO(const char *filename) {
    FILE *file = fopen(filename, "wb+");
    if (!file) {
        perror("File opening failed");
        return;
    }

    int recordCount;
    Record *records;

    initializeRecords(&recordCount, &records);
    populateRecords(records, recordCount, "uniform");

    serializeRecords(records, recordCount, file);

    // Reset file pointer to the beginning
    rewind(file);

    Record *deserializedRecords = malloc(recordCount * sizeof(Record));
    if (!deserializeRecords(&deserializedRecords, &recordCount, file)) {
        handleMemoryError();
    }

    fclose(file);
    free(records);
    free(deserializedRecords);
}

long getAvailableRAM() {
    // Mock function to simulate available RAM
    return 8L * 1024 * 1024 * 1024; // Assume 8 GB for example purposes
}

void logAdjustment(int newRecordCount) {
    printf("Adjusted record count: %d\n", newRecordCount);
}

void handleMemoryError() {
    fprintf(stderr, "Memory allocation failed.\n");
    exit(EXIT_FAILURE);
}
