    size_t char_count = char_initial_count;
    size_t event_count = event_initial_count;

    adjust_data_structures(&float_count, float_size,
                           &char_count, char_size,
                           &event_count, event_size,
                           total_memory);

    // Allocate and initialize structures
    float *floats = malloc(float_count * float_size);
    if (!floats) {
        fprintf(stderr, "Memory allocation failed for floats\n");
        return;
    }

    char **strings = malloc(char_count * sizeof(char *));
    if (!strings) {
        free(floats);
        fprintf(stderr, "Memory allocation failed for strings\n");
        return;
    }

    EventLog *event_logs = NULL;
    int populate_success = populate_event_logs(&event_logs, &event_count, levels, num_levels);
    if (!populate_success || !event_logs) {
        free(strings);
        free(floats);
        fprintf(stderr, "Event log population failed\n");
        return;
    }

    // Serialize event logs
    serialize_event_logs(event_logs, event_count);

    // Cleanup
    free(strings);
    free(floats);
    free(event_logs);
}

void adjust_data_structures(size_t *float_count, size_t float_size,
                            size_t *char_count, size_t char_size,
                            size_t *event_count, size_t event_size,
                            size_t max_memory) {

    // Prioritize reducing the largest structure first
    size_t total_float_size = (*float_count) * float_size;
    size_t total_char_size = (*char_count) * char_size;
    size_t total_event_size = (*event_count) * event_size;

    while (total_float_size + total_char_size + total_event_size > max_memory) {
        if (total_event_size >= total_float_size && total_event_size >= total_char_size) {
            (*event_count)--;
            total_event_size = (*event_count) * event_size;
        } else if (total_char_size >= total_float_size) {
            (*char_count)--;
            total_char_size = (*char_count) * char_size;
        } else {
            (*float_count)--;
            total_float_size = (*float_count) * float_size;
        }
    }
}

int populate_event_logs(EventLog **logs, size_t *log_count, const char *levels[], int num_levels) {
    if (!logs || !*log_count) return 0;

    EventLog *new_logs = malloc(*log_count * sizeof(EventLog));
    if (!new_logs) return 0;

    for (size_t i = 0; i < *log_count; ++i) {
        new_logs[i].timestamp = time(NULL); // Current timestamp
        strncpy(new_logs[i].level, levels[rand() % num_levels], sizeof(new_logs[i].level) - 1);
        new_logs[i].level[sizeof(new_logs[i].level) - 1] = '\0';
    }

    *logs = new_logs;
    return 1;
}

void serialize_event_logs(const EventLog *logs, size_t log_count) {
    if (!logs || !log_count) return;

    printf("[\n");
    for (size_t i = 0; i < log_count; ++i) {
        printf("  {\"timestamp\": %ld, \"level\": \"%s\"}", logs[i].timestamp, logs[i].level);
        if (i < log_count - 1) {
            printf(",");
        }
        printf("\n");
    }
    printf("]\n");
}
