#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define MAX_MEMORY_BUDGET 1048576 // 1MB

typedef struct {
    float x;
    float y;
} point_t;

typedef struct {
    double value;
    char string[256];
    point_t pt;
} geometry_t;

typedef struct measurement {
    float temperature;
    char* location_name;
    time_t timestamp;
} measurement_t;

typedef struct record {
    int value;
} record_t;

typedef struct telemetry_data {
    pthread_mutex_t lock;
    float *temperatures;
    char **sensor_ids;
    measurement_t **measurements;
    long event_offset;
    int sequence_number;
    unsigned int size;
    unsigned int capacity;
} telemetry_data_t;

static void* custom_malloc(size_t size) {
    static size_t pool_size = 0;
    static void *memory_pool = NULL;

    if (pool_size == 0) {
        memory_pool = malloc(MAX_MEMORY_BUDGET);
        if (!memory_pool) {
            perror("Failed to allocate initial memory pool");
            exit(EXIT_FAILURE);
        }
        pool_size = MAX_MEMORY_BUDGET;
    }

    if (size > pool_size) {
        fprintf(stderr, "Requested size exceeds available memory budget\n");
        return NULL;
    }

    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pool_size -= size;
    return ptr;
}

static void* custom_realloc(void *ptr, size_t new_size) {
    void *new_ptr = realloc(ptr, new_size);
    if (!new_ptr) {
        perror("Memory reallocation failed");
        free(ptr);
        exit(EXIT_FAILURE);
    }
    return new_ptr;
}

telemetry_data_t* init_telemetry_data(unsigned int initial_capacity) {
    telemetry_data_t *data = (telemetry_data_t*)custom_malloc(sizeof(telemetry_data_t));
    data->temperatures = (float*)custom_malloc(initial_capacity * sizeof(float));
    data->sensor_ids = (char**)custom_malloc(initial_capacity * sizeof(char*));
    data->measurements = (measurement_t**)custom_malloc(initial_capacity * sizeof(measurement_t*));
    data->capacity = initial_capacity;
    data->size = 0;
    pthread_mutex_init(&data->lock, NULL);
    return data;
}

void resize_telemetry_data(telemetry_data_t *data) {
    unsigned int new_capacity = data->capacity * 2;

    float *new_temps = (float*)custom_realloc(data->temperatures, new_capacity * sizeof(float));
    char **new_ids = (char**)custom_realloc(data->sensor_ids, new_capacity * sizeof(char*));
    measurement_t **new_measurements = (measurement_t**)custom_realloc(data->measurements, new_capacity * sizeof(measurement_t*));

    data->temperatures = new_temps;
    data->sensor_ids = new_ids;
    data->measurements = new_measurements;
    data->capacity = new_capacity;
}

void record_measurement(telemetry_data_t *data, float temperature, const char *sensor_id, const char *location_name) {
    pthread_mutex_lock(&data->lock);

    if (data->size == data->capacity) {
        resize_telemetry_data(data);
    }

    data->temperatures[data->size] = temperature;
    data->sensor_ids[data->size] = strdup(sensor_id);
    measurement_t *new_measurement = (measurement_t*)custom_malloc(sizeof(measurement_t));
    new_measurement->temperature = temperature;
    new_measurement->location_name = strdup(location_name);
    new_measurement->timestamp = time(NULL);

    data->measurements[data->size] = new_measurement;
    data->size++;

    pthread_mutex_unlock(&data->lock);
}

void free_telemetry_data(telemetry_data_t *data) {
    for (unsigned int i = 0; i < data->size; ++i) {
        free(data->sensor_ids[i]);
        free(data->measurements[i]->location_name);
        free(data->measurements[i]);
    }

    pthread_mutex_destroy(&data->lock);
    free(data->temperatures);
    free(data->sensor_ids);
    free(data->measurements);
    free(data);
}

void process_integers(void) {
    int largest = INT_MIN;
    int value;

    while (scanf("%d", &value) == 1) {
        if (value > largest) {
            largest = value;
        }
    }

    printf("Largest integer: %d\n", largest);
}
```

