#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <limits.h>

#define MAX_THREADS 10

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    size_t block_size;
    void* start_ptr;
    void** free_list_head;
} MemoryPool;

void* allocate_from_pool(MemoryPool* pool, size_t num_blocks);
void deallocate_all(MemoryPool* pool);

MemoryPool offset_pool, key_pool, record_pool;

pthread_mutex_t input_lock = PTHREAD_MUTEX_INITIALIZER;
atomic_int largest_value(INT_MIN);

typedef struct {
    long* offsets;
    int* keys;
    record* records;
} ThreadData;

ThreadData thread_data[MAX_THREADS];

void* thread_func(void* arg) {
    int thread_id = *(int*)arg;

    for (size_t i = 0; i < sizeof(long); ++i)
        ((long*)(thread_data[thread_id].offsets))[i] = rand() % 100;

    for (size_t i = 0; i < sizeof(int); ++i)
        thread_data[thread_id].keys[i] = rand() % 100;

    for (size_t i = 0; i < sizeof(record); ++i) {
        ((record*)(thread_data[thread_id].records))[i].value = rand() % 100;
        atomic_fetch_max(&largest_value, ((record*)(thread_data[thread_id].records))[i].value);
    }

    return NULL;
}

void initialize_memory_pools(size_t num_records, size_t num_threads) {
    offset_pool.block_size = sizeof(long);
    key_pool.block_size = sizeof(int);
    record_pool.block_size = sizeof(record);

    offset_pool.start_ptr = malloc(sizeof(long) * num_records);
    key_pool.start_ptr = malloc(sizeof(int) * num_records);
    record_pool.start_ptr = malloc(sizeof(record) * num_records);

    offset_pool.free_list_head = (void**)&offset_pool.start_ptr;
    key_pool.free_list_head = (void**)&key_pool.start_ptr;
    record_pool.free_list_head = (void**)&record_pool.start_ptr;

    for (size_t i = 0; i < num_threads; ++i) {
        thread_data[i].offsets = allocate_from_pool(&offset_pool, sizeof(long));
        thread_data[i].keys = allocate_from_pool(&key_pool, sizeof(int));
        thread_data[i].records = allocate_from_pool(&record_pool, sizeof(record));
    }
}

void* allocate_from_pool(MemoryPool* pool, size_t num_blocks) {
    if (!pool->free_list_head) return NULL;

    void* ptr = *pool->free_list_head;
    *pool->free_list_head = *(void**)ptr;

    if (*pool->free_list_head == NULL)
        pool->free_list_head = NULL; // No more blocks

    return ptr;
}

void deallocate_all(MemoryPool* pool) {
    void** current = (void**)&(pool->start_ptr);

    while (*current) {
        *(void**)current = *(void**)(*current);
        current = (void**)*current;
    }

    *current = NULL;
}

int main() {
    size_t num_records, num_threads;
    printf("Enter number of records: ");
    scanf("%zu", &num_records);

    printf("Enter number of threads: ");
    scanf("%zu", &num_threads);

    if (num_threads > MAX_THREADS) num_threads = MAX_THREADS;

    pthread_t threads[num_threads];
    int thread_ids[num_threads];

    initialize_memory_pools(num_records, num_threads);

    for (size_t i = 0; i < num_threads; ++i) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_func, &thread_ids[i]);
    }

    for (size_t i = 0; i < num_threads; ++i)
        pthread_join(threads[i], NULL);

    printf("Largest value: %d\n", atomic_load(&largest_value));

    deallocate_all(&offset_pool);
    deallocate_all(&key_pool);
    deallocate_all(&record_pool);

    free(offset_pool.start_ptr);
    free(key_pool.start_ptr);
    free(record_pool.start_ptr);

    return 0;
}
