#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define KEYWORD_COUNT 5
const char *keywords[] = {"alpha", "beta", "gamma", "delta", "epsilon"};

typedef struct {
    float value;
    char *label;
    time_t timestamp;
} measurement;

// Memory pool structure
typedef struct {
    size_t block_size;
    size_t total_blocks;
    void *pool;
    pthread_mutex_t lock;
} memory_pool;

// Hash table node
typedef struct hash_node {
    char *key;
    measurement data;
    struct hash_node *next;
} hash_node;

// Hash table structure
typedef struct {
    size_t size;
    hash_node **buckets;
    pthread_mutex_t *locks;
} hash_table;

// Function prototypes
memory_pool* create_memory_pool(size_t block_size, size_t total_blocks);
void destroy_memory_pool(memory_pool *pool);

hash_table* create_hash_table(size_t size);
void destroy_hash_table(hash_table *table);
size_t hash_function(const char *str, size_t table_size);
void insert_measurement(hash_table *table, measurement data);
measurement* find_measurement(hash_table *table, const char *label);
void compute_average(float *average, int count);

// Utility functions
char* generate_random_string(size_t length);
char* secure_password_handling(const char *input);

// Memory pool management
memory_pool* create_memory_pool(size_t block_size, size_t total_blocks) {
    memory_pool *pool = (memory_pool *)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->pool = malloc(block_size * total_blocks);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(memory_pool *pool) {
    if (pool) {
        free(pool->pool);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

// Hash table management
hash_table* create_hash_table(size_t size) {
    hash_table *table = (hash_table *)malloc(sizeof(hash_table));
    if (!table) return NULL;

    table->size = size;
    table->buckets = (hash_node **)calloc(size, sizeof(hash_node *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->locks = (pthread_mutex_t *)calloc(size, sizeof(pthread_mutex_t));
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
    return table;
}

void destroy_hash_table(hash_table *table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        hash_node *node = table->buckets[i];
        while (node) {
            hash_node *tmp = node;
            node = node->next;
            free(tmp->key);
            free(tmp);
        }
        pthread_mutex_destroy(&table->locks[i]);
    }

    free(table->buckets);
    free(table->locks);
    free(table);
}

size_t hash_function(const char *str, size_t table_size) {
    size_t hash = 0;
    while (*str) {
        hash = (hash << 5) + hash + *(unsigned char *)str++;
    }
    return hash % table_size;
}

void insert_measurement(hash_table *table, measurement data) {
    size_t index = hash_function(data.label, table->size);
    pthread_mutex_lock(&table->locks[index]);

    hash_node *new_node = (hash_node *)malloc(sizeof(hash_node));
    new_node->key = strdup(data.label);
    new_node->data = data;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->locks[index]);
}

measurement* find_measurement(hash_table *table, const char *label) {
    size_t index = hash_function(label, table->size);
    pthread_mutex_lock(&table->locks[index]);

    hash_node *node = table->buckets[index];
    while (node) {
        if (strcmp(node->key, label) == 0) {
            measurement *result = &node->data;
            pthread_mutex_unlock(&table->locks[index]);
            return result;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL;
}

void compute_average(float *average, int count) {
    if (count == 0) {
        *average = 0.0f;
        return;
    }

    float sum = 0.0f;
    for (int i = 0; i < count; ++i) {
        sum += average[i];
    }
    *average = sum / count;
}

// Utility functions
char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char *random_string = (char *)malloc(length + 1);
    if (!random_string) return NULL;

    for (size_t i = 0; i < length; ++i) {
        random_string[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    random_string[length] = '\0';
    return random_string;
}

char* secure_password_handling(const char *input) {
    size_t len = strlen(input);
    char *secure_str = (char *)malloc(len + 1);
    if (!secure_str) return NULL;

    for (size_t i = 0; i < len; ++i) {
        secure_str[i] = input[i] ^ 0xAA; // Simple XOR encryption
    }
    secure_str[len] = '\0';
    return secure_str;
}

// Main function to handle measurements
void process_measurements() {
    srand(time(NULL));

    memory_pool *pool = create_memory_pool(sizeof(measurement), 100);
    hash_table *table = create_hash_table(101);

    float averages[KEYWORD_COUNT] = {0.0f};
    int counts[KEYWORD_COUNT] = {0};

    while (scanf("%*s %lf %zu", &measurement.data.value, &measurement.data.timestamp) == 2) {
        measurement.data.label = generate_random_string(5);
        insert_measurement(table, measurement);

        for (int i = 0; i < KEYWORD_COUNT; ++i) {
            if (strcmp(measurement.data.label, keywords[i]) == 0) {
                averages[i] += measurement.data.value;
                counts[i]++;
                break;
            }
        }
    }

    for (int i = 0; i < KEYWORD_COUNT; ++i) {
        compute_average(&averages[i], counts[i]);
        printf("Average for %s: %.2f\n", keywords[i], averages[i]);
    }

    destroy_memory_pool(pool);
    destroy_hash_table(table);
}

int main() {
    process_measurements();
    return 0;
}
```']

