// Implement memory pool functions
MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    void* mem = malloc(block_size * num_blocks);
    if (!mem) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->start = mem;
    pool->current = mem;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool == NULL) return NULL;

    pthread_mutex_lock(&pool->lock);
    void* block = pool->current;
    if (block + pool->block_size <= ((char*)pool->start + pool->block_size * 1000)) {
        pool->current = (char*)pool->current + pool->block_size;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool exhausted
    }
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void free_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->start);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}
