// Custom memory slab allocator for efficient memory management
class SlabAllocator {
public:
    void* Allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!freeList_.empty()) {
            auto ptr = freeList_.back();
            freeList_.pop_back();
            return ptr;
        }

        // If no available memory, allocate new slab
        return ::operator new(size);
    }

    void Deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex_);
        freeList_.push_back(ptr);
    }

private:
    std::vector<void*> freeList_;
    std::mutex mutex_;
};

// Custom struct definition
struct MyStruct {
    float floatValue;
    int intValue;
    char* strValue;

    // Atomic initialize for thread safety
    static void Initialize(MyStruct& s, float fRangeLow, float fRangeHigh, int iLimit) {
        std::atomic_thread_fence(std::memory_order_seq_cst);
        s.floatValue = GenerateRandomFloat(fRangeLow, fRangeHigh);
        s.intValue = GenerateRandomInt(0, iLimit);

        size_t strLen = GenerateRandomInt(1, 11); // Length between 1 and 10
