    }

private:
    static float GenerateRandomFloat(double lowerBound, double upperBound) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(lowerBound, upperBound);
        return static_cast<float>(dis(gen));
    }

    static int GenerateRandomInt(int lowerBound, int upperBound) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(lowerBound, upperBound);
        return dis(gen);
    }

    static char RandomAlphanumeric() {
        const char alphanum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, sizeof(alphanum) - 2);
        return alphanum[dis(gen)];
    }
};

class DynamicValueGenerator {
public:
    DynamicValueGenerator(const std::string& rangeInput, int stepSize)
        : minValue_(std::numeric_limits<double>::max()),
          maxValue_(-std::numeric_limits<double>::max()),
          stepSize_(stepSize),
          dynamicRangeChangeEnabled_(false) {

        if (!ParseRange(rangeInput)) {
            throw std::invalid_argument("Invalid range input.");
        }

        ValidateRange();
    }

    double GetRandomDoubleInRange(double lowerBound, double upperBound) const {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(lowerBound, upperBound);
        return dis(gen);
    }

    int GetRandomIntInRange(int lowerBound, int upperBound) const {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(lowerBound, upperBound);
        return dis(gen);
    }

    MyStruct* GetRandomStruct(int count) {
        auto& slab = structItemPool_;
        MyStruct* structs = static_cast<MyStruct*>(slab.Allocate(count * sizeof(MyStruct)));

        for (int i = 0; i < count; ++i) {
            MyStruct::Initialize(structs[i], minValue_, maxValue_, stepSize_);
        }
        return structs;
    }

    std::vector<int> GetRandomList(int count) const {
        if ((maxValue_ - minValue_) % stepSize_ != 0)
            throw std::invalid_argument("Step size must be an integer divisor of the range.");

        std::vector<int> result(count);

        std::thread([=, &result]() mutable {
            for (int i = 0; i < count; ++i) {
                int randomValue = GetRandomIntInRange(minValue_, maxValue_);
                if ((randomValue - minValue_) % stepSize_ != 0)
                    continue;

                result[i] = randomValue;
            }
        }).join();

        return result;
    }

    void UpdateRange(double newMin, double newMax) {
        std::lock_guard<std::mutex> lock(mutex_);
        minValue_ = newMin;
        maxValue_ = newMax;

        ValidateRange();
    }

    std::string ToString(bool verbose = false) const {
        std::ostringstream oss;
        oss << "[" << minValue_ << ", " << maxValue_ << "]";

        if (verbose) {
            oss << "\nMemory Usage and Performance Metrics: ..." // Placeholder
                << "\n..."; // Add detailed statistics here
        }

        return oss.str();
    }

private:
    double minValue_;
    double maxValue_;
    int stepSize_;
    SlabAllocator structItemPool_;
    std::atomic<bool> dynamicRangeChangeEnabled_;

    mutable std::mutex mutex_;

    bool ParseRange(const std::string& rangeInput) {
        size_t dashPos = rangeInput.find('-');
        size_t dotsPos = rangeInput.find("..");

        if (dashPos != std::string::npos || dotsPos != std::string::npos) {
            double lowerBound, upperBound;

            auto delimiter = (dashPos != std::string::npos) ? dashPos : dotsPos;

            try {
                std::string lowerPart = rangeInput.substr(0, delimiter);
                std::string upperPart = rangeInput.substr(delimiter + 1);

                if (!std::stod(lowerPart, nullptr)) return false;
                if (!std::stod(upperPart, nullptr)) return false;

                lowerBound = std::stod(lowerPart);
                upperBound = std::stod(upperPart);

                minValue_ = lowerBound;
                maxValue_ = upperBound;
            } catch (...) {
                return false;
            }
        }

        return true;
    }

    void ValidateRange() {
        if (minValue_ >= maxValue_) {
            throw std::invalid_argument("Invalid range: minValue must be less than maxValue.");
        }

        if ((maxValue_ - minValue_) % stepSize_ != 0) {
            throw std::invalid_argument("Step size is not a divisor of the range.");
        }
    }
};

// Usage example (main function to test class)
int main() {
    try {
        DynamicValueGenerator dvg{"10..20", 2};

        MyStruct* structs = dvg.GetRandomStruct(5);
        std::vector<int> randomList = dvg.GetRandomList(100);

        std::cout << "Range: " << dvg.ToString(true) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << std::endl;
    }

    return 0;
}
