#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_SIZE 10

typedef struct {
    int value;
} record;

typedef struct HashNode {
    int key;
    record *record_ptr;
    struct HashNode *next;
} HashNode;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    HashNode **hash_table;
    size_t capacity;
    pthread_mutex_t lock;  // Lock for thread safety
} DataStructures;

// Function prototypes
DataStructures* initialize_data_structures(size_t initial_capacity);
void free_data_structures(DataStructures *ds);
long hash_function(int key, size_t capacity);
void resize_if_needed(DataStructures *ds);
int generate_random_value();
record* create_record_with_random_value();

DataStructures* initialize_data_structures(size_t initial_capacity) {
    DataStructures *ds = (DataStructures *)malloc(sizeof(DataStructures));
    if (!ds) return NULL;

    ds->capacity = initial_capacity;
    ds->offsets = (long *)calloc(initial_capacity, sizeof(long));
    ds->keys = (int *)calloc(initial_capacity, sizeof(int));
    ds->records = (record **)calloc(initial_capacity, sizeof(record *));
    ds->hash_table = (HashNode **)calloc(initial_capacity, sizeof(HashNode *));

    pthread_mutex_init(&ds->lock, NULL);

    if (!ds->offsets || !ds->keys || !ds->records || !ds->hash_table) {
        free_data_structures(ds);
        return NULL;
    }

    return ds;
}

void free_data_structures(DataStructures *ds) {
    if (ds) {
        for (size_t i = 0; i < ds->capacity; ++i) {
            free(ds->records[i]);
            HashNode *node = ds->hash_table[i];
            while (node) {
                HashNode *temp = node;
                node = node->next;
                free(temp);
            }
        }
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds->hash_table);
        pthread_mutex_destroy(&ds->lock);
        free(ds);
    }
}

long hash_function(int key, size_t capacity) {
    return (long)(key % capacity);
}

void resize_if_needed(DataStructures *ds) {
    // Placeholder logic for resizing
    size_t new_capacity = ds->capacity * 2;
    long *new_offsets = (long *)realloc(ds->offsets, new_capacity * sizeof(long));
    int *new_keys = (int *)realloc(ds->keys, new_capacity * sizeof(int));
    record **new_records = (record **)realloc(ds->records, new_capacity * sizeof(record *));
    HashNode **new_hash_table = (HashNode **)realloc(ds->hash_table, new_capacity * sizeof(HashNode *));

    if (!new_offsets || !new_keys || !new_records || !new_hash_table) {
        fprintf(stderr, "Error resizing arrays\n");
        return;
    }

    ds->capacity = new_capacity;
    for (size_t i = ds->capacity / 2; i < new_capacity; ++i) {
        new_offsets[i] = 0;
        new_keys[i] = 0;
        new_records[i] = NULL;
        new_hash_table[i] = NULL;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->hash_table = new_hash_table;
}

int generate_random_value() {
    // Simple random number generator (replace with better RNG if needed)
    return rand() % 100;
}

record* create_record_with_random_value() {
    record *rec = malloc(sizeof(record));
    if (!rec) return NULL;

    rec->value = generate_random_value();
    return rec;
}

void insert_key_and_record(DataStructures *ds, int key) {
    pthread_mutex_lock(&ds->lock);

    resize_if_needed(ds);

    long idx = hash_function(key, ds->capacity);

    HashNode *node = malloc(sizeof(HashNode));
    if (!node) {
        fprintf(stderr, "Error allocating memory for new hash node\n");
        pthread_mutex_unlock(&ds->lock);
        return;
    }

    record *new_record = create_record_with_random_value();
    if (!new_record) {
        free(node);
        fprintf(stderr, "Error creating new record\n");
        pthread_mutex_unlock(&ds->lock);
        return;
    }

    node->key = key;
    node->record_ptr = new_record;
    node->next = ds->hash_table[idx];
    ds->hash_table[idx] = node;

    // Example of updating arrays (offsets, keys, records)
    // Assume offsets and keys are managed as circular buffers for simplicity
    static size_t offset_index = 0;

    if (offset_index < ds->capacity) {
        ds->keys[offset_index] = key;
        ds->records[offset_index] = new_record;
        offset_index++;
    } else {
        fprintf(stderr, "Error: Offset index out of bounds\n");
    }

    pthread_mutex_unlock(&ds->lock);
}

// Example function to demonstrate concurrent access
void* threaded_insert(void *arg) {
    DataStructures *ds = (DataStructures *)arg;
    for (int i = 0; i < 100; ++i) {
        insert_key_and_record(ds, rand());
    }
    return NULL;
}

// Example main function
int main() {
    DataStructures *ds = initialize_data_structures(INITIAL_SIZE);
    if (!ds) {
        fprintf(stderr, "Error initializing data structures\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[4];

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, threaded_insert, ds)) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_data_structures(ds);

    return EXIT_SUCCESS;
}
