['```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <memory>
#include <fstream>

struct Task {
    int priority;
    std::string description;
    std::chrono::system_clock::time_point dueDate;

    bool operator<(const Task& other) const {
        return priority > other.priority; // Higher priority tasks come first
    }
};

class TaskScheduler {
public:
    TaskScheduler() : stop(false) {}

    void start(size_t numThreads = 4) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] { this->workerThread(); });
        }
    }

    void stopScheduler() {
        stop.store(true);
        cv.notify_all();
        for (auto& worker : workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

    void addTask(const Task& task) {
        std::lock_guard<std::mutex> lock(queueMutex);
        taskQueue.push(task);
        cv.notify_one();
    }

private:
    void workerThread() {
        while (!stop.load()) {
            Task task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !taskQueue.empty() || stop.load(); });

                if (stop.load() && taskQueue.empty()) break;

                task = taskQueue.top();
                taskQueue.pop();
            }

            processTask(task);
        }
    }

    void processTask(const Task& task) {
        // Simulate task processing
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        logTaskExecution(task);
    }

    void logTaskExecution(const Task& task) {
        std::ofstream logFile("task_log.txt", std::ios_base::app);
        if (logFile.is_open()) {
            auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
            logFile << "Executed Task: Priority=" << task.priority
                    << ", Description=" << task.description
                    << ", DueDate=" << std::ctime(&task.dueDate.time_since_epoch().count())
                    << ", TimeExecuted=" << std::ctime(&now)
                    << std::endl;
        }
    }

    std::priority_queue<Task> taskQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::vector<std::thread> workers;
    std::atomic<bool> stop;
};

void generateRandomTask(Task& task) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::uniform_int_distribution<> priorityDist(1, 5);
    static std::uniform_int_distribution<> lengthDist(1, 20);

    task.priority = priorityDist(gen);
    task.description.resize(lengthDist(gen), 'A' + (gen() % 26));

    auto now = std::chrono::system_clock::now();
    task.dueDate = now + std::chrono::hours(priorityDist(gen) * 24); // Random due date
}

int main() {
    TaskScheduler scheduler;
    scheduler.start();

    for (int i = 0; i < 10000; ++i) {
        Task task;
        generateRandomTask(task);
        scheduler.addTask(task);
    }

    std::this_thread::sleep_for(std::chrono::seconds(10));
    scheduler.stopScheduler();

    return 0;
}
