### PHP Function: `updateWeatherDataWithCaching`

```php
<?php

function updateWeatherDataWithCaching($locations) {
    $apiUrl = "https://api.weather.com/v1/forecast";
    $apiKey = "YOUR_API_KEY"; // Replace with actual API key
    $cacheDuration = 3600; // Cache duration in seconds
    $maxRetries = 3;
    $retryDelay = 2; // Seconds

    function fetchFromApi($url) {
        global $maxRetries, $retryDelay;

        for ($attempt = 0; $attempt < $maxRetries; $attempt++) {
            $response = @file_get_contents($url);

            if ($response !== false) {
                return json_decode($response, true);
            }

            sleep($retryDelay); // Retry after delay
        }

        throw new Exception("Failed to fetch data from API.");
    }

    function getCachedData($key) {
        $cacheFile = sys_get_temp_dir() . "/weather_cache_" . md5($key) . ".json";
        if (file_exists($cacheFile) && (time() - filemtime($cacheFile)) < $GLOBALS['cacheDuration']) {
            return json_decode(file_get_contents($cacheFile), true);
        }

        return false;
    }

    function cacheData($key, $data) {
        $cacheFile = sys_get_temp_dir() . "/weather_cache_" . md5($key) . ".json";
        file_put_contents($cacheFile, json_encode($data));
    }

    foreach ($locations as $location) {
        $cacheKey = "weather_{$location}";

        try {
            $cachedData = getCachedData($cacheKey);

            if ($cachedData !== false) {
                echo "Using cached data for $location.\n";
                continue;
            }

            $url = "{$apiUrl}?apiKey={$GLOBALS['apiKey']}&q={$location}";
            $data = fetchFromApi($url);

            cacheData($cacheKey, $data);
            echo "Fetched and cached new data for $location.\n";

        } catch (Exception $e) {
            echo "Error processing location {$location}: {$e->getMessage()}\n";
        }
    }
}
