const fs = require('fs');
const axios = require('axios');
const path = require('path');

function createConfigLoader(configDir, schema) {
    return async function loadConfiguration(source) {
        let configData;

        if (source.startsWith('http')) {
            try {
                const response = await axios.get(source);
                configData = response.data;
            } catch (error) {
                throw new Error("Failed to fetch configuration from external API.");
            }
        } else {
            const filePath = path.join(configDir, source);
            try {
                const data = fs.readFileSync(filePath);
                configData = JSON.parse(data);
            } catch (error) {
                throw new Error("Failed to read configuration file.");
            }
        }

        // Validate the configuration against the schema
        for (const key in schema) {
            if (!configData.hasOwnProperty(key)) {
                throw new Error(`Configuration missing required field: ${key}`);
            }
        }

        return configData;
    };
}

module.exports = createConfigLoader;
