```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
    time_t timestamp;
} Record;

typedef struct {
    char *data;
    size_t length;
    int active; // flag to indicate if metadata is active
} Metadata;

typedef struct {
    long offset;
    int key;
    Record record;
    Metadata metadata;
    pthread_mutex_t lock;
} DataStructure;

DataStructure dataPool[MAX_RECORDS];
int poolSize = 0;
pthread_mutex_t poolMutex;

void initMemoryPool() {
    srand(time(NULL));
    pthread_mutex_init(&poolMutex, NULL);

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_init(&dataPool[i].lock, NULL);
    }
}

void destroyMemoryPool() {
    for (int i = 0; i < poolSize; i++) {
        free(dataPool[i].metadata.data); // Free metadata data
        pthread_mutex_destroy(&dataPool[i].lock);
    }
    pthread_mutex_destroy(&poolMutex);
}

DataStructure* allocateFromPool() {
    if (poolSize >= MAX_RECORDS) return NULL;

    DataStructure *ds = &dataPool[poolSize++];

    pthread_mutex_lock(&ds->lock);

    ds->offset = rand() % 1000000;
    ds->key = rand() % 10000;
    ds->record.value = rand() % 1000;
    ds->record.timestamp = time(NULL);

    char *metadataData = (char *)malloc(256);
    snprintf(metadataData, 256, "Data_%d", ds->key);
    ds->metadata.data = metadataData;
    ds->metadata.length = strlen(metadataData);
    ds->metadata.active = rand() % 2;

    pthread_mutex_unlock(&ds->lock);

    return ds;
}

void processStringWithMemoryPool() {
    initMemoryPool();

    for (int i = 0; i < 10; i++) { // Example: allocate 10 data structures
        DataStructure *ds = allocateFromPool();

        if (ds != NULL) {
            printf("Allocated: Key=%d, Value=%d\n", ds->key, ds->record.value);
        } else {
            printf("Memory pool exhausted.\n");
        }
    }

    destroyMemoryPool();
}

int main() {
    processStringWithMemoryPool();
    return 0;
