['Below is an implementation in C for managing a dynamic list of user profiles with thread-safe access using mutexes to prevent race conditions:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char **hobbies;
    size_t hobby_count;
} Hobbies;

typedef struct {
    char *name;
    int age;
    Hobbies hobbies;
} UserProfile;

typedef struct {
    UserProfile **profiles;
    size_t profile_count;
    size_t capacity;
    pthread_mutex_t lock;
} ProfileList;

ProfileList* create_profile_list(size_t initial_capacity) {
    ProfileList *list = (ProfileList *)malloc(sizeof(ProfileList));
    list->profile_count = 0;
    list->capacity = initial_capacity;
    list->profiles = (UserProfile **)malloc(initial_capacity * sizeof(UserProfile *));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_profile_list(ProfileList *list) {
    for(size_t i = 0; i < list->profile_count; i++) {
        free(list->profiles[i]->name);
        for (size_t j = 0; j < list->profiles[i]->hobbies.hobby_count; j++) {
            free(list->profiles[i]->hobbies.hobbies[j]);
        }
        free(list->profiles[i]->hobbies.hobbies);
        free(list->profiles[i]);
    }
    free(list->profiles);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

static void resize_profile_list(ProfileList *list) {
    list->capacity *= 2;
    UserProfile **new_profiles = (UserProfile **)realloc(list->profiles, list->capacity * sizeof(UserProfile *));
    if (!new_profiles) {
        // Handle memory allocation failure
        fprintf(stderr, "Failed to resize profile list.\n");
        exit(EXIT_FAILURE);
    }
    list->profiles = new_profiles;
}

UserProfile* create_user_profile(const char *name, int age, const char **hobbies_list, size_t hobby_count) {
    UserProfile *profile = (UserProfile *)malloc(sizeof(UserProfile));
    profile->name = strdup(name);
    profile->age = age;

    profile->hobbies.hobby_count = hobby_count;
    profile->hobbies.hobbies = (char **)malloc(hobby_count * sizeof(char *));
    for(size_t i = 0; i < hobby_count; i++) {
        profile->hobbies.hobbies[i] = strdup(hobbies_list[i]);
    }

    return profile;
}

void free_user_profile(UserProfile *profile) {
    free(profile->name);
    for (size_t j = 0; j < profile->hobbies.hobby_count; j++) {
        free(profile->hobbies.hobbies[j]);
    }
    free(profile->hobbies.hobbies);
    free(profile);
}

void add_user_profile(ProfileList *list, const char *name, int age, const char **hobbies_list, size_t hobby_count) {
    pthread_mutex_lock(&list->lock);

    if (list->profile_count == list->capacity) {
        resize_profile_list(list);
    }

    UserProfile *new_profile = create_user_profile(name, age, hobbies_list, hobby_count);
    list->profiles[list->profile_count++] = new_profile;

    pthread_mutex_unlock(&list->lock);
}

UserProfile* get_user_by_name(ProfileList *list, const char *name) {
    for (size_t i = 0; i < list->profile_count; i++) {
        if (strcmp(list->profiles[i]->name, name) == 0) {
            return list->profiles[i];
        }
    }
    return NULL;
}

UserProfile* get_user_by_age(ProfileList *list, int age) {
    for (size_t i = 0; i < list->profile_count; i++) {
        if (list->profiles[i]->age == age) {
            return list->profiles[i];
        }
    }
    return NULL;
}

void update_user_profile(ProfileList *list, const char *name, int new_age, const char **new_hobbies_list, size_t new_hobby_count) {
    pthread_mutex_lock(&list->lock);

    UserProfile *profile = get_user_by_name(list, name);
    if (profile) {
        profile->age = new_age;
        for(size_t i = 0; i < profile->hobbies.hobby_count; i++) {
            free(profile->hobbies.hobbies[i]);
        }
        free(profile->hobbies.hobbies);

        profile->hobbies.hobby_count = new_hobby_count;
        profile->hobbies.hobbies = (char **)malloc(new_hobby_count * sizeof(char *));
        for(size_t j = 0; j < new_hobby_count; j++) {
            profile->hobbies.hobbies[j] = strdup(new_hobbies_list[j]);
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_user_profile(ProfileList *list, const char *name) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->profile_count; i++) {
        if (strcmp(list->profiles[i]->name, name) == 0) {
            free_user_profile(list->profiles[i]);
            memmove(&list->profiles[i], &list->profiles[i + 1], 
                    (list->profile_count - i - 1) * sizeof(UserProfile *));
            list->profile_count--;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

float calculate_average_age(ProfileList *list) {
    int total_age = 0;
    for(size_t i = 0; i < list->profile_count; i++) {
        total_age += list->profiles[i]->age;
    }
    return (list->profile_count > 0) ? (float)total_age / list->profile_count : 0.0f;
}
```

This code defines a `ProfileList` structure to hold user profiles, along with functions to create and destroy the list, add, update, get by name or age, remove profiles, calculate average age, and manage concurrent access using pthread mutexes for thread safety. Memory allocation is managed manually with appropriate cleanup routines to prevent leaks. The list dynamically resizes as needed to accommodate new profiles.']

