#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define the structure for log_event.
typedef struct {
    int timestamp;
    char event_type[32]; // Assuming max length 31 + null terminator
    int priority_level;
    float value;
} log_event;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool management structures and functions (simplified version)
typedef struct {
    void *start;
    size_t size;
    // Additional fields like free list, etc. can be added here
} memory_pool;

memory_pool* create_memory_pool(size_t size) {
    memory_pool* pool = malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->start = malloc(size);
    if (!pool->start) {
        free(pool);
        return NULL;
    }

    pool->size = size;
    return pool;
}

void* allocate_from_pool(memory_pool* pool, size_t size) {
    pthread_mutex_lock(&lock); // Ensure thread-safe access
    void *ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
    }
    pthread_mutex_unlock(&lock);

    return ptr;
}

void free_memory_pool(memory_pool* pool) {
    pthread_mutex_lock(&lock);
    if (pool && pool->start) {
        free(pool->start);
    }
    free(pool);
    pthread_mutex_unlock(&lock);
}

// Function to dynamically allocate and initialize the arrays
memory_pool* initialize_event_structure(size_t offset_size, size_t key_size, size_t event_size, int timestamp_range_start, int timestamp_range_end, float value_min, float value_max) {
    memory_pool *pool = create_memory_pool(1024 * 1024); // Example pool size
    if (!pool) return NULL;

    long *offsets = (long*) allocate_from_pool(pool, offset_size * sizeof(long));
    int *keys = (int*) allocate_from_pool(pool, key_size * sizeof(int));
    log_event *events = (log_event*) allocate_from_pool(pool, event_size * sizeof(log_event));

    if (!offsets || !keys || !events) {
        printf("Initialization failed due to memory allocation error\n");
        free_memory_pool(pool);
        return NULL;
    }

    // Initialize offsets with a linear progression
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = i;
    }

    // Initialize keys with an incrementing pattern starting from 1
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = i + 1;
    }

    // Initialize log_event records
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < event_size; ++i) {
        events[i].timestamp = timestamp_range_start + rand() % (timestamp_range_end - timestamp_range_start + 1);
        snprintf(events[i].event_type, sizeof(events[i].event_type), "Event_%zu", i); // Example event type
        events[i].priority_level = rand() % 10; // Random priority level from 0 to 9
        events[i].value = value_min + ((float)rand() / RAND_MAX) * (value_max - value_min);
    }

    return pool;
}

// Cleanup function to free allocated memory
void cleanup_event_structure(memory_pool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&lock); // Ensure thread-safe access
    free_memory_pool(pool);
    pthread_mutex_unlock(&lock);
}

// Helper function: Reads a list of integers from stdin and finds the median
int find_median() {
    int n, *arr, i, temp;

    printf("Enter number of elements: ");
    scanf("%d", &n);

    arr = (int*) malloc(n * sizeof(int));
    if (!arr) return -1;

    printf("Enter %d integers:\n", n);
    for (i = 0; i < n; ++i) {
        scanf("%d", &arr[i]);
    }

    // Sort the array using simple bubble sort for simplicity
    for (i = 0; i < n-1; ++i) {
        for (int j = 0; j < n-i-1; ++j) {
            if (arr[j] > arr[j+1]) {
                temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }

    int median;
    if (n % 2 != 0)
        median = arr[n/2];
    else
        median = (arr[(n-1)/2] + arr[n/2]) / 2;

    printf("Median is: %d\n", median);

    free(arr);
    return 0;
}

int main() {
    memory_pool *pool = initialize_event_structure(100, 50, 200, 0, 1000, 1.0f, 10.0f);
    if (!pool) {
        printf("Failed to initialize event structure\n");
        return -1;
    }

    find_median();

    cleanup_event_structure(pool);

    return 0;
}
```

