    int result = res_query(hostname, C_IN, T_A, &handle);

    if (result == -1) {
        *status = RESOLUTION_FAILED;
        fprintf(log_file, "DNS resolution failed for hostname: %s\n", hostname);
        free(ip_address);
        fclose(log_file);
        return NULL;
    }

    // Process DNS response
    ns_rr rr;
    int i, nrr;
    if (ns_parserr(&handle, ns_s_an, 0, &rr) != -1 && ns_getrrtype(rr) == T_A) {
        ns_name_ntop(ns_rr_rdata(rr), ip_address, MAX_IP_LENGTH);
        *status = SUCCESS;
        fprintf(log_file, "DNS resolution succeeded: %s -> ", hostname);
        for (i = 0; i < MAX_IP_LENGTH; i++) {
            if (ip_address[i] == '\0') break;
            fprintf(log_file, "%d.", ip_address[i]);
        }
        fprintf(log_file, "\n");
    } else {
        *status = CACHE_MISS;
        fprintf(log_file, "IP address not found in DNS response for hostname: %s\n", hostname);
        free(ip_address);
        fclose(log_file);
        return NULL;
    }

    // Validate against cache
    CacheNode *current = cache_head;
    while (current) {
        if (strcmp(current->hostname, hostname) == 0 && memcmp(current->ip, ip_address, MAX_IP_LENGTH) == 0) {
            *status = SUCCESS;
            break;
        }
        current = current->next;
    }

    // If not in cache, add to cache
    if (*status != SUCCESS) {
        CacheNode *new_node = (CacheNode *)malloc(sizeof(CacheNode));
        if (!new_node) {
            *status = MEMORY_ERROR;
            free(ip_address);
            fclose(log_file);
            return NULL;
        }
        strncpy(new_node->hostname, hostname, MAX_DNS_LENGTH);
        memcpy(new_node->ip, ip_address, MAX_IP_LENGTH);
        new_node->next = cache_head;
        cache_head = new_node;
    }

    // Execute test function
    (*test_func)();

    // Reset logging system (for demonstration)
    fclose(log_file);

    return ip_address;
}

// Mock test function for demonstration purposes
void mockTestFunction(void) {
    printf("Running mock test...\n");
}

int main() {
    enum StatusCode status;
    u_char *ip = dnsResolutionWithTesting("MockModule", mockTestFunction, &status);
    if (ip) {
        printf("IP Address: ");
        for (int i = 0; i < MAX_IP_LENGTH && ip[i] != '\0'; i++) {
            printf("%d.", ip[i]);
        }
        printf("\n");
        free(ip);
    } else {
        printf("DNS resolution failed with status code: %d\n", status);
    }

    // Free cache
    CacheNode *current = cache_head;
    while (current) {
        CacheNode *next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
