// Define struct item
typedef struct {
    char *name;
    float value;
} item;

#define MEMORY_LIMIT 1048576 // 1MB for demonstration purposes

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_key_t thread_local_data_key;

void initialize_thread_local_storage() {
    pthread_key_create(&thread_local_data_key, NULL);
}

void cleanup_thread_local_storage(void *data) {
    free(data);
}

// Serialization functions
size_t serialize_short(short value, uint8_t **buffer) {
    size_t size = sizeof(value);
    *buffer = malloc(size);
    if (*buffer) {
        memcpy(*buffer, &value, size);
    }
    return size;
}

size_t serialize_float(float value, uint8_t **buffer) {
    size_t size = sizeof(value);
    *buffer = malloc(size);
    if (*buffer) {
        memcpy(*buffer, &value, size);
    }
    return size;
}

size_t serialize_item(const item *i, uint8_t **buffer) {
    size_t name_length = strlen(i->name) + 1; // include null terminator
    size_t size = sizeof(float) + sizeof(uint32_t) + name_length;
    *buffer = malloc(size);
    if (*buffer) {
        memcpy(*buffer, &i->value, sizeof(float));
        uint32_t nlen = htonl(name_length); // Network byte order
        memcpy((uint8_t*)*buffer + sizeof(float), &nlen, sizeof(uint32_t));
        memcpy((uint8_t*)*buffer + sizeof(float) + sizeof(uint32_t), i->name, name_length);
    }
    return size;
}

// Function to handle dynamic memory allocation and management
void manage_dynamic_memory(size_t count) {
    // Ensure thread-local storage is initialized
    initialize_thread_local_storage();

    pthread_mutex_lock(&mutex);

    short *short_values = malloc(count * sizeof(short));
    float *float_values = malloc(count * sizeof(float));
    item **items = malloc(count * sizeof(item*));

    if (!short_values || !float_values || !items) {
        // Handle memory allocation failure
        if (short_values) free(short_values);
        if (float_values) free(float_values);
        if (items) free(items);
        pthread_mutex_unlock(&mutex);
        return;
    }

    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < count; ++i) {
        short_values[i] = rand() % 100;
        float_values[i] = ((float)rand() / RAND_MAX) * 100.0f;

        items[i] = malloc(sizeof(item));
        if (!items[i]) {
            // Handle allocation failure
            for (size_t j = 0; j < i; ++j) free(items[j]);
            free(short_values);
            free(float_values);
            free(items);
            pthread_mutex_unlock(&mutex);
            return;
        }
        items[i]->name = malloc(50 * sizeof(char));
        if (!items[i]->name) {
            // Handle allocation failure
            free(items[i]);
            for (size_t j = 0; j < i; ++j) free(items[j]);
            free(short_values);
            free(float_values);
            free(items);
            pthread_mutex_unlock(&mutex);
            return;
        }
        snprintf(items[i]->name, 50, "Item_%zu", i + 1);
        items[i]->value = ((float)rand() / RAND_MAX) * 100.0f;
    }

    // Example of logging memory usage
    printf("Allocated short values: %zu bytes\n", count * sizeof(short));
    printf("Allocated float values: %zu bytes\n", count * sizeof(float));
    for (size_t i = 0; i < count; ++i) {
        printf("Allocated item[%zu]: %zu bytes\n", i, sizeof(item) + strlen(items[i]->name) + 1);
    }

    // Clean up resources
    free(short_values);
    free(float_values);

    for (size_t i = 0; i < count; ++i) {
        free(items[i]->name);
        free(items[i]);
    }
    free(items);

    pthread_mutex_unlock(&mutex);
}

void *thread_func(void *arg) {
    size_t count = *(size_t *)arg;
    manage_dynamic_memory(count);
    return NULL;
}

int main() {
    const int thread_count = 4;
    pthread_t threads[thread_count];
    size_t counts[] = {100, 200, 150, 250};

    for (int i = 0; i < thread_count; ++i) {
        pthread_create(&threads[i], NULL, thread_func, &counts[i]);
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
