#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_THREADS 10
#define LOG_FLUSH_INTERVAL 5

typedef struct {
    long offset;
    int key;
    double precision;
} record;

typedef struct {
    record *records;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    FILE *log_file;
    time_t last_flush_time;
    char log_buffer[1024];
    size_t log_index;
} memory_pool;

memory_pool pool;

void initialize_memory_pool(size_t count) {
    pool.records = (record *)malloc(count * sizeof(record));
    if (!pool.records) exit(EXIT_FAILURE);

    pthread_mutex_init(&pool.lock, NULL);
    pthread_cond_init(&pool.cond, NULL);
    pool.count = count;
    pool.log_file = fopen("operation_log.txt", "a");
    if (!pool.log_file) exit(EXIT_FAILURE);

    time(&pool.last_flush_time);
    pool.log_index = 0;
}

void log_operation(const char *message) {
    pthread_mutex_lock(&pool.lock);

    time_t now;
    time(&now);
    snprintf(pool.log_buffer + pool.log_index, sizeof(pool.log_buffer) - pool.log_index,
             "%s: %s\n", ctime(&now), message);
    pool.log_index += strlen(message) + 1;

    if (difftime(now, pool.last_flush_time) >= LOG_FLUSH_INTERVAL) {
        fwrite(pool.log_buffer, 1, pool.log_index, pool.log_file);
        fflush(pool.log_file);
        pool.log_index = 0;
        time(&pool.last_flush_time);
    }

    pthread_mutex_unlock(&pool.lock);
}

void destroy_memory_pool() {
    if (pool.records) free(pool.records);
    fclose(pool.log_file);
    pthread_mutex_destroy(&pool.lock);
    pthread_cond_destroy(&pool.cond);
}

void generate_random_record(record *rec, long offset_range, int key_range, double precision_range) {
    rec->offset = rand() % offset_range;
    rec->key = rand() % key_range;
    rec->precision = (double)rand() / RAND_MAX * precision_range;
}

void initialize_records(size_t count, long offset_range, int key_range, double precision_range) {
    for (size_t i = 0; i < count; ++i) {
        generate_random_record(&pool.records[i], offset_range, key_range, precision_range);
        log_operation("Record initialized");
    }
}

