    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    pthread_mutex_lock(&pool.lock);
    printf("Largest integer: %d\n", largest);
    log_operation("Largest integer found");
    pthread_mutex_unlock(&pool.lock);

    return NULL;
}

