```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char *str;
} record;

void* manage_data_structures(size_t N, size_t K, size_t M) {
    // Define the total memory block
    size_t offsets_size = N * sizeof(long);
    size_t keys_size = N * sizeof(int);
    size_t records_size = K * (sizeof(record) + M);

    // Allocate a single contiguous memory block for all data structures
    void* block = malloc(offsets_size + keys_size + records_size);
    if (!block) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    long* offsets = (long*)block;
    int* keys = (int*)((char*)offsets + offsets_size);
    record* records = (record*)((char*)keys + keys_size);

    // Initialize the offset and key arrays with unique values
    for (size_t i = 0; i < N; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    const char predefined_str[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t str_len = sizeof(predefined_str) - 1;

    // Initialize each record structure
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < K; ++i) {
        records[i].value = rand() % 1000; // Random value between 0 and 999

        size_t substr_len = M > str_len ? str_len : M;
        records[i].str = ((char*)records + K * (sizeof(record) + M)) + i * M;
        strncpy(records[i].str, predefined_str, substr_len);
        records[i].str[substr_len] = '\0'; // Null-terminate the string
    }

    // Zero-padding unused space in records if K < N
    for (size_t i = K; i < N; ++i) {
        records[i].value = 0;
        memset(records[i].str, 0, M);
    }

    return (void*)records;
}

void cleanup_memory(void* block_ptr, size_t N, size_t K, size_t M) {
    if (!block_ptr) return;

    // No need to individually free; we just free the whole allocated block
    free(block_ptr);

    // For additional safety in case of premature termination or debugging,
    // you can implement more detailed logging here, such as checksum verification.
}

int main() {
    size_t N = 10;
    size_t K = 7;
    size_t M = 5;

    void* records_array = manage_data_structures(N, K, M);
    if (!records_array) return EXIT_FAILURE;

    // Use the data...

    cleanup_memory(records_array - (N * sizeof(int) + N * sizeof(long)),
                   N, K, M);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Allocation**: A single contiguous block of memory is allocated to store `offsets`, `keys`, and `records`. This reduces fragmentation.
- **Initialization**: The offsets and keys are initialized with unique values. Records' integer fields are assigned random values, and each record gets a substring from a predefined string.
- **Padding Strategy**: Unused space in the records array is zero-padded when `K < N` to avoid wasted memory.
- **Cleanup**: A single call to `free()` deallocates all the memory. The cleanup function takes into account pointer arithmetic to handle different starting points if needed.
- **Error Handling**: If memory allocation fails, a descriptive message is printed without exposing sensitive information.

This approach ensures efficient memory management and robust error handling while considering alignment and padding implications for performance.']

