#include <stdio.h>
#include <stdlib.h>

#define MAX_RECORDS 10000000

typedef struct {
    int key;
    int offset;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
} RecordCollection;

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;

    return collection;
}

int resize_collection(RecordCollection *collection, size_t new_capacity) {
    Record *new_records = realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) return -1;

    collection->records = new_records;
    collection->capacity = new_capacity;
    return 0;
}

int insert_record(RecordCollection *collection, int key, int offset, int value) {
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        if (resize_collection(collection, new_capacity) != 0) {
            return -1; // Resize failed
        }
    }

    Record *record = &collection->records[collection->count++];
    record->key = key;
    record->offset = offset;
    record->value = value;

    return 0;
}

Record* find_record(RecordCollection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            return &collection->records[i];
        }
    }
    return NULL;
}

int delete_record(RecordCollection *collection, int key) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            memmove(&collection->records[i], &collection->records[i + 1],
                    (--collection->count - i) * sizeof(Record));
            return 0;
        }
    }
    return -1;
}

void free_collection(RecordCollection *collection) {
    if (collection) {
        free(collection->records);
        free(collection);
    }
}

int main() {
    RecordCollection *collection = create_collection(1024);

    if (!collection) {
        fprintf(stderr, "Failed to create record collection\n");
        return EXIT_FAILURE;
    }

    insert_record(collection, 1, 100, 200);
    insert_record(collection, 2, 101, 201);

    Record *found = find_record(collection, 1);
    if (found) {
        printf("Record found: key=%d, offset=%d, value=%d\n", found->key, found->offset, found->value);
    }

    delete_record(collection, 1);

    free_collection(collection);

    return EXIT_SUCCESS;
}
