['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct SkillSet {
    char** skills;
    size_t count;
} SkillSet;

typedef struct User {
    char* name;
    int age;
    SkillSet skillSet;
} User;

typedef struct MemoryPool {
    void* pool;
    size_t blockSize;
    size_t blockCount;
    pthread_mutex_t lock;
    void** freeList;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t initialBlocks) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->blockSize = blockSize;
    mp->blockCount = initialBlocks;
    mp->pool = malloc(blockSize * initialBlocks);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    pthread_mutex_init(&mp->lock, NULL);

    mp->freeList = (void**)malloc(initialBlocks * sizeof(void*));
    if (!mp->freeList) {
        free(mp->pool);
        free(mp);
        return NULL;
    }

    for (size_t i = 0; i < initialBlocks - 1; ++i) {
        mp->freeList[i] = (char*)mp->pool + i * blockSize;
        *((void**)(mp->freeList[i])) = mp->freeList[i + 1];
    }
    mp->freeList[initialBlocks - 1] = NULL;

    return mp;
}

void* allocateBlock(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    if (!mp->freeList[0]) {
        size_t newBlocks = mp->blockCount * 2;
        void** tempFreeList = (void**)realloc(mp->freeList, newBlocks * sizeof(void*));
        if (!tempFreeList) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }

        for (size_t i = mp->blockCount; i < newBlocks - 1; ++i) {
            tempFreeList[i] = (char*)mp->pool + mp->blockSize * i;
            *((void**)(tempFreeList[i])) = tempFreeList[i + 1];
        }
        tempFreeList[newBlocks - 1] = NULL;

        mp->freeList = tempFreeList;
        mp->blockCount = newBlocks;
    }

    void* block = mp->freeList[0];
    mp->freeList[0] = *((void**)block);

    pthread_mutex_unlock(&mp->lock);
    return block;
}

void deallocateBlock(MemoryPool* mp, void* block) {
    pthread_mutex_lock(&mp->lock);
    *((void**)(block)) = mp->freeList[0];
    mp->freeList[0] = block;
    pthread_mutex_unlock(&mp->lock);
}

void freeMemoryPool(MemoryPool* mp) {
    if (!mp) return;

    free(mp->pool);
    free(mp->freeList);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

User** createUserList(size_t initialCapacity, size_t maxCapacity, MemoryPool* mp, int* processedCount) {
    User** userList = (User**)allocateBlock(mp);
    if (!userList) return NULL;

    *processedCount = 0;
    for (size_t i = 0; i < initialCapacity; ++i) {
        userList[i] = (User*)allocateBlock(mp);
        if (!userList[i]) {
            // Handle allocation failure
            while (*processedCount > 0) {
                deallocateBlock(mp, userList[--(*processedCount)]);
            }
            deallocateBlock(mp, userList);
            return NULL;
        }
    }

    return userList;
}

void addUser(User** userList, int* size, int maxCapacity, MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    if (*size >= maxCapacity) {
        pthread_mutex_unlock(&mp->lock);
        return; // Handle error: capacity exceeded
    }

    User* newUser = (User*)allocateBlock(mp);
    if (!newUser) {
        pthread_mutex_unlock(&mp->lock);
        return;
    }

    userList[*size] = newUser;
    (*size)++;
    pthread_mutex_unlock(&mp->lock);
}

void updateUser(User** userList, int index, const char* name, int age, SkillSet skillSet) {
    if (index < 0 || index >= *processedCount) return; // Handle invalid index

    User* user = userList[index];
    free(user->name);

    size_t nameLen = strlen(name) + 1;
    user->name = (char*)malloc(nameLen);
    if (!user->name) return; // Handle allocation failure
    strcpy(user->name, name);

    user->age = age;

    for (size_t i = 0; i < user->skillSet.count; ++i) {
        free(user->skillSet.skills[i]);
    }
    free(user->skillSet.skills);

    user->skillSet.skills = (char**)malloc(skillSet.count * sizeof(char*));
    if (!user->skillSet.skills) return; // Handle allocation failure

    for (size_t i = 0; i < skillSet.count; ++i) {
        size_t skillLen = strlen(skillSet.skills[i]) + 1;
        user->skillSet.skills[i] = (char*)malloc(skillLen);
        if (!user->skillSet.skills[i]) return; // Handle allocation failure
        strcpy(user->skillSet.skills[i], skillSet.skills[i]);
    }

    user->skillSet.count = skillSet.count;
}

void removeUser(User** userList, int* size, int index, MemoryPool* mp) {
    if (index < 0 || index >= *size) return; // Handle invalid index

    User* userToRemove = userList[index];
    free(userToRemove->name);

    for (size_t i = 0; i < userToRemove->skillSet.count; ++i) {
        free(userToRemove->skillSet.skills[i]);
    }
    free(userToRemove->skillSet.skills);

    deallocateBlock(mp, userToRemove);

    for (int i = index; i < *size - 1; ++i) {
        userList[i] = userList[i + 1];
    }

    (*size)--;
}

void destroyUserList(User** userList, int size, MemoryPool* mp) {
    for (int i = 0; i < size; ++i) {
        User* user = userList[i];
        free(user->name);

        for (size_t j = 0; j < user->skillSet.count; ++j) {
            free(user->skillSet.skills[j]);
        }
        free(user->skillSet.skills);

        deallocateBlock(mp, user);
    }

    deallocateBlock(mp, userList);
}

int main() {
    size_t initialCapacity = 10;
    size_t maxCapacity = 1000;
    int processedCount;

    MemoryPool* mp = createMemoryPool(sizeof(User), initialCapacity);
    if (!mp) return -1;

    User** userList = createUserList(initialCapacity, maxCapacity, mp, &processedCount);
    if (!userList) {
        freeMemoryPool(mp);
        return -1;
    }

    // Example usage
    addUser(userList, &processedCount, maxCapacity, mp);

    SkillSet skillSet = { .skills = (char*[]){"C", "Java"}, .count = 2 };
    updateUser(userList, 0, "Alice", 30, skillSet);

    removeUser(userList, &processedCount, 0, mp);

    destroyUserList(userList, processedCount, mp);
    freeMemoryPool(mp);

    return 0;
}
