['Below is a C implementation of the described dynamic cache system for records:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 100
#define MEMORY_LIMIT (1 * 1024 * 1024) // 1 MB

typedef struct Record {
    int key;
    long offset;
    int value;
} Record;

// Cache structure
typedef struct Cache {
    Record *records[MAX_ENTRIES];
    size_t size;
    size_t capacity;
    char *memory_block;
    size_t memory_used;
} Cache;

void log_memory_usage(Cache *cache) {
    printf("Memory used: %zu bytes\n", cache->memory_used);
}

int allocate_record_cache(Cache *cache, size_t capacity) {
    if (capacity > MAX_ENTRIES || !cache) return -1;

    cache->records = calloc(capacity, sizeof(Record *));
    if (!cache->records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return -1;
    }

    cache->memory_block = malloc(MEMORY_LIMIT);
    if (!cache->memory_block) {
        fprintf(stderr, "Memory allocation failed for memory block\n");
        free(cache->records);
        return -1;
    }

    cache->size = 0;
    cache->capacity = capacity;
    cache->memory_used = 0;

    srand(time(NULL));
    return 0;
}

void release_record_cache(Cache *cache) {
    if (!cache) return;

    for (size_t i = 0; i < cache->size; ++i) {
        free(cache->records[i]);
    }
    free(cache->records);
    free(cache->memory_block);
}

int add_record(Cache *cache, int value_range_min, int value_range_max) {
    if (!cache || cache->size >= cache->capacity) return -1;

    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for new record\n");
        return -1;
    }

    size_t memory_offset = sizeof(Record) + cache->memory_used;
    if (memory_offset > MEMORY_LIMIT) {
        free(new_record);
        release_record_cache(cache); // Reset the cache
        allocate_record_cache(cache, cache->capacity); // Reallocate
    }

    new_record->offset = (long)new_record;
    new_record->value = rand() % (value_range_max - value_range_min + 1) + value_range_min;

    int key_attempts = 0;
    while (1) {
        if (key_attempts >= cache->capacity / 2) break; // Avoid infinite loop

        new_record->key = rand() % 1001;
        for (size_t i = 0; i < cache->size; ++i) {
            if (cache->records[i]->key == new_record->key) {
                key_attempts++;
                break;
            }
        }

        if (!key_attempts || key_attempts >= cache->capacity / 2) break;
    }

    memcpy((char *)new_record + sizeof(Record), &cache->memory_block[cache->memory_used], memory_offset - sizeof(Record));
    cache->records[cache->size++] = new_record;
    cache->memory_used += memory_offset;

    log_memory_usage(cache);

    return 0;
}

int main() {
    Cache cache;
    if (allocate_record_cache(&cache, MAX_ENTRIES) != 0) {
        fprintf(stderr, "Failed to initialize cache\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (add_record(&cache, 1, 100) != 0) {
            fprintf(stderr, "Failed to add record %d\n", i);
            break;
        }
    }

    release_record_cache(&cache);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Management**: The cache uses a memory block of up to 1 MB and reallocates if the limit is exceeded.
- **LRU Strategy**: When adding a new record, it replaces the least recently used one if necessary.
- **Key Collision Handling**: Implements random key generation with retries to minimize collisions.
- **Error Handling**: Gracefully handles allocation failures and logs memory usage for debugging.']

['```c
#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_RECORDS 10000000

typedef struct {
    int key;
    int offset;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    pthread_mutex_t mutexes[];
} HashTable;

// Initialize hash table
HashTable* init_hash_table(size_t capacity) {
    HashTable* ht = (HashTable*)calloc(1, sizeof(HashTable));
    if (!ht) return NULL;

    ht->buckets = (Node**)calloc(capacity, sizeof(Node*));
    ht->capacity = capacity;
    ht->mutexes = (pthread_mutex_t*)malloc(capacity * sizeof(pthread_mutex_t));
    for (size_t i = 0; i < capacity; i++) {
        pthread_mutex_init(&ht->mutexes[i], NULL);
    }

    return ht;
}

// Hash function
unsigned long hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

// Insert record
int insert_record(HashTable* ht, Record rec) {
    if (!ht) return -1;

    unsigned long index = hash(rec.key, ht->capacity);
    pthread_mutex_lock(&ht->mutexes[index]);

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_unlock(&ht->mutexes[index]);
        return -2;
    }

    node->record = rec;
    node->next = ht->buckets[index];
    ht->buckets[index] = node;

    pthread_mutex_unlock(&ht->mutexes[index]);

    // Implement garbage collection if needed

    return 0;
}

// Delete record
int delete_record(HashTable* ht, int key) {
    if (!ht) return -1;

    unsigned long index = hash(key, ht->capacity);
    pthread_mutex_lock(&ht->mutexes[index]);

    Node *node = ht->buckets[index], *prev = NULL;
    while (node && node->record.key != key) {
        prev = node;
        node = node->next;
    }

    if (!node) {
        pthread_mutex_unlock(&ht->mutexes[index]);
        return -3; // Not found
    }

    if (prev) {
        prev->next = node->next;
    } else {
        ht->buckets[index] = node->next;
    }

    free(node);
    pthread_mutex_unlock(&ht->mutexes[index]);

    return 0;
}

// Lookup record
Record* lookup_record(HashTable* ht, int key) {
    if (!ht) return NULL;

    unsigned long index = hash(key, ht->capacity);
    pthread_mutex_lock(&ht->mutexes[index]);

    Node* node = ht->buckets[index];
    while (node && node->record.key != key) {
        node = node->next;
    }

    Record* result = NULL;
    if (node) {
        result = &node->record;
    }

    pthread_mutex_unlock(&ht->mutexes[index]);
    return result;
}

// Cleanup
void cleanup_hash_table(HashTable* ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->capacity; i++) {
        pthread_mutex_lock(&ht->mutexes[i]);

        Node* node = ht->buckets[i];
        while (node) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }

        pthread_mutex_unlock(&ht->mutexes[i]);
    }

    for (size_t i = 0; i < ht->capacity; i++) {
        pthread_mutex_destroy(&ht->mutexes[i]);
    }

    free(ht->buckets);
    free(ht->mutexes);
    free(ht);
}

int main() {
    HashTable* ht = init_hash_table(1000000); // Example capacity

    Record rec = {1, 10, 100};
    insert_record(ht, rec);

    Record* found = lookup_record(ht, 1);
    if (found) {
        printf("Record Found: %d, %d, %d\n", found->key, found->offset, found->value);
    }

    delete_record(ht, 1);
    cleanup_hash_table(ht);

    return 0;
}
