            return FAILURE;
        }

        records[i]->value = rand();
        records[i]->key_ptr = &keys[i];
        records[i]->offset_ptr = &offsets[i];
    }

    *records_out = records;

    pthread_mutex_lock(&mutex);
    printf("Total number of records processed: %zu\n", num_records);
    pthread_mutex_unlock(&mutex);

    return SUCCESS;
}

status_t serialize_data_structure(record **records, size_t num_records,
                                  const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file)
        return FAILURE;

    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&(records[i]->value), sizeof(int), 1, file);
        int key = *(records[i]->key_ptr);
        fwrite(&key, sizeof(int), 1, file);
        long offset = *(records[i]->offset_ptr);
        fwrite(&offset, sizeof(long), 1, file);
    }

    fclose(file);

    return SUCCESS;
}

void free_data_structure(record **records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i])
            free(records[i]);
    }
    free(records);
}
