#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record_t;

typedef struct {
    size_t capacity;
    size_t count;
    int *keys;
    long *offsets;
    record_t *records;
    pthread_mutex_t lock;
    uint32_t seed;
    size_t cache_size;
    record_t **cache;
    size_t cache_hits;
    size_t total_accesses;
} record_manager_t;

record_manager_t* init_record_manager(size_t arraySize, int minValue, int maxValue, uint32_t seed) {
    record_manager_t *manager = malloc(sizeof(record_manager_t));
    if (!manager) return NULL;

    manager->capacity = arraySize;
    manager->count = 0;
    manager->seed = seed;
    srand(seed);

    manager->keys = malloc(arraySize * sizeof(int));
    manager->offsets = malloc(arraySize * sizeof(long));
    manager->records = malloc(arraySize * sizeof(record_t));

    if (!manager->keys || !manager->offsets || !manager->records) {
        free(manager->keys);
        free(manager->offsets);
        free(manager->records);
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->cache_size = arraySize / 10; // Example cache size
    manager->cache = malloc(manager->cache_size * sizeof(record_t*));
    memset(manager->cache, 0, manager->cache_size * sizeof(record_t*));
    manager->cache_hits = 0;
    manager->total_accesses = 0;

    for (size_t i = 0; i < arraySize; ++i) {
        manager->keys[i] = rand() % (maxValue - minValue + 1) + minValue;
        manager->offsets[i] = (long)(rand() * RAND_MAX);
        manager->records[i].key = manager->keys[i];
        manager->records[i].offset = manager->offsets[i];
    }

    return manager;
}

void resize_record_manager(record_manager_t *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);

    int *new_keys = realloc(manager->keys, new_capacity * sizeof(int));
    long *new_offsets = realloc(manager->offsets, new_capacity * sizeof(long));
    record_t *new_records = realloc(manager->records, new_capacity * sizeof(record_t));

    if (!new_keys || !new_offsets || !new_records) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    manager->keys = new_keys;
    manager->offsets = new_offsets;
    manager->records = new_records;

    manager->capacity = new_capacity;

    for (size_t i = manager->count; i < new_capacity; ++i) {
        manager->keys[i] = rand() % 100 + 1;
        manager->offsets[i] = (long)(rand() * RAND_MAX);
        manager->records[i].key = manager->keys[i];
        manager->records[i].offset = manager->offsets[i];
    }

    pthread_mutex_unlock(&manager->lock);
}

record_t* get_record(record_manager_t *manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->cache_size; ++i) {
        if (manager->cache[i] && manager->cache[i]->key == key) {
            manager->cache_hits++;
            pthread_mutex_unlock(&manager->lock);
            return *manager->cache[i];
        }
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) {
            manager->total_accesses++;
            // Update cache with LRU policy
            record_t *record = &manager->records[i];
            for (size_t j = 0; j < manager->cache_size - 1; ++j) {
                if (!manager->cache[j]) {
                    manager->cache[j] = &manager->records[i];
                    break;
                }
                manager->cache[j] = manager->cache[j + 1];
            }
            manager->cache[manager->cache_size - 1] = record;

            pthread_mutex_unlock(&manager->lock);
            return *record;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void free_record_manager(record_manager_t *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);

    free(manager->keys);
    free(manager->offsets);
    free(manager->records);
    free(manager->cache);
    free(manager);
}

int main() {
    size_t arraySize = 1000;
    int minValue = 1, maxValue = 100;
    uint32_t seed = 12345;

    record_manager_t *manager = init_record_manager(arraySize, minValue, maxValue, seed);
    if (!manager) {
        fprintf(stderr, "Failed to initialize record manager\n");
        return EXIT_FAILURE;
    }

    // Example usage
    record_t *record = get_record(manager, 50);
    if (record) {
        printf("Record found: key=%d, offset=%ld\n", record->key, record->offset);
    } else {
        printf("Record not found\n");
    }

    free_record_manager(manager);

    return EXIT_SUCCESS;
}
