#define MAX_SAMPLES 10000000

typedef struct {
    double *data;
    size_t count;
    double min;
    double max;
    double median;
    double stddev;
} SampleSequence;

// Helper function to compute statistics
void computeStatistics(double *samples, size_t count, SampleSequence *sequence, int prioritizeSpeed) {
    if (count == 0) return;

    sequence->min = samples[0];
    sequence->max = samples[0];

    // Calculate min and max
    for (size_t i = 1; i < count; ++i) {
        if (samples[i] < sequence->min) sequence->min = samples[i];
        if (samples[i] > sequence->max) sequence->max = samples[i];
    }

    // Copy data to sort it for median calculation
    double *sortedData = malloc(count * sizeof(double));
    if (!sortedData) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }
    memcpy(sortedData, samples, count * sizeof(double));

    // Custom sorting (simple insertion sort for demonstration; replace with a more optimized one)
    for (size_t i = 1; i < count; ++i) {
        double key = sortedData[i];
        int j = i - 1;
        while (j >= 0 && sortedData[j] > key) {
            sortedData[j + 1] = sortedData[j];
            --j;
        }
        sortedData[j + 1] = key;
    }

    // Calculate median
    if (count % 2 == 0)
        sequence->median = (sortedData[count / 2 - 1] + sortedData[count / 2]) / 2.0;
    else
        sequence->median = sortedData[count / 2];

    free(sortedData);

    // Calculate standard deviation
    double mean = 0.0, sumSqDiff = 0.0;
    for (size_t i = 0; i < count; ++i) {
        mean += samples[i];
    }
    mean /= count;

    for (size_t i = 0; i < count; ++i) {
        double diff = samples[i] - mean;
        sumSqDiff += diff * diff;
    }

    sequence->stddev = sqrt(sumSqDiff / count);
}

// Custom memory pool for efficient allocation
typedef struct MemoryPool {
    size_t block_size;
    void *blocks[MAX_SAMPLES];
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = blockSize;
    for (size_t i = 0; i < MAX_SAMPLES; ++i) {
        pool->blocks[i] = NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocateFromPool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < MAX_SAMPLES; ++i) {
        if (!pool->blocks[i]) {
            void *block = malloc(pool->block_size);
            if (block) pool->blocks[i] = block;
            pthread_mutex_unlock(&pool->lock);
            return block;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;  // Out of memory
}

void deallocateFromPool(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < MAX_SAMPLES; ++i) {
        if (pool->blocks[i] == block) {
            free(pool->blocks[i]);
            pool->blocks[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void destroyMemoryPool(MemoryPool *pool) {
    for (size_t i = 0; i < MAX_SAMPLES; ++i) {
        if (pool->blocks[i]) free(pool->blocks[i]);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// RealTimeDataProcessor function
SampleSequence* RealTimeDataProcessor(double *data, size_t numSamples, 
                                      void **pipelinePtr, int lastProcessedIndex,
                                      int maxBufferedSamples, MemoryPool *pool) {
    if (numSamples > MAX_SAMPLES || numSamples == 0) return NULL;

    SampleSequence *sequence = allocateFromPool(pool);
    if (!sequence) return NULL;

    sequence->data = malloc(numSamples * sizeof(double));
    if (!sequence->data) {
        deallocateFromPool(pool, sequence);
        return NULL;
    }
    memcpy(sequence->data, data, numSamples * sizeof(double));

    sequence->count = numSamples;

    // Compute statistics with a preference for speed
    computeStatistics(sequence->data, numSamples, sequence, 1);

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    // Simulate concurrent access to shared resources
    // Manage pipeline states here if needed

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return sequence;
}

// Flexible data generator with configurable precision and range
void generateData(double *data, size_t count, double minRange, double maxRange, double stepSize) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        double value = minRange + ((double)rand() / RAND_MAX) * (maxRange - minRange);
        data[i] = round(value / stepSize) * stepSize;
    }
}

// Usage example
int main() {
    size_t numSamples = 1000;
    double *data = malloc(numSamples * sizeof(double));
    if (!data) return EXIT_FAILURE;

    generateData(data, numSamples, 0.0, 100.0, 0.1);

    MemoryPool *pool = createMemoryPool(sizeof(SampleSequence));

    SampleSequence *sequence = RealTimeDataProcessor(data, numSamples, NULL, -1, 1000, pool);
    if (sequence) {
        printf("Min: %f\nMax: %f\nMedian: %f\nStddev: %f\n", 
               sequence->min, sequence->max, sequence->median, sequence->stddev);

        free(sequence->data);
        deallocateFromPool(pool, sequence);
    }

    free(data);
    destroyMemoryPool(pool);

    return EXIT_SUCCESS;
}
