typedef struct {
    long offset;
    int key;
    char record[256]; // Adjust size as needed
} Record;

typedef enum { READ_ONLY, READ_WRITE, APPEND_ONLY } AccessMode;

typedef struct {
    Record *records;
    size_t arraySize;
    size_t capacity;
    AccessMode mode;
    pthread_mutex_t lock;
    int (*checksum)(Record *);
    char cache[256][256]; // Simple fixed-size cache
