} Dataset;

Dataset dataset;

// Function prototypes
void initializeDataset(size_t initialCapacity, AccessMode mode);
void resizeDataset();
void populateDataset(int seed, int minValue, int maxValue);
void *threadFunction(void *arg);
int calculateChecksum(Record *record);
void logMetrics();
void serializeData(const char *filename);
void deserializeData(const char *filename);
void freeResources();

// Initialize the dataset
void initializeDataset(size_t initialCapacity, AccessMode mode) {
    pthread_mutex_init(&dataset.lock, NULL);
    dataset.records = (Record *)malloc(initialCapacity * sizeof(Record));
    dataset.arraySize = 0;
    dataset.capacity = initialCapacity;
    dataset.mode = mode;
    dataset.cacheIndex = 0;

    if (!dataset.checksum) {
        dataset.checksum = calculateChecksum; // Default checksum function
    }
}

// Resize the dataset dynamically
void resizeDataset() {
    pthread_mutex_lock(&dataset.lock);
    size_t newCapacity = dataset.capacity * 2;
    Record *newRecords = (Record *)realloc(dataset.records, newCapacity * sizeof(Record));
    if (newRecords) {
        dataset.records = newRecords;
        dataset.capacity = newCapacity;
    }
    pthread_mutex_unlock(&dataset.lock);
}

// Populate the dataset with random values
void populateDataset(int seed, int minValue, int maxValue) {
    srand(seed);
    for (size_t i = 0; i < dataset.arraySize; ++i) {
        dataset.records[i].offset = rand() % 1000000;
        dataset.records[i].key = rand() % (maxValue - minValue + 1) + minValue;
        snprintf(dataset.records[i].record, sizeof(dataset.records[i].record), "Data-%d", i);
    }
}

// Thread function for multi-threaded environment
void *threadFunction(void *arg) {
    // Example operation: read or write based on mode
    pthread_mutex_lock(&dataset.lock);
    if (dataset.mode == READ_WRITE || dataset.mode == APPEND_ONLY) {
        // Perform write operations
        if (dataset.arraySize >= dataset.capacity) {
            resizeDataset();
        }
        Record *record = &dataset.records[dataset.arraySize++];
        record->offset = rand() % 1000000;
        record->key = rand() % 100;
        snprintf(record->record, sizeof(record->record), "New-Data-%zu", dataset.arraySize);
    } else if (dataset.mode == READ_ONLY) {
        // Perform read operations
        for (size_t i = 0; i < dataset.arraySize; ++i) {
            printf("Record %zu: Key=%d, Offset=%ld\n", i, dataset.records[i].key, dataset.records[i].offset);
        }
    }
    pthread_mutex_unlock(&dataset.lock);

    // Simulate logging and monitoring
    logMetrics();

    return NULL;
}

// Calculate checksum for a record
int calculateChecksum(Record *record) {
    int checksum = 0;
    for (size_t i = 0; i < sizeof(record->record); ++i) {
        checksum += ((unsigned char *)record->record)[i];
    }
    return checksum % 256;
}

// Log metrics for monitoring
void logMetrics() {
    // Example logging function
    printf("Logging memory usage and performance metrics...\n");
}

// Serialize dataset to disk
void serializeData(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&dataset.arraySize, sizeof(size_t), 1, file);
        fwrite(dataset.records, sizeof(Record), dataset.arraySize, file);
        fclose(file);
    }
}

// Deserialize dataset from disk
void deserializeData(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file) {
        fread(&dataset.arraySize, sizeof(size_t), 1, file);
        resizeDataset(); // Ensure capacity is enough
        fread(dataset.records, sizeof(Record), dataset.arraySize, file);
        fclose(file);
    }
}

// Free resources
void freeResources() {
    pthread_mutex_destroy(&dataset.lock);
    free(dataset.records);
}

int main() {
    initializeDataset(1024, READ_WRITE);
    populateDataset(42, 1, 100);

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, threadFunction, NULL);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    serializeData("dataset.dat");

    freeResources();
    return 0;
}
