#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000000

typedef struct {
    double *data;
    size_t count;
} SampleSequence;

typedef struct {
    double *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    double min, max, stddev;
    double median;
} Statistics;

// Helper function to compute the median
static void calculate_median(double* array, size_t count, double* median, int priority) {
    // Implement a custom sorting algorithm optimized for this use case.
    // Example: Quickselect or partial sort for finding median
    qsort(array, count, sizeof(double), (int (*)(const void*, const void*))strcmp);
    *median = (count % 2 == 0) ? (array[count / 2 - 1] + array[count / 2]) / 2 : array[count / 2];
}

// Helper function to compute statistics
static void calculate_statistics(double* data, size_t count, Statistics* stats) {
    double sum = 0.0;
    double sq_sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += data[i];
        sq_sum += data[i] * data[i];
    }
    stats->min = data[0];
    stats->max = data[count - 1];
    double mean = sum / count;
    stats->stddev = sqrt(sq_sum / count - mean * mean);
    calculate_median(data, count, &stats->median, 0); // priority for speed
}

// Function to find median and statistics from incoming data samples
SampleSequence* RealTimeDataProcessor(double* data_samples, size_t num_samples,
                                      MemoryPool* mem_pool) {
    if (num_samples == 0 || mem_pool->pool_size < sizeof(SampleSequence)) {
        return NULL;
    }

    pthread_mutex_lock(&mem_pool->lock);

    // Allocate memory for the sample sequence
    SampleSequence* seq = (SampleSequence*)malloc(sizeof(SampleSequence));
    if (!seq) {
        pthread_mutex_unlock(&mem_pool->lock);
        return NULL;
    }

    // Allocate data buffer from the custom memory pool
    seq->data = (double*)malloc(num_samples * sizeof(double));
    if (!seq->data) {
        free(seq);
        pthread_mutex_unlock(&mem_pool->lock);
        return NULL;
    }

    memcpy(seq->data, data_samples, num_samples * sizeof(double));
    seq->count = num_samples;

    Statistics stats;
    calculate_statistics(seq->data, num_samples, &stats);

    // Log performance and resource usage
    printf("Median: %f, Min: %f, Max: %f, Stddev: %f\n", stats.median, stats.min, stats.max, stats.stddev);

    pthread_mutex_unlock(&mem_pool->lock);
    return seq;
}

// Destructor function for SampleSequence
void free_sample_sequence(SampleSequence* seq) {
    if (seq) {
        free(seq->data);
        free(seq);
    }
}

// Initialize memory pool
MemoryPool init_memory_pool(size_t size) {
    MemoryPool mem_pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

    // Allocate a large block of memory
    mem_pool.pool = (double*)malloc(size * sizeof(double));
    if (!mem_pool.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mem_pool.pool_size = size;

    return mem_pool;
}

// Release memory pool resources
void release_memory_pool(MemoryPool* mem_pool) {
    if (mem_pool->pool) {
        free(mem_pool->pool);
        pthread_mutex_destroy(&mem_pool->lock);
    }
}
