```csharp
using System;
using System.Threading;

public class DynamicDataGenerator
{
    private readonly Random _random;
    private readonly double _min, _max;
    private readonly double _stepSize;
    private readonly object _lock = new object();

    public DynamicDataGenerator(double min, double max, double stepSize)
    {
        if (min >= max || stepSize <= 0)
            throw new ArgumentException("Invalid range or step size");

        _random = new Random();
        _min = min;
        _max = max;
        _stepSize = stepSize;
    }

    public float GetRandomFloat()
    {
        lock (_lock)
        {
            double randomValue = _min + (double)_random.NextDouble() * (_max - _min);
            return (float)(Math.Round(randomValue / _stepSize) * _stepSize);
        }
    }

    public int GetRandomInteger()
    {
        lock (_lock)
        {
            return (int)(_min + _random.Next((int)((_max - _min) / _stepSize)));
        }
    }
}
