#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <jansson.h>  // For JSON handling

typedef enum {
    INFO,
    WARNING,
    ERROR
} log_level;

typedef struct {
    time_t timestamp;
    char *log_message;
    log_level level;
} log_entry;

// Define slab structure and related constants
#define SLAB_SIZE 1024
#define INITIAL_POOLS 10

typedef struct Slab {
    size_t entry_size;
    void *memory_pool;
    size_t total_entries;
    size_t used_entries;
    pthread_mutex_t lock; // For thread-safety
} slab;

// Memory pool structure
typedef struct MemoryPool {
    slab *slabs;
    size_t slab_count;
    size_t max_log_entries;
} memory_pool;

// Global memory pool instance
memory_pool g_memory_pool = {NULL, 0, 10000};  // Example max log entries

// Function declarations
void initialize_memory_pool(size_t entry_size, size_t initial_pools);
log_entry* allocate_log_entry();
void deallocate_log_entry(log_entry *entry);
char* generate_unique_log_message(size_t length);
const char* serialize_to_json(const log_entry* entry);
log_entry* deserialize_from_json(const char* json_str);

// Initialize the memory pool
void initialize_memory_pool(size_t entry_size, size_t initial_pools) {
    g_memory_pool.slabs = calloc(initial_pools, sizeof(slab));
    g_memory_pool.slab_count = initial_pools;

    for (size_t i = 0; i < initial_pools; ++i) {
        slab *s = &g_memory_pool.slabs[i];
        s->entry_size = entry_size;
        s->memory_pool = malloc(SLAB_SIZE);
        memset(s->memory_pool, 0, SLAB_SIZE);
        s->total_entries = SLAB_SIZE / entry_size;
        s->used_entries = 0;
        pthread_mutex_init(&s->lock, NULL);
    }
}

// Allocate a new log entry
log_entry* allocate_log_entry() {
    for (size_t i = 0; i < g_memory_pool.slab_count; ++i) {
        slab *s = &g_memory_pool.slabs[i];
        pthread_mutex_lock(&s->lock);

        if (s->used_entries < s->total_entries) {
            void *entry_ptr = ((char*)s->memory_pool) + (s->used_entries * s->entry_size);
            log_entry *entry = (log_entry *)entry_ptr;

            entry->timestamp = time(NULL);
            entry->log_message = generate_unique_log_message(64); // Example length
            entry->level = INFO;  // Default level

            ++s->used_entries;
            pthread_mutex_unlock(&s->lock);

            return entry;
        }

        pthread_mutex_unlock(&s->lock);
    }

    // If no space, handle resizing or allocation failure
    printf("Memory pool needs resizing.\n");
    return NULL;  // Placeholder for resize handling
}

// Generate a unique log message string
char* generate_unique_log_message(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_+=<>?/";
    char *message = malloc(length + 1);

    if (message) {
        for (size_t i = 0; i < length; ++i) {
            message[i] = charset[rand() % (sizeof(charset) - 1)];
        }
        message[length] = '\0';
    }

    return message;
}

// Deallocate a log entry
void deallocate_log_entry(log_entry *entry) {
    if (!entry) return;

    free(entry->log_message);
    // Implement slab-based deallocation logic here
    printf("Deallocated log entry.\n");
}

// Serialize a log entry to JSON format
const char* serialize_to_json(const log_entry* entry) {
    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_integer(entry->timestamp));
    json_object_set_new(root, "log_message", json_string(entry->log_message));
    const char *level_str = (entry->level == INFO) ? "info" : (entry->level == WARNING) ? "warning" : "error";
    json_object_set_new(root, "level", json_string(level_str));

    char *json_dump = json_dumps(root, JSON_ENCODE_ANY);
    json_decref(root);

    return json_dump;
}

// Deserialize a log entry from JSON format
log_entry* deserialize_from_json(const char* json_str) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    if (!root) {
        printf("Error parsing JSON: %s\n", error.text);
        return NULL;
    }

    log_entry *entry = malloc(sizeof(log_entry));
    if (!entry) return NULL;

    const char *msg = json_string_value(json_object_get(root, "log_message"));
    entry->timestamp = (time_t)json_integer_value(json_object_get(root, "timestamp"));
    entry->log_message = strdup(msg);

    const char *level_str = json_string_value(json_object_get(root, "level"));
    if (strcmp(level_str, "info") == 0)
        entry->level = INFO;
    else if (strcmp(level_str, "warning") == 0)
        entry->level = WARNING;
    else
        entry->level = ERROR;

    json_decref(root);

    return entry;
}

// Example usage of the memory pool and log_entry management
int main() {
    initialize_memory_pool(sizeof(log_entry), INITIAL_POOLS);

    // Allocate a log entry
    log_entry *entry = allocate_log_entry();
    if (entry) {
        const char *json_str = serialize_to_json(entry);
        printf("Serialized: %s\n", json_str);

        free((void*)json_str);

        deallocate_log_entry(entry);
    }

    // Clean up memory pool
    for (size_t i = 0; i < g_memory_pool.slab_count; ++i) {
        slab *s = &g_memory_pool.slabs[i];
        pthread_mutex_destroy(&s->lock);
        free(s->memory_pool);
    }

    free(g_memory_pool.slabs);

    return 0;
}
