#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    float x, y;
} point_t;

typedef struct {
    size_t vertex_count;
    point_t *vertices;
} polygon_t;

typedef struct node {
    polygon_t polygon;
    struct node* next;
} node_t;

typedef struct {
    node_t* head;
    pthread_mutex_t lock;
} polygon_list_t;

polygon_list_t list = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Custom allocator functions
void* custom_alloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void *ptr) {
    free(ptr);
}

// Initialize arrays dynamically
void initialize_arrays(double **double_array, size_t double_count, char **char_array, size_t char_count, point_t ***point_array, size_t point_count) {
    *double_array = (double*)custom_alloc(double_count * sizeof(double));
    *char_array = (char*)custom_alloc(char_count);
    *point_array = (point_t**)custom_alloc(point_count * sizeof(point_t*));
    for(size_t i = 0; i < point_count; ++i) {
        (*point_array)[i] = (point_t*)custom_alloc(sizeof(point_t));
    }
}

// Add a polygon
void add_polygon(polygon_list_t *list, size_t vertex_count, point_t *vertices) {
    pthread_mutex_lock(&list->lock);

    node_t* new_node = (node_t*)custom_alloc(sizeof(node_t));
    if (!new_node) exit(EXIT_FAILURE); // Handle memory allocation failure

    new_node->polygon.vertex_count = vertex_count;
    new_node->polygon.vertices = vertices ? custom_alloc(vertex_count * sizeof(point_t)) : NULL;

    for(size_t i = 0; i < vertex_count && vertices; ++i) {
        new_node->polygon.vertices[i] = vertices[i];
    }

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Remove a polygon by index
void remove_polygon(polygon_list_t *list, size_t index) {
    if (index == 0) {
        node_t* temp = list->head;
        if (!temp) return; // Handle null pointer

        list->head = temp->next;
        custom_free(temp);
        return;
    }

    pthread_mutex_lock(&list->lock);

    node_t *current = list->head, *previous = NULL;

    for (size_t i = 0; current && i < index; ++i) {
        previous = current;
        current = current->next;
    }

    if (!current) return; // Handle invalid index

    previous->next = current->next;
    custom_free(current);

    pthread_mutex_unlock(&list->lock);
}

// Resizing a polygon's vertex array
void resize_polygon(polygon_t *polygon, size_t new_vertex_count, point_t **new_vertices) {
    if (!polygon || !new_vertices) return;

    point_t* temp = (point_t*)custom_alloc(new_vertex_count * sizeof(point_t));
    if (!temp) exit(EXIT_FAILURE); // Handle memory allocation failure

    for (size_t i = 0; i < polygon->vertex_count && i < new_vertex_count; ++i) {
        temp[i] = polygon->vertices[i];
    }

    custom_free(polygon->vertices);
    polygon->vertices = temp;
    polygon->vertex_count = new_vertex_count;
}

// Cleanup function to free the entire list
void cleanup_list(polygon_list_t *list) {
    pthread_mutex_lock(&list->lock);

    node_t* current = list->head;
    while (current) {
        node_t* next_node = current->next;
        custom_free(current->polygon.vertices);
        custom_free(current);
        current = next_node;
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    // Initialize dynamic arrays
    double *double_array = NULL, *char_array = NULL, **point_array = NULL;
    initialize_arrays(&double_array, 10, &char_array, 50, &point_array, 5);

    // Add and manage polygons in the list

    point_t vertices1[] = {{0.0f, 1.0f}, {2.0f, 3.0f}};
    add_polygon(&list, 2, vertices1);

    // Clean up dynamically allocated arrays
    for(size_t i = 0; i < 5; ++i) {
        custom_free(point_array[i]);
    }
    custom_free(point_array);
    custom_free(double_array);
    custom_free(char_array);

    // Clean up polygon list before exiting
    cleanup_list(&list);

    return 0;
}
