// Function to calculate values using a quadratic function and random noise
void populate_data(CustomData *data, size_t index) {
    // Example quadratic function: y = ax^2 + bx + c with some noise
    data->s = (short)(index * index + rand() % 10);
    data->i = index * index + 5;
    data->f = (float)index * index + ((float)rand() / RAND_MAX * 10.0f);
}

// Function to manage a dynamic collection of custom data structures
void manage_data_collection(CustomData **collection, size_t *current_size, size_t *max_size) {
    // Initial allocation for 100 elements
    if (!(*collection)) {
        *collection = (CustomData *)malloc(100 * sizeof(CustomData));
        if (!*collection) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        *current_size = 100;
        *max_size = 1000; // Maximum size
    }

    // Populate initial data
    for (size_t i = 0; i < *current_size; ++i) {
        populate_data(&(*collection)[i], i);
    }

    // Simulate periodic update from external data source
    while (1) {
        size_t new_size = *current_size + rand() % 50; // Example: grow by random amount

        if (new_size > *max_size) {
            fprintf(stderr, "Exceeded maximum allowed size\n");
            break;
        }

        if (new_size > *current_size) {
            CustomData *temp = realloc(*collection, new_size * sizeof(CustomData));
            if (!temp) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(*collection);
                exit(EXIT_FAILURE);
            }
            *collection = temp;
            *current_size = new_size;

            // Populate new data
            for (size_t i = *current_size - 50; i < *current_size; ++i) {
                populate_data(&(*collection)[i], i);
            }
        }

        // Simulate delay or wait time for periodic update
        sleep(1); // Sleep for 1 second

        // Example: handle discrepancies in data format or missing data gracefully
        for (size_t i = 0; i < *current_size; ++i) {
            if ((*collection)[i].f < 0.0f) { // Arbitrary condition to simulate error handling
                (*collection)[i].f = 0.0f; // Reset or handle the error
            }
        }

        // Example: stop after a certain number of updates for demonstration purposes
        static int update_count = 0;
        if (++update_count > 10) {
            break;
        }
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    CustomData *data_collection = NULL;
    size_t current_size = 0, max_size = 0;

    manage_data_collection(&data_collection, &current_size, &max_size);

    // Clean up
    free(data_collection);
    return 0;
}
