#include <pthread.h>

// Define geographical features with metadata.
typedef struct {
    char *name;
    char *description;
    time_t timestamp;
} Metadata;

typedef enum { POINT, LINE, POLYGON } FeatureType;

typedef struct GeographicalFeature {
    FeatureType type;
    void *data;  // Dynamic data (coordinates)
    size_t dataSize;
    Metadata metadata;
    pthread_mutex_t lock;
} GeographicalFeature;

// Dataset structure.
typedef struct {
    GeographicalFeature **features;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock;
} GISDataset;

// Initialize a new dataset.
GISDataset* initialize_dataset(size_t initial_capacity) {
    GISDataset *dataset = (GISDataset *)malloc(sizeof(GISDataset));
    if (!dataset) return NULL;

    dataset->features = (GeographicalFeature **)calloc(initial_capacity, sizeof(GeographicalFeature *));
    if (!dataset->features) {
        free(dataset);
        return NULL;
    }

    dataset->count = 0;
    dataset->capacity = initial_capacity;
    pthread_rwlock_init(&dataset->rwlock, NULL);

    return dataset;
}

// Add a feature to the dataset.
int add_feature(GISDataset *dataset, GeographicalFeature *feature) {
    if (!dataset || !feature) return -1;

    pthread_rwlock_wrlock(&dataset->rwlock);

    // Resize array if necessary.
    if (dataset->count == dataset->capacity) {
        size_t new_capacity = dataset->capacity * 2;
        GeographicalFeature **new_features = (GeographicalFeature **)realloc(dataset->features, new_capacity * sizeof(GeographicalFeature *));
        if (!new_features) {
            pthread_rwlock_unlock(&dataset->rwlock);
            return -1; // Out of memory
        }
        dataset->features = new_features;
        dataset->capacity = new_capacity;
    }

    feature->dataSize = 0;
    feature->metadata.name = strdup("Unnamed");
    feature->metadata.description = strdup("No description");
    feature->metadata.timestamp = time(NULL);
    pthread_mutex_init(&feature->lock, NULL);

    // Add the feature to the dataset.
    dataset->features[dataset->count++] = feature;

    pthread_rwlock_unlock(&dataset->rwlock);
    return 0;
}

// Remove a feature by index.
int remove_feature(GISDataset *dataset, size_t index) {
    if (!dataset || index >= dataset->count) return -1;

    pthread_rwlock_wrlock(&dataset->rwlock);

    GeographicalFeature *feature = dataset->features[index];
    if (feature) {
        free(feature->metadata.name);
        free(feature->metadata.description);
        free(feature->data);
        pthread_mutex_destroy(&feature->lock);
        free(feature);
        memmove(dataset->features + index, dataset->features + index + 1,
                (dataset->count - index - 1) * sizeof(GeographicalFeature *));
        --dataset->count;
    }

    pthread_rwlock_unlock(&dataset->rwlock);
    return 0;
}

// Modify a feature's metadata.
int modify_feature_metadata(GISDataset *dataset, size_t index, const char *name, const char *description) {
    if (!dataset || index >= dataset->count) return -1;

    GeographicalFeature *feature = dataset->features[index];
    if (!feature) return -1;

    pthread_mutex_lock(&feature->lock);

    free(feature->metadata.name);
    feature->metadata.name = name ? strdup(name) : NULL;

    free(feature->metadata.description);
    feature->metadata.description = description ? strdup(description) : NULL;

    pthread_mutex_unlock(&feature->lock);
    return 0;
}

// Clean up the dataset.
void cleanup_dataset(GISDataset *dataset) {
    if (!dataset) return;

    for (size_t i = 0; i < dataset->count; ++i) {
        GeographicalFeature *feature = dataset->features[i];
        free(feature->metadata.name);
        free(feature->metadata.description);
        free(feature->data);
        pthread_mutex_destroy(&feature->lock);
        free(feature);
    }

    free(dataset->features);
    pthread_rwlock_destroy(&dataset->rwlock);
    free(dataset);
}

int main() {
    // Example usage of the GIS dataset management functions.
    GISDataset *dataset = initialize_dataset(10);

    if (!dataset) {
        fprintf(stderr, "Failed to initialize the dataset.\n");
        return EXIT_FAILURE;
    }

    // Create and add a point feature
    GeographicalFeature *point = (GeographicalFeature *)malloc(sizeof(GeographicalFeature));
    point->type = POINT;
    point->data = malloc(2 * sizeof(double));  // Example for storing coordinates.
    *(double *)(point->data) = 10.0;           // x-coordinate
    *((double *)(point->data) + 1) = 20.0;     // y-coordinate
    add_feature(dataset, point);

    // Modify feature metadata
    modify_feature_metadata(dataset, 0, "Point A", "A sample point feature");

    // Cleanup
    remove_feature(dataset, 0);
    cleanup_dataset(dataset);

    return EXIT_SUCCESS;
}
```

This implementation provides a robust framework for managing a GIS dataset with thread-safe operations. The `GeographicalFeature` structure supports metadata and dynamic data storage, while the dataset itself uses a resizable array and read-write locks to handle concurrent access efficiently.']

