#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEM_LIMIT 1024 * 1024 // Example maximum limit in bytes

typedef struct {
    char *char_array;
    int additional_field;
} record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int random_int_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_record(record *rec, size_t key_value) {
    rec->additional_field = random_int_in_range(10, 100); // Example range
    for (size_t i = 0; i < key_value; ++i) {
        rec->char_array[i] = 'A' + rand() % 26; // Random printable ASCII characters A-Z
    }
}

void manage_memory_allocation(long *offsets, size_t num_offsets,
                              int *keys, size_t num_keys,
                              record **records, size_t *num_records,
                              size_t max_mem_limit) {

    if (max_mem_limit <= sizeof(long) || max_mem_limit <= sizeof(int)) {
        log_error("Insufficient memory limit for structure allocation");
        return;
    }

    srand(time(NULL)); // Seed random number generator

    offsets = malloc(num_offsets * sizeof(long));
    keys = malloc(num_keys * sizeof(int));
    records = malloc(num_keys * sizeof(record *));

    if (!offsets || !keys || !records) {
        log_error("Failed to allocate memory for arrays");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    size_t used_memory = num_offsets * sizeof(long) + num_keys * (sizeof(int) + sizeof(record *));

    if (used_memory >= max_mem_limit) {
        log_error("Memory limit exceeded before allocating records");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    *num_records = 0;

    for (size_t i = 0; i < num_keys && used_memory < max_mem_limit; ++i) {
        keys[i] = random_int_in_range(1, 100); // Example key range
        size_t char_array_size = keys[i];

        if (used_memory + sizeof(record) + char_array_size > max_mem_limit) {
            log_error("Memory limit exceeded before allocating record");
            break;
        }

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            log_error("Failed to allocate memory for a record");
            continue; // Proceed with freeing already allocated resources
        }

        used_memory += sizeof(record);
        records[i]->char_array = malloc(char_array_size);

        if (!records[i]->char_array) {
            free(records[i]);
            log_error("Failed to allocate char array within the record");
            break;
        }

        used_memory += char_array_size;

        initialize_record(records[i], keys[i]);

        (*num_records)++;
    }

    // Free all allocated memory at function exit
    for (size_t i = 0; i < *num_records; ++i) {
        free(records[i]->char_array);
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    size_t num_offsets = 10;
    size_t num_keys = 5;
    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;
    size_t num_records = 0;

    manage_memory_allocation(offsets, num_offsets, keys, num_keys,
                             records, &num_records, MAX_MEM_LIMIT);

    return 0;
}
