['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <unistd.h>

// Define the record structure and other necessary structures
typedef struct {
    int intField;
} record;

typedef struct {
    char identifier[16];
    double latitude;
    double longitude;
    double temperature;
    double humidity;
    time_t timestamp;
    char statusMessage[256];
} Sensor;

typedef struct {
    char deviceId[32];
    time_t timestamp;
    char statusMessage[256];
    Sensor *sensor;
} Device;

typedef struct {
    Sensor *sensors;
    Device *devices;
    size_t sensorCount;
    size_t deviceCount;
} MonitoringStation;

// Custom memory pool management
#define MAX_MEMORY_ALLOC_PER_SECOND 50000
#define MAX_DEVICES_SUPPORTED 10000

typedef struct MemoryPoolNode {
    void *memoryBlock;
    size_t blockSize;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

MemoryPoolNode *memoryPoolHead = NULL;
pthread_mutex_t memoryPoolMutex = PTHREAD_MUTEX_INITIALIZER;

void allocateMemoryPool(size_t poolSize) {
    pthread_mutex_lock(&memoryPoolMutex);
    size_t totalAllocated = 0;
    while (totalAllocated < poolSize) {
        MemoryPoolNode *node = malloc(sizeof(MemoryPoolNode));
        if (!node) break;

        node->blockSize = MAX_MEMORY_ALLOC_PER_SECOND - (totalAllocated % MAX_MEMORY_ALLOC_PER_SECOND);
        node->memoryBlock = malloc(node->blockSize);
        node->next = memoryPoolHead;
        memoryPoolHead = node;

        totalAllocated += node->blockSize;
    }
    pthread_mutex_unlock(&memoryPoolMutex);
}

void *customAllocate(size_t size) {
    pthread_mutex_lock(&memoryPoolMutex);

    for (MemoryPoolNode *current = memoryPoolHead; current != NULL; current = current->next) {
        if ((current->blockSize - size) >= sizeof(MemoryPoolNode)) {
            void *allocatedBlock = current->memoryBlock;
            current->memoryBlock = (char *)current->memoryBlock + size;
            current->blockSize -= size;

            pthread_mutex_unlock(&memoryPoolMutex);
            return allocatedBlock;
        }
    }

    pthread_mutex_unlock(&memoryPoolMutex);
    return NULL; // Out of memory
}

void deallocateMemoryPool() {
    pthread_mutex_lock(&memoryPoolMutex);

    while (memoryPoolHead) {
        MemoryPoolNode *node = memoryPoolHead;
        memoryPoolHead = node->next;

        free(node->memoryBlock);
        free(node);
    }

