MetricSummary* NetworkPacketHandler(const unsigned char* packet_data, int packet_size,
                                    NetworkTrafficParser* parser, int last_parsed_index,
                                    int max_buffer_size) {
    if (!packet_data || !parser || packet_size <= 0 || last_parsed_index < 0 ||
        max_buffer_size <= 0) return NULL;

    pthread_mutex_lock(&parser->lock);

    MetricSummary* new_summary = (MetricSummary*)allocate_memory(sizeof(MetricSummary));
    if (!new_summary) {
        pthread_mutex_unlock(&parser->lock);
        return NULL;
    }

    int packets_to_process = packet_size / sizeof(unsigned char); // Assuming each byte is a packet for simplicity
    parser->packet_count += packets_to_process;

    // Simulated processing logic
