    for (int i = last_parsed_index; i < last_parsed_index + packets_to_process && i < max_buffer_size; ++i) {
        int packet_len = packet_data[i] % 256; // Example: derive packet length from data
        total_packet_size += packet_len;

        if (packet_len == 0) { // Simulate packet loss
            parser->lost_packets++;
        }
    }

    parser->total_packet_size += total_packet_size;
    double avg_latency = 5.0; // Placeholder for latency calculation
