    new_summary->total_packets = parser->packet_count;
    new_summary->avg_packet_size = (parser->total_packet_size / parser->packet_count);
    new_summary->packet_loss_count = parser->lost_packets;
    new_summary->latency_ms = (parser->total_latency / parser->packet_count);

    pthread_mutex_unlock(&parser->lock);

    return new_summary;
}

