#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BOOKS 1000

typedef struct {
    char title[256];
    char author[256];
    int publication_year;
    int is_available; // 1 for available, 0 for checked out
} Book;

typedef struct Node {
    Book book;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} LibraryCatalog;

// Custom memory pool
#define POOL_SIZE 1024 * 128 // 128KB
char memory_pool[POOL_SIZE];
size_t pool_offset = 0;
pthread_mutex_t pool_lock;

void* custom_alloc(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (pool_offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[pool_offset];
    pool_offset += size;
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void custom_free(void) {
    // Reset the pool for simplicity in this example
    pthread_mutex_lock(&pool_lock);
    pool_offset = 0;
    pthread_mutex_unlock(&pool_lock);
}

LibraryCatalog* create_catalog() {
    LibraryCatalog* catalog = (LibraryCatalog*)custom_alloc(sizeof(LibraryCatalog));
    catalog->head = NULL;
    pthread_mutex_init(&catalog->lock, NULL);
    catalog->count = 0;
    return catalog;
}

void destroy_catalog(LibraryCatalog* catalog) {
    Node* current = catalog->head;
    while (current != NULL) {
        Node* next = current->next;
        custom_alloc(-sizeof(Node)); // Free node
        current = next;
    }
    pthread_mutex_destroy(&catalog->lock);
    custom_free();
}

void add_book(LibraryCatalog* catalog, const Book* book) {
    Node* new_node = (Node*)custom_alloc(sizeof(Node));
    if (!new_node) return;

    memcpy(&(new_node->book), book, sizeof(Book));
    new_node->next = NULL;

    pthread_mutex_lock(&catalog->lock);
    new_node->next = catalog->head;
    catalog->head = new_node;
    catalog->count++;
    pthread_mutex_unlock(&catalog->lock);
}

void remove_book(LibraryCatalog* catalog, const char* title) {
    pthread_mutex_lock(&catalog->lock);

    Node *current = catalog->head, *prev = NULL;
    while (current != NULL && strcmp(current->book.title, title) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&catalog->lock);
        return; // Book not found
    }

    if (prev == NULL) { // Removing the head
        catalog->head = current->next;
    } else {
        prev->next = current->next;
    }

    custom_alloc(-sizeof(Node)); // Free node
    catalog->count--;

    pthread_mutex_unlock(&catalog->lock);
}

Book* search_book(LibraryCatalog* catalog, const char* title) {
    pthread_mutex_lock(&catalog->lock);

    Node* current = catalog->head;
    while (current != NULL) {
        if (strcmp(current->book.title, title) == 0) {
            pthread_mutex_unlock(&catalog->lock);
            return &(current->book);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&catalog->lock);
    return NULL; // Book not found
}

int main() {
    LibraryCatalog* catalog = create_catalog();

    Book book1 = {"The C Programming Language", "Kernighan and Ritchie", 1978, 1};
    add_book(catalog, &book1);

    Book* search_result = search_book(catalog, "The C Programming Language");
    if (search_result) {
        printf("Book found: %s by %s\n", search_result->title, search_result->author);
    }

    remove_book(catalog, "The C Programming Language");
    destroy_catalog(catalog);

    return 0;
}
```

This implementation provides a basic structure for managing a distributed library catalog system with concurrent access. It uses a linked list to store books and pthread mutexes for synchronization. A custom memory pool is implemented to optimize resource utilization. The code includes functions to add, remove, and search for books in the catalog.']

