// Align structure to 64 bytes (cache line size for most modern CPUs)
typedef struct {
    int value;
} __attribute__((aligned(64))) Record;

#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB pool
#define GROWTH_FACTOR 2

static uint8_t memory_pool[MEMORY_POOL_SIZE];
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t used_memory = 0;

void* allocate(size_t size) {
    pthread_mutex_lock(&lock);
    if (used_memory + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&lock);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[used_memory];
    used_memory += size;
    pthread_mutex_unlock(&lock);
    return ptr;
}

void deallocate(void* ptr, size_t size) {
    pthread_mutex_lock(&lock);
    used_memory -= size;
    pthread_mutex_unlock(&lock);
}

// Random number generation
int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_records(Record* records, size_t count, int min_val, int max_val) {
    for (size_t i = 0; i < count; ++i) {
        records[i].value = random_int(min_val, max_val);
    }
}

int find_largest_integer(const int* array, size_t size) {
    if (size == 0)
        return INT_MIN;

    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void dynamic_resize(int** array, size_t* current_size, size_t new_size) {
    *array = realloc(*array, new_size * sizeof(int));
    for (size_t i = *current_size; i < new_size; ++i) {
        (*array)[i] = 0; // Initialize new slots
    }
    *current_size = new_size;
}

void log_memory_usage() {
    pthread_mutex_lock(&lock);
    printf("Memory Usage: %zu bytes\n", used_memory);
    pthread_mutex_unlock(&lock);
}

