#define MAX_THREADS 10

// Custom memory pool structure
typedef struct MemoryPool {
    size_t block_size;
    void *memory;
    size_t available_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->available_blocks = num_blocks;
    pool->memory = malloc(block_size * num_blocks);
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->available_blocks > 0) {
        void *block = pool->memory + (--pool->available_blocks) * pool->block_size;
        pthread_mutex_unlock(&pool->lock);
        return block;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // Out of memory
}

void free_memory_pool(MemoryPool *pool) {
    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Thread-safe record structure with mutex
