    int value;
    pthread_mutex_t lock;
} ThreadSafeRecord;

ThreadSafeRecord* create_thread_safe_record(int range_min, int range_max) {
    ThreadSafeRecord *rec = malloc(sizeof(ThreadSafeRecord));
    rec->value = rand() % (range_max - range_min + 1) + range_min;
    pthread_mutex_init(&rec->lock, NULL);
    return rec;
}

void free_thread_safe_record(ThreadSafeRecord *record) {
    pthread_mutex_destroy(&record->lock);
    free(record);
}

// Helper function to find the largest integer in an array
