```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t count;
    pthread_mutex_t lock;
} pipeline;

void init_random() {
    srand(time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

pipeline* create_pipeline(size_t count) {
    pipeline *p = malloc(sizeof(pipeline));
    if (!p) return NULL;

    p->offsets = calloc(count, sizeof(long));
    p->keys = calloc(count, sizeof(int));
    p->records = calloc(count, sizeof(record*));

    for (size_t i = 0; i < count; ++i) {
        p->records[i] = malloc(sizeof(record));
        if (!p->records[i]) {
            // Handle allocation failure
            destroy_pipeline(p);
            return NULL;
        }
        p->records[i]->value = random_int(1, 100); // Example range [1, 100]
    }

    pthread_mutex_init(&p->lock, NULL);
    p->count = count;

    return p;
}

void destroy_pipeline(pipeline *p) {
    if (!p) return;

    for (size_t i = 0; i < p->count; ++i)
        free(p->records[i]);

    free(p->records);
    free(p->keys);
    free(p->offsets);
    pthread_mutex_destroy(&p->lock);
    free(p);
}

void* thread_safe_access(void *arg) {
    pipeline *p = (pipeline*) arg;

    pthread_mutex_lock(&p->lock);
    // Perform operations on p->records
    for (size_t i = 0; i < p->count; ++i)
        printf("Record %zu value: %d\n", i, p->records[i]->value);
    pthread_mutex_unlock(&p->lock);

    return NULL;
}

int main() {
    init_random();
    pipeline *p = create_pipeline(10);

    if (!p) {
        fprintf(stderr, "Failed to create pipeline.\n");
        return EXIT_FAILURE;
    }

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i)
        pthread_create(&threads[i], NULL, thread_safe_access, p);

    for (int i = 0; i < 5; ++i)
        pthread_join(threads[i], NULL);

    destroy_pipeline(p);
    return EXIT_SUCCESS;
}
