['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ALLOCATIONS 50000

typedef struct {
    int value;
} Record;

typedef struct MemoryPool {
    void *memory;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

void initialize_memory_pool(size_t block_size, size_t total_blocks) {
    pool.memory = malloc(block_size * total_blocks);
    if (!pool.memory) {
        fprintf(stderr, "Failed to allocate memory for the pool\n");
        exit(EXIT_FAILURE);
    }

    pool.block_size = block_size;
    pool.total_blocks = total_blocks;
    pool.used_blocks = 0;

    pthread_mutex_init(&pool.lock, NULL);

    printf("Memory Pool Initialized: %zu bytes per block, %zu blocks total.\n", block_size, total_blocks);
}

void* allocate_from_pool(size_t size) {
    if (size > pool.block_size || pool.used_blocks >= pool.total_blocks) {
        fprintf(stderr, "Allocation failed: Requested size too large or out of memory\n");
        return NULL;
    }

    pthread_mutex_lock(&pool.lock);

    void *allocated_memory = (char*)pool.memory + pool.used_blocks * pool.block_size;

    pool.used_blocks++;

    pthread_mutex_unlock(&pool.lock);
    printf("Allocated %zu bytes, total used blocks: %zu\n", size, pool.used_blocks);

    return allocated_memory;
}

void free_memory_pool() {
    free(pool.memory);
    pthread_mutex_destroy(&pool.lock);
    printf("Memory Pool Freed.\n");
}

void reset_memory_pool() {
    pthread_mutex_lock(&pool.lock);
    pool.used_blocks = 0;
    pthread_mutex_unlock(&pool.lock);

    printf("Memory Pool Reset: Used blocks now %zu\n", pool.used_blocks);
}

Record* allocate_records(int count) {
    size_t block_size = sizeof(Record);
    Record *records = (Record *)allocate_from_pool(block_size * count);

    if (!records) return NULL;

    for (int i = 0; i < count; ++i) {
        records[i].value = i;
    }

    printf("Allocated %d Records\n", count);

    return records;
}

long* allocate_offsets(int count) {
    size_t block_size = sizeof(long);
    long *offsets = (long *)allocate_from_pool(block_size * count);

    if (!offsets) return NULL;

    for (int i = 0; i < count; ++i) {
        offsets[i] = (long)i;
    }

    printf("Allocated %d Offsets\n", count);

    return offsets;
}

int* allocate_keys(int count) {
    size_t block_size = sizeof(int);
    int *keys = (int *)allocate_from_pool(block_size * count);

    if (!keys) return NULL;

    for (int i = 0; i < count; ++i) {
        keys[i] = i;
    }

    printf("Allocated %d Keys\n", count);

    return keys;
}

void log_memory_usage() {
    pthread_mutex_lock(&pool.lock);

    size_t used_memory = pool.used_blocks * pool.block_size;
    double usage_percentage = (double)used_memory / (pool.total_blocks * pool.block_size) * 100.0;

    printf("Memory Usage: %zu bytes used, %.2f%% of total capacity.\n", used_memory, usage_percentage);

    pthread_mutex_unlock(&pool.lock);
}

int main() {
    initialize_memory_pool(64, MAX_ALLOCATIONS);

    int count = 10; // Example size
    Record *records = allocate_records(count);
    long *offsets = allocate_offsets(count);
    int *keys = allocate_keys(count);

    log_memory_usage();

    reset_memory_pool();
    log_memory_usage();

    free_memory_pool();

    return 0;
}
```

