typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t *records;
} pipeline_t;

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
void* memory_pool[RECORD_COUNT];
int memory_free_list[RECORD_COUNT];

void initialize_memory_pool() {
    for (int i = 0; i < RECORD_COUNT; ++i) {
        memory_free_list[i] = 1; // mark as free
        memory_pool[i] = malloc(sizeof(record_t));
        if (!memory_pool[i]) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
    }
}

record_t* allocate_record() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < RECORD_COUNT; ++i) {
        if (memory_free_list[i]) {
            memory_free_list[i] = 0;
            record_t *allocated = memory_pool[i];
            pthread_mutex_unlock(&pool_mutex);
            return allocated;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return NULL; // out of memory
}

void deallocate_record(record_t *record) {
    for (int i = 0; i < RECORD_COUNT; ++i) {
        if (memory_pool[i] == record) {
            pthread_mutex_lock(&pool_mutex);
            memory_free_list[i] = 1;
            pthread_mutex_unlock(&pool_mutex);
            return;
        }
    }
}

