#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    int value;
    _Atomic unsigned int access_count;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    pthread_mutex_t lock; // Use finer-grained locks or atomic operations for better concurrency
} HashTable;

HashTable* create_hash_table(size_t capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(capacity, sizeof(Node*));
    table->capacity = capacity;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned long hash(int value) {
    return (value ^ 61) ^ (value >> 16);
}

void insert_record(HashTable* table, Record record) {
    unsigned long index = hash(record.value) % table->capacity;
    pthread_mutex_lock(&table->lock);

    Node** bucket = &table->buckets[index];
    while (*bucket != NULL) {
        if ((*bucket)->record.value == record.value) {
            _atomic_fetch_add(&( (*bucket)->record.access_count ), 1);
            pthread_mutex_unlock(&table->lock);
            return;
        }
        bucket = &(*bucket)->next;
    }

    Node* new_node = malloc(sizeof(Node));
    new_node->record = record;
    new_node->next = NULL;

    *bucket = new_node;

    pthread_mutex_unlock(&table->lock);
}

Record* find_max_record(HashTable* table) {
    Record max_record = { .value = INT_MIN, .access_count = 0 };
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            if (node->record.value > max_record.value) {
                max_record = node->record;
            }
            node = node->next;
        }
    }

    pthread_mutex_unlock(&table->lock);

    return &max_record;
}

void delete_record(HashTable* table, int value) {
    unsigned long index = hash(value) % table->capacity;
    pthread_mutex_lock(&table->lock);

    Node** bucket = &table->buckets[index];
    while (*bucket != NULL) {
        if ((*bucket)->record.value == value) {
            Node* to_delete = *bucket;
            *bucket = (*bucket)->next;
            free(to_delete);
            break;
        }
        bucket = &(*bucket)->next;
    }

    pthread_mutex_unlock(&table->lock);
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node != NULL) {
            Node* to_delete = node;
            node = node->next;
            free(to_delete);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void manage_records() {
    HashTable* table = create_hash_table(1024); // Start with a small capacity, resize as needed

    int value;
    while (scanf("%d", &value) == 1) {
        Record record = { .value = value, .access_count = 0 };
        insert_record(table, record);
    }

    Record* max_record = find_max_record(table);
    printf("Maximum Value: %d\n", max_record->value);

    destroy_hash_table(table);
}

int main() {
    manage_records();
    return 0;
}
