typedef enum {
    INFO,
    WARNING,
    ERROR
} log_level;

typedef struct log_entry {
    time_t timestamp;
    char *log_message;
    log_level severity;
} log_entry;

typedef struct memory_pool {
    log_entry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} memory_pool;

#define INITIAL_CAPACITY 10

memory_pool* create_memory_pool() {
    memory_pool *pool = (memory_pool *)malloc(sizeof(memory_pool));
    pool->capacity = INITIAL_CAPACITY;
    pool->count = 0;
    pool->entries = (log_entry **)calloc(pool->capacity, sizeof(log_entry *));
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void resize_memory_pool(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    size_t new_capacity = pool->capacity * 2;
    log_entry **new_entries = (log_entry **)realloc(pool->entries, new_capacity * sizeof(log_entry *));
    if (new_entries) {
        memset(new_entries + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(log_entry *));
        pool->entries = new_entries;
        pool->capacity = new_capacity;
    }
    pthread_mutex_unlock(&pool->lock);
}

log_entry* allocate_log_entry(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        resize_memory_pool(pool);
    }

    log_entry *entry = (log_entry *)malloc(sizeof(log_entry));
    entry->timestamp = time(NULL);
    entry->log_message = strdup("UniqueLogMessage"); // Replace with actual unique generation
    entry->severity = INFO; // Example severity

    pool->entries[pool->count++] = entry;
    pthread_mutex_unlock(&pool->lock);

    return entry;
}

void deallocate_log_entry(memory_pool *pool, log_entry *entry) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->entries[i] == entry) {
            free(pool->entries[i]->log_message);
            free(pool->entries[i]);
            memmove(&pool->entries[i], &pool->entries[i + 1], (pool->count - i - 1) * sizeof(log_entry *));
            pool->count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

char* serialize_log_entry(const log_entry *entry) {
    json_object *jobj = json_object_new_object();
    json_object_object_add(jobj, "timestamp", json_object_new_int64(entry->timestamp));
    json_object_object_add(jobj, "log_message", json_object_new_string(entry->log_message));
    const char *severity_str[] = {"INFO", "WARNING", "ERROR"};
    json_object_object_add(jobj, "severity", json_object_new_string(severity_str[entry->severity]));

    const char *json_str = json_object_to_json_string_ext(jobj, JSON_C_TO_STRING_PLAIN);
    char *result = strdup(json_str);

    json_object_put(jobj);
    return result;
}

log_entry* deserialize_log_entry(const char *json_str) {
    struct json_object *jobj = json_tokener_parse(json_str);
    log_entry *entry = (log_entry *)malloc(sizeof(log_entry));

    json_object_object_get_ex(jobj, "timestamp", &j_timestamp);
    entry->timestamp = json_object_get_int64(j_timestamp);

    json_object_object_get_ex(jobj, "log_message", &j_message);
    entry->log_message = strdup(json_object_get_string(j_message));

    const char *severity_str[] = {"INFO", "WARNING", "ERROR"};
    int severity_index;
    json_object_object_get_ex(jobj, "severity", &j_severity);
    for (severity_index = 0; severity_index < 3; ++severity_index) {
        if (strcmp(json_object_get_string(j_severity), severity_str[severity_index]) == 0) {
            entry->severity = (log_level)severity_index;
            break;
        }
    }

    json_object_put(jobj);
    return entry;
}

void test_log_entries() {
    memory_pool *pool = create_memory_pool();

    log_entry *entry1 = allocate_log_entry(pool);
    char *json1 = serialize_log_entry(entry1);

    log_entry *entry2 = deserialize_log_entry(json1);

    printf("Original Log: %s\n", entry1->log_message);
    printf("Deserialized Log: %s\n", entry2->log_message);

    deallocate_log_entry(pool, entry1);
    free(json1);
    deallocate_log_entry(pool, entry2);

    pthread_mutex_destroy(&pool->lock);
    free(pool->entries);
    free(pool);
}

