void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

node_t* allocate_node_from_pool(MemoryPool* mp) {
    size_t offset = atomic_fetch_add(&mp->offset, mp->block_size);
    void* block = (char*)mp->pool + offset;
    if ((uintptr_t)block + mp->block_size > (uintptr_t)mp->pool + mp->block_size * POOL_SIZE) {
        return NULL; // Out of pool space
    }
    return (node_t*)block;
}

ConcurrentLinkedList* create_list() {
    ConcurrentLinkedList* list = malloc(sizeof(ConcurrentLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_spin_init(&list->lock, PTHREAD_PROCESS_PRIVATE);

    return list;
}

void destroy_list(ConcurrentLinkedList* list) {
