        node_t* current = list->head;
        while (current) {
            node_t* next = current->next;
            free(current); // Assuming no pool allocation for nodes in this function
            current = next;
        }
        pthread_spin_destroy(&list->lock);
        free(list);
    }
}

node_t* add_node(ConcurrentLinkedList* list, double value, char type_name) {
