    if (!new_node) return NULL;

    new_node->data = value;
    new_node->type_name = type_name;
    new_node->next = NULL;

    pthread_spin_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_spin_unlock(&list->lock);

    return new_node;
}

double get_random_double(double min, double max) {
    return (max - min) * ((double)rand() / RAND_MAX) + min;
}

char get_random_char(const char* valid_chars, size_t len) {
    size_t index = rand() % len;
    return valid_chars[index];
}
