#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define logging levels
typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

// Event struct containing timestamp, event type, and message
typedef struct {
    time_t timestamp;
    LogLevel level;
    char *message;
} Event;

// Buffer to hold log messages
typedef struct {
    char *data;
    size_t capacity;
    size_t length;
} Buffer;

// Node for the custom queue
typedef struct QueueNode {
    Event event;
    struct QueueNode* next;
} QueueNode;

// MessageQueue with enqueue and dequeue operations
typedef struct {
    QueueNode *front, *rear;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    LogLevel current_level; // Minimum level to log
} MessageQueue;

// Initialize logging framework
void init_logging_framework(MessageQueue **queue, size_t num_buffers, Buffer ***buffers) {
    // Allocate memory for the message queue
    *queue = (MessageQueue*)malloc(sizeof(MessageQueue));
    (*queue)->front = NULL;
    (*queue)->rear = NULL;
    pthread_mutex_init(&(*queue)->lock, NULL);
    pthread_cond_init(&(*queue)->not_empty, NULL);

    // Set default logging level
    (*queue)->current_level = INFO;

    // Allocate memory for buffers
    *buffers = (Buffer**)malloc(num_buffers * sizeof(Buffer*));
    for (size_t i = 0; i < num_buffers; ++i) {
        (*buffers)[i] = (Buffer*)malloc(sizeof(Buffer));
        (*buffers)[i]->capacity = 1024;
        (*buffers)[i]->length = 0;
        (*buffers)[i]->data = (char*)malloc((*buffers)[i]->capacity);
    }
}

// Thread-safe enqueue operation
void enqueue_event(MessageQueue *queue, Event event) {
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);

    if (!queue->front) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }

    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

// Thread-safe dequeue operation
int dequeue_event(MessageQueue *queue, Event *event) {
    pthread_mutex_lock(&queue->lock);

    while (!queue->front) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }

    QueueNode* temp = queue->front;
    *event = temp->event;

    queue->front = queue->front->next;

    if (!queue->front) {
        queue->rear = NULL;
    }

    free(temp);
    pthread_mutex_unlock(&queue->lock);

    return 0;
}

// Cleanup function
void cleanup_logging_framework(MessageQueue *queue, Buffer **buffers, size_t num_buffers) {
    // Clean up the message queue
    while (dequeue_event(queue, NULL) == 0);

    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);

    // Free buffers
    for (size_t i = 0; i < num_buffers; ++i) {
        if (buffers[i]->data) {
            free(buffers[i]->data);
        }
        free(buffers[i]);
    }
    free(buffers);
}
