#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define NODE_POOL_SIZE 1024
#define EDGE_POOL_SIZE 2048
#define LOCK_FREE_LIST_NODE_COUNT 64

typedef struct Edge {
    int weight;
    char type_label[16];
} Edge;

typedef struct Node {
    double value;
    pthread_mutex_t lock;
    Edge* edges;
    size_t edge_count;
    size_t max_edges;
} Node;

typedef struct Graph {
    Node* nodes;
    size_t node_count;
    size_t max_nodes;
    pthread_rwlock_t rwlock;
} Graph;

typedef struct MemoryBlock {
    void* ptrs[LOCK_FREE_LIST_NODE_COUNT];
    size_t count;
} MemoryBlock;

static MemoryBlock node_pool = {0};
static MemoryBlock edge_pool = {0};

void init_memory_pool(MemoryBlock* pool, size_t element_size, size_t pool_size) {
    for (size_t i = 0; i < pool_size; ++i) {
        void* ptr = malloc(element_size);
        if (!ptr) break;
        pool->ptrs[i] = ptr;
    }
    pool->count = pool_size;
}

void* allocate_from_pool(MemoryBlock* pool, size_t element_size) {
    if (pool->count == 0) return NULL;
    void* ptr = pool->ptrs[--(pool->count)];
    memset(ptr, 0, element_size);
    return ptr;
}

void deallocate_to_pool(MemoryBlock* pool, void* ptr, size_t element_size) {
    if (pool->count < LOCK_FREE_LIST_NODE_COUNT) {
        pool->ptrs[pool->count++] = ptr;
    } else {
        free(ptr);
    }
}

Graph* create_graph(size_t max_nodes) {
    Graph* graph = malloc(sizeof(Graph));
    graph->nodes = allocate_from_pool(&node_pool, sizeof(Node) * max_nodes);
    graph->node_count = 0;
    graph->max_nodes = max_nodes;
    pthread_rwlock_init(&graph->rwlock, NULL);

    for (size_t i = 0; i < max_nodes; ++i) {
        Node* node = &graph->nodes[i];
        pthread_mutex_init(&node->lock, NULL);
        node->edges = allocate_from_pool(&edge_pool, sizeof(Edge) * 10); // Initial edge capacity
        node->edge_count = 0;
        node->max_edges = 10;
    }
    return graph;
}

void destroy_graph(Graph* graph) {
    for (size_t i = 0; i < graph->node_count; ++i) {
        Node* node = &graph->nodes[i];
        pthread_mutex_destroy(&node->lock);
        deallocate_to_pool(&edge_pool, node->edges, sizeof(Edge) * node->max_edges);
    }
    deallocate_to_pool(&node_pool, graph->nodes, sizeof(Node) * graph->max_nodes);
    pthread_rwlock_destroy(&graph->rwlock);
    free(graph);
}

void add_node(Graph* graph, double value) {
    pthread_rwlock_wrlock(&graph->rwlock);
    if (graph->node_count < graph->max_nodes) {
        Node* node = &graph->nodes[graph->node_count++];
        node->value = value;
        pthread_mutex_init(&node->lock, NULL);
        node->edges = allocate_from_pool(&edge_pool, sizeof(Edge) * 10);
        node->edge_count = 0;
        node->max_edges = 10;
    }
    pthread_rwlock_unlock(&graph->rwlock);
}

void add_edge(Graph* graph, size_t from_node_idx, int weight, const char* type_label) {
    if (from_node_idx >= graph->node_count) return;

    Node* node = &graph->nodes[from_node_idx];
    pthread_mutex_lock(&node->lock);

    if (node->edge_count == node->max_edges) {
        size_t new_max_edges = node->max_edges * 2;
        Edge* new_edges = allocate_from_pool(&edge_pool, sizeof(Edge) * new_max_edges);
        memcpy(new_edges, node->edges, sizeof(Edge) * node->edge_count);
        deallocate_to_pool(&edge_pool, node->edges, sizeof(Edge) * node->max_edges);
        node->edges = new_edges;
        node->max_edges = new_max_edges;
    }

    Edge* edge = &node->edges[node->edge_count++];
    strncpy(edge->type_label, type_label, sizeof(edge->type_label) - 1);
    edge->weight = weight;

    pthread_mutex_unlock(&node->lock);
}

double get_node_value(Graph* graph, size_t node_idx) {
    double value = 0.0;
    if (node_idx < graph->node_count) {
        Node* node = &graph->nodes[node_idx];
        pthread_mutex_lock(&node->lock);
        value = node->value;
        pthread_mutex_unlock(&node->lock);
    }
    return value;
}

int main() {
    srand(time(NULL));
    init_memory_pool(&node_pool, sizeof(Node), NODE_POOL_SIZE);
    init_memory_pool(&edge_pool, sizeof(Edge), EDGE_POOL_SIZE);

    Graph* graph = create_graph(1000);

    add_node(graph, (double)rand() / RAND_MAX * 100.0);
    add_edge(graph, 0, rand() % 10 + 1, "typeA");

    printf("Node value: %.2f\n", get_node_value(graph, 0));

    destroy_graph(graph);
    return 0;
}
