#include <pthread.h>

// Structure representing a record
typedef struct {
    long* offset_ptr;
    int key_ref;
} Record;

void* memory_allocation_failed(void) {
    fprintf(stderr, "Memory allocation failed\n");
    exit(EXIT_FAILURE);
}

int allocate_and_initialize(int num_offsets, long** offsets, int** keys, Record*** records, pthread_mutex_t* mutex) {
    if (num_offsets < 1 || num_offsets > 10000) return -1;

    // Allocate memory for offsets
    *offsets = malloc(num_offsets * sizeof(long));
    if (*offsets == NULL) goto fail;

    // Initialize offsets
    for (int i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = i;
    }

    // Allocate memory for keys and set up a hash table to ensure uniqueness
    *keys = malloc(num_offsets * sizeof(int));
    if (*keys == NULL) goto fail;

    int* key_set = calloc(1000001, sizeof(int)); // Simple hash table as bit array
    if (key_set == NULL) goto fail;

    for (int i = 0; i < num_offsets; ++i) {
        int new_key;
        do {
            new_key = rand() % 1000001;
        } while (key_set[new_key]);

        (*keys)[i] = new_key;
        key_set[new_key] = 1; // Mark as used
    }

    free(key_set);

    // Allocate memory for records
    *records = malloc(num_offsets * sizeof(Record*));
    if (*records == NULL) goto fail;

    pthread_mutex_lock(mutex);

    // Initialize records
    for (int i = 0; i < num_offsets; ++i) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) goto unlock_fail;

        (*records)[i]->offset_ptr = &((*offsets)[i]);
        (*records)[i]->key_ref = (*keys)[i];
    }

    pthread_mutex_unlock(mutex);

    return 0;

unlock_fail:
    while (--i >= 0) free((*records)[i]); // Free partially allocated records
    pthread_mutex_unlock(mutex);
fail:
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*records) {
        for (int i = 0; i < num_offsets; ++i) {
            if ((*records)[i]) free((*records)[i]);
        }
        free(*records);
    }
    return -1;
}

void validate_records(int num_offsets, Record** records, long* offsets, int* keys) {
    for (int i = 0; i < num_offsets; ++i) {
        if (!records[i] || !records[i]->offset_ptr || records[i]->key_ref == -1) {
            fprintf(stderr, "Validation failed at index %d\n", i);
            return;
        }
        long offset_val = *records[i]->offset_ptr;
        int key_val = keys[i];

        if (offsets[offset_val] != offset_val || records[i]->key_ref != key_val) {
            fprintf(stderr, "Data integrity check failed at index %d\n", i);
            return;
        }
    }
    printf("All records validated successfully.\n");
}

int main() {
    int num_offsets = 10000; // Example input
    long* offsets = NULL;
    int* keys = NULL;
    Record** records = NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (allocate_and_initialize(num_offsets, &offsets, &keys, &records, &mutex) != 0) {
        memory_allocation_failed();
    }

    validate_records(num_offsets, records, offsets, keys);

    // Free allocated resources
    free(offsets);
    free(keys);
    for (int i = 0; i < num_offsets; ++i) {
        free(records[i]);
    }
    free(records);

    pthread_mutex_destroy(&mutex);

    return 0;
}
