void RealTimeAudioMonitor::ParseAndValidateFrame(const std::vector<float>& frame) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (ValidateFrame(frame)) {
        // Process the valid frame
        std::cout << "Frame validated and processed." << std::endl;
    } else {
        std::cerr << "Invalid frame detected." << std::endl;
    }
}

bool RealTimeAudioMonitor::ValidateFrame(const std::vector<float>& frame) {
    if (frame.size() != monitoring_range) {
        return false; // Size mismatch
    }

    for (const float& sample : frame) {
        if (!std::isfinite(sample)) { // Check for anomalies like NaN or Inf
            return false;
        }
    }

    return true;
}

