['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_TASKS 500

typedef enum { LOW, MEDIUM, HIGH } PriorityLevel;

typedef struct {
    void (*function)(void *);
    void *arg;
    PriorityLevel priority;
} Task;

typedef struct {
    Task **tasks;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} TaskQueue;

typedef struct {
    pthread_t *threads;
    size_t thread_count;
    TaskQueue queue;
    int stop;
    double success_rate;
    double average_execution_time;
    size_t task_backlog_length;
    pthread_mutex_t stats_lock;
} WorkerPool;

TaskQueue* create_task_queue(size_t capacity) {
    TaskQueue *queue = (TaskQueue *)malloc(sizeof(TaskQueue));
    queue->tasks = (Task **)malloc(capacity * sizeof(Task *));
    queue->capacity = capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond_var, NULL);
    return queue;
}

void destroy_task_queue(TaskQueue *queue) {
    free(queue->tasks);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond_var);
    free(queue);
}

WorkerPool* create_worker_pool(size_t initial_thread_count) {
    WorkerPool *pool = (WorkerPool *)malloc(sizeof(WorkerPool));
    pool->threads = (pthread_t *)malloc(initial_thread_count * sizeof(pthread_t));
    pool->thread_count = initial_thread_count;
    pool->queue = *(create_task_queue(100));
    pool->stop = 0;
    pool->success_rate = 0.0;
    pool->average_execution_time = 0.0;
    pool->task_backlog_length = 0;
    pthread_mutex_init(&pool->stats_lock, NULL);

    for (size_t i = 0; i < initial_thread_count; ++i) {
        pthread_create(&pool->threads[i], NULL, worker_function, pool);
    }
    return pool;
}

void destroy_worker_pool(WorkerPool *pool) {
    pool->stop = 1;
    for (size_t i = 0; i < pool->thread_count; ++i) {
        pthread_join(pool->threads[i], NULL);
    }
    free(pool->threads);
    destroy_task_queue(&(pool->queue));
    pthread_mutex_destroy(&pool->stats_lock);
    free(pool);
}

void submit_task(WorkerPool *pool, void (*function)(void *), void *arg, PriorityLevel priority) {
    Task task = {function, arg, priority};

    pthread_mutex_lock(&pool->queue.lock);
    while (pool->queue.count == pool->queue.capacity) {
        pthread_cond_wait(&pool->queue.cond_var, &pool->queue.lock);
    }

    pool->queue.tasks[pool->queue.count++] = &task;
    pthread_cond_signal(&pool->queue.cond_var);
    pthread_mutex_unlock(&pool->queue.lock);
}

void* worker_function(void *arg) {
    WorkerPool *pool = (WorkerPool *)arg;
    while (!pool->stop) {
        Task *task;

        pthread_mutex_lock(&pool->queue.lock);
        while (pool->queue.count == 0 && !pool->stop) {
            pthread_cond_wait(&pool->queue.cond_var, &pool->queue.lock);
        }

        if (pool->stop) {
            pthread_mutex_unlock(&pool->queue.lock);
            break;
        }

        task = pool->queue.tasks[--(pool->queue.count)];
        pthread_mutex_unlock(&pool->queue.lock);

        clock_t start_time = clock();
        task->function(task->arg);
        clock_t end_time = clock();

        double execution_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

        pthread_mutex_lock(&pool->stats_lock);
        pool->success_rate += 1.0; // Simplified for illustration
        pool->average_execution_time = ((pool->average_execution_time * task_backlog_length) + execution_time) / (task_backlog_length + 1);
        ++(pool->task_backlog_length);
        pthread_mutex_unlock(&pool->stats_lock);
    }
    return NULL;
}

void report_statistics(WorkerPool *pool) {
    while (!pool->stop) {
        sleep(60); // Every minute
        pthread_mutex_lock(&pool->stats_lock);

        printf("Success Rate: %.2f%%\n", pool->success_rate);
        printf("Average Execution Time: %.6f seconds\n", pool->average_execution_time);
        printf("Task Backlog Length: %zu\n", pool->task_backlog_length);

        pthread_mutex_unlock(&pool->stats_lock);
    }
}

int main() {
    WorkerPool *pool = create_worker_pool(4);

    // Example task submission
    for (int i = 0; i < MAX_TASKS; ++i) {
        submit_task(pool, example_function, &data[i], HIGH);
    }

    pthread_t report_thread;
    pthread_create(&report_thread, NULL, (void *)report_statistics, pool);

    // Simulate work
    sleep(300); // Run for 5 minutes

    destroy_worker_pool(pool);

    return 0;
}

void example_function(void *arg) {
    // Example task implementation
}
``` 

