#define MAX_TASKS 20
#define TIMEOUT 60

int task_count = 0;
pid_t child_pids[MAX_TASKS] = {0};

void handle_sigterm(int sig) {
    for (int i = 0; i < task_count; ++i) {
        if (child_pids[i]) {
            kill(child_pids[i], SIGTERM);
        }
    }
}

void log_message(FILE *log_fd, const char *message) {
    fprintf(log_fd, "%s\n", message);
    fflush(log_fd);
}

int execute_task(const char *script_path, FILE *log_fd) {
    pid_t pid = fork();
    if (pid == 0) { // Child process
        alarm(TIMEOUT); // Set timeout for the child process

        sigset_t set;
        sigemptyset(&set);
        sigaddset(&set, SIGALRM);
        sigprocmask(SIG_BLOCK, &set, NULL);

        execl(script_path, script_path, (char *)NULL);

        perror("execl"); // If execl fails
        exit(EXIT_FAILURE);
    } else if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, WUNTRACED | WCONTINUED);

        if (WIFEXITED(status)) {
            log_message(log_fd, "Task completed successfully.");
        } else if (WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) {
            kill(pid, SIGKILL); // Ensure child is killed
            log_message(log_fd, "Task terminated due to timeout.");
        }
    } else {
        perror("fork");
        return 0;
    }

    return 1;
}

int manage_tasks(const char *scripts[], int script_count, FILE *log_fd) {
    signal(SIGTERM, handle_sigterm);

    for (int i = 0; i < script_count && task_count < MAX_TASKS; ++i) {
        if (execute_task(scripts[i], log_fd)) {
            child_pids[task_count++] = fork();
            if (child_pids[task_count - 1] == 0) { // Child process
                execute_task(scripts[i], log_fd);
                exit(0); // Ensure child exits after task completion
            } else if (child_pids[task_count - 1] < 0) {
                perror("fork");
                return 0;
            }
        } else {
            log_message(log_fd, "Failed to start task.");
            return 0;
        }
    }

    // Monitor and adapt tasks based on system load
    while (task_count > 0) {
        int status;
        pid_t pid = waitpid(-1, &status, WNOHANG);

        if (pid > 0 && WIFEXITED(status)) {
            for (int i = 0; i < task_count; ++i) {
                if (child_pids[i] == pid) {
                    child_pids[i] = 0;
                    --task_count;
                    break;
                }
            }
        }

        // Simulate adaptive scaling based on system load
        struct rusage usage;
        getrusage(RUSAGE_SELF, &usage);

        if (usage.ru_maxrss < some_threshold) { // Define some_threshold based on your needs
            if (task_count < MAX_TASKS && script_count > task_count) {
                execute_task(scripts[task_count], log_fd);
            }
        }

        sleep(1); // Adjust sleep time as needed for monitoring frequency
    }

    return 1;
}
