#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
    double dblValue;
    char *strPtr;
} Record;

typedef struct CacheNode {
    Record record;
    time_t timestamp;
    struct CacheNode *prev, *next;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    size_t capacity;
    pthread_mutex_t lock;
} LRUCache;

LRUCache* createCache(size_t capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->head = cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void freeCache(LRUCache *cache) {
    CacheNode *current = cache->head;
    while (current != NULL) {
        CacheNode *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void updateTimestamp(CacheNode *node) {
    node->timestamp = time(NULL);
}

CacheNode* getLeastRecentlyUsed(LRUCache *cache) {
    return cache->head;
}

void moveToTail(LRUCache *cache, CacheNode *node) {
    if (node == cache->tail) return;

    if (node == cache->head) {
        cache->head = node->next;
        cache->head->prev = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    node->next = NULL;
    node->prev = cache->tail;
    if (cache->tail) {
        cache->tail->next = node;
    }
    cache->tail = node;

    if (!cache->head) {
        cache->head = node;
    }
}

void addToCache(LRUCache *cache, Record record) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *node = malloc(sizeof(CacheNode));
    node->record = record;
    updateTimestamp(node);

    if (cache->capacity <= 0 || cache->head == NULL) {
        node->next = node->prev = NULL;
        cache->head = cache->tail = node;
    } else if (cache->capacity > 1 && cache->size < cache->capacity) {
        moveToTail(cache, node);
        cache->tail->next = node;
        node->prev = cache->tail;
        cache->tail = node;
    } else {
        CacheNode *lru = getLeastRecentlyUsed(cache);
        if (lru == cache->head) {
            cache->head = lru->next;
            if (cache->head) {
                cache->head->prev = NULL;
            }
        } else {
            lru->prev->next = lru->next;
            if (lru->next) {
                lru->next->prev = lru->prev;
            }
        }
        free(lru);

        moveToTail(cache, node);
    }

    pthread_mutex_unlock(&cache->lock);
}

Record* findLargest(int *arr, size_t n, pthread_mutex_t *mutex) {
    pthread_mutex_lock(mutex);
    int largest = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    pthread_mutex_unlock(mutex);
    return &((Record){.value = largest, .dblValue = 0.0, .strPtr = NULL});
}

void* processOperations(void *arg);

