#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>
#include <float.h>

#define MAX_THREADS 10
#define POOL_SIZE 1024

typedef struct {
    float components[3];
    size_t dimensions;
} Vector;

typedef struct {
    double value;
} Point;

typedef struct MemoryPool {
    void *pool;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

void init_pool(MemoryPool *mp, size_t pool_size) {
    mp->pool = malloc(pool_size);
    mp->size = pool_size;
    pthread_mutex_init(&mp->lock, NULL);
}

void* allocate_from_pool(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    void *ptr = malloc(size);
    if (!ptr && (mp->size >= size)) { // Simulate memory exhaustion
        ptr = mp->pool;
        memmove(ptr, mp->pool + sizeof(mp->pool), size);
        mp->size -= size;
    }
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

double random_double(double min, double max) {
    return min + ((max - min) * rand() / (RAND_MAX + 1.0));
}

double euclidean_distance(const Vector *v1, const Vector *v2) {
    if (v1->dimensions != v2->dimensions) {
        fprintf(stderr, "Vector dimensions do not match\n");
        return DBL_MAX;
    }
    double distance = 0.0;
    for (size_t i = 0; i < v1->dimensions; ++i) {
        double diff = v1->components[i] - v2->components[i];
        distance += diff * diff;
    }
    return sqrt(distance);
}

void* thread_safe_euclidean_distance(void *arg) {
    const Vector **vectors = (const Vector **)arg;
    size_t index1, index2;

    pthread_mutex_lock(&pthread_self());
    // Retrieve indices from some source or user input
    printf("Enter two indices to calculate distance: ");
    scanf("%zu %zu", &index1, &index2);
    pthread_mutex_unlock(&pthread_self());

    if (index1 >= MAX_THREADS || index2 >= MAX_THREADS) {
        fprintf(stderr, "Invalid indices\n");
        return NULL;
    }

    double dist = euclidean_distance(vectors[index1], vectors[index2]);
    printf("Distance: %f\n", dist);
    return NULL;
}

void manage_memory() {
    MemoryPool pool;
    init_pool(&pool, POOL_SIZE);

    Vector *vectors[MAX_THREADS];
    Point *points[MAX_THREADS];
    int *indices[MAX_THREADS];

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        vectors[i] = allocate_from_pool(&pool, sizeof(Vector));
        points[i] = allocate_from_pool(&pool, sizeof(Point));
        indices[i] = allocate_from_pool(&pool, sizeof(int));

        // Initialize vector
        vectors[i]->dimensions = 3;
        for (size_t j = 0; j < vectors[i]->dimensions; ++j) {
            vectors[i]->components[j] = rand() % 100 / 10.0;  // Random float between 0 and 10
        }

        // Initialize point with random double
        points[i]->value = random_double(0.0, 100.0);

        // Initialize index (for demonstration purposes)
        *indices[i] = i;
    }

    pthread_t threads[MAX_THREADS];
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, thread_safe_euclidean_distance, vectors);
    }

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_pool(&pool);
}

int main() {
    srand(time(NULL));
    manage_memory();
    return 0;
}
