#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_ELEMENTS 10000000

typedef struct {
    double *data;
    size_t count;
} SampleSequence;

typedef struct {
    pthread_mutex_t lock;
    int lastProcessedIndex;
    int maxBufferedSamples;
} PipelineState;

double customMedian(double* data, size_t count, bool prioritizeSpeed);
void computeStatistics(double* data, size_t count, double *min, double *max, double *stdDev);

SampleSequence* RealTimeDataProcessor(
    const double* incomingData,
    int numSamples,
    PipelineState* pipeline,
    int lastSampleIndexProcessed,
    int maxBufferedSamples
) {
    if (numSamples <= 0 || !incomingData || !pipeline)
        return NULL;

    pthread_mutex_lock(&pipeline->lock);

    SampleSequence *sequence = (SampleSequence *)malloc(sizeof(SampleSequence));
    if (!sequence) {
        pthread_mutex_unlock(&pipeline->lock);
        return NULL;
    }

    sequence->data = (double*)malloc(MAX_ELEMENTS * sizeof(double));
    if (!sequence->data) {
        free(sequence);
        pthread_mutex_unlock(&pipeline->lock);
        return NULL;
    }

    size_t effectiveCount = numSamples < maxBufferedSamples ? numSamples : maxBufferedSamples;
    for (size_t i = 0; i < effectiveCount; ++i) {
        sequence->data[i] = incomingData[i];
    }
    sequence->count = effectiveCount;

    pthread_mutex_unlock(&pipeline->lock);

    return sequence;
}

double customMedian(double* data, size_t count, bool prioritizeSpeed) {
    if (count == 0)
        return NAN;

    // Custom sorting algorithm: quicksort for simplicity
    qsort(data, count, sizeof(double), compareDoubles);

    if (count % 2 == 1)
        return data[count / 2];
    else
        return (data[(count - 1) / 2] + data[count / 2]) / 2.0;
}

void computeStatistics(double* data, size_t count, double *min, double *max, double *stdDev) {
    if (count == 0 || !data)
        return;

    *min = data[0];
    *max = data[0];

    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += data[i];
        if (data[i] < *min) *min = data[i];
        if (data[i] > *max) *max = data[i];
    }

    double mean = sum / count;
    double varianceSum = 0.0;

    for (size_t i = 0; i < count; ++i)
        varianceSum += (data[i] - mean) * (data[i] - mean);

    *stdDev = sqrt(varianceSum / count);
}

int compareDoubles(const void* a, const void* b) {
    double arg1 = *(const double*)a;
    double arg2 = *(const double*)b;

    if (arg1 < arg2) return -1;
    if (arg1 > arg2) return 1;
    return 0;
}
