using System;
using System.Collections.Generic;
using System.Threading;

public class DynamicDataGenerator {
    private readonly Random _random = new Random();
    private readonly object _lock = new object();
    public float Min { get; set; }
    public float Max { get; set; }
    public float StepSize { get; set; }

    public DynamicDataGenerator(float min, float max, float stepSize) {
        if (min >= max || stepSize <= 0)
            throw new ArgumentException("Invalid range or step size");

        Min = min;
        Max = max;
        StepSize = stepSize;
    }

    public int GetRandomInt() {
        lock (_lock) {
            return _random.Next((int)(Min / StepSize), (int)(Max / StepSize));
        }
    }

    public float GetRandomFloat() {
        lock (_lock) {
            return Min + ((float)_random.NextDouble() * (Max - Min)) / StepSize * StepSize;
        }
    }
}
