    coordinate *coordinates;    // Array of coordinates
    size_t num_coordinates;
    metadata *metadata;         // Optional metadata
    int has_metadata;
} geometry;

typedef struct {
    void **pool;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t initial_capacity) {
    memory_pool *mp = (memory_pool*)malloc(sizeof(memory_pool));
    mp->capacity = initial_capacity;
    mp->size = 0;
    mp->pool = (void**)malloc(mp->capacity * sizeof(void*));
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* pool_alloc(memory_pool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);

    if (mp->size + 1 > mp->capacity) {
        size_t new_capacity = mp->capacity * 2;
        void **new_pool = (void**)realloc(mp->pool, new_capacity * sizeof(void*));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL; // Handle realloc failure
        }
        mp->pool = new_pool;
        mp->capacity = new_capacity;
    }

    void *ptr = malloc(size);
    if (ptr) {
        mp->pool[mp->size++] = ptr;
    }
    pthread_mutex_unlock(&mp->lock);

    return ptr;
}

void pool_free(memory_pool *mp, void *ptr) {
    // Implement a garbage collection strategy to handle memory reclamation
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->size; ++i) {
        if (mp->pool[i] == ptr) {
            free(ptr);
            memmove(&mp->pool[i], &mp->pool[i + 1], (mp->size - i - 1) * sizeof(void*));
            --mp->size;
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
}

