// Define the configuration types
typedef enum {
    CONFIG_TYPE_INT,
    CONFIG_TYPE_STRING,
    CONFIG_TYPE_BOOL
} config_type_t;

// Configuration entry structure
typedef struct {
    char *key;
    char *value;
    config_type_t type;
} config_entry_t;

// Memory pool slab node
typedef struct PoolNode {
    void *memory;
    size_t size;
    struct PoolNode *next;
} PoolNode_t;

// Global memory pool structure
typedef struct {
    PoolNode_t *head;
    size_t total_size;
    pthread_mutex_t lock;
} MemoryPool_t;

MemoryPool_t memory_pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

// Function prototypes
void initialize_memory_pool(size_t initial_size);
void* allocate_from_pool(size_t size);
void deallocate_to_pool(void *memory, size_t size);
void resize_memory_pool_if_needed();

config_entry_t* create_config_entry(const char *key, const char *value, config_type_t type);
void free_config_entry(config_entry_t *entry);

char* serialize_config_to_json(config_entry_t **entries, size_t count);
int deserialize_config_from_json(char *json_str, config_entry_t ***entries, size_t *count);

// System performance metrics function pointers
typedef int (*metric_func)(void *);

typedef struct {
    char *name;
    metric_func func;
    void *param;
} system_metric_t;

system_metric_t* discover_system_metrics(size_t *count);

void log_memory_usage();
void log_performance_metrics();

// Implementation

void initialize_memory_pool(size_t initial_size) {
    pthread_mutex_lock(&memory_pool.lock);
    PoolNode_t *node = (PoolNode_t *)malloc(sizeof(PoolNode_t));
    node->memory = malloc(initial_size);
    node->size = initial_size;
    node->next = memory_pool.head;
    memory_pool.head = node;
    memory_pool.total_size += initial_size;
    pthread_mutex_unlock(&memory_pool.lock);
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);

    PoolNode_t *current = memory_pool.head;
    while (current != NULL && current->size < size) {
        current = current->next;
    }

    if (current == NULL) {
        resize_memory_pool_if_needed();
        current = memory_pool.head; // Recheck after resizing
    }

    void *allocated_memory = current->memory;
    current->memory += size;

    pthread_mutex_unlock(&memory_pool.lock);
    return allocated_memory;
}

void deallocate_to_pool(void *memory, size_t size) {
    pthread_mutex_lock(&memory_pool.lock);

    PoolNode_t *node = (PoolNode_t *)malloc(sizeof(PoolNode_t));
    node->memory = memory;
    node->size = size;
    node->next = memory_pool.head;
    memory_pool.head = node;

    pthread_mutex_unlock(&memory_pool.lock);
}

void resize_memory_pool_if_needed() {
    // Implement logic to resize the pool
    // For now, simply allocate more space
    size_t new_size = 1024; // Example size
    initialize_memory_pool(new_size);
}

config_entry_t* create_config_entry(const char *key, const char *value, config_type_t type) {
    config_entry_t *entry = (config_entry_t *)allocate_from_pool(sizeof(config_entry_t));
    entry->key = strdup(key);
    entry->value = strdup(value);
    entry->type = type;
    return entry;
}

void free_config_entry(config_entry_t *entry) {
    deallocate_to_pool(entry->key, strlen(entry->key) + 1);
    deallocate_to_pool(entry->value, strlen(entry->value) + 1);
    deallocate_to_pool(entry, sizeof(config_entry_t));
}

char* serialize_config_to_json(config_entry_t **entries, size_t count) {
    json_t *root = json_array();
    for (size_t i = 0; i < count; ++i) {
        json_t *entry_obj = json_object();
        json_object_set_new(entry_obj, "key", json_string(entries[i]->key));
        json_object_set_new(entry_obj, "value", json_string(entries[i]->value));
        char type_str[10];
        snprintf(type_str, sizeof(type_str), "%d", entries[i]->type);
        json_object_set_new(entry_obj, "type", json_string(type_str));
        json_array_append_new(root, entry_obj);
    }
    char *json_str = json_dumps(root, JSON_INDENT(2));
    json_decref(root);
    return json_str;
}

int deserialize_config_from_json(char *json_str, config_entry_t ***entries, size_t *count) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    size_t len = json_array_size(root);
    *entries = (config_entry_t **)allocate_from_pool(len * sizeof(config_entry_t *));
    for (size_t i = 0; i < len; ++i) {
        json_t *entry_obj = json_array_get(root, i);
        const char *key = json_string_value(json_object_get(entry_obj, "key"));
        const char *value = json_string_value(json_object_get(entry_obj, "value"));
        int type = atoi(json_string_value(json_object_get(entry_obj, "type")));
        (*entries)[i] = create_config_entry(key, value, (config_type_t)type);
    }
    *count = len;
    json_decref(root);
    return 0;
}

system_metric_t* discover_system_metrics(size_t *count) {
    // Example metrics discovery
    system_metric_t metrics[] = {
        {"CPU Usage", get_cpu_usage, NULL},
        {"Memory Usage", get_memory_usage, NULL}
    };
    *count = sizeof(metrics) / sizeof(system_metric_t);
    return metrics;
}

void log_memory_usage() {
    pthread_mutex_lock(&memory_pool.lock);
    printf("Total memory allocated: %zu bytes\n", memory_pool.total_size);
    pthread_mutex_unlock(&memory_pool.lock);
}

void log_performance_metrics() {
    size_t count;
    system_metric_t *metrics = discover_system_metrics(&count);
    for (size_t i = 0; i < count; ++i) {
        int value = metrics[i].func(metrics[i].param);
        printf("%s: %d\n", metrics[i].name, value);
    }
}

