#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define MAX_KEYS 1000000

typedef struct {
    int id;
} record_t;

typedef struct {
    pthread_mutex_t lock;
    long *offsets;
    int *keys;
    record_t *records;
    size_t num_offsets;
    float load_factor;
} memory_manager_t;

// Helper function for random number generation
int generate_unique_key(int max_value, int *existing_keys, int used_keys_count) {
    int new_key;
    do {
        new_key = rand() % max_value;
    } while (used_keys_count == 0 || binary_search(existing_keys, used_keys_count, new_key));
    return new_key;
}

// Check if a key exists in the sorted list
int binary_search(int *keys, int count, int key) {
    int left = 0, right = count - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (keys[mid] == key) return 1;
        if (keys[mid] < key) left = mid + 1;
        else right = mid - 1;
    }
    return 0;
}

// Initialize memory manager
void init_memory_manager(memory_manager_t *manager, size_t num_offsets, float load_factor) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->num_offsets = num_offsets;
    manager->load_factor = load_factor;

    // Allocate and initialize offsets array
    if (num_offsets > 0 && num_offsets <= 10000) {
        manager->offsets = malloc(num_offsets * sizeof(long));
        if (!manager->offsets) {
            perror("Failed to allocate memory for offsets");
            exit(EXIT_FAILURE);
        }

        for (size_t i = 0; i < num_offsets; ++i) {
            if ((long)i + 1 > LONG_MAX - i) {
                fprintf(stderr, "Integer overflow detected in offsets initialization\n");
                free(manager->offsets);
                exit(EXIT_FAILURE);
            }
            manager->offsets[i] = (long)i;
        }
    } else {
        fprintf(stderr, "num_offsets out of range: %zu\n", num_offsets);
        exit(EXIT_FAILURE);
    }

    // Calculate number of keys based on load factor
    size_t num_keys = (size_t)(num_offsets / load_factor);

    // Allocate and initialize keys array with unique random values
    manager->keys = malloc(num_keys * sizeof(int));
    if (!manager->keys) {
        perror("Failed to allocate memory for keys");
        free(manager->offsets);
        exit(EXIT_FAILURE);
    }

    int *existing_keys = malloc(num_keys * sizeof(int));
    if (!existing_keys) {
        perror("Failed to allocate temporary memory for key uniqueness check");
        free(manager->keys);
        free(manager->offsets);
        exit(EXIT_FAILURE);
    }

    size_t used_keys_count = 0;
    for (size_t i = 0; i < num_keys; ++i) {
        manager->keys[i] = generate_unique_key(MAX_KEYS, existing_keys, used_keys_count++);
        // Maintain a sorted array of existing keys
        int pos = used_keys_count - 1;
        while (pos > 0 && existing_keys[pos-1] > manager->keys[i]) {
            existing_keys[pos] = existing_keys[pos-1];
            --pos;
        }
        existing_keys[pos] = manager->keys[i];
    }

    free(existing_keys);

    // Allocate and initialize records array
    manager->records = malloc(num_offsets * sizeof(record_t));
    if (!manager->records) {
        perror("Failed to allocate memory for records");
        free(manager->keys);
        free(manager->offsets);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        manager->records[i].id = i;
    }
}

// Function to serialize records
void serialize_records(const memory_manager_t *manager, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for serialization");
        return;
    }

    pthread_mutex_lock(&manager->lock);
    size_t offsets_size = manager->num_offsets * sizeof(long);
    size_t keys_size = (size_t)(manager->num_offsets / manager->load_factor) * sizeof(int);

    if (fwrite(manager->offsets, sizeof(long), manager->num_offsets, file) != manager->num_offsets ||
        fwrite(manager->keys, sizeof(int), (size_t)(manager->num_offsets / manager->load_factor), file) != manager->num_offsets / manager->load_factor) {
        perror("Failed to write data during serialization");
    }

    for (size_t i = 0; i < manager->num_offsets; ++i) {
        if (!fwrite(&manager->records[i], sizeof(record_t), 1, file)) {
            perror("Failed to serialize records array");
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
}

// Function to clean up memory manager
void cleanup_memory_manager(memory_manager_t *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
}

int main() {
    size_t num_offsets = 1000; // Example value, should be set based on application requirements
    float load_factor = 0.75f;

    memory_manager_t manager;
    init_memory_manager(&manager, num_offsets, load_factor);

    serialize_records(&manager, "records.bin");

    cleanup_memory_manager(&manager);
    return 0;
}
```

