#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <math.h>

#define MAX_STRING_LENGTH 256
#define NUM_POINTS 1000

typedef struct {
    float x;
    float y;
} point_t;

typedef struct {
    point_t p;
    double area;
} geometry_t;

typedef struct MemoryPool {
    void *start;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

void initialize_memory_pool(MemoryPool *pool, size_t size) {
    pool->start = malloc(size);
    if (!pool->start) exit(EXIT_FAILURE);
    pool->size = size;
    pthread_mutex_init(&pool->lock, NULL);
}

void *allocate_from_pool(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    void *ptr = memalign(16, size);
    if (ptr + size <= pool->start + pool->size) {
        ptr = pool->start;
        pool->start += size;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void deallocate_memory_pool(MemoryPool *pool) {
    free(pool->start);
    pthread_mutex_destroy(&pool->lock);
}

double calculate_distance(point_t a, point_t b) {
    float dx = a.x - b.x;
    float dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

void read_points(const char *filename, point_t *points, size_t max_points) {
    FILE *file = fopen(filename, "r");
    if (!file) exit(EXIT_FAILURE);

    for (size_t i = 0; i < max_points && fscanf(file, "%f %f", &points[i].x, &points[i].y) == 2; ++i);

    fclose(file);
}

void calculate_and_print_total_area(geometry_t *geometries, size_t num_geometries) {
    double total_area = 0.0;
    for (size_t i = 0; i < num_geometries; ++i) {
        total_area += geometries[i].area;
    }
    printf("Total Area: %f\n", total_area);
}

void *geometry_thread_func(void *arg) {
    geometry_t *geometries = (geometry_t *)arg;
    point_t center = {0.5, 0.5}; // Example center for area calculation

    for (size_t i = 0; i < NUM_POINTS; ++i) {
        geometries[i].area = calculate_distance(geometries[i].p, center);
    }

    return NULL;
}

void initialize_and_process_geometries(const char *filename) {
    MemoryPool pool;
    initialize_memory_pool(&pool, 1024 * 1024); // 1MB memory pool

    point_t *points = (point_t *)allocate_from_pool(&pool, NUM_POINTS * sizeof(point_t));
    char **strings = (char **)allocate_from_pool(&pool, NUM_POINTS * sizeof(char *));
    geometry_t *geometries = (geometry_t *)allocate_from_pool(&pool, NUM_POINTS * sizeof(geometry_t));

    for (size_t i = 0; i < NUM_POINTS; ++i) {
        strings[i] = (char *)allocate_from_pool(&pool, MAX_STRING_LENGTH);
        snprintf(strings[i], MAX_STRING_LENGTH, "String %zu", i);
    }

    read_points(filename, points, NUM_POINTS);

    for (size_t i = 0; i < NUM_POINTS; ++i) {
        geometries[i].p = points[i];
    }

    pthread_t threads[4];
    size_t segment_size = NUM_POINTS / 4;

    for (int i = 0; i < 4; ++i) {
        geometry_t *segment = &geometries[i * segment_size];
        pthread_create(&threads[i], NULL, geometry_thread_func, (void *)segment);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    calculate_and_print_total_area(geometries, NUM_POINTS);

    // Deallocate memory
    deallocate_memory_pool(&pool);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initialize_and_process_geometries(argv[1]);

    return EXIT_SUCCESS;
}
