pthread_mutex_t max_lock = PTHREAD_MUTEX_INITIALIZER;
int find_max_int(int *arr, size_t n) {
    pthread_mutex_lock(&max_lock);
    int max_val = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max_val) max_val = arr[i];
    }
    pthread_mutex_unlock(&max_lock);
    return max_val;
}

