['Below is a C implementation of the described functionality using a simple memory pool, lock-free mechanisms, and logging for monitoring. This code assumes basic structures are defined as needed for `record`, `memory_pool_t`, etc.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

#define POOL_SIZE 1024 // Size of the memory pool
#define CACHE_SIZE 512 // Cache size for reusing memory

typedef struct {
    int value;
} record;

// Memory pool structure for efficient allocation and deallocation
typedef struct {
    void *pool[POOL_SIZE];
    pthread_mutex_t lock;
} memory_pool_t;

// Cache entry for reusable records
typedef struct cache_entry {
    struct cache_entry *next;
    record *data;
} cache_entry_t;

// Global memory pool and cache structures
static memory_pool_t global_pool = { .lock = PTHREAD_MUTEX_INITIALIZER };
static cache_entry_t *cache_free_list = NULL;
static atomic_int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Logging structure for monitoring allocations/deallocations
typedef struct {
    int total_allocs;
    int total_deallocs;
} logging_info_t;

static logging_info_t log_info = { .total_allocs = 0, .total_deallocs = 0 };

// Utility function to initialize memory pool
void init_memory_pool(memory_pool_t *pool) {
    for (int i = 0; i < POOL_SIZE; ++i) {
        pool->pool[i] = NULL;
    }
}

// Allocate a block of memory from the global pool or cache
void* allocate_memory(size_t size, const char *type) {
    pthread_mutex_lock(&cache_lock);

    if (cache_size > 0 && type == "record") {
        cache_entry_t *entry = cache_free_list;
        cache_free_list = entry->next;
        --cache_size;
        pthread_mutex_unlock(&cache_lock);

        log_info.total_allocs++;
        return entry->data;
    }

    void *memory;
    pthread_mutex_lock(&global_pool.lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (!global_pool.pool[i]) {
            memory = malloc(size);
            global_pool.pool[i] = memory;
            pthread_mutex_unlock(&global_pool.lock);

            log_info.total_allocs++;
            return memory;
        }
    }

    pthread_mutex_unlock(&global_pool.lock);

    // If no free slot, allocate from heap (fallback)
    memory = malloc(size);
    log_info.total_allocs++;

    pthread_mutex_unlock(&cache_lock);
    return memory;
}

// Deallocate a block of memory to the global pool or cache
void deallocate_memory(void *memory, const char *type) {
    if (!memory) return;

    if (type == "record") {
        pthread_mutex_lock(&cache_lock);

        // Try to add back to cache
        if (cache_size < CACHE_SIZE) {
            cache_entry_t *entry = (cache_entry_t*)malloc(sizeof(cache_entry_t));
            entry->data = memory;
            entry->next = cache_free_list;
            cache_free_list = entry;
            ++cache_size;
        } else {
            free(memory);
        }

        pthread_mutex_unlock(&cache_lock);

    } else {
        // Deallocate from global pool
        pthread_mutex_lock(&global_pool.lock);
        for (int i = 0; i < POOL_SIZE; ++i) {
            if (global_pool.pool[i] == memory) {
                free(memory);
                global_pool.pool[i] = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&global_pool.lock);
    }

    log_info.total_deallocs++;
}

// Initialize and fill arrays with random values
void* initialize_data(long *offset, int n_offsets, int *keys, long *record_count) {
    size_t record_size = sizeof(record);

    // Allocate memory for offsets and keys
    offset = (long*)allocate_memory(n_offsets * sizeof(long), "long");
    keys = (int*)allocate_memory(n_offsets * sizeof(int), "int");

    // Allocate memory for records using a lock-free atomic operation for size count
    *record_count = n_offsets;
    record **records_array = (record**)allocate_memory(*record_count * sizeof(record*), "record*");

    for (long i = 0; i < *record_count; ++i) {
        records_array[i] = (record*)allocate_memory(record_size, "record");

        // Initialize record with random int value
        records_array[i]->value = rand() % 100; // Example range: 0-99

        // Populate offsets and keys arrays with dummy values for illustration
        offset[i] = i * 10;
        keys[i] = i + 1;
    }

    return (void*)records_array;
}

// Example of a logging function to track memory operations
void log_operations() {
    printf("Total allocations: %d\n", log_info.total_allocs);
    printf("Total deallocations: %d\n", log_info.total_deallocs);
}

int main() {
    long *offset = NULL;
    int *keys = NULL;
    long record_count = 0;

    // Seed random number generator
    srand((unsigned)time(NULL));

    // Initialize data arrays and records
    void* records = initialize_data(offset, 10, keys, &record_count);

    // Log the operations
    log_operations();

    // Deallocate all allocated memory
    for (long i = 0; i < record_count; ++i) {
        deallocate_memory(records[i], "record");
    }

    deallocate_memory(records, "record*");
    deallocate_memory(offset, "long");
    deallocate_memory(keys, "int");

    return 0;
}
