['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    size_t total_size;
    void *memory_start;
    pthread_mutex_t lock;
    size_t used_size;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size);
void destroy_memory_pool(MemoryPool *pool);

static inline void* pool_allocate(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (size + pool->used_size > pool->total_size) {
        // Attempt to resize the memory pool
        size_t new_size = pool->total_size * 2;
        void *new_memory_start = realloc(pool->memory_start, new_size);
        if (!new_memory_start) {
            fprintf(stderr, "Memory allocation failed during resizing\n");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->memory_start = new_memory_start;
        pool->total_size = new_size;
    }

    void *allocated_memory = (char*)pool->memory_start + pool->used_size;
    pool->used_size += size;
    pthread_mutex_unlock(&pool->lock);

    return allocated_memory;
}

static inline void* aligned_alloc(MemoryPool *pool, size_t alignment, size_t size) {
    void *ptr = pool_allocate(pool, size + alignment);
    if (!ptr)
        return NULL;

    uintptr_t addr = (uintptr_t)ptr + alignment;
    uintptr_t mask = alignment - 1;
    if ((addr & mask) != 0)
        addr += (alignment - (addr & mask));

    pthread_mutex_lock(&pool->lock);
    pool->used_size = (char*)addr - (char*)pool->memory_start + size;
    pthread_mutex_unlock(&pool->lock);

    return (void*)addr;
}

static inline void log_memory_usage(MemoryPool *pool) {
    printf("Memory Pool Usage: %zu/%zu bytes\n", pool->used_size, pool->total_size);
}

void initialize_data_structure(int num_records, int key_range_min, int key_range_max) {
