        records[i].value = rand() % (key_range_max - key_range_min + 1) + key_range_min;

        pthread_mutex_lock(&records_lock);
        // Perform thread-safe operations on records
        pthread_mutex_unlock(&records_lock);
    }

    log_memory_usage(pool);

    destroy_memory_pool(pool);
}

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool)
        return NULL;

    pool->memory_start = malloc(initial_size);
    if (!pool->memory_start) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    pool->total_size = initial_size;
    pool->used_size = 0;

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->memory_start);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}
