#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int packet_id;
    time_t timestamp;
    size_t payload_length;
} Packet;

typedef struct {
    int error_code;
    time_t processing_timestamp;
} PacketMetadata;

#define INITIAL_POOL_SIZE 1024
#define CACHE_MAX_SIZE 128

typedef struct MemoryPoolNode {
    void *memory;
    size_t size;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode *free_list;
    pthread_mutex_t lock;
    int num_allocations;
    int num_deallocations;
} MemoryPool;

MemoryPool pool = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0};

static void log_event(const char* event) {
    printf("%s: %d allocations, %d deallocations\n", event, pool.num_allocations, pool.num_deallocations);
}

void initialize_pool() {
    MemoryPoolNode *node = (MemoryPoolNode *)malloc(INITIAL_POOL_SIZE * sizeof(MemoryPoolNode));
    if (!node) {
        perror("Failed to allocate memory for the initial pool");
        exit(EXIT_FAILURE);
    }

    node->size = INITIAL_POOL_SIZE;
    node->memory = malloc(node->size * sizeof(Packet));
    if (!node->memory) {
        free(node);
        perror("Failed to allocate memory block in the initial pool");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < INITIAL_POOL_SIZE - 1; ++i) {
        node[i].next = &node[i + 1];
    }
    node[INITIAL_POOL_SIZE - 1].next = NULL;

    pool.free_list = node;
}

void* allocate_packet(size_t size) {
    pthread_mutex_lock(&pool.lock);

    if (!pool.free_list) {
        // Allocate more memory when pool is exhausted
        MemoryPoolNode *node = (MemoryPoolNode *)malloc(sizeof(MemoryPoolNode));
        if (!node) {
            perror("Failed to allocate memory for the new pool node");
            pthread_mutex_unlock(&pool.lock);
            return NULL;
        }

        node->size = size;
        node->memory = malloc(size);
        if (!node->memory) {
            free(node);
            perror("Failed to allocate memory block in the new pool node");
            pthread_mutex_unlock(&pool.lock);
            return NULL;
        }

        MemoryPoolNode *current = pool.free_list;
        while (current->next != NULL)
            current = current->next;

        current->next = node;
    }

    MemoryPoolNode *allocated_node = pool.free_list;
    pool.free_list = allocated_node->next;
    ++pool.num_allocations;
    pthread_mutex_unlock(&pool.lock);

    return allocated_node->memory;
}

void deallocate_packet(void *ptr) {
    if (!ptr)
        return;

    pthread_mutex_lock(&pool.lock);

    MemoryPoolNode node = {ptr, 0, pool.free_list};
    node.next = pool.free_list;
    pool.free_list = node;
    ++pool.num_deallocations;

    pthread_mutex_unlock(&pool.lock);
}

PacketMetadata* create_metadata() {
    return (PacketMetadata *)allocate_packet(sizeof(PacketMetadata));
}

void destroy_metadata(PacketMetadata *metadata) {
    if (!metadata)
        return;

    deallocate_packet(metadata);
}

Packet* create_packet(int packet_id, size_t payload_length) {
    Packet *packet = (Packet *)allocate_packet(sizeof(Packet));

    if (packet) {
        packet->packet_id = packet_id;
        packet->timestamp = time(NULL);
        packet->payload_length = payload_length;
    }

    return packet;
}

void destroy_packet(Packet *packet) {
    if (!packet)
        return;

    deallocate_packet(packet);
}

int main() {
    initialize_pool();

    // Example usage
    Packet *packet1 = create_packet(1, 512);
    PacketMetadata *metadata1 = create_metadata();

    if (packet1 && metadata1) {
        printf("Packet created with ID: %d\n", packet1->packet_id);
        log_event("After creation");

        destroy_packet(packet1);
        destroy_metadata(metadata1);

        log_event("After deallocation");
    }

    return 0;
}
```

