#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <semaphore.h>

typedef struct {
    int value;
    time_t timestamp;
} record;

typedef struct MemoryNode {
    long offset;
    int key;
    record *data;
    struct MemoryNode *next;
} MemoryNode;

typedef struct {
    MemoryNode *head;
    sem_t lock;
    size_t size;
    size_t capacity;
} MemoryPool;

// Function prototypes
MemoryPool* create_memory_pool(size_t initial_capacity);
int allocate_memory(MemoryPool *pool, long offset, int key, record *data);
void deallocate_memory(MemoryPool *pool, long offset);
void log_operation(const char *operation, long offset);
void initialize_ipc(int *shmid, char **shmaddr);

// Create a memory pool with specified capacity
MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->head = NULL;
    sem_init(&pool->lock, 0, 1);
    pool->size = 0;
    pool->capacity = initial_capacity;

    for (size_t i = 0; i < initial_capacity; ++i) {
        MemoryNode *node = (MemoryNode *)malloc(sizeof(MemoryNode));
        node->offset = -1; // Indicates unused
        node->key = -1;
        node->data = NULL;
        node->next = pool->head;
        pool->head = node;
    }

    return pool;
}

// Allocate memory in the pool for a new record
int allocate_memory(MemoryPool *pool, long offset, int key, record *data) {
    sem_wait(&pool->lock);
    MemoryNode *current = pool->head;

    while (current != NULL) {
        if (current->offset == -1 && current->key == -1) { // Unused slot
            current->offset = offset;
            current->key = key;
            current->data = data;
            log_operation("ALLOCATE", offset);
            sem_post(&pool->lock);
            return 0; // Success
        }
        current = current->next;
    }

    sem_post(&pool->lock);
    return -1; // Failure: pool is full
}

// Deallocate memory in the pool by offset
void deallocate_memory(MemoryPool *pool, long offset) {
    sem_wait(&pool->lock);
    MemoryNode *current = pool->head;
    while (current != NULL) {
        if (current->offset == offset) {
            current->offset = -1;
            current->key = -1;
            free(current->data);
            current->data = NULL;
            log_operation("DEALLOCATE", offset);
            break;
        }
        current = current->next;
    }
    sem_post(&pool->lock);
}

// Log memory operations
void log_operation(const char *operation, long offset) {
    FILE *log_file = fopen("memory_operations.log", "a");
    if (log_file != NULL) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: Offset=%ld at %s\n", operation, offset, ctime(&now));
        fclose(log_file);
    }
}

// Initialize IPC for shared memory
void initialize_ipc(int *shmid, char **shmaddr) {
    key_t key = ftok("memory_manager", 'R');
    if (key == -1) {
        perror("ftok");
        exit(1);
    }

    *shmid = shmget(key, sizeof(MemoryPool), IPC_CREAT | 0666);
    if (*shmid == -1) {
        perror("shmget");
        exit(1);
    }

    *shmaddr = (char *)shmat(*shmid, NULL, 0);
    if (*shmaddr == (char *)(-1)) {
        perror("shmat");
        exit(1);
    }
}

// Example usage
int main() {
    MemoryPool *pool = create_memory_pool(10);

    record r1 = { .value = 42, .timestamp = time(NULL) };
    allocate_memory(pool, 1000L, 1, &r1);

    deallocate_memory(pool, 1000L);

    int shmid;
    char *shmaddr;
    initialize_ipc(&shmid, &shmaddr);

    // Cleanup
    MemoryNode *current = pool->head;
    while (current != NULL) {
        MemoryNode *temp = current;
        current = current->next;
        free(temp);
    }
    sem_destroy(&pool->lock);
    free(pool);

    shmdt(shmaddr);
    shmctl(shmid, IPC_RMID, NULL);

    return 0;
}
``` 

This code demonstrates a basic modular memory management system that includes thread safety via semaphores and inter-process communication (IPC) using shared memory. It logs operations to a file with minimal overhead. The structure is designed for further expansion to accommodate more complex caching strategies and distributed environment considerations.']

