    printf("[%s] %s\n", ctime(&now), event);
}

int rand_age(int min, int max) {
    return rand() % (max - min + 1) + min;
}

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->blocks = malloc(num_blocks * sizeof(void *));
    pool->num_blocks = num_blocks;
    pthread_mutex_init(&pool_lock, NULL);
    for (size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
    }
    return pool;
}

void* pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->pool_lock);
    if (pool->num_blocks > 0) {
        void **block_ptr = &pool->blocks[--pool->num_blocks];
        void *allocated_block = *block_ptr;
        *block_ptr = NULL;
        pthread_mutex_unlock(&pool->pool_lock);
        return allocated_block;
    }
    pthread_mutex_unlock(&pool->pool_lock);
    return malloc(pool->block_size); // Fallback
}

void pool_free(MemoryPool *pool, void *ptr) {
    pthread_mutex_lock(&pool->pool_lock);
    if (pool->num_blocks < pool->blocks) {
        pool->blocks[pool->num_blocks++] = ptr;
    }
    pthread_mutex_unlock(&pool->pool_lock);
}

Profile* create_profile(const char *name, int age, MemoryPool *pool) {
    Profile *profile = pool_alloc(pool);
    if (!profile) return NULL;

    pthread_mutex_init(&profile->lock, NULL);
    strncpy(profile->name, name, NAME_LEN - 1);
    profile->age = age;
    profile->hobbies = NULL;

    log_event("Profile created");

    return profile;
}

void add_hobby(Profile *profile, const char *hobby_name) {
    pthread_mutex_lock(&profile->lock);

    Hobby *new_hobby = pool_alloc(pool);
    if (!new_hobby) {
        pthread_mutex_unlock(&profile->lock);
        log_event("Failed to allocate hobby");
        return;
    }

    strcpy(new_hobby->name, hobby_name);
    new_hobby->next = profile->hobbies;
    profile->hobbies = new_hobby;

    log_event("Hobby added");

    pthread_mutex_unlock(&profile->lock);
}

Profile* find_oldest_profile(Profile *profiles, size_t num_profiles) {
    Profile *oldest = NULL;
    int max_age = -1;

    for (size_t i = 0; i < num_profiles; ++i) {
        pthread_mutex_lock(&profiles[i].lock);

        if (profiles[i].age > max_age) {
            if (oldest) pthread_mutex_unlock(&oldest->lock);
            oldest = &profiles[i];
            max_age = profiles[i].age;
        } else {
            pthread_mutex_unlock(&profiles[i].lock);
        }
    }

    if (oldest) pthread_mutex_unlock(&oldest->lock);

    return oldest;
}

int main() {
    srand(time(NULL));
    MemoryPool *pool = create_memory_pool(sizeof(Profile), MAX_PROFILES);
    Profile *profiles[MAX_PROFILES];
    size_t num_profiles = 0;

    char name[NAME_LEN];
    int age, min_age = 18, max_age = 100;

    while (scanf("%s %d", name, &age) == 2 && num_profiles < MAX_PROFILES) {
        if (age < min_age || age > max_age) {
            log_event("Invalid age range");
            continue;
        }

        Profile *profile = create_profile(name, rand_age(min_age, max_age), pool);
        if (!profile) {
            log_event("Failed to create profile due to memory exhaustion");
            break;
        }
        profiles[num_profiles++] = profile;
    }

    Profile *oldest = find_oldest_profile(profiles, num_profiles);
    if (oldest) {
        printf("Oldest user: %s, Age: %d\n", oldest->name, oldest->age);
    } else {
        log_event("No profiles available");
    }

    // Cleanup
    for (size_t i = 0; i < num_profiles; ++i) {
        pthread_mutex_destroy(&profiles[i]->lock);
        pool_free(pool, profiles[i]);
    }
    free(pool->blocks);
    free(pool);

    return 0;
}
```

### Key Points:
- **Memory Pool**: A custom memory pool is used for efficient allocation and deallocation of `Profile` and `Hobby` structures.
- **Thread Safety**: Mutex locks are used to ensure thread-safe operations on profiles and hobbies.
- **Logging**: Simple logging with timestamps tracks significant events like profile creation and hobby addition.
- **Random Age Initialization**: Ages are initialized randomly within a specified range.
- **Error Handling**: Handles memory exhaustion gracefully by using a fallback allocation method.']

