```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <limits.h>
#include <time.h>

typedef struct {
    int value;
} record;

#define POOL_SIZE 1024
#define RECORDS 100

typedef struct MemoryPool {
    char *pool;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

// Global memory pool for records and related data
MemoryPool mem_pool = {0};

// Function to initialize the memory pool
void init_memory_pool(size_t size) {
    mem_pool.pool = malloc(size);
    if (!mem_pool.pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mem_pool.offset = 0;
    pthread_mutex_init(&mem_pool.lock, NULL);
}

// Function to allocate memory from the pool
void* pool_alloc(size_t size) {
    pthread_mutex_lock(&mem_pool.lock);
    if (mem_pool.offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&mem_pool.lock);
        return NULL; // Out of memory in the pool
    }
    void *ptr = mem_pool.pool + mem_pool.offset;
    mem_pool.offset += size;
    pthread_mutex_unlock(&mem_pool.lock);
    return ptr;
}

// Function to free all allocated resources (simple for demonstration)
void cleanup() {
    free(mem_pool.pool);
    pthread_mutex_destroy(&mem_pool.lock);
}

record* create_records(size_t count) {
    record *records = pool_alloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate records");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed random number generator
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
    }

    return records;
}

typedef struct QueueNode {
    int data;
    struct QueueNode *next;
} QueueNode;

typedef struct {
    QueueNode *front, *rear;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConcurrentQueue;

// Initialize concurrent queue
void init_queue(ConcurrentQueue *queue) {
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

// Enqueue element in the queue
void enqueue(ConcurrentQueue *queue, int value) {
    QueueNode* new_node = malloc(sizeof(QueueNode));
    if (!new_node) {
        perror("Failed to allocate queue node");
        exit(EXIT_FAILURE);
    }

    new_node->data = value;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);
    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

// Dequeue element from the queue
int dequeue(ConcurrentQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    while (queue->front == NULL) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }

    QueueNode* temp = queue->front;
    int data = temp->data;
    queue->front = queue->front->next;

    if (queue->front == NULL) {
        queue->rear = NULL;
    }

    free(temp);

    pthread_mutex_unlock(&queue->lock);
    return data;
}

int largest_value = INT_MIN;
pthread_mutex_t largest_lock;

void* find_largest(void *arg) {
    int value = *(int*)arg;
    pthread_mutex_lock(&largest_lock);
    if (value > largest_value) {
        largest_value = value;
    }
    pthread_mutex_unlock(&largest_lock);
}

void process_input(int *keys, size_t count) {
    ConcurrentQueue queue;
    init_queue(&queue);

    // Enqueue all keys
    for (size_t i = 0; i < count; ++i) {
        enqueue(&queue, keys[i]);
    }

    pthread_t threads[count];

    // Create threads to process each key and update the largest value
    for (size_t i = 0; i < count; ++i) {
        int *key = malloc(sizeof(int));
        if (!key) {
            perror("Failed to allocate memory for key");
            exit(EXIT_FAILURE);
        }

        *key = dequeue(&queue);

        pthread_create(&threads[i], NULL, find_largest, (void *)key);
    }

    // Join all threads
    for (size_t i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Largest value: %d\n", largest_value);

    // Cleanup queue
    while (queue.front != NULL) {
        dequeue(&queue);
    }
}

int main() {
    init_memory_pool(POOL_SIZE * sizeof(record) + 1000); // Example size

    pthread_mutex_init(&largest_lock, NULL);

    int keys[RECORDS];
    for (size_t i = 0; i < RECORDS; ++i) {
        printf("Enter integer %zu: ", i + 1);
        if (scanf("%d", &keys[i]) != 1 || keys[i] < 0) {
            fprintf(stderr, "Invalid input\n");
            exit(EXIT_FAILURE);
        }
    }

    record *records = create_records(RECORDS);

    process_input(keys, RECORDS);

    cleanup();
    return 0;
}
```

### Key Features:

- **Memory Pool**: A simple memory pool is implemented to manage the allocation of records and other related data. It uses a mutex for thread-safe operations.

- **Thread Safety**: Mutex locks are used to ensure that updates to shared resources (like `largest_value` and memory allocations) are thread-safe.

- **Concurrent Queue**: A queue with condition variables is implemented to manage concurrent access efficiently, reducing contention by using producer-consumer pattern.

- **Random Value Initialization**: Each record's integer field is set to a random value between 1 and 100.

- **Input Handling**: Reads integers from standard input and processes them using threads to determine the largest integer in a thread-safe manner.']

