} record;

// Thread-safe mutex for accessing shared resources
pthread_mutex_t print_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize cryptographic primitives
void init_crypto_primitives() {
    if (EVP_add_cipher(NULL, EVP_aes_256_cbc()) != 1 ||
        EVP_add_digest(NULL, EVP_sha256()) != 1 ||
        EC_KEY_set_method(EC_KEY_new_by_curve_name(NID_X9_62_prime256v1), NULL) != 1) {
        fprintf(stderr, "Error initializing cryptographic primitives\n");
        exit(EXIT_FAILURE);
    }
}

// Function to generate unique strings and random integers
void initialize_data(long *offsets, int *keys, record **records, size_t n, size_t k, const char *s, size_t m) {
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = i;
        keys[i] = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
    }

    char *base_str = strdup(s);
    *records = malloc(k * sizeof(record));
    if (!*records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    size_t chunk_size = strlen(base_str) / k;
    for (size_t i = 0; i < k; ++i) {
        (*records)[i].value = rand() % (MAX_INT - MIN_INT + 1) + MIN_INT;
        size_t start = i * chunk_size;
        size_t end = (i == k - 1) ? strlen(base_str) : start + chunk_size;
        if (end > m) end = m;

        (*records)[i].str = malloc((end - start + 1) * sizeof(char));
        if (!(*records)[i].str) {
            perror("Failed to allocate memory for record string");
            exit(EXIT_FAILURE);
        }
        strncpy((*records)[i].str, base_str + start, end - start);
        (*records)[i].str[end - start] = '\0';
    }

    free(base_str);
}

// Thread-safe function to find and print the largest integer
void *find_largest(void *arg) {
    int *numbers = (int *)arg;
    size_t count = *(size_t *)(arg + sizeof(int) * 1024); // Assuming max input of 1024 integers

    pthread_mutex_lock(&print_mutex);
    int max_num = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > max_num) {
            max_num = numbers[i];
        }
    }
    printf("Largest integer: %d\n", max_num);
    pthread_mutex_unlock(&print_mutex);

    return NULL;
}

// Function to clean up resources
void cleanup_resources(long *offsets, int *keys, record *records, size_t n, size_t k) {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < k; ++i) {
        free(records[i].str);
    }
    free(records);
}

// Main function to manage memory pool
record **manage_memory_pool(size_t n, size_t k, const char *s) {
    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));
    record *records;
    if (!offsets || !keys) {
        perror("Failed to allocate memory for offsets or keys");
        exit(EXIT_FAILURE);
    }

    initialize_data(offsets, keys, &records, n, k, s, M);

    // Example: Find the largest integer from standard input
    pthread_t thread;
    int numbers[1024];
    size_t count = 0;

    while (scanf("%d", &numbers[count]) == 1 && count < 1024) {
        ++count;
    }

    if (pthread_create(&thread, NULL, find_largest, (void *)(numbers)) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }
    pthread_join(thread, NULL);

    // Cleanup
    cleanup_resources(offsets, keys, records, n, k);

    return &records; // Return pointer to the records array
}

int main() {
    init_crypto_primitives();

    size_t n = 100;
    size_t k = 50;
    const char *s = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    record **records = manage_memory_pool(n, k, s);

    return 0;
}
