class CommandExecutor {
  constructor(maxConcurrency, pollInterval) {
    this.maxConcurrency = maxConcurrency;
    this.pollInterval = pollInterval;
    this.activeCommands = new Set();
    this.commandQueue = [];
    this.commandOutputs = {};
    this.uiElements = {};

    document.body.addEventListener('click', (event) => {
      const commandElement = event.target.closest('.command');
      if (commandElement) {
        const command = commandElement.dataset.command;
        this.executeAndDisplayCommand(command, [], maxConcurrency, pollInterval);
      }
    });
  }

  executeAndDisplayCommand(command, dependencies, maxConcurrency, pollInterval) {
    return new Promise(async (resolve, reject) => {
      if (this.activeCommands.size >= maxConcurrency) {
        this.commandQueue.push({ command, resolve, reject, dependencies });
        return;
      }

      try {
        const output = await this.runCommand(command, dependencies);
        this.displayOutput(command, output);
        resolve(output);
      } catch (error) {
        console.error(`Error executing command: ${command}`, error);
        reject(error);
      } finally {
        if (this.commandQueue.length > 0) {
          const nextTask = this.commandQueue.shift();
          this.executeAndDisplayCommand(nextTask.command, nextTask.dependencies, maxConcurrency, pollInterval)
            .then((output) => nextTask.resolve(output))
            .catch((error) => nextTask.reject(error));
        }
      }
    });
  }

  async runCommand(command, dependencies) {
    const [cmd, ...args] = command.split(' ');
    if (!dependencies.every(dep => this.checkDependencyAvailability(dep))) {
      throw new Error("Some dependencies are unavailable");
    }

    return new Promise((resolve, reject) => {
      this.activeCommands.add(command);
      const childProcess = require('child_process').exec;

      const process = childProcess(`${cmd} ${args.join(' ')}`);

      let outputBuffer = '';

      process.stdout.on('data', (data) => {
        outputBuffer += data.toString();
      });

      process.stderr.on('data', (data) => {
        console.error(`stderr: ${data}`);
      });

      process.on('close', (code) => {
        this.activeCommands.delete(command);
        if (code === 0) {
          resolve(outputBuffer);
        } else {
          reject(new Error(`Command exited with code ${code}`));
        }
      });
    });
  }

  checkDependencyAvailability(dependency) {
    // Simulated dependency check logic
    return true;
  }

  displayOutput(command, output) {
    if (!this.uiElements[command]) {
      const element = document.createElement('div');
      element.className = 'command-output';
      this.uiElements[command] = element;
      document.body.appendChild(element);
    }

    const commandElement = this.uiElements[command];
    commandElement.textContent = `${command}: ${output}`;
  }

  startPolling(command, dependencies) {
    setInterval(async () => {
      try {
        const output = await this.runCommand(command, dependencies);
        this.displayOutput(command, output);
      } catch (error) {
        console.error(`Poll error for command: ${command}`, error);
      }
    }, this.pollInterval);
  }
}

const executor = new CommandExecutor(3, 1000);

function executeAndDisplayCommand(command, maxConcurrency, pollInterval, dependencies = []) {
  return executor.executeAndDisplayCommand(command, dependencies, maxConcurrency, pollInterval)
    .then(() => {
      executor.startPolling(command, dependencies);
    })
    .catch((error) => console.error(`Final error for command: ${command}`, error));
}
