#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    float x;
    float y;
} Point;

#define FLOAT_POOL_SIZE 100
#define CHAR_POOL_SIZE 1000
#define POINT_POOL_SIZE 100

typedef struct MemoryPool {
    void *blocks;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool create_pool(size_t block_size, size_t total_blocks) {
    MemoryPool pool = {0};
    pool.block_size = block_size;
    pool.total_blocks = total_blocks;
    pool.blocks = malloc(block_size * total_blocks);
    pool.used_blocks = 0;
    pthread_mutex_init(&pool.lock, NULL);
    return pool;
}

void free_pool(MemoryPool *pool) {
    if (pool->blocks) {
        free(pool->blocks);
        pthread_mutex_destroy(&pool->lock);
    }
}

void* allocate_block(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_blocks < pool->total_blocks) {
        void *block = (char*)pool->blocks + pool->used_blocks * pool->block_size;
        pool->used_blocks++;
        pthread_mutex_unlock(&pool->lock);
        return block;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // No available blocks
}

void deallocate_block(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    if (block >= pool->blocks && block < (char*)pool->blocks + pool->total_blocks * pool->block_size) {
        char* ptr = (char*)block;
        size_t index = (ptr - (char*)pool->blocks) / pool->block_size;
        for (size_t i = index; i < pool->used_blocks - 1; i++) {
            memcpy(ptr, ptr + pool->block_size, pool->block_size);
        }
        pool->used_blocks--;
    }
    pthread_mutex_unlock(&pool->lock);
}

typedef struct DataHandler {
    double *floats;
    char **strings;
    Point *points;
    size_t num_floats;
    size_t num_strings;
    size_t num_points;
    MemoryPool float_pool;
    MemoryPool string_pool;
    MemoryPool point_pool;
} DataHandler;

DataHandler* init_data_handler(size_t max_floats, size_t max_strings, size_t max_points) {
    DataHandler *handler = malloc(sizeof(DataHandler));

    handler->float_pool = create_pool(sizeof(double), FLOAT_POOL_SIZE);
    handler->strings = (char**)malloc(max_strings * sizeof(char*));
    handler->string_pool = create_pool(sizeof(char) * 256, CHAR_POOL_SIZE); // Assume max string length of 255
    handler->points = (Point*)malloc(max_points * sizeof(Point));
    handler->point_pool = create_pool(sizeof(Point), POINT_POOL_SIZE);

    handler->num_floats = handler->num_strings = handler->num_points = 0;

    for (size_t i = 0; i < max_strings; i++) {
        size_t str_len = rand() % 255 + 1;
        char *str = allocate_block(&handler->string_pool);
        if (str) {
            for (size_t j = 0; j < str_len; j++) {
                ((char*)str)[j] = 'A' + rand() % 26;
            }
            handler->strings[i] = str;
            handler->num_strings++;
        } else {
            handler->strings[i] = NULL;
        }
    }

    return handler;
}

void free_data_handler(DataHandler *handler) {
    for (size_t i = 0; i < handler->num_strings; i++) {
        if (handler->strings[i]) {
            deallocate_block(&handler->string_pool, handler->strings[i]);
        }
    }

    free(handler->strings);
    free(handler->points);
    free_pool(&handler->float_pool);
    free_pool(&handler->string_pool);
    free_pool(&handler->point_pool);
    free(handler);
}

int main() {
    DataHandler *handler = init_data_handler(100, 100, 100);

    // Example usage
    for (size_t i = 0; i < handler->num_strings; i++) {
        if (handler->strings[i]) {
            printf("String %zu: %s\n", i, handler->strings[i]);
        }
    }

    free_data_handler(handler);
    return 0;
}
```

