```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define POOL_SIZE 1024

typedef struct {
    int id;
    char ip_address[16];
    int operational_state; // e.g., 0 for inactive, 1 for active
} Device;

typedef struct MemoryPool {
    Device *pool;
    size_t pool_size;
    size_t free_index;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (Device*)malloc(sizeof(Device) * size);
    mp->pool_size = size;
    mp->free_index = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

Device* allocate_device(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_index < mp->pool_size) {
        Device *device = &mp->pool[mp->free_index++];
        pthread_mutex_unlock(&mp->lock);
        return device;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

void deallocate_device(MemoryPool *mp, Device *device) {
    pthread_mutex_lock(&mp->lock);
    size_t index = device - mp->pool;
    if (index < mp->free_index) {
        memmove(&mp->pool[index], &mp->pool[mp->free_index++], sizeof(Device) * (mp->free_index - index - 1));
    }
    pthread_mutex_unlock(&mp->lock);
}

void* update_device_states(void *arg) {
    MemoryPool *mp = (MemoryPool*)arg;
    while (1) {
        pthread_mutex_lock(&mp->lock);
        for (size_t i = 0; i < mp->free_index; ++i) {
            // Simulate state update from an external monitoring service
            Device *device = &mp->pool[i];
            device->operational_state = rand() % 2; // Randomly set active/inactive
        }
        pthread_mutex_unlock(&mp->lock);
        sleep(5); // Adjust based on latency and reliability requirements
    }
}

int main() {
    MemoryPool *mp = create_memory_pool(POOL_SIZE);

    pthread_t updater_thread;
    if (pthread_create(&updater_thread, NULL, update_device_states, mp) != 0) {
        perror("Failed to create update thread");
        destroy_memory_pool(mp);
        return EXIT_FAILURE;
    }

    // Simulate adding devices
    for (int i = 0; i < 100; ++i) {
        Device *device = allocate_device(mp);
        if (device) {
            device->id = i;
            snprintf(device->ip_address, sizeof(device->ip_address), "192.168.1.%d", i);
            device->operational_state = rand() % 2;
        }
    }

    // Simulate program running
    sleep(20);

    destroy_memory_pool(mp);
    pthread_cancel(updater_thread);
    pthread_join(updater_thread, NULL);

    return EXIT_SUCCESS;
}
```

