#include <stdint.h>
#include <pthread.h>

#define MAX_MEASUREMENTS 100000

typedef struct {
    double sensor_data;
    uint32_t timestamp;
} measurement;

// Define a structure for the memory pool.
typedef struct {
    void* start;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
MemoryPool* initialize_memory_pool(size_t size);
void free_memory_pool(MemoryPool* pool);
measurement* allocate_measurement(MemoryPool* pool, double data, uint32_t time);
void interpolate_sensor_data(double* destination, const double* source, 
                             uint32_t start_time, uint32_t end_time, 
                             uint32_t timestamp, int method);

// Initialize a memory pool
MemoryPool* initialize_memory_pool(size_t size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->start = malloc(size);
    pool->size = size;
    pthread_mutex_init(&pool->lock, NULL);

    if (!pool->start) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Free a memory pool
void free_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->start);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

// Allocate a new measurement from the pool
measurement* allocate_measurement(MemoryPool* pool, double data, uint32_t time) {
    if (!pool || !pool->start) return NULL;

    pthread_mutex_lock(&pool->lock);

    // Calculate available size and ensure enough space for at least one measurement
    if ((uintptr_t)pool->start + sizeof(measurement) > (uintptr_t)pool->start + pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    measurement* m = (measurement*)pool->start;
    pool->start = (void*)((uintptr_t)pool->start + sizeof(measurement));

    m->sensor_data = data;
    m->timestamp = time;

    pthread_mutex_unlock(&pool->lock);
    return m;
}

// Interpolation function supporting linear, cubic, and spline
void interpolate_sensor_data(double* destination, const double* source, 
                             uint32_t start_time, uint32_t end_time, 
                             uint32_t timestamp, int method) {
    // Linear interpolation as an example (other methods can be added)
    if (method == 0 && start_time < end_time && timestamp >= start_time && timestamp <= end_time) {
        double t = (double)(timestamp - start_time) / (end_time - start_time);
        *destination = source[0] + t * (source[1] - source[0]);
    }
}

// Main function for demonstration purposes
int main() {
    MemoryPool* pool = initialize_memory_pool(MAX_MEASUREMENTS * sizeof(measurement));
    if (!pool) return EXIT_FAILURE;

    double data_source[] = {10.0, 20.0};
    uint32_t start_time = 1000;
    uint32_t end_time = 2000;
    uint32_t timestamp = 1500;

    for (int i = 0; i < MAX_MEASUREMENTS; ++i) {
        double interpolated_data;
        interpolate_sensor_data(&interpolated_data, data_source, start_time, 
                                end_time, timestamp + i, 0);

        measurement* m = allocate_measurement(pool, interpolated_data, timestamp + i);
        if (!m) break;

        printf("Measurement %d: Sensor Data = %.2f, Timestamp = %u\n", i, m->sensor_data, m->timestamp);
    }

    free_memory_pool(pool);

    return EXIT_SUCCESS;
}
