#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define CACHE_LINE_SIZE 64
#define MAX_THREADS 10000
#define K_MAX 1000
#define N_MAX 1000
#define M 50

typedef struct {
    int value;
    char *str;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    pthread_mutex_t lock;
} DataStructure;

// Memory pool for custom allocation
static void* memory_pool = NULL;
static size_t pool_size = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (!memory_pool || pool_size < size) {
        free(memory_pool);
        memory_pool = malloc(size);
        pool_size = size;
    }
    pthread_mutex_unlock(&pool_lock);
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    void *ptr = memory_pool;
    memory_pool = (char*)memory_pool + size;
    pool_size -= size;
    if (pool_size < 0) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

DataStructure* create_data_structure(size_t n, size_t k) {
    DataStructure *ds = allocate_from_pool(sizeof(DataStructure));
    ds->offsets = allocate_from_pool(n * sizeof(long));
    ds->keys = allocate_from_pool(n * sizeof(int));
    ds->records = allocate_from_pool(k * sizeof(record*));

    pthread_mutex_init(&ds->lock, NULL);

    for (size_t i = 0; i < n; ++i) {
        ds->offsets[i] = i * CACHE_LINE_SIZE;
        ds->keys[i] = rand() % 1000000;
    }

    char predefined_string[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    srand(time(NULL));

    for (size_t i = 0; i < k; ++i) {
        record *rec = allocate_from_pool(sizeof(record));
        rec->value = rand() % 10000;
        size_t start_idx = rand() % (sizeof(predefined_string) - M);
        rec->str = allocate_from_pool(M + 1);
        strncpy(rec->str, &predefined_string[start_idx], M);
        rec->str[M] = '\0';
        ds->records[i] = rec;
    }

    return ds;
}

void update_record(DataStructure *ds, size_t index, int new_value, const char* new_str) {
    pthread_mutex_lock(&ds->lock);
    if (index < (size_t)(-1 >> 1)) { // Check for valid index
        ds->records[index]->value = new_value;
        strncpy(ds->records[index]->str, new_str, M);
        ds->records[index]->str[M] = '\0';
    }
    pthread_mutex_unlock(&ds->lock);
}

void print_max_int() {
    int max_int = INT_MIN;
    int num;
    while (scanf("%d", &num) == 1) {
        if (num > max_int) {
            max_int = num;
        }
    }
    printf("Maximum integer: %d\n", max_int);
}

void cleanup_data_structure(DataStructure *ds, size_t k) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < k; ++i) {
        free(ds->records[i]->str);
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int main() {
    initialize_memory_pool(1024 * 1024); // Initialize a 1MB pool

    DataStructure *ds = create_data_structure(N_MAX, K_MAX);

    update_record(ds, 0, 12345, "NewString");

    print_max_int();

    cleanup_data_structure(ds, K_MAX);

    return 0;
}
```

This code provides a basic implementation of the described requirements. It includes a custom memory pool for efficient allocation and minimizes fragmentation by using a single block of memory. The `DataStructure` is thread-safe with mutex locks, allowing concurrent updates without locking the entire structure. Memory cleanup ensures no leaks, and the example demonstrates how to integrate new records and retrieve maximum integers safely.']

