#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    SUCCESS = 0,
    ALLOCATION_ERROR = 1,
    KEY_ALLOCATION_ERROR = 2,
    RECORD_ALLOCATION_ERROR = 3,
} ErrorCode;

typedef struct {
    int *value;
    unsigned int idx;
} Record;

typedef struct CacheNode {
    void *memory;
    size_t size;
    struct CacheNode *next, *prev;
} CacheNode;

typedef struct {
    CacheNode *head, *tail;
    size_t max_size;
    pthread_mutex_t lock;
} LRUCache;

static void log_error(const char *operation, size_t requested_size) {
    fprintf(stderr, "Error: Failed to allocate %zu bytes for operation '%s'.\n", requested_size, operation);
}

ErrorCode get_from_cache(LRUCache *cache, size_t size, void **memory) {
    if (cache->head == NULL) return ALLOCATION_ERROR;

    CacheNode *node = cache->head;
    while (node != NULL && node->size != size) {
        node = node->next;
    }

    if (node == NULL) return ALLOCATION_ERROR;

    *memory = node->memory;
    if (cache->head == node) {
        cache->head = node->next;
    } else {
        node->prev->next = node->next;
        if (node->next != NULL) node->next->prev = node->prev;
    }

    node->next = cache->tail;
    node->prev = NULL;

    if (cache->tail != NULL) {
        cache->tail->next = node;
    }
    cache->tail = node;

    return SUCCESS;
}

ErrorCode put_to_cache(LRUCache *cache, void *memory, size_t size) {
    pthread_mutex_lock(&cache->lock);

    CacheNode *node = malloc(sizeof(CacheNode));
    if (node == NULL) {
        pthread_mutex_unlock(&cache->lock);
        log_error("Cache node", sizeof(CacheNode));
        return ALLOCATION_ERROR;
    }

    node->memory = memory;
    node->size = size;

    if (cache->tail != NULL) {
        cache->tail->next = node;
        node->prev = cache->tail;
    } else {
        cache->head = node;
    }
    cache->tail = node;
    node->next = NULL;

    // Simple eviction strategy: evict the least recently used
    if (cache->max_size < size) { // Assuming max_size is total memory in bytes, this would need refinement.
        CacheNode *evict_node = cache->head;
        while (evict_node != NULL && evict_node->next != NULL) {
            evict_node = evict_node->next;
        }
        free(evict_node->memory);
        if (cache->head == evict_node) {
            cache->head = evict_node->next;
        } else {
            evict_node->prev->next = evict_node->next;
        }
        free(evict_node);
    }

    pthread_mutex_unlock(&cache->lock);
    return SUCCESS;
}

ErrorCode allocate_records(size_t max_offsets, size_t max_keys, size_t max_records, int check_bounds) {
    long *offsets = NULL;
    int *keys = NULL;
    Record *records = NULL;

    // Initialize LRU cache
    LRUCache cache = {NULL, NULL, 1024 * 1024, PTHREAD_MUTEX_INITIALIZER}; // Example size of 1MB

    ErrorCode status = SUCCESS;

    if (check_bounds && max_offsets == 0) return ALLOCATION_ERROR;
    offsets = malloc(max_offsets * sizeof(long));
    if (!offsets) {
        log_error("Offsets", max_offsets * sizeof(long));
        return ALLOCATION_ERROR;
    }
    memset(offsets, 0, max_offsets * sizeof(long));

    if (check_bounds && max_keys == 0) {
        free(offsets);
        return KEY_ALLOCATION_ERROR;
    }
    keys = malloc(max_keys * sizeof(int));
    if (!keys) {
        log_error("Keys", max_keys * sizeof(int));
        free(offsets);
        return KEY_ALLOCATION_ERROR;
    }
    for (size_t i = 0; i < max_keys; ++i) {
        keys[i] = (int)i;
    }

    if (check_bounds && max_records == 0) {
        free(keys);
        free(offsets);
        return RECORD_ALLOCATION_ERROR;
    }

    // Cache management: Try to get records from cache first
    void *cached_memory = NULL;
    size_t record_size = sizeof(Record) + sizeof(int);
    if (get_from_cache(&cache, max_records * record_size, &cached_memory) == SUCCESS) {
        records = cached_memory;
    } else {
        records = malloc(max_records * record_size);
        if (!records) {
            log_error("Records", max_records * record_size);
            free(keys);
            free(offsets);
            return RECORD_ALLOCATION_ERROR;
        }
    }

    for (size_t i = 0; i < max_records; ++i) {
        records[i].value = (int *)(records + i) + 1; // Pointer arithmetic to point right after the structure
        *records[i].value = rand() % 1001;
        records[i].idx = (unsigned int)i % max_keys; // Ensuring idx is within bounds of keys array
    }

    put_to_cache(&cache, records, max_records * record_size);

    // Normally you'd return the pointers or some status object
    printf("Allocation successful.\n");

    return status;
}

int main() {
    srand(time(NULL)); // Initialize random number generator
    ErrorCode result = allocate_records(10, 5, 3, 1);
    if (result != SUCCESS) {
        fprintf(stderr, "Failed to allocate records with error code: %d\n", result);
    }
    return 0;
}
