typedef struct {
    time_t timestamp;
    char *payload;
    double probability;
    char *status_message;
} data_entry;

#define NUM_ENTRIES 1000

void manage_memory_allocation(long *offsets, int *keys, data_entry *entries, 
                              double *probabilities, char **status_messages,
                              size_t max_payload_size, double min_probability) {

    // Allocate memory
    offsets = (long *)malloc(NUM_ENTRIES * sizeof(long));
    keys = (int *)malloc(NUM_ENTRIES * sizeof(int));
    probabilities = (double *)malloc(NUM_ENTRIES * sizeof(double));
    status_messages = (char **)malloc(NUM_ENTRIES * sizeof(char *));

    for (size_t i = 0; i < NUM_ENTRIES; ++i) {
        offsets[i] = i;
        keys[i] = (int)i;

        // Initialize data_entry
        entries[i].timestamp = time(NULL);

        char payload[32];
        snprintf(payload, sizeof(payload), "ID_%zu", i);
        size_t payload_length = strlen(payload) < max_payload_size ? strlen(payload) : max_payload_size - 1;
        entries[i].payload = (char *)malloc(payload_length + 1);
        strncpy(entries[i].payload, payload, payload_length);
        entries[i].payload[payload_length] = '\0';

        // Generate random probability
        double prob = ((double)rand() / RAND_MAX);
        entries[i].probability = prob < min_probability ? min_probability : prob;

        status_messages[i] = (char *)malloc(20 * sizeof(char));
        snprintf(status_messages[i], 20, "Success_%zu", i);
    }
}

void free_resources(long *offsets, int *keys, data_entry *entries,
                    double *probabilities, char **status_messages) {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < NUM_ENTRIES; ++i) {
        free(entries[i].payload);
        free(status_messages[i]);
    }
    free(probabilities);
    free(status_messages);
}

int main() {
    size_t max_payload_size = 50;
    double min_probability = 0.1;

    long *offsets = NULL;
    int *keys = NULL;
    data_entry *entries = (data_entry *)malloc(NUM_ENTRIES * sizeof(data_entry));
    double *probabilities = NULL;
    char **status_messages = NULL;

    manage_memory_allocation(offsets, keys, entries, probabilities, status_messages,
                             max_payload_size, min_probability);

    // Example usage
    printf("First entry: %s\n", entries[0].payload);

    free_resources(offsets, keys, entries, probabilities, status_messages);
    free(entries);

    return 0;
}
