#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    float floatValue;
    int intValue;
    bool boolValue;
} item_t;

typedef struct {
    double *numbers;
    size_t num_count;
} numbers_t;

typedef struct {
    char **strings;
    size_t str_count;
} strings_t;

typedef struct {
    item_t *items;
    size_t item_count;
} items_t;

typedef struct hash_node {
    char key[129];
    item_t value;
    struct hash_node *next;
} hash_node_t;

typedef struct {
    hash_node_t **buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} hashtable_t;

unsigned long hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash;
}

void initialize_hashtable(hashtable_t *table, size_t capacity) {
    table->buckets = calloc(capacity, sizeof(hash_node_t *));
    if (!table->buckets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    table->capacity = capacity;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
}

void resize_hashtable(hashtable_t *table);

hash_node_t* create_hash_node(const char *key, item_t value) {
    hash_node_t *node = malloc(sizeof(hash_node_t));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    strncpy(node->key, key, 128);
    node->value = value;
    node->next = NULL;
    return node;
}

void insert_into_hashtable(hashtable_t *table, const char *key, item_t value) {
    pthread_mutex_lock(&table->lock);

    unsigned long index = hash_function(key) % table->capacity;
    hash_node_t *node = create_hash_node(key, value);

    if (table->buckets[index]) {
        node->next = table->buckets[index];
    }
    table->buckets[index] = node;
    table->count++;

    if ((float)table->count / table->capacity > 0.75) {
        resize_hashtable(table);
    }

    pthread_mutex_unlock(&table->lock);
}

item_t* retrieve_from_hashtable(hashtable_t *table, const char *key) {
    unsigned long index = hash_function(key) % table->capacity;
    hash_node_t *node = table->buckets[index];

    while (node) {
        if (strncmp(node->key, key, 128) == 0) {
            return &node->value;
        }
        node = node->next;
    }

    return NULL; // Key not found
}

void resize_hashtable(hashtable_t *table) {
    size_t new_capacity = table->capacity * 2;
    hash_node_t **new_buckets = calloc(new_capacity, sizeof(hash_node_t *));
    if (!new_buckets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        hash_node_t *node = table->buckets[i];
        while (node) {
            unsigned long new_index = hash_function(node->key) % new_capacity;
            hash_node_t *next_node = node->next;

            node->next = new_buckets[new_index];
            new_buckets[new_index] = node;

            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void free_hashtable(hashtable_t *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        hash_node_t *node = table->buckets[i];
        while (node) {
            hash_node_t *next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
}

int main() {
    hashtable_t table;
    initialize_hashtable(&table, 16);

    item_t item1 = {3.14f, 42, true};
    insert_into_hashtable(&table, "exampleKey", item1);

    item_t *retrieved_item = retrieve_from_hashtable(&table, "exampleKey");
    if (retrieved_item) {
        printf("Retrieved: %f, %d, %s\n", retrieved_item->floatValue,
               retrieved_item->intValue, retrieved_item->boolValue ? "true" : "false");
    }

    free_hashtable(&table);
    return 0;
}
```

This code includes a hash table with dynamic resizing and thread safety using mutex locks. It handles memory allocation failures gracefully and provides functions to insert and retrieve items based on string keys.']

