typedef struct node {
    unsigned long *timestamp;
    char name[256];
    int status;
    struct node *next;
} node;

typedef struct {
    node *head;
    pthread_mutex_t lock;
} linked_list;

node* allocate_node(const char *name, int status) {
    node *new_node = (node *)malloc(sizeof(node));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failed for node of size %zu\n", sizeof(node));
        return NULL;
    }
    new_node->timestamp = (unsigned long *)malloc(sizeof(unsigned long));
    if (!new_node->timestamp) {
        fprintf(stderr, "Error: Memory allocation failed for timestamp of size %zu\n", sizeof(unsigned long));
        free(new_node);
        return NULL;
    }
    *new_node->timestamp = time(NULL);
    strncpy(new_node->name, name, 255);
    new_node->name[255] = '\0';
    new_node->status = status;
    new_node->next = NULL;
    return new_node;
}

int add_node(linked_list *list, const char *name, int status) {
    pthread_mutex_lock(&list->lock);
    node *new_node = allocate_node(name, status);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Allocation failed
    }
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_node(linked_list *list, const char *name) {
    pthread_mutex_lock(&list->lock);
    node **indirect = &list->head;
    while (*indirect) {
        if (strcmp((*indirect)->name, name) == 0) {
            node *to_free = *indirect;
            *indirect = to_free->next;
            free(to_free->timestamp);
            free(to_free);
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        indirect = &(*indirect)->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Node not found
}

int init_linked_list(linked_list *list, int check_bounds) {
    list->head = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialization failed\n");
        return -1;
    }
    return 0; // Success
}

int cleanup_linked_list(linked_list *list) {
    pthread_mutex_lock(&list->lock);
    node *current = list->head;
    while (current) {
        node *next = current->next;
        free(current->timestamp);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    return 0; // Success
}

void iterate_and_transform(linked_list *list, int (*transform)(int)) {
    pthread_mutex_lock(&list->lock);
    node *current = list->head;
    while (current) {
        current->status = transform(current->status);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

node* init_node_array(size_t max_nodes, int reference_value, int check_bounds) {
    if (!max_nodes) return NULL;

    node *array = (node *)malloc(max_nodes * sizeof(node));
    if (!array) {
        fprintf(stderr, "Error: Memory allocation failed for node array of size %zu\n", max_nodes * sizeof(node));
        return NULL;
    }

    time_t current_time = time(NULL);
    for (size_t i = 0; i < max_nodes; ++i) {
        array[i].timestamp = &current_time;
        sprintf(array[i].name, "Resource_%zu", i);
        array[i].status = (current_time % reference_value == 0) ? 2 : (current_time % reference_value == 1) ? 1 : 0;
        array[i].next = NULL; // Not used in array
    }
    return array;
}

int free_node_array(node *array, size_t max_nodes) {
    if (!array) return -1;

    free(array);
    return 0; // Success
