#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a record structure
typedef struct {
    int *value;
    unsigned int idx; // index into keys array
} record;

// Cache entry for LRU cache management
typedef struct CacheEntry {
    void *data;
    size_t size;
    struct CacheEntry *prev, *next;
} CacheEntry;

// Cache structure with head and tail pointers for LRU eviction
typedef struct {
    CacheEntry *head, *tail;
    size_t capacity;
    size_t current_size;
    pthread_mutex_t lock;
} LRUCache;

// Function to log messages
void log_message(const char *message) {
    printf("%s\n", message);
}

// Allocate and initialize an LRU cache
LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = (LRUCache *)malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->head = cache->tail = NULL;
    cache->capacity = capacity;
    cache->current_size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Add entry to LRU cache
void add_to_cache(LRUCache *cache, CacheEntry *entry) {
    pthread_mutex_lock(&cache->lock);

    if (cache->head == NULL) {
        cache->head = cache->tail = entry;
    } else {
        cache->head->prev = entry;
        entry->next = cache->head;
        cache->head = entry;
    }
    cache->current_size++;
    pthread_mutex_unlock(&cache->lock);
}

// Remove least recently used item from cache
void* evict_from_cache(LRUCache *cache) {
    pthread_mutex_lock(&cache->lock);

    void *data = NULL;
    if (cache->tail != NULL) {
        CacheEntry *entry_to_evict = cache->tail;

        if (cache->head == cache->tail) { // Only one element
            cache->head = cache->tail = NULL;
        } else {
            cache->tail = entry_to_evict->prev;
            cache->tail->next = NULL;
        }

        data = entry_to_evict->data;
        free(entry_to_evict);
        cache->current_size--;
    }

    pthread_mutex_unlock(&cache->lock);
    return data;
}

// Check and evict if necessary to make space
void ensure_cache_capacity(LRUCache *cache, size_t size_needed) {
    while (cache->current_size >= cache->capacity && cache->tail != NULL) {
        void *evicted_data = evict_from_cache(cache);
        free(evicted_data); // Assuming all data is malloc'd
    }
}

// Function to allocate and initialize records with constraints
int allocate_records(size_t max_offsets, size_t max_keys, size_t max_records,
                     int check_bounds, size_t cache_capacity) {

    if (check_bounds && (max_offsets == 0 || max_keys == 0 || max_records == 0)) {
        log_message("Error: Sizes must be greater than zero.");
        return -1;
    }

    // Allocate offsets
    long *offsets = (long *)calloc(max_offsets, sizeof(long));
    if (!offsets) {
        log_message("Failed to allocate memory for offsets");
        return -1;
    }

    // Allocate keys
    int *keys = (int *)malloc(max_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        log_message("Failed to allocate memory for keys");
        return -1;
    }

    for (size_t i = 0; i < max_keys; ++i)
        keys[i] = (int)i;

    // Define a record structure containing value pointer and index
    record *records = (record *)malloc(max_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        log_message("Failed to allocate memory for records");
        return -1;
    }

    LRUCache *cache = create_cache(cache_capacity);
    if (!cache) {
        free(offsets);
        free(keys);
        free(records);
        log_message("Failed to create cache");
        return -1;
    }

    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < max_records; ++i) {
        CacheEntry *entry = (CacheEntry *)malloc(sizeof(CacheEntry));
        if (!entry) {
            free(offsets);
            free(keys);
            free(records);
            pthread_mutex_destroy(&cache->lock);
            free(cache);
            log_message("Failed to allocate cache entry");
            return -1;
        }

        int *value = (int *)calloc(1, sizeof(int));
        if (!value) {
            free(entry);
            free(offsets);
            free(keys);
            free(records);
            pthread_mutex_destroy(&cache->lock);
            free(cache);
            log_message("Failed to allocate memory for record value");
            return -1;
        }

        *value = rand() % 1001; // Random int between 0 and 1000

        records[i].value = value;
        records[i].idx = (unsigned int)(rand() % max_keys);

        entry->data = records[i].value;
        entry->size = sizeof(int);

        ensure_cache_capacity(cache, sizeof(record));
        add_to_cache(cache, entry); // Add new record to cache
    }

    log_message("Memory allocation and initialization completed successfully.");

    return 0; // Success
}

// Note: For actual usage in a multithreaded environment, you will need to protect shared resources with appropriate mutex locks.
