#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ARRAY_SIZE 1024
#define RANDOM_RANGE_MAX 1000
#define LOG_FILE "error_log.txt"
#define RECORD_SIZE sizeof(struct record)
#define CACHE_LINE_SIZE 64

typedef struct {
    int value;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void log_error(const char *message) {
    pthread_mutex_lock(&mutex);
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) return;
    }
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&mutex);
}

int init_log() {
    pthread_mutex_lock(&mutex);
    if (!log_file) {
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) return -1;
    }
    pthread_mutex_unlock(&mutex);
    return 0;
}

void clean_up(void *offsets, void *keys, record *records, size_t records_size) {
    free(offsets);
    free(keys);
    free(records);
}

size_t get_padded_size(size_t size) {
    return ((size + CACHE_LINE_SIZE - 1) / CACHE_LINE_SIZE) * CACHE_LINE_SIZE;
}

void process_data_pipeline(size_t array_size) {
    if (init_log() != 0) return;

    pthread_mutex_lock(&mutex);

    size_t padded_size = get_padded_size(array_size);
    size_t actual_size = array_size < MAX_ARRAY_SIZE ? array_size : MAX_ARRAY_SIZE;
    long *offsets = (long *)calloc(padded_size, sizeof(long));
    int *keys = (int *)calloc(padded_size, sizeof(int));

    if (!offsets || !keys) {
        log_error("Memory allocation failed for offsets or keys.");
        pthread_mutex_unlock(&mutex);
        return;
    }

    size_t min_used_size = actual_size;

    record *records = (record *)malloc(min_used_size * RECORD_SIZE);

    if (!records) {
        log_error("Memory allocation failed for records.");
        clean_up(offsets, keys, NULL, 0);
        pthread_mutex_unlock(&mutex);
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < min_used_size; ++i) {
        records[i].value = rand() % RANDOM_RANGE_MAX;
    }

    record *expanded_records = realloc(records, padded_size * RECORD_SIZE);

    if (!expanded_records) {
        log_error("Memory allocation failed for expanded records.");
        clean_up(offsets, keys, records, min_used_size);
        pthread_mutex_unlock(&mutex);
        return;
    }
    records = expanded_records;

    // Simulate data processing operation
    memcpy(records, records, padded_size * RECORD_SIZE);

    clean_up(offsets, keys, records, padded_size);
    pthread_mutex_unlock(&mutex);
}

int main() {
    process_data_pipeline(512);  // Example usage
    return 0;
}
```

### Key Highlights:
- **Memory Management**: The function uses `calloc` and `realloc` to handle dynamic memory allocation with error checking.
- **Error Handling**: Errors are logged using a mutex-protected logging mechanism for thread safety.
- **Cache Optimization**: Arrays are padded to the nearest cache line size.
- **Thread Safety**: Mutexes ensure thread-safe access during initialization and cleanup operations.
- **Extensibility**: The code is structured in such a way that new fields or functionalities can be added with minimal disruption.']

