#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_ARRAY_SIZE 1000

typedef struct {
    int value;
} Record;

typedef struct MemoryPool {
    size_t element_size;
    void *buffer;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t element_size, size_t capacity) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->capacity = capacity;
    pool->used = 0;

    pthread_mutex_init(&pool->lock, NULL);
    pool->buffer = malloc(element_size * capacity);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }

    void *ptr = ((char*)pool->buffer) + (pool->element_size * pool->used++);
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void free_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->buffer);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int generate_random_int(int min, int max) {
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;
    static unsigned int seed;

    void init_seed() {
        seed = (unsigned int)time(NULL);
    }

    pthread_once(&once_control, init_seed);
    return rand_r(&seed) % (max - min + 1) + min;
}

void handle_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (!log_file) return;

    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}

void process_arrays(size_t long_size, size_t int_size) {
    if (long_size > MAX_ARRAY_SIZE || int_size > MAX_ARRAY_SIZE) {
        handle_error("Array sizes exceed maximum limit");
        return;
    }

    MemoryPool *pool = create_memory_pool(sizeof(Record), (size_t)(long_size < int_size ? long_size : int_size));
    if (!pool) {
        handle_error("Memory pool creation failed");
        return;
    }

    Record *records = (Record*)malloc(long_size * sizeof(Record));
    if (!records) {
        free_memory_pool(pool);
        handle_error("Records array allocation failed");
        return;
    }

    for (size_t i = 0; i < long_size && i < int_size; ++i) {
        Record *record = allocate_from_pool(pool);
        if (!record) break;

        records[i].value = generate_random_int(1, 100);
    }

    size_t min_size = long_size < int_size ? long_size : int_size;
    Record *processed_records = (Record*)malloc(min_size * sizeof(Record));
    if (!processed_records) {
        free(records);
        free_memory_pool(pool);
        handle_error("Processed records array allocation failed");
        return;
    }

    memcpy(processed_records, records, min_size * sizeof(Record));

    // Simulate further processing
    // Integration with external library would go here

    free(records);
    free(processed_records);
    free_memory_pool(pool);
}

int main() {
    size_t long_size = 500; // Example input
    size_t int_size = 300;  // Example input

    process_arrays(long_size, int_size);

    return 0;
}
