#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256

typedef struct {
    char *key;
    char *content;
} Script;

typedef struct Node {
    Script script;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} ScriptCollection;

typedef struct {
    int *data;
    size_t size;
} Dataset;

typedef struct {
    ScriptCollection *scripts;
    pthread_mutex_t scripts_lock;
    size_t capacity;
    size_t count;
    void **pool;
} MemoryPool;

void initialize_pool(MemoryPool *mp, size_t initial_capacity) {
    mp->capacity = initial_capacity;
    mp->count = 0;
    mp->pool = malloc(mp->capacity * sizeof(void *));
    pthread_mutex_init(&mp->scripts_lock, NULL);
}

void* pool_alloc(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->scripts_lock);

    void *ptr = NULL;
    if (mp->count < mp->capacity) {
        ptr = malloc(size);
        mp->pool[mp->count++] = ptr;
    }

    pthread_mutex_unlock(&mp->scripts_lock);
    return ptr;
}

void pool_free(MemoryPool *mp, void *ptr) {
    for (size_t i = 0; i < mp->count; ++i) {
        if (mp->pool[i] == ptr) {
            free(ptr);
            memmove(&mp->pool[i], &mp->pool[i + 1], (mp->count - i - 1) * sizeof(void *));
            --mp->count;
            break;
        }
    }
}

void add_script(ScriptCollection *collection, Script script) {
    Node *new_node = pool_alloc(collection->scripts, sizeof(Node));
    if (!new_node) return;

    new_node->script = script;
    pthread_mutex_lock(&collection->lock);
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_mutex_unlock(&collection->lock);
}

void render_scripts(const ScriptCollection *collection, FILE *output) {
    pthread_mutex_lock(&collection->lock);

    Node *current = collection->head;
    while (current) {
        fprintf(output, "<script>%s</script>\n", current->script.content);
        current = current->next;
    }

    pthread_mutex_unlock(&collection->lock);
}

void initialize_collection(ScriptCollection *collection, MemoryPool *pool) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->scripts = pool;
}

int find_max_in_dataset(const Dataset *dataset) {
    int max_value = INT_MIN;
    for (size_t i = 0; i < dataset->size; ++i) {
        if (dataset->data[i] > max_value)
            max_value = dataset->data[i];
    }
    return max_value;
}

void process_input_stream(FILE *input, ScriptCollection *collection, MemoryPool *pool) {
    char line[1024];
    while (fgets(line, sizeof(line), input)) {
        Dataset dataset;
        int value;

        dataset.data = malloc(sizeof(int)); // Initial allocation
        dataset.size = 0;

        char *token = strtok(line, " \t\n");
        while (token) {
            value = atoi(token);
            if (dataset.size % 10 == 0) { // Reallocate every 10 elements to minimize frequent allocations
                dataset.data = realloc(dataset.data, sizeof(int) * (dataset.size + 10));
            }
            dataset.data[dataset.size++] = value;
            token = strtok(NULL, " \t\n");
        }

        int max_value = find_max_in_dataset(&dataset);
        char content[128];
        snprintf(content, sizeof(content), "Max: %d", max_value);

        Script script;
        script.key = pool_alloc(pool, MAX_KEY_LENGTH * sizeof(char));
        snprintf(script.key, MAX_KEY_LENGTH, "script_%lu", (unsigned long)pthread_self());
        script.content = pool_alloc(pool, strlen(content) + 1);
        strcpy(script.content, content);

        add_script(collection, script);

        free(dataset.data);
    }
}

void merge_results(ScriptCollection *collection, FILE *output) {
    render_scripts(collection, output);
}

int main() {
    ScriptCollection collection;
    MemoryPool pool;

    initialize_pool(&pool, 1000); // Initial capacity of memory pool
    initialize_collection(&collection, &pool);

    pthread_t threads[4];
    FILE *inputs[] = { stdin, fopen("input1.txt", "r"), fopen("input2.txt", "r"), NULL };

    for (int i = 0; inputs[i] != NULL; ++i) {
        if (pthread_create(&threads[i], NULL, 
            (void *(*)(void *))process_input_stream, (void *)(inputs[i])) != 0) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    for (int i = 0; i < 4 && threads[i] != 0; ++i) {
        pthread_join(threads[i], NULL);
    }

    merge_results(&collection, stdout);

    // Cleanup
    Node *current = collection.head;
    while (current) {
        Node *next = current->next;
        pool_free(pool, current->script.key);
        pool_free(pool, current->script.content);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&collection.lock);
    free(pool.pool);

    for (int i = 0; inputs[i] != NULL && inputs[i] != stdin; ++i) {
        fclose(inputs[i]);
    }

    return 0;
}
```

