['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    int *value;
} Node;

typedef struct Bucket {
    Node **nodes;
    size_t count;
    pthread_mutex_t lock;
} Bucket;

// Function to initialize a bucket with memory allocation
Bucket* create_bucket(size_t initial_size) {
    Bucket *bucket = malloc(sizeof(Bucket));
    if (!bucket) return NULL;

    bucket->nodes = calloc(initial_size, sizeof(Node *));
    if (!bucket->nodes) {
        free(bucket);
        return NULL;
    }

    bucket->count = 0;
    pthread_mutex_init(&bucket->lock, NULL);

    return bucket;
}

// Function to add a node to the bucket
int add_node_to_bucket(Bucket *bucket, int value) {
    if (!bucket || bucket->nodes == NULL) return -1;

    pthread_mutex_lock(&bucket->lock);

    if (bucket->count >= (size_t)(sizeof(bucket->nodes) / sizeof(Node *))) {
        size_t new_size = bucket->count ? 2 * bucket->count : 4;
        Node **new_nodes = realloc(bucket->nodes, new_size * sizeof(Node *));
        if (!new_nodes) {
            pthread_mutex_unlock(&bucket->lock);
            return -1; // Out of memory
        }
        bucket->nodes = new_nodes;
    }

    Node *node = malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_unlock(&bucket->lock);
        return -1; // Out of memory
    }

    node->value = malloc(sizeof(int));
    if (!node->value) {
        free(node);
        pthread_mutex_unlock(&bucket->lock);
        return -1; // Out of memory
    }

    *node->value = value;
    bucket->nodes[bucket->count++] = node;

    pthread_mutex_unlock(&bucket->lock);

    return 0;
}

// Function to remove a node from the bucket by index
int remove_node_from_bucket(Bucket *bucket, size_t index) {
    if (!bucket || bucket->nodes == NULL || index >= bucket->count) return -1;

    pthread_mutex_lock(&bucket->lock);

    Node *node = bucket->nodes[index];
    if (node) {
        free(node->value);
        free(node);

        memmove(&bucket->nodes[index], &bucket->nodes[index + 1],
                (bucket->count - index - 1) * sizeof(Node *));
        bucket->count--;
    }

    pthread_mutex_unlock(&bucket->lock);

    return 0;
}

// Function to free all resources of a bucket
void destroy_bucket(Bucket *bucket) {
    if (!bucket) return;

    pthread_mutex_lock(&bucket->lock);

    for (size_t i = 0; i < bucket->count; ++i) {
        Node *node = bucket->nodes[i];
        if (node) {
            free(node->value);
            free(node);
        }
    }

    free(bucket->nodes);
    pthread_mutex_unlock(&bucket->lock);

    pthread_mutex_destroy(&bucket->lock);
    free(bucket);
}

// Example usage of the function
int main() {
    Bucket *bucket = create_bucket(2); // Initial size is arbitrary

    if (!bucket) return -1;

    add_node_to_bucket(bucket, 10);
    add_node_to_bucket(bucket, 20);

    remove_node_from_bucket(bucket, 0);

    destroy_bucket(bucket);

    return 0;
}
```

This code provides a robust implementation to manage memory for nodes and buckets in a distributed data processing system. It handles dynamic scaling, memory allocation, deallocation, and concurrency using mutex locks for synchronization. Edge cases such as out-of-memory conditions are managed gracefully.']

