#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SENSORS 10000

typedef struct {
    double temperature;
    double humidity;
    double pressure;
} SensorReadings;

typedef struct {
    SensorReadings readings;
    double timestamp; // Measurement time
} sensor_data;

// Mutex for thread-safe memory allocation and deallocation
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

sensor_data* initialize_sensor_array(int num_sensors) {
    if (num_sensors <= 0 || num_sensors > MAX_SENSORS) {
        fprintf(stderr, "Invalid number of sensors requested.\n");
        return NULL;
    }

    // Lock the mutex for thread-safe operation
    pthread_mutex_lock(&mutex);

    // Allocate memory for the array of sensor_data structures
    sensor_data* sensor_array = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));

    if (!sensor_array) {
        fprintf(stderr, "Memory allocation failed.\n");

        // Unlock before returning NULL due to failure
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize each sensor's data fields
    for (int i = 0; i < num_sensors; ++i) {
        sensor_array[i].readings.temperature = 0.0;
        sensor_array[i].readings.humidity = 0.0;
        sensor_array[i].readings.pressure = 0.0;
        sensor_array[i].timestamp = 0.0;
    }

    // Unlock the mutex after allocation and initialization
    pthread_mutex_unlock(&mutex);

    return sensor_array;
}

void free_sensor_array(sensor_data* sensor_array) {
    if (!sensor_array) return;

    // Lock the mutex for thread-safe deallocation
    pthread_mutex_lock(&mutex);

    free(sensor_array);

    // Unlock the mutex after freeing memory
    pthread_mutex_unlock(&mutex);
}

