['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ERROR_CODE -1

typedef struct {
    int value;
} record;

void log_error(const char* message) {
    FILE *file = fopen("error_log.txt", "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
}

int initialize_data(long n_offsets, long n_keys, int min_value, int max_value) {
    long i;
    unsigned int num_failures = 0;

    // Allocate memory for offsets and keys
    long *offsets = (long *)malloc(n_offsets * sizeof(long));
    int *keys = (int *)malloc(n_keys * sizeof(int));

    if (!offsets || !keys) {
        log_error("Memory allocation failed for offsets or keys.");
        num_failures++;
        free(offsets);
        free(keys);
        return ERROR_CODE;
    }

    // Allocate memory for records
    record *records = (record *)malloc(n_keys * sizeof(record));
    if (!records) {
        log_error("Memory allocation failed for records.");
        num_failures++;
        free(offsets);
        free(keys);
        return ERROR_CODE;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Initialize offsets and keys
    for (i = 0; i < n_offsets; i++) {
        offsets[i] = rand() % n_keys;  // Random offset value within the range of n_keys
    }
    for (i = 0; i < n_keys; i++) {
        keys[i] = min_value + rand() % (max_value - min_value + 1);  // Random key value within specified range
    }

    // Initialize records with random values
    for (i = 0; i < n_keys; i++) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    // Copy keys to corresponding record positions based on offsets
    for (i = 0; i < n_offsets && i < n_keys; i++) {  // Ensure bounds are respected
        if (offsets[i] >= 0 && offsets[i] < n_keys) {
            records[offsets[i]].value = keys[i];
        }
    }

    // Free allocated memory to prevent leaks
    free(offsets);
    free(keys);
    free(records);

    return num_failures;
}

int main() {
    int min_value = 10, max_value = 100;
    long n_offsets = 1000000, n_keys = 1000000;

    int result = initialize_data(n_offsets, n_keys, min_value, max_value);
    if (result == ERROR_CODE) {
        printf("An error occurred during initialization.\n");
    } else {
        printf("Initialization completed with %d memory allocation failures.\n", result);
    }

    return 0;
}
```

This C code defines a function `initialize_data` that allocates and initializes arrays for offsets, keys, and records. It ensures graceful handling of memory allocation failures by logging errors and returning an error code if any allocations fail. The function uses random values within specified ranges to initialize the keys and record structures efficiently. Finally, it frees all allocated resources to prevent memory leaks.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure to hold environmental measurements
typedef struct {
    float co2_concentration;  // CO2 concentration (float)
    float noise_level;        // Noise level (float)
} EnvironmentalMeasurement;

// Structure to hold sensor data with multiple readings
typedef struct {
    double temperature;
    double pressure;
    EnvironmentalMeasurement env_measurement;
} SensorData;

// Shared data structure for managing sensor data
typedef struct {
    size_t count;
    size_t capacity;
    SensorData *data;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} SensorDataManager;

// Function to initialize the sensor data manager
void initSensorDataManager(SensorDataManager *manager, size_t initial_capacity) {
    if (initial_capacity == 0) return;

    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->data = malloc(sizeof(SensorData) * manager->capacity);

    if (!manager->data) {
        fprintf(stderr, "Failed to allocate memory for sensor data\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);
}

// Function to resize the internal array dynamically
void resizeSensorDataManager(SensorDataManager *manager, size_t new_capacity) {
    SensorData *new_data = realloc(manager->data, sizeof(SensorData) * new_capacity);

    if (!new_data) {
        fprintf(stderr, "Failed to reallocate memory for sensor data\n");
        exit(EXIT_FAILURE);
    }

    manager->data = new_data;
    manager->capacity = new_capacity;
}

// Function to add a new sensor data entry
void addSensorData(SensorDataManager *manager, SensorData new_data) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2; // Double the capacity
        resizeSensorDataManager(manager, new_capacity);
    }

    manager->data[manager->count++] = new_data;

    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve a sensor data entry by index
int getSensorData(SensorDataManager *manager, size_t index, SensorData *out_data) {
    if (index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);

    *out_data = manager->data[index];

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Function to clean up the sensor data manager
void cleanupSensorDataManager(SensorDataManager *manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
}
```

This code demonstrates a thread-safe mechanism for managing and updating a collection of environmental sensor data in a multi-threaded application. It uses mutex locks to prevent data corruption during concurrent access, dynamic memory allocation to handle variable numbers of sensor data entries, and efficient resizing strategies to minimize memory fragmentation and allocations.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SENSOR_READINGS 10000

typedef struct {
    double temperature;
    double humidity;
    double pressure;
} Readings;

typedef struct {
    double timestamp;
    int status; // 0 for invalid, 1 for valid
    Readings readings;
} SensorData;

typedef struct SensorMetadataNode {
    int sensor_id;
    char location[50];
    double calibration_factor;
    struct SensorMetadataNode* next;
} SensorMetadataNode;

typedef struct {
    SensorData* data_array;
    pthread_mutex_t lock;
    SensorMetadataNode* metadata_head;
} WeatherMonitorSystem;

WeatherMonitorSystem* initialize_weather_monitor_system() {
    WeatherMonitorSystem* system = (WeatherMonitorSystem*)malloc(sizeof(WeatherMonitorSystem));

    if (!system) {
        perror("Failed to allocate memory for weather monitor system");
        return NULL;
    }

    // Dynamically allocate the array of sensor_data structures
    system->data_array = (SensorData*)calloc(MAX_SENSOR_READINGS, sizeof(SensorData));
    if (!system->data_array) {
        perror("Failed to allocate memory for sensor data array");
        free(system);
        return NULL;
    }

    // Initialize mutex lock for thread safety
    if (pthread_mutex_init(&system->lock, NULL) != 0) {
        perror("Failed to initialize mutex lock");
        free(system->data_array);
        free(system);
        return NULL;
    }

    system->metadata_head = NULL;

    return system;
}

void add_sensor_metadata(WeatherMonitorSystem* system, int sensor_id, const char* location, double calibration_factor) {
    if (system == NULL || location == NULL) return;

    SensorMetadataNode* new_node = (SensorMetadataNode*)malloc(sizeof(SensorMetadataNode));
    if (!new_node) {
        perror("Failed to allocate memory for sensor metadata node");
        return;
    }

    new_node->sensor_id = sensor_id;
    strncpy(new_node->location, location, sizeof(new_node->location) - 1);
    new_node->calibration_factor = calibration_factor;
    new_node->next = NULL;

    pthread_mutex_lock(&system->lock);

    // Add node to the beginning of the list for O(1) insertion
    new_node->next = system->metadata_head;
    system->metadata_head = new_node;

    pthread_mutex_unlock(&system->lock);
}

void free_weather_monitor_system(WeatherMonitorSystem* system) {
    if (system == NULL) return;

    // Free sensor data array
    free(system->data_array);

    // Free metadata linked list
    SensorMetadataNode* current = system->metadata_head;
    while (current != NULL) {
        SensorMetadataNode* next_node = current->next;
        free(current);
        current = next_node;
    }

    // Destroy mutex lock
    pthread_mutex_destroy(&system->lock);

    // Free the system structure itself
    free(system);
}

// Example usage
int main() {
    WeatherMonitorSystem* monitor_system = initialize_weather_monitor_system();

    if (monitor_system != NULL) {
        add_sensor_metadata(monitor_system, 1, "Location A", 0.98);
        add_sensor_metadata(monitor_system, 2, "Location B", 1.02);

        // Use the system...

        free_weather_monitor_system(monitor_system);
    }

    return 0;
}
```

This C code provides a thread-safe initialization and management of sensor data structures for a weather monitoring system using an array of `SensorData` and a linked list of `SensorMetadataNode`. It includes memory allocation, mutex locking for concurrency safety, and proper cleanup functions.']

