LogLevel getMostVerboseLogLevel(const std::vector<std::string>& levels) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    auto map = std::unordered_map<std::string, LogLevel>{
        {"ERROR", LogLevel::ERROR},
        {"WARN", LogLevel::WARN},
        {"INFO", LogLevel::INFO},
        {"DEBUG", LogLevel::DEBUG}
    };

