            geom.value = static_cast<double>(dis(gen));
            size_t len = str_length_dis(gen);
            geom.str.resize(len);
            std::generate_n(geom.str.begin(), len, [&]() { return 'A' + dis(gen) * 26; });
            geom.point.x = static_cast<float>(dis(gen));
            geom.point.y = static_cast<float>(dis(gen));
        }

        // Concurrent processing of integers from stdin
        std::mutex mtx;
        std::thread input_thread([&]() {
            int largest = findLargestInteger(mtx);
            logger.log("Largest integer found: " + std::to_string(largest));
        });

        input_thread.join();

    } catch (const std::exception& e) {
        logger.log(std::string("Error: ") + e.what());
    }

    // Deallocate memory
    pool.deallocate(doubles);
    pool.deallocate(strings);
    pool.deallocate(points);

    file.close();
}

int main() {
    MemoryPool pool;
    CustomLogger custom_logger; // Assume this is a concrete implementation of ILogger

    loadDataFromCompressedFile("data.bin", pool, custom_logger);

    return 0;
}
