class MemoryPool<T> {
    private final List<T[]> pool = new ArrayList<>();

    @SafeVarargs
    public void add(T[] array) { pool.add(array); }

    public T allocate(int size, Supplier<T[]> factory) {
        for (T[] arr : pool) {
            if (arr.length >= size) {
                T[] result = Arrays.copyOf(arr, size);
                pool.remove(arr);
                return result;
            }
        }
        return factory.get();
    }
}

