// Memory Pool for efficient memory management
class MemoryPool {
public:
    MemoryPool(size_t blockSize, size_t blockCount);
    ~MemoryPool();

    void* allocate(size_t size);
    void deallocate(void* ptr);

private:
    struct Block {
        Block* next;
    };

    Block* freeList = nullptr;
    std::mutex poolMutex;
    void createBlocks(size_t blockSize, size_t blockCount);
};

MemoryPool::MemoryPool(size_t blockSize, size_t blockCount) {
    createBlocks(blockSize, blockCount);
}

void MemoryPool::createBlocks(size_t blockSize, size_t blockCount) {
    for (size_t i = 0; i < blockCount; ++i) {
        Block* newBlock = reinterpret_cast<Block*>(operator new(blockSize));
        newBlock->next = freeList;
        freeList = newBlock;
    }
}

MemoryPool::~MemoryPool() {
    while (freeList) {
        Block* temp = freeList;
        freeList = freeList->next;
        operator delete(temp);
    }
}

void* MemoryPool::allocate(size_t size) {
    std::lock_guard<std::mutex> lock(poolMutex);
    if (!freeList) return nullptr;

    Block* head = freeList;
    freeList = head->next;
    return head;
}

void MemoryPool::deallocate(void* ptr) {
    std::lock_guard<std::mutex> lock(poolMutex);
    Block* block = static_cast<Block*>(ptr);
    block->next = freeList;
    freeList = block;
}

