std::string findHighestAverageReadingSensor(const std::unordered_map<std::string, std::vector<double>>& readings) {
    std::mutex mtx;
    double maxAvg = -1.0;
    std::string bestSensor;

    auto compareAndSetMax = [&](const std::pair<const std::string, const std::vector<double>>& entry) {
        std::lock_guard<std::mutex> lock(mtx);
        if (entry.second.empty()) return;

        double avg = std::accumulate(entry.second.begin(), entry.second.end(), 0.0) / entry.second.size();
        if (avg > maxAvg) {
            maxAvg = avg;
            bestSensor = entry.first;
        }
    };

    for (const auto& [sensorId, sensorReadings] : readings) {
        compareAndSetMax({sensorId, sensorReadings});
    }

    return bestSensor;
}

