        SensorData* entry = static_cast<SensorData*>(pool.allocate(sizeof(SensorData)));
        if (!entry) break;

        // Deserialize binary data into entry (example)
        file.read(reinterpret_cast<char*>(&entry->reading), sizeof(entry->reading));
        size_t metadataSize;
        file.read(reinterpret_cast<char*>(&metadataSize), sizeof(metadataSize));
        entry->metadata.resize(metadataSize);
        file.read(&entry->metadata[0], metadataSize);

        float x, y;
        file.read(reinterpret_cast<char*>(&x), sizeof(x));
        file.read(reinterpret_cast<char*>(&y), sizeof(y));
        entry->location = {x, y};

        // Process data with strategy
        strategy->process(*entry);

        if (!std::isnan(entry->reading)) {
            sensorReadings[entry->metadata].push_back(entry->reading);
        }

        dataEntries.push_back(*entry);
        pool.deallocate(entry);
    }

    file.close();

    std::string highestAvgSensor = findHighestAverageReadingSensor(sensorReadings);
    std::cout << "Sensor with the highest average reading: " << highestAvgSensor << std::endl;

    // Clean up
    for (auto& entry : dataEntries) {
        pool.deallocate(&entry);
    }
}

