['Below is an implementation of a C function that manages a flexible, in-memory record store supporting concurrent access from multiple threads:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_RECORDS 1024

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    atomic_size_t count;
    pthread_rwlock_t lock;
} RecordStore;

// Initialize the record store
void initRecordStore(RecordStore *store, size_t max_records) {
    store->capacity = max_records;
    store->offsets = (long *)malloc(sizeof(long) * max_records);
    store->keys = (int *)malloc(sizeof(int) * max_records);
    store->records = (Record *)calloc(max_records, sizeof(Record));
    atomic_store(&store->count, 0);
    pthread_rwlock_init(&store->lock, NULL);

    // Seed random number generator
    srand(time(NULL));
}

// Free the record store resources
void freeRecordStore(RecordStore *store) {
    free(store->offsets);
    free(store->keys);
    free(store->records);
    pthread_rwlock_destroy(&store->lock);
}

// Insert a new record into the store
int insertRecord(RecordStore *store, int key, int min_val, int max_val) {
    pthread_rwlock_wrlock(&store->lock);

    size_t current_count = atomic_load(&store->count);
    if (current_count >= store->capacity) {
        printf("Warning: Record Store is at capacity.\n");
        pthread_rwlock_unlock(&store->lock);
        return -1;
    }

    int index = current_count;
    store->keys[index] = key;
    store->records[index].value = min_val + rand() % (max_val - min_val + 1);

    atomic_fetch_add(&store->count, 1);
    pthread_rwlock_unlock(&store->lock);
    return 0;
}

// Update an existing record in the store
int updateRecord(RecordStore *store, int key, int new_value) {
    pthread_rwlock_wrlock(&store->lock);

    for (size_t i = 0; i < atomic_load(&store->count); ++i) {
        if (store->keys[i] == key) {
            store->records[i].value = new_value;
            pthread_rwlock_unlock(&store->lock);
            return 0;
        }
    }

    printf("Warning: Key not found for update.\n");
    pthread_rwlock_unlock(&store->lock);
    return -1;
}

// Query a record by key
int queryRecord(RecordStore *store, int key) {
    pthread_rwlock_rdlock(&store->lock);

    for (size_t i = 0; i < atomic_load(&store->count); ++i) {
        if (store->keys[i] == key) {
            pthread_rwlock_unlock(&store->lock);
            return store->records[i].value;
        }
    }

    printf("Warning: Key not found for query.\n");
    pthread_rwlock_unlock(&store->lock);
    return -1;
}

// Test the record store with multi-threading
void *threadFunction(void *arg) {
    RecordStore *store = (RecordStore *)arg;

    for (int i = 0; i < 100; ++i) {
        int key = rand() % MAX_RECORDS;
        insertRecord(store, key, 1, 100);
        queryRecord(store, key);
        updateRecord(store, key, rand() % 100 + 1);
    }

    return NULL;
}

int main() {
    RecordStore store;
    initRecordStore(&store, MAX_RECORDS);

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, threadFunction, &store);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    freeRecordStore(&store);

    return 0;
}
```

This code defines a `RecordStore` with support for concurrent access using read-write locks. It initializes arrays for offsets and keys, allocates memory for records, and provides functions to insert, update, and query records. The test suite simulates high concurrency by creating multiple threads that perform these operations.']

