    init_memory_pool(sizeof(long) + sizeof(int), ARRAY_SIZE * 2); // long_int_pairs
    init_memory_pool(sizeof(double), ARRAY_SIZE); // doubles
    init_memory_pool(sizeof(char*) * MAX_STRING_LENGTH, ARRAY_SIZE); // strings pointers
    init_memory_pool(sizeof(char) * MAX_STRING_LENGTH, ARRAY_SIZE); // char strings
    init_memory_pool(sizeof(Point), ARRAY_SIZE); // points
    init_memory_pool(sizeof(ComplexGeometry) + sizeof(char*) * MAX_STRING_LENGTH, ARRAY_SIZE); // complex_geometries

    long *long_int_pairs = allocate_long_int_pairs(ARRAY_SIZE);
    double *doubles = allocate_double_array(ARRAY_SIZE);
    char **strings = allocate_char_string_array(ARRAY_SIZE);
    Point *points = allocate_point_array(ARRAY_SIZE);
    ComplexGeometry *complex_geometries = allocate_complex_geometry_array(ARRAY_SIZE);

    initialize_data_structures(long_int_pairs, doubles, strings, points, complex_geometries, ARRAY_SIZE);

    FILE *streams[NUM_STREAMS];
    for (int i = 0; i < NUM_STREAMS; ++i) {
        streams[i] = fopen((char*)malloc(20), "r"); // Example stream files
    }

    process_datasets_concurrently(streams, NUM_STREAMS, stdout);

    cleanup_datasets(long_int_pairs, doubles, strings, points, complex_geometries, ARRAY_SIZE);

    for (int i = 0; i < NUM_STREAMS; ++i) {
        fclose(streams[i]);
        free((char*)streams[i]);
    }

    deallocate_memory_pool();
}

int main() {
    srand(time(NULL));
    process_memory_and_datasets();
    return 0;
}
