['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Entry {
    float floatValue;
    char *stringValue;
    int intValue;
    struct Entry *next;
} Entry;

#define MAX_MEMORY_USAGE 1048576 // Example threshold in bytes (1 MB)

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Entry* create_entry(float f, const char *str, int i) {
    Entry *newEntry = (Entry *)malloc(sizeof(Entry));
    if (!newEntry) return NULL;

    newEntry->floatValue = f;
    newEntry->intValue = i;
    newEntry->next = NULL;

    size_t strLen = strlen(str);
    newEntry->stringValue = (char *)malloc(strLen + 1);
    if (!newEntry->stringValue) {
        free(newEntry);
        return NULL;
    }

    strcpy(newEntry->stringValue, str);

    return newEntry;
}

int add_entry(Entry **head, float f, const char *str, int i) {
    pthread_mutex_lock(&lock);

    Entry *newEntry = create_entry(f, str, i);
    if (!newEntry) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    size_t currentSize = 0;

    for (Entry *iter = *head; iter != NULL; iter = iter->next) {
        currentSize += sizeof(Entry) + strlen(iter->stringValue) + 1;
    }
    currentSize += sizeof(Entry) + strlen(str) + 1;

    if (currentSize > MAX_MEMORY_USAGE) {
        free(newEntry->stringValue);
        free(newEntry);
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Memory usage exceeded threshold\n");
        return -2;
    }

    newEntry->next = *head;
    *head = newEntry;

    pthread_mutex_unlock(&lock);
    return 0;
}

void free_entries(Entry **head) {
    Entry *current = *head;
    while (current != NULL) {
        Entry *temp = current;
        current = current->next;
        free(temp->stringValue);
        free(temp);
    }
    *head = NULL;
}

int main() {
    Entry *entries = NULL;

    add_entry(&entries, 1.0f, "First", 10);
    add_entry(&entries, 2.5f, "Second", 20);

    // Free all allocated memory
    free_entries(&entries);

    return 0;
}
