LTE_RRC_MESSAGE_TYPE_UE_CONTEXT_RELEASE_REQUEST* initialize_ue_context_release_requests(
    size_t num_structs,
    L1_LOGGING_CONFIG* logging_config) {

    // Check cache first
    LTE_RRC_MESSAGE_TYPE_UE_CONTEXT_RELEASE_REQUEST* structs = NULL;
    if (cache_count > 0) {
        structs = get_cached_struct();
        if (structs != NULL) {
            return structs;
        }
    }

    // Allocate memory dynamically
    structs = allocate_structs(num_structs, logging_config);

    // If allocation exceeds cache size, release older entries in the cache
    if ((cache_count + num_structs) > MAX_CACHE_SIZE) {
        release_all_structs();
        for (size_t i = 0; i < num_structs && cache_count < MAX_CACHE_SIZE; ++i) {
