typedef struct {
    uint8_t *key;
    size_t key_len;
} CryptoKey;

// Function to securely generate AES-256 keys
CryptoKey* generate_aes_key() {
    CryptoKey *key = malloc(sizeof(CryptoKey));
    if (RAND_bytes(key->key, 32) != 1) { // 32 bytes for AES-256
        free(key);
        return NULL;
    }
    key->key_len = 32;
    return key;
}

// Function to securely generate ChaCha20 keys
CryptoKey* generate_chacha20_key() {
    CryptoKey *key = malloc(sizeof(CryptoKey));
    if (RAND_bytes(key->key, 32) != 1) { // 32 bytes for ChaCha20
        free(key);
        return NULL;
    }
    key->key_len = 32;
    return key;
}

// Function to securely generate ECDSA keys
EC_KEY* generate_ecdsa_key() {
    EC_KEY *eckey = EC_KEY_new_by_curve_name(NID_X9_62_prime256v1);
    if (eckey == NULL || !EC_KEY_generate_key(eckey)) {
        if (eckey) EC_KEY_free(eckey);
        return NULL;
    }
    return eckey;
}

// HMAC-SHA256 for message authentication
int hmac_sha256(const uint8_t *key, size_t key_len, const uint8_t *data, size_t data_len, uint8_t *digest) {
    unsigned int digest_len = EVP_MAX_MD_SIZE;
    HMAC_CTX *hctx = HMAC_CTX_new();

    if (!HMAC_Init_ex(hctx, key, key_len, EVP_sha256(), NULL)) return -1;
    if (!HMAC_Update(hctx, data, data_len)) return -2;
    if (!HMAC_Final(hctx, digest, &digest_len)) return -3;

    HMAC_CTX_free(hctx);
    return 0; // Success
}

// ECDSA signature verification
int verify_ecdsa_signature(EC_KEY *eckey, const uint8_t *data, size_t data_len, const uint8_t *sig_buf, size_t sig_len) {
    EVP_PKEY *pkey = EVP_PKEY_new();
    if (!EC_KEY_import_key(EVP_PKEY_get1_EC_KEY(pkey), eckey)) return -1;

    X509_SIG *x509_sig = d2i_X509_SIG(NULL, &sig_buf, sig_len);
    int ret = X509_SIG_verify(x509_sig, data, data_len);

    EVP_PKEY_free(pkey);
    X509_SIG_free(x509_sig);

    return ret;
}

