    pthread_rwlock_t rwlock;
} DataStructure;

void init_random() {
    srand((unsigned)time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* generate_metadata(size_t index) {
    static char metadata[256][32];
    snprintf(metadata[index], sizeof(metadata[0]), "meta_%zu", index);
    return metadata[index];
}

int init_data_structure(DataStructure *ds, size_t initial_capacity) {
    ds->capacity = initial_capacity;
    ds->keys = (char **)malloc(sizeof(char *) * initial_capacity);
    ds->offsets = (int *)malloc(sizeof(int) * initial_capacity);
    ds->data = (CustomData *)malloc(sizeof(CustomData) * initial_capacity);

    if (!ds->keys || !ds->offsets || !ds->data)
        return -1;

    pthread_mutex_init(&ds->lock, NULL);
    pthread_rwlock_init(&ds->rwlock, NULL);
    for (size_t i = 0; i < initial_capacity; ++i) {
        ds->keys[i] = strdup("default_key");
        ds->offsets[i] = random_int(1, 100);
        snprintf(ds->data[i].metadata, sizeof(ds->data[i].metadata), generate_metadata(i));
    }
    return 0;
}

void destroy_data_structure(DataStructure *ds) {
    for (size_t i = 0; i < ds->capacity; ++i)
        free(ds->keys[i]);
    free(ds->keys);
    free(ds->offsets);
    free(ds->data);

    pthread_mutex_destroy(&ds->lock);
    pthread_rwlock_destroy(&ds->rwlock);
}

void insert_item(DataStructure *ds, const char *key, int offset, CustomData data) {
    pthread_rwlock_wrlock(&ds->rwlock);
    if (pthread_mutex_trylock(&ds->lock) != 0) {
        pthread_rwlock_unlock(&ds->rwlock);
        return; // Lock not acquired
    }

    for (size_t i = 0; i < ds->capacity; ++i) {
        if (ds->offsets[i] == offset) { // Simplified example of finding by offset
            free(ds->keys[i]);
            ds->keys[i] = strdup(key);
            ds->data[i].value = data.value;
            snprintf(ds->data[i].metadata, sizeof(ds->data[i].metadata), "%s", data.metadata);

            pthread_mutex_unlock(&ds->lock);
            pthread_rwlock_unlock(&ds->rwlock);
            return;
        }
    }

    printf("Warning: Capacity reached. Insertion failed.\n");

    pthread_mutex_unlock(&ds->lock);
    pthread_rwlock_unlock(&ds->rwlock);
}

void query_item(DataStructure *ds, const char *key, int offset, CustomData *result) {
    pthread_rwlock_rdlock(&ds->rwlock);

    for (size_t i = 0; i < ds->capacity; ++i) {
        if (strcmp(ds->keys[i], key) == 0 && ds->offsets[i] == offset) {
            result->value = ds->data[i].value;
            snprintf(result->metadata, sizeof(result->metadata), "%s", ds->data[i].metadata);
            break;
        }
    }

    pthread_rwlock_unlock(&ds->rwlock);
}

void sample_statistics(DataStructure *ds) {
    pthread_rwlock_rdlock(&ds->rwlock);

    int sum = 0;
    for (size_t i = 0; i < ds->capacity; ++i)
        sum += ds->data[i].value;

    printf("Average value: %f\n", sum / (float)ds->capacity);

    pthread_rwlock_unlock(&ds->rwlock);
}

void test_data_structure() {
    DataStructure ds;
    init_random();
    init_data_structure(&ds, 10);

    CustomData data = {42, "custom metadata"};
    insert_item(&ds, "new_key", 42, data);

    CustomData result;
    query_item(&ds, "new_key", 42, &result);
    printf("Queried Value: %d, Metadata: %s\n", result.value, result.metadata);

    sample_statistics(&ds);

    destroy_data_structure(&ds);
}

int main() {
    test_data_structure();
    return 0;
}
