```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <math.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
    char *metadata;
} record_t;

typedef struct {
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    record_t records[MAX_RECORDS];
    size_t count;
    pthread_rwlock_t lock;
    // Memory pool details would go here, omitted for brevity
} RecordStore;

void init_record_store(RecordStore *store) {
    store->count = 0;
    pthread_rwlock_init(&store->lock, NULL);
}

int generate_truncated_normal(int min_val, int max_val) {
    static const double mean = (max_val + min_val) / 2.0;
    static const double stddev = (max_val - min_val) / 4.0; // Arbitrary choice
    double u1, u2, z;

    do {
        u1 = rand() * (1.0 / RAND_MAX);
        u2 = rand() * (1.0 / RAND_MAX);
        z = sqrt(-2.0 * log(u1)) * cos(2 * M_PI * u2);
        int val = round(mean + stddev * z);
    } while (val < min_val || val > max_val);

    return val;
}

int insert_record(RecordStore *store, int key, const char *metadata) {
    pthread_rwlock_wrlock(&store->lock);

    if (store->count >= MAX_RECORDS) {
        fprintf(stderr, "Warning: Record store at capacity\n");
        pthread_rwlock_unlock(&store->lock);
        return -1; // Capacity full
    }

    record_t new_record;
    new_record.value = generate_truncated_normal(0, 100); // Example range
    new_record.metadata = strdup(metadata);

    int index = store->count++;
    store->offsets[index] = (long) &store->records[index];
    store->keys[index] = key;
    store->records[index] = new_record;

    pthread_rwlock_unlock(&store->lock);
    return 0; // Success
}

record_t *query_record(RecordStore *store, int key) {
    pthread_rwlock_rdlock(&store->lock);

    for (size_t i = 0; i < store->count; ++i) {
        if (store->keys[i] == key) {
            record_t *res = &store->records[i];
            pthread_rwlock_unlock(&store->lock);
            return res;
        }
    }

    pthread_rwlock_unlock(&store->lock);
    return NULL; // Not found
}

void update_record(RecordStore *store, int key, int new_value) {
    pthread_rwlock_wrlock(&store->lock);

    for (size_t i = 0; i < store->count; ++i) {
        if (store->keys[i] == key) {
            store->records[i].value = new_value;
            pthread_rwlock_unlock(&store->lock);
            return;
        }
    }

    pthread_rwlock_unlock(&store->lock);
}

void free_record_store(RecordStore *store) {
    pthread_rwlock_wrlock(&store->lock);

    for (size_t i = 0; i < store->count; ++i) {
        free(store->records[i].metadata);
    }

    pthread_rwlock_unlock(&store->lock);
    pthread_rwlock_destroy(&store->lock);
}

int main() {
    srand(time(NULL));

    RecordStore store;
    init_record_store(&store);

    // Example operations
    insert_record(&store, 1, "First record");
    update_record(&store, 1, 42);

    record_t *record = query_record(&store, 1);
    if (record) {
        printf("Record value: %d\n", record->value);
        printf("Metadata: %s\n", record->metadata);
    }

    free_record_store(&store);

    return 0;
}
```

### Explanation:

- **Data Structures**: The `RecordStore` structure holds arrays for offsets, keys, and records, along with a count of current entries and a read-write lock for synchronization.

- **Random Value Generation**: A truncated normal distribution is used to generate integer values within a specified range.

- **Concurrency Control**: Read-write locks (`pthread_rwlock_t`) are used to allow multiple concurrent reads but exclusive writes, reducing contention in high-concurrency scenarios.

- **Memory Management**: Records and their metadata strings are dynamically allocated, with a function provided for cleanup.

This implementation assumes basic operations of insertion, update, and query while managing concurrency. Further extensions can include more sophisticated memory management strategies, statistical sampling, integrity checks, and enhanced metadata support.']

