#include <pthread.h>
#include <time.h>

typedef struct {
    int *data;
} record;

typedef struct {
    long offsets;
    int keys;
} dataSource;

void handle_memory_failure(void) {
    fprintf(stderr, "Memory allocation failed. Exiting gracefully.\n");
    exit(EXIT_FAILURE);
}

int* populate_records(record **records, size_t numRecords) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        records[i]->data = malloc(sizeof(int));
        if (!records[i]->data) handle_memory_failure();
        *records[i]->data = rand() % 2000001 - 1000000;
    }
    return *records[0]->data; // Return first element for verification
}

void free_records(record **records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i]->data) free(records[i]->data);
    }
    free(*records);
}

record** allocate_records(size_t *numRecords, const dataSource *dataSources, size_t numDataSources) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Estimate initial memory allocation
    *numRecords = 5000 * numDataSources;

    record **records = malloc(*numRecords * sizeof(record*));
    if (!records) handle_memory_failure();

    for (size_t i = 0; i < *numRecords; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) handle_memory_failure();
        records[i]->data = NULL;
    }

    // Populate records with random data
    populate_records(records, *numRecords);

    pthread_mutex_destroy(&lock);
    return records;
}

void process_data_sources(const dataSource *dataSources, size_t numDataSources) {
    size_t numRecords;
    record **records = allocate_records(&numRecords, dataSources, numDataSources);

    // Example processing with potential for concurrent access
    int firstElement = populate_records(records, numRecords);

    printf("First element value: %d\n", firstElement);

    free_records(&records, numRecords);
}

int main() {
    dataSource sources[] = {
        {1000L, 200},
        {1500L, 300}
        // Add more dataSources as needed
    };

    size_t numDataSources = sizeof(sources) / sizeof(sources[0]);
    process_data_sources(sources, numDataSources);

    return 0;
}
