#include <string.h>
#include <time.h>
#include <pthread.h>
#include <assert.h>

#define MAX_RECORDS 10000
#define INITIAL_CAPACITY 100
#define MEMORY_ALIGNMENT 64
#define DATA_RANGE_MAX 255

typedef struct {
    int key;
    unsigned char *data;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

typedef enum { REJECT_DUPLICATES, UPDATE_EXISTING } DuplicatePolicy;

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int is_key_valid(int key) {
    // Simulate network latency and failures
    sleep(rand() % 3); 
    if (rand() % 10 < 2) return -1; // Simulated network failure

    // Check against external data source
    return 1; // Assume valid for simplicity
}

RecordCollection* create_collection(DuplicatePolicy policy) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    collection->records = calloc(INITIAL_CAPACITY, sizeof(Record*));
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(RecordCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->data);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection *collection, int key, DuplicatePolicy policy) {
    if (is_key_valid(key) == -1) {
        log_message("Network error during key validation.");
        return 0;
    }

    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            if (policy == REJECT_DUPLICATES) {
                log_message("Duplicate key rejected.");
                pthread_mutex_unlock(&collection->lock);
                return 0;
            } else {
                free(collection->records[i]->data);
                collection->records[i]->data = malloc(DATA_RANGE_MAX);
                memset(collection->records[i]->data, rand() % DATA_RANGE_MAX, DATA_RANGE_MAX);
                log_message("Duplicate key updated.");
                pthread_mutex_unlock(&collection->lock);
                return 1;
            }
        }
    }

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record **new_records = realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            log_message("Memory allocation failed.");
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->data = malloc(DATA_RANGE_MAX);
    memset(record->data, rand() % DATA_RANGE_MAX, DATA_RANGE_MAX);

    collection->records[collection->count++] = record;
    log_message("Record added successfully.");

    pthread_mutex_unlock(&collection->lock);
    return 1;
}

void serialize_collection(RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_message("Failed to open file for serialization.");
        return;
    }

    fwrite(&collection->capacity, sizeof(size_t), 1, file);
    fwrite(&collection->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < collection->count; ++i) {
        fwrite(&collection->records[i]->key, sizeof(int), 1, file);
        fwrite(collection->records[i]->data, DATA_RANGE_MAX, 1, file);
    }

    fclose(file);
    log_message("Serialization completed.");
}

void deserialize_collection(RecordCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_message("Failed to open file for deserialization.");
        return;
    }

    size_t capacity, count;
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&count, sizeof(size_t), 1, file);

    collection->records = realloc(collection->records, capacity * sizeof(Record*));
    collection->capacity = capacity;
    collection->count = count;

    for (size_t i = 0; i < count; ++i) {
        Record *record = malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        record->data = malloc(DATA_RANGE_MAX);
        fread(record->data, DATA_RANGE_MAX, 1, file);

        collection->records[i] = record;
    }

    fclose(file);
    log_message("Deserialization completed.");
}

void monitor_performance(RecordCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    printf("Collection Size: %zu\n", collection->count);
    printf("Number of Unique Keys: %zu\n", collection->count); // Assuming no duplicates
    pthread_mutex_unlock(&collection->lock);
}

int main() {
    srand(time(NULL));

    RecordCollection *collection = create_collection(REJECT_DUPLICATES);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        add_record(collection, rand() % 10000, REJECT_DUPLICATES);
    }

    serialize_collection(collection, "records.dat");

    destroy_collection(collection);

    collection = create_collection(UPDATE_EXISTING);
    deserialize_collection(collection, "records.dat");
    monitor_performance(collection);

    destroy_collection(collection);

    return 0;
}
