#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <string.h>

#define MAX_SERVERS 1000

typedef struct {
    int Server_ID;
    char name[256];
    char description[512];
    time_t timestamp;
    // Other metadata
} MediaServer;

typedef struct Node {
    MediaServer server;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int count;
    size_t capacity;  // Max capacity for LRU cache
} LRUCache;

LRUCache* create_cache(size_t capacity) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->head = NULL;
    cache->tail = NULL;
    pthread_mutex_init(&cache->lock, NULL);
    cache->count = 0;
    cache->capacity = capacity;
    return cache;
}

void move_to_head(Node* node, LRUCache* cache) {
    if (node == cache->head) return;

    // Remove from current position
    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (cache->tail == node) cache->tail = node->prev;

    // Move to head
    node->next = cache->head;
    node->prev = NULL;
    if (cache->head) cache->head->prev = node;
    cache->head = node;
    if (!cache->tail) cache->tail = node;
}

void evict(LRUCache* cache) {
    if (cache->tail) {
        Node* old_tail = cache->tail;
        if (old_tail->prev) old_tail->prev->next = NULL;
        cache->tail = old_tail->prev;
        free(old_tail);
        cache->count--;
    }
}

Node* get_or_create_node(LRUCache* cache, int server_id, MediaServer server_data) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current) {
        if (current->server.Server_ID == server_id) {
            move_to_head(current, cache);
            pthread_mutex_unlock(&cache->lock);
            return current;
        }
        current = current->next;
    }

    if (cache->count >= cache->capacity) evict(cache);

    Node* new_node = (Node*)malloc(sizeof(Node));
    memcpy(&new_node->server, &server_data, sizeof(MediaServer));
    new_node->next = cache->head;
    new_node->prev = NULL;
    if (cache->head) cache->head->prev = new_node;
    cache->head = new_node;
    if (!cache->tail) cache->tail = new_node;

    pthread_mutex_unlock(&cache->lock);
    return new_node;
}

void update_server(LRUCache* cache, int server_id, MediaServer updated_data) {
    Node* node = get_or_create_node(cache, server_id, updated_data);
    if (node && node->server.Server_ID == server_id) {
        memcpy(&node->server, &updated_data, sizeof(MediaServer));
    }
}

void free_cache(LRUCache* cache) {
    pthread_mutex_lock(&cache->lock);

    Node* current = cache->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

void initialize_crypto() {
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha256());
    EVP_add_cipher(EVP_camellia_128_ecb());
    EVP_add_digest_alias("MD5", EVP_md5());
    EVP_add_digest_alias("SHA1", EVP_sha1());
}

void manage_gis_dataset() {
    // Initialize LRU Cache
    LRUCache* cache = create_cache(100);

    // Initialize crypto
    initialize_crypto();

    // Example usage
    MediaServer server = {1, "Server1", "A description", time(NULL)};
    update_server(cache, 1, server);

    // Simulate operations...

    free_cache(cache);
}

int main() {
    manage_gis_dataset();
    return 0;
}
```

This code provides a basic framework for managing a distributed GIS dataset using an LRU cache and OpenSSL cryptographic functions. It includes thread-safe operations for adding, updating, and evicting media server instances from the cache. The cryptographic initialization is demonstrated with EVP_add_cipher and EVP_add_digest. This example does not cover all aspects of the task, such as rollback mechanisms, analytics integration, or handling network issues, but it provides a starting point for further development.']

