#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1024

typedef struct Entry {
    char *key;
    double value;
    time_t timestamp;
} Entry;

typedef struct HashTable {
    Entry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    atomic_size_t pool_size;
    char *memory_pool;
} HashTable;

static unsigned long hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;
    return hash;
}

HashTable* initialize_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    table->capacity = INITIAL_POOL_SIZE;
    table->count = 0;
    table->entries = calloc(table->capacity, sizeof(Entry *));
    pthread_mutex_init(&table->lock, NULL);
    atomic_store(&table->pool_size, INITIAL_POOL_SIZE);
    table->memory_pool = malloc(INITIAL_POOL_SIZE * sizeof(Entry));
    if (!table->memory_pool) {
        free(table);
        return NULL;
    }
    return table;
}

void* allocate_memory(HashTable *table, size_t entry_count) {
    pthread_mutex_lock(&table->lock);
    char *new_pool = realloc(table->memory_pool, atomic_load(&table->pool_size) * sizeof(Entry));
    if (!new_pool) {
        pthread_mutex_unlock(&table->lock);
        return NULL;
    }
    table->memory_pool = new_pool;
    atomic_store(&table->pool_size, atomic_load(&table->pool_size) + entry_count);
    pthread_mutex_unlock(&table->lock);
    return (void*)table->memory_pool;
}

Entry* get_entry(HashTable *table, const char *key) {
    unsigned long hash = hash_function(key) % table->capacity;
    for (size_t i = 0; i < table->capacity; ++i) {
        size_t idx = (hash + i) % table->capacity;
        if (!table->entries[idx]) continue;
        if (strcmp(table->entries[idx]->key, key) == 0)
            return table->entries[idx];
    }
    return NULL;
}

void insert_or_update_entry(HashTable *table, const char *key, double value) {
    pthread_mutex_lock(&table->lock);

    Entry *entry = get_entry(table, key);
    if (!entry) {
        entry = allocate_memory(table, 1);
        if (!entry) {
            pthread_mutex_unlock(&table->lock);
            return;
        }
        entry->key = strdup(key);
        table->entries[hash_function(key) % table->capacity] = entry;
        ++table->count;
    }

    entry->value = value;
    entry->timestamp = time(NULL);

    pthread_mutex_unlock(&table->lock);
}

double get_value(HashTable *table, const char *key) {
    pthread_mutex_lock(&table->lock);

    Entry *entry = get_entry(table, key);
    double value = entry ? entry->value : NAN;

    pthread_mutex_unlock(&table->lock);
    return value;
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->entries[i]) {
            free(table->entries[i]->key);
            free(table->entries[i]);
        }
    }
    free(table->entries);
    free(table->memory_pool);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    HashTable *hash_table = initialize_hash_table();
    if (!hash_table) return 1;

    insert_or_update_entry(hash_table, "temperature", 36.6);
    printf("Temperature: %.2f\n", get_value(hash_table, "temperature"));

    free_hash_table(hash_table);
    return 0;
}
