    STATUS_OK,
    STATUS_ERROR,
    STATUS_PENDING
} status;

typedef struct {
    double value;
    char *name;
    point p;
    status s;
} geometry;

// Custom memory pool structure for geometries
typedef struct {
    size_t size;
    void *pool;
    pthread_mutex_t lock;
    size_t offset;
} MemoryPool;

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

MemoryPool* create_memory_pool(size_t num_elements, size_t element_size) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->size = num_elements * element_size;
    mp->pool = malloc(mp->size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }
    mp->offset = 0;
    pthread_mutex_init(&mp->lock, NULL);

    log_message("Memory pool created");

    return mp;
}

void* allocate_from_pool(MemoryPool *mp, size_t element_size) {
    if (element_size > mp->size - mp->offset) {
        return NULL; // Out of memory
    }

    pthread_mutex_lock(&mp->lock);
    void *ptr = (char *)mp->pool + mp->offset;
    mp->offset += element_size;
    pthread_mutex_unlock(&mp->lock);

    log_message("Allocated from pool");

    return ptr;
}

void free_memory_pool(MemoryPool *mp) {
    if (!mp) return;

    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);

    log_message("Memory pool freed");
}

geometry* initialize_geometry_array(size_t num_geometries, MemoryPool *mp) {
    geometry *geomArray = (geometry *)allocate_from_pool(mp, num_geometries * sizeof(geometry));
    if (!geomArray) return NULL;

    for (size_t i = 0; i < num_geometries; ++i) {
        geomArray[i].value = (double)i;
        geomArray[i].name = strdup("Geometry");
        geomArray[i].p.x = (float)(i * 1.1);
        geomArray[i].p.y = (float)(i * 2.2);
        geomArray[i].s = (status)(i % 3);
    }

    log_message("Initialized geometry array");

    return geomArray;
}

void find_largest_integer(int *array, size_t num_elements, int *result) {
    pthread_mutex_lock((pthread_mutex_t *)result);
    for (size_t i = 0; i < num_elements; ++i) {
        if (array[i] > *result) {
            *result = array[i];
        }
    }
    pthread_mutex_unlock((pthread_mutex_t *)result);

    log_message("Largest integer found");
}

void read_integers(int **intArray, size_t *numElements) {
    printf("Enter number of integers: ");
    scanf("%zu", numElements);

    *intArray = (int *)malloc(*numElements * sizeof(int));
    if (!*intArray) return;

    log_message("Integer array allocated");

    printf("Enter integers:\n");
    for (size_t i = 0; i < *numElements; ++i) {
        scanf("%d", &((*intArray)[i]));
    }
}

void handle_geometries(size_t num_geometries, MemoryPool *mp) {
    int largest = INT_MIN;
    pthread_mutex_t largest_lock = PTHREAD_MUTEX_INITIALIZER;

    geometry *geomArray = initialize_geometry_array(num_geometries, mp);
    if (!geomArray) {
        log_message("Failed to initialize geometries");
        return;
    }

    // Simulating concurrent access
    pthread_t threads[2];

    for (int i = 0; i < 2; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))find_largest_integer, &largest);
    }

    for (int i = 0; i < 2; ++i) {
