    if (!mp) {
        log_message("Memory pool creation failed");
        return EXIT_FAILURE;
    }

    size_t num_geometries = 5;

    read_integers(&array, &num_elements);

    handle_geometries(num_geometries, mp);

    free(array);

    return 0;
}
