#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long *offset;
    int key;
} record;

void manage_memory(int num_offsets, long offsets[], int num_keys, int keys[], record records[], int min_value, int max_value, unsigned int seed) {
    if (num_offsets <= 0 || num_keys <= 0 || min_value > max_value) return;

    // Allocate memory for the array of long offsets
    long *offset_array = (long *)malloc(num_offsets * sizeof(long));
    if (!offset_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Copy user-provided offsets into allocated memory
    memcpy(offset_array, offsets, num_offsets * sizeof(long));

    // Allocate memory for the array of int keys (double the number of offsets)
    int *key_array = (int *)malloc(2 * num_offsets * sizeof(int));
    if (!key_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset_array);
        return;
    }

    // Initialize integer keys using a custom hash function
    for (int i = 0; i < 2 * num_offsets; ++i) {
        key_array[i] = (i * 2654435761u) & 0xFFFFFFFF; // Simple scalable hash function
    }

    // Set the value of each record's integer key to a random value within specified range using seed
    srand(seed);
    for (int i = 0; i < num_offsets; ++i) {
        records[i].offset = &offset_array[i];
        records[i].key = min_value + rand() % (max_value - min_value + 1);
    }

    // Populate keys array with values from key_array
    memcpy(keys, key_array, num_keys * sizeof(int));

    // Boundary checks can be done during operations above using conditionals

    // Free allocated memory at the end to prevent leaks
    free(offset_array);
    free(key_array);
}

int main() {
    int num_offsets = 5;
    long offsets[] = {1, 2, 3, 4, 5};
    int num_keys = 10;
    int keys[10];
    record records[5];
    int min_value = 0;
    int max_value = 100;
    unsigned int seed = 42;

    manage_memory(num_offsets, offsets, num_keys, keys, records, min_value, max_value, seed);

    // Display initialized keys for verification
    printf("Keys: ");
    for (int i = 0; i < num_keys; ++i) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    return 0;
}
