// Thread-safe random number generator state
typedef struct {
    pthread_mutex_t mutex;
    unsigned int seed;
} rng_state;

void init_rng(rng_state *rng, unsigned int initial_seed) {
    pthread_mutex_init(&rng->mutex, NULL);
    rng->seed = initial_seed;
}

unsigned int thread_safe_random(rng_state *rng, unsigned int range_min, unsigned int range_max) {
    pthread_mutex_lock(&rng->mutex);

    rng->seed ^= (rng->seed << 13);
    rng->seed ^= (rng->seed >> 17);
    rng->seed ^= (rng->seed << 5);

    unsigned int result = (rng->seed % (range_max - range_min + 1)) + range_min;

    pthread_mutex_unlock(&rng->mutex);
    return result;
}

void manage_memory(int num_offsets, unsigned int salt, unsigned int seed, time_t inactive_threshold) {
    if (num_offsets <= 0) {
        printf("Invalid number of offsets\n");
        return;
    }

    size_t offset_array_size = ((num_offsets + CHUNK_SIZE - 1) / CHUNK_SIZE) * CHUNK_SIZE;
    long *offsets = malloc(offset_array_size * sizeof(long));
    int *keys = malloc(num_offsets * KEY_MULTIPLIER * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    record *records = calloc(num_offsets, sizeof(record));
    if (!records) {
        printf("Memory allocation for records failed\n");
        free(offsets);
        free(keys);
        return;
    }

    rng_state rng;
    init_rng(&rng, seed);

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Initialize offsets and keys
    for (int i = 0; i < num_offsets; ++i) {
        if (i >= offset_array_size || i * KEY_MULTIPLIER >= num_offsets * KEY_MULTIPLIER) {
            printf("Boundary check failed\n");
            break;
        }

        unsigned int key1 = hash_function(i, salt);
        unsigned int key2 = thread_safe_random(&rng, 0, 100000);

        offsets[i] = (long)i; // Example assignment
        keys[i * KEY_MULTIPLIER] = key1;
        keys[i * KEY_MULTIPLIER + 1] = key2;

        records[i].offset = &offsets[i];
        records[i].key = key2; 
        records[i].timestamp = time(NULL);
    }

    pthread_mutex_lock(&lock);

    // Marking inactive records
    for (int i = 0; i < num_offsets; ++i) {
        if (difftime(time(NULL), records[i].timestamp) > inactive_threshold) {
            records[i].key = -1; // Arbitrary mark to denote inactivity
        }
    }

    pthread_mutex_unlock(&lock);

    // Cleanup and deallocation
    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_destroy(&lock);
}

int main() {
    manage_memory(1000, 12345, 67890, 3600); // Example usage
    return 0;
}
