// Thread function for parallel computation
void* compute_series(void* arg) {
    Node** nodes = (Node**)arg;
    int start = *(int*)nodes[0];
    int end = *(int*)nodes[1];

    for (int i = start; i < end; ++i) {
        double value = compute_value(i);
        insert_node(&(*nodes)[2], i, value);
    }
    return NULL;
}

void manage_memory_and_operations(int num_elements, double* values, Node** head) {
    // 1. Allocate memory for array of doubles
    *head = NULL;

    // Estimate a larger size to minimize frequent reallocations.
    int estimated_size = (num_elements > 1000) ? num_elements + 500 : num_elements;
    values = (double*)calloc(estimated_size, sizeof(double));

    if (!values) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // 2. Allocate memory for linked list
    const int cache_size = 1000; // Size of node cache.
    Node* node_cache[cache_size];
    int cache_top = 0;

    // Helper to create a node, using cached nodes if available
    Node* create_node(double value) {
        Node* node;
        if (cache_top > 0) {
            node = node_cache[--cache_top];
        } else {
            node = (Node*)malloc(sizeof(Node));
        }
        node->value = value;
        node->next = NULL;
        return node;
    }

    // Helper to insert a node
    void insert_node(Node** head, int index, double value) {
        Node* new_node = create_node(value);
        if (!(*head)) {
            *head = new_node;
        } else {
            Node* current = *head;
            for (int i = 0; i < index - 1 && current->next != NULL; ++i) {
                current = current->next;
            }
            new_node->next = current->next;
            current->next = new_node;
        }

        if (cache_top < cache_size) {
            node_cache[cache_top++] = new_node;
        } else {
            free(new_node);
        }
    }

    // 4. Populate linked list with values from mathematical series
    int num_threads = 4; 
    pthread_t threads[num_threads];
    int segment_size = (num_elements + num_threads - 1) / num_threads;

    for (int i = 0; i < num_threads; ++i) {
        int start = i * segment_size;
        int end = (i + 1) * segment_size;
        if (end > num_elements) end = num_elements;

        // Prepare arguments
        int args[2] = {start, end};
        pthread_create(&threads[i], NULL, compute_series, &args);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // 5. Retrieve average of first n nodes
    int n = num_elements;
    double average = get_average(*head, n);
    printf("Average of first %d elements: %.2f\n", n, average);

    // Populate values array with the linked list values
    Node* current = *head;
    for (int i = 0; i < num_elements && current != NULL; ++i) {
        values[i] = current->value;
        current = current->next;
    }

    print_array(values, num_elements);

    // 6. Free allocated memory
    free_list(head, -1); // Free entire list
    free(values);
}

// Function to compute value for a given index (custom formula)
double compute_value(int index) {
    return (index + 1) * (3.14 / (index + 2)); // Example custom formula
}

// Function to get average of first n nodes
double get_average(Node* head, int n) {
    double sum = 0;
    Node* current = head;
    int count = 0;

    for (; current != NULL && count < n; ++count) {
        sum += current->value;
        current = current->next;
    }

    return (count > 0) ? sum / count : 0.0;
}

// Function to free the linked list
void free_list(Node** head, int up_to_index) {
    Node* current = *head;
    Node* next_node;

    while (current != NULL) {
        if (up_to_index < 0 || (*head)->value <= compute_value(up_to_index)) {
            next_node = current->next;
            free(current);
            current = next_node;
        } else {
            break;
        }
    }

    *head = current;

    // Push freed nodes to the cache
    for (int i = 0; i < cache_size && next_node != NULL; ++i) {
        node_cache[i] = current;
        current = current->next;
    }
}

// Helper function to print array values
void print_array(double values[], int size) {
    printf("Array Values: ");
    for (int i = 0; i < size; ++i) {
        printf("%.2f ", values[i]);
    }
    printf("\n");
}
