#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // Maximum memory usage (1MB)
#define POOL_SIZE 1000               // Number of records in the pool

typedef struct {
    int key;
    long offset;
} Record;

// Global variables for memory management and synchronization
Record* record_pool[POOL_SIZE];
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory_used = 0;
pthread_mutex_t memory_used_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_record_pool() {
    pthread_mutex_lock(&memory_lock);
    for (int i = 0; i < POOL_SIZE; ++i) {
        record_pool[i] = malloc(sizeof(Record));
        if (!record_pool[i]) {
            fprintf(stderr, "Failed to allocate memory for Record.\n");
            exit(EXIT_FAILURE); // Handle allocation failure
        }
        total_memory_used += sizeof(Record);
    }
    pthread_mutex_unlock(&memory_lock);
}

int allocate_record(int key, long offset) {
    pthread_mutex_lock(&memory_lock);

    if (total_memory_used + sizeof(Record) > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory usage exceeded.\n");
        pthread_mutex_unlock(&memory_lock);
        return -1; // Indicate failure
    }

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (!record_pool[i]) { // Find an unused slot
            record_pool[i] = malloc(sizeof(Record));
            if (!record_pool[i]) {
                fprintf(stderr, "Failed to allocate memory during allocation.\n");
                pthread_mutex_unlock(&memory_lock);
                return -1;
            }
            total_memory_used += sizeof(Record);
            record_pool[i]->key = key;
            record_pool[i]->offset = offset;
            pthread_mutex_unlock(&memory_lock);
            return i; // Return index of allocated record
        }
    }

    fprintf(stderr, "No available slots in the pool.\n");
    pthread_mutex_unlock(&memory_lock);
    return -1; // Indicate failure
}

void reset_records() {
    pthread_mutex_lock(&memory_lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (record_pool[i]) {
            record_pool[i]->key = 0;
            record_pool[i]->offset = 0L;
        }
    }

    pthread_mutex_unlock(&memory_lock);
}

void cleanup_record_pool() {
    pthread_mutex_lock(&memory_lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (record_pool[i]) {
            free(record_pool[i]);
            record_pool[i] = NULL;
        }
    }

    total_memory_used = 0;
    pthread_mutex_unlock(&memory_lock);
}

// Main function to demonstrate usage
int main() {
    initialize_record_pool();

    int index = allocate_record(1, 100);
    if (index != -1) {
        printf("Record allocated at index: %d\n", index);
    }

    reset_records();
    cleanup_record_pool();

    return 0;
}
