// Memory pool structure
typedef struct {
    void** blocks;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blocks = (void**)malloc(block_size * num_blocks);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->num_blocks = 0;
    pthread_mutex_init(&pool->lock, NULL);

    for(size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
    }

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->num_blocks >= MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void* block = pool->blocks[pool->num_blocks++];
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void memory_pool_free(MemoryPool* pool, void* block) {
    // Note: Implement deallocation logic as needed
}

