void network_data_reception_thread(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;

    Record* records = memory_pool_alloc(pool, sizeof(Record) * RECORD_COUNT);
    Shape* shapes = memory_pool_alloc(pool, sizeof(Shape) * SHAPE_COUNT);

