['Below is a C implementation that addresses the requirements of managing dynamic user sessions within a web application environment.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define SESSION_ID_LEN 36
#define MEMORY_LIMIT 1024 * 1024 // Example limit in bytes

typedef enum { ACTIVE, EXPIRED, INACTIVE } SessionStatus;

typedef struct {
    char sessionID[SESSION_ID_LEN];
    time_t lastActivity;
    SessionStatus status;
} UserSession;

typedef struct {
    UserSession* sessions;
    int count;
    size_t memoryUsage;
    pthread_mutex_t lock;
} SessionManager;

void initializeSessionManager(SessionManager* manager, int initialCapacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->memoryUsage = sizeof(UserSession) * initialCapacity;
    manager->sessions = (UserSession*)malloc(manager->memoryUsage);

    if (!manager->sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void freeSessionManager(SessionManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->sessions);
}

void addSession(SessionManager* manager, const char* sessionID, time_t lastActivity, SessionStatus status) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_SESSIONS || manager->memoryUsage + sizeof(UserSession) > MEMORY_LIMIT) {
        // Cleanup expired sessions to make room
        for (int i = 0; i < manager->count; ++i) {
            if (manager->sessions[i].status == EXPIRED) {
                memmove(&manager->sessions[i], &manager->sessions[i + 1],
                        sizeof(UserSession) * (manager->count - i - 1));
                --manager->count;
                --manager->memoryUsage;
                break; // Break after cleaning one expired session
            }
        }
    }

    if (manager->count < MAX_SESSIONS && manager->memoryUsage + sizeof(UserSession) <= MEMORY_LIMIT) {
        strcpy(manager->sessions[manager->count].sessionID, sessionID);
        manager->sessions[manager->count].lastActivity = lastActivity;
        manager->sessions[manager->count].status = status;
        ++manager->count;
        manager->memoryUsage += sizeof(UserSession);
    }

    pthread_mutex_unlock(&manager->lock);
}

void resetSessions(SessionManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        manager->sessions[i].status = INACTIVE;
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanupExpiredSessions(SessionManager* manager, time_t currentTime, int expirationTimeInSeconds) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count;) {
        if (currentTime - manager->sessions[i].lastActivity > expirationTimeInSeconds &&
            manager->sessions[i].status != INACTIVE) {
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    sizeof(UserSession) * (manager->count - i - 1));
            --manager->count;
            --manager->memoryUsage;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void periodicCleanup(SessionManager* manager, int cleanupIntervalInSeconds) {
    while (1) {
        sleep(cleanupIntervalInSeconds);

        time_t currentTime = time(NULL);
        cleanupExpiredSessions(manager, currentTime, 3600); // Example: Sessions expire after 1 hour
    }
}

int main() {
    SessionManager sessionManager;
    initializeSessionManager(&sessionManager, MAX_SESSIONS / 2);

    // Simulate web server startup
    resetSessions(&sessionManager);

    // Start cleanup thread (in real application, use a dedicated thread pool)
    pthread_t cleanupThread;
    pthread_create(&cleanupThread, NULL, (void*)periodicCleanup, &sessionManager);

    // Web server operations...

    // Simulate web server shutdown
    pthread_cancel(cleanupThread);
    pthread_join(cleanupThread, NULL);

    freeSessionManager(&sessionManager);
    return 0;
}
```

### Key Points:
- **Thread Safety**: The `pthread_mutex_t` lock ensures that session management operations are thread-safe.
- **Memory Management**: The code handles memory allocation failures and dynamically manages the number of sessions based on a predefined limit.
- **Session Cleanup**: A periodic cleanup function removes expired sessions to optimize resource usage.
- **Initialization and Shutdown**: Resetting sessions at startup and shutdown minimizes overhead.']

