['Below are C code snippets for a custom memory pool manager to handle `Record` structures efficiently and a thread-safe function to compute and print the median of integers from standard input.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#include <string.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 512 // Example: 512 MB max memory usage

typedef struct {
    int key;
    long offset;
} Record;

typedef struct MemoryPoolNode {
    Record record;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

typedef struct {
    MemoryPoolNode* free_list_head;
    size_t block_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool;

void initialize_memory_pool(size_t pool_size) {
    pthread_mutex_init(&memory_pool.lock, NULL);
    memory_pool.free_list_head = NULL;
    memory_pool.block_size = sizeof(MemoryPoolNode);

    for (size_t i = 0; i < pool_size; ++i) {
        MemoryPoolNode* node = malloc(memory_pool.block_size);
        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        node->next = memory_pool.free_list_head;
        memory_pool.free_list_head = node;
    }

    // Monitor and adjust the pool size based on performance metrics
}

void* allocate_record() {
    pthread_mutex_lock(&memory_pool.lock);

    if (memory_pool.free_list_head == NULL) {
        MemoryPoolNode* node = malloc(memory_pool.block_size);
        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }
    }

    MemoryPoolNode* node = memory_pool.free_list_head;
    memory_pool.free_list_head = node->next;

    pthread_mutex_unlock(&memory_pool.lock);
    return &node->record;
}

void deallocate_record(void* record) {
    if (!record) return;

    MemoryPoolNode* node = (MemoryPoolNode*)((char*)record - offsetof(MemoryPoolNode, record));

    pthread_mutex_lock(&memory_pool.lock);
    node->next = memory_pool.free_list_head;
    memory_pool.free_list_head = node;
    pthread_mutex_unlock(&memory_pool.lock);
}

double calculate_median(int* numbers, size_t count) {
    if (count == 0) return NAN;

    // Simple insertion sort
    for (size_t i = 1; i < count; ++i) {
        int key = numbers[i];
        int j = i - 1;
        while (j >= 0 && numbers[j] > key) {
            numbers[j + 1] = numbers[j];
            --j;
        }
        numbers[j + 1] = key;
    }

    if (count % 2 == 0)
        return ((double)numbers[count / 2 - 1] + numbers[count / 2]) / 2.0;
    else
        return (double)numbers[count / 2];
}

void* read_input_and_compute_median(void*) {
    size_t count = 0, capacity = 10;
    int* numbers = malloc(capacity * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int num;
    while (scanf("%d", &num) == 1) {
        if (count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                fprintf(stderr, "Memory reallocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
        numbers[count++] = num;
    }

    double median = calculate_median(numbers, count);
    printf("Median: %f\n", median);

    free(numbers);
    return NULL;
}

int main() {
    initialize_memory_pool(10000); // Initialize pool with 10,000 nodes

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, read_input_and_compute_median, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);
    return EXIT_SUCCESS;
}
```

**Key Points:**

- **Memory Pool:** A simple memory pool design is used to manage `Record` instances efficiently. The pool size can be adjusted based on performance metrics.
- **Thread Safety:** Mutexes ensure that the memory pool operations are thread-safe, minimizing contention in a multi-threaded environment.
- **Median Calculation:** A basic insertion sort approach is implemented for calculating the median, and it operates within its own thread to ensure thread safety.
- **Error Handling:** Basic error handling is included for memory allocation failures.

This implementation provides a foundation to handle high-performance requirements while maintaining code simplicity. Further optimizations could include more advanced sorting algorithms, dynamic resizing based on load conditions, or even lock-free data structures depending on the specific use case and performance analysis.']

