['Below is a C implementation that addresses the outlined requirements by defining a function to allocate and initialize various data structures with considerations for concurrency, dynamic integration, and robust error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 50

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    double dValue;
    char str[MAX_STRING_LENGTH];
    Point p;
} Geometry;

typedef struct {
    int value;
    double floatingPointNumber;
} Record;

typedef struct MemoryPool {
    size_t blockSize;
    void *memoryBlock;
    pthread_mutex_t lock;
} MemoryPool;

void* custom_alloc(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (size > pool->blockSize || !pool->memoryBlock) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *ptr = pool->memoryBlock;
    pool->memoryBlock = realloc(pool->memoryBlock, size + ((char*)pool->memoryBlock - (char*)ptr));
    if (!pool->memoryBlock) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void* initialize_memory(size_t arraySize, int dataType, int rangeMin, int rangeMax, MemoryPool *pool) {
    void *data = custom_alloc(pool, sizeof(long) * arraySize); // Adjust type accordingly
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < arraySize; ++i) {
        switch (dataType) {
            case 1: { // long offsets
                ((long*)data)[i] = rand() % (rangeMax - rangeMin + 1) + rangeMin;
                break;
            }
            case 2: { // int keys
                ((int*)data)[i] = rand() % (rangeMax - rangeMin + 1) + rangeMin;
                break;
            }
            case 3: { // Record structures
                Record *record = &((Record*)data)[i];
                record->value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
                record->floatingPointNumber = (double)(rand()) / RAND_MAX * (rangeMax - rangeMin + 1) + rangeMin;
                break;
            }
            case 4: { // Char strings
                char *str = &(((char**)data)[i][0]);
                for (int j = 0; j < MAX_STRING_LENGTH; ++j) {
                    str[j] = rand() % 26 + 'A';
                }
                break;
            }
            case 5: { // Point objects
                Point *point = &((Point*)data)[i];
                point->x = (float)(rand()) / RAND_MAX * (rangeMax - rangeMin + 1) + rangeMin;
                point->y = (float)(rand()) / RAND_MAX * (rangeMax - rangeMin + 1) + rangeMin;
                break;
            }
            case 6: { // Geometry structures
                Geometry *geometry = &((Geometry*)data)[i];
                geometry->dValue = (double)(rand()) / RAND_MAX * (rangeMax - rangeMin + 1) + rangeMin;
                for (int j = 0; j < MAX_STRING_LENGTH; ++j) {
                    geometry->str[j] = rand() % 26 + 'A';
                }
                geometry->p.x = (float)(rand()) / RAND_MAX * (rangeMax - rangeMin + 1) + rangeMin;
                geometry->p.y = (float)(rand()) / RAND_MAX * (rangeMax - rangeMin + 1) + rangeMin;
                break;
            }
        }
    }

    return data;
}

MemoryPool* create_memory_pool(size_t blockSize, size_t blockCount) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->blockSize = blockSize;
    pool->memoryBlock = malloc(blockCount * blockSize);

    if (!pool->memoryBlock) {
        free(pool);
        fprintf(stderr, "Failed to initialize memory block for the pool\n");
        return NULL;
    }

    return pool;
}

void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->memoryBlock);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int main() {
    size_t arraySize = 1000;
    int rangeMin = 1, rangeMax = 100;

    MemoryPool *pool = create_memory_pool(1024, 10);
    if (!pool) return EXIT_FAILURE;

    void* data = initialize_memory(arraySize, 3 /* Record type */, rangeMin, rangeMax, pool);
    if (data) {
        // Use the allocated and initialized memory
    }

    free_memory_pool(pool);

    return EXIT_SUCCESS;
}
```

### Key Features:
- **Custom Memory Pool**: Uses a simple custom allocator for efficient memory management.
- **Thread-Safety**: Mutexes protect access to shared resources, ensuring thread-safe operations.
- **Dynamic Initialization**: Initializes structures with random values within specified ranges.
- **Error Handling**: Handles allocation failures and logs errors accordingly.
- **Scalability**: Designed to handle varying data sizes through dynamic parameter specification.

This code provides a foundation for building scalable, high-performance applications that manage complex data structures efficiently.']

