  externalSystemConfigs: [
    { name: 'LoggingService', endpoint: '/log' },
    { name: 'MonitoringService', endpoint: '/monitor' }
  ],
  batchSize: 5
};

const manager = new ScriptManager(options);
manager.manageScripts([
  // Dataset of script objects
]);
