void example_operation(void *data) {
    record *rec = (record*) data;
    printf("Operating on record with value: %d\n", rec->value);
}

// Serialize records to binary format
size_t serialize_records(record *records, size_t count, unsigned char **output) {
    size_t total_size = sizeof(size_t) + count * (sizeof(int) + strlen(records[0].str_value) + 1 + sizeof(void*));
    *output = malloc(total_size);

    if (!*output) return 0;

    unsigned char *ptr = *output;
    memcpy(ptr, &count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &(records[i].value), sizeof(int));
        ptr += sizeof(int);

        size_t str_len = strlen(records[i].str_value) + 1;
        memcpy(ptr, records[i].str_value, str_len);
        ptr += str_len;

        void *func_ptr = (void*)records[i].operation;
        memcpy(ptr, &func_ptr, sizeof(void*));
        ptr += sizeof(void*);
    }

    return total_size;
}

// Deserialize binary format to records
size_t deserialize_records(unsigned char *input, record **records) {
    size_t count;
    memcpy(&count, input, sizeof(size_t));
    input += sizeof(size_t);

    *records = malloc(count * sizeof(record));

    for (size_t i = 0; i < count; ++i) {
        unsigned char *ptr = input;

        memcpy(&( (*records)[i].value ), ptr, sizeof(int));
        ptr += sizeof(int);

        int_to_str((*records)[i].value, ((*records)[i].str_value));

        void **func_ptr = (void**)&((*records)[i].operation);
        memcpy(func_ptr, ptr, sizeof(void*));
        ptr += sizeof(void*);
    }

    return count;
}

// Thread-safe function to allocate and initialize arrays
record *allocate_and_initialize(int record_count, long *offsets, int *keys) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for offsets and keys
    offsets = malloc(record_count * sizeof(long));
    keys = malloc(record_count * sizeof(int));

    if (!offsets || !keys) {
        free(offsets); free(keys);
        return NULL;
    }

    record *records = malloc(record_count * sizeof(record));
    if (!records) {
        free(offsets); free(keys);
        return NULL;
    }

    // Initialize records with random values and example operation
    srand(time(NULL)); // Seed for randomness

    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; ++i) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 1000;

        records[i].value = rand() % 1000; // Random value within range
        int_to_str(records[i].value, records[i].str_value);
        records[i].operation = example_operation;
    }
    pthread_mutex_unlock(&lock);

    return records;
}

// Free allocated memory safely
void free_resources(long *offsets, int *keys, record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
```']

['Below is a C implementation for managing dynamic lists of `DeviceSession` structures with thread-safe operations in a multi-threaded environment, cryptographic functionalities using OpenSSL, and geometric object handling:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/ecdsa.h>
#include <openssl/sha.h>

typedef struct {
    double x;
    double y;
} point_t;

typedef struct {
    double area;
    char *description;
    point_t centroid;
} Shape;

typedef struct PacketFlow {
    unsigned char data[64];
    size_t length;
    struct PacketFlow *next;
} PacketFlow;

typedef struct {
    int qos_id;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    size_t key_len;
} QoSProfile;

typedef struct DeviceSession {
    char *DeviceID;
    PacketFlow *packet_list;
    QoSProfile *qos_profiles;
    size_t qos_count;
    pthread_mutex_t lock;
} DeviceSession;

void init_crypto() {
    EVP_add_cipher(&aes);
    EVP_add_digest(&sha256);
}

DeviceSession* create_device_session(const char *device_id) {
    DeviceSession *session = (DeviceSession *)calloc(1, sizeof(DeviceSession));
    if (!session) return NULL;

    session->DeviceID = strdup(device_id);
    pthread_mutex_init(&session->lock, NULL);

    // Assume a fixed number of QoS profiles for simplicity
    const size_t qos_count = 5;
    session->qos_profiles = (QoSProfile *)malloc(qos_count * sizeof(QoSProfile));
    if (!session->qos_profiles) {
        free(session);
        return NULL;
    }
    session->qos_count = qos_count;

    // Initialize cryptographic primitives
    init_crypto();

    return session;
}

void log_operation(const char *message) {
    pthread_mutex_t log_lock;
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    pthread_once(&once, []() { pthread_mutex_init(&log_lock, NULL); });

    pthread_mutex_lock(&log_lock);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_lock);
}

void free_device_session(DeviceSession *session) {
    if (!session) return;

    pthread_mutex_destroy(&session->lock);

    free(session->DeviceID);
    PacketFlow *packet = session->packet_list;
    while (packet) {
        PacketFlow *next = packet->next;
        free(packet);
        packet = next;
    }

    free(session->qos_profiles);
    free(session);
}

void* handle_shape(void *arg) {
    Shape *shape = (Shape *)arg;

    // Example shape description and area
    strcpy(shape->description, "Circle");
    shape->area = 3.14159; // Example for circle with radius 1

    shape->centroid.x = 0.5;
    shape->centroid.y = 0.5;

    return NULL;
}

int main() {
    DeviceSession *session = create_device_session("Device_1234");
    if (!session) {
        fprintf(stderr, "Failed to create device session\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    Shape shape;
    pthread_create(&thread_id, NULL, handle_shape, &shape);
    pthread_join(thread_id, NULL);

    log_operation("DeviceSession and Shape initialized");

    free_device_session(session);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Each `DeviceSession` includes a mutex for thread-safe operations.
- **Cryptographic Primitives**: Initialized using OpenSSL's EVP functions.
- **Logging**: Implemented with mutex protection to ensure thread safety.
- **Memory Management**: Uses dynamic memory allocation, ensuring proper cleanup to prevent leaks.
- **Concurrency**: Handles concurrent access to shape attributes using threading.

This implementation provides a foundation for managing device sessions and cryptographic operations while considering performance and scalability. Adjustments can be made based on specific requirements and constraints of the IoT platform.']

