#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int payer;
    int payee;
    double amount;
} PaymentRecord;

typedef struct {
    char TransactionID[20];
    time_t timestamp;
    PaymentRecord *paymentRecords;
    size_t paymentCount;
    double TotalAmount; // Total transaction amount
    pthread_mutex_t lock; // For thread safety
} TransactionLog;

void calculateTotalAmount(TransactionLog *transaction) {
    if (transaction == NULL || transaction->paymentRecords == NULL) return;

    pthread_mutex_lock(&transaction->lock);

    double total = 0.0;
    for (size_t i = 0; i < transaction->paymentCount; ++i) {
        total += transaction->paymentRecords[i].amount;
    }

    // Assuming some error margin adjustments can be done here if needed
    transaction->TotalAmount = total;

    pthread_mutex_unlock(&transaction->lock);
}

void handleTransactionLogs(TransactionLog **logs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        calculateTotalAmount(logs[i]);
    }
}

// Example of a function to initialize transaction logs
void initTransactionLog(TransactionLog *log, const char *transactionID, time_t timestamp, PaymentRecord *records, size_t paymentCount) {
    snprintf(log->TransactionID, sizeof(log->TransactionID), "%s", transactionID);
    log->timestamp = timestamp;
    log->paymentRecords = records;
    log->paymentCount = paymentCount;
    log->TotalAmount = 0.0;
    pthread_mutex_init(&log->lock, NULL);
}

// Example cleanup function
void freeTransactionLog(TransactionLog *log) {
    if (log != NULL) {
        pthread_mutex_destroy(&log->lock);
        // Assuming dynamic allocation for PaymentRecords, it should be freed here.
    }
}

int main() {
    size_t numTransactions = 3;
    TransactionLog *transactionLogs[numTransactions];

    // Example initialization
    PaymentRecord records1[] = {{1, 2, 100.5}, {3, 4, 200.75}};
    TransactionLog log1;
    initTransactionLog(&log1, "TXN123", time(NULL), records1, sizeof(records1) / sizeof(PaymentRecord));
    transactionLogs[0] = &log1;

    PaymentRecord records2[] = {{5, 6, 300.25}, {7, 8, 400.50}};
    TransactionLog log2;
    initTransactionLog(&log2, "TXN124", time(NULL), records2, sizeof(records2) / sizeof(PaymentRecord));
    transactionLogs[1] = &log2;

    PaymentRecord records3[] = {{9, 10, 500.75}, {11, 12, 600.25}};
    TransactionLog log3;
    initTransactionLog(&log3, "TXN125", time(NULL), records3, sizeof(records3) / sizeof(PaymentRecord));
    transactionLogs[2] = &log3;

    // Handle all logs
    handleTransactionLogs(transactionLogs, numTransactions);

    // Print results
    for (size_t i = 0; i < numTransactions; ++i) {
        printf("Transaction ID: %s, Total Amount: %.2f\n", transactionLogs[i]->TransactionID, transactionLogs[i]->TotalAmount);
    }

    // Cleanup
    freeTransactionLog(transactionLogs[0]);
    freeTransactionLog(transactionLogs[1]);
    freeTransactionLog(transactionLogs[2]);

    return 0;
}
