// C# interop for generating MD5 hash
#ifdef __cplusplus_cli
#pragma managed(push, off)

#import "System.Security.Cryptography.CryptographicServices.dll"
using namespace System::Security::Cryptography;

String^ generateMD5Hash(String^ input) {
    MD5 md5 = gcnew MD5();
    array<unsigned char>^ data = md5->ComputeHash(System::Text::Encoding::UTF8->GetBytes(input));
    StringBuilder^ sBuilder = gcnew StringBuilder();

    for (int i = 0; i < data->Length; i++) {
        sBuilder->Append(data[i].ToString("x2"));
    }

    return sBuilder->ToString();
}

#pragma managed(pop)
#endif

