void processImage(const char* imagePath) {
    MagickWand *magick_wand = NULL;
    MagickBooleanType status;

    // Initialize ImageMagick's environment
    MagickWandGenesis();

    magick_wand = NewMagickWand();
    if (magick_wand == NULL) {
        logError("Failed to initialize MagickWand");
        return;
    }

    // Read image from file
    status = MagickReadImage(magick_wand, imagePath);
    if (status == MagickFalse) {
        logError("Failed to read image");
        magick_wand = DestroyMagickWand(magick_wand);
        return;
    }

    // Validate image integrity using checksums
    validateImageIntegrity(magick_wand);

    // Process the image: resize and convert format
    status = MagickResizeImage(magick_wand, 800, 600, LanczosFilter, 1.0); // Example resizing
    if (status == MagickFalse) {
        logError("Failed to resize image");
        magick_wand = DestroyMagickWand(magick_wand);
        return;
    }

    status = MagickSetImageFormat(magick_wand, "JPEG"); // Convert format
    if (status == MagickFalse) {
        logError("Failed to convert image format");
        magick_wand = DestroyMagickWand(magick_wand);
        return;
    }

    // Write the processed image back
    char outputPath[1024];
    snprintf(outputPath, sizeof(outputPath), "%s_output.jpg", basename(imagePath));
    status = MagickWriteImage(magick_wand, outputPath);
    if (status == MagickFalse) {
        logError("Failed to write image");
