    // Start a thread for watching the directory
    if (pthread_create(&watcher_thread, NULL, directoryWatcher, (void *)directoryPath) != 0) {
        logError("Failed to create directory watcher thread");
    }

    while ((entry = readdir(dir)) != NULL) {
        char filePath[1024];
        snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, entry->d_name);

        struct stat fileStat;
        if (stat(filePath, &fileStat) == 0 && S_ISREG(fileStat.st_mode)) {
            // Process images based on dynamic priority
            processImage(filePath);
        }
    }

    closedir(dir);

    pthread_join(watcher_thread, NULL); // Ensure watcher thread completes

    MagickWandTerminus();
}

