<?php

function updateWeatherDataWithCaching($locations) {
    $cache = new Cache(); // Assume Cache is a class handling both in-memory and disk-based caching
    $dbConnection = new PDO('mysql:host=localhost;dbname=weather', 'username', 'password');

    foreach ($locations as $location) {
        if (($data = $cache->get($location)) === false) {
            $apiKey = 'YOUR_API_KEY';
            $url = "http://api.weather.com/v3/wx/conditions/current?location={$location}&format=json&apiKey={$apiKey}";

            $weatherData = file_get_contents($url);
            if ($weatherData !== FALSE) {
                $data = json_decode($weatherData, true);

                // Update database
                $stmt = $dbConnection->prepare('REPLACE INTO weather_data (location, temperature, humidity, wind_speed) VALUES (:location, :temperature, :humidity, :wind_speed)');
                $stmt->execute([
                    ':location' => $data['location'],
                    ':temperature' => $data['temperature'],
                    ':humidity' => $data['humidity'],
                    ':wind_speed' => $data['wind_speed']
                ]);

                // Cache data
                $cache->set($location, $data, 3600); // Cache for 1 hour
            }
        }

        if (isset($data)) {
            echo "Updated weather data for {$location}: Temperature - {$data['temperature']}°C, Humidity - {$data['humidity']}%, Wind Speed - {$data['wind_speed']} km/h\n";
        } else {
            echo "Failed to update weather data for {$location}.\n";
        }
    }
}

