#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    char *pool;
    size_t pool_size;
    pthread_mutex_t lock;
    size_t offset;
} MemoryPool;

#define MEMORY_POOL_SIZE 1024 * 1024

MemoryPool* create_memory_pool() {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->pool = malloc(MEMORY_POOL_SIZE);
    mp->pool_size = MEMORY_POOL_SIZE;
    pthread_mutex_init(&mp->lock, NULL);
    mp->offset = 0;
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->offset + size > mp->pool_size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Out of memory
    }
    void *ptr = mp->pool + mp->offset;
    mp->offset += size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

