// Metric structure with float values
struct Metric {
    float value;
};

// Data processing engine class
class DataProcessingEngine {
public:
    DataProcessingEngine(size_t doubleArraySize, size_t charArraySize)
        : state_(State::Stopped), pool_(), doubleArray_(new (pool_.allocate(sizeof(double) * doubleArraySize)) double[doubleArraySize]),
          charArray_(new (pool_.allocate(sizeof(char) * charArraySize)) char[charArraySize]) {

        // Initialize metrics with random values
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<float> dis(0.0, 1.0);

        for (auto& metric : metrics_) {
            metric.value = static_cast<float>(dis(gen));
        }
    }

    ~DataProcessingEngine() {
        pool_.deallocate(doubleArray_, sizeof(double) * doubleArraySize_);
        pool_.deallocate(charArray_, sizeof(char) * charArraySize_);
    }

    void start(size_t delay_ms) {
        std::lock_guard<std::mutex> lock(mutex_);
        state_ = State::Running;
        worker_thread_ = std::thread(&DataProcessingEngine::run, this, delay_ms);
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (state_ == State::Stopped) return;
            state_ = State::Stopped;
            cv_.notify_all();
        }
        if (worker_thread_.joinable()) worker_thread_.join();
    }

    void pause(size_t delay_ms) {
        std::lock_guard<std::mutex> lock(mutex_);
        state_ = State::Paused;
        cv_.wait_for(lock, std::chrono::milliseconds(delay_ms));
    }

private:
    enum class State { Running, Paused, Stopped };

    void run(size_t delay_ms) {
        while (state_ == State::Running) {
            process();
            if (state_ == State::Paused) {
                std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms));
            }
        }
    }

    void process() {
        // Placeholder for data processing logic
        std::cout << "Processing data...\n";
        retryLogic();
    }

    void retryLogic() {
        int retries = 3;
        while (retries-- > 0) {
            try {
                // Simulate data ingestion operation
                if (std::rand() % 2 == 0) throw std::runtime_error("Transient failure");
                break; // Success
            } catch (...) {
                if (retries == 0) {
                    std::cerr << "Operation failed after retries\n";
                }
            }
        }
    }

    State state_;
    MemoryPool pool_;
    double* doubleArray_;
    char* charArray_;
    size_t doubleArraySize_ = 100;
    size_t charArraySize_ = 50;
    std::vector<Metric> metrics_ = {Metric(), Metric(), Metric()};
    std::thread worker_thread_;
    std::mutex mutex_;
