    manager->count = 0;
    manager->records = (ActivityRecord*)allocate_memory(manager->capacity * sizeof(ActivityRecord));
    pthread_mutex_init(&manager->lock, NULL);

    if (!manager->records) {
        log_activity("Failed to allocate memory for records");
        free(manager);
        return NULL;
