    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity * RESIZE_THRESHOLD) {
        resize_activities(manager);
    }

    ActivityRecord record = {location, timestamp, status};
    manager->records[manager->count++] = record;

    log_activity("Activity added");

    pthread_mutex_unlock(&manager->lock);
}

void resize_activities(ActivityManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    ActivityRecord* new_records = (ActivityRecord*)allocate_memory(new_capacity * sizeof(ActivityRecord));
    if (!new_records) {
        log_activity("Failed to allocate memory for resizing activities");
        return;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        new_records[i] = manager->records[i];
    }

    deallocate_memory(manager->records);
    manager->records = new_records;
    manager->capacity = new_capacity;

