typedef struct {
    float x;
    float y;
} Point;

// Define enum status for events
enum Status { ACTIVE, INACTIVE };

// Define struct event containing timestamp, id, and status
typedef struct {
    time_t timestamp;
    int id;
    enum Status status;
} Event;

#define POOL_SIZE 1024 * 1024 // 1MB pool size

// Memory Pool Structure
typedef struct {
    void* memory;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_memory_pool() {
    pool.memory = malloc(POOL_SIZE);
    if (!pool.memory) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pool.size = POOL_SIZE;
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool.lock);

    if (size > pool.size) {
        pthread_mutex_unlock(&pool.lock);
        return NULL; // Not enough space
    }

    void* ptr = pool.memory;
    pool.memory = ((char*)pool.memory) + size;
    pool.size -= size;

    pthread_mutex_unlock(&pool.lock);
    return ptr;
}

void free_memory_pool() {
    free(pool.memory);
    pool.memory = NULL;
    pool.size = 0;
}

// Function to initialize points with random values
Point* create_points(size_t count) {
    Point* points = (Point*)allocate_from_pool(count * sizeof(Point));
    if (!points) return NULL;

    for (size_t i = 0; i < count; ++i) {
        points[i].x = ((float)rand() / RAND_MAX) * 100.0f;
        points[i].y = ((float)rand() / RAND_MAX) * 100.0f;
    }
    return points;
}

// Thread-safe function to count lines in a file
typedef struct {
    const char* filepath;
    long* line_count;
} FileTask;

void* count_lines(void* arg) {
    FileTask* task = (FileTask*)arg;
    FILE* file = fopen(task->filepath, "r");
    if (!file) return NULL;

    long lines = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        ++lines;
    }
    fclose(file);

    pthread_mutex_t count_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&count_lock);
    *task->line_count = lines;
    pthread_mutex_unlock(&count_lock);
    pthread_mutex_destroy(&count_lock);

    return NULL;
}

// Main function to manage memory and process files
void manage_memory_and_files() {
    initialize_memory_pool();

    // Create data structures
    double* doubles_array = (double*)allocate_from_pool(100 * sizeof(double));
    char* chars_array = (char*)allocate_from_pool(256);
    Point* points = create_points(50);

    Event* events_array = (Event*)allocate_from_pool(10 * sizeof(Event));

    // Setup thread for file processing
    pthread_t threads[10];
    long line_counts[10] = {0};
    char filepath[256];

    while (scanf("%255s", filepath) == 1) {
        FileTask* task = allocate_from_pool(sizeof(FileTask));
        if (!task) break;

        task->filepath = strdup(filepath);
        task->line_count = &line_counts[strlen(line_counts)];

        pthread_create(&threads[strlen(threads)], NULL, count_lines, task);

        // Example: Join threads for demonstration; in practice, manage joining as needed
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (threads[i]) pthread_join(threads[i], NULL);
    }

    free_memory_pool();
}

int main() {
    srand(time(NULL));
    manage_memory_and_files();
    return 0;
}
