typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t size;
    pthread_mutex_t mutex; // For thread safety
} memory_pool;

memory_pool* create_memory_pool(size_t size) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->offsets = (long*)calloc(size, sizeof(long));
    pool->keys = (int*)calloc(size, sizeof(int));
    pool->records = (record*)calloc(size, sizeof(record));
    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);
    pool->size = size;

    // Initialize records with random values
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        pool->records[i].value = rand() % 100 + 1;
    }

    return pool;
}

void free_memory_pool(memory_pool* pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->mutex);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
}

