// Companion function to append a slash or return NULL based on size limit
char* append_slash_if_fits(const char* input, size_t size_limit) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&mutex);

    size_t input_length = strlen(input);
    if (input_length >= size_limit) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    char* result = (char*)malloc(size_limit + 1); // +1 for slash and null terminator
    if (!result) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    strncpy(result, input, size_limit - 1);
    result[size_limit - 1] = '/';
    result[size_limit] = '\0';

    pthread_mutex_unlock(&mutex);
    return result;
}

