fn create_directory_with_status_file(
    dir_name: String,
    override_env_var: bool,
    env_var_key: String,
) -> io::Result<()> {
    let path = Path::new(&dir_name);

    // Create directory with atomic operation to handle race conditions.
    let created = fs::create_dir_all(&path).map_err(|e| {
        eprintln!("Failed to create directory '{}': {}", dir_name, e);

        // Integrate with logging service
        let log_service = DataIngestionService;
        if let Err(_) = log_service.log_error(&format!(
            "Error creating directory {}: {}",
            dir_name,
            e
        ))
        .await {
            eprintln!("Failed to log error for directory creation");
        }

        io::Error::new(io::ErrorKind::Other, e)
    })?;

    if !created.metadata()?.is_dir() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "Path is not a directory after creation",
        ));
    }

    let env_var = Arc::new(Mutex::new(env::var(env_var_key.clone()).ok()));

    // Use thread to handle environment variable setting
    {
        let env_var_clone = env_var.clone();
        thread::spawn(move || {
            let mut var_guard = env_var_clone.lock().unwrap();

            if *var_guard.is_none() || override_env_var {
                let client = ConfigManagementServiceClient;

                // Set and propagate environment variable
                match client.update_env_variable(&env_var_key, &dir_name) {
                    Ok(_) => {
                        *var_guard = Some(dir_name);
                    }
                    Err(e) => {
                        eprintln!("Failed to update environment variable '{}': {}", env_var_key, e);

                        // Integrate with monitoring service for critical errors
                        let monitor_client = MonitoringServiceClient;
                        monitor_client.alert_administrator(&format!(
                            "Critical: Failed to update environment variable {}: {}",
                            env_var_key,
                            e
                        ));
                    }
                }
            }
        });
    }

    if path.join("status.txt").exists() {
        return Ok(());
    }

    // Atomic operation for file creation and initialization
    let mut status_file = match File::options()
        .write(true)
        .create_new(true)
        .open(&path.join("status.txt")) {
            Ok(file) => file,
            Err(e) => {
                eprintln!("Failed to create 'status.txt' in '{}': {}", dir_name, e);

                // Log and monitor critical errors
                let log_service = DataIngestionService;
                if let Err(_) = log_service.log_error(&format!(
                    "Error creating 'status.txt' in {}: {}",
                    dir_name,
                    e
                ))
                .await {
                    eprintln!("Failed to log error for status file creation");
                }

                return Err(io::Error::new(
                    io::ErrorKind::Other,
                    format!("Failed to create 'status.txt': {}", e),
                ));
            }
        };

    let current_time = SystemTime::now().duration_since(SystemTime::UNIX_EPOCH)
        .map_err(|_| io::Error::new(io::ErrorKind::Other, "System time error"))?
        .as_secs();

    if let Err(e) = writeln!(status_file, "Initialized at: {}", current_time) {
        eprintln!("Failed to write to 'status.txt' in '{}': {}", dir_name, e);

        // Log and monitor critical errors
        let log_service = DataIngestionService;
        if let Err(_) = log_service.log_error(&format!(
            "Error writing to 'status.txt' in {}: {}",
            dir_name,
            e
        ))
        .await {
            eprintln!("Failed to log error for status file writing");
        }

        return Err(io::Error::new(
            io::ErrorKind::Other,
            format!("Failed to write to 'status.txt': {}", e),
        ));
    }

    Ok(())
}

