#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define INITIAL_POOL_SIZE 1024

typedef struct {
    int value;
} record_t;

// Define the memory pool structure.
typedef struct MemoryPool {
    void *pool;
    size_t total_size;
    atomic_size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->total_size = initial_size;
    mp->used_size = 0;
    mp->pool = malloc(mp->total_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* allocate_from_pool(MemoryPool *mp, size_t size) {
    if (size > mp->total_size - atomic_load(&mp->used_size)) {
        // Resize pool logic.
        size_t new_size = mp->total_size + INITIAL_POOL_SIZE; 
        void *new_pool = realloc(mp->pool, new_size);
        if (!new_pool) return NULL;

        pthread_mutex_lock(&mp->lock);
        mp->total_size = new_size;
        pthread_mutex_unlock(&mp->lock);
    }

    size_t offset = atomic_fetch_add(&mp->used_size, size);

    return (char *)mp->pool + offset;
}

void free_memory_pool(MemoryPool *mp) {
    if (!mp) return;

    pthread_mutex_destroy(&mp->lock);
    free(mp->pool);
    free(mp);
}

// Array structure
typedef struct DynamicArray {
    void *data;
    size_t capacity;
    size_t element_size;
} DynamicArray;

void init_dynamic_array(DynamicArray *array, size_t initial_capacity, size_t element_size) {
    array->capacity = initial_capacity;
    array->element_size = element_size;
    array->data = malloc(initial_capacity * element_size);
}

void resize_dynamic_array(DynamicArray *array) {
    // Double the capacity for linear expansion
    size_t new_capacity = array->capacity * 2;
    void *new_data = realloc(array->data, new_capacity * array->element_size);

    if (new_data) {
        array->data = new_data;
        array->capacity = new_capacity;
    } else {
        fprintf(stderr, "Failed to resize dynamic array\n");
        // Handle error appropriately
    }
}

void free_dynamic_array(DynamicArray *array) {
    free(array->data);
}

// Main function to initialize arrays
void* init_arrays(size_t initial_long_count, size_t initial_int_count, size_t initial_record_count) {
    MemoryPool *mp = create_memory_pool(INITIAL_POOL_SIZE);

    if (!mp) return NULL;

    DynamicArray long_array, int_keys, record_array;
    init_dynamic_array(&long_array, initial_long_count, sizeof(long));
    init_dynamic_array(&int_keys, initial_int_count, sizeof(int));
    init_dynamic_array(&record_array, initial_record_count, sizeof(record_t));

    // Fill arrays with example data
    for (size_t i = 0; i < long_array.capacity; ++i) {
        ((long *)long_array.data)[i] = (long)i;
    }
    for (size_t i = 0; i < int_keys.capacity; ++i) {
        ((int *)int_keys.data)[i] = (int)i;
    }
    for (size_t i = 0; i < record_array.capacity; ++i) {
        ((record_t *)record_array.data)[i].value = (int)i;
    }

    // Provide a means to free all allocated resources
    void (*deallocator)(DynamicArray *, MemoryPool *) = [](DynamicArray *array, MemoryPool *mp) {
        free_dynamic_array(array);
        free_memory_pool(mp);
    };

    return deallocator;  // Return the cleanup function for use later
}

int main() {
    size_t initial_long_count = 10;
    size_t initial_int_count = 10;
    size_t initial_record_count = 10;

    void (*cleanup)(DynamicArray *, MemoryPool *) = init_arrays(initial_long_count, initial_int_count, initial_record_count);

    if (cleanup) cleanup(NULL, NULL); // Example usage; normally you'd store and use the arrays here

    return 0;
}
