#ifndef MEMORY_POOL_H
#define MEMORY_POOL_H

#include <stdlib.h>
#include <pthread.h>

typedef struct {
    size_t block_size;
    size_t num_blocks;
    void *pool;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks);
void* pool_alloc(MemoryPool *mp);
void release_memory_pool(MemoryPool **mp);

#endif // MEMORY_POOL_H
```

**memory_pool.c**
```c
#include "memory_pool.h"
#include <string.h>

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->num_blocks = num_blocks;
    mp->pool = calloc(num_blocks, block_size);
    pthread_mutex_init(&mp->lock, NULL);

    return mp;
}

void* pool_alloc(MemoryPool *mp) {
    if (!mp) return NULL;
    pthread_mutex_lock(&mp->lock);

    // Simple allocation strategy
    static size_t next_free = 0;
    void *block = (char*)mp->pool + next_free * mp->block_size;

    if ((next_free + 1) < mp->num_blocks) {
        next_free++;
    } else {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Pool exhausted
    }

    pthread_mutex_unlock(&mp->lock);
    return block;
}

void release_memory_pool(MemoryPool **mp) {
    if (!mp || !*mp) return;

    MemoryPool *temp = *mp;
    free(temp->pool);
    pthread_mutex_destroy(&temp->lock);
    free(temp);
    *mp = NULL;
}
