#include "record.h"
#include <stdlib.h>
#include <time.h>

static pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

Record* create_record(MemoryPool *mp, int min_val, int max_val) {
    Record *r = (Record*)pool_alloc(mp);
    if (!r) return NULL;

    r->value = rand() % (max_val - min_val + 1) + min_val;

    return r;
}

void serialize_record(const Record *r, uint8_t **buffer, size_t *size) {
    if (!r || !buffer || !size) return;

    *size = sizeof(int);
    *buffer = malloc(*size);

    if (*buffer) {
        memcpy(*buffer, &r->value, *size);
    }
}

int deserialize_record(Record *r, const uint8_t *buffer, size_t size) {
    if (!r || !buffer || size != sizeof(int)) return -1;

    memcpy(&r->value, buffer, size);
    return 0;
}
