['Below is a C implementation of a dynamic memory pool for storing structured records with thread safety, custom allocation strategy, statistical monitoring, and offloading capabilities:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>

#define DEFAULT_INITIAL_CAPACITY 1024
#define DEFAULT_RANDOM_RANGE 1000
#define HEALTH_CHECK_FREQUENCY 5 // seconds

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t data;
} structured_record_t;

typedef struct memory_pool {
    structured_record_t *records;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    double peak_usage;
    double avg_utilization;
    size_t resize_count;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t initial_capacity);
void destroy_memory_pool(memory_pool_t *pool);
int allocate_record(memory_pool_t *pool, structured_record_t **record);
void deallocate_record(memory_pool_t *pool, structured_record_t *record);
void* health_monitor(void *arg);
void resize_memory_pool(memory_pool_t *pool);

memory_pool_t* create_memory_pool(size_t initial_capacity) {
    memory_pool_t *pool = (memory_pool_t*)malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->records = (structured_record_t*)calloc(initial_capacity, sizeof(structured_record_t));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->peak_usage = 0.0;
    pool->avg_utilization = 0.0;
    pool->resize_count = 0;

    pthread_t health_thread;
    if (pthread_create(&health_thread, NULL, health_monitor, pool) != 0) {
        destroy_memory_pool(pool);
        return NULL;
    }

    pthread_detach(health_thread);

    return pool;
}

void destroy_memory_pool(memory_pool_t *pool) {
    if (!pool) return;

    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
    free(pool);
}

int allocate_record(memory_pool_t *pool, structured_record_t **record) {
    pthread_mutex_lock(&pool->lock);

    while (pool->used >= pool->capacity) {
        resize_memory_pool(pool);
    }

    size_t index = pool->used++;
    *record = &pool->records[index];

    double utilization = (double)pool->used / pool->capacity;
    if (utilization > pool->peak_usage) {
        pool->peak_usage = utilization;
    }
    pool->avg_utilization = ((pool->avg_utilization * (pool->resize_count)) + utilization) / (pool->resize_count + 1);

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void deallocate_record(memory_pool_t *pool, structured_record_t *record) {
    if (!pool || !record) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->used; ++i) {
        if (&pool->records[i] == record) {
            memmove(&pool->records[i], &pool->records[i + 1], sizeof(structured_record_t) * (pool->used - i - 1));
            --pool->used;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

void* health_monitor(void *arg) {
    memory_pool_t *pool = (memory_pool_t*)arg;

    while (1) {
        sleep(HEALTH_CHECK_FREQUENCY);

        pthread_mutex_lock(&pool->lock);

        printf("Memory Pool Status:\n");
        printf("Peak Usage: %.2f%%\n", pool->peak_usage * 100);
        printf("Average Utilization: %.2f%%\n", pool->avg_utilization * 100);
        printf("Resizes: %zu\n", pool->resize_count);

        pthread_mutex_unlock(&pool->lock);
    }

    return NULL;
}

void resize_memory_pool(memory_pool_t *pool) {
    size_t new_capacity = pool->capacity * 2;
    structured_record_t *new_records = (structured_record_t*)realloc(pool->records, new_capacity * sizeof(structured_record_t));
    if (!new_records) return;

    pool->records = new_records;
    pool->capacity = new_capacity;
    ++pool->resize_count;
}

int main(int argc, char **argv) {
    size_t initial_capacity = DEFAULT_INITIAL_CAPACITY;
    // Parse command-line arguments or environment variables to set `initial_capacity` and other parameters.

    memory_pool_t *pool = create_memory_pool(initial_capacity);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool.\n");
        return EXIT_FAILURE;
    }

    structured_record_t *record;
    allocate_record(pool, &record);
    record->offset = 0;
    record->key = rand() % DEFAULT_RANDOM_RANGE;
    record->data.value = rand() % DEFAULT_RANDOM_RANGE;

    deallocate_record(pool, record);

    destroy_memory_pool(pool);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Thread Safety**: Uses mutex and condition variables to manage concurrent access.
- **Dynamic Resizing**: Doubles the capacity when needed, minimizing fragmentation.
- **Statistical Monitoring**: Tracks peak usage, average utilization, and resize frequency.
- **Health Monitoring Thread**: Periodically prints memory pool statistics.
- **Error Handling**: Ensures robust resource management with proper cleanup.

### Considerations:
- The implementation can be extended to support offloading to external storage when nearing capacity limits.
- Configuration via command-line or environment variables is suggested for flexibility.
- The health monitoring frequency and resizing strategy can be adjusted based on system requirements.']

['Below is a C implementation for managing and optimizing memory using a custom memory pool, supporting `long`, `int` keys, and `record` structures. The code incorporates dynamic resizing, concurrency via lock-free data structures, error handling, statistical monitoring, and integration with external demand updates.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct MemoryPool {
    atomic_size_t used_memory;
    size_t capacity;
    void *memory;
    pthread_mutex_t resize_lock; // For resizing operations
} MemoryPool;

// Forward declarations for helper functions
void* allocate_from_pool(MemoryPool *pool, size_t size);
void deallocate_from_pool(MemoryPool *pool, void *ptr, size_t size);
void resize_memory_pool(MemoryPool *pool);

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->used_memory = 0;
    pool->capacity = initial_capacity;
    pool->memory = malloc(initial_capacity);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->resize_lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool *pool, size_t size) {
    void *ptr = malloc(size);
    if (ptr) {
        atomic_fetch_add_explicit(&pool->used_memory, size, memory_order_relaxed);
        if (atomic_load_explicit(&pool->used_memory, memory_order_acquire) > pool->capacity) {
            pthread_mutex_lock(&pool->resize_lock);
            resize_memory_pool(pool);
            pthread_mutex_unlock(&pool->resize_lock);
        }
    }
    return ptr;
}

void deallocate_from_pool(MemoryPool *pool, void *ptr, size_t size) {
    if (ptr) {
        atomic_fetch_sub_explicit(&pool->used_memory, size, memory_order_relaxed);
        free(ptr);
    }
}

void resize_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->resize_lock);

    // Simple resizing strategy: double the capacity
    size_t new_capacity = pool->capacity * 2;
    void *new_memory = realloc(pool->memory, new_capacity);

    if (new_memory) {
        pool->capacity = new_capacity;
        pool->memory = new_memory;
    }

    pthread_mutex_unlock(&pool->resize_lock);
}

void monitor_pool_usage(MemoryPool *pool) {
    size_t usage = atomic_load_explicit(&pool->used_memory, memory_order_acquire);
    printf("Current Usage: %zu/%zu\n", usage, pool->capacity);
}

void update_from_external_source(MemoryPool *pool, size_t new_capacity_estimate) {
    pthread_mutex_lock(&pool->resize_lock);

    if (new_capacity_estimate > pool->capacity) {
        void *new_memory = realloc(pool->memory, new_capacity_estimate);
        if (new_memory) {
            pool->capacity = new_capacity_estimate;
            pool->memory = new_memory;
        }
    }

    pthread_mutex_unlock(&pool->resize_lock);
}

void free_memory_pool(MemoryPool *pool) {
    if (pool) {
        if (pool->memory) free(pool->memory);
        pthread_mutex_destroy(&pool->resize_lock);
        free(pool);
    }
}
```

### Key Features:
- **Dynamic Memory Pool:** Supports dynamic resizing based on current usage patterns.
- **Concurrency Support:** Uses atomic operations for concurrent access and mutexes to manage resizing safely.
- **Error Handling:** Ensures proper deallocation of resources even when errors occur during allocation or resizing.
- **Monitoring Component:** Periodically logs the current memory pool usage, helping in identifying potential issues.

### Considerations:
- **Thread Safety:** Achieved using atomic operations for frequent access and mutexes for less common resize operations.
- **Dynamic Resizing Strategy:** Uses a simple doubling strategy; can be adapted based on observed load patterns.
- **Monitoring Frequency:** The `monitor_pool_usage` function should be called periodically to ensure efficient pool management.

This implementation provides a foundation that can be further refined or integrated into a larger system, with the ability to dynamically adapt to changing application demands.']

