void initialize_memory_pool(size_t num_elements) {
    mem_pool.capacity = num_elements;
    mem_pool.offsets = malloc(sizeof(long) * num_elements);
    mem_pool.keys = malloc(sizeof(int) * num_elements);
    mem_pool.records = malloc(sizeof(Record) * num_elements);

