        mem_pool.keys[i] = rand() % 1000; // Random int key within range [0, 999]
        mem_pool.records[i].key = rand() % 1000; // Record's int field
    }
}

void cleanup_memory_pool() {
    free(mem_pool.offsets);
    free(mem_pool.keys);
    free(mem_pool.records);

    mem_pool.capacity = 0;
    mem_pool.offsets = NULL;
    mem_pool.keys = NULL;
