SharedIntData* create_shared_int_data(size_t capacity) {
    SharedIntData *shared_data = malloc(sizeof(SharedIntData));
    if (!shared_data) return NULL;

    shared_data->data = malloc(sizeof(int) * capacity);
    if (!shared_data->data) {
        free(shared_data);
        return NULL;
    }

    pthread_mutex_init(&shared_data->lock, NULL);
    pthread_cond_init(&shared_data->cond_var, NULL);

    shared_data->size = 0;
    shared_data->capacity = capacity;
    shared_data->in_use = 0;

    return shared_data;
}

void free_shared_int_data(SharedIntData *shared_data) {
    if (shared_data) {
        pthread_mutex_destroy(&shared_data->lock);
        pthread_cond_destroy(&shared_data->cond_var);

        free(shared_data->data);
        free(shared_data);
    }
}

// Thread function to read data from a network socket
void* network_reader(void *arg) {
    SharedIntData *shared_data = (SharedIntData *) arg;

    // Simulate reading integers from a network socket
    for (int i = 0; i < 100; ++i) { // Simulated loop for reading data
        pthread_mutex_lock(&shared_data->lock);

        if (shared_data->size >= shared_data->capacity) {
            pthread_cond_signal(&shared_data->cond_var);
            pthread_mutex_unlock(&shared_data->lock);
            continue;
        }

        int value = rand() % 1000; // Simulate received network integer
        shared_data->data[shared_data->size++] = value;

        pthread_cond_broadcast(&shared_data->cond_var);
        pthread_mutex_unlock(&shared_data->lock);
    }
    return NULL;
}

// Garbage collection function
void garbage_collector(SharedIntData *shared_data) {
    while (1) {
        pthread_mutex_lock(&gc_lock);

        if (shared_data->in_use) { // If GC is already running, exit to prevent deadlock
            pthread_mutex_unlock(&gc_lock);
            continue;
        }

        shared_data->in_use = 1;

        // Simple garbage collection logic: reset the buffer when full for demonstration purposes.
        if (shared_data->size == shared_data->capacity) {
            memmove(shared_data->data, &shared_data->data[shared_data->size], sizeof(int) * (shared_data->capacity - shared_data->size));
            shared_data->size = 0;
        }

        shared_data->in_use = 0;

        pthread_mutex_unlock(&gc_lock);

        // Sleep to simulate periodic GC
        sleep(5);
    }
}

int main() {
    size_t num_elements = 1000; // Example number of elements

    initialize_memory_pool(num_elements);

    SharedIntData *shared_data = create_shared_int_data(500); // Example capacity
    if (!shared_data) {
