        cleanup_memory_pool();
        return EXIT_FAILURE;
    }

    pthread_t reader_thread;
    pthread_create(&reader_thread, NULL, network_reader, (void *)shared_data);

    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collector, (void *)shared_data);

    // Join threads in a real application
    pthread_join(reader_thread, NULL);
    pthread_cancel(gc_thread); // In practice handle this more gracefully

    free_shared_int_data(shared_data);
    cleanup_memory_pool();

    return EXIT_SUCCESS;
}
