#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a simple memory pool structure for demonstration purposes.
typedef struct {
    size_t block_size;
    void* start;
    pthread_mutex_t lock; // Mutex to protect the memory pool
} MemoryPool;

int processStringWithLimitAndThreadSafeMemoryPool(const char* str, int sizeLimit, char** result, void* pool) {
    if (!str || !result || !pool) return -1;

    MemoryPool* mem_pool = (MemoryPool*)pool;
    size_t len = strlen(str);

    pthread_mutex_lock(&mem_pool->lock); // Lock the memory pool for thread safety

    if (len >= sizeLimit) {
        *result = NULL;
        pthread_mutex_unlock(&mem_pool->lock);
        return -1;
    }

    size_t new_size = len + 2; // For string and null terminator
    char* buffer = malloc(new_size);

    if (!buffer) {
        pthread_mutex_unlock(&mem_pool->lock);
        return -1;
    }

    strncpy(buffer, str, len);
    buffer[len] = '/';
    buffer[len + 1] = '\0';

    *result = buffer;

    pthread_mutex_unlock(&mem_pool->lock); // Unlock after operation
    return 0;
}

// Placeholder for the Node and function types used in the second function.
typedef struct Node Node;
typedef void (*CallbackFunction)(Node*);

// Forward declaration of helper functions
void processDOMHelper(Node* node, const char* selector, CallbackFunction callback, Node** resultArray, int* count, MemoryPool* pool);

int processDOMWithSelectorAndThreadSafety(Node* root, const char* selector, CallbackFunction callback, void* pool) {
    if (!root || !selector || !callback || !pool) return -1;

    MemoryPool* mem_pool = (MemoryPool*)pool;

    Node** resultArray = malloc(sizeof(Node*) * 1024); // Initial capacity
    int count = 0;

    pthread_mutex_lock(&mem_pool->lock);

    if (!resultArray) {
        pthread_mutex_unlock(&mem_pool->lock);
        return -1;
    }

    processDOMHelper(root, selector, callback, resultArray, &count, mem_pool);

    // Resize the array to fit exactly
    Node* finalResult = realloc(resultArray, sizeof(Node*) * count);

    if (!finalResult) {
        free(resultArray);
        pthread_mutex_unlock(&mem_pool->lock);
        return -1;
    }

    pthread_mutex_unlock(&mem_pool->lock);

    // Set the result pointer to point to the array of matched elements
    *result = (char*)finalResult;

    return 0;
}

void processDOMHelper(Node* node, const char* selector, CallbackFunction callback, Node** resultArray, int* count, MemoryPool* pool) {
    if (!node || !selector || !callback) return;

    pthread_mutex_lock(&pool->lock); // Lock for thread safety

    if (callback(node)) { // If the node matches the criteria
        if (*count >= 1024) { // Expand array when necessary, simplistic approach
            Node** temp = realloc(resultArray, sizeof(Node*) * (*count + 1024));
            if (!temp) {
                pthread_mutex_unlock(&pool->lock);
                return;
            }
            resultArray = temp;
        }
        resultArray[(*count)++] = node; // Add matching node to results
    }

    pthread_mutex_unlock(&pool->lock); // Unlock after operation

    for (Node* child = node->firstChild; child; child = child->nextSibling) {
        processDOMHelper(child, selector, callback, resultArray, count, pool);
    }
}
