#define POOL_SIZE 1024

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    size_t size;
    size_t used;
    pthread_mutex_t lock;
    void* memory[POOL_SIZE];
} MemoryPool;

MemoryPool pool = {0};

void initialize_pool() {
    pthread_mutex_init(&pool.lock, NULL);
    for (int i = 0; i < POOL_SIZE; ++i) {
        pool.memory[i] = NULL;
    }
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool.lock);

    if (pool.used + size > sizeof(pool.memory)) {
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    void* ptr = malloc(size);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool.memory[i] == NULL) {
            pool.memory[i] = ptr;
            pool.used += size;
            pthread_mutex_unlock(&pool.lock);
            return ptr;
        }
    }

    free(ptr);
    pthread_mutex_unlock(&pool.lock);
    return NULL;
}

void deallocate_from_pool(void* ptr) {
    pthread_mutex_lock(&pool.lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool.memory[i] == ptr) {
            pool.used -= sizeof(*ptr);
            free(pool.memory[i]);
            pool.memory[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&pool.lock);
}

void initialize_data_structures(size_t longs_count, size_t ints_count, size_t records_count) {
