```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1000
#define MEMORY_BLOCK_SIZE sizeof(struct sensor)
#define MAX_SENSORS 100
#define LOG_BUFFER_SIZE 1024

typedef struct {
    float temperature;
    float humidity;
    time_t timestamp;
} sensor;

typedef struct {
    double *measurements;
    char *status_indicators;
    sensor *records;
    int capacity;
    int count;
    pthread_mutex_t lock;
    FILE *log_file;
} SensorManager;

static void* memory_pool[INITIAL_POOL_SIZE];
static int pool_index = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(SensorManager *manager, const char *message) {
    if (manager->log_file && message) {
        pthread_mutex_lock(&manager->lock);
        fprintf(manager->log_file, "%s\n", message);
        fflush(manager->log_file);
        pthread_mutex_unlock(&manager->lock);
    }
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < INITIAL_POOL_SIZE) {
        void *memory = memory_pool[pool_index++];
        pthread_mutex_unlock(&pool_lock);
        return memory;
    } else {
        pthread_mutex_unlock(&pool_lock);
        return malloc(size);
    }
}

void initialize_memory_pool() {
    for (int i = 0; i < INITIAL_POOL_SIZE; ++i) {
        memory_pool[i] = malloc(MEMORY_BLOCK_SIZE);
    }
}

SensorManager* create_sensor_manager() {
    SensorManager *manager = (SensorManager*)allocate_from_pool(sizeof(SensorManager));
    manager->measurements = (double*)allocate_from_pool(MAX_SENSORS * sizeof(double));
    manager->status_indicators = (char*)allocate_from_pool(MAX_SENSORS);
    manager->records = (sensor*)allocate_from_pool(MAX_SENSORS * MEMORY_BLOCK_SIZE);
    manager->capacity = MAX_SENSORS;
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen("sensor_log.txt", "a");

    log_message(manager, "SensorManager initialized.");

    return manager;
}

void free_memory_pool() {
    for (int i = 0; i < pool_index; ++i) {
        free(memory_pool[i]);
    }
}

void destroy_sensor_manager(SensorManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    fclose(manager->log_file);

    free(manager->measurements);
    free(manager->status_indicators);
    free(manager->records);
    free(manager);

    log_message(manager, "SensorManager destroyed.");
}

void add_sensor(SensorManager *manager, float temperature, float humidity) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;

        double* new_measurements = (double*)allocate_from_pool(new_capacity * sizeof(double));
        char* new_status_indicators = (char*)allocate_from_pool(new_capacity);
        sensor* new_records = (sensor*)allocate_from_pool(new_capacity * MEMORY_BLOCK_SIZE);

        if (new_measurements && new_status_indicators && new_records) {
            memcpy(new_measurements, manager->measurements, manager->capacity * sizeof(double));
            memcpy(new_status_indicators, manager->status_indicators, manager->capacity);
            memcpy(new_records, manager->records, manager->capacity * MEMORY_BLOCK_SIZE);

            free(manager->measurements);
            free(manager->status_indicators);
            free(manager->records);

            manager->measurements = new_measurements;
            manager->status_indicators = new_status_indicators;
            manager->records = new_records;

            manager->capacity = (int)new_capacity;
        } else {
            pthread_mutex_unlock(&manager->lock);
            log_message(manager, "Failed to allocate memory for sensor expansion.");
            return;
        }
    }

    manager->measurements[manager->count] = temperature + humidity; // example calculation
    manager->status_indicators[manager->count] = (temperature > 20.0) ? 'H' : 'L'; // High/Low indicator
    manager->records[manager->count].temperature = temperature;
    manager->records[manager->count].humidity = humidity;
    manager->records[manager->count].timestamp = time(NULL);

    manager->count++;

    char log_buffer[LOG_BUFFER_SIZE];
    snprintf(log_buffer, sizeof(log_buffer), "Added sensor: temp=%.2f, humid=%.2f", temperature, humidity);
    log_message(manager, log_buffer);

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    initialize_memory_pool();

    SensorManager *sensor_manager = create_sensor_manager();

    add_sensor(sensor_manager, 21.5, 45.3);
    add_sensor(sensor_manager, 19.0, 55.2);
    // Add more sensors as needed...

    destroy_sensor_manager(sensor_manager);

    free_memory_pool();

    return 0;
}
```

### Key Points:
- **Memory Pool**: A fixed-size memory pool is used to allocate blocks of sensor data initially.
- **Dynamic Scaling**: Memory allocation doubles when the number of sensors exceeds current capacity.
- **Thread Safety**: Mutex locks ensure safe concurrent access and modifications.
- **Logging**: All actions are logged for debugging and performance tuning.']

