        return -1;
    }

    // Calculate the number of keys and records based on constraints
    size_t num_keys = num_offsets / 2;
    size_t record_size = sizeof(record);

    if ((sizeof(long) * num_offsets > MAX_OFFSET_MEMORY) ||
        (record_size * num_keys > MAX_RECORD_MEMORY)) {
        return -1; // Exceeds memory limits
    }

    long *offsets = malloc(sizeof(long) * num_offsets);
    int *keys = malloc(sizeof(int) * num_keys);

    if (!offsets || !keys) {
        free(offsets);  // Free any allocated memory before returning
        free(keys);
        return -2;      // Memory allocation failed
    }

    record *records = malloc(record_size * num_keys);
    if (!records) {
        free(offsets);
        free(keys);
        return -3;      // Memory allocation for records failed
    }

    // Initialize keys and offsets (example values)
