#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1024
#define MAX_RECORDS 100

typedef struct {
    int value;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t *records;
    size_t num_offsets;
    size_t num_keys;
    pthread_mutex_t lock; // For thread-safety
} data_structure_t;

data_structure_t* allocate_data_structures(size_t num_keys) {
    if (num_keys > MAX_RECORDS) {
        return NULL;
    }

    data_structure_t *ds = malloc(sizeof(data_structure_t));
    if (!ds) return NULL;

    pthread_mutex_init(&ds->lock, NULL);

    // Calculate maximum number of longs and ints that fit within 1024 bytes
    size_t long_size = sizeof(long);
    size_t int_size = sizeof(int);
    size_t max_long_count = MAX_MEMORY / (2 * long_size); 
    size_t remaining_space = MAX_MEMORY - (max_long_count * long_size);

    ds->num_keys = num_keys;
    ds->num_offsets = remaining_space / long_size;

    ds->offsets = malloc(ds->num_offsets * long_size);
    if (!ds->offsets) goto error_cleanup;

    ds->keys = malloc(num_keys * int_size);
    if (!ds->keys) goto error_cleanup;

    ds->records = malloc(num_keys * sizeof(record_t));
    if (!ds->records) goto error_cleanup;

    return ds;

error_cleanup:
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
    return NULL;
}

void populate_records(data_structure_t *ds, unsigned int seed) {
    if (!ds) return;

    srand(seed);
    for (size_t i = 0; i < ds->num_keys; ++i) {
        pthread_mutex_lock(&ds->lock); // Ensure thread-safe modification
        ds->records[i].value = rand() % 1000 + 1;
        pthread_mutex_unlock(&ds->lock);
    }
}

record_t* get_record(data_structure_t *ds, size_t index) {
    if (!ds || index >= ds->num_keys) return NULL;

    pthread_mutex_lock(&ds->lock); // Ensure thread-safe access
    record_t *result = &ds->records[index];
    pthread_mutex_unlock(&ds->lock);

    return result;
}

void free_data_structures(data_structure_t *ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->lock);
        free(ds);
    }
}
