#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

// Define a cache line size (commonly 64 bytes)
#define CACHE_LINE_SIZE 64

// Structure representing each record in the distributed linked list
typedef struct record {
    long offset;
    int key;
    struct record* next;
} Record;

// Memory pool structure for efficient memory management
typedef struct {
    size_t element_size;
    void* memory_pool;
    size_t total_elements;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
MemoryPool* create_memory_pool(size_t element_size, size_t num_elements);
void destroy_memory_pool(MemoryPool* pool);
Record* allocate_record(MemoryPool* pool);
int initialize_records(Record** records_array, size_t array_size, MemoryPool* pool);
int free_records(Record** records_array, size_t array_size);
void* serialize_records(const Record* record, size_t num_elements, char** buffer);
size_t deserialize_records(char* buffer, Record** records_array, size_t num_elements);

// Create a memory pool for efficient allocation
MemoryPool* create_memory_pool(size_t element_size, size_t num_elements) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    size_t pool_size = num_elements * element_size;
    void* aligned_memory = _aligned_malloc(pool_size, CACHE_LINE_SIZE);
    if (!aligned_memory) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    pool->element_size = element_size;
    pool->memory_pool = aligned_memory;
    pool->total_elements = num_elements;

    return pool;
}

// Destroy the memory pool
void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        _aligned_free(pool->memory_pool);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

// Allocate a record from the memory pool
Record* allocate_record(MemoryPool* pool) {
    if (!pthread_mutex_lock(&pool->lock)) {
        void* memory = malloc(pool->element_size);
        if (memory) {
            pthread_mutex_unlock(&pool->lock);
            return (Record*)memory;
        }
        pthread_mutex_unlock(&pool->lock);
    }
    return NULL; // Allocation failed
}

// Initialize an array of records with unique identifiers
int initialize_records(Record** records_array, size_t array_size, MemoryPool* pool) {
    if (!records_array || !pool) return -1;

    for (size_t i = 0; i < array_size; ++i) {
        records_array[i] = allocate_record(pool);
        if (!records_array[i]) {
            // Clean up previously allocated records
            free_records(records_array, i);
            return -1;
        }

        // Generate unique identifier (simulated here)
        records_array[i]->offset = rand();
        records_array[i]->key = rand() % 1000; 
        records_array[i]->next = NULL;
    }

    return 0;
}

// Free an array of records
int free_records(Record** records_array, size_t array_size) {
    for (size_t i = 0; i < array_size; ++i) {
        if (records_array[i]) {
            free(records_array[i]);
            records_array[i] = NULL;
        }
    }
    return 0;
}

// Serialize the records to a buffer
void* serialize_records(const Record* record, size_t num_elements, char** buffer) {
    *buffer = (char*)malloc(num_elements * sizeof(Record));
    if (!(*buffer)) return NULL;

    memcpy(*buffer, record, num_elements * sizeof(Record));
    return *buffer;
}

// Deserialize records from a buffer
size_t deserialize_records(char* buffer, Record** records_array, size_t num_elements) {
    memcpy(records_array, buffer, num_elements * sizeof(Record));
    return num_elements;
}

int main() {
    const size_t NUM_RECORDS = 1000000; // Example size for demonstration
    MemoryPool* pool = create_memory_pool(sizeof(Record), NUM_RECORDS);
    if (!pool) {
        fprintf(stderr, "Memory pool creation failed\n");
        return -1;
    }

    Record** records_array = (Record**)malloc(NUM_RECORDS * sizeof(Record*));
    if (!records_array || initialize_records(records_array, NUM_RECORDS, pool) != 0) {
        destroy_memory_pool(pool);
        free(records_array);
        fprintf(stderr, "Failed to initialize records\n");
        return -1;
    }

    char* buffer = NULL;
    serialize_records(records_array[0], NUM_RECORDS, &buffer);

    Record** deserialized_records = (Record**)malloc(NUM_RECORDS * sizeof(Record*));
    deserialize_records(buffer, deserialized_records, NUM_RECORDS);

    free_records(records_array, NUM_RECORDS);
    destroy_memory_pool(pool);
    free(buffer);
    free(records_array);
    free(deserialized_records);

    return 0;
}
```

This C code defines a memory pool for efficient allocation of `Record` structures aligned to cache line size. The functions handle dynamic creation and destruction of the memory pool, initialization, serialization, and deserialization of records. Error checking ensures that any allocation failure leads to cleanup of allocated resources. Thread safety is ensured with mutex locks when accessing shared data in the memory pool. This code serves as a foundation for further development towards handling distributed linked lists with high concurrency and efficient memory utilization.']

