```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

// Define platform-specific cache line size
#if defined(__x86_64__) || defined(_M_X64)
    #define CACHE_LINE_SIZE 64
#elif defined(__aarch64__)
    #define CACHE_LINE_SIZE 128
#else
    #define CACHE_LINE_SIZE 64 // Default fallback
#endif

typedef struct {
    int value;
} record_t;

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) {
        ptr = NULL;
    }
    return ptr;
}

uint32_t custom_hash(int key, uint32_t num_buckets) {
    // Simple hash function for demonstration
    return (key ^ 0x5bd1e995) % num_buckets;
}

void* init_record(void *arg) {
    struct {
        record_t *records;
        int start;
        int end;
        int min_val, max_val;
    } *data = arg;

    srand(time(NULL) + pthread_self());

    for (int i = data->start; i < data->end; ++i) {
        data->records[i].value = rand() % (data->max_val - data->min_val + 1) + data->min_val;
    }

    return NULL;
}

void create_thread_pool(record_t *records, int num_records, int min_val, int max_val, int num_threads) {
    pthread_t *threads = malloc(num_threads * sizeof(pthread_t));
    atomic_int thread_count = 0;

    int records_per_thread = num_records / num_threads;
    for (int i = 0; i < num_threads; ++i) {
        struct {
            record_t *records;
            int start, end, min_val, max_val;
        } *data = malloc(sizeof(*data));

        data->records = records + i * records_per_thread;
        data->start = i * records_per_thread;
        data->end = (i == num_threads - 1) ? num_records : (i + 1) * records_per_thread;
        data->min_val = min_val;
        data->max_val = max_val;

        pthread_create(&threads[i], NULL, init_record, data);
        atomic_fetch_add(&thread_count, 1);

        // Join threads after creation for simplicity
        pthread_join(threads[i], NULL);
        free(data);
    }

    free(threads);
}

void allocate_and_initialize(int num_long_offsets, int num_keys, int record_range_min, int record_range_max) {
    size_t aligned_size = (num_long_offsets * sizeof(long) + CACHE_LINE_SIZE - 1) & ~(CACHE_LINE_SIZE - 1);

    long *offsets = aligned_malloc(aligned_size, CACHE_LINE_SIZE);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    int *keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    size_t record_size = 16; // Align struct record with 16 bytes
    size_t max_record_memory = 1024 * 1024 - 1; // Less than 1 MB
    int num_records = (max_record_memory / record_size);

    record_t *records = aligned_malloc(num_records * sizeof(record_t), record_size);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(keys);
        free(offsets);
        return;
    }

    create_thread_pool(records, num_records, record_range_min, record_range_max, 4);

    // Clean up
    free(keys);
    free(offsets);
    free(records);
}

int main() {
    int num_long_offsets = 1000; // Example size
    int num_keys = 500;
    int record_range_min = 10;
    int record_range_max = 99;

    allocate_and_initialize(num_long_offsets, num_keys, record_range_min, record_range_max);

    return 0;
}
```

