using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class DynamicMemoryManager : IMemoryPoolConfigurable
{
    private const int DefaultOffsetLimit = 1024 * 1024; // 1 MB
    private const int DefaultRecordLimit = 256 * 1024;  // 256 KB

    private long offsetLimit;
    private long recordLimit;

    private List<long[]> offsetArrayPool;
    private List<int[]> keyArrayPool;
    private List<Record> recordArrayPool;

    public DynamicMemoryManager()
    {
        offsetLimit = DefaultOffsetLimit;
        recordLimit = DefaultRecordLimit;

        offsetArrayPool = new List<long[]>();
        keyArrayPool = new List<int[]>();
        recordArrayPool = new List<Record>();

        LoadConfiguration();
    }

    private void LoadConfiguration()
    {
        try
        {
            if (File.Exists("config.txt"))
            {
                var lines = File.ReadAllLines("config.txt");
                offsetLimit = long.Parse(lines[0]);
                recordLimit = long.Parse(lines[1]);
            }
        }
        catch (Exception ex)
        {
            LogError($"Failed to load configuration: {ex.Message}");
        }
    }

    public void ConfigureMemory(long newOffsetLimit, long newRecordLimit)
    {
        offsetLimit = newOffsetLimit;
        recordLimit = newRecordLimit;

        SaveConfiguration();
    }

    private void SaveConfiguration()
    {
        try
        {
            File.WriteAllLines("config.txt", new string[] { offsetLimit.ToString(), recordLimit.ToString() });
        }
        catch (Exception ex)
        {
            LogError($"Failed to save configuration: {ex.Message}");
        }
    }

    public int AllocateOffsets(int size, out long[] offsets)
    {
        offsets = null;

        if (CalculateSizeInBytes(size * sizeof(long)) > offsetLimit - CalculateUsedMemory(offsetArrayPool))
        {
            LogError("Offset allocation failed due to memory limit.");
            return -1; // Allocation failure code
        }

        offsets = new long[size];
        offsetArrayPool.Add(offsets);
        return 0;
    }

    public int AllocateKeys(int size, out int[] keys)
    {
        keys = null;

        if (CalculateSizeInBytes(size * sizeof(int)) > offsetLimit - CalculateUsedMemory(keyArrayPool))
        {
            LogError("Key allocation failed due to memory limit.");
            return -1; // Allocation failure code
        }

        keys = new int[size];
        keyArrayPool.Add(keys);
        return 0;
    }

    public int AllocateRecords(int size, Func<int, long, int> hashFunction, out Record[] records)
    {
        records = null;

        if (CalculateSizeInBytes(size * sizeof(Record)) > recordLimit - CalculateUsedMemory(recordArrayPool))
        {
            LogError("Record allocation failed due to memory limit.");
            return -1; // Allocation failure code
        }

        records = new Record[size];
        for (int i = 0; i < size; i++)
        {
            if (keyArrayPool.Count > 0 && offsetArrayPool.Count > 0)
            {
                int key = keyArrayPool[keyArrayPool.Count - 1][i];
                long offset = offsetArrayPool[offsetArrayPool.Count - 1][i];
                records[i] = new Record(hashFunction(key, offset));
            }
        }

        recordArrayPool.Add(records);
        return 0;
    }

    public int DeallocateOffsets(long[] offsets)
    {
        if (offsetArrayPool.Contains(offsets))
        {
            offsetArrayPool.Remove(offsets);
            return 0; // Success
        }

        LogError("Offset deallocation failed due to non-existent allocation.");
        return -1; // Deallocation failure code
    }

    public int DeallocateKeys(int[] keys)
    {
        if (keyArrayPool.Contains(keys))
        {
            keyArrayPool.Remove(keys);
            return 0; // Success
        }

        LogError("Key deallocation failed due to non-existent allocation.");
        return -1; // Deallocation failure code
    }

    public int DeallocateRecords(Record[] records)
    {
        if (recordArrayPool.Contains(records))
        {
            recordArrayPool.Remove(records);
            return 0; // Success
        }

        LogError("Record deallocation failed due to non-existent allocation.");
        return -1; // Deallocation failure code
    }

    public override string ToString()
    {
        var sb = new StringBuilder();
        sb.AppendLine($"Offset Limit: {offsetLimit}");
        sb.AppendLine($"Record Limit: {recordLimit}");
        sb.AppendLine($"Used Offset Memory: {CalculateUsedMemory(offsetArrayPool)}");
        sb.AppendLine($"Used Record Memory: {CalculateUsedMemory(recordArrayPool)}");

        return sb.ToString();
    }

    private long CalculateSizeInBytes(int size)
    {
        return (long)size;
    }

    private long CalculateUsedMemory<T>(List<T> pool)
    {
        long used = 0;
        foreach (var array in pool)
        {
            if (array is long[] longArray)
                used += longArray.Length * sizeof(long);
            else if (array is int[] intArray)
                used += intArray.Length * sizeof(int);
            else if (array is Record[] recordArray)
                used += recordArray.Length * Marshal.SizeOf(typeof(Record));
        }
        return used;
    }

    private void LogError(string message)
    {
        // Implement logging mechanism, e.g., write to a log file or console
        Console.WriteLine($"[ERROR] {message}");
    }

    public class Record
    {
        public int Value { get; }

        public Record(int value)
        {
            Value = value;
        }
    }
}

public interface IMemoryPoolConfigurable
{
    void ConfigureMemory(long newOffsetLimit, long newRecordLimit);
}
