#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define MAX_OFFSETS_SIZE 1048576 // 1 MB
#define MAX_RECORDS_SIZE 262144 // 256 KB
#define HASH_SEED_BASE 31

typedef struct {
    int value;
} record_t;

// Global mutex for concurrency control
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

// Thread-local storage to track allocations
__thread size_t total_allocations = 0;
__thread size_t total_deallocations = 0;

// Logging mechanism
void log_memory_usage(const char* message) {
    pthread_mutex_lock(&memory_lock);
    printf("%s - Total Allocations: %zu, Total Deallocations: %zu\n", message, total_allocations, total_deallocations);
    pthread_mutex_unlock(&memory_lock);
}

// Simple hash function
int custom_hash(int key, long seed) {
    return (key * HASH_SEED_BASE + seed) % 10007; // Example prime number for hashing
}

int manage_dynamic_memory(size_t num_offsets, int** keys_out, record_t*** records_out) {
    if (!keys_out || !records_out) return -1;

    size_t max_num_offsets = MAX_OFFSETS_SIZE / sizeof(long);
    if (num_offsets > max_num_offsets) {
        log_memory_usage("Offset allocation exceeds limit");
        return -2;
    }

    // Allocate memory for offsets
    long* offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        log_memory_usage("Failed to allocate offsets");
        return -3;
    }
    total_allocations += num_offsets * sizeof(long);

    // Allocate memory for keys
    size_t num_keys = num_offsets / 2;
    int* keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        log_memory_usage("Failed to allocate keys");
        return -4;
    }
    total_allocations += num_keys * sizeof(int);

    // Allocate memory for records
    size_t max_num_records = MAX_RECORDS_SIZE / sizeof(record_t);
    record_t* records = malloc(max_num_records * sizeof(record_t));
    if (!records) {
        free(offsets);
        free(keys);
        log_memory_usage("Failed to allocate records");
        return -5;
    }
    total_allocations += max_num_records * sizeof(record_t);

    // Initialize keys and records
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i + 1; // Example key initialization
    }

    for (size_t i = 0; i < num_keys; ++i) {
        long seed = offsets[i * 2]; // Use offset as seed
        records[i].value = custom_hash(keys[i], seed);
    }

    // Set output pointers
    *keys_out = keys;
    *records_out = &records;

    log_memory_usage("Memory allocation successful");
    return 0;
}

void free_dynamic_memory(int* keys, record_t** records) {
    if (keys) {
        free(keys);
        total_deallocations += sizeof(*keys) * (sizeof(keys[0]) / sizeof(int));
    }
    if (records && *records) {
        free(*records);
        total_deallocations += sizeof(**records) * (MAX_RECORDS_SIZE / sizeof(record_t));
    }
    log_memory_usage("Memory deallocation complete");
}

int main() {
    int* keys;
    record_t** records;

    int result = manage_dynamic_memory(1000, &keys, &records);
    if (result != 0) {
        printf("Error: %d\n", result);
        return result;
    }

    // Use the allocated memory...

    free_dynamic_memory(keys, records);
    return 0;
}
