['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    void *value;
} record;

record* allocate_and_initialize_array(size_t size, int min_val, int max_val, const char* data_type) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Check the data type and set appropriate size
    size_t elem_size = 0;
    if (strcmp(data_type, "int") == 0) {
        elem_size = sizeof(int);
    } else if (strcmp(data_type, "long") == 0) {
        elem_size = sizeof(long);
    }

    if (elem_size == 0) {
        pthread_mutex_destroy(&lock);
        fprintf(stderr, "Unsupported data type.\n");
        return NULL;
    }

    record *array = malloc(size * sizeof(record));
    if (!array) {
        pthread_mutex_destroy(&lock);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Initialize random number generator
    srand((unsigned int)time(NULL));

    pthread_t threads[2];
    size_t segment_size = size / 2;

    void* init_segment(void *arg) {
        record *arr = (record*) arg;
        size_t start_idx, end_idx;

        if (*(int*)arg == 0) { // First half
            start_idx = 0;
            end_idx = segment_size;
        } else { // Second half
            start_idx = segment_size;
            end_idx = size;
        }

        for (size_t i = start_idx; i < end_idx; ++i) {
            if (elem_size == sizeof(int)) {
                int value = min_val + rand() % ((max_val - min_val) + 1);
                arr[i].value = malloc(elem_size);
                *(int*)arr[i].value = value;
            } else { // long type
                long value = min_val + (long)(rand()) % ((max_val - min_val) + 1);
                arr[i].value = malloc(elem_size);
                *(long*)arr[i].value = value;
            }
        }

        return NULL;
    }

    pthread_mutex_lock(&lock);

    // Create threads to initialize array segments
    int thread_args[2] = {0, 1};
    for (int i = 0; i < 2; ++i) {
        if (pthread_create(&threads[i], NULL, init_segment, &thread_args[i])) {
            fprintf(stderr, "Error creating thread\n");
            free(array);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
    }

    // Join threads
    for (int i = 0; i < 2; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            free(array);
            pthread_mutex_destroy(&lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    // Return the allocated and initialized array
    return array;
}

void free_record_array(record *array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i].value != NULL) {
            free(array[i].value);
        }
    }
    free(array);
}
