['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char *name;
} Record;

typedef struct {
    Record **records;
    size_t capacity;
    pthread_mutex_t lock;
} DataPipeline;

#define MAX_RECORDS 10000
#define MAX_STRING_LENGTH 256
#define STRING_NAME_BASE "Record_"

void log_operation(const char *operation) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), operation);
}

int generate_random_int() {
    // Optimized for performance; use a better RNG if needed
    return rand();
}

char* create_unique_name(size_t index) {
    static pthread_mutex_t name_lock;
    pthread_mutex_init(&name_lock, NULL);

    char *unique_name = (char *)malloc(MAX_STRING_LENGTH);
    pthread_mutex_lock(&name_lock);
    snprintf(unique_name, MAX_STRING_LENGTH, "%s%d", STRING_NAME_BASE, index);
    pthread_mutex_unlock(&name_lock);

    return unique_name;
}

void initialize_data_pipeline(DataPipeline *pipeline, size_t initial_capacity) {
    pipeline->records = (Record **)malloc(initial_capacity * sizeof(Record *));
    pipeline->capacity = initial_capacity;
    pthread_mutex_init(&pipeline->lock, NULL);
    log_operation("DataPipeline initialized");
}

void resize_data_pipeline(DataPipeline *pipeline, size_t new_capacity) {
    pthread_mutex_lock(&pipeline->lock);

    Record **new_records = (Record **)realloc(pipeline->records, new_capacity * sizeof(Record *));
    if (!new_records) {
        perror("Failed to reallocate memory for records");
        exit(EXIT_FAILURE);
    }

    pipeline->records = new_records;
    pipeline->capacity = new_capacity;

    log_operation("DataPipeline resized");

    pthread_mutex_unlock(&pipeline->lock);
}

void add_record(DataPipeline *pipeline, int value) {
    if (pipeline->capacity == 0) initialize_data_pipeline(pipeline, MAX_RECORDS);

    if ((size_t)pipeline->capacity == MAX_RECORDS) {
        log_operation("Maximum record capacity reached");
        return;
    }

    pthread_mutex_lock(&pipeline->lock);

    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->value = value;
    new_record->name = create_unique_name(pipeline->capacity);

    if ((size_t)pipeline->capacity == pipeline->records[0]) {
        resize_data_pipeline(pipeline, pipeline->capacity * 2);
    }

    pipeline->records[pipeline->capacity++] = new_record;

    pthread_mutex_unlock(&pipeline->lock);
}

void save_to_disk(const DataPipeline *pipeline, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    fwrite(&(pipeline->capacity), sizeof(size_t), 1, file);

    for (size_t i = 0; i < pipeline->capacity; ++i) {
        fwrite(&(pipeline->records[i]->value), sizeof(int), 1, file);
        size_t name_length = strlen(pipeline->records[i]->name) + 1;
        fwrite(&name_length, sizeof(size_t), 1, file);
        fwrite(pipeline->records[i]->name, sizeof(char), name_length, file);
    }

    fclose(file);
    log_operation("DataPipeline saved to disk");
}

void load_from_disk(DataPipeline *pipeline, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }

    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);

    resize_data_pipeline(pipeline, capacity);

    for (size_t i = 0; i < capacity; ++i) {
        Record *record = pipeline->records[i];
        fread(&(record->value), sizeof(int), 1, file);

        size_t name_length;
        fread(&name_length, sizeof(size_t), 1, file);
        record->name = (char *)malloc(name_length);
        fread(record->name, sizeof(char), name_length, file);
    }

    fclose(file);
    log_operation("DataPipeline loaded from disk");
}

void cleanup_data_pipeline(DataPipeline *pipeline) {
    for (size_t i = 0; i < pipeline->capacity; ++i) {
        free(pipeline->records[i]->name);
        free(pipeline->records[i]);
    }

    free(pipeline->records);
    pthread_mutex_destroy(&pipeline->lock);
    log_operation("DataPipeline cleaned up");
}

int main() {
    srand(time(NULL));

    DataPipeline pipeline;
    initialize_data_pipeline(&pipeline, 0);

    for (int i = 0; i < 100; ++i) {
        add_record(&pipeline, generate_random_int());
    }

    save_to_disk(&pipeline, "data.bin");

    DataPipeline new_pipeline;
    load_from_disk(&new_pipeline, "data.bin");

    cleanup_data_pipeline(&pipeline);
    cleanup_data_pipeline(&new_pipeline);

    return 0;
}
