} DeviceManager;

DeviceManager* create_device_manager(size_t initial_capacity) {
    DeviceManager* manager = (DeviceManager*)malloc(sizeof(DeviceManager));
    manager->devices = (Device*)calloc(initial_capacity, sizeof(Device));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen("device_log.txt", "a");
