void destroy_device_manager(DeviceManager* manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->devices[i].last_known_state);
        }
        free(manager->devices);
        fclose(manager->log_file);
        pthread_mutex_unlock(&manager->lock);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

void log_device_access(DeviceManager* manager, const char* message) {
    if (manager && manager->log_file) {
        pthread_mutex_lock(&manager->lock);
        fprintf(manager->log_file, "%s\n", message);
        fflush(manager->log_file);
        pthread_mutex_unlock(&manager->lock);
    }
}

int add_device(DeviceManager* manager, int unique_id, const char* state) {
    if (pthread_mutex_trylock(&manager->lock) != 0) return -1;

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Device* new_devices = (Device*)realloc(manager->devices, new_capacity * sizeof(Device));
        if (!new_devices) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->devices = new_devices;
        manager->capacity = new_capacity;
    }

    Device device;
    device.unique_id = unique_id;
    device.last_known_state = strdup(state);
    device.metadata.network_latency = 0; // Default value
    device.metadata.last_successful_connection = time(NULL); // Current timestamp
    device.metadata.error_count = 0;

    manager->devices[manager->count++] = device;

    char log_message[128];
    snprintf(log_message, sizeof(log_message), "Added device with ID %d", unique_id);
    log_device_access(manager, log_message);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_device(DeviceManager* manager, int unique_id) {
    if (pthread_mutex_trylock(&manager->lock) != 0) return -1;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->devices[i].unique_id == unique_id) {
            free(manager->devices[i].last_known_state);
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->devices[j] = manager->devices[j + 1];
            }
            --manager->count;

            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Removed device with ID %d", unique_id);
            log_device_access(manager, log_message);

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}

void update_device_state(DeviceManager* manager, int unique_id, const char* new_state) {
    if (pthread_mutex_trylock(&manager->lock) != 0) return;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->devices[i].unique_id == unique_id) {
            free(manager->devices[i].last_known_state);
            manager->devices[i].last_known_state = strdup(new_state);

            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Updated state for device ID %d", unique_id);
            log_device_access(manager, log_message);

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Example usage
int main() {
    DeviceManager* manager = create_device_manager(10);

    add_device(manager, 1, "Connected");
    update_device_state(manager, 1, "Disconnected");
    remove_device(manager, 1);

    destroy_device_manager(manager);
    return 0;
}
```

