typedef struct {
    long timestamp;
    int key;
    double temperature;
    char status; // 'A' for accurate, 'P' for potential error
} sensor_record;

typedef struct memory_pool {
    size_t block_size;
    void *memory;
    size_t total_blocks;
    size_t free_blocks;
    pthread_mutex_t lock;
} memory_pool;

// Function prototypes
void init_memory_pool(memory_pool *pool, size_t block_size, size_t num_blocks);
void* pool_alloc(memory_pool *pool);
void pool_free_all(memory_pool *pool);
void initialize_sensor_records(sensor_record **records, int count, double min_temp, double max_temp);

// Initialize memory pool
void init_memory_pool(memory_pool *pool, size_t block_size, size_t num_blocks) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->total_blocks = num_blocks;
    pool->free_blocks = num_blocks;

    pool->memory = malloc(block_size * num_blocks);
    if (!pool->memory) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
}

// Allocate a block from the memory pool
void* pool_alloc(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->free_blocks == 0) {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    void *block = pool->memory + ((pool->total_blocks - pool->free_blocks) * pool->block_size);
    pool->free_blocks--;

    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Free all allocated blocks in the memory pool
void pool_free_all(memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);

    pool->free_blocks = pool->total_blocks;

    pthread_mutex_unlock(&pool->lock);
}

// Initialize sensor records with random data
void initialize_sensor_records(sensor_record **records, int count, double min_temp, double max_temp) {
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        (*records)[i].timestamp = rand() % 100000;
        (*records)[i].key = rand() % 1000;
        (*records)[i].temperature = min_temp + ((double)rand() / RAND_MAX) * (max_temp - min_temp);
        (*records)[i].status = (rand() % 10 < 2) ? 'P' : 'A'; // 20% chance of error
    }
}

// Main function to manage sensor data
void manage_sensor_data(int record_count, double temp_min, double temp_max) {
    memory_pool pool;
    init_memory_pool(&pool, sizeof(sensor_record), record_count);

    sensor_record *records = (sensor_record *)pool_alloc(&pool);
    initialize_sensor_records(&records, record_count, temp_min, temp_max);

    // Simulate processing of records
    for (int i = 0; i < record_count; ++i) {
        printf("Record %d: Timestamp=%ld, Key=%d, Temp=%.2f, Status=%c\n",
               i, records[i].timestamp, records[i].key, records[i].temperature, records[i].status);
    }

    pool_free_all(&pool);
    free(pool.memory);
}

int main() {
    manage_sensor_data(1000, -10.0, 40.0); // Example usage
    return 0;
}
