#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Node structure for the balanced tree (AVL Tree)
typedef struct AVLNode {
    int key;
    struct AVLNode *left, *right;
    int height;
} AVLNode;

// Utility function to get the maximum of two integers
int max(int a, int b) {
    return (a > b) ? a : b;
}

// Function to create a new AVL node
AVLNode* newNode(int key) {
    AVLNode* node = (AVLNode*)malloc(sizeof(AVLNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for AVL node.\n");
        exit(EXIT_FAILURE);
    }
    node->key = key;
    node->left = node->right = NULL;
    node->height = 1; // New node is initially added at leaf
    return node;
}

// Function to right rotate subtree rooted with y
AVLNode* rightRotate(AVLNode *y) {
    AVLNode *x = y->left;
    AVLNode *T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    return x;
}

// Function to left rotate subtree rooted with x
AVLNode* leftRotate(AVLNode *x) {
    AVLNode *y = x->right;
    AVLNode *T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    return y;
}

// Get the height of the node
int height(AVLNode *N) {
    if (N == NULL)
        return 0;
    return N->height;
}

// Get balance factor of node N
int getBalance(AVLNode *N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

// Insert a key into the AVL tree and return the new root
AVLNode* insert(AVLNode* node, int key) {
    // Perform the normal BST insertion
    if (node == NULL)
        return newNode(key);

    if (key < node->key)
        node->left = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key);
    else // Equal keys are not allowed in BST
        return node;

    // Update height of this ancestor node
    node->height = 1 + max(height(node->left), height(node->right));

    // Get the balance factor of this ancestor node to check whether it became unbalanced
    int balance = getBalance(node);

    // If unbalanced, then there are 4 cases

    // Left Left Case
    if (balance > 1 && key < node->left->key)
        return rightRotate(node);

    // Right Right Case
    if (balance < -1 && key > node->right->key)
        return leftRotate(node);

    // Left Right Case
    if (balance > 1 && key > node->left->key) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    // Right Left Case
    if (balance < -1 && key < node->right->key) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    // Return the unchanged node pointer
    return node;
}

// Function to check if a value is present in the AVL tree
bool contains(AVLNode* root, int key) {
    if (root == NULL)
        return false;
    if (key < root->key)
        return contains(root->left, key);
    else if (key > root->key)
        return contains(root->right, key);
    else
        return true; // Key found
}

void freeAVL(AVLNode* node) {
    if (node == NULL)
        return;
    freeAVL(node->left);
    freeAVL(node->right);
    free(node);
}

void* createDataStructures(unsigned int seed, size_t recordAllocSize) {
    // Seed the random number generator
    srand(seed);

    long *offsets = malloc(10000 * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array.\n");
        return NULL;
    }

    AVLNode *keysRoot = NULL;

    bool *offsetSet = calloc(10001, sizeof(bool)); // Using an extra slot to handle 0-10,000 range
    if (!offsetSet) {
        fprintf(stderr, "Memory allocation failed for offset hash set.\n");
        free(offsets);
        return NULL;
    }

    int offsetsCount = 0;
    while (offsetsCount < 10000) {
        long offset = rand() % 100000; // Generate a random number in a large range
        if (!offsetSet[offset]) { // Check uniqueness
            offsets[offsetsCount++] = offset;
            offsetSet[offset] = true;
        }
    }

    int keysCount = 0;
    while (keysCount < 5000) {
        int key = rand() % 10000 + 1; // Generate a random number between 1 and 10,000
        if (!contains(keysRoot, key)) { // Check uniqueness using AVL tree
            keysRoot = insert(keysRoot, key);
            keysCount++;
        }
    }

    size_t recordSize = sizeof(record);
    if (recordAllocSize % recordSize != 0) {
        fprintf(stderr, "Specified allocation size is not a multiple of the record structure size.\n");
        free(offsets);
        free(offsetSet);
        freeAVL(keysRoot);
        return NULL;
    }

    record *records = malloc(recordAllocSize);
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        free(offsets);
        free(offsetSet);
        freeAVL(keysRoot);
        return NULL;
    }

    bool *recordValuesSet = calloc(10001, sizeof(bool)); // Using an extra slot to handle 0-10,000 range
    if (!recordValuesSet) {
        fprintf(stderr, "Memory allocation failed for record values set.\n");
        free(offsets);
        free(offsetSet);
        freeAVL(keysRoot);
        free(records);
        return NULL;
    }

    int recordsCount = 0;
    while (recordsCount < 1000) {
        int value = rand() % 10000 + 1; // Generate a random number between 1 and 10,000
        if (!recordValuesSet[value]) { // Check uniqueness within the array
            records[recordsCount].value = value;
            recordValuesSet[value] = true;
            recordsCount++;
        }
    }

    free(offsetSet);
    free(recordValuesSet);

    return (void*)malloc(sizeof(void*) * 3); // Return a pointer to an array of pointers for offsets, keysRoot, and records
}

void cleanupDataStructures(void* dataPtr) {
    if (!dataPtr)
        return;

    void **data = (void**)dataPtr;
    free(data[0]); // Free offsets
    freeAVL((AVLNode*)data[1]); // Free AVL tree for keys
    free(data[2]); // Free records

    free(data); // Free the array of pointers
}
