    ConfigCollection *collection = (ConfigCollection *)malloc(sizeof(ConfigCollection));
    if (!collection) return NULL;

    collection->configs = (DeviceConfig *)aligned_alloc(16, sizeof(DeviceConfig) * initial_capacity);
    if (!collection->configs) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    atomic_store(&collection->threshold, threshold);

    log_message("Configuration collection initialized.");
    return collection;
}

int add_config(ConfigCollection *collection, const DeviceConfig *config) {
    pthread_mutex_lock(&collection->lock);

    if (atomic_load(&collection->count) >= atomic_load(&collection->threshold)) {
        size_t new_capacity = collection->capacity * EXPANSION_FACTOR;
        DeviceConfig *new_configs = (DeviceConfig *)aligned_realloc(collection->configs, 16, sizeof(DeviceConfig) * new_capacity);
        if (!new_configs) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Failed to reallocate memory
        }
        collection->capacity = new_capacity;
        log_message("Configuration capacity expanded.");
    }

    memcpy(&collection->configs[atomic_fetch_add(&collection->count, 1)], config, sizeof(DeviceConfig));
    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

DeviceConfig* get_config(ConfigCollection *collection, size_t index) {
    if (index >= atomic_load(&collection->count)) {
        log_message("Configuration access out of bounds.");
        return NULL;
    }

    pthread_mutex_lock(&collection->lock);
    DeviceConfig *config = &collection->configs[index];
    pthread_mutex_unlock(&collection->lock);

    return config; // Return pointer to the requested configuration
}

void free_collection(ConfigCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->lock);
        aligned_free(collection->configs);
        free(collection);
        log_message("Configuration collection deallocated.");
    }
}

// Example Usage:
/*
int main() {
    ConfigCollection *collection = init_collection(INITIAL_CAPACITY, INITIAL_CAPACITY);
    assert(collection != NULL);

    DeviceConfig config1 = {"192.168.0.1", "255.255.255.0", "192.168.0.254", "8.8.8.8"};
    add_config(collection, &config1);

    DeviceConfig *retrieved = get_config(collection, 0);
    if (retrieved) {
        printf("IP Address: %s\n", retrieved->ip_address);
    }

    free_collection(collection);
    return 0;
}
