import threading
from abc import ABC, abstractmethod
from collections import defaultdict
from functools import lru_cache
import logging

# Assuming we have some third-party monitoring framework integration library
# from monitoring_framework import log_change, log_error 

class NetworkConfigurable(ABC):
    def __init__(self, protocol_id, **kwargs):
        self.protocol_id = protocol_id
        self.config_settings = kwargs

    @abstractmethod
    def load_config(self, config_source):
        """Load configuration settings."""
        pass

    @abstractmethod
    def save_config(self, destination):
        """Save configuration settings."""
        pass

    @abstractmethod
    def validate_parameters(self) -> bool:
        """Validate network parameters."""
        return True

    @abstractmethod
    def apply_changes(self):
        """Apply changes to active network interfaces."""
        pass


class NetworkConfigRegistry:
    _registry_lock = threading.Lock()
    _factories = {}

    @classmethod
    def register_factory(cls, protocol_id, factory_cls):
        with cls._registry_lock:
            cls._factories[protocol_id] = factory_cls

    @classmethod
    def create_instance(cls, protocol_id, **kwargs):
        with cls._registry_lock:
            if protocol_id in cls._factories:
                return cls._factories[protocol_id](protocol_id, **kwargs)
            else:
                raise ValueError(f"No registered factory for protocol ID: {protocol_id}")

    @classmethod
    def load_external_factories(cls, module_name):
        # Dynamically load external factories from a specified module
        import importlib
        module = importlib.import_module(module_name)
        with cls._registry_lock:
            for attr in dir(module):
                if isinstance(getattr(module, attr), type) and issubclass(getattr(module, attr), NetworkConfigurable):
                    factory_cls = getattr(module, attr)
                    protocol_id = factory_cls.get_protocol_id()
                    cls.register_factory(protocol_id, factory_cls)


class ConfigCache:
    def __init__(self, maxsize=100):
        self.cache = lru_cache(maxsize=maxsize)(self._cache_fetch)

    def _cache_fetch(self, key, loader_func, *args, **kwargs):
        return loader_func(*args, **kwargs)

    def get_config(self, config_key, loader_func, *args, **kwargs):
        try:
            return self.cache(config_key, loader_func, *args, **kwargs)
        except Exception as e:
            logging.error(f"Error fetching from cache: {e}")
            raise


class ValidationPlugin(ABC):
    @abstractmethod
    def validate(self, config_settings) -> bool:
        """Custom validation logic."""
        return True


class PluginManager:
    _plugins = {}

    @classmethod
    def register_plugin(cls, protocol_id, plugin_cls):
        if not issubclass(plugin_cls, ValidationPlugin):
            raise ValueError("Invalid plugin class")
        cls._plugins[protocol_id] = plugin_cls()

    @classmethod
    def validate(cls, protocol_id, config_settings) -> bool:
        plugin = cls._plugins.get(protocol_id)
        return plugin.validate(config_settings) if plugin else True


class DefaultNetworkConfig(NetworkConfigurable):
    # Example subclass for a default network configuration

    def load_config(self, config_source):
        # Load logic
        pass

    def save_config(self, destination):
        # Save logic
        pass

    def validate_parameters(self) -> bool:
        return PluginManager.validate(self.protocol_id, self.config_settings)

    def apply_changes(self):
        # Apply changes to network interfaces
        pass


def monitor_wrapper(func):
    def wrapper(*args, **kwargs):
        try:
            result = func(*args, **kwargs)
            logging.info(f"Config change applied for {args[0].protocol_id}")
            return result
        except Exception as e:
            logging.error(f"Error in config operation: {e}")
            raise
    return wrapper


class AdvancedNetworkConfig(DefaultNetworkConfig):

    @monitor_wrapper
    def load_config(self, config_source):
        super().load_config(config_source)

    @monitor_wrapper
    def save_config(self, destination):
        super().save_config(destination)

    @monitor_wrapper
    def apply_changes(self):
        if not self.validate_parameters():
            raise ValueError("Invalid configuration parameters")
        super().apply_changes()


# Register a sample default factory for protocol_id "default"
NetworkConfigRegistry.register_factory("default", DefaultNetworkConfig)
PluginManager.register_plugin("default", ValidationPlugin)  # Example plugin registration

# Usage example:
config = NetworkConfigRegistry.create_instance('default', address="192.168.1.1")
cache = ConfigCache(maxsize=50)

try:
    config.load_config("/path/to/config")
except Exception as e:
    logging.error(f"Failed to load configuration: {e}")

