#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

typedef struct {
    int value;
} record;

typedef pthread_mutex_t mutex_lock;
typedef pthread_rwlock_t rwlock;

#define MAX_RETRIES 3

// Memory pool structure
typedef struct {
    size_t block_size;
    void* memory;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} mem_pool;

void init_mem_pool(mem_pool *pool, size_t block_size, size_t total_blocks) {
    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->memory = malloc(block_size * total_blocks);
    pool->used_blocks = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void* mem_pool_alloc(mem_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_blocks < pool->total_blocks) {
        void* block = ((char*)pool->memory) + (pool->used_blocks++ * pool->block_size);
        pthread_mutex_unlock(&pool->lock);
        return block;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void free_mem_pool(mem_pool *pool) {
    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
}

// Helper functions
int get_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* current_system_time_str() {
    time_t now = time(NULL);
    char* str = malloc(20); // YYYY-MM-DD HH:MM:SS
    if (str == NULL) return NULL;
    strftime(str, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));
    return str;
}

void find_largest_integer(const int *keys, size_t count, int *largest) {
    *largest = keys[0];
    for (size_t i = 1; i < count; ++i) {
        if (keys[i] > *largest) {
            *largest = keys[i];
        }
    }
}

void find_shortest_string(const char **strings, size_t count, const char **shortest) {
    *shortest = strings[0];
    size_t min_length = strlen(strings[0]);
    for (size_t i = 1; i < count; ++i) {
        if (strlen(strings[i]) < min_length) {
            min_length = strlen(strings[i]);
            *shortest = strings[i];
        }
    }
}

// Function to read integers and strings from standard input
int* read_integers(size_t *count, mem_pool *pool) {
    int number;
    size_t capacity = 10;
    int *numbers = (int*)mem_pool_alloc(pool);
    if (!numbers) return NULL;

    *count = 0;
    while (scanf("%d", &number) == 1) {
        if (*count >= capacity) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) break;
        }
        numbers[(*count)++] = number;
    }

    return numbers;
}

char*** read_strings(size_t *count, mem_pool *pool) {
    char buffer[256];
    size_t capacity = 10;
    char ***strings = (char***)mem_pool_alloc(pool);
    if (!strings) return NULL;

    *count = 0;
    while (scanf("%255s", buffer) == 1) {
        if (*count >= capacity) {
            capacity *= 2;
            strings = realloc(strings, capacity * sizeof(char*));
            if (!strings) break;
        }
        strings[*count] = strdup(buffer);
        if (!strings[*count]) break;
        (*count)++;
    }

    return strings;
}

// Main function
void process_data(size_t int_count, size_t str_count) {
    mem_pool pool;
    init_mem_pool(&pool, 1024, 1000);

    // Allocate arrays
    long* offsets = (long*)mem_pool_alloc(&pool);
    int* keys = (int*)mem_pool_alloc(&pool);
    record* records = (record*)mem_pool_alloc(&pool);
    char** string_keys = (char**)mem_pool_alloc(&pool);

    if (!offsets || !keys || !records || !string_keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free_mem_pool(&pool);
        return;
    }

    // Initialize arrays
    for (size_t i = 0; i < int_count; ++i) {
        keys[i] = get_random_int(1, 100);
        records[i].value = get_random_int(1, 100);
        offsets[i] = (long)i * sizeof(int);
    }

    for (size_t i = 0; i < str_count; ++i) {
        string_keys[i] = current_system_time_str();
    }

    // Find largest integer and shortest string
    int largest_int = INT_MIN;
    const char* shortest_str = NULL;

    find_largest_integer(keys, int_count, &largest_int);
    find_shortest_string(string_keys, str_count, &shortest_str);

    printf("Largest Integer: %d\n", largest_int);
    printf("Shortest String: %s\n", shortest_str);

    // Free allocated memory
    for (size_t i = 0; i < str_count; ++i) {
        free(string_keys[i]);
    }
    free_mem_pool(&pool);
}

// Companion function
char* append_slash_if_within_limit(const char *input, size_t limit) {
    size_t input_len = strlen(input);
    if (input_len >= limit) return NULL;

    char* new_str = malloc(limit + 2); // Include space for slash and null terminator
    if (!new_str) return NULL;

    strncpy(new_str, input, limit - 1);
    new_str[limit - 1] = '/';
    new_str[limit] = '\0';

    return new_str;
}

