#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>

#define POOL_SIZE 1024 * 1024 // 1MB memory pool

typedef struct {
    char* data;
    size_t length;
} String;

typedef struct {
    int intValue;
    double doubleValue;
    String* stringValue;
} Object;

typedef struct {
    long* longArray;
    int* intArray;
    double* doubleArray;
    Object* objectArray;
    size_t objectCount;
    pthread_mutex_t lock;
    char memoryPool[POOL_SIZE];
    size_t offset;
} MemoryManager;

MemoryManager* createMemoryManager(size_t objectCount) {
    MemoryManager* mm = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!mm) return NULL;

    mm->longArray = (long*)calloc(100, sizeof(long));
    mm->intArray = (int*)calloc(100, sizeof(int));
    mm->doubleArray = (double*)calloc(100, sizeof(double));
    mm->objectArray = (Object*)malloc(objectCount * sizeof(Object));

    if (!mm->longArray || !mm->intArray || !mm->doubleArray || !mm->objectArray) {
        free(mm->longArray);
        free(mm->intArray);
        free(mm->doubleArray);
        free(mm->objectArray);
        free(mm);
        return NULL;
    }

    mm->objectCount = objectCount;
    pthread_mutex_init(&mm->lock, NULL);
    mm->offset = 0;

    for (size_t i = 0; i < objectCount; ++i) {
        mm->objectArray[i].intValue = 0;
        mm->objectArray[i].doubleValue = 0.0;
        mm->objectArray[i].stringValue = (String*)malloc(sizeof(String));
        if (!mm->objectArray[i].stringValue) {
            for (size_t j = 0; j < i; ++j) free(mm->objectArray[j].stringValue);
            free(mm->longArray);
            free(mm->intArray);
            free(mm->doubleArray);
            free(mm->objectArray);
            pthread_mutex_destroy(&mm->lock);
            free(mm);
            return NULL;
        }
    }

    return mm;
}

void* allocateFromPool(MemoryManager* mm, size_t size) {
    if (mm->offset + size > POOL_SIZE) return NULL;

    void* ptr = &mm->memoryPool[mm->offset];
    mm->offset += size;
    return ptr;
}

void freeMemoryManager(MemoryManager* mm) {
    for (size_t i = 0; i < mm->objectCount; ++i) {
        free(mm->objectArray[i].stringValue);
    }
    free(mm->longArray);
    free(mm->intArray);
    free(mm->doubleArray);
    free(mm->objectArray);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}

void* threadSafeSmallestInt(void* arg) {
    int* array = (int*)arg;
    size_t length = *(size_t*)(arg + sizeof(int*) * 2);

    if (!length) return NULL;

    int smallest = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] < smallest) smallest = array[i];
    }

    return &smallest;
}

void readIntegers(int** array, size_t* count) {
    *count = 0;
    int capacity = 10;
    *array = (int*)malloc(capacity * sizeof(int));

    if (!*array) exit(EXIT_FAILURE);

    while (scanf("%d", (*array) + *count) == 1) {
        ++(*count);
        if (*count >= capacity) {
            capacity *= 2;
            *array = realloc(*array, capacity * sizeof(int));
            if (!*array) exit(EXIT_FAILURE);
        }
    }
}

void serializeToJson(const Object* objects, size_t count, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "[\n");
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&objects[i].lock);
        fprintf(file, "  {\"int\": %d, \"double\": %.2f, \"string\": \"%s\"}",
                objects[i].intValue,
                objects[i].doubleValue,
                objects[i].stringValue->data);
        pthread_mutex_unlock(&objects[i].lock);

        if (i < count - 1) fprintf(file, ",");
