#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 256
#define POOL_SIZE 1024

typedef struct {
    int id;
    float value;
    char *name;
} Record;

typedef struct MemoryPool {
    size_t unit_size;
    unsigned char *pool;
    unsigned char *next_free;
    pthread_mutex_t lock;
} MemoryPool;

// Function prototypes
void initialize_memory_pool(MemoryPool *mp, size_t unit_size, size_t pool_size);
void* allocate_from_pool(MemoryPool *mp);
void deallocate_from_pool(MemoryPool *mp, void *ptr);
void log_message(const char *message);
void read_records(const char *filename, Record **records, int *count);

// Global variables for monitoring
size_t peak_memory_usage = 0;
pthread_mutex_t memory_usage_lock;

void initialize_monitoring_system() {
    pthread_mutex_init(&memory_usage_lock, NULL);
}

void update_peak_memory(size_t current_usage) {
    pthread_mutex_lock(&memory_usage_lock);
    if (current_usage > peak_memory_usage) {
        peak_memory_usage = current_usage;
    }
    pthread_mutex_unlock(&memory_usage_lock);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    initialize_monitoring_system();

    MemoryPool mp;
    initialize_memory_pool(&mp, sizeof(Record), POOL_SIZE);

    Record *records = NULL;
    int record_count = 0;

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void *(*)(void *))read_records, argv[1])) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    printf("Peak memory usage: %zu bytes\n", peak_memory_usage);

    // Cleanup
    for (int i = 0; i < record_count; ++i) {
        deallocate_from_pool(&mp, records[i].name);
        deallocate_from_pool(&mp, &records[i]);
    }
    free(records);

    return EXIT_SUCCESS;
}

void initialize_memory_pool(MemoryPool *mp, size_t unit_size, size_t pool_size) {
    pthread_mutex_init(&mp->lock, NULL);
    mp->unit_size = unit_size;
    mp->pool = malloc(pool_size * unit_size);
    mp->next_free = mp->pool;
    if (!mp->pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
}

void* allocate_from_pool(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->next_free + mp->unit_size <= mp->pool + POOL_SIZE * mp->unit_size) {
        void *ptr = mp->next_free;
        mp->next_free += mp->unit_size;
        update_peak_memory((size_t)(mp->next_free - mp->pool));
        pthread_mutex_unlock(&mp->lock);
        return ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    log_message("Memory pool exhausted");
    return NULL;
}

void deallocate_from_pool(MemoryPool *mp, void *ptr) {
    // Simplified for demonstration; in practice, you might use a free list.
    (void)mp;
    (void)ptr;
}

void log_message(const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

void* read_records(void *arg) {
    const char *filename = arg;
    Record **records = malloc(sizeof(Record *) * POOL_SIZE);
    int count = 0;

    FILE *file = fopen(filename, "r");
    if (!file) {
        log_message("Failed to open file");
        return NULL;
    }

    MemoryPool mp;
    initialize_memory_pool(&mp, sizeof(Record), POOL_SIZE);

    while (fscanf(file, "%d %f %255s", &records[count]->id, &records[count]->value,
                  records[count]->name) == 3) {
        if (strlen(records[count]->name) > MAX_STRING_LENGTH - 1) {
            log_message("String length exceeded limit, using default value");
            strcpy(records[count]->name, "default");
        }
        ++count;
    }

    fclose(file);
    *records = realloc(*records, count * sizeof(Record *));
    *record_count = count;

    return NULL;
}
