    pool->keys = calloc(num_records, sizeof(int));
    pool->records = calloc(num_records, sizeof(Record));
    pool->count = num_records;
    pthread_mutex_unlock(&lock);

    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool);
        return NULL;
    }

    return pool;
}

