#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <time.h>

#define MEMORY_POOL_SIZE 1024 * 1024 // Example size
#define MAX_WORDS 100
#define NUM_RECORDS 1000

typedef struct {
    int value;
    float data;
    char* str;
} record;

char* dictionary[MAX_WORDS] = {"word1", "word2", "word3"}; // Predefined dictionary

// Custom memory pool
char memory_pool[MEMORY_POOL_SIZE];
size_t memory_offset = 0;
pthread_mutex_t mem_pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&mem_pool_lock);
    if (memory_offset + size > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&mem_pool_lock);
        return NULL; // Out of memory
    }
    void* ptr = &memory_pool[memory_offset];
    memory_offset += size;
    pthread_mutex_unlock(&mem_pool_lock);
    return ptr;
}

void initialize_data(long* offsets, int* keys, float* data_points, record* records, const char** cipher_modes) {
    srand(time(NULL));

    for (int i = 0; i < NUM_RECORDS; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        data_points[i] = (float)(rand() / (RAND_MAX + 1.0));

        records[i].value = rand() % 200;
        records[i].data = (float)(rand() / (RAND_MAX + 1.0));

        int word_index = rand() % MAX_WORDS;
        size_t str_len = strlen(dictionary[word_index]) + 1;
        records[i].str = allocate_from_pool(str_len);
        if (records[i].str) {
            strcpy(records[i].str, dictionary[word_index]);
        }
    }
}

EVP_CIPHER* setup_cipher(const char* cipher_mode, int key_index, const unsigned char* keys[], size_t key_sizes[], int num_keys, int* status_code) {
    EVP_CIPHER_CTX *ctx = NULL;

    if (key_index < 0 || key_index >= num_keys) {
        *status_code = -1; // Error: out-of-bounds index
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        *status_code = -2; // Error: failed to create cipher context
        return NULL;
    }

    int result;
    if (strcmp(cipher_mode, "ECB") == 0) {
        result = EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, keys[key_index], NULL);
    } else if (strcmp(cipher_mode, "EDE") == 0 || strcmp(cipher_mode, "EDE3") == 0) {
        result = EVP_CipherInit_ex(ctx, EVP_des_ede3(), NULL, keys[key_index], key_sizes[key_index], 1); // Encrypt
    } else if (strcmp(cipher_mode, "CFB") == 0) {
        result = EVP_EncryptInit_ex(ctx, EVP_aes_256_cfb128(), NULL, keys[key_index], NULL);
    } else {
        *status_code = -3; // Error: unsupported cipher mode
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (result != 1) {
        *status_code = -4; // Error: failed to initialize cipher
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    *status_code = 0; // Success
    return ctx;
}

void log_activity(const char* message) {
    printf("LOG: %s\n", message);
}

// Thread-safe function to manage data and operations
void* manage_data_operations(void* args) {
    long offsets[NUM_RECORDS];
    int keys[NUM_RECORDS];
    float data_points[NUM_RECORDS];
    record records[NUM_RECORDS];

    const char* cipher_modes[] = {"ECB", "EDE", "EDE3", "CFB"};
    unsigned char key1[32] = {0}; // Example key
    size_t key_sizes[] = {sizeof(key1)};
    int status_code;

    initialize_data(offsets, keys, data_points, records, cipher_modes);
    log_activity("Data initialized.");

    EVP_CIPHER* cipher_ctx = setup_cipher(cipher_modes[rand() % 4], rand() % 1, &key1, key_sizes, 1, &status_code);
    if (cipher_ctx) {
        log_activity("Cipher set up successfully.");
    } else {
        log_activity("Failed to set up cipher. Status code: ");
        printf("%d\n", status_code);
    }

    // Clean-up
    for (int i = 0; i < NUM_RECORDS; ++i) {
        free(records[i].str);
    }

    if (cipher_ctx) {
        EVP_CIPHER_CTX_free(cipher_ctx);
    }

    return NULL;
}

int main() {
    pthread_t threads[4]; // Example thread count

    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, manage_data_operations, NULL);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
