// Define structures
typedef struct {
    float x, y;
} Point;

typedef struct {
    double number;
    char *string;
    Point point;
} Geometry;

// Memory pool structure
typedef struct {
    size_t block_size;
    size_t num_blocks;
    void *pool;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables for logging and thread safety
pthread_mutex_t log_lock;
pthread_mutex_t geometry_lock;

void initialize_logger() {
    pthread_mutex_init(&log_lock, NULL);
}

void finalize_logger() {
    pthread_mutex_destroy(&log_lock);
}

void log_event(const char *message) {
    pthread_mutex_lock(&log_lock);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_lock);
}

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->num_blocks = num_blocks;
    mp->pool = malloc(block_size * num_blocks);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (!mp || !mp->pool) {
        pthread_mutex_unlock(&mp->lock);
        log_event("Memory pool allocation failed.");
        return NULL;
    }
    void *block = mp->pool;
    mp->pool += mp->block_size; // Move the pointer forward
    pthread_mutex_unlock(&mp->lock);
    log_event("Allocated memory block from pool.");
    return block;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->lock);
        free(mp);
    }
}

// Function to generate a random alphanumeric string
char* generate_random_string(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *str = (char *)malloc(length + 1);
    if (!str) return NULL;

    for (size_t n = 0; n < length; ++n) {
        int key = rand() % (int)(sizeof(charset) - 1);
        str[n] = charset[key];
    }
    str[length] = '\0';
    log_event("Generated random string.");
    return str;
}

