float find_median(double *array, int n) {
    if (n == 0) return NAN;

    double* sorted_array = malloc(n * sizeof(double));
    memcpy(sorted_array, array, n * sizeof(double));

    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (sorted_array[j] > sorted_array[j + 1]) {
                double temp = sorted_array[j];
                sorted_array[j] = sorted_array[j + 1];
                sorted_array[j + 1] = temp;
            }
        }
    }

    float median = (n % 2 == 0) ? (sorted_array[n/2 - 1] + sorted_array[n/2]) / 2 : sorted_array[n/2];

    free(sorted_array);
    return median;
}

