void* custom_malloc(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);

    if (!memory_pool.pool || memory_pool.total_blocks < MAX_ALLOCATIONS) {
        // Handle allocation failure or exhaustion gracefully
        fprintf(stderr, "Memory pool exhausted.\n");
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL;
    }

    void* ptr = memory_pool.pool;
    memory_pool.pool += size; 
    memory_pool.total_blocks++;

    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void custom_free(void* ptr) {
    // For simplicity, we assume no need for free in this pool
}

void init_memory_pool() {
