#define POOL_SIZE 1024 // Example pool size; adjust as needed

typedef struct {
    long offset;
    int key;
    char device_id[32];
    double sensor_value;
    struct {
        int value1;
        int value2;
    } record;
} SensorData;

// Memory Pool for efficient allocation
char memory_pool[POOL_SIZE * sizeof(SensorData)];
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Head of the free list
SensorData* free_list_head = NULL;

void initialize_memory_pool() {
    pthread_mutex_lock(&pool_mutex);
    free_list_head = (SensorData*)memory_pool;
    SensorData* current = free_list_head;

    for(int i = 0; i < POOL_SIZE - 1; ++i) {
        current->next_free = (SensorData*)(memory_pool + ((i+1) * sizeof(SensorData)));
        current = current->next_free;
    }
    current->next_free = NULL;
    pthread_mutex_unlock(&pool_mutex);
}

void* allocate_sensor_data() {
    pthread_mutex_lock(&pool_mutex);

    SensorData* allocated = free_list_head;
    if (allocated != NULL) {
        free_list_head = allocated->next_free;
    } else {
        fprintf(stderr, "Memory pool exhausted\n");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }

    memset(allocated, 0, sizeof(SensorData));
    pthread_mutex_unlock(&pool_mutex);
    return allocated;
}

void deallocate_sensor_data(void* data) {
    if (data == NULL) return;

    SensorData* sensor_data = (SensorData*)data;
    pthread_mutex_lock(&pool_mutex);

    sensor_data->next_free = free_list_head;
    free_list_head = sensor_data;

    pthread_mutex_unlock(&pool_mutex);
}

// DAO strategy interface
typedef struct {
