}

// Initialize a Data Accessor with a strategy
void initialize_data_accessor(DataAccessor* accessor, DAOStrategy* strategy, void* context) {
    accessor->strategy = strategy;
    accessor->context = context;
}

// Usage example:
int main() {
    initialize_memory_pool();

    SensorData* data1 = allocate_sensor_data();
    if (data1 != NULL) {
        data1->offset = 12345L;
        data1->key = 6789;
        strcpy(data1->device_id, "Device_001");
        data1->sensor_value = 98.76;
        data1->record.value1 = rand() % 1000;
        data1->record.value2 = rand() % 1000;

        DAOStrategy strategy = {read_data, write_data};
        DataAccessor accessor;
