    *records = malloc(num_records * sizeof(record *));
    if (*records == NULL) {
        pthread_mutex_unlock(&mutex);
        return MEMORY_ALLOCATION_FAILURE;
    }

    *event_counts = calloc(num_records, sizeof(int));
    if (*event_counts == NULL) {
        free(*records);
