    int num_statuses = sizeof(statuses) / sizeof(statuses[0]);

    for (int i = 0; i < num_records; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Free previously allocated memory
            while (i > 0) {
                free((*records)[--i]);
            }
            free(*records);
            free(*event_counts);
            pthread_mutex_unlock(&mutex);
            return MEMORY_ALLOCATION_FAILURE;
