        if (fetch_metadata_from_api((*records)[i]) != SUCCESS) {
            free((*records)[i]);
            while (i > 0) {
                free((*records)[--i]);
            }
            free(*records);
            free(*event_counts);
            pthread_mutex_unlock(&mutex);
            return API_FETCH_FAILURE;
        }
    }

    pthread_mutex_unlock(&mutex);
    return SUCCESS;
}

void free_records(int num_records, record **records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
