#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct MemoryPool {
    long *offsets;
    int capacity_offsets;
    int count_offsets;

    int *keys;
    int capacity_keys;
    int count_keys;

    record *records;
    int capacity_records;
    int count_records;

    pthread_mutex_t lock;
    unsigned int ref_count;
} MemoryPool;

#define INITIAL_CAPACITY 10
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100

MemoryPool* create_memory_pool() {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->offsets = calloc(INITIAL_CAPACITY, sizeof(long));
    pool->keys = calloc(INITIAL_CAPACITY, sizeof(int));
    pool->records = calloc(INITIAL_CAPACITY, sizeof(record));

    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool->offsets);
        free(pool->keys);
        free(pool->records);
        free(pool);
        return NULL;
    }

    pool->capacity_offsets = INITIAL_CAPACITY;
    pool->count_offsets = 0;

    pool->capacity_keys = INITIAL_CAPACITY;
    pool->count_keys = 0;

    pool->capacity_records = INITIAL_CAPACITY;
    pool->count_records = 0;

    pthread_mutex_init(&pool->lock, NULL);
    pool->ref_count = 1; // Initial reference

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool && --pool->ref_count == 0) {
        pthread_mutex_lock(&pool->lock);

        free(pool->offsets);
        free(pool->keys);
        free(pool->records);

        pthread_mutex_unlock(&pool->lock);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int pool_resize(MemoryPool *pool, int capacity_type) {
    if (capacity_type == 0 && pool->count_offsets >= pool->capacity_offsets) {
        long *new_offsets = realloc(pool->offsets, pool->capacity_offsets * 2 * sizeof(long));
        if (!new_offsets) return -1;
        pool->offsets = new_offsets;
        pool->capacity_offsets *= 2;
    } else if (capacity_type == 1 && pool->count_keys >= pool->capacity_keys) {
        int *new_keys = realloc(pool->keys, pool->capacity_keys * 2 * sizeof(int));
        if (!new_keys) return -1;
        pool->keys = new_keys;
        pool->capacity_keys *= 2;
    } else if (capacity_type == 2 && pool->count_records >= pool->capacity_records) {
        record *new_records = realloc(pool->records, pool->capacity_records * 2 * sizeof(record));
        if (!new_records) return -1;
        pool->records = new_records;
        pool->capacity_records *= 2;
    }

    return 0;
}

int add_to_pool(MemoryPool *pool, long offset, int key, record rec) {
    pthread_mutex_lock(&pool->lock);

    if (pool_resize(pool, 0) != 0 || pool_resize(pool, 1) != 0 || pool_resize(pool, 2) != 0) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    pool->offsets[pool->count_offsets++] = offset;
    pool->keys[pool->count_keys++] = key;
    pool->records[pool->count_records++].value = rec.value;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void initialize_record(record *rec) {
    srand(time(NULL));
    rec->value = RANDOM_RANGE_MIN + rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1);
}

void process_input(MemoryPool *pool, int *array, size_t array_size) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < array_size; ++i) {
        initialize_record(&pool->records[pool->count_records]);
        if (add_to_pool(pool, array[i], i, pool->records[pool->count_records - 1]) != 0) {
            fprintf(stderr, "Failed to add record due to memory issues.\n");
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

int find_largest_number(int *array, size_t array_size) {
    int max = INT_MIN;
    for (size_t i = 0; i < array_size; ++i) {
        if (array[i] > max)
            max = array[i];
    }
    return max;
}

void* input_handler(void *arg) {
    MemoryPool *pool = (MemoryPool *) arg;
    int num, count = 0;

    while (scanf("%d", &num) == 1 && count < 10000) { // Limiting to avoid excessive memory use
        if (count >= pool->capacity_offsets) break; // Assuming size limits for simplicity

        int *array = realloc(pool->keys, sizeof(int) * (count + 1));
        if (!array) {
            fprintf(stderr, "Memory allocation failed.\n");
            break;
        }
        pool->keys = array;
        pool->keys[count++] = num;
    }

    pthread_mutex_lock(&pool->lock);
    int largest = find_largest_number(pool->keys, count);
    printf("Largest number: %d\n", largest);

    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

int main() {
    MemoryPool *pool = create_memory_pool();
    if (!pool) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, input_handler, (void *) pool);

    pthread_join(thread_id, NULL);

    destroy_memory_pool(pool);

    return EXIT_SUCCESS;
}
