#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t data;
} custom_record_t;

// Define a simple memory pool for the records
typedef struct {
    void *pool;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} memory_pool_t;

memory_pool_t mem_pool = {NULL, 0, 0, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to initialize the memory pool
int init_memory_pool(size_t block_size, size_t num_blocks) {
    pthread_mutex_lock(&mem_pool.lock);
    if (mem_pool.pool != NULL) {
        pthread_mutex_unlock(&mem_pool.lock);
        return -1; // Already initialized
    }

    mem_pool.block_size = block_size;
    mem_pool.total_blocks = num_blocks;

    mem_pool.pool = malloc(block_size * num_blocks);
    if (!mem_pool.pool) {
        pthread_mutex_unlock(&mem_pool.lock);
        return -1;
    }

    mem_pool.used_blocks = 0;
    pthread_mutex_unlock(&mem_pool.lock);
    return 0;
}

// Function to allocate a record from the pool
custom_record_t *allocate_record_from_pool(int key, int value_range_min, int value_range_max) {
    if (pthread_mutex_trylock(&mem_pool.lock) != 0) {
        // Mutex is busy; try later or handle differently in real usage
        return NULL;
    }

    if (mem_pool.used_blocks >= mem_pool.total_blocks) {
        pthread_mutex_unlock(&mem_pool.lock);
        return NULL;
    }

    custom_record_t *record = 
        (custom_record_t *)((char *)mem_pool.pool + (mem_pool.block_size * mem_pool.used_blocks));
    record->offset = rand();
    record->key = key;
    record->data.value = rand() % (value_range_max - value_range_min + 1) + value_range_min;

    mem_pool.used_blocks++;
    pthread_mutex_unlock(&mem_pool.lock);
    return record;
}

// Function to free the memory pool
void free_memory_pool() {
    pthread_mutex_lock(&mem_pool.lock);
    if (mem_pool.pool != NULL) {
        free(mem_pool.pool);
        mem_pool.pool = NULL;
        mem_pool.used_blocks = 0;
    }
    pthread_mutex_unlock(&mem_pool.lock);
}

// Helper function to find the largest integer in an array
int find_largest(int *array, size_t size) {
    if (size == 0) return -1;

    int max_val = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max_val) {
            max_val = array[i];
        }
    }
    return max_val;
}

// Thread-safe function to handle concurrent accesses
void *thread_function(void *arg) {
    int key = *(int *)arg;
    custom_record_t *record = allocate_record_from_pool(key, 0, 100);

    if (record != NULL) {
        printf("Record created with key: %d and value: %d\n", record->key, record->data.value);
    }

    pthread_exit(NULL);
}

int main() {
    srand(time(0));

    // Initialize the memory pool
    if (init_memory_pool(sizeof(custom_record_t), MAX_RECORDS) != 0) {
        fprintf(stderr, "Failed to initialize memory pool\n");
        return EXIT_FAILURE;
    }

    int *input_array = NULL;
    size_t array_size = 0;

    printf("Enter integers (end with a non-integer): ");
    while (scanf("%d", &((int *)realloc(input_array, sizeof(int) * (array_size + 1)))[array_size++]) == 1) {
        // Reading input into dynamic array
    }

    if (array_size > 0) {
        printf("Largest integer: %d\n", find_largest(input_array, array_size));
    } else {
        printf("No integers entered.\n");
    }

    free(input_array);

    // Create threads to test concurrency
    pthread_t threads[MAX_RECORDS];
    int keys[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS && i < array_size; ++i) {
        keys[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &keys[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
        }
    }

    for (int i = 0; i < MAX_RECORDS && i < array_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory pool
    free_memory_pool();

    return EXIT_SUCCESS;
}
