    private static int processCallCount = 0;

    public static void main(String[] args) {
        // Example usage of the string processing functionality
        StringBuilder resultBuilder = new StringBuilder();
        String processedString = processStringWithLimit("HelloWorld", 10, resultBuilder);
        System.out.println(processedString);

        // Example usage of the command execution functionality
        executeCommandAsync("ls -l", "tempfile.txt");
    }

    public static String processStringWithLimit(String input, int sizeLimit, StringBuilder output) {
        if (input == null || sizeLimit <= 0) {
            logger.warning("Invalid input or size limit.");
            return null;
        }

        processCallCount++;
        logger.info("processStringWithLimit called " + processCallCount + " times.");

        char[] charArray = new char[input.length()];
        for (int i = 0; i < input.length(); i++) {
            charArray[i] = input.charAt(i);
        }

        if (input.length() <= sizeLimit) {
            output.append(charArray).append('/');
        } else {
            output.append("String exceeds limit.");
        }

        logger.info("Processed string: " + output.toString());
        return output.toString();
    }

    public static void executeCommandAsync(String command, String tempFilePath) {
        ExecutorService executor = Executors.newSingleThreadExecutor();

        Future<?> future = executor.submit(() -> {
            try {
                // Check and delete the temporary file if it exists
                Path path = Paths.get(tempFilePath);
                if (Files.exists(path)) {
                    Files.delete(path);
                    logger.info("Deleted existing temp file: " + tempFilePath);
                }

                ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
                processBuilder.redirectErrorStream(true);

                long startTime = System.currentTimeMillis();
                long timeout = 5000; // Timeout in milliseconds

                try (Process process = processBuilder.start()) {
                    ExecutorService streamExecutor = Executors.newCachedThreadPool();

                    CompletableFuture<Void> outputFuture = handleStreamAsync(process.getInputStream(), "Output", streamExecutor);
                    CompletableFuture<Void> errorFuture = handleStreamAsync(process.getErrorStream(), "Error", streamExecutor);

                    // Wait for the command to complete or timeout
                    if (!process.waitFor(timeout, TimeUnit.MILLISECONDS)) {
                        process.destroy();
                        logger.warning("Command timed out.");
                    }

                    // Shutdown streams executor and wait for completion
                    streamExecutor.shutdown();
                    try {
                        if (!outputFuture.get() || !errorFuture.get()) {
                            throw new IOException("Stream handling failed");
                        }
                    } catch (InterruptedException | ExecutionException e) {
                        Thread.currentThread().interrupt();
                        logger.log(Level.SEVERE, "Error handling streams", e);
                    }

                    long duration = System.currentTimeMillis() - startTime;
                    logger.info("Command executed in: " + duration + "ms");

                } catch (IOException | InterruptedException e) {
                    logger.log(Level.SEVERE, "Exception during command execution", e);
                }
            } finally {
                executor.shutdown();
            }
        });

        try {
            future.get(); // Wait for the command to complete
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            logger.log(Level.SEVERE, "Error in command execution task", e);
        }
    }

    private static CompletableFuture<Void> handleStreamAsync(InputStream inputStream, String streamType, ExecutorService executor) {
        return CompletableFuture.runAsync(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    logger.info(streamType + ": " + line);
                }
            } catch (IOException e) {
                logger.log(Level.SEVERE, streamType + " handling error", e);
            }
        }, executor);
    }
}
