    printf("%s\n", message);
}

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->block_size = block_size;
    mp->total_blocks = total_blocks;
    mp->pool = calloc(total_blocks * block_size, 1);
    pthread_mutex_init(&mp->lock, NULL);

    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    log_message("Memory pool created.");
    return mp;
}

void destroy_memory_pool(MemoryPool* mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
    log_message("Memory pool destroyed.");
}

// Core functions
DataContainer* initialize_data_container(size_t capacity, size_t offset_block_size, size_t key_block_size, size_t record_block_size) {
    DataContainer* dc = malloc(sizeof(DataContainer));
    if (!dc) return NULL;

    dc->capacity = capacity;
    dc->offsets = calloc(capacity, sizeof(long));
    dc->keys = calloc(capacity, sizeof(int));
    dc->records = (record*)malloc(capacity * sizeof(record));

    if (!dc->offsets || !dc->keys || !dc->records) {
        free(dc->offsets);
        free(dc->keys);
        free(dc->records);
        free(dc);
        log_message("Initialization failed due to allocation error.");
        return NULL;
    }

    dc->mp = create_memory_pool(record_block_size, capacity);
    if (!dc->mp) {
        free(dc->offsets);
        free(dc->keys);
        free(dc->records);
        free(dc);
        log_message("Initialization failed: Memory pool creation failed.");
        return NULL;
    }

    pthread_mutex_init(&dc->mutex, NULL);
    pthread_rwlock_init(&dc->rwlock, NULL);

    for (size_t i = 0; i < capacity; ++i) {
        dc->records[i].value = rand() % 100 + 1; // Random number between 1 and 100
    }

    log_message("Data container initialized.");
    return dc;
}

void destroy_data_container(DataContainer* dc) {
    if (dc) {
        free(dc->offsets);
        free(dc->keys);
        for (size_t i = 0; i < dc->capacity; ++i) {
            pthread_mutex_lock(&dc->mutex); // Ensure safe concurrent access
            free(((char*)dc->mp.pool) + (i * dc->mp.block_size));
            pthread_mutex_unlock(&dc->mutex);
        }
        destroy_memory_pool(dc->mp);
        free(dc->records);
        pthread_mutex_destroy(&dc->mutex);
        pthread_rwlock_destroy(&dc->rwlock);
        free(dc);
        log_message("Data container destroyed.");
    }
}

void resize_data_container(DataContainer* dc, size_t new_capacity) {
    if (!dc || !new_capacity) return;

    long* new_offsets = realloc(dc->offsets, new_capacity * sizeof(long));
    int* new_keys = realloc(dc->keys, new_capacity * sizeof(int));
    record* new_records = (record*)realloc(dc->records, new_capacity * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        log_message("Resize failed due to allocation error.");
        return;
    }

    dc->capacity = new_capacity;
    dc->offsets = new_offsets;
    dc->keys = new_keys;
    dc->records = new_records;

    for (size_t i = dc->capacity / 2; i < new_capacity; ++i) {
        dc->records[i].value = rand() % 100 + 1;
    }

    log_message("Data container resized.");
}

void refresh_data(DataContainer* dc) {
    if (!dc) return;

    pthread_rwlock_wrlock(&dc->rwlock);
    for (size_t i = 0; i < dc->capacity; ++i) {
        dc->records[i].value = rand() % 100 + 1;
    }
    pthread_rwlock_unlock(&dc->rwlock);

    log_message("Data refreshed.");
}

// Example usage
int main() {
    srand(time(NULL));

    DataContainer* container = initialize_data_container(MAX_CAPACITY, sizeof(long), sizeof(int), sizeof(record));
    if (container) {
        refresh_data(container);
        resize_data_container(container, MAX_CAPACITY * 2);

        destroy_data_container(container);
    }

    return 0;
}
