    STATUS_ERROR
} Status;

// Structure to hold a record
typedef struct {
    long offset;
    int key;
    double data_value;
    Status status;
    int value;
    float average;
    char status_indicator;
    time_t timestamp; // Use time_t for simplicity
} Record;

// Define a structure for the memory pool node
typedef struct MemoryNode {
    Record *record;
    struct MemoryNode *next;
} MemoryNode;

// Global variables for memory management and logging
MemoryNode *memory_pool_head = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
sem_t resource_semaphore; // For backpressure

// Function to initialize a record (stub)
Record* init_record(long offset, int key, double data_value, Status status, int value, float average, char status_indicator) {
