    if (!new_record) return NULL;

    new_record->offset = offset;
    new_record->key = key;
    new_record->data_value = data_value;
    new_record->status = status;
    new_record->value = value;
    new_record->average = average;
    new_record->status_indicator = status_indicator;
    new_record->timestamp = time(NULL);

    // Log allocation
    printf("Record allocated at offset %ld\n", offset);

    return new_record;
}

// Function to acquire a record from memory pool or allocate new one (with caching mechanism)
Record* acquire_record(long offset, int key, double data_value, Status status, int value, float average, char status_indicator) {
    pthread_mutex_lock(&pool_lock);

    MemoryNode *current = memory_pool_head;
    while (current != NULL) {
        if (!current->record->status_indicator) { // Assume empty if indicator is not set
            current->record->offset = offset;
            current->record->key = key;
            current->record->data_value = data_value;
            current->record->status = status;
            current->record->value = value;
            current->record->average = average;
            current->record->status_indicator = status_indicator;
            current->record->timestamp = time(NULL);

            // Log reuse
            printf("Record reused from pool at offset %ld\n", offset);

            pthread_mutex_unlock(&pool_lock);
            return current->record;
        }
        current = current->next;
    }

    Record *new_record = init_record(offset, key, data_value, status, value, average, status_indicator);

    if (new_record) {
        MemoryNode *new_node = (MemoryNode *)malloc(sizeof(MemoryNode));
        new_node->record = new_record;
        new_node->next = memory_pool_head;
        memory_pool_head = new_node;
    }

    pthread_mutex_unlock(&pool_lock);
    return new_record;
}

// Function to release a record back to pool
void release_record(Record *record) {
    if (!record) return;

    pthread_mutex_lock(&pool_lock);

    // Mark as reusable (set status_indicator to 0)
    record->status_indicator = '\0';

    MemoryNode *current = memory_pool_head;
    while (current != NULL && current->record != record) {
        current = current->next;
    }

    if (current) {
        // Log release
        printf("Record released back to pool at offset %ld\n", record->offset);

        // Remove from list
        MemoryNode *to_free = memory_pool_head;
        memory_pool_head = memory_pool_head->next;
        free(to_free->record);  // Free the record itself
        free(to_free);          // Free the node
    }

    pthread_mutex_unlock(&pool_lock);
}

// Function to cleanup memory pool on shutdown (graceful handling of leaks)
void cleanup_memory_pool() {
    pthread_mutex_lock(&pool_lock);

    MemoryNode *current = memory_pool_head;
    while (current != NULL) {
        MemoryNode *to_free = current;
        current = current->next;

        // Log cleanup
        printf("Cleaning up record at offset %ld\n", to_free->record->offset);

        free(to_free->record);
        free(to_free);
    }

    pthread_mutex_unlock(&pool_lock);
