['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRING_LENGTH 64

typedef struct {
    int key;
    long offset;
    char *data;
} Record;

typedef struct {
    Record **records;
    size_t record_count;
    pthread_mutex_t mutex;
} DataStore;

void initialize_random() {
    srand((unsigned int) time(NULL));
}

int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char random_char() {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t index = rand() % (sizeof(charset) - 1);
    return charset[index];
}

void generate_random_string(char *str, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        str[i] = random_char();
    }
    str[length] = '\0';
}

DataStore* initialize_data_store(size_t record_count, size_t max_memory_budget, size_t string_memory_limit) {
    if (record_count == 0 || max_memory_budget == 0) return NULL;

    DataStore *store = malloc(sizeof(DataStore));
    if (!store) return NULL;

    pthread_mutex_init(&store->mutex, NULL);
    store->records = calloc(record_count, sizeof(Record*));
    if (!store->records) {
        free(store);
        return NULL;
    }
    store->record_count = record_count;

    size_t total_string_memory_used = 0;
    for (size_t i = 0; i < record_count; ++i) {
        pthread_mutex_lock(&store->mutex);

        Record *record = malloc(sizeof(Record));
        if (!record) {
            // Free previously allocated memory in case of failure
            for (size_t j = 0; j < i; ++j) free(store->records[j]);
            free(store->records);
            pthread_mutex_destroy(&store->mutex);
            free(store);
            return NULL;
        }

        record->key = random_int(1, 1000); // Example range
        record->offset = (long)i * sizeof(Record);

        size_t string_length = MAX_STRING_LENGTH;
        if (total_string_memory_used + (string_length + 1) > string_memory_limit) {
            string_length = string_memory_limit - total_string_memory_used - 1;
        }
        record->data = malloc(string_length + 1);
        if (!record->data) {
            free(record);
            for (size_t j = 0; j < i; ++j) free(store->records[j]);
            free(store->records);
            pthread_mutex_destroy(&store->mutex);
            free(store);
            return NULL;
        }

        generate_random_string(record->data, string_length);
        total_string_memory_used += (string_length + 1);

        store->records[i] = record;

        pthread_mutex_unlock(&store->mutex);
    }

    // Validation and error handling
    for (size_t i = 0; i < record_count; ++i) {
        if (!store->records[i]) {
            // Free previously allocated memory in case of failure
            for (size_t j = 0; j <= i; ++j) free(store->records[j]);
            free(store->records);
            pthread_mutex_destroy(&store->mutex);
            free(store);
            return NULL;
        }
    }

    return store;
}

void cleanup_data_store(DataStore *store) {
    if (!store) return;

    pthread_mutex_lock(&store->mutex);

    for (size_t i = 0; i < store->record_count; ++i) {
        if (store->records[i]) {
            free(store->records[i]->data);
            free(store->records[i]);
        }
    }

    free(store->records);
    pthread_mutex_unlock(&store->mutex);

    pthread_mutex_destroy(&store->mutex);
    free(store);
}
