                   Record ***records, size_t *numRecords,
                   long **offsets, int **keys, MemoryLogEntry logs[]);

void deallocateMemory(Record **records, size_t numRecords,
                      long *offsets, int *keys, MemoryLogEntry logs[], size_t logCount);

size_t getCurrentMemoryUsage(size_t numRecords);
void initializeRandom(int minRange, int maxRange);

// Function to allocate memory dynamically
int allocateMemory(long offsetSize, int keySize, long maxMemoryLimit,
                   Record ***records, size_t *numRecords,
                   long **offsets, int **keys, MemoryLogEntry logs[]) {
    size_t recordSize = sizeof(Record);
    long offsetMemRequired = offsetSize * sizeof(long);
    long keyMemRequired = keySize * sizeof(int);

    // Calculate total memory required
    for (size_t i = 1; ; ++i) {
        size_t recordsMemRequired = i * recordSize;
        long totalMemRequired = offsetMemRequired + keyMemRequired + recordsMemRequired;

        if (totalMemRequired > maxMemoryLimit) break;

        // Check the remaining memory usage
        *numRecords = i;
    }

    if (*numRecords == 0) return -1; // Memory allocation failed

    size_t numAllocations = 3;  // offsets, keys, records

    long totalBytesAllocated = offsetMemRequired + keyMemRequired +
                               (*numRecords * recordSize);

    for (size_t j = 0; j < numAllocations; ++j) {
        if (j == 0) {
            *offsets = malloc(offsetMemRequired);
            logs[j].operation = "Allocate offsets";
        } else if (j == 1) {
            *keys = malloc(keyMemRequired);
            logs[j].operation = "Allocate keys";
        } else {
            *records = malloc(*numRecords * recordSize);
            logs[j].operation = "Allocate records";
        }

        if (!(*offsets || *keys || *records)) return -1; // Check for allocation failure

        logs[j].bytes = (j == 0) ? offsetMemRequired : ((j == 1) ? keyMemRequired : (*numRecords * recordSize));
    }

    return 0;
}

// Function to deallocate memory
void deallocateMemory(Record **records, size_t numRecords,
                      long *offsets, int *keys, MemoryLogEntry logs[], size_t logCount) {
    for (size_t i = 0; i < logCount; ++i) {
        if (logs[i].operation[6] == 'f') { // Check if operation is "Free"
            free(logs[i].bytes);
        }
    }

    free(records);
    free(offsets);
    free(keys);
}

// Function to get the current memory usage
