                       &offsets, &keys, logs) != 0) {
        printf("Failed to allocate memory.\n");
        return -1;
    }

    initializeRandom(1, 100); // Example range for random values

    size_t usedBytes = getCurrentMemoryUsage(numRecords);
    long remainingCapacity = maxMemoryLimit - usedBytes;

    printf("Used bytes: %zu\n", usedBytes);
    printf("Remaining capacity: %ld\n", remainingCapacity);

    deallocateMemory(records, numRecords, offsets, keys, logs, logCount);
