#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct MetaRecord {
    Record *record_ptr;
    long offset;
    int key;
    size_t size;
    char type[16];
} MetaRecord;

typedef struct MemoryPool {
    void **blocks;
    size_t block_size;
    size_t total_blocks;
    size_t used_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables
MemoryPool memory_pool = {NULL, 0, 0, 0, PTHREAD_MUTEX_INITIALIZER};
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void init_log(const char *filename) {
    log_file = fopen(filename, "a");
}

void log_message(const char *message) {
    pthread_mutex_lock(&log_lock);
    if (log_file) fprintf(log_file, "%s\n", message);
    fflush(log_file); // Ensure logs are written immediately
    pthread_mutex_unlock(&log_lock);
}

void init_memory_pool(size_t block_size, size_t initial_blocks) {
    pthread_mutex_lock(&memory_pool.lock);

    memory_pool.block_size = block_size;
    memory_pool.total_blocks = initial_blocks;
    memory_pool.blocks = malloc(sizeof(void *) * initial_blocks);

    if (memory_pool.blocks == NULL) {
        log_message("Memory allocation failed for pool initialization.");
        pthread_mutex_unlock(&memory_pool.lock);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initial_blocks; ++i) {
        memory_pool.blocks[i] = malloc(block_size);
        if (memory_pool.blocks[i] == NULL) {
            log_message("Memory allocation failed within pool initialization.");
            pthread_mutex_unlock(&memory_pool.lock);
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_unlock(&memory_pool.lock);
}

void *allocate_from_pool() {
    pthread_mutex_lock(&memory_pool.lock);

    if (memory_pool.used_blocks >= memory_pool.total_blocks) {
        size_t new_blocks = memory_pool.total_blocks * 2;
        void **new_block_array = realloc(memory_pool.blocks, sizeof(void *) * new_blocks);

        if (new_block_array == NULL) {
            log_message("Memory reallocation failed during pool expansion.");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }

        memory_pool.total_blocks = new_blocks;
        memory_pool.blocks = new_block_array;

        for (size_t i = memory_pool.used_blocks; i < new_blocks; ++i) {
            memory_pool.blocks[i] = malloc(memory_pool.block_size);
            if (memory_pool.blocks[i] == NULL) {
                log_message("Memory allocation failed during pool expansion.");
                pthread_mutex_unlock(&memory_pool.lock);
                return NULL;
            }
        }
    }

    void *allocated_memory = memory_pool.blocks[memory_pool.used_blocks++];
    pthread_mutex_unlock(&memory_pool.lock);

    log_message("Allocated block from memory pool.");

    return allocated_memory;
}

void deallocate_from_pool(void *ptr) {
    if (!ptr) return;

    for (size_t i = 0; i < memory_pool.total_blocks; ++i) {
        if (memory_pool.blocks[i] == ptr) {
            pthread_mutex_lock(&memory_pool.lock);

            free(memory_pool.blocks[i]);
            memory_pool.blocks[i] = memory_pool.blocks[--memory_pool.used_blocks];

            pthread_mutex_unlock(&memory_pool.lock);

            log_message("Deallocated block from memory pool.");
            return;
        }
    }
}

void *create_record(size_t index, int key) {
    Record *record = (Record *)allocate_from_pool();
    if (!record) return NULL;

    record->value = rand() % 100 + 1; // Initialize with a random value in range [1, 100]

    log_message("Created and initialized new record.");

    MetaRecord *meta_record = (MetaRecord *)allocate_from_pool();
    if (!meta_record) {
        deallocate_from_pool(record);
        return NULL;
    }

    meta_record->record_ptr = record;
    meta_record->offset = index;
    meta_record->key = key;
    strncpy(meta_record->type, "Standard", sizeof(meta_record->type));
    meta_record->size = sizeof(Record);

    log_message("Created and initialized new meta-record.");

    return (void *)meta_record;
}

int read_input_and_find_largest() {
    int count;
    scanf("%d", &count);

    long *offsets = (long *)malloc(count * sizeof(long));
    int *keys = (int *)malloc(count * sizeof(int));
    void **records = malloc(count * sizeof(void *));

    if (!offsets || !keys || !records) {
        log_message("Failed to allocate arrays for input processing.");
        return -1;
    }

    srand((unsigned)time(NULL));

    int largest_value = INT_MIN;

    pthread_mutex_t max_lock = PTHREAD_MUTEX_INITIALIZER;
    void *max_args[3] = {&largest_value, &max_lock, NULL};

    #define MAX_THREADS 4
    pthread_t threads[MAX_THREADS];
    size_t chunk_size = (count + MAX_THREADS - 1) / MAX_THREADS;

    for (size_t t = 0; t < MAX_THREADS && count > 0; ++t) {
        size_t start_index = t * chunk_size;
        size_t end_index = start_index + chunk_size > count ? count : start_index + chunk_size;

        if (start_index >= count) continue;

        void *(*thread_func)(void *) = find_largest_in_chunk;
        void *args[3] = {(void *)&offsets, (void *)&keys, (void *)(size_t)start_index};
        pthread_create(&threads[t], NULL, thread_func, args);

        count -= chunk_size;
    }

    for (int t = 0; t < MAX_THREADS; ++t) {
        if (pthread_tryjoin_np(threads[t], NULL)) continue; // Non-blocking join
    }

    log_message("Completed finding the largest value in input data.");

    printf("Largest Value: %d\n", largest_value);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}

void *find_largest_in_chunk(void *args) {
    long **offsets = (long **)args;
    int **keys = (int **)args + 1;
    size_t start_index = *(size_t *)(args + 2);

    pthread_mutex_t *max_lock = (pthread_mutex_t *)args[3];
    int local_largest_value = INT_MIN;

    for (size_t i = start_index; i < (start_index + chunk_size) && i < count; ++i) {
        MetaRecord *meta_record = create_record(i, (*keys)[i]);

        if (!meta_record) continue;

        records[i] = meta_record;

        pthread_mutex_lock(max_lock);
        if ((*offsets)[i] == -1 || local_largest_value > meta_record->record_ptr->value) {
            local_largest_value = meta_record->record_ptr->value;
            (*offsets)[i] = i;
        }
        pthread_mutex_unlock(max_lock);

        log_message("Processed record in thread-safe manner.");
    }

    return NULL;
}

int main() {
    init_log("system.log");

    init_memory_pool(sizeof(Record), 10); // Initialize memory pool

    if (read_input_and_find_largest() != 0) {
        log_message("Error occurred during input processing or finding largest value.");
    }

    // Deallocate remaining resources
    for (size_t i = 0; i < memory_pool.used_blocks; ++i) {
        deallocate_from_pool(memory_pool.blocks[i]);
    }

    free(memory_pool.blocks);
    fclose(log_file);

    return 0;
}
