class DynamicResourceAndDataManager {
private:
    std::vector<long> longArray;
    std::vector<int> intArray;
    struct Record {
        int intValue;
        double doubleValue;
    };
    std::vector<Record> recordArray;

    std::mutex arrayMutex;

    // Memory pool and cache management (simplified example)
    size_t memoryPoolSize = 1024 * 1024; // 1 MB for demonstration
    char* memoryPool;
    size_t offset = 0;

    void initializeMemoryPool() {
        memoryPool = new char[memoryPoolSize];
    }

public:
    DynamicResourceAndDataManager()
    : longArray(), intArray(), recordArray() {
        initializeMemoryPool();
    }

    ~DynamicResourceAndDataManager() {
        delete[] memoryPool;
    }

    void allocateRecord(Record& rec) {
        if (offset + sizeof(rec) > memoryPoolSize) {
            throw std::runtime_error("Out of Memory");
        }
        memcpy(memoryPool + offset, &rec, sizeof(rec));
        offset += sizeof(rec);
    }

    void storeIntegers() {
        int num;
        while (std::cin >> num) {
            std::lock_guard<std::mutex> lock(arrayMutex);
            intArray.push_back(num);
        }
    }

    int findLargestInteger() const {
        int maxVal = INT_MIN;
        std::lock_guard<std::mutex> lock(arrayMutex);

        for (const auto& val : intArray) {
            if (val > maxVal) {
                maxVal = val;
            }
        }

        return maxVal;
    }

    void printLargestInteger() const {
        int largest = findLargestInteger();
        std::cout << "The largest integer is: " << largest << std::endl;
    }
};

class DynamicDataGenerator {
private:
    double minValue, maxValue, stepSize;

    std::random_device rd;
    std::mt19937 gen;
    std::uniform_real_distribution<> floatDist;
    std::uniform_int_distribution<> intDist;

    void updateDistributions() {
        floatDist = std::uniform_real_distribution<>(minValue, maxValue);
        intDist = std::uniform_int_distribution<>(static_cast<int>(minValue), static_cast<int>(maxValue));
    }

public:
    DynamicDataGenerator(double min = 0.0, double max = 1.0, double step = 0.01)
    : minValue(min), maxValue(max), stepSize(step), gen(rd()) {
        if (minValue >= maxValue) throw std::invalid_argument("Invalid range");
        updateDistributions();
    }

    void UpdateRange(double min, double max) {
        if (min >= max) throw std::invalid_argument("Invalid range");
        minValue = min;
        maxValue = max;
        stepSize = (max - min) / 10; // Example of setting step size
        updateDistributions();
    }

    double GetRandomFloat() {
        return round(floatDist(gen) * (1.0/stepSize)) * stepSize;
    }

    int GetRandomInt() {
        return intDist(gen);
    }

    std::vector<int> GetRandomList(int count) {
        std::vector<int> randomList(count);
        for (int i = 0; i < count; ++i) {
            randomList[i] = GetRandomInt();
        }
        return randomList;
    }

    std::string ToString() const {
        return "[" + std::to_string(minValue) + ", " + std::to_string(maxValue) + "]";
    }

    void serialize(const std::string& filename) const {
        std::ofstream file(filename, std::ios::binary);
        if (!file.is_open()) throw std::runtime_error("Unable to open file for writing");

        double data[3] = {minValue, maxValue, stepSize};
        file.write(reinterpret_cast<const char*>(data), sizeof(data));
    }

    void deserialize(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file.is_open()) throw std::runtime_error("Unable to open file for reading");

        double data[3];
        file.read(reinterpret_cast<char*>(data), sizeof(data));

        minValue = data[0];
        maxValue = data[1];
        stepSize = data[2];

        updateDistributions();
    }
};

// Example of usage
int main() {
    DynamicResourceAndDataManager manager;

    // Reading integers from standard input and storing them.
    std::thread storeIntegersThread(&DynamicResourceAndDataManager::storeIntegers, &manager);
    storeIntegersThread.join();

    manager.printLargestInteger();

    DynamicDataGenerator generator(0.0, 10.0, 1.0);
    std::cout << "Random Float: " << generator.GetRandomFloat() << std::endl;
    std::cout << "Random Int: " << generator.GetRandomInt() << std::endl;

    auto randomList = generator.GetRandomList(5);
    for (int num : randomList) {
        std::cout << num << ' ';
    }
    std::cout << std::endl;

    generator.UpdateRange(1.0, 20.0);
    std::cout << "Updated Range: " << generator.ToString() << std::endl;

    // Example of serialization/deserialization
    generator.serialize("data.bin");
    DynamicDataGenerator newGenerator;
    newGenerator.deserialize("data.bin");

    return 0;
}
