#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a session structure
typedef struct {
    char *session_id;
    time_t last_activity;
    char *location;
    size_t location_length;
} Session;

// Define the hash table node for separate chaining
typedef struct HashNode {
    Session *session;
    struct HashNode *next;
} HashNode;

// Define the hash table structure
typedef struct {
    HashNode **buckets;
    size_t bucket_count;
    pthread_mutex_t lock;
} HashTable;

// Function prototypes
unsigned long hash(const char *str);
HashTable* create_hash_table(size_t initial_size);
void destroy_session(Session *session);
int add_session(HashTable *table, const char *session_id, Session *session);
Session* get_session(HashTable *table, const char *session_id);
void remove_expired_sessions(HashTable *table, time_t current_time);
void log_operation(const char *operation);

// Create a new hash table
HashTable* create_hash_table(size_t initial_size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (HashNode **)calloc(initial_size, sizeof(HashNode *));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->bucket_count = initial_size;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

// Calculate a simple hash
unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c

    return hash;
}

// Add a session to the hash table
int add_session(HashTable *table, const char *session_id, Session *session) {
    unsigned long index = hash(session_id) % table->bucket_count;

    pthread_mutex_lock(&table->lock);

    HashNode *node = (HashNode *)malloc(sizeof(HashNode));
    if (!node) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    node->session = session;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    log_operation("Session added");

    pthread_mutex_unlock(&table->lock);

    return 0;
}

// Get a session by ID
Session* get_session(HashTable *table, const char *session_id) {
    unsigned long index = hash(session_id) % table->bucket_count;

    pthread_mutex_lock(&table->lock);

    HashNode *node = table->buckets[index];
    while (node) {
        if (strcmp(node->session->session_id, session_id) == 0) {
            pthread_mutex_unlock(&table->lock);
            return node->session;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);

    return NULL;
}

// Remove expired sessions
void remove_expired_sessions(HashTable *table, time_t current_time) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        HashNode **node = &table->buckets[i];

        while (*node) {
            if (difftime(current_time, (*node)->session->last_activity) > 3600) { // Example expiration time
                HashNode *to_remove = *node;
                *node = (*node)->next;

                destroy_session(to_remove->session);
                free(to_remove);

                log_operation("Expired session removed");
            } else {
                node = &(*node)->next;
            }
        }
    }
}

// Destroy a session
void destroy_session(Session *session) {
    if (session) {
        free(session->session_id);
        free(session->location);
        free(session);
    }
}

// Log operations to a file
void log_operation(const char *operation) {
    FILE *log_file = fopen("operations.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s - %s\n", ctime(&now), operation);
        fclose(log_file);
    }
}

int main() {
    // Example usage
    HashTable *table = create_hash_table(16);
    if (!table) return 1;

    Session *session = (Session *)malloc(sizeof(Session));
    session->session_id = strdup("session123");
    session->last_activity = time(NULL);

    size_t location_length = rand() % 100 + 1;
    session->location = malloc(location_length);
    for (size_t i = 0; i < location_length; ++i) {
        session->location[i] = 'A' + rand() % 26;
    }
    session->location[location_length - 1] = '\0';

    add_session(table, session->session_id, session);

    Session *retrieved_session = get_session(table, "session123");
    if (retrieved_session) {
        printf("Session found: %s\n", retrieved_session->location);
    }

    remove_expired_sessions(table, time(NULL));

    // Cleanup
    for (size_t i = 0; i < table->bucket_count; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *to_remove = node;
            node = node->next;

            destroy_session(to_remove->session);
            free(to_remove);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);

    return 0;
}
