    manager->enable_pooling = 1; // Default to enabled

    return manager;
}

// Function to handle connection requests
void* request_connection(void *arg) {
    ConnectionManager *manager = (ConnectionManager *)arg;

    pthread_mutex_lock(&manager->pool->lock);
    if (manager->pool->current_connections < manager->pool->max_connections) {
        // Simulate obtaining a connection
        printf("Acquiring connection...\n");
        manager->pool->current_connections++;
    } else {
        printf("Max connections reached. Waiting...\n");
        pthread_mutex_unlock(&manager->pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&manager->pool->lock);

    // Simulate using the connection
    sleep(1);

    pthread_mutex_lock(&manager->pool->lock);
    manager->pool->current_connections--;
    printf("Releasing connection...\n");
    pthread_mutex_unlock(&manager->pool->lock);

    return NULL;
