import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

// Transaction class
class Transaction {
    private String transactionId;
    private long timestamp;
    private double amount;
    private String currency;
    private Map<String, String> userMetadata;

    public Transaction(String transactionId, long timestamp, double amount, 
                       String currency, Map<String, String> userMetadata) {
        this.transactionId = transactionId;
        this.timestamp = timestamp;
        this.amount = amount;
        this.currency = currency;
        this.userMetadata = userMetadata;
    }

    // Getters and other methods

    public long getTimestamp() { return timestamp; }
    public String getCurrency() { return currency; }
    public Map<String, String> getUserMetadata() { return userMetadata; }
}

// Strategy interface for filtering transactions
interface FilterStrategy {
    boolean apply(Transaction transaction);
}

// Concrete filter strategies
class DateRangeFilter implements FilterStrategy {
    private long startDate;
    private long endDate;

    public DateRangeFilter(long startDate, long endDate) {
        this.startDate = startDate;
        this.endDate = endDate;
    }

    @Override
    public boolean apply(Transaction transaction) {
        return transaction.getTimestamp() >= startDate && transaction.getTimestamp() <= endDate;
    }
}

class TransactionTypeFilter implements FilterStrategy {
    private String requiredCurrency;

    public TransactionTypeFilter(String requiredCurrency) {
        this.requiredCurrency = requiredCurrency;
    }

    @Override
    public boolean apply(Transaction transaction) {
        return requiredCurrency.equals(transaction.getCurrency());
    }
}

// TransactionProcessor class to handle streaming and filtering
class TransactionProcessor {
    private final BlockingQueue<Transaction> transactionQueue = new LinkedBlockingQueue<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private List<FilterStrategy> filters;

    public TransactionProcessor(List<FilterStrategy> filters) {
        this.filters = filters;
    }

    public void startProcessing(Path filePath) throws IOException, InterruptedException {
        Files.lines(filePath).forEach(line -> {
            try {
                transactionQueue.put(parseTransaction(line));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        for (int i = 0; i < 4; i++) {
            executor.submit(() -> processTransactions());
        }
    }

    private Transaction parseTransaction(String line) {
        String[] parts = line.split(",");
        Map<String, String> metadata = new HashMap<>();
        // Assuming specific indices for transaction data
        metadata.put("userId", parts[5]);
        return new Transaction(parts[0], Long.parseLong(parts[1]), 
                               Double.parseDouble(parts[2]), parts[3], metadata);
    }

    private void processTransactions() {
        try {
            while (true) {
                Transaction transaction = transactionQueue.take();
                if (filters.stream().allMatch(filter -> filter.apply(transaction))) {
                    // Handle valid transaction
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}

// Main class to run the application
public class TransactionProcessorApp {
    public static void main(String[] args) throws IOException, InterruptedException {
        List<FilterStrategy> filters = Arrays.asList(
            new DateRangeFilter(1609459200000L, 1640995200000L), // Example date range
            new TransactionTypeFilter("USD")
        );

        Path filePath = Paths.get("path/to/your/csvfile.csv");
        TransactionProcessor processor = new TransactionProcessor(filters);
        processor.startProcessing(filePath);

        Runtime.getRuntime().addShutdownHook(new Thread(processor::shutdown));
    }
}
```

### Key Points:
- **Concurrency**: Uses `BlockingQueue` for thread-safe transaction processing and an `ExecutorService` for multi-threaded execution.
- **Filtering Strategy Pattern**: Implements a flexible filtering mechanism using strategy pattern with different filter criteria.
- **Scalability**: Designed to handle high-throughput by allowing horizontal scaling via multiple threads.
- **Graceful Shutdown**: Ensures all resources are properly released on shutdown.
- **Logging & Monitoring**: Can be integrated as needed (e.g., SLF4J, Log4j) for tracking performance and system health.

This code provides a foundation to build upon with additional features like distributed caching, advanced garbage collection tuning, or third-party integrations.']

