}

void initialize_geometries(MemoryPool *pool, Geometry **geometries, int num_geometries) {
    *geometries = pool_alloc(pool, sizeof(Geometry) * num_geometries);
    if (!*geometries) return;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_geometries; i++) {
        Geometry* geom = &(*geometries)[i];

        geom->value = ((double)rand() / RAND_MAX) * 100.0;

        char* str = random_alphanumeric(10);
        geom->string = pool_alloc(pool, sizeof(char) * (strlen(str) + 1));
