        geom->point.x = ((float)rand() / RAND_MAX) * 100.0;
        geom->point.y = ((float)rand() / RAND_MAX) * 100.0;

        free(str);
    }

    pthread_mutex_destroy(&lock);
}

int compare_ints(const void* a, const void* b) {
    return (*(int*)b - *(int*)a);
}

void find_largest(int *array, int size, int *largest, pthread_mutex_t *mutex) {
    qsort(array, size, sizeof(int), compare_ints);
    pthread_mutex_lock(mutex);
    *largest = array[0];
    pthread_mutex_unlock(mutex);
}

void process_data(MemoryPool *pool, int **data_array, int *num_elements, int *largest, pthread_t thread_count) {
    *data_array = pool_alloc(pool, sizeof(int) * 1000000); // Assume max input size
    if (!*data_array) return;

