    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < thread_count; i++) {
        pthread_create(NULL, NULL, (void*)find_largest, (void*)&((*data_array), *num_elements, largest, &mutex));
    }
    for (int i = 0; i < thread_count; i++) {
        pthread_join(NULL, NULL);
    }

    pthread_mutex_destroy(&mutex);
}

int main() {
    srand(time(0));

    MemoryPool* pool = create_memory_pool();
    if (!pool) return EXIT_FAILURE;

    Geometry *geometries;
    initialize_geometries(pool, &geometries, 10);

    int num_elements = 0, largest = INT_MIN;
    int *data_array = NULL;
    process_data(pool, &data_array, &num_elements, &largest, 4);

    printf("Largest integer: %d\n", largest);

    destroy_memory_pool(pool);
    if (geometries) free(geometries);
    if (data_array) free(data_array);

    return EXIT_SUCCESS;
}
