// Memory pool structure
typedef struct {
    size_t size;
    char* start;
    char* next_free;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool mem_pool = {POOL_SIZE, NULL, NULL, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool() {
    mem_pool.start = (char*)malloc(mem_pool.size);
    if (!mem_pool.start) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    mem_pool.next_free = mem_pool.start;
}

void* pool_alloc(size_t size) {
    pthread_mutex_lock(&mem_pool.lock);
    if ((size_t)(mem_pool.next_free - mem_pool.start + size) > mem_pool.size) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(EXIT_FAILURE);
    }
    void* ptr = mem_pool.next_free;
    mem_pool.next_free += size;
    pthread_mutex_unlock(&mem_pool.lock);
    return ptr;
}

void free_memory_pool() {
    free(mem_pool.start);
}

