// Memory pool for custom memory allocation
typedef struct {
    size_t block_size;
    void* blocks;
    size_t num_blocks;
} MemoryPool;

MemoryPool create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool mp = {block_size, malloc(block_size * num_blocks), num_blocks};
    return mp;
}

void* pool_alloc(MemoryPool* mp) {
    if (mp->blocks == NULL) {
        return NULL; // Pool exhausted
    }
    void* block = mp->blocks;
    mp->blocks += mp->block_size;
    return block;
}

void destroy_memory_pool(MemoryPool* mp) {
    free(mp->blocks);
    mp->blocks = NULL;
}

// Helper function to calculate moving average (thread-safe)
float calculate_moving_average(TradeEvent* events, size_t count) {
    static threading_mutex_t lock;
    if (lock == 0) { // Initialize once
        threading_mutex_init(&lock, NULL);
