    float sum = 0.0f;
    threading_mutex_lock(&lock);
    for (size_t i = 0; i < count; ++i) {
        sum += events[i].value;
    }
    threading_mutex_unlock(&lock);

    return count > 0 ? sum / count : 0.0f;
}

