template <typename T>
class MemoryPool {
public:
    MemoryPool(size_t size) : poolSize_(size), currentIndex_(0) {
        pool_.reserve(poolSize_);
        for (size_t i = 0; i < poolSize_; ++i) {
            pool_.emplace_back(new T());
        }
    }

    ~MemoryPool() {
        for (auto& ptr : pool_) {
            delete ptr;
        }
    }

    T* allocate() {
        if (currentIndex_ >= poolSize_) throw std::bad_alloc();
        return pool_[currentIndex_++];
    }

    void deallocate(T* ptr) {
        // Simplified: no actual memory reuse for this example
        currentIndex_ = (currentIndex_ > 0) ? --currentIndex_ : currentIndex_;
    }

