#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1000
#define MAX_CAPACITY 10000

typedef struct {
    int value;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    // Additional fields for memory pool management could be added here
} RecordArray;

void log_event(const char *event) {
    printf("Log: %s\n", event);
}

RecordArray* initialize_record_array() {
    RecordArray *arr = malloc(sizeof(RecordArray));
    arr->capacity = INITIAL_CAPACITY;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    arr->records = calloc(arr->capacity, sizeof(record)); // Memory pool initialization
    log_event("Initialized record array");
    return arr;
}

void resize_record_array(RecordArray *arr) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2 > MAX_CAPACITY ? MAX_CAPACITY : arr->capacity * 2;
        record *new_records = realloc(arr->records, new_capacity * sizeof(record));

        if (!new_records && new_capacity > arr->capacity) {
            perror("Failed to resize array");
            pthread_mutex_unlock(&arr->lock);
            return; // Handle allocation failure gracefully
        }

        arr->records = new_records;
        arr->capacity = new_capacity;
        log_event("Resized record array");
    }

    pthread_mutex_unlock(&arr->lock);
}

int add_record(RecordArray *arr, int value) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        resize_record_array(arr);
        if (arr->size >= arr->capacity) { // Check again in case resizing failed
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }
    }

    arr->records[arr->size].value = value;
    arr->size++;
    log_event("Added new record");

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int load_from_external_source(RecordArray *arr, int (*fetch_value)(void)) {
    pthread_mutex_lock(&arr->lock);

    while (1) {
        if (arr->size >= arr->capacity) {
            resize_record_array(arr);
            if (arr->size >= arr->capacity) { // Check again after resizing
                pthread_mutex_unlock(&arr->lock);
                return -1;
            }
        }

        int value = fetch_value();
        if (value == -1) break; // Sentinel value to indicate end of data

        add_record(arr, value); 
    }

    pthread_mutex_unlock(&arr->lock);
    log_event("Loaded records from external source");
    return 0;
}

void free_record_array(RecordArray *arr) {
    pthread_mutex_lock(&arr->lock);

    free(arr->records);
    arr->records = NULL;
    arr->capacity = 0;
    arr->size = 0;

    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
    log_event("Freed record array");
}

// Example usage
int fetch_value() {
    // Replace with actual data fetching logic.
    static int counter = 0;
    if (counter < 20) { // Simulate some external data source
        return counter++;
    }
    return -1; // Sentinel value indicating no more data
}

int main() {
    RecordArray *arr = initialize_record_array();

    load_from_external_source(arr, fetch_value);

    for (size_t i = 0; i < arr->size; ++i) {
        printf("Record %zu: %d\n", i, arr->records[i].value);
    }

    free_record_array(arr);
    return 0;
}
