#include <stdio.h>
#include <stdlib.h>

typedef struct Record {
    long offset;
    int key;
    double precision;
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    Record* tail;
    size_t size;
    // Placeholder for potential hash table or other structures
} LinkedList;

#define INITIAL_POOL_SIZE 1024

// Custom memory pool structure
typedef struct MemoryPool {
    size_t size;
    size_t used;
    void* start;
    void** freeList; 
} MemoryPool;

MemoryPool* create_memory_pool(size_t elementSize, size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->size = elementSize * capacity;
    pool->used = 0;
    pool->start = malloc(pool->size);
    if (!pool->start) {
        free(pool);
        return NULL;
    }
    pool->freeList = (void**)malloc(capacity * sizeof(void*));
    if (!pool->freeList) {
        free(pool->start);
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < capacity - 1; ++i) {
        ((char**)pool->freeList)[i] = (void*)((char*)pool->start + i * elementSize);
        ((char**)((char*)pool->start + i * elementSize))[0] = (void*)((char*)pool->start + (i + 1) * elementSize);
    }
    ((char**)pool->freeList)[capacity - 1] = NULL;

    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t elementSize) {
    if (!pool || pool->used >= pool->size / elementSize)
        return NULL;

    void** freeElement = (void**)pool->freeList;
    pool->freeList = (void**)*freeElement;
    ++pool->used;
    return *freeElement;
}

void deallocate_from_pool(MemoryPool* pool, void* ptr) {
    if (!pool || !ptr)
        return;

    *((char**)ptr) = (void*)pool->freeList;
    pool->freeList = (void**)ptr;
    --pool->used;
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    MemoryPool* recordPool = create_memory_pool(sizeof(Record), INITIAL_POOL_SIZE);
    if (!recordPool) {
        free(list);
        return NULL;
    }

    list->memoryPool = recordPool;

    return list;
}

void destroy_linked_list(LinkedList* list) {
    if (!list) return;

    Record* current = list->head;
    while (current) {
        Record* next = current->next;
        deallocate_from_pool(list->memoryPool, current);
        current = next;
    }

    free(list->memoryPool->freeList);
    free(list->memoryPool->start);
    free(list->memoryPool);

    free(list);
}

Record* create_record(long offset, int key, double precision) {
    Record* newRecord = (Record*)allocate_from_pool(list->memoryPool, sizeof(Record));
    if (!newRecord) return NULL;

    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->precision = precision;
    newRecord->next = NULL;

    return newRecord;
}

void insert_at_head(LinkedList* list, Record* record) {
    if (!list || !record) return;

    record->next = list->head;
    list->head = record;

    if (list->tail == NULL) {
        list->tail = record;
    }

    ++list->size;
}

void insert_at_tail(LinkedList* list, Record* record) {
    if (!list || !record) return;

    record->next = NULL;
    if (list->tail) {
        list->tail->next = record;
    } else {
        list->head = record;
    }

    list->tail = record;
    ++list->size;
}

void delete_from_head(LinkedList* list, Record** outRecord) {
    if (!list || !outRecord || list->head == NULL) return;

    *outRecord = list->head;
    list->head = list->head->next;

    if (list->head == NULL) {
        list->tail = NULL;
    }

    --list->size;
}

void delete_from_tail(LinkedList* list, Record** outRecord) {
    if (!list || !outRecord || list->tail == NULL) return;

    *outRecord = list->tail;

    if (list->head == list->tail) {
        list->head = list->tail = NULL;
    } else {
        Record* current = list->head;
        while (current && current->next != list->tail) {
            current = current->next;
        }

        if (current) {
            current->next = NULL;
            list->tail = current;
        }
    }

    --list->size;
}

int main() {
    LinkedList* list = create_linked_list();
    if (!list) {
        printf("Failed to create linked list\n");
        return 1;
    }

    Record* record1 = create_record(10, 1, 3.14);
    insert_at_head(list, record1);

    Record* record2 = create_record(20, 2, 6.28);
    insert_at_tail(list, record2);

    Record* deletedRecord;
    delete_from_head(list, &deletedRecord);
    if (deletedRecord) {
        deallocate_from_pool(list->memoryPool, deletedRecord);
    }

    destroy_linked_list(list);

    return 0;
}
