#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10000
#define LOAD_FACTOR 0.75

typedef enum {
    ACTIVE,
    INACTIVE,
    EXPIRED
} SessionState;

typedef struct {
    char *session_id;
    time_t timestamp;
    SessionState state;
    pthread_mutex_t lock; // For thread safety per session object
} Session;

// Simulated user management API for validating session IDs
int authenticate_user(const char *session_id) {
    // Stub function to simulate user authentication
    return session_id != NULL && strlen(session_id) > 0;
}

typedef struct {
    Session **table;
    size_t capacity;
    size_t size;
    pthread_mutex_t global_lock; // For resizing and managing the table
} SessionManager;

unsigned long hash_function(const char *str, size_t cap) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % cap;
}

SessionManager* create_session_manager() {
    SessionManager *manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    manager->table = calloc(manager->capacity, sizeof(Session *));
    if (!manager->table) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->global_lock, NULL);
    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->table[i]) {
            free(manager->table[i]->session_id);
            pthread_mutex_destroy(&manager->table[i]->lock);
            free(manager->table[i]);
        }
    }
    free(manager->table);
    pthread_mutex_destroy(&manager->global_lock);
    free(manager);
}

void resize_table(SessionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Session **new_table = calloc(new_capacity, sizeof(Session *));
    if (!new_table) return; // Handle allocation failure gracefully

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->table[i]) {
            size_t index = hash_function(manager->table[i]->session_id, new_capacity);
            pthread_mutex_lock(&manager->global_lock);
            while (new_table[index]) {
                index = (index + 1) % new_capacity;
            }
            new_table[index] = manager->table[i];
            pthread_mutex_unlock(&manager->global_lock);
        }
    }

    free(manager->table);
    manager->table = new_table;
    manager->capacity = new_capacity;
}

void insert_session(SessionManager *manager, const char *session_id) {
    if (!authenticate_user(session_id)) return;

    size_t index = hash_function(session_id, manager->capacity);
    Session *new_session = malloc(sizeof(Session));
    if (!new_session) return; // Handle allocation failure gracefully

    new_session->session_id = strdup(session_id);
    if (!new_session->session_id) {
        free(new_session);
        return;
    }

    new_session->timestamp = time(NULL);
    new_session->state = ACTIVE;

    pthread_mutex_init(&new_session->lock, NULL);

    while (1) {
        pthread_mutex_lock(&manager->global_lock);
        if (!manager->table[index] || strcmp(manager->table[index]->session_id, session_id) == 0) {
            manager->table[index] = new_session;
            break;
        }
        index = (index + 1) % manager->capacity;
    }

    pthread_mutex_unlock(&manager->global_lock);

    if (++(manager->size) > LOAD_FACTOR * manager->capacity) {
        resize_table(manager);
    }
}

Session* get_session(SessionManager *manager, const char *session_id) {
    size_t index = hash_function(session_id, manager->capacity);
    while (1) {
        pthread_mutex_lock(&manager->global_lock);
        Session *session = manager->table[index];
        if (!session || strcmp(session->session_id, session_id) != 0) {
            pthread_mutex_unlock(&manager->global_lock);
            index = (index + 1) % manager->capacity;
        } else {
            pthread_mutex_lock(&session->lock);
            pthread_mutex_unlock(&manager->global_lock);
            return session;
        }
    }
}

void update_session_state(SessionManager *manager, const char *session_id, SessionState state) {
    Session *session = get_session(manager, session_id);
    if (session) {
        pthread_mutex_lock(&session->lock);
        session->state = state;
        pthread_mutex_unlock(&session->lock);
    }
}

void delete_session(SessionManager *manager, const char *session_id) {
    size_t index = hash_function(session_id, manager->capacity);
    while (1) {
        pthread_mutex_lock(&manager->global_lock);
        Session *session = manager->table[index];
        if (!session || strcmp(session->session_id, session_id) != 0) {
            pthread_mutex_unlock(&manager->global_lock);
            index = (index + 1) % manager->capacity;
        } else {
            free(session->session_id);
            pthread_mutex_destroy(&session->lock);
            free(session);

            // Remove from table by replacing with last element
            size_t last_index = manager->size - 1;
            while (last_index > index && !manager->table[last_index]) --last_index;

            if (last_index != index) {
                Session *temp = manager->table[last_index];
                manager->table[last_index] = NULL;
                pthread_mutex_lock(&manager->global_lock);
                while (manager->table[index]) {
                    size_t new_index = hash_function(temp->session_id, manager->capacity);
                    while (manager->table[new_index]) {
                        new_index = (new_index + 1) % manager->capacity;
                    }
                    manager->table[new_index] = temp;
                    index = new_index;
                }
            }

            manager->table[index] = NULL;
            pthread_mutex_unlock(&manager->global_lock);
            break;
        }
    }
}

void iterate_sessions(SessionManager *manager, int from_last) {
    size_t start = (from_last ? manager->size - 1 : 0);
    for (size_t i = 0; i < manager->capacity; ++i) {
        pthread_mutex_lock(&manager->global_lock);
        Session *session = from_last ? manager->table[start] : manager->table[i];
        if (!session) continue;

        start = (start + 1) % manager->capacity;
        if (from_last && start == 0) break;

        printf("Session ID: %s, State: %d\n", session->session_id,
               session->state);
    }
    pthread_mutex_unlock(&manager->global_lock);
}

int main() {
    SessionManager *manager = create_session_manager();
    if (!manager) return EXIT_FAILURE;

    insert_session(manager, "session1");
    update_session_state(manager, "session1", INACTIVE);

    Session *s = get_session(manager, "session1");
    if (s) printf("Retrieved session with state %d\n", s->state);

    iterate_sessions(manager, 0);
    delete_session(manager, "session1");

    destroy_session_manager(manager);
    return EXIT_SUCCESS;
}
