double randomDouble(double min, double max) {
    return (min + ((double)rand() / RAND_MAX) * (max - min));
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <long array size> <int keys size> <record count>\n", argv[0]);
        return EXIT_FAILURE;
    }

