    int intKeysSize = atoi(argv[2]);
    int recordCount = atoi(argv[3]);

    if (recordCount < 20 || recordCount > 1000) {
        fprintf(stderr, "Record count must be between 20 and 1000.\n");
        return EXIT_FAILURE;
    }

    long availableMemory = getAvailableMemory();
    long maxArraySize = calculateMaxArraySize(availableMemory);

    if (longArraySize + intKeysSize > maxArraySize) {
