        return EXIT_FAILURE;
    }

    long *offsetArray = malloc(longArraySize * sizeof(long));
    int *keyArray = malloc(intKeysSize * sizeof(int));

    if (!offsetArray || !keyArray) {
        free(offsetArray);
        free(keyArray);
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    Record *records = malloc(recordCount * sizeof(Record));
    if (!records) {
        free(offsetArray);
        free(keyArray);
        logEvent("Memory allocation for records failed.");
        return EXIT_FAILURE;
    }

