        free(offsetArray);
        free(keyArray);
        free(records);
        logEvent("Memory allocation for timestamps failed.");
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    int uniqueCheckAttempts = 0;
    do {
        memset(timestamps, 0, recordCount * sizeof(double));
        for (int i = 0; i < recordCount; ++i) {
            double newTimestamp;
            do {
                newTimestamp = randomDouble(minTimestamp, maxTimestamp);
            } while (bsearch(&newTimestamp, timestamps, i, sizeof(double), 
                            (int(*)(const void*, const void*)) strcmp) && uniqueCheckAttempts++ < 100);

            if (uniqueCheckAttempts >= 100) {
                handleNetworkFailure(); // Log collision handling attempt
                fprintf(stderr, "Failed to generate unique timestamp after %d attempts.\n", uniqueCheckAttempts);
                free(offsetArray);
                free(keyArray);
                free(records);
