```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 16
#define MAX_RECORDS 10000

typedef struct Record {
    long offset;
    int key;
    double precision;
} Record;

typedef struct ListNode {
    Record record;
    struct ListNode *next;
} ListNode;

typedef struct LinkedList {
    ListNode *head;
    ListNode *tail;
    pthread_mutex_t lock;
} LinkedList;

typedef struct MemoryPool {
    void *pool;
    size_t block_size;
    size_t pool_size;
    unsigned char *free_list;
    pthread_mutex_t mutex;
} MemoryPool;

LinkedList *create_linked_list();
void destroy_linked_list(LinkedList *list, MemoryPool *memory_pool);
ListNode *allocate_node(MemoryPool *memory_pool);
void free_node(ListNode *node, MemoryPool *memory_pool);

void insert_head(LinkedList *list, Record record, MemoryPool *memory_pool);
void delete_head(LinkedList *list, MemoryPool *memory_pool);
void insert_tail(LinkedList *list, Record record, MemoryPool *memory_pool);
void delete_tail(LinkedList *list, MemoryPool *memory_pool);

MemoryPool *create_memory_pool(size_t block_size, size_t pool_size);
void destroy_memory_pool(MemoryPool *pool);

int main() {
    // Example usage
    MemoryPool *memory_pool = create_memory_pool(sizeof(ListNode), INITIAL_SIZE * sizeof(ListNode));
    LinkedList *list = create_linked_list();

    Record rec1 = { .offset = 100, .key = 1, .precision = 3.14 };
    insert_head(list, rec1, memory_pool);

    destroy_linked_list(list, memory_pool);
    destroy_memory_pool(memory_pool);

    return 0;
}

LinkedList *create_linked_list() {
    LinkedList *list = malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList *list, MemoryPool *memory_pool) {
    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *next = current->next;
        free_node(current, memory_pool);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

ListNode *allocate_node(MemoryPool *memory_pool) {
    pthread_mutex_lock(&memory_pool->mutex);
    if (!memory_pool->free_list) {
        pthread_mutex_unlock(&memory_pool->mutex);
        return NULL;  // Out of memory
    }
    ListNode *node = (ListNode *)memory_pool->pool;
    size_t index = *(size_t *)memory_pool->free_list;
    *(size_t *)(memory_pool->free_list) += memory_pool->block_size;

    if (*(size_t *)(memory_pool->free_list) >= memory_pool->pool_size)
        memory_pool->free_list = NULL;

    pthread_mutex_unlock(&memory_pool->mutex);
    return node;
}

void free_node(ListNode *node, MemoryPool *memory_pool) {
    pthread_mutex_lock(&memory_pool->mutex);
    *(size_t *)node = (size_t)memory_pool->free_list;
    memory_pool->free_list = (unsigned char *)node;
    pthread_mutex_unlock(&memory_pool->mutex);
}

void insert_head(LinkedList *list, Record record, MemoryPool *memory_pool) {
    ListNode *new_node = allocate_node(memory_pool);
    if (!new_node) return;

    new_node->record = record;
    new_node->next = list->head;

    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    if (list->tail == NULL)
        list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
}

void delete_head(LinkedList *list, MemoryPool *memory_pool) {
    pthread_mutex_lock(&list->lock);
    if (list->head != NULL) {
        ListNode *temp = list->head;
        list->head = temp->next;
        if (list->head == NULL)
            list->tail = NULL;
        free_node(temp, memory_pool);
    }
    pthread_mutex_unlock(&list->lock);
}

void insert_tail(LinkedList *list, Record record, MemoryPool *memory_pool) {
    ListNode *new_node = allocate_node(memory_pool);
    if (!new_node) return;

    new_node->record = record;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail != NULL)
        list->tail->next = new_node;
    list->tail = new_node;
    if (list->head == NULL)
        list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void delete_tail(LinkedList *list, MemoryPool *memory_pool) {
    pthread_mutex_lock(&list->lock);
    if (list->tail != NULL) {
        if (list->head == list->tail) {
            free_node(list->tail, memory_pool);
            list->head = list->tail = NULL;
        } else {
            ListNode *current = list->head;
            while (current->next != list->tail)
                current = current->next;

            free_node(list->tail, memory_pool);
            list->tail = current;
            list->tail->next = NULL;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

MemoryPool *create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->pool_size = pool_size * block_size;
    pool->pool = malloc(pool->pool_size);
    pool->free_list = (unsigned char *)pool->pool;

    pthread_mutex_init(&pool->mutex, NULL);

    for (size_t i = 0; i < pool_size - 1; ++i)
        *(size_t *)(pool->free_list + i * block_size) = i + 1;

    *(size_t *)(pool->free_list + (pool_size - 1) * block_size) = 0;

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}
```

### Key Points:
- **Memory Pool**: A custom memory pool is used to minimize fragmentation and improve cache performance.
- **Thread Safety**: Mutex locks are used for thread-safe operations on the linked list and memory pool.
- **Linked List Operations**: Supports insertion and deletion at both head and tail.
- **Scalability**: Designed to handle up to 10,000 records efficiently.

This code provides a scalable solution with an emphasis on performance and resource management.']

