        exit(EXIT_FAILURE);
    }
}

int dns_query(const char *domain) {
    pthread_mutex_lock(&dns_rate_limiter.lock);
    time_t now = time(NULL);
    if (now - dns_rate_limiter.start_time > 60) {
        dns_rate_limiter.query_count = 0;
        dns_rate_limiter.start_time = now;
    }

    if (dns_rate_limiter.query_count >= MAX_DNS_QUERIES_PER_MINUTE) {
        pthread_mutex_unlock(&dns_rate_limiter.lock);
        return -1; // Rate limit exceeded
