    if (device) {
        strncpy(device->status_message, new_status, sizeof(device->status_message) - 1);
        device->timestamp = time(NULL);
    }
    pthread_mutex_unlock(&network.lock);
}

void process_device_identifiers() {
    char identifier[32];
    while (scanf("%31s", identifier) == 1) {
        pthread_mutex_lock(&network.lock);
        for (int i = 0; i < MAX_DEVICES; ++i) {
            if (strcmp(network.devices[i].status_message, "") == 0 && strcmp(identifier, network.devices[i].identifier) == 0) {
                update_device_status(&network.devices[i], "Active");
                break;
            }
        }
        pthread_mutex_unlock(&network.lock);
    }
}

int main() {
    initialize_memory_pool();
    initialize_network();

    // Example usage
    dns_query("example.com");

    process_device_identifiers();

    free(memory_pool.pool);
    return 0;
}
