        offsets[i] = i;
    }
}

// Function to initialize keys array with a prime sum
void init_keys(int *keys, int num_keys) {
    bool valid_configuration = false;
    do {
        for (int i = 0; i < num_keys; ++i) {
            keys[i] = rand() % MAX_KEYS;
        }
        int sum = 0;
        for (int i = 0; i < num_keys; ++i) {
            sum += keys[i];
        }
        valid_configuration = is_prime(sum);
    } while (!valid_configuration);
}

// Function to initialize records array
void init_records(Record *records, long *offsets, int *keys, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        records[i].offset_ptr = &offsets[i];
        records[i].key = keys[i];
    }
}

// Function to serialize the records array
void serialize_records(Record *records, int num_records, unsigned char **serialized_data, size_t *size) {
    *size = num_records * sizeof(Record);
    *serialized_data = malloc(*size);
    if (*serialized_data == NULL) {
        fprintf(stderr, "Serialization error: Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(*serialized_data, records, *size);
}

// Function to free allocated memory
void free_memory(long *offsets, int *keys, Record *records, unsigned char *serialized_data) {
    free(offsets);
    free(keys);
    free(records);
    free(serialized_data);
}

// Unit test function
void run_tests() {
    srand(time(NULL));

    // Test case: basic functionality
    int num_offsets = 100;
    long *offsets = malloc(num_offsets * sizeof(long));
    init_offsets(offsets, num_offsets);

    int num_keys = 50;
    int *keys = malloc(num_keys * sizeof(int));
    init_keys(keys, num_keys);

    Record *records = malloc(num_keys * sizeof(Record));
    init_records(records, offsets, keys, num_keys);

    unsigned char *serialized_data = NULL;
    size_t serialized_size;
    serialize_records(records, num_keys, &serialized_data, &serialized_size);

    // Perform integrity check
    for (int i = 0; i < num_keys; ++i) {
        if (records[i].offset_ptr != &offsets[i] || records[i].key != keys[i]) {
            fprintf(stderr, "Integrity error at index %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    printf("All tests passed.\n");

    // Free memory
    free_memory(offsets, keys, records, serialized_data);
}

int main() {
    run_tests();
    return 0;
}
