```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    SUCCESS,
    ERROR_MEMORY_ALLOCATION_FAILED,
    ERROR_KEYS_INITIALIZATION_FAILED,
    ERROR_RECORDS_INITIALIZATION_FAILED,
    ERROR_BOUNDS_CHECK_FAILURE
} StatusCode;

typedef struct {
    int *value;
    size_t idx;
} record;

typedef struct CacheEntry {
    void *memory;
    size_t size;
    struct CacheEntry *next;
    struct CacheEntry *prev;
} CacheEntry;

typedef struct {
    CacheEntry *head;
    CacheEntry *tail;
    size_t capacity;
    pthread_mutex_t lock;
} LRUCache;

LRUCache cache = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void log_error(const char *operation, size_t requested_size, void *allocated_memory) {
    fprintf(stderr, "Error: %s failed for size %zu. Allocated memory: %p\n", operation, requested_size, allocated_memory);
}

CacheEntry* create_cache_entry(void *memory, size_t size) {
    CacheEntry *entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    if (!entry) return NULL;
    entry->memory = memory;
    entry->size = size;
    entry->next = NULL;
    entry->prev = NULL;
    return entry;
}

void cache_add(LRUCache *cache, CacheEntry *entry) {
    pthread_mutex_lock(&cache->lock);
    if (cache->capacity == 0 || cache->head == NULL) {
        cache->head = entry;
        cache->tail = entry;
    } else {
        entry->next = cache->head;
        cache->head->prev = entry;
        cache->head = entry;
    }
    pthread_mutex_unlock(&cache->lock);
}

void cache_evict(LRUCache *cache) {
    pthread_mutex_lock(&cache->lock);
    if (cache->tail != NULL) {
        CacheEntry *to_free = cache->tail;
        if (cache->tail->prev != NULL)
            cache->tail = cache->tail->prev;
        else
            cache->head = NULL;

        if (cache->tail != NULL)
            cache->tail->next = NULL;

        pthread_mutex_unlock(&cache->lock);
        free(to_free->memory);
        free(to_free);
    } else {
        pthread_mutex_unlock(&cache->lock);
    }
}

void* allocate_from_cache(LRUCache *cache, size_t size) {
    pthread_mutex_lock(&cache->lock);
    CacheEntry *entry = cache->head;
    while (entry != NULL && entry->size != size) {
        entry = entry->next;
    }

    if (entry != NULL) {
        if (cache->capacity > 0) {
            // Move accessed entry to head
            if (entry == cache->head)
                cache->tail = entry->prev;

            if (entry->prev != NULL)
                entry->prev->next = entry->next;

            if (entry->next != NULL)
                entry->next->prev = entry->prev;

            entry->next = cache->head;
            entry->prev = NULL;
            cache->head->prev = entry;
            cache->head = entry;
        }

        pthread_mutex_unlock(&cache->lock);
        return entry->memory;
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

StatusCode allocate_records(size_t max_offsets, size_t max_keys, size_t max_records, int check_bounds) {
    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    // Allocate offsets
    offsets = (long *)malloc(max_offsets * sizeof(long));
    if (!offsets) {
        log_error("Allocate offsets", max_offsets * sizeof(long), NULL);
        return ERROR_MEMORY_ALLOCATION_FAILED;
    }
    memset(offsets, 0, max_offsets * sizeof(long));

    // Allocate keys
    keys = (int *)malloc(max_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        log_error("Allocate keys", max_keys * sizeof(int), NULL);
        return ERROR_KEYS_INITIALIZATION_FAILED;
    }

    for (size_t i = 0; i < max_keys; ++i) {
        if (check_bounds && i >= max_keys) break;
        keys[i] = (int)i;
    }

    // Allocate records
    records = (record *)malloc(max_records * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        log_error("Allocate records", max_records * sizeof(record), NULL);
        return ERROR_RECORDS_INITIALIZATION_FAILED;
    }

    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < max_records; ++i) {
        if (check_bounds && i >= max_records) break;
        records[i].value = &keys[rand() % max_keys];  // Random key reference
        records[i].idx = (size_t)(rand() % 1001);      // Random value between 0 and 1000
    }

    // Cache the allocated memory for potential reuse
    pthread_mutex_lock(&cache.lock);
    if (cache.capacity == 0) {
        cache.head = create_cache_entry(offsets, max_offsets * sizeof(long));
        if (!cache.head) {
            free(keys);
            free(records);
            free(offsets);
            log_error("Cache add offsets", max_offsets * sizeof(long), NULL);
            pthread_mutex_unlock(&cache.lock);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }
        cache.tail = cache.head;

        CacheEntry *key_entry = create_cache_entry(keys, max_keys * sizeof(int));
        if (!key_entry) {
            free(records);
            free(offsets);
            log_error("Cache add keys", max_keys * sizeof(int), NULL);
            pthread_mutex_unlock(&cache.lock);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }
        cache.head->next = key_entry;
        key_entry->prev = cache.head;
        cache.tail = key_entry;

        CacheEntry *record_entry = create_cache_entry(records, max_records * sizeof(record));
        if (!record_entry) {
            free(keys);
            free(offsets);
            log_error("Cache add records", max_records * sizeof(record), NULL);
            pthread_mutex_unlock(&cache.lock);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }
        key_entry->next = record_entry;
        record_entry->prev = key_entry;
    } else {
        cache_evict(&cache);  // Evict least recently used if capacity is exceeded
        CacheEntry *offsets_cache = create_cache_entry(offsets, max_offsets * sizeof(long));
        if (!offsets_cache) {
            free(keys);
            free(records);
            free(offsets);
            log_error("Cache add offsets", max_offsets * sizeof(long), NULL);
            pthread_mutex_unlock(&cache.lock);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }
        cache_add(&cache, offsets_cache);

        CacheEntry *keys_cache = create_cache_entry(keys, max_keys * sizeof(int));
        if (!keys_cache) {
            free(records);
            free(offsets);
            log_error("Cache add keys", max_keys * sizeof(int), NULL);
            pthread_mutex_unlock(&cache.lock);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }
        cache_add(&cache, keys_cache);

        CacheEntry *records_cache = create_cache_entry(records, max_records * sizeof(record));
        if (!records_cache) {
            free(keys);
            free(offsets);
            log_error("Cache add records", max_records * sizeof(record), NULL);
            pthread_mutex_unlock(&cache.lock);
            return ERROR_MEMORY_ALLOCATION_FAILED;
        }
        cache_add(&cache, records_cache);
    }
    pthread_mutex_unlock(&cache.lock);

    // Successfully allocated and initialized resources
    return SUCCESS;
}
