['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    float value;
    bool active;
} StructElement;

typedef struct HashNode {
    double identifier;
    StructElement data;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

double hash_function(double identifier) {
    return identifier * 2654435761; // A simple hash function (FNV-1a-like)
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(initial_capacity, sizeof(HashNode*));
    table->capacity = initial_capacity;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void resize_hash_table(HashTable* table);

void insert_hash_table(HashTable* table, double identifier, StructElement data) {
    pthread_mutex_lock(&table->lock);

    if ((double)table->count / table->capacity >= LOAD_FACTOR) {
        resize_hash_table(table);
    }

    size_t index = (size_t)(hash_function(identifier) % table->capacity);
    HashNode* node = malloc(sizeof(HashNode));
    node->identifier = identifier;
    node->data = data;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    table->count++;
    pthread_mutex_unlock(&table->lock);
}

void resize_hash_table(HashTable* table) {
    size_t new_capacity = table->capacity * 2;
    HashNode** new_buckets = calloc(new_capacity, sizeof(HashNode*));

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            size_t index = (size_t)(hash_function(node->identifier) % new_capacity);
            HashNode* next_node = node->next;
            node->next = new_buckets[index];
            new_buckets[index] = node;
            node = next_node;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* next_node = node->next;
            free(node);
            node = next_node;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void log_operation(const char* message) {
    // Simple logging function
    printf("%s\n", message);
}

int persist_data(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return -1;

    for (size_t i = 0; i < table->capacity; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            fprintf(file, "%f,%f,%d\n", node->identifier, node->data.value, node->data.active);
            node = node->next;
        }
    }

    fclose(file);
    return 0;
}

void process_data(size_t num_elements) {
    double* doubles = malloc(num_elements * sizeof(double));
    char* status = calloc(num_elements, sizeof(char));
    StructElement* structs = malloc(num_elements * sizeof(StructElement));

    if (!doubles || !status || !structs) {
        log_operation("Memory allocation failed");
        return;
    }

    HashTable* table = create_hash_table(INITIAL_CAPACITY);
    for (size_t i = 0; i < num_elements; ++i) {
        doubles[i] = rand() / (double)RAND_MAX * 100.0; // Random double
        status[i] = 'A'; // Example status
        structs[i].value = (float)doubles[i];
        structs[i].active = true;

        insert_hash_table(table, doubles[i], structs[i]);
    }

    if (persist_data(table, "data.txt") != 0) {
        log_operation("Persistence failed");
    } else {
        log_operation("Data persisted successfully");
    }

    free(doubles);
    free(status);
    free(structs);
    free_hash_table(table);
}

int main() {
    process_data(1000); // Example usage
    return 0;
}
