['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MEMORY_POOL_SIZE 1024 // Adjust based on capacity needed
#define KEY_RANGE 1000
#define OFFSET_RANGE 500000

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock; // Use a mutex for simplicity, could consider finer granularity or lock-free strategies
} MemoryPool;

MemoryPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void init_random() {
    srand(time(NULL));
}

Record create_record() {
    Record rec;
    rec.key = rand() % KEY_RANGE;
    rec.offset = (long)rand() % OFFSET_RANGE;
    return rec;
}

int allocate_and_initialize_records(MemoryPool* pool, size_t num_records) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count + num_records > MEMORY_POOL_SIZE) {
        printf("Memory pool capacity exceeded.\n");
        pthread_mutex_unlock(&pool->lock);
        return -1; // Memory usage cap exceeded
    }

    for (size_t i = 0; i < num_records; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }

        new_node->record = create_record();
        new_node->next = pool->head;
        pool->head = new_node;
        pool->count++;
    }

    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

void cleanup_memory_pool(MemoryPool* pool) {
    Node* current = pool->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pool->count = 0;

    pthread_mutex_destroy(&pool->lock);
}

int main() {
    init_random();

    if (allocate_and_initialize_records(&pool, 100) == 0) {
        printf("Records allocated and initialized successfully.\n");
    }

    cleanup_memory_pool(&pool);

    return 0;
}
```

This implementation demonstrates a basic thread-safe memory pool for storing records with integer keys and long offset values. It uses a simple mutex lock to ensure that operations on the memory pool are atomic, preventing race conditions when accessed by multiple threads concurrently.

The function `allocate_and_initialize_records` attempts to allocate and initialize the requested number of records within a predefined memory usage cap. If successful, it returns 0; otherwise, it handles errors such as exceeding the memory pool's capacity or failing to allocate memory for new nodes.

Finally, `cleanup_memory_pool` properly frees all allocated resources associated with the memory pool and destroys the mutex lock to prevent memory leaks and ensure deterministic behavior upon termination of the program.']

