    // Assume all positive keys are valid for this example
    return key > 0;
}

int initialize_records(int *keys, long *offsets, struct record *records, int record_count, size_t max_memory) {
    if (record_count <= 0 || keys == NULL || offsets == NULL || records == NULL || max_memory == 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 0;
    }

    srand(time(NULL)); // Seed the random number generator

    size_t record_size = sizeof(struct record);
    size_t current_memory_usage = 0;
    int success_count = 0;

    for (int i = 0; i < record_count && current_memory_usage <= max_memory; ++i) {
        if (keys[i] < 0 || offsets[i] < 0 || i >= record_count) {
            fprintf(stderr, "Out of bounds access detected.\n");
            continue;
        }

        if (!validate_key(keys[i])) {
            fprintf(stderr, "Invalid key: %d\n", keys[i]);
            continue;
        }

        // Calculate required memory for one more record
        size_t new_memory_usage = current_memory_usage + record_size;
        if (new_memory_usage > max_memory) {
            fprintf(stderr, "Memory limit exceeded.\n");
            break;
        }

        records[success_count].value = rand() % 100; // Random value between 0 and 99
        records[success_count].is_active = (rand() % 2 == 0); // 50% probability of being active
        records[success_count].timestamp = time(NULL);

        current_memory_usage += record_size;
        success_count++;
    }

    printf("Records initialized: %d\n", success_count);
    printf("Memory usage: %zu bytes\n", current_memory_usage);

    return success_count;
}

int main() {
