    long offsets[] = {0, 10, 20, 30, 40};
    struct record records[10];
    size_t max_memory = sizeof(records);

    int initialized_count = initialize_records(keys, offsets, records, 5, max_memory);

    for (int i = 0; i < initialized_count; ++i) {
        printf("Record %d: Value=%d, Active=%d, Timestamp=%ld\n", 
               i, records[i].value, records[i].is_active, records[i].timestamp);
    }

    return 0;
}
