// Custom memory pool structure for managing allocations
typedef struct {
    unsigned char *pool;
    size_t total_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool global_memory_pool = {NULL, MEMORY_LIMIT_PER_SECOND, 0, PTHREAD_MUTEX_INITIALIZER};

void init_global_memory_pool() {
    pthread_mutex_lock(&global_memory_pool.lock);
    if (!global_memory_pool.pool) {
        global_memory_pool.pool = (unsigned char *)malloc(global_memory_pool.total_size);
        memset(global_memory_pool.pool, 0, global_memory_pool.total_size);
    }
    pthread_mutex_unlock(&global_memory_pool.lock);
}

void *allocate_from_pool(size_t size) {
    if (size > global_memory_pool.total_size - global_memory_pool.used_size)
        return NULL;

    void *allocated = NULL;
    pthread_mutex_lock(&global_memory_pool.lock);
    allocated = &global_memory_pool.pool[global_memory_pool.used_size];
    global_memory_pool.used_size += size;
    pthread_mutex_unlock(&global_memory_pool.lock);

    return allocated;
}

void release_global_memory_pool() {
    pthread_mutex_lock(&global_memory_pool.lock);
    free(global_memory_pool.pool);
    global_memory_pool.pool = NULL;
    global_memory_pool.used_size = 0;
    pthread_mutex_unlock(&global_memory_pool.lock);
}

typedef struct {
