} TrafficSignal;

void process_traffic_data(const char *vehicle_ids[], int vehicle_count) {
    VehicleNode *nodes = (VehicleNode *)allocate_from_pool(vehicle_count * sizeof(VehicleNode));
    if (!nodes)
        return; // handle allocation failure

    for (int i = 0; i < vehicle_count; ++i) {
