            device->timestamp = time(NULL);
            snprintf(device->status_message, sizeof(device->status_message), "Initialized");
            device->sensor = sensor;
        }
    }

    // Traffic signal optimization logic
    TrafficSignal signals[100]; // Assuming a fixed number of signals for simplicity
    for (int i = 0; i < 100; ++i) {
