    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <vehicle_ids...>\n", argv[0]);
        return EXIT_FAILURE;
    }

    init_global_memory_pool();

    // Process the traffic data based on vehicle identifiers provided
    process_traffic_data(argv + 1, argc - 1);

    release_global_memory_pool();
    return EXIT_SUCCESS;
}
