typedef enum {
    SUCCESS,
    ERROR_ALLOC_FAILURE,
    ERROR_BOUNDS_CHECK_FAILED,
    ERROR_DUPLICATE_KEY,
    ERROR_INVALID_RANGE
} ErrorCode;

typedef struct {
    int *value;
    int idx;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *operation, size_t requested_size) {
    fprintf(stderr, "Error during %s: Failed to allocate %zu bytes\n", operation, requested_size);
}

bool check_bounds(size_t size, size_t max_size, bool check_bounds_enabled) {
    if (check_bounds_enabled && size > max_size) {
        log_error("Bounds Check", size);
        return false;
    }
    return true;
}

ErrorCode manage_resources(int max_offsets, int max_keys, int max_records, 
                           int initial_capacity, double growth_factor, bool check_bounds_flag) {

    pthread_mutex_lock(&lock);

    long *offsets = malloc(max_offsets * sizeof(long));
    if (!offsets) {
        log_error("Offsets Allocation", max_offsets * sizeof(long));
        pthread_mutex_unlock(&lock);
        return ERROR_ALLOC_FAILURE;
    }

    int current_capacity = initial_capacity;
    int *keys = malloc(current_capacity * sizeof(int));
    if (!keys) {
        free(offsets);
        log_error("Keys Initial Allocation", current_capacity * sizeof(int));
        pthread_mutex_unlock(&lock);
        return ERROR_ALLOC_FAILURE;
    }

    for (int i = 0; i < current_capacity; ++i) {
        keys[i] = -1; // Initialize with an invalid value
    }

    int num_keys = 0;
    bool product_in_range = true;
    long product = 1;

    Record *records = malloc(max_records * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        log_error("Records Allocation", max_records * sizeof(Record));
        pthread_mutex_unlock(&lock);
        return ERROR_ALLOC_FAILURE;
    }

    for (int i = 0; i < max_records; ++i) {
        records[i].value = malloc(sizeof(int));
        if (!records[i].value) {
            for (int j = 0; j < i; ++j) {
                free(records[j].value);
            }
            free(records);
            free(keys);
            free(offsets);
            log_error("Record Value Allocation", sizeof(int));
            pthread_mutex_unlock(&lock);
            return ERROR_ALLOC_FAILURE;
        }

        records[i].idx = rand() % num_keys;
        if (records[i].idx >= num_keys) {
            free(records[i].value);
            for (int j = 0; j < i; ++j) {
                free(records[j].value);
            }
            free(records);
            free(keys);
            free(offsets);
            log_error("Invalid Record Index", 0);
            pthread_mutex_unlock(&lock);
            return ERROR_BOUNDS_CHECK_FAILED;
        }

        *records[i].value = rand() % 1001; // Random integer between 0 and 1000
    }

    for (int i = 0; i < num_keys && product_in_range; ++i) {
        if (!check_bounds(keys[i] * product, INT_MAX, check_bounds_flag)) {
            product_in_range = false;
        }
        product *= keys[i];
    }

    pthread_mutex_unlock(&lock);

    return SUCCESS;
}

int main() {
    ErrorCode status = manage_resources(MAX_OFFSETS, MAX_KEYS, MAX_RECORDS, INITIAL_CAPACITY, GROWTH_FACTOR, true);
    if (status != SUCCESS) {
        printf("Resource management failed with error code: %d\n", status);
    } else {
        printf("Resource management succeeded.\n");
    }
    return 0;
}
