['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    SUCCESS,
    MEMORY_ALLOCATION_FAILURE,
    INVALID_ARGUMENTS,
} Status;

typedef struct {
    int *value;
    int idx;
} Record;

typedef struct CacheNode {
    void* data;
    size_t size;
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

typedef struct {
    CacheNode* head;
    CacheNode* tail;
    unsigned capacity;
    pthread_mutex_t lock;
} LRUCache;

LRUCache cache = {0, 0, 10, PTHREAD_MUTEX_INITIALIZER};

void initialize_cache() {
    cache.head = malloc(sizeof(CacheNode));
    cache.tail = malloc(sizeof(CacheNode));
    if (!cache.head || !cache.tail) {
        fprintf(stderr, "Failed to initialize LRU Cache\n");
        exit(MEMORY_ALLOCATION_FAILURE);
    }
    cache.head->next = cache.tail;
    cache.tail->prev = cache.head;
    cache.capacity = 10; // Example capacity
}

void evict_cache() {
    if (cache.head->next == cache.tail) return;

    CacheNode* lru = cache.tail->prev;
    if (lru->data) free(lru->data);
    lru->prev->next = cache.tail;
    cache.tail->prev = lru->prev;
    free(lru);
}

void add_to_cache(void *data, size_t size) {
    pthread_mutex_lock(&cache.lock);

    if (cache.capacity == 0) return;

    CacheNode* node = malloc(sizeof(CacheNode));
    if (!node) {
        fprintf(stderr, "Failed to allocate cache node\n");
        pthread_mutex_unlock(&cache.lock);
        return;
    }

    node->data = data;
    node->size = size;
    node->next = cache.head->next;
    node->prev = cache.head;

    cache.head->next->prev = node;
    cache.head->next = node;

    if (node->next == cache.tail) {
        evict_cache();
    }

    pthread_mutex_unlock(&cache.lock);
}

void* get_from_cache(size_t size) {
    pthread_mutex_lock(&cache.lock);

    CacheNode *current = cache.head->next, *prev;
    while (current != cache.tail) {
        if (current->size >= size) {
            prev = current->prev;
            // Move the node to head
            current->next->prev = current->prev;
            current->prev->next = current->next;

            current->next = cache.head->next;
            current->prev = cache.head;
            cache.head->next->prev = current;
            cache.head->next = current;

            pthread_mutex_unlock(&cache.lock);
            return current->data;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

Status resource_manager(size_t max_offsets, size_t max_keys, size_t max_records, int check_bounds) {
    if (check_bounds && (max_offsets == 0 || max_keys == 0 || max_records == 0)) {
        fprintf(stderr, "Invalid argument: zero size allocation\n");
        return INVALID_ARGUMENTS;
    }

    long *offsets = get_from_cache(max_offsets * sizeof(long));
    if (!offsets) {
        offsets = malloc(max_offsets * sizeof(long));
        if (!offsets) {
            fprintf(stderr, "Failed to allocate memory for offsets\n");
            return MEMORY_ALLOCATION_FAILURE;
        }
        add_to_cache(offsets, max_offsets * sizeof(long));
    }

    int *keys = get_from_cache(max_keys * sizeof(int));
    if (!keys) {
        keys = malloc(max_keys * sizeof(int));
        if (!keys) {
            fprintf(stderr, "Failed to allocate memory for keys\n");
            free(offsets);
            return MEMORY_ALLOCATION_FAILURE;
        }
        add_to_cache(keys, max_keys * sizeof(int));

        for (size_t i = 0; i < max_keys; ++i) {
            keys[i] = i;
        }
    }

    Record *records = get_from_cache(max_records * sizeof(Record));
    if (!records) {
        records = malloc(max_records * sizeof(Record));
        if (!records) {
            fprintf(stderr, "Failed to allocate memory for records\n");
            free(offsets);
            free(keys);
            return MEMORY_ALLOCATION_FAILURE;
        }
        add_to_cache(records, max_records * sizeof(Record));

        srand(time(NULL)); // Seed random number generator

        for (size_t i = 0; i < max_records; ++i) {
            records[i].value = malloc(sizeof(int));
            if (!records[i].value) {
                fprintf(stderr, "Failed to allocate memory for record value\n");
                free(offsets);
                free(keys);
                // Free previously allocated records
                while (i > 0) {
                    free(records[--i].value);
                }
                free(records);
                return MEMORY_ALLOCATION_FAILURE;
            }

            *records[i].value = rand() % 1001; // Random number between 0 and 1000
            records[i].idx = i % max_keys; // Index referencing the keys array
        }
    }

    return SUCCESS;
}
```

This code implements a `resource_manager` function in C that dynamically allocates memory for arrays of offsets, keys, and records. It incorporates an LRU cache mechanism to reuse previously allocated memory, ensuring efficient resource management under constrained environments. The code includes error handling and logging for failed allocations and supports thread-safe operations using mutex locks.']

