#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>
#include <openssl/sha.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    size_t offset_count;
    int* keys;
    size_t key_count;
    record** records;
    size_t record_count;
    pthread_mutex_t lock;
} MemoryPool;

#define HASH_SIZE 32

typedef struct {
    unsigned char hash[HASH_SIZE];
} sha256_hash;

// Utility function to generate a random integer within a specified range
int getRandomInt(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function prototypes
MemoryPool* createMemoryPool(size_t initial_capacity);
void freeMemoryPool(MemoryPool* pool);
record* allocateRecord(MemoryPool* pool);
void freeRecord(record* rec);
sha256_hash computeSHA256Hash(const record* rec);
void logToExternalService(const char* message);

void* processAndTransformRecords(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;

    // Allocate initial capacity
    pool->offsets = malloc(sizeof(long) * 10);  // Initial capacity for offsets
    pool->keys = malloc(sizeof(int) * 10);
    pool->records = malloc(sizeof(record*) * 10);
    if (!pool->offsets || !pool->keys || !pool->records) {
        logToExternalService("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Initialize mutex
    pthread_mutex_init(&pool->lock, NULL);

    size_t latest_key = 0;
    record* latest_record = NULL;

    while (1) {  // Read records from standard input indefinitely
        long offset;
        int key;

        if (scanf("%ld %d", &offset, &key) != 2) break;  // Break on EOF or error

        pthread_mutex_lock(&pool->lock);

        // Resize arrays if necessary
        if (pool->record_count == pool->offset_count) {
            size_t new_capacity = pool->offset_count * 2;
            pool->offsets = realloc(pool->offsets, sizeof(long) * new_capacity);
            pool->keys = realloc(pool->keys, sizeof(int) * new_capacity);
            pool->records = realloc(pool->records, sizeof(record*) * new_capacity);

            if (!pool->offsets || !pool->keys || !pool->records) {
                logToExternalService("Memory reallocation failed");
                pthread_mutex_unlock(&pool->lock);
                exit(EXIT_FAILURE);
            }
        }

        // Allocate and initialize a new record
        record* rec = allocateRecord(pool);
        rec->value = getRandomInt(1, 100);  // Random value between 1 and 100

        pool->offsets[pool->record_count] = offset;
        pool->keys[pool->key_count++] = key;
        pool->records[pool->record_count++] = rec;

        if (key > latest_key) {
            latest_key = key;
            latest_record = rec;
        }

        pthread_mutex_unlock(&pool->lock);
    }

    // Compute SHA-256 hashes asynchronously
    sha256_hash* hash_array = malloc(sizeof(sha256_hash) * pool->record_count);
    if (!hash_array) {
        logToExternalService("Hash array allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_t* threads = malloc(sizeof(pthread_t) * pool->record_count);
    if (!threads) {
        logToExternalService("Thread creation allocation failed");
        free(hash_array);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < pool->record_count; ++i) {
        pthread_create(&threads[i], NULL, (void*(*)(void*))computeSHA256Hash, pool->records[i]);
    }

    for (size_t i = 0; i < pool->record_count; ++i) {
        void* result;
        pthread_join(threads[i], &result);
        hash_array[i] = *(sha256_hash*)result;
        free(result); // Free the temporary buffer allocated in computeSHA256Hash
    }

    // Print latest record key and value
    if (latest_record) {
        printf("Latest Record - Key: %d, Value: %d\n", latest_key, latest_record->value);
    }

    // Example log of hashes (could be logged to external service)
    for (size_t i = 0; i < pool->record_count; ++i) {
        char hash_str[HASH_SIZE * 2 + 1];
        for (int j = 0; j < HASH_SIZE; ++j) {
            sprintf(hash_str + (j * 2), "%02x", hash_array[i].hash[j]);
        }
        logToExternalService(hash_str);
    }

    free(threads);
    free(hash_array);

    // Clean up
    pthread_mutex_destroy(&pool->lock);
    for (size_t i = 0; i < pool->record_count; ++i) {
        freeRecord(pool->records[i]);
    }
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    return NULL;
}

MemoryPool* createMemoryPool(size_t initial_capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) exit(EXIT_FAILURE);
    memset(pool, 0, sizeof(MemoryPool));
    pool->offset_count = initial_capacity;
    pool->key_count = initial_capacity;
    return pool;
}

void freeMemoryPool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->record_count; ++i) {
        freeRecord(pool->records[i]);
    }
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

record* allocateRecord(MemoryPool* pool) {
    record* rec = malloc(sizeof(record));
    if (!rec) exit(EXIT_FAILURE);
    return rec;
}

void freeRecord(record* rec) {
    free(rec);
}

sha256_hash computeSHA256Hash(const record* rec) {
    unsigned char hash[HASH_SIZE];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, &rec->value, sizeof(rec->value));
    SHA256_Final(hash, &sha256);

    sha256_hash result;
    memcpy(result.hash, hash, HASH_SIZE);

    unsigned char* buffer = malloc(HASH_SIZE);
    if (!buffer) exit(EXIT_FAILURE);
    memcpy(buffer, result.hash, HASH_SIZE);
    return (sha256_hash){.hash = *buffer};
}

void logToExternalService(const char* message) {
    // Simulated logging function
    printf("Log: %s\n", message);
}
