// Function to dynamically allocate and initialize records
int initialize_records(Record*** records, size_t record_count, int* keys, long* offsets, 
                       size_t max_memory, void* data_source, int** skipped_keys) {
    if (!records || !keys || !offsets || !data_source) return 0;

    *records = NULL;
    size_t total_size = 0;
    int initialized_count = 0;
    int* temp_skipped_keys = NULL;
    int skipped_count = 0;

    // Calculate max records that can fit in memory
    size_t record_struct_size = sizeof(Record);
    size_t potential_records = max_memory / record_struct_size;

    if (potential_records < record_count) {
        printf("Reducing record count due to memory constraints.\n");
        record_count = potential_records;
    }

    *records = malloc(record_count * sizeof(Record*));
    if (!*records) return 0; // Memory allocation failed

    for (size_t i = 0; i < record_count && total_size <= max_memory; ++i) {
        if (keys[i] >= 0 && offsets[i] >= 0 && is_valid_key(keys[i], data_source)) {
            (*records)[i] = malloc(record_struct_size);
            if (!(*records)[i]) break;

            // Initialize record fields
            srand(time(NULL) ^ i); // Seed for randomness
            (*records)[i]->value = rand() % 100;  // Random number between 0 and 99
            (*records)[i]->active = (rand() % 2 == 0);
            (*records)[i]->timestamp = time(NULL);
            (*records)[i]->reference_count = 0;

            total_size += record_struct_size;
            initialized_count++;
        } else {
            // Log skipped key and allocate space for it
            temp_skipped_keys = realloc(temp_skipped_keys, (skipped_count + 1) * sizeof(int));
            if (!temp_skipped_keys) break; // Memory allocation failed

            temp_skipped_keys[skipped_count++] = keys[i];
        }
    }

    // Handle memory failures and resize records array
    if (total_size > max_memory || initialized_count < record_count) {
        for (size_t i = 0; i < initialized_count; ++i) {
            free((*records)[i]);
        }
        free(*records);
        *records = NULL;
        initialized_count = 0;
    }

    // Set skipped keys list
    *skipped_keys = temp_skipped_keys;

    return initialized_count;  // Return the number of successfully initialized records
}

// Example usage
int main() {
    Record** records;
    int keys[] = {1, 2, 3, 4, 5};
    long offsets[] = {0, 10, 20, 30, 40};
    size_t max_memory = 1024; // Adjust as needed

    int skipped_keys[100];
    int initialized_count = initialize_records(&records, 5, keys, offsets, max_memory, NULL, &skipped_keys);

    printf("Initialized %d records.\n", initialized_count);
    if (skipped_keys) {
        printf("Skipped keys: ");
        for (int i = 0; skipped_keys[i] != -1; ++i) {
            printf("%d ", skipped_keys[i]);
        }
        printf("\n");
    }

    // Cleanup
    if (records) {
        for (int i = 0; i < initialized_count; ++i) {
            free(records[i]);
        }
        free(records);
    }

    return 0;
}
