#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

// Memory pool structure for managing memory allocation efficiently
typedef struct {
    size_t block_size;
    void *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} memory_pool;

void init_memory_pool(memory_pool *mp, size_t block_size, size_t num_blocks) {
    mp->block_size = block_size;
    mp->pool_size = block_size * num_blocks;
    mp->pool = malloc(mp->pool_size);
    if (!mp->pool) {
        perror("Failed to allocate memory pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&mp->lock, NULL);
}

void* allocate_memory_pool(memory_pool *mp) {
    pthread_mutex_lock(&mp->lock);
    void *block = malloc(mp->block_size);
    if (!block) {
        perror("Failed to allocate memory from pool");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&mp->lock);
    return block;
}

void free_memory_pool(memory_pool *mp) {
    pthread_mutex_lock(&mp->lock);
    free(mp->pool);
    pthread_mutex_unlock(&mp->lock);
    pthread_mutex_destroy(&mp->lock);
}

// Helper function to get hostname IP address
char* resolve_hostname(const char* hostname, memory_pool *mp) {
    struct addrinfo hints, *res;
    char ip_str[INET6_ADDRSTRLEN];
    char *result;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Support IPv4 only

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        perror("Failed to resolve hostname");
        return NULL;
    }

    result = allocate_memory_pool(mp);
    inet_ntop(res->ai_family, &(((struct sockaddr_in *)res->ai_addr)->sin_addr), ip_str, sizeof(ip_str));
    strncpy(result, ip_str, INET6_ADDRSTRLEN);

    freeaddrinfo(res);
    return result;
}

// Thread-safe function to find the largest integer in an array
int find_largest_integer(int *arr, size_t length) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int max = arr[0];

    pthread_mutex_lock(&lock);
    for (size_t i = 1; i < length; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    pthread_mutex_unlock(&lock);

    return max;
}

// Thread-safe function to calculate the average of positive floats
double thread_safe_average_positive(float *arr, size_t length) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    double sum = 0.0;
    int count = 0;

    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < length; ++i) {
        if (arr[i] > 0) {
            sum += arr[i];
            count++;
        }
    }
    pthread_mutex_unlock(&lock);

    return count ? sum / count : 0.0;
}

// Geometry struct with random initialization
typedef struct {
    float x, y;
} point;

typedef struct {
    double value;
    char name[16];
    point pt;
} geometry;

void initialize_geometry(geometry *geom) {
    // Initialize with random values
    geom->value = ((double)rand() / RAND_MAX) * 100.0; // Example range 0-100
    for (int i = 0; i < 15; ++i) {
        char rand_char = (rand() % 2 == 0) ? (char)(rand() % 26 + 'A') : (char)(rand() % 10 + '0');
        geom->name[i] = rand_char;
    }
    geom->name[15] = '\0';
    geom->pt.x = ((float)rand() / RAND_MAX) * 100.0; // Example range 0-100
    geom->pt.y = ((float)rand() / RAND_MAX) * 100.0; // Example range 0-100
}

// Main function to demonstrate usage
int main() {
    srand(time(NULL));

    memory_pool mp;
    init_memory_pool(&mp, sizeof(char) * INET6_ADDRSTRLEN, 10);

    char hostname[] = "example.com";
    char *ip_address = resolve_hostname(hostname, &mp);
    if (ip_address) {
        printf("IP Address of %s: %s\n", hostname, ip_address);
        free(ip_address);
    }

    int numbers[] = {1, 5, 3, 9, 2};
    size_t num_length = sizeof(numbers) / sizeof(numbers[0]);
    printf("Largest Integer: %d\n", find_largest_integer(numbers, num_length));

    float floats[] = {1.5f, -2.3f, 4.7f, 3.6f, -1.0f};
    size_t float_length = sizeof(floats) / sizeof(floats[0]);
    printf("Average of Positive Floats: %f\n", thread_safe_average_positive(floats, float_length));

    geometry geom;
    initialize_geometry(&geom);
    printf("Geometry Value: %lf, Name: %s, Point: (%.2f, %.2f)\n",
           geom.value, geom.name, geom.pt.x, geom.pt.y);

    free_memory_pool(&mp);
    return 0;
}
