class MemoryPool {
private:
    struct Block {
        Block* next;
    };

    Block* freeList = nullptr;
    size_t blockSize;
    unsigned char* poolStart;
    size_t poolSize;

public:
    MemoryPool(size_t blockSize, size_t numBlocks)
        : blockSize(blockSize), poolSize(blockSize * numBlocks) {
        poolStart = new unsigned char[poolSize];
        for (size_t i = 0; i < numBlocks; ++i) {
            auto* block = reinterpret_cast<Block*>(poolStart + i * blockSize);
            block->next = freeList;
            freeList = block;
        }
    }

    ~MemoryPool() { delete[] poolStart; }

    void* allocate() {
        if (!freeList) throw std::bad_alloc();
        Block* block = freeList;
        freeList = freeList->next;
        return block;
    }

    void deallocate(void* ptr) {
        auto* block = static_cast<Block*>(ptr);
        block->next = freeList;
        freeList = block;
    }
};

