['Below is an implementation of a C function that dynamically allocates memory for an array of `entry` structures, initializes a hash table, supports insertion and lookup operations, ensures balanced distribution across hash buckets, handles potential memory allocation failures gracefully, and provides error handling and cleanup mechanisms.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *key;
    int value;
} entry;

typedef struct bucket {
    entry **entries;
    size_t size;
    size_t count;
} bucket;

typedef struct {
    bucket **buckets;
    size_t num_buckets;
    pthread_mutex_t lock;
} hashtable;

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash;
}

hashtable* create_hashtable(size_t initial_size) {
    hashtable *ht = malloc(sizeof(hashtable));
    if (!ht) return NULL;

    ht->num_buckets = initial_size;
    ht->buckets = calloc(initial_size, sizeof(bucket *));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        ht->buckets[i] = malloc(sizeof(bucket));
        if (!ht->buckets[i]) {
            for (size_t j = 0; j <= i; ++j) free(ht->buckets[j]);
            free(ht->buckets);
            free(ht);
            return NULL;
        }
        ht->buckets[i]->entries = NULL;
        ht->buckets[i]->size = 0;
        ht->buckets[i]->count = 0;
    }

    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

void resize_hashtable(hashtable *ht) {
    size_t new_size = ht->num_buckets * 2;
    bucket **new_buckets = calloc(new_size, sizeof(bucket *));
    if (!new_buckets) return;

    for (size_t i = 0; i < new_size; ++i) {
        new_buckets[i] = malloc(sizeof(bucket));
        if (!new_buckets[i]) {
            for (size_t j = 0; j <= i; ++j) free(new_buckets[j]);
            free(new_buckets);
            return;
        }
        new_buckets[i]->entries = NULL;
        new_buckets[i]->size = 0;
        new_buckets[i]->count = 0;
    }

    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < ht->num_buckets; ++i) {
        bucket *old_bucket = ht->buckets[i];
        size_t old_count = old_bucket->count;

        for (size_t j = 0; j < old_count; ++j) {
            entry *e = old_bucket->entries[j];

            unsigned long new_index = hash(e->key) % new_size;
            bucket *new_bucket = new_buckets[new_index];

            if (++new_bucket->count > new_bucket->size) {
                size_t new_entry_size = (new_bucket->count < 4) ? 4 : new_bucket->count * 2;
                entry **new_entries = realloc(new_bucket->entries, new_entry_size * sizeof(entry *));
                if (!new_entries) return;

                new_bucket->entries = new_entries;
                new_bucket->size = new_entry_size;
            }

            new_bucket->entries[new_bucket->count - 1] = e;
        }
    }

    for (size_t i = 0; i < ht->num_buckets; ++i) {
        free(ht->buckets[i]);
    }
    free(ht->buckets);
    pthread_mutex_unlock(&ht->lock);

    ht->buckets = new_buckets;
    ht->num_buckets = new_size;

    pthread_mutex_unlock(&ht->lock);
}

int insert_entry(hashtable *ht, const char *key, int value) {
    if (!ht || !key) return -1;

    unsigned long index = hash(key) % ht->num_buckets;
    bucket *bucket = ht->buckets[index];

    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < bucket->count; ++i) {
        if (strcmp(bucket->entries[i]->key, key) == 0) {
            bucket->entries[i]->value = value;
            pthread_mutex_unlock(&ht->lock);
            return 0;
        }
    }

    entry *new_entry = malloc(sizeof(entry));
    if (!new_entry) {
        pthread_mutex_unlock(&ht->lock);
        return -1;
    }

    new_entry->key = strdup(key);
    if (!new_entry->key) {
        free(new_entry);
        pthread_mutex_unlock(&ht->lock);
        return -1;
    }
    new_entry->value = value;

    if (bucket->count >= bucket->size) {
        size_t new_size = (bucket->size < 4) ? 4 : bucket->size * 2;
        entry **new_entries = realloc(bucket->entries, new_size * sizeof(entry *));
        if (!new_entries) {
            free(new_entry->key);
            free(new_entry);
            pthread_mutex_unlock(&ht->lock);
            return -1;
        }

        bucket->entries = new_entries;
        bucket->size = new_size;
    }

    bucket->entries[bucket->count++] = new_entry;

    if (bucket->count > ht->num_buckets * 0.75) {
        resize_hashtable(ht);
    }

    pthread_mutex_unlock(&ht->lock);

    return 0;
}

int lookup_entry(hashtable *ht, const char *key, int *value) {
    if (!ht || !key || !value) return -1;

    unsigned long index = hash(key) % ht->num_buckets;
    bucket *bucket = ht->buckets[index];

    pthread_mutex_lock(&ht->lock);

    for (size_t i = 0; i < bucket->count; ++i) {
        if (strcmp(bucket->entries[i]->key, key) == 0) {
            *value = bucket->entries[i]->value;
            pthread_mutex_unlock(&ht->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&ht->lock);

    return -1;
}

void free_hashtable(hashtable *ht) {
    if (!ht) return;

    for (size_t i = 0; i < ht->num_buckets; ++i) {
        bucket *bucket = ht->buckets[i];
        for (size_t j = 0; j < bucket->count; ++j) {
            free(bucket->entries[j]->key);
            free(bucket->entries[j]);
        }
        free(bucket->entries);
        free(bucket);
    }

    free(ht->buckets);

    pthread_mutex_destroy(&ht->lock);
    free(ht);
}
```

This implementation provides a hash table with dynamic resizing, handles memory allocation failures gracefully, and ensures thread safety using mutex locks. It supports insertion and lookup operations efficiently while maintaining balanced distribution across hash buckets.']

