        printf("Metric: %s\n", metrics[i].name);
    }

    free(metrics);
    // Free memory pool and records
    for (size_t i = 0; i < count; ++i) {
        free(pool->records[i]);
    }

    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);

    return 0;
}
