typedef struct state_node {
    int state_id;
    struct state_node* next;
} state_node;

typedef struct {
    state_node* head;
    pthread_mutex_t lock;
} StateListManager;

state_node* createStateNode(int state_id) {
    state_node* node = (state_node*)malloc(sizeof(state_node));
    if (!node) return NULL;
    node->state_id = state_id;
    node->next = NULL;
    return node;
}

void initializeStateList(StateListManager* manager, int num_states, const int* states) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->head = NULL;

    for (int i = 0; i < num_states; ++i) {
        state_node* new_node = createStateNode(states[i]);
        if (!new_node) continue;

        pthread_mutex_lock(&manager->lock);
        new_node->next = manager->head;
        manager->head = new_node;
        pthread_mutex_unlock(&manager->lock);
    }
}

state_node* createSubsetStateList(StateListManager* manager, int last_state_id) {
    state_node* current = manager->head;
    state_node** tail = &current;

    while (current && current->state_id != last_state_id) {
        tail = &(current->next);
        current = current->next;
    }

    if (!current) return NULL;

    *tail = NULL; // Detach the subset list
    return manager->head;
}

void freeStateList(state_node* head) {
    state_node* tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }
}

// Memory pool management, concurrency handling, logging, and other functions would be implemented here
// For brevity, these are not fully fleshed out in this example.

int main() {
    StateListManager manager;
    int states[MAX_STATES] = {0}; // Example state array

    // Simulating input: populate the states array with integers from 1 to MAX_STATES
    for (int i = 0; i < MAX_STATES; ++i) {
        states[i] = i + 1;
    }

    initializeStateList(&manager, MAX_STATES, states);

    int last_state_id = 500; // Example last state ID
    state_node* subset_list = createSubsetStateList(&manager, last_state_id);

    if (subset_list) {
        printf("Created a subset state list ending with state ID: %d\n", last_state_id);
        freeStateList(subset_list);
    } else {
        printf("Failed to create a subset state list.\n");
    }

    pthread_mutex_destroy(&manager.lock);

    return 0;
}
