#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>
#include <time.h>

#define NUM_RECORDS 5
#define RECORD_STR_LEN 50
#define CATEGORY_STR_LEN 20

typedef struct {
    int key;
    char* description;
    double value;
} record;

typedef struct {
    record records[NUM_RECORDS];
    char identifier[CATEGORY_STR_LEN];
} category;

// Custom memory pool structure
typedef struct {
    size_t block_size;
    void* memory_pool;
    pthread_mutex_t lock;
} memory_pool_t;

void log_operation(const char *operation) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), operation);
}

memory_pool_t* create_memory_pool(size_t size, size_t block_count) {
    memory_pool_t* pool = malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pthread_mutex_init(&(pool->lock), NULL);
    pool->block_size = size * block_count;
    pool->memory_pool = malloc(pool->block_size);
    log_operation("Memory pool created");

    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }
    return pool;
}

void* allocate_from_pool(memory_pool_t* pool, size_t size) {
    pthread_mutex_lock(&(pool->lock));
    void* ptr = malloc(size);
    log_operation("Memory allocated");
    pthread_mutex_unlock(&(pool->lock));
    if (!ptr) {
        perror("Allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory_pool(memory_pool_t* pool) {
    pthread_mutex_lock(&(pool->lock));
    free(pool->memory_pool);
    log_operation("Memory pool freed");
    pthread_mutex_unlock(&(pool->lock));
    pthread_mutex_destroy(&(pool->lock));
    free(pool);
}

double compute_average(const int* numbers, size_t count) {
    double sum = 0;
    for (size_t i = 0; i < count; ++i)
        sum += numbers[i];
    return count ? sum / count : 0.0;
}

void process_input(memory_pool_t* pool) {
    printf("Enter number of integers: ");
    size_t num_count;
    scanf("%zu", &num_count);

    int* numbers = (int*)allocate_from_pool(pool, sizeof(int) * num_count);

    for (size_t i = 0; i < num_count; ++i) {
        printf("Enter integer %zu: ", i + 1);
        scanf("%d", &(numbers[i]));
    }

    double average = compute_average(numbers, num_count);
    printf("Average value is: %.2f\n", average);

    free(numbers);
}

void* thread_safe_access(void* arg) {
    category* categories = (category*)arg;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < NUM_RECORDS; ++i) {
        pthread_mutex_lock(&lock);
        printf("Accessing category %d with identifier: %s\n", i, categories[i].identifier);
        // Simulate work
        sleep(1);
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return NULL;
}

void initialize_components(memory_pool_t* pool) {
    double* doubles = (double*)allocate_from_pool(pool, sizeof(double) * NUM_RECORDS);

    char** strings = (char**)allocate_from_pool(pool, sizeof(char*) * NUM_RECORDS);
    for (int i = 0; i < NUM_RECORDS; ++i)
        strings[i] = (char*)allocate_from_pool(pool, RECORD_STR_LEN);

    record* records = (record*)allocate_from_pool(pool, sizeof(record) * NUM_RECORDS);
    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].key = i;
        snprintf(strings[i], RECORD_STR_LEN, "Description %d", i);
        records[i].description = strings[i];
        records[i].value = doubles[i] * 1.5;
    }

    category* categories = (category*)allocate_from_pool(pool, sizeof(category) * NUM_RECORDS);
    for (int i = 0; i < NUM_RECORDS; ++i) {
        memcpy(categories[i].records, &records[i], sizeof(record));
        snprintf(categories[i].identifier, CATEGORY_STR_LEN, "Category %d", i);
    }

    pthread_t threads[NUM_RECORDS];
    for (int i = 0; i < NUM_RECORDS; ++i)
        pthread_create(&threads[i], NULL, thread_safe_access, (void*)&categories);

    for (int i = 0; i < NUM_RECORDS; ++i)
        pthread_join(threads[i], NULL);

    free(doubles);
    for (int i = 0; i < NUM_RECORDS; ++i)
        free(strings[i]);
}

void cleanup_components(memory_pool_t* pool) {
    free_memory_pool(pool);
}

void initialize_and_process() {
    memory_pool_t* pool = create_memory_pool(100, 10);
    if (!pool) return;

    process_input(pool);
    initialize_components(pool);

    cleanup_components(pool);
}

int main() {
    initialize_and_process();
    return 0;
}
