#define THREAD_SAFE_LOCK pthread_mutex_t lock;
#define THREAD_SAFE_INIT pthread_mutex_init(&lock, NULL);
#define THREAD_SAFE_UNLOCK pthread_mutex_unlock(&lock);
#define THREAD_SAFE_LOCKING pthread_mutex_lock(&lock);

typedef struct {
    char *sensor_id;
    double data_value;
    time_t timestamp;
} sensor_data;

typedef struct {
    sensor_data *pool;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock; // For thread safety
} SensorPool;

SensorPool* create_sensor_pool(size_t initial_size) {
    SensorPool *sp = malloc(sizeof(SensorPool));
    if (!sp) return NULL;

    sp->pool = malloc(initial_size * sizeof(sensor_data));
    if (!sp->pool) {
        free(sp);
        return NULL;
    }
    sp->size = 0;
    sp->capacity = initial_size;
    THREAD_SAFE_INIT
    return sp;
}

int add_sensor(SensorPool *sp, const char *sensor_id, double data_value, time_t timestamp) {
    if (sp->size >= MAX_SENSORS || sp->size >= sp->capacity) {
        size_t new_capacity = sp->capacity * 2;
        sensor_data *new_pool = realloc(sp->pool, new_capacity * sizeof(sensor_data));
        if (!new_pool) return -1;
        sp->pool = new_pool;
        sp->capacity = new_capacity;
    }

    THREAD_SAFE_LOCKING
    for (size_t i = 0; i < sp->size; ++i) {
        if (strcmp(sp->pool[i].sensor_id, sensor_id) == 0 && sp->pool[i].timestamp == timestamp) {
            THREAD_SAFE_UNLOCK
            return -1;
        }
    }

    sensor_data *new_sensor = &sp->pool[sp->size++];
    new_sensor->sensor_id = strdup(sensor_id);
    if (!new_sensor->sensor_id) {
        THREAD_SAFE_UNLOCK
        return -1;
    }
    new_sensor->data_value = data_value;
    new_sensor->timestamp = timestamp;

    THREAD_SAFE_UNLOCK
    printf("Sensor added: %s, value: %.2f, time: %ld\n", sensor_id, data_value, (long)timestamp);
    return 0;
}

void free_sensor_pool(SensorPool *sp) {
    if (!sp) return;

    THREAD_SAFE_LOCKING
    for (size_t i = 0; i < sp->size; ++i) {
        free(sp->pool[i].sensor_id);
    }
    free(sp->pool);

    pthread_mutex_destroy(&sp->lock);
    free(sp);
}

char* serialize_sensor_data(sensor_data *data) {
    json_t *root = json_object();
    json_object_set_new(root, "sensor_id", json_string(data->sensor_id));
    json_object_set_new(root, "data_value", json_real(data->data_value));
    json_object_set_new(root, "timestamp", json_integer((int)data->timestamp));

    char *json_dump = json_dumps(root, JSON_ENCODE_ANY);
    json_decref(root);

    return json_dump;
}

sensor_data* deserialize_sensor_data(const char *json_str) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);
    if (!root) return NULL;

    const char *id = json_string_value(json_object_get(root, "sensor_id"));
    double value = json_real_value(json_object_get(root, "data_value"));
    time_t timestamp = (time_t)json_integer_value(json_object_get(root, "timestamp"));

    sensor_data *data = malloc(sizeof(sensor_data));
    if (!data) {
        json_decref(root);
        return NULL;
    }

    data->sensor_id = strdup(id);
    data->data_value = value;
    data->timestamp = timestamp;

    json_decref(root);
    return data;
}

void test_serialization() {
    SensorPool *sp = create_sensor_pool(INITIAL_POOL_SIZE);
    if (!sp) return;

    add_sensor(sp, "sensor_1", 23.45, time(NULL));

    for (size_t i = 0; i < sp->size; ++i) {
        char *json_str = serialize_sensor_data(&sp->pool[i]);
        printf("Serialized: %s\n", json_str);
        free(json_str);

        sensor_data *deserialized = deserialize_sensor_data(json_str);
        if (deserialized) {
            printf("Deserialized: ID=%s, Value=%.2f, Timestamp=%ld\n",
                   deserialized->sensor_id, deserialized->data_value, (long)deserialized->timestamp);
            free(deserialized->sensor_id);
            free(deserialized);
        }
    }

    free_sensor_pool(sp);
}

int main() {
    test_serialization();
    return 0;
}
