#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <math.h>
#include <stdatomic.h>
#include <string.h>

// Define the record structure
typedef struct {
    int value;
} record;

// Mutex-based lock-free stack for managing queue elements
typedef struct StackNode {
    int data;
    struct StackNode* next;
} StackNode;

typedef struct LockFreeStack {
    atomic_uintptr_t top;
} LockFreeStack;

// Initialize the lock-free stack
void initLockFreeStack(LockFreeStack* stack) {
    uintptr_t null_node = (uintptr_t)NULL;
    atomic_store(&stack->top, null_node);
}

// Push an element onto the stack
void push(LockFreeStack* stack, int data) {
    StackNode* new_node = malloc(sizeof(StackNode));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    StackNode* old_top;

    do {
        old_top = (StackNode*)atomic_load(&stack->top);
        new_node->next = old_top;
    } while (!atomic_compare_exchange_weak(
               &stack->top,
               (uintptr_t*)&old_top,
               (uintptr_t)new_node));
}

// Pop an element from the stack
int pop(LockFreeStack* stack) {
    StackNode* top_node;
    int result;

    do {
        uintptr_t ptr = atomic_load(&stack->top);
        if ((uintptr_t)NULL == ptr) return -1;  // Stack is empty
        top_node = (StackNode*)ptr;
    } while (!atomic_compare_exchange_weak(
               &stack->top,
               &ptr,
               (uintptr_t)top_node->next));

    result = top_node->data;
    free(top_node);
    return result;
}

// Define a reference-counted pointer for the queue
typedef struct RefCountedQueue {
    LockFreeStack stack;
    atomic_int ref_count;
} RefCountedQueue;

// Initialize the reference-counted queue
RefCountedQueue* createRefCounterQueue() {
    RefCountedQueue* q = malloc(sizeof(RefCountedQueue));
    if (!q) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    initLockFreeStack(&q->stack);
    atomic_init(&q->ref_count, 1);
    return q;
}

// Increase the reference count
void retain(RefCountedQueue* queue) {
    atomic_fetch_add_explicit(&queue->ref_count, 1, memory_order_relaxed);
}

// Decrease the reference count and free if zero
void release(RefCountedQueue* queue) {
    if (atomic_fetch_sub_explicit(&queue->ref_count, 1, memory_order_acq_rel) == 1) {
        while (pop(&queue->stack) != -1); // Drain stack
        free(queue);
    }
}

// Function to initialize arrays with normal distribution values
void initNormalDistribution(int* keys, record* records, size_t size, int mean, double stddev) {
    for (size_t i = 0; i < size; ++i) {
        double u1 = ((double)rand() / RAND_MAX);
        double u2 = ((double)rand() / RAND_MAX);
        double z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);

        keys[i] = (int)(z0 * stddev + mean);
        records[i].value = keys[i];
    }
}

// Function to dynamically allocate and initialize data structures
void initDataStructures(size_t num_elements, int* offsets, int* keys, record** records_ptr,
                        double mean, double stddev) {
    // Memory alignment for cache-line optimization
    long align_size = 64; // Assuming 64-byte cache line

    // Allocate aligned memory
    void* mem = malloc(align_size + num_elements * sizeof(long));
    offsets = (long*)(((uintptr_t)mem + align_size - 1) & ~(align_size - 1));

    mem = malloc(align_size + num_elements * sizeof(int));
    keys = (int*)(((uintptr_t)mem + align_size - 1) & ~(align_size - 1));

    mem = malloc(align_size + num_elements * sizeof(record));
    *records_ptr = (record*)(((uintptr_t)mem + align_size - 1) & ~(align_size - 1));

    // Initialize keys and records with normal distribution
    initNormalDistribution(keys, *records_ptr, num_elements, mean, stddev);

    // Read integers from standard input and enqueue in a thread-safe manner
    RefCountedQueue* queue = createRefCounterQueue();
    int value;
    while (scanf("%d", &value) == 1) {
        retain(queue);
        push(&queue->stack, value);
        release(queue);
    }

    // Handle unexpected termination of the input stream gracefully
    // Note: Additional error checking and handling would typically be necessary

    printf("Data structures initialized and filled with values.\n");
}

int main() {
    size_t num_elements = 1000; // Example number of elements
    double mean = 50.0;
    double stddev = 10.0;

    long* offsets;
    int* keys;
    record* records;

    initDataStructures(num_elements, offsets, keys, &records, mean, stddev);

    // Clean up
    free((void*)(((uintptr_t)keys - sizeof(int)) & ~(64 - 1))); // Adjust based on actual allocation
    free((void*)(((uintptr_t)offsets - sizeof(long)) & ~(64 - 1)));
    free((void*)(((uintptr_t)records - sizeof(record)) & ~(64 - 1)));

    return 0;
}
