#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_ARRAY_SIZE 10
#define CACHE_POLICY_SIZE 5

typedef struct Node {
    unsigned long *timestamp;
    char *name;
    int status;
    int priority; // 0: low, 1: medium, 2: high
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct Record {
    int value;
} Record;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} LinkedList;

typedef struct ResizableArray {
    Record** records;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} ResizableArray;

// Function prototypes
LinkedList* create_linked_list();
Node* add_node(LinkedList* list, unsigned long timestamp, const char* name, int status, int priority);
int remove_node(LinkedList* list, Node* node);
ResizableArray* create_resizable_array(size_t initial_size);
void resize_array_if_needed(ResizableArray* arr);
void apply_transformation_to_list(LinkedList* list, void (*transform)(int*));

// Error logging function
void log_error(const char* operation, size_t requested_size, size_t actual_size) {
    if (actual_size < requested_size) {
        fprintf(stderr, "Error during %s: Requested %zu bytes but allocated only %zu bytes.\n", operation, requested_size, actual_size);
    }
}

// Create a new linked list
LinkedList* create_linked_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) {
        log_error("linked list creation", sizeof(LinkedList), 0);
        return NULL;
    }

    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Add a node to the linked list
Node* add_node(LinkedList* list, unsigned long timestamp, const char* name, int status, int priority) {
    if (!list) return NULL;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_error("node allocation", sizeof(Node), 0);
        return NULL;
    }

    new_node->timestamp = malloc(sizeof(unsigned long));
    if (!new_node->timestamp) {
        free(new_node);
        log_error("timestamp allocation", sizeof(unsigned long), 0);
        return NULL;
    }
    *new_node->timestamp = timestamp;

    size_t name_length = strlen(name) + 1;
    new_node->name = malloc(name_length);
    if (!new_node->name) {
        free(new_node->timestamp);
        free(new_node);
        log_error("name allocation", name_length, 0);
        return NULL;
    }
    memcpy(new_node->name, name, name_length);

    new_node->status = status;
    new_node->priority = priority;
    new_node->prev = list->tail;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);

    return new_node;
}

// Remove a node from the linked list
int remove_node(LinkedList* list, Node* node) {
    if (!list || !node) return -1;

    pthread_mutex_lock(&list->lock);
    if (node->prev) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }

    if (node->next) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }
    pthread_mutex_unlock(&list->lock);

    free(node->name);
    free(node->timestamp);
    free(node);

    return 0;
}

// Create a new resizable array
ResizableArray* create_resizable_array(size_t initial_size) {
    ResizableArray* arr = malloc(sizeof(ResizableArray));
    if (!arr) {
        log_error("array creation", sizeof(ResizableArray), 0);
        return NULL;
    }

    arr->records = malloc(initial_size * sizeof(Record*));
    if (!arr->records) {
        free(arr);
        log_error("record array allocation", initial_size * sizeof(Record*), 0);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        arr->records[i] = malloc(sizeof(Record));
        if (!arr->records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(arr->records[j]);
            }
            free(arr->records);
            free(arr);
            log_error("record allocation", sizeof(Record), 0);
            return NULL;
        }
        arr->records[i]->value = rand() % 100 + 1; // Random value between 1 and 100
    }

    arr->capacity = initial_size;
    arr->used = initial_size;
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

// Resize the array if needed
void resize_array_if_needed(ResizableArray* arr) {
    if (!arr || !pthread_mutex_lock(&arr->lock)) return;

    if (arr->used >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        Record** new_records = realloc(arr->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&arr->lock);
            log_error("array resizing", new_capacity * sizeof(Record*), 0);
            return;
        }

        for (size_t i = arr->capacity; i < new_capacity; ++i) {
            new_records[i] = malloc(sizeof(Record));
            if (!new_records[i]) {
                pthread_mutex_unlock(&arr->lock);
                log_error("record allocation", sizeof(Record), 0);
                return;
            }
            new_records[i]->value = rand() % 100 + 1; // Random value between 1 and 100
        }

        arr->records = new_records;
        arr->capacity = new_capacity;
    }

    pthread_mutex_unlock(&arr->lock);
}

// Apply a transformation to each node's status in the linked list
void apply_transformation_to_list(LinkedList* list, void (*transform)(int*)) {
    if (!list || !transform) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        transform(&(current->status));
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Example transformation function
void example_transformation(int* status) {
    if (*status == 0) *status = 1; // Change normal to warning for demonstration
}
