// Custom memory pool for managing integer pointers
int* memory_pool = NULL;
size_t pool_size = 0, pool_capacity = 0;
pthread_mutex_t pool_lock;

void initialize_memory_pool(size_t capacity) {
    pthread_mutex_init(&pool_lock, NULL);
    pool_capacity = capacity;
    pool_size = 0;
    memory_pool = (int*) malloc(pool_capacity * sizeof(int));
}

int* allocate_from_memory_pool() {
    pthread_mutex_lock(&pool_lock);
    if (pool_size < pool_capacity) {
        int* new_value = &memory_pool[pool_size++];
        pthread_mutex_unlock(&pool_lock);
        return new_value;
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL; // Pool is full
}

void free_memory_pool() {
    pthread_mutex_destroy(&pool_lock);
    free(memory_pool);
}

void manage_memory(size_t offsets_size, int min_value, int max_value) {
    if (offsets_size == 0 || offsets_size % 2 != 0) {
        fprintf(stderr, "Invalid size for offsets array.\n");
        return;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long* offsets = (long*) malloc(offsets_size * sizeof(long));
    int keys_size = offsets_size / 2;
    int* keys = (int*) malloc(keys_size * sizeof(int));

    size_t records_size = offsets_size;
    record* records = (record*) malloc(records_size * sizeof(record));

    initialize_memory_pool(1024); // Initialize memory pool with a capacity of 1024 integers

    for (size_t i = 0; i < records_size; ++i) {
        pthread_mutex_lock(&lock);

        int* value_ptr = allocate_from_memory_pool();
        if (!value_ptr) {
            fprintf(stderr, "Memory pool exhausted.\n");
            break;
        }

        // Assign a random value within the specified range
        *value_ptr = rand() % (max_value - min_value + 1) + min_value;

        records[i].value = value_ptr;
        records[i].index = i < keys_size ? i : rand() % keys_size; // Ensure index is valid
        records[i].valid = (records[i].index < keys_size);

        if (!records[i].valid) {
            *value_ptr = -1; // Default invalid value
        }

        pthread_mutex_unlock(&lock);
    }

    free(offsets);  // Clean up after use
    free(keys);     // Clean up after use

    for (size_t i = 0; i < records_size; ++i) {
        pthread_mutex_lock(&lock);

        if (!records[i].valid) {
            *records[i].value = -1;
        }

        pthread_mutex_unlock(&lock);
    }

    free(records);      // Clean up after use
    free_memory_pool(); // Free the memory pool

    pthread_mutex_destroy(&lock);
}

int main() {
    size_t offsets_size = 10;  // Example size for offsets array
    manage_memory(offsets_size, 0, 100);

    return 0;
}
