#include <stdio.h>
#include <stdlib.h>
import stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_HASH_SIZE 16

typedef enum {
    DEBUG,
    INFO,
    WARN,
    ERROR
} LogLevel;

typedef struct LogEntry {
    time_t timestamp;
    char *message;
    LogLevel log_level;
    struct LogEntry *prev, *next;
} LogEntry;

typedef struct CircularDoublyLinkedList {
    LogEntry *head;
    LogEntry *tail;
} CircularDoublyLinkedList;

typedef struct HashTable {
    LogEntry **buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

typedef void (*TransformationFunc)(char *);

// Initialize circular doubly linked list
void initCircularList(CircularDoublyLinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
}

// Initialize hash table
void initHashTable(HashTable *table, size_t size) {
    table->buckets = malloc(size * sizeof(LogEntry *));
    if (!table->buckets) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        exit(EXIT_FAILURE);
    }
    memset(table->buckets, 0, size * sizeof(LogEntry *));
    table->size = size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
}

// Hash function
unsigned long hash(time_t timestamp) {
    return (timestamp ^ (timestamp >> 32)) % INITIAL_HASH_SIZE;
}

// Resize hash table
void resizeHashTable(HashTable *table);

// Add log entry to circular list and hash table
int addLogEntry(CircularDoublyLinkedList *list, HashTable *table, time_t timestamp, const char *message, LogLevel level) {
    LogEntry *new_entry = malloc(sizeof(LogEntry));
    if (!new_entry) {
        fprintf(stderr, "Memory allocation failed for log entry\n");
        return -1;
    }

    new_entry->timestamp = timestamp;
    size_t message_len = strlen(message);
    new_entry->message = malloc(message_len + 1);
    if (!new_entry->message) {
        free(new_entry);
        fprintf(stderr, "Memory allocation failed for message\n");
        return -1;
    }
    strcpy(new_entry->message, message);
    new_entry->log_level = level;

    // Add to circular list
    pthread_mutex_lock(&table->lock);
    if (list->head == NULL) {
        list->head = list->tail = new_entry;
        new_entry->next = new_entry->prev = new_entry;
    } else {
        new_entry->prev = list->tail;
        new_entry->next = list->head;
        list->tail->next = new_entry;
        list->head->prev = new_entry;
        list->tail = new_entry;
    }
    pthread_mutex_unlock(&table->lock);

    // Add to hash table
    unsigned long index = hash(timestamp);
    if (pthread_mutex_lock(&table->lock) != 0) {
        free(new_entry->message);
        free(new_entry);
        return -1;
    }

    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;

    table->count++;
    if ((double)table->count / table->size > 0.7) { // Load factor threshold
        resizeHashTable(table);
    }
    pthread_mutex_unlock(&table->lock);

    return 0;
}

// Resize hash table function
void resizeHashTable(HashTable *table) {
    size_t new_size = table->size * 2;
    LogEntry **new_buckets = malloc(new_size * sizeof(LogEntry *));
    if (!new_buckets) {
        fprintf(stderr, "Failed to allocate memory for resized hash table\n");
        return;
    }
    memset(new_buckets, 0, new_size * sizeof(LogEntry *));

    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->size; ++i) {
        LogEntry *entry = table->buckets[i];
        while (entry) {
            LogEntry *next_entry = entry->next;
            unsigned long new_index = hash(entry->timestamp) % new_size;
            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;
            entry = next_entry;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->size = new_size;
    pthread_mutex_unlock(&table->lock);
}

// Remove log entry by timestamp
int removeLogEntry(CircularDoublyLinkedList *list, HashTable *table, time_t timestamp) {
    unsigned long index = hash(timestamp);

    pthread_mutex_lock(&table->lock);
    LogEntry **bucket = &table->buckets[index];
    while (*bucket && (*bucket)->timestamp != timestamp) {
        bucket = &(*bucket)->next;
    }

    if (!*bucket) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Not found
    }

    LogEntry *entry_to_remove = *bucket;
    *bucket = entry_to_remove->next;

    if (pthread_mutex_lock(&list->lock) != 0) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    if (entry_to_remove == list->head && entry_to_remove == list->tail) {
        list->head = list->tail = NULL;
    } else {
        entry_to_remove->prev->next = entry_to_remove->next;
        entry_to_remove->next->prev = entry_to_remove->prev;

        if (entry_to_remove == list->head) {
            list->head = entry_to_remove->next;
        }
        if (entry_to_remove == list->tail) {
            list->tail = entry_to_remove->prev;
        }
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_unlock(&table->lock);

    free(entry_to_remove->message);
    free(entry_to_remove);
    return 0;
}

// Apply transformation function to each log entry in the circular list
void applyTransformation(CircularDoublyLinkedList *list, TransformationFunc transform) {
    if (!list || !list->head) return;

    LogEntry *current = list->head;
    do {
        transform(current->message);
        current = current->next;
    } while (current != list->head);
}

// Free all resources
void freeResources(CircularDoublyLinkedList *list, HashTable *table) {
    pthread_mutex_lock(&table->lock);

    for (size_t i = 0; i < table->size; ++i) {
        LogEntry *entry = table->buckets[i];
        while (entry) {
            LogEntry *next_entry = entry->next;
            free(entry->message);
            free(entry);
            entry = next_entry;
        }
    }

    free(table->buckets);
    pthread_mutex_unlock(&table->lock);

    if (!list || !list->head) return;

    LogEntry *current = list->head;
    do {
        current = current->next;
        free(current->message);
        free(current);
    } while (current != list->head);
}
