#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_PRIORITY_LEVELS 3

typedef struct {
    float *data;
    size_t size;
} Metrics;

typedef struct Node {
    unsigned long *timestamp;
    char *name;
    int status;
    int priority; // high, medium, low
    Metrics metrics;
    struct Node *prev;
    struct Node *next;
} Node;

typedef struct {
    int value;
} Record;

// Helper function for aligned allocation
void* aligned_alloc(size_t alignment, size_t size) {
    void *ptr = NULL;
#if defined(_POSIX_C_SOURCE)
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
#else
    ptr = _aligned_malloc(size, alignment);
#endif
    return ptr;
}

// Helper function for freeing aligned allocation
void free_aligned(void *ptr) {
#if defined(_POSIX_C_SOURCE)
    free(ptr);
#else
    _aligned_free(ptr);
#endif
}

// Logging mechanism
void log_error(const char *operation, size_t requested_size, size_t allocated_size) {
    if (requested_size != allocated_size) {
        fprintf(stderr, "Error in %s: Requested size %zu but got %zu\n", operation, requested_size, allocated_size);
    }
}

// Function to allocate and initialize a doubly linked list
Node* create_node(unsigned long timestamp_value, const char *name, int status, int priority, float *metrics_data, size_t metrics_count) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) {
        log_error("Allocate node", sizeof(Node), 0);
        return NULL;
    }

    node->timestamp = aligned_alloc(alignof(unsigned long), sizeof(unsigned long));
    if (!node->timestamp) {
        free(node);
        log_error("Allocate timestamp", sizeof(unsigned long), 0);
        return NULL;
    }
    *node->timestamp = timestamp_value;

    size_t name_len = strlen(name) + 1;
    node->name = (char *)malloc(name_len);
    if (!node->name) {
        free_aligned(node->timestamp);
        free(node);
        log_error("Allocate name", name_len, 0);
        return NULL;
    }
    memcpy(node->name, name, name_len);

    node->status = status;
    node->priority = priority;

    Metrics *metrics = (Metrics *)aligned_alloc(alignof(float), sizeof(Metrics));
    if (!metrics) {
        free(node->name);
        free_aligned(node->timestamp);
        free(node);
        log_error("Allocate metrics", sizeof(Metrics), 0);
        return NULL;
    }

    node->metrics.data = aligned_alloc(alignof(float), metrics_count * sizeof(float));
    if (!node->metrics.data) {
        free(metrics);
        free(node->name);
        free_aligned(node->timestamp);
        free(node);
        log_error("Allocate metrics data", metrics_count * sizeof(float), 0);
        return NULL;
    }

    memcpy(node->metrics.data, metrics_data, metrics_count * sizeof(float));
    node->metrics.size = metrics_count;

    node->prev = node->next = NULL;
    return node;
}

// Function to add a node to the linked list
void add_node(Node **head, Node *new_node) {
    new_node->next = *head;
    if (*head != NULL) {
        (*head)->prev = new_node;
    }
    *head = new_node;
}

// Function to remove a node from the linked list
void remove_node(Node **head, Node *node_to_remove) {
    if (node_to_remove == NULL) return;

    if (node_to_remove->prev != NULL) {
        node_to_remove->prev->next = node_to_remove->next;
    } else {
        *head = node_to_remove->next;
    }

    if (node_to_remove->next != NULL) {
        node_to_remove->next->prev = node_to_remove->prev;
    }

    free_aligned(node_to_remove->timestamp);
    free(node_to_remove->name);
    free_aligned(node_to_remove->metrics.data);
    free(node_to_remove->metrics.data);
    free(node_to_remove);
}

// Function to initialize a resizable array of records
Record* create_records(size_t capacity, int min_value, int max_value) {
    Record *records = (Record *)malloc(capacity * sizeof(Record));
    if (!records) {
        log_error("Allocate records", capacity * sizeof(Record), 0);
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }
    return records;
}

// Function to resize the array of records
Record* resize_records(Record *records, size_t old_capacity, size_t new_capacity) {
    Record *new_records = (Record *)realloc(records, new_capacity * sizeof(Record));
    if (!new_records && new_capacity > 0) {
        log_error("Reallocate records", new_capacity * sizeof(Record), 0);
        return NULL;
    }

    for (size_t i = old_capacity; i < new_capacity; ++i) {
        int min_value = -100, max_value = 100;
        new_records[i].value = min_value + rand() % (max_value - min_value + 1);
    }
    return new_records;
}

// Example use case
int main() {
    srand(time(NULL));

    Node *head = NULL;

    // Create nodes and add them to the list
    float metrics_data_1[] = {1.0, 2.5, 3.7};
    Node *node1 = create_node(1627851901UL, "Resource1", 0, 1, metrics_data_1, 3);
    if (node1) add_node(&head, node1);

    float metrics_data_2[] = {4.5, 5.9};
    Node *node2 = create_node(1627852001UL, "Resource2", 1, 2, metrics_data_2, 2);
    if (node2) add_node(&head, node2);

    // Create a resizable array of records
    size_t capacity = INITIAL_CAPACITY;
    Record *records = create_records(capacity, 0, 50);

    // Simulate resizing the records
    capacity *= 2; 
    Record *new_records = resize_records(records, INITIAL_CAPACITY, capacity);
    if (new_records) {
        free(records); // Free old array if realloc succeeded
        records = new_records;
    }

    // Remove a node from the list
    remove_node(&head, node1);

    // Clean up remaining nodes
    while (head != NULL) {
        Node *temp = head;
        head = head->next;
        remove_node(&head, temp);
    }

    free(records); // Cleanup records

    return 0;
}
