["```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef enum { SUCCESS, ERROR_OUT_OF_MEMORY } Status;

typedef struct {
    long *offsets;
    int *keys;
    Record *records;
    size_t size;
    pthread_mutex_t lock; // Mutex for protecting data
} MemoryManager;

Status initialize_memory_manager(MemoryManager *manager, size_t num_elements, size_t memory_limit) {
    if (!manager || num_elements == 0) return ERROR_OUT_OF_MEMORY;

    size_t offset_size = num_elements * sizeof(long);
    size_t keys_size = num_elements * sizeof(int);
    size_t records_size = num_elements * sizeof(Record);

    size_t total_memory_required = offset_size + keys_size + records_size;

    if (total_memory_required > memory_limit) return ERROR_OUT_OF_MEMORY;

    // Allocate memory
    manager->offsets = (long *)malloc(offset_size);
    manager->keys = (int *)malloc(keys_size);
    manager->records = (Record *)malloc(records_size);

    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        return ERROR_OUT_OF_MEMORY;
    }

    // Initialize memory
    for (size_t i = 0; i < num_elements; ++i) {
        manager->offsets[i] = 0; // Initialize offsets to zero
        manager->keys[i] = 0;    // Initialize keys to zero
        manager->records[i].value = 0; // Initialize records value to zero
    }

    manager->size = num_elements;

    pthread_mutex_init(&manager->lock, NULL);

    return SUCCESS;
}

void reset_records(MemoryManager *manager) {
    if (!manager || !manager->records) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        manager->records[i].value = 0;
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_memory_manager(MemoryManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
}
