long next_power_of_two(long x) {
    return 1UL << (32 - __builtin_clz(x - 1));
}

bool allocate_and_initialize(long offsets_size, long min_value, long max_value, int keys_min_threshold, long* offsets, int** keys, record*** records) {
    if (offsets_size < 2 || (offsets_size & (offsets_size - 1)) != 0) { // Check if not a power of two
        fprintf(stderr, "Invalid size for offsets array. Must be a power of two.\n");
        return false;
    }

    size_t keys_size = offsets_size / 2;

    if (keys_size < keys_min_threshold) {
        fprintf(stderr, "Keys array size below minimum threshold.\n");
        return false;
    }

    *offsets = malloc(offsets_size * sizeof(long));
    if (*offsets == NULL) {
        perror("Failed to allocate memory for offsets array");
        return false;
    }

    *keys = calloc(keys_size, sizeof(int)); // Use calloc to initialize values
    if (*keys == NULL) {
        free(*offsets);
        perror("Failed to allocate memory for keys array");
        return false;
    }

    size_t records_size = offsets_size;
    *records = malloc(records_size * sizeof(record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        perror("Failed to allocate memory for records array");
        return false;
    }

    // Initialize the record structures
    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < records_size; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for record %zu\n", i);
            // Free previously allocated resources
            while (i > 0) { // Free all previous allocations in case of error
                free((*records)[--i]);
            }
            free(*records);
            free(*keys);
            free(*offsets);
            return false;
        }

        (*records)[i]->value = malloc(sizeof(int));
        if ((*records)[i]->value == NULL) {
            fprintf(stderr, "Failed to allocate memory for int value in record %zu\n", i);
            free((*records)[i]);
            while (i > 0) {
                free((*records)[--i]);
            }
            free(*records);
            free(*keys);
            free(*offsets);
            return false;
        }

        (*records)[i]->index = rand() % keys_size; // Random index within bounds
        if ((*records)[i]->index >= keys_size) {
            fprintf(stderr, "Index out of bounds for record %zu. Resetting value.\n", i);
            free((*records)[i]->value);
            (*records)[i]->valid = false;
            *(*records)[i] = (record){NULL, 0, false};
            continue; // Skip random number generation for this iteration
        }

        int random_value = rand() % (max_value - min_value + 1) + min_value;
        *(*records)[i]->value = random_value;

        (*records)[i]->valid = true;
    }

    return true;
}

void free_resources(long* offsets, int* keys, record** records, size_t records_size) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        for (size_t i = 0; i < records_size; ++i) {
            if (records[i] != NULL) {
                free(records[i]->value);
                free(records[i]);
            }
        }
        free(records);
    }
}

// Example usage
