```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
import <math.h>
#include <sys/socket.h>
#include <arpa/inet.h>

#define QUEUE_SIZE 1024

typedef struct {
    int value;
} record;

typedef struct Node {
    struct Node* next;
    record data;
} QueueNode;

typedef struct {
    QueueNode* head;
    QueueNode* tail;
    pthread_spinlock_t lock;
    int count;
} SpinlockQueue;

typedef struct {
    double mean;
    double stddev;
} DistributionProfile;

// Function prototypes
double generateNormal(double mean, double stddev);
void initQueue(SpinlockQueue* q);
int enqueue(SpinlockQueue* q, record rec);
record dequeue(SpinlockQueue* q);
void* producer(void* arg);
void* consumer(void* arg);

SpinlockQueue queue;
DistributionProfile profile = {50.0, 10.0};

// Initialize the spinlock-based queue
void initQueue(SpinlockQueue* q) {
    pthread_spin_init(&q->lock, PTHREAD_PROCESS_PRIVATE);
    q->head = NULL;
    q->tail = NULL;
    q->count = 0;
}

// Generate a normally distributed random number using Box-Muller transform
double generateNormal(double mean, double stddev) {
    static int hasSpare = 0;
    static double spare;

    if (hasSpare == 1) {
        hasSpare = 0;
        return mean + spare * stddev;
    }

    hasSpare = 1;
    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;

    double z0 = sqrt(-2.0 * log(u1)) * cos(2 * M_PI * u2);
    spare = sqrt(-2.0 * log(u1)) * sin(2 * M_PI * u2);

    return mean + z0 * stddev;
}

// Enqueue a record into the queue
int enqueue(SpinlockQueue* q, record rec) {
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) return -1;

    newNode->data.value = (int)generateNormal(profile.mean, profile.stddev);
    newNode->next = NULL;

    pthread_spin_lock(&q->lock);

    if (q->tail) {
        q->tail->next = newNode;
    } else {
        q->head = newNode;
    }

    q->tail = newNode;
    q->count++;

    pthread_spin_unlock(&q->lock);
    return 0;
}

// Dequeue a record from the queue
record dequeue(SpinlockQueue* q) {
    record rec;
    pthread_spin_lock(&q->lock);

    if (!q->head) {
        pthread_spin_unlock(&q->lock);
        return (record){-1}; // Return -1 value to indicate empty queue
    }

    QueueNode* temp = q->head;
    rec = temp->data;
    q->head = q->head->next;

    if (!q->head) {
        q->tail = NULL;
    }

    free(temp);
    q->count--;

    pthread_spin_unlock(&q->lock);
    return rec;
}

// Producer thread function
void* producer(void* arg) {
    int sock = *(int*)arg;
    char buffer[1024];
    while (recv(sock, buffer, sizeof(buffer), 0) > 0) {
        record rec;
        // Process buffer to create a record; omitted for brevity
        enqueue(&queue, rec);
    }
    return NULL;
}

// Consumer thread function
void* consumer(void* arg) {
    while (1) {
        record rec = dequeue(&queue);
        if (rec.value != -1) {
            // Process the record; omitted for brevity
        }
    }
    return NULL;
}

int main(int argc, char** argv) {
    int sock;
    struct sockaddr_in server_addr;

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, '0', sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);

    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        exit(EXIT_FAILURE);
    }

    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection Failed");
        exit(EXIT_FAILURE);
    }

    initQueue(&queue);

    pthread_t prod_thread, cons_thread;
    pthread_create(&prod_thread, NULL, producer, &sock);
    pthread_create(&cons_thread, NULL, consumer, NULL);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    close(sock);
    return 0;
}
