    apiStrategy->process(sampleData);
    Logger::log("API data processed.");

    // Use DAO for storage operations
    dao = std::make_unique<DistributedDatabaseDao>();
    nlohmann::json jsonData;
    dao->save(jsonData);

    Logger::log("Data saved and replicated successfully.");
}

int main() {
    DataProcessorApp app;
    app.run();
    return 0;
}
```

