typedef struct {
    double value;
    char *str;
    Point point;
} Geometry;

typedef struct MemoryPool {
    size_t totalSize;
    void *memory;
    pthread_mutex_t lock;
} MemoryPool;

// Function to create a memory pool
MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->totalSize = size;
    pool->memory = malloc(size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to allocate memory from the pool
void* pool_allocate(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (size > pool->totalSize) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    void *ptr = pool->memory;
    pool->memory = (char*)pool->memory + size;
    pool->totalSize -= size;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Function to generate a random alphanumeric string
void random_alphanumeric_string(char *str, int length) {
