        random_alphanumeric_string(str, ALPHANUMERIC_LENGTH);
        geometries[i].str = str;

        Point *point = (Point*)pool_allocate(pool, sizeof(Point));
        if (!point) return NULL;
        point->x = ((float)rand() / RAND_MAX) * 100.0f; // Example range
        point->y = ((float)rand() / RAND_MAX) * 100.0f; // Example range
        geometries[i].point = *point;
    }

    return geometries;
}

// Function to deallocate the memory pool
