        free(config);
        return NULL;
    }

    // Determine format and parse
    char buffer[256];
    fread(buffer, 1, sizeof(buffer), file);

    if (strncmp(buffer, "{", 1) == 0) {
        config->format = strdup("JSON");
        fseek(file, 0, SEEK_SET);
        struct json_object *parsed_json;
        parsed_json = json_tokener_parse(file);
        fclose(file);
        pthread_mutex_lock(&config->lock);
        config->json = parsed_json; // Take ownership
        pthread_mutex_unlock(&config->lock);
    } else if (strstr(buffer, "[") != NULL) {
        config->format = strdup("INI");
        fseek(file, 0, SEEK_SET);
        if (config_read_file(&config->ini, file) == CONFIG_FALSE) {
            log_error("Failed to parse INI configuration.");
            free(config);
            fclose(file);
            return NULL;
        }
        fclose(file);
    } else if (strstr(buffer, "<?xml") != NULL) {
        config->format = strdup("XML");
        fseek(file, 0, SEEK_SET);
        config->xml = xmlParseFile(filename);
        if (!config->xml) {
            log_error("Failed to parse XML configuration.");
            free(config);
            fclose(file);
            return NULL;
        }
    } else {
        log_error("Unsupported file format.");
        free(config);
        fclose(file);
        return NULL;
    }

    // Validate against schema here...

    return config;
}

// Function to free configuration data
void free_config(struct ConfigData *config) {
    if (!config) return;

    pthread_mutex_lock(&config->lock);
    if (config->json) json_object_put(config->json); // Release JSON object
    if (config->ini) config_destroy(&config->ini);  // Destroy INI structure

    if (config->xml) xmlFreeDoc(config->xml);        // Free XML document
    pthread_mutex_unlock(&config->lock);

    free(config->format);
    pthread_mutex_destroy(&config->lock);
    free(config);
}

