// Define a simple memory pool structure
typedef struct {
    size_t block_size;
    void* memory;
} MemoryPool;

#define POOL_SIZE 1024 * 64

void init_memory_pool(MemoryPool* pool, size_t item_size, size_t count) {
    pool->block_size = item_size * count;
    pool->memory = malloc(pool->block_size);
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    static size_t offset = 0;
    if (offset + size > pool->block_size) return NULL; // Out of memory
    void* block = (char*)pool->memory + offset;
    offset += size;
    return block;
}

void free_memory_pool(MemoryPool* pool) {
    free(pool->memory);
    pool->memory = NULL;
}

// Define structures
typedef struct {
    float x, y;
} Point;

typedef struct {
    double value;
    char *string;
    Point point;
} Geometry;

typedef struct {
    int integer;
