} Complex;

// Global memory pool
MemoryPool mem_pool;

// Synchronization primitives
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Configuration for logging and debug
int enable_logging = 1;

void log(const char* message) {
    if (enable_logging) {
        printf("%s\n", message);
    }
}

