    const char charset[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    for (size_t i = 0; i < length; ++i) {
        int key = rand() % (sizeof(charset) - 1);
        str[i] = charset[key];
    }
    str[length] = '\0';
}

double random_double(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

void* initialize_memory(void* data) {
    // Initialize structures
    if (data == NULL) return NULL;

    log("Initializing memory for five types of data structures.");

    // 1. Double precision floating-point numbers
    double* doubles = allocate_from_pool(&mem_pool, sizeof(double));
    if (!doubles) { perror("Allocation error"); exit(EXIT_FAILURE); }

    // 2. Char strings
    char* string = (char*)allocate_from_pool(&mem_pool, 256);
    if (!string) { perror("Allocation error"); exit(EXIT_FAILURE); }
    generate_random_alphanumeric_string(string, 255);

    // 3. Point structures
    Point point = {
        .x = (float)random_double(-100.0, 100.0),
        .y = (float)random_double(-100.0, 100.0)
    };

    // 4. Geometry structures
    Geometry geometry;
    geometry.value = random_double(1.0, 10.0);
    geometry.string = string; // Reuse allocated char string
    geometry.point = point;

    // 5. Complex structures
    Complex complex;
    complex.integer = 42; // Predefined value

    complex.geometry = geometry;

    size_t points_count = 5;
    complex.points_array = (Point*)allocate_from_pool(&mem_pool, sizeof(Point) * points_count);
    if (!complex.points_array) { perror("Allocation error"); exit(EXIT_FAILURE); }
    complex.array_size = points_count;

    for (size_t i = 0; i < points_count; ++i) {
        complex.points_array[i].x = (float)random_double(-100.0, 100.0);
        complex.points_array[i].y = (float)random_double(-100.0, 100.0);
    }

    return &complex;
}

void cleanup_memory(void* complex_ptr) {
    if (!complex_ptr) return;

    Complex* complex = (Complex*)complex_ptr;

    // Since we're using a single memory pool, no need to free individual allocations
    log("Cleaning up allocated memory.");

    // Reset the global offset for potential reuse of the memory pool
    mem_pool.offset = 0;
}

int main() {
    srand((unsigned)time(NULL));
    init_memory_pool(&mem_pool, sizeof(Complex), 1); // Initialize memory pool

    pthread_t thread_id;

    // Create a thread to initialize and clean up the data structures
    if (pthread_create(&thread_id, NULL, (void*(*)(void*))initialize_memory, NULL) != 0) {
        perror("Thread creation failed");
        exit(EXIT_FAILURE);
    }

    void* complex_data;
    pthread_join(thread_id, &complex_data);

    cleanup_memory(complex_data);

    free_memory_pool(&mem_pool);

    return 0;
}
