#include "random.h" // Assuming a library for random number generation
#include "lockfree_queue.h" // Assuming a lock-free queue implementation

#define FLOAT_ARRAY_SIZE 100
#define STRING_LENGTH 10
#define POOL_THRESHOLD 0.8
#define MEMORY_POOL_SIZE (1024 * 1024) // Example size, adjust as needed

typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    double value;
    char str[STRING_LENGTH];
    Point point;
} Geometry;

typedef struct {
    Geometry geom1;
    Geometry geom2;
    int version;
} ComplexGeometry;

typedef struct MemoryBlock {
    void *ptr;
    atomic_int ref_count;
} MemoryBlock;

MemoryBlock memory_pool[MEMORY_POOL_SIZE];
atomic_int pool_usage = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Mutex for critical sections
lockfree_queue_t* compaction_tasks = NULL;        // Queue for asynchronous tasks

void init_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        memory_pool[i].ptr = NULL;
        atomic_store(&memory_pool[i].ref_count, 0);
    }
}

MemoryBlock allocate_memory(size_t size) {
    pthread_mutex_lock(&lock);

    MemoryBlock block;
    for (int i = 0; i < MEMORY_POOL_SIZE; ++i) {
        if (memory_pool[i].ptr == NULL && pool_usage < MEMORY_POOL_SIZE * POOL_THRESHOLD) {
            memory_pool[i].ptr = malloc(size);
            atomic_store(&memory_pool[i].ref_count, 1);
            pool_usage++;
            block.ptr = memory_pool[i].ptr;
            block.ref_count = i;
            pthread_mutex_unlock(&lock);
            return block;
        }
    }

    pthread_mutex_unlock(&lock);
    fprintf(stderr, "Memory allocation failed\n");
    exit(EXIT_FAILURE);
}

void deallocate_memory(MemoryBlock* block) {
    pthread_mutex_lock(&lock);

    if (block && atomic_fetch_sub(&memory_pool[block->ref_count].ref_count, 1) == 1) {
        free(memory_pool[block->ref_count].ptr);
        memory_pool[block->ref_count].ptr = NULL;
        pool_usage--;
    }

    pthread_mutex_unlock(&lock);
}

void* allocate_aligned_memory(size_t size, size_t alignment) {
    void *ptr = malloc(size + alignment);
    if (!ptr)
        return NULL;

    uintptr_t addr = (uintptr_t)ptr + alignment - 1;
    addr -= addr % alignment;
    ptr = (void*)addr;

    MemoryBlock block = { .ptr = ptr, .ref_count = 0 };
    atomic_store(&memory_pool[block.ref_count].ref_count, 1);
    return block.ptr;
}

int allocate_float_array(double **array) {
    *array = (double *)allocate_aligned_memory(FLOAT_ARRAY_SIZE * sizeof(double), alignof(double));
    if (!*array)
        return -1;

    for (int i = 0; i < FLOAT_ARRAY_SIZE; ++i) {
        (*array)[i] = rand_double(0.0, 100.0); // Assuming rand_double generates a random double in range
    }

    return 0;
}

void initialize_geometry(Geometry *geom) {
    geom->value = rand_double(0.0, 1.0);
    generate_random_string(geom->str, STRING_LENGTH); // Assuming this function exists
    geom->point.x = rand_float(0.0f, 100.0f); // Assuming rand_float generates a random float in range
    geom->point.y = rand_float(0.0f, 100.0f);
}

void update_complex_geometry_version(ComplexGeometry *cg) {
    atomic_fetch_add(&cg->version, 1);
}

