#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_S_TMSI 0xFFFFFFFF

typedef struct {
    uint32_t PAGING_MESSAGE_TAG;
    uint32_t S_TMSI;
    int T3112_timer; // configurable timer value
} NFAPI_RRC_PDU_T;

typedef struct {
    NFAPI_RRC_PDU_T *array;
    size_t size;
    pthread_mutex_t lock;
    uint64_t next_unique_id; // For generating unique S-TMSI values
    FILE *log_file;
} NFAPIDynamicArray;

// Initialize the dynamic array structure
void init_dynamic_array(NFAPIDynamicArray *da, size_t initial_size) {
    da->array = (NFAPI_RRC_PDU_T *)malloc(initial_size * sizeof(NFAPI_RRC_PDU_T));
    da->size = initial_size;
    pthread_mutex_init(&da->lock, NULL);
    da->next_unique_id = 1; // Start with a unique ID greater than zero
    da->log_file = fopen("paging_message_log.txt", "a");
}

// Destroy the dynamic array structure and free resources
void destroy_dynamic_array(NFAPIDynamicArray *da) {
    pthread_mutex_destroy(&da->lock);
    fclose(da->log_file);
    free(da->array);
}

// Thread-safe function to add a new NFAPI_RRC_PDU_T to the dynamic array
int add_paging_message(NFAPIDynamicArray *da, int T3112_timer) {
    pthread_mutex_lock(&da->lock);

    if (da->next_unique_id >= MAX_S_TMSI) {
        fprintf(stderr, "Error: Maximum S-TMSI value reached.\n");
        pthread_mutex_unlock(&da->lock);
        return -1;
    }

    // Resize array if necessary
    size_t current_size = da->size;
    if (current_size == 0 || (current_size * sizeof(NFAPI_RRC_PDU_T)) % MAX_S_TMSI == 0) {
        current_size *= 2;
        da->array = (NFAPI_RRC_PDU_T *)realloc(da->array, current_size * sizeof(NFAPI_RRC_PDU_T));
        if (!da->array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failed
        }
    }

    uint32_t paging_message_tag = rand();  // Generate a random PAGING_MESSAGE_TAG
    NFAPI_RRC_PDU_T *pdu = &da->array[(current_size / 2) - 1];
    pdu->PAGING_MESSAGE_TAG = paging_message_tag;
    pdu->S_TMSI = da->next_unique_id++;
    pdu->T3112_timer = T3112_timer;

    // Log the creation of PAGING_MESSAGE_TAG
    fprintf(da->log_file, "Created Paging Message Tag: %u at time %ld\n", paging_message_tag, time(NULL));

    pthread_mutex_unlock(&da->lock);
    return 0; // Success
}

// Example usage
int main() {
    NFAPIDynamicArray da;
    init_dynamic_array(&da, 10); // Initialize with an initial size of 10

    // Simulate adding paging messages in a multi-threaded environment
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, (void *(*)(void *))add_paging_message, &da);
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_dynamic_array(&da);

    return 0;
}
