    int node_count;
    int edge_count;
    pthread_mutex_t lock;
    // Metadata and monitoring fields
    double average_degree;
    time_t last_updated;
} Graph;

Graph* create_graph() {
    Graph *graph = (Graph *)malloc(sizeof(Graph));
    if (!graph) return NULL;

    memset(graph, 0, sizeof(Graph));
    pthread_mutex_init(&graph->lock, NULL);
    graph->node_count = 0;
    graph->edge_count = 0;

    // Initialize monitoring and logging
    log_event("Graph created", 0);

    return graph;
}

int verify_node_in_db(int node_id) {
    // Simulate network latency and potential service outages
    // Implement actual DB verification logic here.
    return rand() % 2; // Randomly simulate existence (replace with real check)
}

void log_event(const char *message, int error_code) {
    time_t now = time(NULL);
    printf("[%s] %s - Error Code: %d\n", ctime(&now), message, error_code);
}

int add_node(Graph *graph, int node_id) {
    if (!graph) return -1;

    pthread_mutex_lock(&graph->lock);

    if (graph->node_count >= MAX_NODES) {
        log_event("Node addition failed: Max nodes reached", 1);
        pthread_mutex_unlock(&graph->lock);
        return -2;
    }

    int exists = verify_node_in_db(node_id);
    if (!exists) {
        Node *new_node = (Node *)malloc(sizeof(Node));
        if (!new_node) {
            log_event("Memory allocation failed for new node", 2);
            pthread_mutex_unlock(&graph->lock);
            return -3;
        }

        new_node->id = node_id;
        strcpy(new_node->attributes, "default"); // Initialize with default attributes
        graph->nodes[graph->node_count++] = new_node;

        log_event("Node added", 0);

    } else {
        // Update existing node or add edges as per policy
        for (int i = 0; i < graph->node_count; i++) {
            if (graph->nodes[i]->id == node_id) {
                // Update attributes or handle edge addition
                log_event("Node exists, update/edges added", 0);
                break;
            }
        }
    }

    pthread_mutex_unlock(&graph->lock);

    return 0;
}

int add_edge(Graph *graph, int from_node, int to_node) {
    if (!graph || from_node < 0 || to_node < 0) return -1;

    pthread_mutex_lock(&graph->lock);

    if (graph->edge_count >= MAX_EDGES) {
        log_event("Edge addition failed: Max edges reached", 3);
        pthread_mutex_unlock(&graph->lock);
        return -4;
    }

    graph->edges[graph->edge_count++] = (Edge){from_node, to_node};
    log_event("Edge added", 0);

    pthread_mutex_unlock(&graph->lock);

    return 0;
}

void serialize_graph(Graph *graph) {
    // Implement a compact binary serialization mechanism
    if (!graph) return;

    FILE *file = fopen("graph_data.bin", "wb");
    if (file) {
        fwrite(&graph->node_count, sizeof(int), 1, file);
        for (int i = 0; i < graph->node_count; i++) {
            fwrite(graph->nodes[i], sizeof(Node), 1, file);
        }
        fwrite(&graph->edge_count, sizeof(int), 1, file);
        fwrite(graph->edges, sizeof(Edge), graph->edge_count, file);
        fclose(file);

        log_event("Graph serialized to binary", 0);
    } else {
        log_event("Failed to open file for serialization", 4);
    }
}

void monitor_graph(Graph *graph) {
    if (!graph) return;

    pthread_mutex_lock(&graph->lock);

    graph->average_degree = (double)(2 * graph->edge_count) / graph->node_count;
    printf("Average Degree: %.2f\n", graph->average_degree);

    pthread_mutex_unlock(&graph->lock);
}

void handle_network_partition(Graph *graph, int partitioned) {
    if (!graph) return;

    if (partitioned) {
        log_event("Handling network partition", 5);
        // Implement logic to maintain consistency during partitions
    }
}

void cleanup_graph(Graph *graph) {
    if (!graph) return;

    for (int i = 0; i < graph->node_count; i++) {
        free(graph->nodes[i]);
    }

    pthread_mutex_destroy(&graph->lock);
    free(graph);

    log_event("Graph cleaned up", 0);
}

// Main function to demonstrate usage
int main() {
    Graph *graph = create_graph();

    add_node(graph, 1);
    add_edge(graph, 0, 1);
    serialize_graph(graph);
    monitor_graph(graph);
    handle_network_partition(graph, 1);

    cleanup_graph(graph);

    return 0;
}
