    public SecretKey deriveEncryptionKeyFromPassword(String password) throws Exception {
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
        byte[] keyBytes = sha256.digest(password.getBytes());
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256);
        return new javax.crypto.spec.SecretKeySpec(keyBytes, 0, 32, "AES");
    }

    @Bean
    public Cipher createCipher(SecretKey secretKey) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        byte[] iv = new byte[cipher.getBlockSize()];
        java.security.SecureRandom random = new java.security.SecureRandom();
        random.nextBytes(iv);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, new javax.crypto.spec.IvParameterSpec(iv));
        return cipher;
    }

    // Additional beans for distributed caching, tracing, etc. would be defined here.

}

