// Custom memory pool
typedef struct {
    void *pool;
    size_t size;
    size_t offset;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->pool = malloc(size);
    mp->size = size;
    mp->offset = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* memory_pool_alloc(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->offset + size > mp->size) {
        pthread_mutex_unlock(&mp->lock);
        return NULL; // Out of memory
    }
    void *ptr = (char*)mp->pool + mp->offset;
    mp->offset += size;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    free(mp);
}

// Cache functions
Cache* create_cache(size_t capacity) {
    Cache *cache = malloc(sizeof(Cache));
    cache->cache = calloc(capacity, sizeof(Geometry *));
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

Geometry* get_from_cache(Cache *cache, size_t index) {
    if (index >= cache->count) return NULL;
    pthread_mutex_lock(&cache->lock);
    Geometry *geom = cache->cache[index];
    pthread_mutex_unlock(&cache->lock);
    return geom;
}

void add_to_cache(Cache *cache, Geometry *geometry) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count < cache->capacity) {
        cache->cache[cache->count++] = geometry;
    }
    pthread_mutex_unlock(&cache->lock);
}

void destroy_cache(Cache *cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->cache[i]->name);
        free(cache->cache[i]);
    }
    free(cache->cache);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Helper functions
void generate_random_string(char *str, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    if (length) {
        --length;
        for (; length > 0; --length) {
            int key = rand() % (int)(sizeof(charset) - 1);
            str[length] = charset[key];
        }
        str[0] = '\0';
        strcat(str, &charset[rand() % (int)(sizeof(charset) - 1)]);
    }
}

double generate_random_double(double min, double max) {
    return ((double)rand() / RAND_MAX) * (max - min) + min;
}

// Main function
