            return NULL;
        }, (void*)geometry);
    }

    for (size_t i = 0; i < NUM_GEOMETRIES; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool(mp);
    destroy_cache(cache);

    // Read integers from standard input and find the largest
    int n, *numbers = NULL;
    printf("Enter number of integers: ");
    scanf("%d", &n);

    numbers = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &numbers[i]);
    }

    int largest = find_largest(numbers, n);
    printf("Largest integer: %d\n", largest);

    free(numbers);
}

int find_largest(int *arr, size_t n) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    int max = arr[0];

    for (size_t i = 1; i < n; ++i) {
        pthread_mutex_lock(&lock);
        if (arr[i] > max) {
            max = arr[i];
        }
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return max;
}
