#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Data structure holding a string and an integer.
typedef struct {
    char *str;
    int value;
} Data;

// Node structure containing a pointer to the data structure.
typedef struct Node {
    Data *data;
    struct Node *next;
} Node;

// Memory pool for efficient allocation/deallocation.
typedef struct {
    size_t block_size;
    void *free_list;
    pthread_mutex_t lock;
} MemoryPool;

// Thread-safe collection of nodes with a unique string constraint.
typedef struct {
    Node *head;
    MemoryPool node_pool;
    MemoryPool data_pool;
    pthread_rwlock_t rwlock;
    pthread_mutex_t str_lock;
    char **unique_strings; // Simplified for demonstration purposes
    size_t num_unique;
} Collection;

// Helper function declarations.
void init_memory_pool(MemoryPool *pool, size_t block_size);
void* memory_pool_alloc(MemoryPool *pool);
void memory_pool_free(MemoryPool *pool, void *ptr);

// Initialize the collection and memory pools.
int initialize_collection(Collection *collection, size_t node_block_size, size_t data_block_size) {
    pthread_rwlock_init(&collection->rwlock, NULL);
    pthread_mutex_init(&collection->str_lock, NULL);

    init_memory_pool(&collection->node_pool, sizeof(Node));
    init_memory_pool(&collection->data_pool, sizeof(Data));

    collection->head = NULL;
    collection->num_unique = 0;
    return 0; // Success
}

// Add a node to the collection if its string is unique.
int add_node(Collection *collection, const char *str, int value) {
    pthread_mutex_lock(&collection->str_lock);
    for (size_t i = 0; i < collection->num_unique; ++i) {
        if (strcmp(collection->unique_strings[i], str) == 0) {
            pthread_mutex_unlock(&collection->str_lock);
            return -1; // String already exists.
        }
    }
    char *new_str = strdup(str); // Simplified, consider memory pool for real implementation.
    collection->unique_strings = realloc(collection->unique_strings, (collection->num_unique + 1) * sizeof(char *));
    collection->unique_strings[collection->num_unique++] = new_str;
    pthread_mutex_unlock(&collection->str_lock);

    pthread_rwlock_wrlock(&collection->rwlock);
    Node *new_node = memory_pool_alloc(&collection->node_pool);
    Data *new_data = memory_pool_alloc(&collection->data_pool);
    new_data->str = strdup(str); // Simplified.
    new_data->value = value;
    new_node->data = new_data;
    new_node->next = collection->head;
    collection->head = new_node;
    pthread_rwlock_unlock(&collection->rwlock);

    return 0; // Success
}

// Helper function to calculate the average string length.
double calculate_average_string_length(const Collection *collection) {
    size_t total_length = 0, count = 0;

    pthread_rwlock_rdlock(&collection->rwlock);
    Node *current = collection->head;
    while (current != NULL) {
        total_length += strlen(current->data->str);
        ++count;
        current = current->next;
    }
    pthread_rwlock_unlock(&collection->rwlock);

    return count == 0 ? 0 : (double)total_length / count;
}

// Memory pool functions.
void init_memory_pool(MemoryPool *pool, size_t block_size) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->block_size = block_size;
    pool->free_list = NULL; // Initialize free list as empty.
}

void* memory_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    void *ptr = pool->free_list;
    if (ptr != NULL) {
        pool->free_list = *(void**)ptr;
    } else {
        ptr = malloc(pool->block_size);
    }

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void memory_pool_free(MemoryPool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);

    *(void**)ptr = pool->free_list;
    pool->free_list = ptr;

    pthread_mutex_unlock(&pool->lock);
}

