#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct item {
    char identifier;
    unsigned int value;
} item;

typedef struct node {
    item *data;
    struct node *left, *right;
} node;

typedef struct bst {
    node *root;
    pthread_mutex_t lock;
} bst;

bst *initialize_bst();
void free_tree(node *root);
node* insert_node(node *root, item *new_item, int depth_threshold, unsigned int max_value);
item* create_random_item();
void destroy_bst(bst *tree);

bst *initialize_bst() {
    bst *tree = malloc(sizeof(bst));
    if (!tree) return NULL;

    pthread_mutex_init(&tree->lock, NULL);
    tree->root = NULL;
    return tree;
}

node* insert_node(node *root, item *new_item, int depth_threshold, unsigned int max_value) {
    if (root == NULL) {
        node *new_node = malloc(sizeof(node));
        if (!new_node) return NULL;

        new_node->data = new_item;
        new_node->left = new_node->right = NULL;

        // Check for depth threshold and handle resizing logic here
        // This is a simplified placeholder for handling the depth threshold

        return new_node;
    }

    if (root->data->identifier > new_item->identifier)
        root->left  = insert_node(root->left, new_item, depth_threshold, max_value);
    else if (root->data->identifier < new_item->identifier)
        root->right = insert_node(root->right, new_item, depth_threshold, max_value);

    return root;
}

item* create_random_item(unsigned int max_value) {
    item *new_item = malloc(sizeof(item));
    if (!new_item) return NULL;

    // Example identifier generation
    new_item->identifier = rand() % 256;
    new_item->value = rand() % (max_value + 1);

    return new_item;
}

void free_tree(node *root) {
    if (root == NULL) return;

    free_tree(root->left);
    free_tree(root->right);

    free(root->data);
    free(root);
}

void destroy_bst(bst *tree) {
    pthread_mutex_lock(&tree->lock);

    free_tree(tree->root);
    pthread_mutex_unlock(&tree->lock);

    pthread_mutex_destroy(&tree->lock);
    free(tree);
}

int main() {
    srand(time(NULL));

    bst *my_tree = initialize_bst();
    if (!my_tree) {
        fprintf(stderr, "Failed to initialize BST\n");
        return 1;
    }

    int num_items = 10; // Example number of items
    unsigned int max_value = 1000;

    for (int i = 0; i < num_items; ++i) {
        item *new_item = create_random_item(max_value);
        if (!new_item) {
            fprintf(stderr, "Failed to create a new item\n");
            destroy_bst(my_tree);
            return 1;
        }

        pthread_mutex_lock(&my_tree->lock);

        my_tree->root = insert_node(my_tree->root, new_item, 10, max_value);

        pthread_mutex_unlock(&my_tree->lock);
    }

    // Use the tree for operations...

    destroy_bst(my_tree);

    return 0;
}
```

This code provides a basic structure for managing memory dynamically within a balanced binary search tree (BST) in C. It includes the creation of items with random values, insertion into the BST while ensuring thread safety via mutex locks, and cleanup functions to free allocated memory properly. The code does not cover all details such as balancing the tree or handling resizing at depth thresholds but provides a framework for these operations.']

