#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <limits.h>

#define LOG_FILE_SIZE 1024 * 1024 // 1 MB

typedef struct {
    long offset;
    int key;
    float weight;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

// Global variables for logging and largest number
static FILE *log_file = NULL;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
int largest_number = INT_MIN;
pthread_mutex_t largest_num_lock = PTHREAD_MUTEX_INITIALIZER;

void init_log() {
    log_file = fopen("operations.log", "a");
}

void rotate_logs() {
    pthread_mutex_lock(&log_lock);
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) >= LOG_FILE_SIZE) {
        fclose(log_file);
        rename("operations.log", "operations_old.log");
        log_file = fopen("operations.log", "w");
    }
    pthread_mutex_unlock(&log_lock);
}

void log_operation(const char *message) {
    rotate_logs();
    pthread_mutex_lock(&log_lock);
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&log_lock);
}

int init_memory_pool(MemoryPool* pool, size_t initial_capacity) {
    pool->records = malloc(sizeof(Record) * initial_capacity);
    if (!pool->records) return -1;

    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    log_operation("Memory pool initialized.");
    return 0;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);

    log_operation("Memory pool destroyed.");
}

int add_record(MemoryPool* pool, Record record) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record* new_records = realloc(pool->records, sizeof(Record) * new_capacity);
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            log_operation("Out of memory during record addition.");
            return -1;
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }

    pool->records[pool->size++] = record;

    pthread_mutex_unlock(&pool->lock);

    log_operation("Record added.");
    return 0;
}

int find_largest_number(int* numbers, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&largest_num_lock);
        if (numbers[i] > largest_number) {
            largest_number = numbers[i];
        }
        pthread_mutex_unlock(&largest_num_lock);
    }

    return largest_number;
}

void* process_input(void* arg) {
    int number;
    while (scanf("%d", &number) == 1) {
        // Process each number to update the largest_number safely
        pthread_mutex_lock(&largest_num_lock);
        if (number > largest_number) {
            largest_number = number;
        }
        pthread_mutex_unlock(&largest_num_lock);
    }

    log_operation("Input processing completed.");
    return NULL;
}

int main() {
    init_log();

    MemoryPool pool;
    if (init_memory_pool(&pool, 10)) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return EXIT_FAILURE;
    }

    pthread_t input_thread;
    if (pthread_create(&input_thread, NULL, process_input, NULL) != 0) {
        fprintf(stderr, "Failed to create thread.\n");
        destroy_memory_pool(&pool);
        return EXIT_FAILURE;
    }

    pthread_join(input_thread, NULL);

    printf("Largest number: %d\n", largest_number);

    destroy_memory_pool(&pool);
    fclose(log_file);

    log_operation("Program terminated.");
    return EXIT_SUCCESS;
}
```

