typedef struct {
    int value;
} record;

record* manage_dynamic_memory(int offset_size, long initial_offset_value,
                              int key_size, int initial_key_value,
                              int record_size, int rand_min, int rand_max, unsigned int seed) {

    // Allocate memory for the arrays
    long *offset_array = (long *)malloc(offset_size * sizeof(long));
    int *key_array = (int *)malloc(key_size * sizeof(int));
    record *record_array = (record *)malloc(record_size * sizeof(record));

    // Check if any allocation failed
    if (!offset_array || !key_array || !record_array) {
        free(offset_array);
        free(key_array);
        free(record_array);
        return NULL;
    }

    // Seed the random number generator for reproducibility
    srand(seed);

    // Initialize offset and key arrays with initial values
    for (int i = 0; i < offset_size && i < offset_size; ++i) {
        offset_array[i] = initial_offset_value;
    }

    for (int i = 0; i < key_size && i < key_size; ++i) {
        key_array[i] = initial_key_value;
    }

    // Populate the record array with random values
    for (int i = 0; i < record_size && i < record_size; ++i) {
        record_array[i].value = rand_min + rand() % (rand_max - rand_min + 1);
    }

    // Copy key values into record array in reverse order
    int min_size = record_size < key_size ? record_size : key_size;
    for (int i = 0; i < min_size && i < record_size; ++i) {
        if (record_array[record_size - 1 - i].value == 0) { // Assuming zero is an invalid value
            record_array[record_size - 1 - i].value = key_array[i];
        }
    }

    // Free the allocated memory
    free(offset_array);
    free(key_array);

    return record_array;
}

// Example of using the function
int main() {
    int offset_size = 10, initial_offset_value = 100;
    int key_size = 5, initial_key_value = 200;
    int record_size = 8, rand_min = 0, rand_max = 50;
    unsigned int seed = 42;

    record *result = manage_dynamic_memory(offset_size, initial_offset_value,
                                           key_size, initial_key_value,
                                           record_size, rand_min, rand_max, seed);

    if (result) {
        for (int i = 0; i < record_size && result[i].value != 0; ++i) { // Assuming zero is an invalid value
            printf("Record %d: %d\n", i, result[i].value);
        }
        free(result); // Free the allocated memory for record array
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
