                         int max_int_value, size_t min_free_memory_threshold,
                         float current_memory_usage_percentage);

record* manage_resources(size_t offset_size, long offset_init_value,
                         size_t key_size, int key_init_value,
                         size_t record_size, int rand_min, int rand_max,
                         unsigned int seed, long max_long_value,
                         int max_int_value, size_t min_free_memory_threshold,
                         float current_memory_usage_percentage) {

    // Assume total system memory is 8GB (this would be dynamically determined in a real scenario).
    const size_t total_system_memory = 8 * 1024 * 1024 * 1024;
    const size_t minimum_free_memory = min_free_memory_threshold;

    // Calculate the current free memory.
    size_t current_free_memory = total_system_memory * (1.0 - current_memory_usage_percentage / 100.0);

    if (current_free_memory < minimum_free_memory) {
        return NULL;  // Not enough free memory to proceed safely.
    }

    // Calculate memory requirements for each array.
    size_t offset_array_size = sizeof(long) * offset_size;
    size_t key_array_size = sizeof(int) * key_size;
    size_t record_array_size = sizeof(record) * record_size;

    // Check if the total required memory exceeds available free memory.
    size_t total_required_memory = offset_array_size + key_array_size + record_array_size;
    if (total_required_memory > current_free_memory - minimum_free_memory) {
        return NULL;  // Not enough memory to allocate all structures.
    }

    // Allocate and initialize the arrays with logging.
    long* offsets = malloc(offset_array_size);
    int* keys = malloc(key_array_size);
    record* records = malloc(record_array_size);

    if (!offsets || !keys || !records) {
        free(offsets);  // Ensure no memory leaks.
        free(keys);
        free(records);
        return NULL;
    }

    log_memory_event("Allocated offsets", offset_array_size);
    log_memory_event("Allocated keys", key_array_size);
    log_memory_event("Allocated records", record_array_size);

    // Initialize the arrays with bounds checking and logging.
    for (size_t i = 0; i < offset_size && offsets; ++i) {
        if (offset_init_value <= max_long_value) {
            offsets[i] = offset_init_value;
        }
    }

    for (size_t i = 0; i < key_size && keys; ++i) {
        if (key_init_value <= max_int_value) {
            keys[i] = key_init_value;
        }
    }

    // Seed the random number generator.
    srand(seed);

    // Populate the record array with random values and log initialization.
    for (size_t i = 0; i < record_size && records; ++i) {
        if (rand_min <= rand_max) {
            records[i].value = rand() % (rand_max - rand_min + 1) + rand_min;
        }
    }

    // Check uniqueness of keys and copy in reverse order.
    int* key_frequency = calloc(key_size, sizeof(int));
    int unique_keys = 1;  // Assume initially all keys are unique.

    for (size_t i = 0; i < key_size; ++i) {
        key_frequency[keys[i]]++;
        if (key_frequency[keys[i]] > 1) {
            unique_keys = 0;
            break;
        }
    }

    if (unique_keys) {
        for (size_t i = 0, j = key_size - 1; i < record_size && i < key_size && records; ++i, --j) {
            records[i].value = keys[j];
        }
    } else {
        int default_value = -1; // Placeholder for duplicates.
        for (size_t i = 0, j = key_size - 1; i < record_size && i < key_size && records; ++i, --j) {
            if (key_frequency[keys[j]] > 1) {
                records[i].value = default_value;
            } else {
                records[i].value = keys[j];
            }
        }
    }

    free(key_frequency);

    // Free memory and log deallocation events.
    log_memory_event("Deallocated offsets", offset_array_size);
    log_memory_event("Deallocated keys", key_array_size);
    log_memory_event("Deallocated records", record_array_size);

    free(offsets);
    free(keys);

    return records;
}
