Record records[NUM_RECORDS];
int offsets[NUM_RECORDS];
char keys[NUM_RECORDS][BUFFER_SIZE];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_data(int min_val, int max_val) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < NUM_RECORDS; ++i) {
        // Initialize offsets
        offsets[i] = i * BUFFER_SIZE;

        // Initialize keys with a unique string identifier
        snprintf(keys[i], BUFFER_SIZE, "ID_%d", i);

        // Randomly assign an integer value to each record within the specified range
        records[i].value = min_val + rand() % (max_val - min_val + 1);

        // Allocate memory for the identifier buffer
        records[i].identifier = malloc(BUFFER_SIZE);
        if (!records[i].identifier) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        // Copy unique string identifier into the dynamically allocated buffer
        strcpy(records[i].identifier, keys[i]);
    }

    pthread_mutex_unlock(&lock);
}

int verify_data() {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        if (offsets[i] != i * BUFFER_SIZE ||
            strncmp(keys[i], records[i].identifier, BUFFER_SIZE) != 0 ||
            (records[i].value < min_val || records[i].value > max_val)) {
            return 0;
        }
    }
    return 1;
}

int main() {
    srand(time(NULL));

    int min_val = 10; // Example range
    int max_val = 100;

    init_data(min_val, max_val);

    if (verify_data()) {
        printf("Data initialized and verified successfully.\n");
    } else {
        fprintf(stderr, "Verification failed!\n");
        return EXIT_FAILURE;
    }

    // Free allocated memory
    for (int i = 0; i < NUM_RECORDS; ++i) {
        free(records[i].identifier);
    }

    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
