typedef struct {
    int value;
} Record;

typedef struct {
    size_t num_offsets;
    size_t num_keys;
    size_t num_records;
    size_t additional_records;
} Summary;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_data_structures(size_t num_records, int initial_offset_value, 
                                int initial_key_value, size_t additional_records,
                                unsigned int seed) {
    if (num_records <= 0 || additional_records < 0) {
        printf("Invalid number of records.\n");
        return;
    }

    pthread_mutex_lock(&lock);

    // Allocate memory for offsets and keys
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        perror("Memory allocation failed");
        if (offsets) free(offsets);
        if (keys) free(keys);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize offsets and keys
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = initial_offset_value + i;
        keys[i] = initial_key_value + i;
    }

    size_t total_record_count = num_records * 2 + additional_records;

    // Allocate memory for Record arrays
    Record *records1 = malloc(num_records * 2 * sizeof(Record));
    Record *records2 = malloc(additional_records * sizeof(Record));

    if (!records1 || !records2) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        if (records1) free(records1);
        if (records2) free(records2);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize random number generator
    srand(seed);

    // Populate records with non-consecutive values for the second array
    int last_val = -2;  // Ensure no consecutive numbers

    for (size_t i = 0; i < num_records * 2; ++i) {
        records1[i].value = rand() % 100;
    }

    for (size_t i = 0; i < additional_records; ++i) {
        int val;
        do {
            val = rand() % 100;
        } while (val == last_val + 1 || val == last_val - 1);
        records2[i].value = val;
        last_val = val;
    }

    // Copy keys into records in reverse order
    for (size_t i = 0; i < num_records; ++i) {
        records1[num_records + i].value = keys[num_records - 1 - i];
    }

    Summary *summary = malloc(sizeof(Summary));
    if (!summary) {
        perror("Memory allocation failed");
        free(offsets);
        free(keys);
        free(records1);
        free(records2);
        pthread_mutex_unlock(&lock);
        return;
    }

    summary->num_offsets = num_records;
    summary->num_keys = num_records;
    summary->num_records = num_records * 2;
    summary->additional_records = additional_records;

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records1);
    free(records2);

    pthread_mutex_unlock(&lock);

    printf("Summary: Offsets=%zu, Keys=%zu, Records=%zu, AdditionalRecords=%zu\n",
           summary->num_offsets, summary->num_keys,
           summary->num_records, summary->additional_records);

    // Normally you'd return the summary or process it further
}
