#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} Record;

// Memory pool for managing allocations
#define POOL_SIZE 10000
size_t memory_pool[POOL_SIZE];
size_t allocated_count = 0;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void* thread_safe_malloc(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (allocated_count >= POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL; // Pool exhausted
    }
    void* ptr = malloc(size);
    if (ptr != NULL) {
        memory_pool[allocated_count++] = size;
    }
    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

void thread_safe_free(void** ptr_ptr) {
    pthread_mutex_lock(&pool_mutex);
    if (*ptr_ptr != NULL) {
        free(*ptr_ptr);
        *ptr_ptr = NULL;
        allocated_count--;
    }
    pthread_mutex_unlock(&pool_mutex);
}

// Pseudo-random number generator
uint32_t pseudo_random(uint32_t seed) {
    return (seed * 1103515245 + 12345) & 0x7fffffff;
}

void manage_records(size_t num_offsets, const long* offsets) {
    if (num_offsets == 0 || offsets == NULL) {
        fprintf(stderr, "Invalid input\n");
        return;
    }

    long max_offset = (1LL << 63) - 1;
    pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for offset array
    long* dynamic_offsets = (long*)thread_safe_malloc(num_offsets * sizeof(long));
    if (!dynamic_offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Copy and validate offsets
    for (size_t i = 0; i < num_offsets; ++i) {
        if (offsets[i] > max_offset) {
            fprintf(stderr, "Offset exceeds maximum value\n");
            thread_safe_free((void**)&dynamic_offsets);
            pthread_mutex_destroy(&record_lock);
            return;
        }
        dynamic_offsets[i] = offsets[i];
    }

    // Allocate memory for records
    Record* records = (Record*)thread_safe_malloc(num_offsets * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        thread_safe_free((void**)&dynamic_offsets);
        pthread_mutex_destroy(&record_lock);
        return;
    }

    // Process each offset
    for (size_t i = 0; i < num_offsets; ++i) {
        long offset = dynamic_offsets[i];

        // Compute key and handle zero value case
        int key = (int)(offset >> 2);
        if (key == 0) key = 1; // Avoid zero keys

        // Generate pseudo-random number with seed as the key
        uint32_t random_value = pseudo_random(key);

        pthread_mutex_lock(&record_lock);
        records[i].value = (int)random_value;
        pthread_mutex_unlock(&record_lock);
    }

    // Log results (for debugging)
    for (size_t i = 0; i < num_offsets; ++i) {
        printf("Record %zu: Value=%d\n", i, records[i].value);
    }

    // Cleanup
    thread_safe_free((void**)&dynamic_offsets);
    thread_safe_free((void**)&records);
    pthread_mutex_destroy(&record_lock);
}

int main() {
    size_t num_offsets = 5;
    long offsets[] = {1000L, 2000000000L, 9000000000000000000LL, -1, (1LL << 62)};

    manage_records(num_offsets, offsets);

    return 0;
}
```

