#define NODE_MAX_LABEL_LEN 256
#define POOL_SIZE 1024 * 1024 // Example size, adjust as needed

typedef enum { DISCONNECTED, CONNECTED } NodeStatus;

typedef struct {
    int id;
    float x, y;
} Node;

typedef struct {
    double weight;
    char label[NODE_MAX_LABEL_LEN];
    Node *nodes[2]; // assuming links between two nodes
    NodeStatus status;
} Link;

typedef struct {
    long offsets[POOL_SIZE];
    int keys[POOL_SIZE];
    int values[POOL_SIZE];
    void *memory_pool; // Custom memory pool

    pthread_mutex_t lock;
} MemoryManager;

MemoryManager mem_manager;

// Function prototypes
void log_operation(const char *operation);
void* allocate_memory(size_t size);
void free_memory(void *ptr, size_t size);
void initialize_memory_manager();
void destroy_memory_manager();
void handle_external_configuration_update();

// Utility functions
static void log_operation(const char *operation) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), operation);
}

static void* allocate_memory(size_t size) {
    pthread_mutex_lock(&mem_manager.lock);
    // Simple allocation strategy, consider more complex strategies for production
    mem_manager.memory_pool = realloc(mem_manager.memory_pool, size + (size & 0x7));
    if (!mem_manager.memory_pool) {
        log_operation("Memory allocation failed");
        pthread_mutex_unlock(&mem_manager.lock);
        return NULL;
    }
    void *ptr = mem_manager.memory_pool;
    mem_manager.memory_pool = (char*)mem_manager.memory_pool + size + (size & 0x7); // align to 8 bytes
    log_operation("Allocated memory");
    pthread_mutex_unlock(&mem_manager.lock);
    return ptr;
}

static void free_memory(void *ptr, size_t size) {
    pthread_mutex_lock(&mem_manager.lock);
    mem_manager.memory_pool = (char*)ptr - size - (size & 0x7); // revert pointer
    log_operation("Freed memory");
    pthread_mutex_unlock(&mem_manager.lock);
}

static void initialize_memory_manager() {
    pthread_mutex_init(&mem_manager.lock, NULL);
    mem_manager.memory_pool = malloc(POOL_SIZE);
    if (!mem_manager.memory_pool) {
        fprintf(stderr, "Failed to allocate initial memory pool\n");
        exit(EXIT_FAILURE);
    }
    log_operation("Initialized memory manager");
}

static void destroy_memory_manager() {
    pthread_mutex_destroy(&mem_manager.lock);
    free(mem_manager.memory_pool);
    log_operation("Destroyed memory manager");
}

// Thread-safe initialization and configuration
void handle_external_configuration_update() {
    // Simulate reading from an external service
    pthread_mutex_lock(&mem_manager.lock);
    // Merge new configurations here
    log_operation("Updated configuration from external service");
    pthread_mutex_unlock(&mem_manager.lock);
}

int main() {
    initialize_memory_manager();

    // Example usage
    Node *node1 = (Node*)allocate_memory(sizeof(Node));
    if (!node1) return EXIT_FAILURE;
    node1->id = 1;
    node1->x = 0.0f;
    node1->y = 0.0f;

    char label[NODE_MAX_LABEL_LEN];
    snprintf(label, NODE_MAX_LABEL_LEN, "Node%d", node1->id);

    Link *link = (Link*)allocate_memory(sizeof(Link));
    if (!link) return EXIT_FAILURE;
    link->weight = 1.23;
    strncpy(link->label, label, NODE_MAX_LABEL_LEN);
    link->nodes[0] = node1;
    link->status = CONNECTED;

    handle_external_configuration_update();

    free_memory(node1, sizeof(Node));
    free_memory(link, sizeof(Link));

    destroy_memory_manager();
    return 0;
}
